/* dbt-edith UI shell: sidebar, editor tabs, lineage, node detail, terminal. */
(() => {
const $ = (s) => document.querySelector(s);
const $$ = (s) => [...document.querySelectorAll(s)];

const S = {
  meta: null,
  open: new Map(),   // path -> {doc, dirty, stamp, disk}
  order: [],
  active: null,
  focus: null,       // unique_id currently in the lineage view
  unsynced: '',      // file whose tab came up with no node in the manifest, for a reload to look again
  stampsAsked: false, // a look at the open files' stamps is on its way, so another waits its turn
  stampsAgain: false, // one was asked for meanwhile, and runs once that look is done
  cm: null,
  term: null, ws: null, fit: null,
  termKeys: 0,                // how many keys or pastes the person has typed into the terminal, so a command waiting for its Enter can tell a line they changed (0161)
  typedChip: null,            // the chip beside a command typed for the person: its decoration and marker, one at a time (0161)
  venv: null,                 // /api/meta's venv: the one dbt-edith was started in, and each found
  termVenv: undefined,        // the terminal's VIRTUAL_ENV at its last prompt, '' for none, undefined unheard (0069)
  pathReadsCwd: '',           // /api/meta: why the terminal's shell reads the current folder, relative, empty or cmd, '' when it does not, so what is typed may run a program in the project (0130)
  pathEntry: '',              // the first relative entry of that PATH, as it is written, '' for the other reasons (0130)
  shellName: '',              // /api/meta's name for the terminal's shell, bash or zsh, '' until it answers (0073)
  termPrompt: undefined,      // true at bash's prompt, false once Enter hands its line on, undefined unheard (0073)
  venvAsked: undefined,       // the last folder the terminal named that sent the page to read the venvs again
  look: { theme: 'night', follow: false, apparitions: true, boxes: 'tombstone' },  // /api/look: the theme, Follow the system, the Halloween theme's apparitions and box style, kept per machine (0106, 0150)
  hw: { ghostTimer: 0, eyesTimer: 0, flyTimer: 0, witchX: undefined, running: false, saving: Promise.resolve(), sides: new Map() },  // what the look has running
  preview: null,              // path of the reusable preview tab, VS Code style
  back: [], fwd: [],          // where following a link came from, a browser's two stacks
  rows: new Map(),            // tree rows currently rendered, by path
  fileMarks: new Map(),       // path -> {kind, materialized} of a model's, seed's or snapshot's file, from /api/dir, for the file's icon (0151)
  gitMod: new Set(), gitUnt: new Set(), gitAdded: new Set(),
  gitModDirs: new Set(), gitUntDirs: new Set(),
  gitPrefixes: [], gitKey: '',
  git: null,                  // full payload of /api/git
  committing: false,          // a commit is running: the button says so whatever the poll repaints (0165)
  diffLayout: 'sbs',          // 'sbs' or 'inline', one choice for every diff tab, kept for the page's life (0165)
  artifactAsk: { compiled: 0, run: 0 },        // the latest load of each pane, so an older answer never paints
  artifactCm: { compiled: null, run: null },  // read-only editors for the two files under target/
  artifactInfo: { compiled: null, run: null },  // the last answer of each, so another environment repaints without a request
  envs: null,                 // payload of /api/envs
  env: '',                    // this tab's chosen .env file, '' for the manifest as parsed
  artifactRow: '',            // envRowKey() as the Compiled or Run row was last drawn
  node: null,                 // catalog: node currently displayed
  catTab: 'preview',          // catalog: preview | columns
  graphMode: 'model',         // lineage canvas: model | column | select
  colFocus: null,             // {id, column} when the canvas shows columns
  colCut: new Set(),          // roles the column walk stops at downstream, kept across refocuses
  colIndirect: false,         // collin's indirect edges walked and drawn: off on load, kept across refocuses (0097)
  colSub: null,               // last /api/collineage payload, which the stop at menu counts
  depthLevels: null,          // {key, levels, kind, name} of the answer drawn: what the depth menus list (0158)
  depthKey: '',               // the ask the depth control waits on: an answer under another key is not its own
  colReach: new WeakMap(),    // /api/colreach answers, by the /api/node payload they complete
  selectSub: null,            // last /api/select payload, for the two copy buttons
  selectShown: '',            // the line the lineage last drew, for the status bar
  selectAsk: 0,               // bumped per run, so only the latest answer is drawn
  cardAsk: 0,                 // bumped per box clicked and per card closed, so only the latest box's Catalog shows (0101)
  colRaise: null,             // {key, max} a click asked a column's canvas to draw past the cap, for that request only (0118)
  selectRaise: null,          // {expr, tests, max} a click asked to draw past the cap, for that line only
  selectBack: null,           // while the selection's panel is down: where what it took from the dock goes back, and the mode
  selectHistory: [],          // expressions typed this session, newest first
  selectHistAt: -1,           // where the arrow keys are in that history, -1 being the empty line
  colHighlight: '',           // column row to mark in the Columns table
  colSort: 'az',              // catalog: az | tests | key
  colReveal: '',              // the node whose Columns draw scrolls to colHighlight's row
  colFilter: '',              // catalog: what the Columns filter holds, kept from one node to the next
  dock: 'lineage',            // the dock tab on screen
  lastPane: '',               // the pane last clicked or focused, for a Cmd+F with nothing focused
  graphFind: null,            // the lineage's find bar, once Cmd+F has reached the canvas (0081)
  keysReturn: null,           // where focus goes back to when the shortcut list closes
  sidecar: null,              // payload of /api/sidecar: whether Snowflake is picked, and its script
  sidecarPoll: 0,             // the timer asking again while the script starts
  collin: null,               // the collin part of /api/meta: installed, stale, and its last run
  collinPoll: 0,              // the timer asking again while a run started by a pick goes on
  update: null,               // payload of /api/update: the newest dbt-edith known, and how to install it
  updatePoll: 0,              // the timer asking again, every few seconds while a look is on its way
  updateAsks: 0,              // requests to /api/update made, numbered, so an older answer never replaces a newer one
  updateShown: 0,             // the number of the request whose answer is in `update`
  updateAt: 0,                // when that answer came, which the menu's opening asks again after
  lookPosted: false,          // a Check for updates waits on its answer, which the polls' answers must not replace
  installSince: 0,            // when the update was typed into the terminal, asked every few seconds after (0095)
  notice: null,               // the centred card showing, if any: { card, timer, off } (0111)
  updateMenu: null,           // Edith's menu, drawn again while open when an answer comes in
  freshCard: null,            // the manifest pill's card, drawn again while open when a poll changes the answer (0157)
  build: '',                  // the build stamp, under the version in Edith's menu
  cllSources: [],             // column-lineage caches /api/meta offers, newest first
  cllActive: '',              // file name of the one the graph holds, '' for none
  cllTool: '',                // fusion | collin | snowflake | '' for another producer or none
  features: null,             // { snowflake, snowflake_set, builds_stale_days }: which feature families are on
  profiles: null,             // { path, found }: where dbt looks for its profile, null with nowhere to look
  colAsk: 0,                  // bumped on every column click, so only the latest answer is drawn
  colDraw: 0,                 // bumped per column request and on leaving column mode: only the last answer is drawn
  colWait: false,             // the canvas is cleared, waiting for a collin run to end before it draws S.colFocus
  colAnswered: false,         // Snowflake has answered once on this page, so no sign-in tab is expected
  history: null,              // the query history on screen: rows, more, session, targets, busy, error
  historyRole: null,          // whose queries it shows: null for the target's role, '*' for all, or a role
  historyAsk: 0,              // bumped per history request, so only the latest answer is drawn
  jobsRun: 0,                 // bumped per Jobs request, so only the latest answer is drawn
  jobsKeys: null,             // the Airflow keys and the shape the server proposes (0063)
  jobsLooked: 0,              // when the last Jobs request that looked at the job files was answered, in ms
  sfSession: null,            // { org, account, user, role } of the script's connection, once asked
  cloneFrom: null,            // where this tab last copied from: a .env file, '' for built, null before any
  cloneMode: 'clone',         // clone | ctas, as last chosen in this tab
  nodeCache: new Map(),       // /api/node payloads, by query: hover asks far more often than click
  nodeGen: 0,                 // bumped when the manifest or a .env file changes under the cache
  vars: null,                 // payload of /api/vars, for the editor's var() marks
  outline: null,              // { path, nodes } scanned for the breadcrumb's symbol half
  crumbLine: -1,              // the line that half was last drawn for
  version: '',                // this build's version, named in an exported graph
  keyless: false,             // the server refused this tab for want of its launch key (0052)
  collinSeen: undefined,      // collin's run counter when its report was last shown, for the news
  reports: null,              // /api/reports: which reports have something to show, and when written
  reportsAt: undefined,       // the newest report file the freshness poll last named
  panel: '',                  // the panel rolled down over the editor and the dock, '' for none (0064, 0091)
  panelReturn: null,          // where focus goes back to when the panel is closed from the keyboard
  reportsSection: '',         // the section on screen in it, or last on screen this session
  reportsShown: null,         // the index entry the section on screen was read at
  reportsAsk: 0,              // bumped per section read, so only the latest answer is drawn
  reportsDrawn: '',           // the section whose answer is in the panel, '' while one is read
  reportsPlace: {},           // per section, its open folds, its filter, the lists shown whole and its scroll, for when it is shown again
  reportsCounts: {},          // the order of the steps' rail count, left by the last time it was drawn (0137)
  jobBuildsPick: { last: null, rows: {} }, // Builds by job: the environment last picked by a cell, and the one each open row is on
  settingsSection: '',        // the section of the settings on screen, or last on screen this session (0100)
  settingsKept: {},           // per section holding a form, its body as it was left, until the panel rolls up
  settingsFrom: '',           // the panel the settings took the place of, '' for none
  settingsRepaint: false,     // a redraw of the section on screen is on its way, for every change made meanwhile
  featuresBusy: false,        // Snowflake's switch was flipped and the server has not answered yet
  macroFocus: '',             // the macro whose callers a card asked the Macros section for (0105)
  runSeen: undefined,         // the last run's file time when its section was last shown, for the news
  jobsSeen: undefined,        // how many models no scheduled job ran when the coverage was last shown
  warningsSeen: undefined,    // how many config paths applied to nothing when the warnings were last shown
  unusedKey: undefined,       // the warnings' index entry the gutter of dbt_project.yml was last marked for
  unused: null,               // { key, report }: /api/reports/warnings as read for that entry
  jobsReveal: null,           // { id, key, index } the step a Catalog chip asked the Jobs tab to show, { id, maybe } for the unresolved
  jobsFor: null,              // the node a Catalog chip opened the Jobs tab on, when not the focus, while the Catalog shows it
  catJobs: new Map(),         // per node, the jobs answer its Catalog section drew, until the jobs may have changed
  catJobsGen: 0,              // counts those changes, so an answer asked for before one is dropped
  builds: null,               // the last read of dbt_artifacts: { readAt, targets, byEnv, pending, failed }, never kept (0117)
  buildsBusy: false,          // a read is on its way, one environment's tables at a time
  buildsPackages: false,      // the Reports grid lists the packages' models too
  tour: null,                 // the guided tour on screen: its steps, the one shown, and the page as it was (0074)
  tourOfferHeld: false,       // the offer waits for a manifest with a model, and is asked for again when one lands (0078)
};

// ------------------------------------------------------------------ util --
/* A route that can fail in several ways answers with JSON, and its fields end
   up on the Error: the message stays readable either way. */
function apiError(text, fallback) {
  try {
    const body = JSON.parse(text);
    if (body && body.error) return Object.assign(new Error(body.error), body);
  } catch { /* a plain sentence, which is the usual case */ }
  return new Error(text || fallback);
}

/* The launch key (0122). The printed link carries it as `key`; the page keeps
   it in this origin's own storage, so another port of the same host never
   sees it, and takes it out of the address bar. A key from the address is
   stored only once the server has accepted it, so a stale link, a bookmark
   from an earlier launch, cannot overwrite the one a newer tab stored. Storage
   can be refused (a private window, blocked site data), and the key then
   lives in `launchKey` alone, for as long as the page does. */
const KEY_STORE = 'dbt-edith-key';
let launchKey = '';     // the one in use
let keyPending = '';    // one from the address that no answer has vouched for yet

function storedKey() {
  try { return localStorage.getItem(KEY_STORE) || ''; } catch { return ''; }
}

function takeLaunchKey() {
  const params = new URLSearchParams(location.search);
  const given = params.get('key');
  if (given) {
    params.delete('key');
    const rest = params.toString();
    history.replaceState(null, '', location.pathname + (rest ? '?' + rest : '') + location.hash);
    keyPending = given;
  }
  launchKey = given || storedKey();
  return launchKey;
}

/* The server took the key: now it is kept. */
function keyAccepted() {
  if (!keyPending || keyPending !== launchKey) return;
  try { localStorage.setItem(KEY_STORE, keyPending); } catch { /* kept for this page only */ }
  keyPending = '';
}

/* The server refused the key. A newer launch, in another tab on this port,
   may have stored another: true when one differing from this page's was found
   and taken, and the request is worth one more try. */
function keyRefused() {
  const stored = storedKey();
  if (!stored || stored === launchKey) return false;
  launchKey = stored;
  keyPending = '';
  return true;
}

takeLaunchKey();

/* Sent on every request: a header is not a cookie, so only this page's own
   code, and no other server on the host, ever carries it. */
function keyHeaders() {
  return launchKey ? { authorization: 'Bearer ' + launchKey } : {};
}

/* The requests that wait on something slower than the server's own reading:
   the manifest read again, collin, Snowflake, git over the network, GitHub's
   releases. While one is out past WORK_DELAY, Edith's mark moves. Picked by
   route rather than by time alone, so a search that is slow on a big project
   or a poll nobody asked for never sets her going. */
const WORK_ROUTES = ['/api/reload', '/api/collineage', '/api/collin/compare', '/api/snowflake/',
  '/api/git/push', '/api/git/pull', '/api/git/fetch', '/api/update/check'];
const WORK_DELAY = 400;
const WORK_FADE = 300;

function isWork(path) {
  const p = String(path).split('?')[0];
  return WORK_ROUTES.some((r) => (r.endsWith('/') ? p.startsWith(r) : p === r || p.startsWith(r + '/')));
}

/* Counted, since a reload and a column fetched meanwhile overlap: the mark
   stops with the last of them. It starts only past the delay, so an answer
   that comes at once never flickers it, and the packets fade before the loop
   is taken away, none vanishing halfway along an arm. */
let workOut = 0;
let workTimer = 0;

function markWorking(on) {
  const brand = document.getElementById('brand');
  if (!brand) return;
  clearTimeout(workTimer);
  if (on) {
    brand.classList.add('working', 'flowing');
  } else {
    brand.classList.remove('flowing');
    workTimer = setTimeout(() => brand.classList.remove('working'), WORK_FADE);
  }
}

function workBegan() {
  if (workOut++ > 0) return;
  clearTimeout(workTimer);
  workTimer = setTimeout(() => markWorking(true), WORK_DELAY);
}

function workEnded() {
  if (--workOut > 0) return;
  clearTimeout(workTimer);
  const brand = document.getElementById('brand');
  /* `working`, not `flowing`: a request begun during a fade has cleared its
     timer, and removing the class here would cut the packets short. */
  if (brand && brand.classList.contains('working')) markWorking(false);
}

/* A collin run started by a pick, or by a column clicked on a stale cache, is
   not a request of its own: the page learns of it, and of its end, from
   /api/meta, which is no work route. So the run is counted here, once from the
   moment S.collin says it is running to the moment it says otherwise, and the
   flag keeps it from being counted twice or left begun, which would keep the
   mark moving for good. Called after every change of S.collin. */
let collinWorks = false;

function followCollinWork() {
  const running = !!S.collin && S.collin.state === 'running';
  if (running === collinWorks) return;
  collinWorks = running;
  if (running) workBegan();
  else workEnded();
}

async function request(path, init = {}) {
  const work = isWork(path);
  if (work) workBegan();
  try {
    for (let again = true; ; again = false) {
      const r = await fetch(path, { ...init, headers: { ...init.headers, ...keyHeaders() } });
      if (r.status === 401 && again && keyRefused()) continue;
      if (r.ok) keyAccepted();
      return r;
    }
  } finally {
    if (work) workEnded();
  }
}

const api = {
  async get(path) {
    const r = await request(path);
    if (!r.ok) throw apiError(await refusal(r), r.statusText);
    return r.json();
  },
  async send(path, method, body) {
    const r = await request(path, { method, headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) });
    if (!r.ok) throw apiError(await refusal(r), r.statusText);
    return r.json();
  },
};

/* The body of a refused request. A 401 is the server saying this tab never got
   its launch key: every later request will fail the same way, so it is said
   once, in a bar that stays, rather than in a toast per request (0052). */
async function refusal(r) {
  const text = await r.text();
  if (r.status === 401) keyMissing(text);
  return text;
}

function keyMissing(text) {
  if (S.keyless) return;
  S.keyless = true;
  const bar = document.createElement('div');
  bar.className = 'keyless';
  bar.setAttribute('role', 'alert');
  bar.textContent = (text || 'no key for this server in this tab')
    + '. The terminal where dbt-edith runs shows it after "open". A link from an earlier launch no longer works.';
  document.body.prepend(bar);
}

/* One /api/node payload per node, shared by the catalog, the ref() marks and the
   hover card. The server rediscovers the .env files and walks the graph twice on
   every request, which a click could afford and a hover cannot. The promise is
   what is stored, not the value: a hover and the click that follows it 30ms
   later are then one request rather than two.

   The entry expires, because the server reloads the graph by itself when dbt
   rewrites the artifacts (watch_artifacts, every three seconds) and never tells
   the browser. Before this cache existed every click refetched, so a `dbt build`
   in the terminal showed up on the next click; an entry that outlived that poll
   would take that back. Three seconds is the server's own interval, so the cache
   is never staler than the thing it is caching. */
const NODE_CACHE_MAX = 200;
const NODE_CACHE_TTL = 3000;

function nodeKey(q) {
  return q.id ? 'id:' + q.id : 'file:' + q.file;
}

function nodeDetail(q) {
  const key = nodeKey(q);
  const hit = S.nodeCache.get(key);
  if (hit && hit.gen === S.nodeGen && Date.now() - hit.at < NODE_CACHE_TTL) return hit.p;
  const path = q.id ? '/api/node?id=' + encodeURIComponent(q.id) : '/api/node?file=' + encodeURIComponent(q.file);
  // A failed request must not be remembered as the answer.
  const p = api.get(path).catch((e) => { S.nodeCache.delete(key); throw e; });
  S.nodeCache.set(key, { gen: S.nodeGen, at: Date.now(), p });
  if (S.nodeCache.size > NODE_CACHE_MAX) S.nodeCache.delete(S.nodeCache.keys().next().value);
  return p;
}

/* The project's vars, plus any env var asked for by name. Keyed by the chosen
   environment as well, because the same var resolves differently under each. */
function fetchVars(names) {
  const key = (S.env || '') + '|' + (names || '');
  if (!S.vars) S.vars = new Map();
  const hit = S.vars.get(key);
  if (hit) return hit;
  let url = '/api/vars?env=' + encodeURIComponent(S.env || '');
  if (names) url += '&names=' + encodeURIComponent(names);
  const p = api.get(url).catch((e) => { S.vars.delete(key); throw e; });
  S.vars.set(key, p);
  return p;
}

/* The manifest was reloaded, or a file the payload derives from was saved. */
function dropNodeCache() {
  S.nodeGen++;
  S.nodeCache.clear();
  S.vars = null;
}

function toast(msg, kind = '') {
  const t = document.createElement('div');
  t.className = 'toast ' + kind;
  t.textContent = msg;
  $('#toast').appendChild(t);
  setTimeout(() => t.remove(), 3200);
}

/* A card in the middle of the page, for the one message that must not be
   missed: what to do once the update is typed, and that it is installed. A
   toast is three seconds at the bottom, and these were read as nothing
   having happened (0111). One at a time, a new one replacing the last. It
   has no backdrop, so the terminal and the page stay usable around it; with
   no `sticky` it goes by itself after `ms`, otherwise only its button or
   Escape closes it, but only with the focus in the terminal (which the update
   leaves it in), on the card or on the bare page: in the editor, a find bar,
   the tour or a menu Escape is theirs, and the card stays. In the terminal it
   stops at the card, or it would also reach a prompt or a vim. A click on
   the card keeps the focus where it was, so Enter still reaches the terminal. */
function notice({ title, body, sticky = false, ms = 15000 }) {
  closeNotice();
  const card = document.createElement('div');
  card.className = 'notice';
  card.setAttribute('role', 'status');
  const head = document.createElement('div');
  head.className = 'notice-head';
  const h = document.createElement('div');
  h.className = 'notice-title';
  h.textContent = title;
  const x = document.createElement('button');
  x.type = 'button';
  x.className = 'notice-x';
  x.textContent = '×';
  x.title = 'Close';
  x.setAttribute('aria-label', 'Close');
  x.addEventListener('click', closeNotice);
  head.append(h, x);
  const p = document.createElement('div');
  p.className = 'notice-body';
  p.textContent = body;
  card.append(head, p);
  card.addEventListener('mousedown', (e) => e.preventDefault());
  document.body.appendChild(card);
  const onKey = (e) => {
    if (e.key !== 'Escape') return;
    const t = e.target;
    const inTerm = !!(t && t.closest && t.closest('#term'));
    if (!inTerm && t !== document.body && !card.contains(t)) return;
    closeNotice();
    // Taken, so the find bar's and the panel's Escape handlers (which check
    // defaultPrevented) leave their own things open; in the terminal it also
    // goes no further.
    e.preventDefault();
    if (inTerm) e.stopPropagation();
  };
  document.addEventListener('keydown', onKey, true);
  S.notice = {
    card,
    timer: sticky ? 0 : setTimeout(closeNotice, ms),
    off: () => document.removeEventListener('keydown', onKey, true),
  };
}

function closeNotice() {
  const n = S.notice;
  if (!n) return;
  S.notice = null;
  clearTimeout(n.timer);
  n.off();
  n.card.remove();
}

/* Same colour rule as the lineage canvas, so a model looks the same everywhere. */
const dot = (n) => {
  const d = document.createElement('span');
  d.className = 'dot';
  d.style.background = Lineage.nodeColor(typeof n === 'string' ? { kind: n } : n);
  d.title = Lineage.matLabel(typeof n === 'string' ? { kind: n } : n);
  return d;
};

/* Whether CodeMirror took this for a Mac. Asked of CodeMirror rather than of
   the user agent, so a key the shortcut list names as ⌘ is one CodeMirror
   binds to Cmd, and never a Ctrl it is waiting for instead. */
const IS_MAC = CodeMirror.keyMap.default === CodeMirror.keyMap.macDefault;
/* 'mac', 'windows' or 'other', for the keys that differ between the three:
   the terminal's line keys and the rows of the shortcut list naming them. */
const KEYS_OS = IS_MAC ? 'mac' : /^Win/.test(navigator.platform || '') ? 'windows' : 'other';

// ---------------------------------------------------------------- editor --
/* Jinja in a model, one token at a time, from an opening delimiter to its close.
   Each piece is styled by what it is, so a call reads apart from a variable, a
   keyword or a string. `jinja-dbt` is what dbt itself provides, taken from its list
   of Jinja functions and context variables: `ref`, `this` and `adapter` look alike,
   `dbt_utils.star` does not. */
const JINJA_KEYWORDS = new Set(('and as block break call continue do docs elif else endblock endcall ' +
  'enddocs endfilter endfor endif endmacro endmaterialization endraw endset endsnapshot endtest ' +
  'endwith extends filter for from if import in include is macro materialization not or raw ' +
  'recursive set snapshot test with without').split(' '));
const JINJA_ATOMS = new Set(['true', 'false', 'none', 'True', 'False', 'None']);
const DBT_GLOBALS = new Set(('adapter api builtins config dbt_version debug env_var exceptions ' +
  'execute flags fromjson fromyaml graph invocation_id is_incremental load_result local_md5 log ' +
  'model modules print project_name ref return run_query run_started_at selected_resources set ' +
  'set_strict source statement target this thread_id tojson toyaml var zip zip_strict').split(' '));

function jinjaStart() {
  return { close: null, quote: null, depth: 0, tag: false, dot: false, pipe: false };
}

function jinjaToken(stream, state) {
  if (!state.close) {
    // dbtSqlMode only calls in here outside a block when a delimiter opens.
    const open = stream.match(/^\{([{%#])[-+]?/);
    Object.assign(state, jinjaStart(), { close: { '{': '}}', '%': '%}', '#': '#}' }[open[1]] });
    state.tag = open[1] === '%';
    return open[1] === '#' ? 'jinja-comment' : 'jinja-delim';
  }
  if (state.close === '#}') {
    if (stream.match(/^.*?#\}/)) state.close = null;
    else stream.skipToEnd();
    return 'jinja-comment';
  }
  if (state.quote || stream.match(/^['"]/, false)) {
    if (!state.quote) state.quote = stream.next();
    while (!stream.eol()) {
      const ch = stream.next();
      if (ch === '\\') stream.next();
      else if (ch === state.quote) { state.quote = null; break; }
    }
    state.tag = state.dot = state.pipe = false;
    return 'jinja-string';
  }
  const end = stream.match(/^[-+]?(?:\}\}|%\})/, false);
  if (end && end[0].endsWith(state.close)) {
    stream.match(end[0]);
    state.close = null;
    return 'jinja-delim';
  }
  if (stream.eatSpace()) return null;
  if (stream.match(/^\d+(?:\.\d+)?/)) {
    state.tag = state.dot = state.pipe = false;
    return 'jinja-number';
  }
  const word = stream.match(/^[A-Za-z_]\w*/);
  if (word) {
    const w = word[0];
    const { tag, dot, pipe } = state;
    state.tag = state.dot = state.pipe = false;
    // The first word of a {% %} block is its tag, whatever else it could be.
    if (tag) return 'jinja-keyword';
    // A named argument before a keyword: dbt_utils.star(from=...) is common.
    if (state.depth > 0 && stream.match(/^\s*=(?!=)/, false)) return 'jinja-param';
    if (JINJA_KEYWORDS.has(w) && !stream.match('(', false)) return 'jinja-keyword';
    const called = stream.match(/^\s*\(/, false);
    // After a dot it is an attribute or a method, never a dbt global.
    if (dot) return called ? 'jinja-fn' : 'jinja-var';
    if (JINJA_ATOMS.has(w)) return 'jinja-atom';
    if (DBT_GLOBALS.has(w)) return 'jinja-dbt';
    return called || pipe ? 'jinja-fn' : 'jinja-var';
  }
  const ch = stream.next();
  if ('([{'.includes(ch)) state.depth++;
  else if (')]}'.includes(ch) && state.depth > 0) state.depth--;
  state.tag = false;
  state.dot = ch === '.';
  state.pipe = ch === '|';
  return 'jinja-punct';
}

/* SQL with Jinja in it. The SQL mode is never shown the Jinja: while it tokenizes,
   the line is cut short at the next delimiter, as CodeMirror's multiplex addon
   does. Shown the whole line, it took the apostrophe in {# don't #} for the start
   of a string and coloured the rest of the file as one. */
function dbtSqlMode(sql) {
  return {
    startState: () => ({ sql: CodeMirror.startState(sql), jinja: jinjaStart() }),
    copyState: (s) => ({ sql: CodeMirror.copyState(sql, s.sql), jinja: { ...s.jinja } }),
    token(stream, state) {
      if (state.jinja.close || stream.match(/^\{[{%#]/, false)) return jinjaToken(stream, state.jinja);
      const at = stream.string.slice(stream.pos).search(/\{[{%#]/);
      if (at < 0) return sql.token(stream, state.sql);
      const line = stream.string;
      stream.string = line.slice(0, stream.pos + at);
      try {
        return sql.token(stream, state.sql);
      } finally {
        stream.string = line;
      }
    },
    indent: sql.indent && ((state, textAfter, line) => sql.indent(state.sql, textAfter, line)),
    innerMode: (state) => ({ state: state.sql, mode: sql }),
  };
}

CodeMirror.defineMode('dbt-sql', (cfg) => dbtSqlMode(CodeMirror.getMode(cfg, 'text/x-sql')));

/* ref('x') / ref('pkg','x') / source('src','table') -> clickable marks, and
   ref('x', v=2) or version=2, which names one version of a model (0104).
   Marks live on the Doc, so they survive tab switches and are scanned once. */
const REF_RE = /\b(ref|source)\s*\(\s*(['"])([^'"\n]+)\2\s*(?:,\s*(['"])([^'"\n]+)\4\s*)?(?:,\s*(?:v|version)\s*=\s*(?:(['"])([^'"\n]*)\6|([\w.]+))\s*)?\)/g;
const TOKEN_RE = /[A-Za-z0-9_]+/g;
// An unquoted version is one only as a number: `v=my_var` is not known before
// dbt renders it, and `v=True` names no version (dbt builds `a.vTrue`), and
// read as a name either made a version that is not there. `1.` is no number
// to Jinja. A zero is false to dbt, so it names none.
const NUMBER_LITERAL = /^\d+(?:\.\d+)?$/;
const ZERO_LITERAL = /^0+(?:\.0*)?$/;

/* Blanks out {# ... #} blocks, keeping both offsets and line breaks intact: dbt
   never evaluates what is inside them, so neither should the link scanner.
   Only where Jinja's lexer opens one, in the text between blocks: a `{#` inside
   a string of a {{ }} or {% %} block, or in a raw block, is text, and masking
   from there cut the string in half, so every quote after it was read the
   wrong way round to the end of the file. */
function maskJinjaComments(src) {
  const opener = /\{([{%#])/g;
  let out = '', at = 0, m;
  while ((m = opener.exec(src)) !== null) {
    if (m[1] === '#') {
      const close = src.indexOf('#}', opener.lastIndex);
      if (close < 0) break;
      out += src.slice(at, m.index) + src.slice(m.index, close + 2).replace(/[^\n]/g, ' ');
      at = opener.lastIndex = close + 2;
    } else if (m[1] === '%' && /^[-+]?\s*raw\s*[-+]?%\}/.test(src.slice(opener.lastIndex, opener.lastIndex + 16))) {
      const endraw = /\{%[-+]?\s*endraw\s*[-+]?%\}/g;
      endraw.lastIndex = opener.lastIndex;
      opener.lastIndex = endraw.exec(src) ? endraw.lastIndex : src.length;
    } else {
      opener.lastIndex = Math.min(src.length, jinjaBlockEnd(src, opener.lastIndex, m[1] === '%' ? '%}' : '}}') + 2);
    }
  }
  return out + src.slice(at);
}

/* Where a block opened before `from` closes: the first `close` outside a
   string with every bracket shut, since Jinja's lexer reads the `}}` ending
   `{'a': {'b': 1}}` as two braces of the dict. A block still being typed, whose
   brackets never balance, ends at its first `close`, or at the end of the text. */
function jinjaBlockEnd(text, from, close) {
  let quote = '', depth = 0, first = -1;
  for (let i = from; i < text.length - 1; i++) {
    const c = text[i];
    if (quote) {
      if (c === '\\') i++;
      else if (c === quote) quote = '';
      continue;
    }
    if (c === '"' || c === "'") { quote = c; continue; }
    if (c === close[0] && text[i + 1] === '}') {
      if (depth <= 0) return i;
      if (first < 0) first = i;
    }
    if ('([{'.includes(c)) depth++;
    else if (')]}'.includes(c)) depth--;
  }
  return first >= 0 ? first : text.length;
}

/* Explicit ref() / source() calls, with the exact range of each name. */
function scanCalls(text) {
  const found = [];
  let m;
  REF_RE.lastIndex = 0;
  while ((m = REF_RE.exec(text)) !== null) {
    const isSource = m[1] === 'source';
    const q1 = m[2] + m[3] + m[2];
    const o1 = m[0].indexOf(q1);
    const a1 = [m.index + o1 + 1, m.index + o1 + 1 + m[3].length];
    let a2 = null;
    if (m[5] !== undefined) {
      const q2 = m[4] + m[5] + m[4];
      const o2 = m[0].indexOf(q2, o1 + q1.length);
      a2 = [m.index + o2 + 1, m.index + o2 + 1 + m[5].length];
    }
    if (isSource && !a2) continue;
    // A versioned model is named as dbt ls names it; no version is its latest,
    // which the server resolves the bare name to. dbt tests the argument for
    // truth, so a 0 or an empty string names no version either.
    const version = m[7] !== undefined ? m[7] : m[8];
    const named = m[7] !== undefined ? version !== '' : m[8] !== undefined && NUMBER_LITERAL.test(m[8]) && !ZERO_LITERAL.test(m[8]);
    const model = (m[5] !== undefined ? m[5] : m[3]) + (named ? '.v' + version : '');
    const name = isSource ? `${m[3]}.${m[5]}` : model;
    found.push({ name, ranges: isSource ? [a1, a2] : [a2 || a1] });
  }
  return found;
}

/* var('x') / var('x', default) / env_var('X') / env_var('X', 'd') -> hover marks.
   The dbt-sql mode gives var, env_var, ref and source the same `jinja-dbt`
   token, so the token type cannot tell them apart. The scanner can. */
const VAR_RE = /\b(var|env_var)\s*\(\s*(['"])([^'"\n]+)\2\s*(?:,([^)\n]*))?\)/g;

function scanVars(text) {
  const found = [];
  let m;
  VAR_RE.lastIndex = 0;
  while ((m = VAR_RE.exec(text)) !== null) {
    // \b matches after a dot too, so dbt_utils.var('x') would otherwise count.
    if (text[m.index - 1] === '.') continue;
    // The whole call, not just the name inside the quotes the way scanCalls
    // marks a ref(). `var('x')` reads as one word, so anything less than the
    // whole of it is a target you have to aim at, for its card and, a var(),
    // for the click that opens its line.
    const name = m.index + m[0].indexOf(m[2]) + 1;
    found.push({
      kind: m[1],
      name: m[3],
      fallback: m[4] === undefined ? '' : m[4].trim(),
      ranges: [[m.index, m.index + m[0].length]],
      // The name inside the quotes, which no other link may claim.
      nameAt: [name, name + m[3].length],
    });
  }
  return found;
}

/* Which link a click or a pause lands on, from the classes CodeMirror puts on
   the span under the pointer. A var()'s default can hold a ref() or a macro
   call, `var('t', ref('stg_payments'))`, whose span carries both marks'
   classes: the inner, tighter link wins, as a click did before a var() could
   be clicked; the hover now follows the click. 'env' is an env_var(), which
   has its card and nothing to open. */
function linkUnder(cl) {
  if (!cl) return '';
  if (cl.contains('cm-macrolink')) return 'macro';
  if (cl.contains('cm-dirlink')) return 'dir';
  if (cl.contains('cm-reflink')) return 'ref';
  if (cl.contains('cm-varlink')) return cl.contains('env') ? 'env' : 'var';
  return '';
}

/* The vocabulary's hits, a parent's name wherever it is written, less those
   inside a var()'s or an env_var()'s own name: `var('orders')` beside
   `ref('orders')` is the var, whose card and click are its own. A ref()
   written as a var's default is a call, not a vocabulary hit, and keeps its
   link. */
function outsideVarNames(text, hits) {
  const names = scanVars(text).map((v) => v.nameAt);
  const inside = ([from, to]) => names.some(([a, b]) => from >= a && to <= b);
  return hits.map((h) => ({ ...h, ranges: h.ranges.filter((r) => !inside(r)) })).filter((h) => h.ranges.length);
}

/* The line under a variable's value, saying where the value came from. Pure, so
   the wording can be checked without a DOM. `env` is the chosen file's name, or
   '' when this tab is showing the manifest as dbt parsed it. */
/* Why a value is hidden: the server says whether its name or its value gave
   it away, and a value found out by its name is the usual case. */
function hiddenWhy(row) {
  return row.redacted === 'value'
    ? 'hidden because the value carries a password'
    : 'hidden because the name reads as a credential';
}

function varNote(row, env) {
  const names = (row.vars || []).join(', ');
  const where = env || 'any environment file';
  if (row.redacted) {
    const why = hiddenWhy(row);
    return row.status === 'env' || row.status === 'placeholder' ? `set in ${where}, ${why}` : why;
  }
  switch (row.status) {
    case 'env':
      return row.default_used ? 'the default written in the call, not from a file' : `read from ${where}`;
    case 'missing':
      return env ? `${names} is not set in ${env}` : `${names} needs an environment, and none is selected`;
    case 'placeholder':
      return `${names} is a placeholder in ${where}, not a real value`;
    case 'unevaluated':
      return 'not evaluated: a secret, or Jinja this does not read';
    default:
      return '';
  }
}

/* automate_dv declares parents through a YAML metadata block rather than ref(),
   in more shapes than are worth chasing with one regex per shape:

       source_model: "stg_x"           source_model = ["a", "b"]
       source_model: stg_x             satellites:
       as_of_date_table: as_of_dates     sat_x__y:

   So the vocabulary comes from the manifest (the node's real parents) and only
   those names are looked for in the text. A name is linked when it is quoted,
   is a YAML key, or is a YAML value, which keeps short model names such as
   "order" or "status" from matching every column that happens to share the name.
*/
function scanVocabulary(text, vocab) {
  const found = [];
  if (!vocab.size) return found;
  let m;
  TOKEN_RE.lastIndex = 0;
  while ((m = TOKEN_RE.exec(text)) !== null) {
    const name = m[0];
    if (!vocab.has(name)) continue;
    const s = m.index, e = s + name.length;
    const prev = text[s - 1], next = text[e];
    const quoted = (prev === '"' && next === '"') || (prev === "'" && next === "'");
    const isKey = /^\s*:/.test(text.slice(e, e + 8));
    const isValue = prev !== '.' && /[:=]\s*$/.test(text.slice(Math.max(0, s - 32), s));
    if (quoted || isKey || isValue) found.push({ name, ranges: [[s, e]] });
  }
  return found;
}

/* The names a properties file declares nodes under, each to be linked to its
   node: a table under `sources:`, named `source.table` the way the graph names
   it, and an entry of one of these top-level lists. Only a `name:` on an item
   of such a list counts, so a column named like a model is never taken for
   one, and the `models:` of dbt_project.yml, a mapping of configs, declares
   nothing. Entries under `macros:` come back as well, for the macro links. */
const DECLARING_LISTS = new Set(['models', 'seeds', 'snapshots', 'analyses', 'exposures']);

function yamlDeclared(text) {
  const nodes = yamlOutline(text);
  const lines = text.split('\n');
  const starts = [];
  let offset = 0;
  for (const l of lines) { starts.push(offset); offset += l.length + 1; }
  // The key an item hangs from, when that key is a top-level list.
  const listOf = (item) => {
    const list = item.parent >= 0 ? nodes[item.parent] : null;
    return list && list.parent < 0 && list.kind === 'seq' ? list.label : '';
  };
  const nameUnder = (item) => {
    for (let j = item + 1; j < nodes.length && nodes[j].line <= nodes[item].endLine; j++) {
      if (nodes[j].parent !== item || nodes[j].label !== 'name') continue;
      const v = yamlNameAt(lines[nodes[j].line], nodes[j].col);
      return v ? v.value : '';
    }
    return '';
  };
  const sourceNames = new Map();
  const found = [];
  for (const n of nodes) {
    if (n.label !== 'name' || n.parent < 0) continue;
    const v = yamlNameAt(lines[n.line], n.col);
    if (!v) continue;
    const ranges = [[starts[n.line] + v.from, starts[n.line] + v.to]];
    const item = nodes[n.parent];
    const list = listOf(item);
    if (DECLARING_LISTS.has(list)) {
      found.push({ kind: 'node', name: v.value, ranges });
      continue;
    }
    if (list === 'macros') {
      found.push({ kind: 'macro', name: v.value, ranges });
      continue;
    }
    // A table's item hangs from `tables`, which sits on an item of `sources`.
    const tables = item.parent >= 0 ? nodes[item.parent] : null;
    if (!tables || tables.label !== 'tables' || tables.kind !== 'seq' || tables.parent < 0) continue;
    if (listOf(nodes[tables.parent]) !== 'sources') continue;
    if (!sourceNames.has(tables.parent)) sourceNames.set(tables.parent, nameUnder(tables.parent));
    const source = sourceNames.get(tables.parent);
    if (source) found.push({ kind: 'source', name: `${source}.${v.value}`, ranges });
  }
  return found;
}

/* The value of a `name:` key written at `col`, and where it sits in the line.
   Null for anything but a plain or quoted scalar: Jinja, a flow collection, an
   anchor or a block scalar never names a node the way it is written. */
function yamlNameAt(line, col) {
  const colon = line.indexOf(':', col);
  if (colon < 0) return null;
  let from = colon + 1;
  while (line[from] === ' ' || line[from] === '\t') from++;
  let to;
  const q = line[from];
  if (q === '"' || q === "'") {
    to = line.indexOf(q, from + 1);
    if (to < 0) return null;
    from++;
  } else {
    if (q === undefined || '[{|>&*!#'.includes(q)) return null;
    const comment = line.slice(from).search(/[ \t]#/);
    to = comment < 0 ? line.length : from + comment;
    while (to > from && /\s/.test(line[to - 1])) to--;
  }
  const value = line.slice(from, to);
  if (!value || value.includes('{{') || value.includes('{%')) return null;
  return { value, from, to };
}

/* The blocks of dbt_project.yml whose keys are folders. `vars`, `sources`,
   `flags`, `dispatch`, `exposures`, `metrics`, `semantic-models` and
   `saved-queries` nest the same way and are left alone: their keys are names,
   never paths. Both spellings of the test block are here, since dbt-core 1.8
   renamed it and projects carry either. */
const PATH_BLOCKS = new Set(['models', 'seeds', 'snapshots', 'analyses', 'macros', 'tests', 'data_tests']);

/* dbt's own config names. They decide nothing about what a key is: dbt reads a
   key holding a mapping as a folder unless it starts with `+`, whatever its
   name (0039). What the list does is name the mistake that rule punishes, a
   `docs:` or `meta:` written without its `+`, which dbt then looks for as a
   folder and applies to nothing, so the card of such a key can say why.

   Taken from what dbt writes: every key of `config` on a model, a seed and a
   test node of an 18 825 node manifest, plus the snapshot and seed configs its
   documentation lists, which that project has none of. A config missing from
   it costs only that sentence in a card. */
const DBT_CONFIGS = new Set([
  'access', 'alias', 'as_columnstore', 'batch_size', 'begin', 'check_cols', 'classifiers',
  'cluster_by', 'column_types', 'compute', 'concurrent_batches', 'contract', 'database',
  'dbt_valid_to_current', 'delimiter', 'docs', 'enabled', 'error_if', 'event_time', 'fail_calc',
  'file_format', 'freshness', 'full_refresh', 'grants', 'group', 'hard_deletes',
  'incremental_predicates', 'incremental_strategy', 'indexes', 'invalidate_hard_deletes',
  'latest_version_pointer', 'limit', 'lookback', 'materialized', 'meta', 'on_configuration_change',
  'on_error', 'on_schema_change', 'packages', 'persist_docs', 'post-hook', 'post_hook',
  'pre-hook', 'pre_hook', 'primary_key', 'query_tag', 'quote_columns', 'quoting', 'refresh_mode',
  'schema', 'severity', 'snapshot_meta_column_names', 'sql_header', 'static_analysis',
  'store_failures', 'store_failures_as', 'strategy', 'tags', 'target_database', 'target_lag',
  'target_schema', 'transient', 'unique_key', 'updated_at', 'warn_if', 'where',
]);

/* The key written at `col`, and where its own text sits in the line. One layer
   of quotes is left out, so a click on a quote does nothing, the way
   yamlNameAt treats a value. */
function yamlKeyRange(line, col) {
  const written = line.slice(col);
  const kv = yamlKey(written);
  if (!kv || !kv.key) return null;
  const q = written[0];
  const quoted = (q === '"' || q === "'") && written[1 + kv.key.length] === q;
  const from = col + (quoted ? 1 : 0);
  return [from, from + kv.key.length];
}

/* Every key in dbt_project.yml that names a folder, as the chain of keys the
   server places on disk (0036). One entry per key, so `models:` links to its
   root and each level below links to its own folder.

   dbt's rule decides, in dbt-core and in Fusion alike: a key is a path segment
   when it holds a mapping and does not start with `+`, and a config otherwise,
   whatever its name (0039). So a folder named `contract` or `schema` is a
   folder, and a `docs:` written without its `+` is one too, which dbt looks for
   and applies to nothing. A key under a `+config`, or under a sequence item,
   is out: nothing below either is a path.

   Each entry also carries where its key sits and the configs set directly
   under it, with the line each starts on, which is what the excerpt of the keys
   reaching a file shows (0038, 0156). */
function projectPathKeys(text) {
  const nodes = yamlOutline(text);
  const lines = text.split('\n');
  const starts = [];
  let offset = 0;
  for (const l of lines) { starts.push(offset); offset += l.length + 1; }
  const kids = nodes.map(() => []);
  nodes.forEach((n, j) => { if (n.parent >= 0) kids[n.parent].push(j); });

  const out = [];
  for (let i = 0; i < nodes.length; i++) {
    if (nodes[i].kind !== 'map') continue;
    const chain = [];
    let at = i;
    let ok = true;
    while (nodes[at].parent >= 0) {
      const parent = nodes[nodes[at].parent];
      // A sequence item is not a mapping key, whatever it holds.
      if (parent.kind === 'seq') { ok = false; break; }
      chain.unshift(nodes[at].label);
      at = nodes[at].parent;
    }
    if (!ok) continue;
    const block = nodes[at].label;
    if (!PATH_BLOCKS.has(block)) continue;
    if (chain.some((seg) => seg.startsWith('+'))) continue;
    const range = yamlKeyRange(lines[nodes[i].line], nodes[i].col);
    if (!range) continue;
    const base = starts[nodes[i].line];
    // The same rule the other way round: what a level sets is a `+`, or a value
    // that is no mapping, whatever the name.
    const sets = kids[i]
      .filter((j) => nodes[j].label.startsWith('+') || nodes[j].kind !== 'map')
      .map((j) => ({
        name: nodes[j].label, value: yamlLineValue(lines[nodes[j].line], nodes[j].col),
        node: j, line: nodes[j].line,
      }));
    out.push({
      block, chain, ranges: [[base + range[0], base + range[1]]],
      line: nodes[i].line, col: range[0], sets,
    });
  }
  return out;
}

/* A value as written on its line, less a trailing comment, quotes kept. A
   quote only opens where YAML could start a quoted scalar, so the apostrophe
   in `don't` hides no comment. */
function yamlValueText(v) {
  let quote = '';
  for (let i = 0; i < v.length; i++) {
    const c = v[i];
    if (quote) { if (c === quote) quote = ''; continue; }
    if ((c === '"' || c === "'") && (i === 0 || '[{, '.includes(v[i - 1]))) { quote = c; continue; }
    if (c === '#' && (i === 0 || v[i - 1] === ' ' || v[i - 1] === '\t')) return v.slice(0, i).trimEnd();
  }
  return v;
}

/* The value a key holds on its own line, as written, less a trailing comment
   and one layer of quotes. Empty when the value sits on the lines below, as a
   mapping, a list or a `|` block, since one line of a menu cannot hold it. */
function yamlLineValue(line, col) {
  const kv = yamlKey(line.slice(col));
  if (!kv) return '';
  const v = yamlValueText(kv.value);
  if (v[0] === '|' || v[0] === '>') return '';
  return unquote(v);
}

/* The project's `name:`, which is the first level of every fqn it owns. */
function projectNameIn(text) {
  const lines = text.split('\n');
  const top = yamlOutline(text).find((n) => n.parent < 0 && n.label === 'name');
  return (top && yamlLineValue(lines[top.line], top.col)) || null;
}

/* The blocks whose keys can reach a file, and the roots dbt reads them under
   when a package's own dbt_project.yml is not read, as 0036 places them. Macros
   are not here: a macro is no node, and a file holds several. */
const REACHED_BLOCKS = ['models', 'seeds', 'snapshots', 'analyses'];
const PACKAGE_ROOTS = { models: ['models'], seeds: ['seeds'], snapshots: ['snapshots'], analyses: ['analyses'], tests: ['tests'] };

/* Whether a file sits in an installed package, whose own project owns it. */
function inPackage(file) { return /^(dbt_packages|dbt_modules)\/[^/]+\/./.test(file); }

/* A file's fqn as dbt builds it: the project, the folders under the resource
   path it sits in, and its name without the extension. Read off the path, so
   it holds with no manifest at all, and it matched dbt's own for every model,
   seed and singular test of the 18 825 node project (0038).

   `roots` are the server's, one list per block. The longest root holding the
   file decides its kind, since one path may sit inside another. The test
   block's roots include the model roots, because a key there may name a
   model folder for the generic tests hanging on it (0036); those are left out
   here, so a model is never reached through `data_tests:`, which configures
   its tests rather than the model. A file under a package directory takes
   the package's name and the conventional roots. Null for a file that is no
   resource. */
function fileFqn(file, roots, name) {
  let parts = file.split('/');
  let head = name;
  let byBlock = roots || {};
  if (inPackage(file)) {
    head = parts[1];
    parts = parts.slice(2);
    byBlock = PACKAGE_ROOTS;
  }
  if (!head) return null;
  const rel = parts.join('/');
  const models = byBlock.models || [];
  const candidates = [];
  for (const b of REACHED_BLOCKS) for (const root of byBlock[b] || []) candidates.push({ blocks: [b], root });
  for (const root of byBlock.tests || []) {
    if (!models.includes(root)) candidates.push({ blocks: ['tests', 'data_tests'], root });
  }
  let best = null;
  for (const c of candidates) {
    if (rel.startsWith(c.root + '/') && (!best || c.root.length > best.root.length)) best = c;
  }
  if (!best) return null;
  const segs = rel.slice(best.root.length + 1).split('/');
  const leaf = segs.pop();
  const dot = leaf.lastIndexOf('.');
  segs.push(dot > 0 ? leaf.slice(0, dot) : leaf);
  return { blocks: best.blocks, fqn: [head, ...segs] };
}

/* The keys of dbt_project.yml that reach a file, broadest first. dbt's rule:
   a key applies to every node whose fqn its chain begins, so a model three
   folders below the only key written is reached by that key and by those
   above it, and the deepest one is not necessarily its own folder's. The key
   of the block itself applies to the whole kind, packages included. Where the
   config is written, and what a deeper level of this file replaces or adds to
   as dbt's merge rules say (0156): a `config()` in the file or in its
   properties YAML is applied after every level and is not looked at. */
function configLevels(keys, at) {
  if (!at) return [];
  const levels = keys
    .filter((k) => at.blocks.includes(k.block) && k.chain.length <= at.fqn.length
      && k.chain.every((seg, i) => seg === at.fqn[i]))
    .sort((a, b) => a.chain.length - b.chain.length);
  // A project writing both blocks is read by dbt through `data_tests:` alone.
  return levels.some((k) => k.block === 'data_tests') ? levels.filter((k) => k.block !== 'tests') : levels;
}

/* What the card of a key placed nowhere says. A key named after a config is
   almost always that config without its `+`, which dbt reads as a folder and
   so never applies: worth saying in those words, since nothing else will until
   dbt warns at parse time, and Fusion refuses the keys under it outright. */
function missingKeyNote(t) {
  const roots = (t.roots || []).join(', ');
  if (!roots) return `${t.block} has no readable path in this file, so there is nothing to look under.`;
  const last = t.chain[t.chain.length - 1];
  if (last && DBT_CONFIGS.has(last)) {
    return `Without its +, dbt reads ${last}: as a folder, finds none under ${roots}, and applies `
      + `nothing under it. Written +${last}:, it is the config.`;
  }
  return `No such folder under ${roots}. dbt reports a config path that matches nothing as a warning when it parses the project.`;
}

/* A config path that applies to no resource, as dbt writes it in its warning:
   the block by its own name, `data_tests` for one written `tests:`, then the
   keys below it (0103). */
function unusedSays(u) {
  return [u.block].concat(u.chain).join('.');
}

/* The kind of node each block's paths are used by. */
const BLOCK_NODES = {
  models: 'model', seeds: 'seed', snapshots: 'snapshot', sources: 'source', data_tests: 'data test',
  unit_tests: 'unit test', metrics: 'metric', semantic_models: 'semantic model', saved_queries: 'saved query',
  exposures: 'exposure', functions: 'function',
};

/* Why dbt warns of a path: no fqn of its kind begins with its keys, nor the
   fqn of any disabled node, which dbt counts for every block. A key named
   after a config is most likely that config without its `+`, which dbt reads
   as a folder (0039). */
function unusedWhy(u) {
  const kind = BLOCK_NODES[u.block] || 'node';
  const notes = [u.chain.length
    ? `No ${kind}'s fqn begins with these keys, nor any disabled node's, so what the last one sets applies to nothing.`
    : `The manifest holds no ${kind} and no disabled node, so what ${u.written || u.block}: sets applies to nothing.`];
  const last = u.chain[u.chain.length - 1];
  if (last && DBT_CONFIGS.has(last)) notes.push(`Without its +, dbt reads ${last}: as a folder; written +${last}:, it is the config.`);
  if (u.written) notes.push(`dbt reads ${u.written}: as ${u.block}:, its name since dbt 1.8.`);
  return notes.join(' ');
}

/* The paths under the reason they apply to nothing, each reason said once, in
   the order the paths come in. */
function unusedByWhy(list) {
  const groups = [];
  for (const u of list || []) {
    const why = unusedWhy(u);
    let g = groups.find((x) => x.why === why);
    if (!g) groups.push(g = { why, rows: [] });
    g.rows.push(u);
  }
  return groups;
}

/* How many leading keys of each path it has in common with the one before, so
   that a list of paths under one folder shows that folder once, dimmed after.
   Never every key: a path always shows its own last one. */
function unusedShared(list) {
  const keys = (u) => [u.block].concat(u.chain);
  return (list || []).map((u, i) => {
    if (!i) return 0;
    const a = keys(u);
    const b = keys(list[i - 1]);
    let n = 0;
    while (n < a.length - 1 && n < b.length && a[n] === b[n]) n++;
    return n;
  });
}

/* The line, from 0, that each path's last key sits on in the editor's text,
   found by its chain of keys rather than taken from the file the server read:
   an edit not saved yet moves a key, and a key taken out takes its mark with
   it. A path the text does not spell out, merged in from an anchor, is put
   at the server's line only when `saved` says the text is the file's. Nothing
   under a list item is a path. */
function unusedLines(text, unused, saved) {
  const nodes = yamlOutline(text);
  const at = new Map();
  nodes.forEach((n, i) => {
    const labels = [];
    for (let j = i; j >= 0; j = nodes[j].parent) {
      const p = nodes[j].parent;
      if (p >= 0 && nodes[p].kind === 'seq') return;
      labels.unshift(nodes[j].label);
    }
    const key = JSON.stringify(labels);
    if (!at.has(key)) at.set(key, n.line);
  });
  return (unused || []).flatMap((u) => {
    const line = at.get(JSON.stringify([u.written || u.block].concat(u.chain)));
    if (line !== undefined) return [{ line, u }];
    return saved && u.line > 0 ? [{ line: u.line - 1, u }] : [];
  });
}

/* The paths grouped by the line they are marked on, since a gutter keeps one
   mark per line: an alias and a path inside what it names, or two keys of one
   flow mapping, share a line and so a mark, whose card names each of them. */
function unusedByLine(marks) {
  const by = new Map();
  for (const { line, u } of marks) {
    if (!by.has(line)) by.set(line, []);
    by.get(line).push(u);
  }
  return Array.from(by, ([line, paths]) => ({ line, paths }));
}

/* What the pointer is on, for the hover card: the grey of a stale mark is in it,
   as the card then carries a note a fresh one does not. */
function unusedHoverKey(paths, stale) {
  return 'unused:' + (stale ? 'stale:' : '') + paths.map(unusedSays).join(' | ');
}

/* Calls inside Jinja, as the dotted name before a `(`: `hub`, `automate_dv.hub`.
   Only inside a block, since outside one `coalesce(` is SQL, and a project
   macro named like a SQL function would otherwise link every use of it.
   Whether a name is a macro, and which one, is the server's answer: the same
   bare `hub` is the project's own or automate_dv's depending on what the
   project defines (0028). A name after a dot is a method, after a pipe a
   filter, and after `macro` the definition itself; none of those is a call.
   The range is the macro's own name, without its package: the SQL mode draws
   `automate_dv`, the dot and `hub` as three tokens, and a mark across them
   would light up one piece at a time under the pointer. */
const JINJA_DEFINERS = new Set(['macro', 'test', 'materialization']);

/* `yaml` for a properties or project file, where Jinja inside a double-quoted
   scalar writes its own quotes as `\"`: YAML hands Jinja a plain `"`, so that
   is what the scan reads, one space and one quote keeping every offset. */
function scanMacroCalls(text, yaml = false) {
  if (yaml) text = text.replace(/\\"/g, ' "');
  const found = new Map();
  const opener = /\{([{%])[-+]?/g;
  let m;
  while ((m = opener.exec(text)) !== null) {
    const tag = m[1] === '%';
    const end = jinjaBlockEnd(text, opener.lastIndex, tag ? '%}' : '}}');
    let i = opener.lastIndex;
    let first = tag;           // the first word of a {% %} block is its tag
    let defines = false;       // and after `macro`, the next name is being defined
    let quote = '';
    while (i < end) {
      const c = text[i];
      if (quote) {
        if (c === '\\') i++;
        else if (c === quote) quote = '';
        i++;
        continue;
      }
      if (c === '"' || c === "'") { quote = c; i++; continue; }
      if (!/[A-Za-z_]/.test(c)) { i++; continue; }
      const from = i;
      while (i < end && /[\w.]/.test(text[i])) i++;
      const chain = text.slice(from, i);
      if (first) {
        first = false;
        defines = JINJA_DEFINERS.has(chain);
        // Nothing in a raw block is Jinja, so the scan resumes after it.
        if (chain === 'raw') {
          const close = /\{%[-+]?\s*endraw\s*[-+]?%\}/g;
          close.lastIndex = end;
          const r = close.exec(text);
          opener.lastIndex = r ? close.lastIndex : text.length;
          break;
        }
        continue;
      }
      if (defines) { defines = false; continue; }
      let j = i;
      while (text[j] === ' ' || text[j] === '\t') j++;
      if (text[j] !== '(' || text[from - 1] === '.') continue;
      let k = from - 1;
      while (k >= 0 && /\s/.test(text[k])) k--;
      if (text[k] === '|') continue;
      const parts = chain.split('.');
      if (parts.length > 2 || parts.some((p) => !p)) continue;
      if (!found.has(chain)) found.set(chain, []);
      found.get(chain).push([from + chain.lastIndexOf('.') + 1, from + chain.length]);
    }
    if (opener.lastIndex < end) opener.lastIndex = end;
  }
  return [...found].map(([call, ranges]) => ({ call, ranges }));
}

/* Where `{% macro name(` sits, as a line and a column, so a link lands on the
   definition rather than at the top of a file that may hold twenty. Comments
   are masked first: a commented-out copy is not the macro dbt reads. A generic
   test and a materialization are macros too, which dbt names from their own
   blocks: `{% test x(` is `test_x`, and `{% materialization x, adapter='y' %}`
   is `materialization_x_y`, `_default` without an adapter. The command line
   finds a macro the same way in `macros::block_in` (src/macros.rs), which also
   leaves a `{%` in a raw block or a string alone, as this does not: a change
   to what names a macro wants the other changed with it. */
function macroDefLine(text, name) {
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const masked = maskJinjaComments(text);
  let m = new RegExp('(\\{%[-+]?\\s*macro\\s+)' + esc(name) + '\\s*\\(').exec(masked);
  if (!m && name.startsWith('test_')) {
    m = new RegExp('(\\{%[-+]?\\s*test\\s+)' + esc(name.slice(5)) + '\\s*\\(').exec(masked);
  }
  if (!m && name.startsWith('materialization_')) {
    const adapterOf = (args) => (/\badapter\s*=\s*['"](\w+)['"]/.exec(args) || [])[1] || 'default';
    for (const hit of masked.matchAll(/(\{%[-+]?\s*materialization\s+)(\w+)([^%]*)/g)) {
      if (`materialization_${hit[2]}_${adapterOf(hit[3])}` === name) { m = hit; break; }
    }
  }
  if (!m) return null;
  const at = m.index + m[1].length;
  const before = text.slice(0, at);
  const line = before.split('\n').length - 1;
  return { line, ch: at - (before.lastIndexOf('\n') + 1) };
}

/* Where a data test is declared in a properties file (0041). The manifest
   gives a test no line, so it is looked for over the buffer: under the entry
   of `t.host`, the node whose YAML declares it, in the tests of its column,
   else in the entry's own, an item naming its generic, bare or through its
   package. Two items of one generic on one column differ by arguments no
   payload carries, so one whose `name:` is dbt's name for the test wins, and
   the first otherwise. Short of the item, the nearest thing found: the list,
   the column, the entry; nothing when the entry is not there. `end` is the
   item's last line, its arguments included, and the line itself otherwise. */
function testLine(text, t) {
  if (!t || !t.host || !t.test_name) return null;
  const nodes = yamlOutline(text), lines = text.split('\n');
  const kids = new Map();
  nodes.forEach((n, i) => {
    if (!kids.has(n.parent)) kids.set(n.parent, []);
    kids.get(n.parent).push(i);
  });
  const under = (i) => kids.get(i) || [];
  const key = (i, label) => (i == null ? null : under(i).find((j) => nodes[j].label === label));
  const value = (j) => yamlLineValue(lines[nodes[j].line], nodes[j].col);
  // dbt matches a column by name whatever its case, and a node by its name.
  const named = (list, name, fold) => (list == null ? null : under(list).find((i) => {
    const j = key(i, 'name');
    if (j == null) return false;
    const v = value(j);
    return fold ? v.toLowerCase() === name.toLowerCase() : v === name;
  }));
  const entry = (list, name) => {
    const i = named(list, name, false);
    return i != null ? i : named(list, name, true);
  };
  const tops = under(-1);
  let host = null;
  for (const top of tops) {
    if (host == null && DECLARING_LISTS.has(nodes[top].label)) host = entry(top, t.host);
  }
  // A source is `source.table` in the graph, a table under its source here.
  const dot = t.host.indexOf('.');
  if (host == null && dot > 0) {
    for (const top of tops) {
      if (host != null || nodes[top].label !== 'sources') continue;
      const src = entry(top, t.host.slice(0, dot));
      if (src != null) host = entry(key(src, 'tables'), t.host.slice(dot + 1));
    }
  }
  if (host == null) return null;

  const testsOf = (i) => {
    const d = key(i, 'data_tests');
    return d != null ? d : key(i, 'tests');
  };
  const col = t.column ? named(key(host, 'columns'), t.column, true) : null;
  const g = t.test_name;
  const same = (k) => {
    const v = unquote(String(k).replace(/\s+#.*$/, '').trim());
    return v === g || v.endsWith('.' + g);
  };
  // `- not_null`, `- relationships:` and its arguments, or an item naming
  // its generic under `test_name:`.
  const isTest = (i) => {
    const first = under(i)[0];
    if (first == null) return same(nodes[i].label);
    if (nodes[first].line === nodes[i].line && same(nodes[first].label)) return true;
    const tn = key(i, 'test_name');
    return tn != null && same(value(tn));
  };
  const called = (i) => {
    for (let j = i + 1; j < nodes.length && nodes[j].line <= nodes[i].endLine; j++) {
      if (nodes[j].label === 'name' && value(j) === t.name) return true;
    }
    return false;
  };
  const at = (i, whole) => ({ line: nodes[i].line, ch: nodes[i].col, end: whole ? nodes[i].endLine : nodes[i].line });
  // A generic on the whole model may name a column in its arguments, which
  // gives it a column in the manifest though it sits in the entry's tests.
  for (const list of [testsOf(col), testsOf(host)]) {
    if (list == null) continue;
    const found = under(list).filter(isTest);
    if (!found.length) continue;
    const mine = found.find(called);
    return at(mine != null ? mine : found[0], true);
  }
  return at([testsOf(col), col, testsOf(host), host].find((i) => i != null));
}

/* Whether a file defines a macro, a generic test or a materialization: the
   .sql files that carry no node of their own however fresh the manifest. Read
   from the buffer rather than asked of the manifest, so a macro written since
   the last parse counts as one too. */
function definesMacros(text) {
  return new RegExp('\\{%[-+]?\\s*(' + [...JINJA_DEFINERS].join('|') + ')\\s').test(maskJinjaComments(text));
}

/* The names a file's parents are linked by: each one's own, and a versioned
   model's bare name too, which a ref() naming no version writes and a macro's
   argument may carry. It goes to the latest version among the parents, else
   the first, and never over a parent of that very name (0104). */
function parentNames(parents) {
  const known = {};
  for (const p of parents) known[p.name] = p;
  for (const p of parents) {
    if (!p.base) continue;
    const held = known[p.base];
    if (!held || (held.base && p.latest && !held.latest)) known[p.base] = p;
  }
  return known;
}

/* The rows /api/resolve answered, by the name each was asked for: a model's
   bare name answers with its latest version's, `orders.v2`, and says so. */
function byAsked(rows) {
  const out = {};
  for (const r of rows) out[r.asked || r.name] = r;
  return out;
}

async function markRefs(doc, path) {
  doc.getAllMarks().forEach((mk) => { if (mk.refTarget) mk.clear(); });
  const text = maskJinjaComments(doc.getValue());
  const calls = scanCalls(text);
  // In a properties file, the names that declare its nodes link to them too.
  const declared = path && modeFor(path) === 'text/x-yaml' && text.length <= OUTLINE_MAX
    ? yamlDeclared(text).filter((d) => d.kind !== 'macro')
    : [];

  // The manifest is the authority on what this file actually depends on.
  let parents = [];
  if (path) {
    try { parents = (await nodeDetail({ file: path })).parents; }
    catch { /* not a dbt node: ref() calls are still linked below */ }
  }
  const known = parentNames(parents);

  const unknown = [...new Set([...calls, ...declared].map((c) => c.name))].filter((n) => !known[n]);
  const resolved = {};
  if (unknown.length) {
    try {
      const rows = await api.send('/api/resolve', 'POST', { names: unknown });
      Object.assign(resolved, byAsked(rows));
    } catch { /* leave them unresolved */ }
  }
  // A declared name is linked where it is declared and nowhere else: in the
  // vocabulary below, a table would also link every column sharing its name.
  for (const c of calls) if (resolved[c.name]) known[c.name] = resolved[c.name];

  // A source parent is named "src.table", which never appears as one token.
  // Custom macros such as replicate('crm', 'X') hide the source() call, so
  // the table half is added to the vocabulary when no model already claims it.
  for (const [name, target] of Object.entries({ ...known })) {
    const dot = name.indexOf('.');
    // A versioned model's `orders.v2` has no table half, and `v2` is no name.
    if (dot < 0 || (target.kind && target.kind !== 'source')) continue;
    const table = name.slice(dot + 1);
    if (!known[table]) known[table] = target;
  }
  const vocab = new Set(Object.keys(known).filter((n) => !n.includes('.')));
  // Declared first, so a name that is both keeps the click that stays put.
  const hits = [...declared, ...calls, ...outsideVarNames(text, scanVocabulary(text, vocab))];
  const isCall = new Set(calls), isDeclared = new Set(declared);

  const seen = new Set();
  for (const hit of hits) {
    // A declared name asked for itself, and `known` may hold a source table
    // of the same name: a model called after its source links to the model.
    const target = isDeclared.has(hit)
      ? resolved[hit.name] || known[hit.name]
      : known[hit.name] || resolved[hit.name];
    for (const [from, to] of hit.ranges) {
      if (seen.has(from)) continue;
      seen.add(from);
      if (!target && !isCall.has(hit) && !isDeclared.has(hit)) continue;
      const title = target
        ? `${target.disabled ? 'DISABLED ' : ''}${target.kind}${target.materialized ? ' · ' + target.materialized : ''}\n${target.file}`
        : `${hit.name} is in no manifest node (stale manifest or a typo)`;
      // No `attributes: {title}`: the native tooltip it drew is now the hover
      // card's job, and the two would overlap. The line it used to show is kept
      // on the mark so the card can say exactly the same thing.
      const mark = doc.markText(doc.posFromIndex(from), doc.posFromIndex(to), {
        className: 'cm-reflink' + (target ? (target.disabled ? ' dis' : '') : ' missing'),
      });
      mark.refTarget = target || { name: hit.name };
      mark.refTitle = title;
      if (isDeclared.has(hit)) mark.declared = true;
    }
  }
}

/* Marks every var() and env_var() call so the hover card has something to
   attach to. Synchronous on purpose: the values arrive when a card opens, not
   on every keystroke. markRefs only ever clears its own refTarget marks and
   this only ever clears its own, and ref|source and var|env_var are disjoint,
   so the two never contend for a range. */
function markVars(doc) {
  doc.getAllMarks().forEach((mk) => { if (mk.varTarget) mk.clear(); });
  const text = maskJinjaComments(doc.getValue());
  for (const hit of scanVars(text)) {
    for (const [from, to] of hit.ranges) {
      // A var() opens its line on a click; an env_var() has only its card.
      const mark = doc.markText(doc.posFromIndex(from), doc.posFromIndex(to), {
        className: hit.kind === 'var' ? 'cm-varlink' : 'cm-varlink env',
      });
      mark.varTarget = hit;
    }
  }
}

/* Links every macro call in the buffer, and in a properties file every entry
   under `macros:`, to the file that defines the macro. The names come from the
   buffer and the answer from the manifest (0028): only a call the server can
   place in the project comes back, so dbt's own macros, Jinja's builtins and a
   typo all stay text. The marks are replaced only once the answer is in, and
   not at all when a later scan has started or the buffer has moved on, since
   ranges read from one text would land on the wrong words of another. */
async function markMacros(doc, path) {
  const scan = doc.macroScan = (doc.macroScan || 0) + 1;
  const raw = doc.getValue();
  const text = maskJinjaComments(raw);
  const yaml = !!path && modeFor(path) === 'text/x-yaml';
  const hits = scanMacroCalls(text, yaml);
  if (yaml && text.length <= OUTLINE_MAX) {
    for (const d of yamlDeclared(text)) if (d.kind === 'macro') hits.push({ call: d.name, ranges: d.ranges });
  }
  let links = [];
  if (hits.length) {
    try {
      links = await api.send('/api/macros/resolve', 'POST', { file: path || '', calls: hits.map((h) => h.call) });
    } catch { return; }
  }
  if (doc.macroScan !== scan || doc.getValue() !== raw) return;
  doc.getAllMarks().forEach((mk) => { if (mk.macroTarget) mk.clear(); });
  const byCall = new Map(links.map((l) => [l.call, l]));
  for (const hit of hits) {
    const target = byCall.get(hit.call);
    if (!target) continue;
    for (const [from, to] of hit.ranges) {
      const mark = doc.markText(doc.posFromIndex(from), doc.posFromIndex(to), { className: 'cm-macrolink' });
      mark.macroTarget = target;
    }
  }
}

/* Links every folder key in dbt_project.yml to the folder it configures. The
   chains come from the buffer and the answer from the server, the only side
   that sees the disk and reads `model-paths` (0036). A chain it cannot place
   is marked all the same, dashed: dbt says a config reaching nothing only once,
   at parse time, and the card says it where the key is. Guarded like
   markMacros, since ranges read from one text would land on the words of
   another. */
async function markProjectDirs(doc, path) {
  if (path !== 'dbt_project.yml') return;                 // a package's own is its own
  const scan = doc.dirScan = (doc.dirScan || 0) + 1;
  const raw = doc.getValue();
  if (raw.length > OUTLINE_MAX) return;
  const keys = projectPathKeys(raw);
  let answer = { placed: [], roots: {} };
  if (keys.length) {
    try { answer = await api.send('/api/project/resolve', 'POST', { keys: keys.map((k) => ({ block: k.block, chain: k.chain })) }); }
    catch { return; }
  }
  if (doc.dirScan !== scan || doc.getValue() !== raw) return;
  doc.getAllMarks().forEach((mk) => { if (mk.dirTarget) mk.clear(); });
  const placed = new Map((answer.placed || []).map((p) => [dirKey(p), p]));
  for (const key of keys) {
    const target = placed.get(dirKey(key)) || { block: key.block, chain: key.chain, roots: dirRoots(answer.roots, key.block) };
    for (const [from, to] of key.ranges) {
      const mark = doc.markText(doc.posFromIndex(from), doc.posFromIndex(to), {
        className: 'cm-dirlink' + (target.path ? '' : ' missing'),
      });
      mark.dirTarget = target;
    }
  }
}

/* The block and the chain together, which is how a mark finds its answer: a
   pair, not a joined string, so a key holding a slash cannot collide. */
const dirKey = (k) => JSON.stringify([k.block, k.chain]);

/* Where the server looked, which is what a key that found nothing can say. */
const dirRoots = (roots, block) => (roots || {})[block] || [];

/* The keys of dbt_project.yml that dbt would warn of, each marked in a gutter
   of its own (0103). The paths are the server's, read from the file on disk
   against the manifest, and read again only when the Reports index says their
   count or their files moved; the lines are the text's own (unusedLines). The
   gutter is there only while the file in front has a mark. */
async function markUnusedPaths(doc, path) {
  if (path !== 'dbt_project.yml') return;
  const scan = doc.unusedScan = (doc.unusedScan || 0) + 1;
  const entry = S.reports && S.reports.warnings;
  const key = JSON.stringify(entry || null);
  let report = null;
  if (entry) {
    if (S.unused && S.unused.key === key) report = S.unused.report;
    else {
      try { report = await api.get('/api/reports/warnings'); }
      catch { return; }
      S.unused = { key, report };
    }
  }
  if (doc.unusedScan !== scan) return;
  const f = S.open.get(path);
  const marks = report ? unusedLines(doc.getValue(), report.unused, !!f && !f.dirty) : [];
  // Grey while the manifest is behind, as the chip is gone then.
  const stale = warningsStale(report, S.fresh);
  // A card still waiting to open would measure the element this removes.
  if (hoverKey.startsWith('unused:')) closeHoverCard();
  doc.clearGutter('cfgwarn');
  for (const { line, paths } of unusedByLine(marks)) {
    // The hover card says why (wireHovers), so no native tooltip says it again.
    const el = jel('div', 'cfgwarn-mark' + (stale ? ' stale' : ''), '!');
    el.unusedPaths = paths;
    el.unusedStale = stale;
    el.setAttribute('aria-label', `dbt warns that ${paths.map(unusedSays).join(' and ')} ${paths.length > 1 ? 'apply' : 'applies'} to no resource`);
    el.addEventListener('mousedown', (e) => { e.preventDefault(); openReports('warnings'); });
    doc.setGutterMarker(line, 'cfgwarn', el);
  }
  doc.unusedMarks = marks.length;
  if (S.cm && S.cm.getDoc() === doc) paintWarnGutter();
}

function remarkUnusedPaths() {
  const f = S.open.get('dbt_project.yml');
  if (f && f.doc) markUnusedPaths(f.doc, 'dbt_project.yml');
}

/* The gutter of those marks, shown beside the line numbers only for a file
   that has one, so every other file keeps its width. */
function paintWarnGutter() {
  const want = !!S.cm.getDoc().unusedMarks;
  if (want === (S.cm.getOption('gutters') || []).includes('cfgwarn')) return;
  S.cm.setOption('gutters', want ? ['cfgwarn', 'CodeMirror-linenumbers'] : []);
}

function wireRefClicks(cm) {
  cm.getWrapperElement().addEventListener('mousedown', (e) => {
    if (e.button !== 0 || e.altKey) return;              // alt-click still places the cursor
    const kind = linkUnder(e.target.classList);
    if (!kind || kind === 'env') return;
    const pos = cm.coordsChar({ left: e.clientX, top: e.clientY }, 'window');
    const marks = cm.findMarksAt(pos);
    const macro = kind === 'macro' && marks.find((mk) => mk.macroTarget);
    if (macro) {
      e.preventDefault();
      openMacro(macro.macroTarget);
      return;
    }
    const folder = kind === 'dir' && marks.find((mk) => mk.dirTarget);
    if (folder) {
      e.preventDefault();
      openConfigPath(folder.dirTarget);
      return;
    }
    const v = kind === 'var' && marks.find((mk) => mk.varTarget && mk.varTarget.kind === 'var');
    if (v) {
      e.preventDefault();
      openVarDef(v.varTarget);
      return;
    }
    const mark = marks.find((mk) => mk.refTarget);
    if (!mark) return;
    e.preventDefault();
    const t = mark.refTarget;
    if (!t.id) return toast(`${t.name} is not in the manifest`, 'err');
    pushJump();
    if (mark.declared) return focusDeclared(t.id);
    openFile(t.file, { focusLineage: false, preview: true });
    focusNode(t.id);
    revealInTree(t.file);
  });
}

/* A name clicked in the file that declares it. The editor stays where it is,
   since the definition is the line that was clicked, and the lineage moves.
   The terminal is the one dock that shows nothing of a node, so from there
   the lineage is brought forward; the others all follow the focus. */
function focusDeclared(id) {
  focusNode(id);
  if (!$('#dock-terminal').classList.contains('hidden')) showDock('lineage');
}

/* The file a macro is defined in, at its `{% macro %}` line, or at `t.line`
   lines into it. The lineage stays on the model being read: a macro is not a
   node. */
async function openMacro(t) {
  pushJump();
  await openFile(t.file, { focusLineage: false, preview: true });
  const f = S.open.get(t.file);
  if (S.active !== t.file || !f || !f.doc) return;          // it could not be opened
  revealInTree(t.file);
  const at = macroDefLine(f.doc.getValue(), t.name);
  // A finding names a line of the macro's own text, counted from its `{% macro %}`.
  if (at) gotoPos(at.line + (t.line > 1 ? t.line - 1 : 0), t.line > 1 ? 0 : at.ch);
}

/* The model's file opened as a macro's is, with the names a card lists lit in
   it (0145). */
async function openFileOnNames(file, names) {
  pushJump();
  await openFile(file, { focusLineage: false, preview: true });
  const f = S.open.get(file);
  if (S.active !== file || !f || !f.doc) return;             // it could not be opened
  revealInTree(file);
  findNames(S.cm, names);
}

/* The model's compiled SQL in the dock, with the same names lit once it is
   painted. A text dbt has not compiled is left as the pane says. */
async function openCompiledOnNames(id, names) {
  // Only when this load painted the model's compiled SQL: not a text dbt has
  // not compiled, nor an error, nor an answer a later load has passed.
  if (!await showDock('compiled', { id })) return;
  // The pane measures itself in a timer queued as it was painted; the match is
  // scrolled to only after it, or it lands on stale heights.
  await new Promise((done) => setTimeout(done, 0));
  findNames(S.artifactCm.compiled, names);
}

/* A project var's definition in dbt_project.yml, at its key, lit as a test's
   line is. The server says whether the block defines it, as the card does, so
   a var it would not find there opens nothing, and the line is the buffer's
   (varLanding). A tab of the file with unsaved edits is what is on screen and
   the server reads the disk, so the buffer alone decides then: a key added
   there is found, one renamed or deleted is not. The place to come back to is
   taken before any wait, as the click left it. */
async function openVarDef(t) {
  const from = here();
  const file = 'dbt_project.yml';
  const kept = S.open.get(file);
  let row = null;
  if (kept && kept.dirty && kept.doc) {
    if (!varDefLine(kept.doc.getValue(), t.name)) return toast(`${t.name} is not in the vars: block of the unsaved ${file}`);
  } else {
    let body;
    try { body = await fetchVars(''); } catch { return toast(`could not read ${file}`, 'err'); }
    row = (body.vars || []).find((v) => v.name === t.name);
    if (!row) return toast(`${t.name} is not in the vars: block of ${file}`);
    // Another file opened during the wait: the click's place is gone, and
    // following it now would pin a preview nobody asked to keep.
    if ((here() || {}).key !== (from || {}).key) return;
  }
  pushJump({ at: from });
  await openFile(file, { focusLineage: false, preview: true });
  const f = S.open.get(file);
  if (S.active !== file || !f || !f.doc) return;             // it could not be opened
  revealInTree(file);
  const at = varLanding(f.doc.getValue(), t.name, f.dirty ? null : row);
  if (!at) return;
  gotoPos(at.line, at.ch);
  // In the upper third rather than at an edge, the vars around it in view.
  const third = S.cm.getScrollInfo().clientHeight / 3;
  S.cm.scrollIntoView({ from: { line: at.line, ch: 0 }, to: { line: at.line, ch: 0 } }, third);
  flashLines(at.line, at.line);
}

/* A generic test opened where it is declared (0041): its properties file, at
   the item `testLine` finds under its host, even when that file is the one
   shown. `pin` keeps the tab, as a double click does; `focus` false leaves the
   keyboard on the canvas a click came from. A second click on the test the
   cursor already sits on, the first half of a double click among them, is no
   new place to come back to, so it records none. */
async function openTest(t, { pin = false, focus = true } = {}) {
  if (!t || !t.file) return;
  const spot = (f) => {
    if (!f || !f.doc) return null;
    const text = f.doc.getValue();
    return text.length <= OUTLINE_MAX ? testLine(text, t) : null;
  };
  const there = S.active === t.file && S.cm ? spot(S.open.get(t.file)) : null;
  const cur = there && S.cm.getCursor();
  if (!(cur && cur.line === there.line && cur.ch === there.ch)) pushJump({ pin });
  await openFile(t.file, { focusLineage: false, preview: !pin });
  revealInTree(t.file);
  const f = S.open.get(t.file);
  if (S.active !== t.file || !f || !f.doc) return;           // it could not be opened
  const at = spot(f);
  if (!at) return;
  gotoPos(at.line, at.ch, focus);
  // In the upper third rather than at an edge, its arguments below it.
  const third = S.cm.getScrollInfo().clientHeight / 3;
  S.cm.scrollIntoView({ from: { line: at.line, ch: 0 }, to: { line: at.line, ch: 0 } }, third);
  flashLines(at.line, at.end);
}

/* Lines lit for a moment, then faded, so the eye finds where a jump landed
   among a few hundred alike. Only one at a time: a second jump clears the
   first rather than leaving two lit. */
let flashed = null;
function flashLines(from, to) {
  if (!S.cm) return;
  const doc = S.cm.getDoc();
  if (flashed) {
    clearTimeout(flashed.timer);
    flashed.handles.forEach((h) => flashed.doc.removeLineClass(h, 'background', 'cm-flash'));
  }
  const handles = [];
  for (let l = from; l <= Math.min(to, from + 40); l++) handles.push(doc.addLineClass(l, 'background', 'cm-flash'));
  const timer = setTimeout(() => {
    handles.forEach((h) => doc.removeLineClass(h, 'background', 'cm-flash'));
    flashed = null;
  }, 1800);
  flashed = { doc, handles, timer };
}

/* The cursor's line, lit in the page and its number in the gutter (--cur-line,
   0166). One at a time, with the document it belongs to as flashLines keeps its
   own: a tab switched to has its line painted after swapDoc, and the line left
   behind in the other document is cleared there, not left lit under it. */
let curLine = null;
function paintCurLine() {
  if (!S.cm) return;
  const doc = S.cm.getDoc();
  const handle = doc.getLineHandle(doc.getCursor('head').line);
  if (curLine && curLine.doc === doc && curLine.handle === handle) return;
  if (curLine) {
    curLine.doc.removeLineClass(curLine.handle, 'background', 'cm-curline');
    curLine.doc.removeLineClass(curLine.handle, 'gutter', 'cm-curline-gutter');
  }
  doc.addLineClass(handle, 'background', 'cm-curline');
  doc.addLineClass(handle, 'gutter', 'cm-curline-gutter');
  curLine = { doc, handle };
}

/* The folder a config key in dbt_project.yml configures, opened in the tree
   rather than in a tab: there is nothing to read in a folder. A chain the
   server could not place does nothing here, since the card is what explains
   it. The lineage stays where it is, as it does for a macro: a folder is not a
   node. */
async function openConfigPath(t) {
  if (!t.path) return;
  showSide('files');
  if (!t.dir) {
    await openFile(t.path, { focusLineage: false, preview: true });
    revealInTree(t.path);
    return;
  }
  if (!await revealInTree(t.path, { expand: true })) toast(`${t.path} is not in the tree`, 'err');
}

/* Hovering a mark opens the card. The classList gate comes first because
   coordsChar snaps to the nearest character even far past the end of a line, so
   without it every move over the empty area to the right of a line would
   resolve onto whatever mark that line ends with. */
function wireHovers(cm) {
  const wrap = cm.getWrapperElement();
  // The editor's cards stay over the editor (0167), the tabs and the code both.
  const inEditor = () => $('#editor-pane').getBoundingClientRect();
  wrap.addEventListener('mousemove', (e) => {
    const cl = e.target.classList;
    if (cl && cl.contains('cfgwarn-mark')) {
      const mark = e.target;
      return hoverEnter(unusedHoverKey(mark.unusedPaths, mark.unusedStale), () => mark.getBoundingClientRect(),
        (el) => fillUnusedCard(el, mark.unusedPaths, mark.unusedStale), inEditor);
    }
    const kind = linkUnder(cl);
    if (!kind) return hoverLeave();
    const pos = cm.coordsChar({ left: e.clientX, top: e.clientY }, 'window');
    const at = () => cm.charCoords(pos, 'window');
    if (kind === 'dir') {
      const dm = cm.findMarksAt(pos).find((mk) => mk.dirTarget);
      if (!dm) return hoverLeave();
      return hoverEnter('dir:' + dirKey(dm.dirTarget), at, (el) => fillDirCard(el, dm.dirTarget), inEditor);
    }
    if (kind === 'macro') {
      const mm = cm.findMarksAt(pos).find((mk) => mk.macroTarget);
      if (!mm) return hoverLeave();
      return hoverEnter('macro:' + mm.macroTarget.id, at, (el) => fillMacroCard(el, mm.macroTarget), inEditor);
    }
    if (kind === 'var' || kind === 'env') {
      const vm = cm.findMarksAt(pos).find((mk) => mk.varTarget);
      if (!vm) return hoverLeave();
      return hoverEnter(`${vm.varTarget.kind}:${vm.varTarget.name}`, at, (el) => fillVarCard(el, vm.varTarget), inEditor);
    }
    const mark = cm.findMarksAt(pos).find((mk) => mk.refTarget);
    if (!mark) return hoverLeave();
    const t = mark.refTarget;
    if (!t.id) {
      return hoverEnter('miss:' + t.name, at, (el) => {
        hoverCardBody(el, { title: t.name });
        el.append(Object.assign(document.createElement('div'), { className: 'hc-desc muted', textContent: mark.refTitle }));
      }, inEditor);
    }
    hoverEnter('node:' + t.id, at, (el) => fillNodeCard(el, t.id, t), inEditor);
  });
  wrap.addEventListener('mouseleave', hoverLeave);
}

function modeFor(path) {
  const p = path.toLowerCase();
  if (p.endsWith('.sql')) return 'dbt-sql';
  if (p.endsWith('.yml') || p.endsWith('.yaml')) return 'text/x-yaml';
  if (p.endsWith('.md')) return 'text/x-markdown';
  return null;
}

function initEditor() {
  // The marks of a heading are tokens of their own, so they can be quieter than its words (0165).
  CodeMirror.defineMIME('text/x-markdown', { name: 'markdown', highlightFormatting: true });
  S.cm = CodeMirror($('#editor-host'), {
    lineNumbers: true, lineWrapping: false, indentUnit: 4, tabSize: 4,
    styleActiveLine: false, value: '',
  });
  S.cm.on('change', (cm, ch) => {
    // The file itself changing on disk is no edit of the user's (0067).
    if (!S.active || ch.origin === 'disk') return;
    const f = S.open.get(S.active);
    if (!f || ownsPane(f)) return;
    const pinned = S.preview === S.active;
    if (pinned) S.preview = null;       // editing a preview tab pins it
    if (f && !f.dirty) { f.dirty = true; renderTabs(); }
    else if (pinned) renderTabs();
  });
  S.cm.on('cursorActivity', updateStatus);
  S.cm.on('cursorActivity', crumbCursor);
  S.cm.on('cursorActivity', paintCurLine);
  let rescan = null;
  S.cm.on('change', (cm, ch) => {
    // A reload scans its own tab: under a diff tab, S.cm still holds the last
    // file's Doc, and S.active would name the diff (0067).
    if (ch.origin === 'disk') return;
    clearTimeout(rescan);
    // The path as well as the Doc, taken now: a tab switched within the delay
    // would otherwise scan this file as that one, and a .yml would lose the
    // links only a properties file gets.
    const doc = S.cm.getDoc(), path = S.active;
    rescan = setTimeout(() => {
      markLinks(doc, path);
      refreshOutline();
      renderCrumbs();
    }, 500);
  });
  wireRefClicks(S.cm);
  wireHovers(S.cm);
}

// ------------------------------------------------------------------ find --
/* Find inside one editor: the file being edited, the Compiled or Run SQL, a
   diff. The browser's own find cannot do this, because CodeMirror keeps only
   the lines on screen in the page, so a match two screens down is not there to
   be found. The search runs over the document CodeMirror holds instead, and the
   highlight is an overlay, which CodeMirror paints a line at a time as it draws
   it. Both go through matchInLine, so the count and the highlight cannot
   disagree about what a match is. */

function escapeRegExp(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/* The query as a global RegExp, or why it cannot be one. A plain query is
   escaped, so `.` and `(` mean themselves. */
function findPattern(query, opts) {
  if (!query) return { re: null, error: '' };
  const flags = opts.caseSensitive ? 'g' : 'gi';
  if (!opts.regex) return { re: new RegExp(escapeRegExp(query), flags), error: '' };
  try {
    return { re: new RegExp(query, flags), error: '' };
  } catch (e) {
    return { re: null, error: e.message };
  }
}

/* A letter, a digit or an underscore, in any script: `donn` is not a whole
   word inside `données`. */
function isWordChar(ch) {
  return !!ch && /[\p{L}\p{N}_]/u.test(ch);
}

/* VS Code's rule for a whole word: each end of the match meets the edge of the
   line or something that is not part of a word, or is not part of one itself,
   so `.id` is a whole word in `o.id` and `id` is not one in `order_id`. */
function wholeWord(text, from, to) {
  const left = from === 0 || !isWordChar(text[from - 1]) || !isWordChar(text[from]);
  const right = to === text.length || !isWordChar(text[to]) || !isWordChar(text[to - 1]);
  return left && right;
}

/* The first match in one line at or after `from`, as {from, to}, or null. An
   empty match is stepped over: `^` or `x*` matches between every two
   characters, and a find that stopped there would never move. */
function matchInLine(text, re, from, whole) {
  for (let at = from; at <= text.length;) {
    re.lastIndex = at;
    const m = re.exec(text);
    if (!m) return null;
    const end = m.index + m[0].length;
    if (end > m.index && (!whole || wholeWord(text, m.index, end))) return { from: m.index, to: end };
    at = m.index + 1;
  }
  return null;
}

/* Every match in document order, as {line, from, to}, and whether there were
   more than `cap`. Line by line, as the overlay paints, so `^` and `$` are the
   ends of a line and no match runs across two. Past the cap the count says so
   rather than going on: nobody steps through ten thousand matches, and each
   one is an object. */
function findMatches(lines, re, whole, cap) {
  const hits = [];
  if (!re) return { hits, capped: false };
  for (let line = 0; line < lines.length; line++) {
    const text = lines[line];
    for (let m = matchInLine(text, re, 0, whole); m; m = matchInLine(text, re, m.to, whole)) {
      if (hits.length === cap) return { hits, capped: true };
      hits.push({ line, from: m.from, to: m.to });
    }
  }
  return { hits, capped: false };
}

/* The match a step lands on, as {line, from, to}, or null when there is none.
   Forward, the first one starting at or after `pos`; backward, the last one
   starting before it; both wrap around the end. Read from the text rather
   than from the counted matches, so a step past the cap still finds the next
   one. Each line is read from its start, as the count and the overlay read it,
   so a step never lands on a match neither of them has: `aa` in `aaa` is the
   first two letters, even from a cursor after the first. */
function nextMatch(lines, re, whole, pos, dir) {
  const n = lines.length;
  if (!re || !n) return null;
  const at = Math.min(pos.line, n - 1);
  // k runs once round the document and back onto the starting line, where
  // only the part the first pass left out still counts.
  for (let k = 0; k <= n; k++) {
    const line = dir > 0 ? (at + k) % n : (at - k + n) % n;
    let pick = null;
    for (let m = matchInLine(lines[line], re, 0, whole); m; m = matchInLine(lines[line], re, m.to, whole)) {
      const after = m.from >= pos.ch;
      if (k === 0 && after !== dir > 0) continue;
      if (k === n && after === dir > 0) continue;
      pick = m;
      if (dir > 0) break;
    }
    if (pick) return { line, from: pick.from, to: pick.to };
  }
  return null;
}

/* Whether a selection is exactly a match, however far past the cap. */
function isMatch(lines, re, whole, from, to) {
  if (!re || from.line !== to.line || from.line >= lines.length) return false;
  const text = lines[from.line];
  for (let m = matchInLine(text, re, 0, whole); m && m.from <= from.ch; m = matchInLine(text, re, m.to, whole)) {
    if (m.from === from.ch && m.to === to.ch) return true;
  }
  return false;
}

/* Which counted match a selection is, or -1: the ordinal in "3 of 17". Past
   the cap there is none to give. */
function hitAt(hits, from, to) {
  let lo = 0, hi = hits.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    const h = hits[mid];
    if (h.line < from.line || (h.line === from.line && h.from < from.ch)) lo = mid + 1;
    else hi = mid;
  }
  const h = hits[lo];
  return h && h.line === from.line && h.from === from.ch && to.line === h.line && to.ch === h.to ? lo : -1;
}

/* What the bar says beside the box. `at` is the counted match the selection
   is on, or -1; `onMatch` says the selection is a match all the same, one past
   the cap, which has no number to give. */
function findLabel(query, found, at, error, onMatch) {
  if (!query) return '';
  if (error) return 'invalid pattern';
  const n = found.hits.length;
  if (!n) return 'No results';
  const total = n + (found.capped ? '+' : '');
  if (at >= 0) return (at + 1) + ' of ' + total;
  if (onMatch) return '? of ' + total;
  return total + (n === 1 && !found.capped ? ' result' : ' results');
}

/* Every match painted, as an overlay mode. CodeMirror hands it one line at a
   time from its start, so each call either paints the match it stands on or
   skips to the next one. */
function findOverlay(re, whole) {
  return {
    token(stream) {
      const m = matchInLine(stream.string, re, stream.pos, whole);
      if (!m) { stream.skipToEnd(); return null; }
      if (m.from > stream.pos) { stream.pos = m.from; return null; }
      stream.pos = m.to;
      return 'findhit';
    },
  };
}

/* What the last bar used, which is what the next one opens with, the way VS
   Code carries a search from one editor to the next: Cmd+F in the Compiled tab
   after a search in the model looks for the same thing. Each open bar keeps
   its own copy, so typing in one never changes what another highlights. */
const findPrefs = { query: '', caseSensitive: false, wholeWord: false, regex: false };
const FIND_CAP = 10000;

// One of a find bar's buttons: previous, next, close.
function findButton(label, title, run) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'icon';
  b.textContent = label;
  b.title = title;
  b.addEventListener('click', run);
  return b;
}

/* One editor's bar, built the first time Cmd+F reaches that editor. It lives
   inside CodeMirror's own wrapper, where CodeMirror's dialogs go, so it moves
   with the editor: the Compiled one is detached and put back between nodes. */
function findBar(cm) {
  if (cm.state.findBar) return cm.state.findBar;
  const st = {
    cm, open: false, q: { ...findPrefs }, key: '', re: null, error: '', lines: [],
    found: { hits: [], capped: false }, at: -1, cur: null, mark: null, overlay: null,
    origin: { line: 0, ch: 0 }, moving: false, timer: 0,
    keys: { Esc: () => closeFind(cm) },
  };
  const bar = document.createElement('div');
  bar.className = 'findbar hidden';
  bar.setAttribute('role', 'search');
  const input = document.createElement('input');
  input.className = 'find-q';
  input.placeholder = 'Find';
  input.spellcheck = false;
  input.autocomplete = 'off';
  input.setAttribute('aria-label', 'Find in this text');
  const option = (name, label, title) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'find-opt find-' + name;
    b.textContent = label;
    b.title = title;
    b.addEventListener('click', () => {
      st.q[name] = !st.q[name];
      findPrefs[name] = st.q[name];
      refreshFind(st, true);
      input.focus();
    });
    return [name, b];
  };
  st.opts = [
    option('caseSensitive', 'Aa', 'Match case'),
    option('wholeWord', 'ab', 'Match whole word'),
    option('regex', '.*', 'Use a regular expression'),
  ];
  const count = document.createElement('span');
  count.className = 'find-count';
  count.setAttribute('aria-live', 'polite');
  bar.append(input, ...st.opts.map(([, b]) => b), count,
    findButton('↑', `Previous match (${keyLabel('Shift+Enter', IS_MAC)})`, () => stepFind(cm, -1)),
    findButton('↓', `Next match (${keyLabel('Enter', IS_MAC)})`, () => stepFind(cm, 1)),
    findButton('×', `Close (${keyLabel('Escape', IS_MAC)})`, () => closeFind(cm)));
  Object.assign(st, { bar, input, count });

  input.addEventListener('input', () => {
    st.q.query = findPrefs.query = input.value;
    refreshFind(st, true);
  });
  bar.addEventListener('keydown', (e) => {
    const k = keyCombo(e, IS_MAC);
    // Enter steps from the box only: on one of the buttons it presses it.
    const dir = { 'Mod+G': 1, F3: 1, 'Mod+Shift+G': -1, 'Shift+F3': -1 }[k]
      || (e.target === input && { Enter: 1, 'Shift+Enter': -1 }[k]);
    if (dir) stepFind(cm, dir);
    else if (k === 'Escape') closeFind(cm);
    else if (k === 'Mod+F') { input.focus(); input.select(); }
    else return;
    e.preventDefault();
  });
  // An edit moves matches; waiting for a pause keeps a burst of typing to one
  // count. A document swapped in, another tab's, is counted at once.
  cm.on('changes', () => {
    if (!st.open) return;
    clearTimeout(st.timer);
    st.timer = setTimeout(() => refreshFind(st, false), 150);
  });
  cm.on('swapDoc', (_, old) => {
    if (!st.open || old === cm.getDoc()) return;
    st.origin = cm.getCursor('from');
    refreshFind(st, false);
  });
  // Typing searches from where the cursor was put, never from where the last
  // keystroke's match happened to land: after `x` has jumped far ahead, a `y`
  // typed in its place still starts from the same line.
  cm.on('cursorActivity', () => {
    if (st.open && !st.moving) st.origin = cm.getCursor('from');
  });
  cm.getWrapperElement().appendChild(bar);
  cm.state.findBar = st;
  return st;
}

/* Counts again and repaints. `jump` is for typing and the option buttons: it
   moves to the first match from where the search started. */
function refreshFind(st, jump) {
  const { cm, q } = st;
  clearTimeout(st.timer);
  st.timer = 0;
  const key = [q.query, q.caseSensitive, q.wholeWord, q.regex].join('\u0000');
  if (key !== st.key) {
    // Only a new pattern repaints: the overlay reads the text as it draws it,
    // so an edit needs no new one.
    st.key = key;
    const pat = findPattern(q.query, q);
    st.re = pat.re;
    st.error = pat.error;
    if (st.overlay) cm.removeOverlay(st.overlay);
    st.overlay = st.re ? findOverlay(st.re, q.wholeWord) : null;
    if (st.overlay) cm.addOverlay(st.overlay);
  }
  st.lines = [];
  cm.getDoc().eachLine((l) => { st.lines.push(l.text); });
  st.found = findMatches(st.lines, st.re, q.wholeWord, FIND_CAP);
  const m = jump && nextMatch(st.lines, st.re, q.wholeWord, st.origin, 1);
  if (m) return gotoMatch(st, m, false);
  const from = cm.getCursor('from'), to = cm.getCursor('to');
  settleFind(st, isMatch(st.lines, st.re, q.wholeWord, from, to) ? { from, to } : null);
}

/* A step moves where the next one, and the next query, start from. */
function gotoMatch(st, m, step) {
  const { cm } = st;
  const from = { line: m.line, ch: m.from }, to = { line: m.line, ch: m.to };
  st.moving = true;
  cm.setSelection(from, to, { scroll: false });
  // A third of the height clear on either side, so the match never lands under
  // the bar or on the bottom line, where it would still have to be looked for.
  cm.scrollIntoView({ from, to }, Math.round(cm.getScrollInfo().clientHeight / 3));
  st.moving = false;
  if (step) st.origin = from;
  settleFind(st, { from, to });
}

/* `cur` is the match the selection is on, or null. It is painted brighter than
   the rest, because the selection alone is a faint blue once the focus is in
   the box. */
function settleFind(st, cur) {
  const { q } = st;
  st.cur = cur;
  st.at = cur ? hitAt(st.found.hits, cur.from, cur.to) : -1;
  if (st.mark) st.mark.clear();
  st.mark = cur ? st.cm.markText(cur.from, cur.to, { className: 'cm-findcur' }) : null;
  st.input.classList.toggle('bad', !!st.error);
  st.input.title = st.error;
  st.count.textContent = findLabel(q.query, st.found, st.at, st.error, !!cur);
  st.count.classList.toggle('none', !!q.query && (!!st.error || !st.found.hits.length));
  for (const [name, b] of st.opts) b.setAttribute('aria-pressed', String(!!q[name]));
}

function showFind(st) {
  if (!st.open) {
    st.open = true;
    st.origin = st.cm.getCursor('from');
    st.bar.classList.remove('hidden');
    st.cm.addKeyMap(st.keys);
    // Room above the first line, as VS Code makes, or a match there would sit
    // under the bar with nowhere to scroll it to.
    st.cm.getWrapperElement().classList.add('find-open');
    st.cm.refresh();
  }
  st.input.value = st.q.query;
  refreshFind(st, false);
}

/* Cmd+F. A selection on one line becomes the query, as in VS Code, unless it
   is the match already selected: that would swap a pattern for the one string
   it happened to match. */
function openFind(cm) {
  const st = findBar(cm);
  const onMatch = st.open && !!st.cur;
  if (!st.open) st.q = { ...findPrefs };
  const sel = cm.getSelection();
  if (sel && !sel.includes('\n') && sel.length <= 200 && !onMatch) {
    st.q.query = findPrefs.query = st.q.regex ? escapeRegExp(sel) : sel;
  }
  showFind(st);
  st.input.focus();
  st.input.select();
}

/* The pattern a card's names are found with (0145): longest first, because an
   alternation keeps the first branch that matches and the whole-word test comes
   after it, so `refund` ahead of `refund_total` would never let the longer one
   be lit. Ties by name, so the pattern is the same on every start.

   The other way round needs help too: the bar retries a rejected match one
   character on, so a shorter name at the same place is never tried, and
   `orders.status_code` would light neither `orders.status` (not a whole word)
   nor the `orders` before it. A name another, shorter name begins therefore
   ends in `(?!\w)`, and the pattern itself falls through to the shorter one
   where the whole-word test would have said no. Every branch that matches at
   one place starts at the same character, so only the right edge differs. `\w`
   is ASCII without the `u` flag: a letter of another script right after is
   still left to the whole-word test, which rejects it, so nothing false is lit.
   Names no other begins stay as they are. */
function namesPattern(names) {
  const sorted = [...names].sort((x, y) => y.length - x.length || (x < y ? -1 : x > y ? 1 : 0));
  const lower = sorted.map((n) => n.toLowerCase());     // the bar runs with case off
  return sorted.map((n, i) => {
    const begun = lower.some((o) => o.length < lower[i].length && lower[i].startsWith(o));
    return escapeRegExp(n) + (begun && isWordChar(n[n.length - 1]) ? '(?!\\w)' : '');
  }).join('|');
}

/* A card's names lit in an editor (0145): this editor's find bar opened on all
   of them as whole words, case aside, with the first one reached and the focus
   in the text, so Escape and Cmd+G reach the bar. Only this bar's own query:
   the options other bars open with are left as they were. A text that holds
   none of the names is just shown. */
function findNames(cm, names) {
  if (!cm || !names || !names.length) return;
  const st = findBar(cm);
  st.q = { query: namesPattern(names), caseSensitive: false, wholeWord: true, regex: true };
  cm.setCursor({ line: 0, ch: 0 });
  st.origin = { line: 0, ch: 0 };
  showFind(st);
  stepFind(cm, 1);
  cm.focus();
}

/* Enter and Shift+Enter in the bar, Cmd+G and F3 in the text. With the bar
   closed it opens on the last query first, and leaves the focus in the text. */
function stepFind(cm, dir) {
  const st = findBar(cm);
  if (!st.open) {
    st.q = { ...findPrefs };
    showFind(st);
  } else if (st.timer) {
    refreshFind(st, false);                  // an edit is still waiting to be counted
  }
  const m = nextMatch(st.lines, st.re, st.q.wholeWord, cm.getCursor(dir > 0 ? 'to' : 'from'), dir);
  if (m) gotoMatch(st, m, true);
}

/* The selection stays on the last match, so Escape leaves the cursor where the
   search brought it, ready to type. */
function closeFind(cm) {
  const st = cm.state.findBar;
  if (!st || !st.open) return;
  st.open = false;
  clearTimeout(st.timer);
  st.timer = 0;
  st.bar.classList.add('hidden');
  cm.getWrapperElement().classList.remove('find-open');
  cm.refresh();
  cm.removeKeyMap(st.keys);
  if (st.overlay) cm.removeOverlay(st.overlay);
  st.overlay = null;
  st.key = '';
  st.lines = [];
  if (st.mark) st.mark.clear();
  st.mark = st.cur = null;
  cm.focus();
}

/* CodeMirror's default keymaps already bind Cmd+F, Cmd+G and Shift+Cmd+G (Ctrl
   elsewhere) to these three names and leave them for the embedder to define.
   Defining them is what reaches every editor here, the diff panes included,
   and only the one with the focus answers. */
CodeMirror.commands.find = (cm) => openFind(cm);
CodeMirror.commands.findNext = (cm) => stepFind(cm, 1);
CodeMirror.commands.findPrev = (cm) => stepFind(cm, -1);
// The same two under the keys Windows and VS Code give them.
CodeMirror.keyMap.default.F3 = 'findNext';
CodeMirror.keyMap.default['Shift-F3'] = 'findPrev';

/* The editor a Cmd+F from outside every editor means: the file on screen, or
   the working-tree side of a diff. */
function activeEditor() {
  const f = S.active && S.open.get(S.active);
  if (!f) return null;
  if (f.kind === 'diff') return f.mv ? f.mv.editor() : f.icm;
  return ownsPane(f) ? null : S.cm;
}

/* Where an element sits, by pane. Everything in the dock belongs to the tab on
   screen, its tab bar included, so Cmd+F after a click on Compiled searches the
   SQL under it. '' is the page itself, with nothing focused. */
function paneOf(el) {
  if (!el || !el.closest || el === document.body) return '';
  if (el.closest('#editor-pane')) return 'editor';
  if (el.closest('#sidebar')) return 'sidebar';
  // The selection's panel holds the canvas and the Catalog beside it.
  if (el.closest('#select-panel')) return el.closest('#catalog') ? 'catalog' : 'lineage';
  if (el.closest('#dock')) return S.dock;
  return 'other';
}

/* Cmd+F wherever CodeMirror has not answered it already. False where there is
   nothing of ours to search, the terminal, and the browser's own find opens
   instead. */
function findInPane(pane) {
  // A panel covers every pane: the browser's own find searches it. The
  // selection's holds the canvas and the Catalog, which keep their own.
  if (S.panel && !panelOpen('select')) return false;
  if (pane === 'catalog') return focusColumnFilter();
  if (pane === 'lineage') return openGraphFind();
  if (pane === 'compiled' || pane === 'run') {
    const cm = S.artifactCm[pane];
    if (!cm || !document.body.contains(cm.getWrapperElement())) return false;
    openFind(cm);
    return true;
  }
  if (pane !== 'editor' && pane !== 'sidebar' && pane !== '') return false;
  const cm = activeEditor();
  if (!cm) return false;
  openFind(cm);
  return true;
}

/* The lineage's find bar (0081), built the first time Cmd+F reaches the
   canvas. The search is Lineage's, which knows where each box is drawn; the
   bar only holds the query and says what came of it. The query is its own
   rather than the editors' (findPrefs): a box is looked for by a name, where
   the editors' last query is as often a piece of SQL. */
function graphFindBar() {
  if (S.graphFind) return S.graphFind;
  const bar = document.createElement('div');
  bar.className = 'findbar hidden';
  bar.setAttribute('role', 'search');
  const input = document.createElement('input');
  input.className = 'find-q';
  input.spellcheck = false;
  input.autocomplete = 'off';
  input.title = `A box on the canvas, by its name. ${keyLabel('Mod+K', IS_MAC)} searches the whole project.`;
  const count = document.createElement('span');
  count.className = 'find-count';
  count.setAttribute('aria-live', 'polite');
  bar.append(input, count,
    findButton('↑', `Previous match (${keyLabel('Shift+Enter', IS_MAC)})`, () => Lineage.findStep(-1)),
    findButton('↓', `Next match (${keyLabel('Enter', IS_MAC)})`, () => Lineage.findStep(1)),
    findButton('×', `Close (${keyLabel('Escape', IS_MAC)})`, closeGraphFind));
  input.addEventListener('input', () => Lineage.find(input.value, true));
  bar.addEventListener('keydown', (e) => {
    const k = keyCombo(e, IS_MAC);
    // Enter steps from the box only: on one of the buttons it presses it.
    const dir = { 'Mod+G': 1, F3: 1, 'Mod+Shift+G': -1, 'Shift+F3': -1 }[k]
      || (e.target === input && { Enter: 1, 'Shift+Enter': -1 }[k]);
    if (dir) Lineage.findStep(dir);
    else if (k === 'Escape') closeGraphFind();
    else if (k === 'Mod+F') { input.focus(); input.select(); }
    else return;
    e.preventDefault();
  });
  $('#lineage-top').append(bar);
  S.graphFind = { bar, input, count, open: false, back: null };
  return S.graphFind;
}

/* Opening paints the last query's matches and leaves the view where it is,
   as an editor's bar does; the folder names move down under the bar. */
function showGraphFind(st) {
  if (st.open) return;
  st.open = true;
  st.bar.classList.remove('hidden');
  Lineage.placeHeads();
  Lineage.find(st.input.value, false);
}

/* Whether the canvas is on screen: the dock's lineage with no panel over it,
   or up in the selection's panel. */
const lineageSeen = () => panelOpen('select') || (S.dock === 'lineage' && !S.panel);

/* Cmd+F over the lineage. False where the canvas is not on screen, and the
   browser's own find opens instead. What had the focus gets it back when the
   bar closes: the selector's box, say, or nothing from the canvas. */
function openGraphFind() {
  if (!lineageSeen()) return false;
  const st = graphFindBar();
  const was = document.activeElement;
  if (!st.bar.contains(was)) st.back = was && was !== document.body ? was : null;
  showGraphFind(st);
  st.input.focus();
  st.input.select();
  return true;
}

/* Cmd+G and F3 from the canvas itself, where a click leaves the focus. With
   the bar closed they open it on its last query, as in an editor; with no
   query yet they are the browser's. */
function stepGraphFind(pane, dir) {
  const st = S.graphFind;
  if (pane !== 'lineage' || !lineageSeen() || !st || !st.input.value) return false;
  showGraphFind(st);
  Lineage.findStep(dir);
  return true;
}

/* What Lineage found, beside the box, in the words an editor's count uses.
   Called on every redraw while the bar is open, so it follows the canvas. */
function paintGraphFind(r) {
  const st = S.graphFind;
  if (!st || !st.open) return;
  const q = st.input.value, column = S.graphMode === 'column';
  st.input.placeholder = column ? 'Find a column' : 'Find a node';
  st.input.setAttribute('aria-label', column ? 'Find a column on the canvas' : 'Find a node on the canvas');
  st.count.textContent = findLabel(q, { hits: r.hits, capped: false }, r.at, '', false);
  st.count.classList.toggle('none', !!q && !r.hits.length);
}

/* The view stays on the last match, and the query in the box for next time.
   The focus goes back where it was before the bar took it. */
function closeGraphFind() {
  const st = S.graphFind;
  if (!st || !st.open) return;
  const inBar = st.bar.contains(document.activeElement);
  st.open = false;
  st.bar.classList.add('hidden');
  Lineage.findEnd();
  Lineage.placeHeads();
  if (!inBar) return;
  const back = st.back;
  st.back = null;
  // Still on screen: a chip on the canvas is SVG, which has no offsetParent.
  if (back && back.isConnected && back.getClientRects().length) back.focus();
  else document.activeElement.blur();
}

/* Whether an Escape nothing else has taken closes the lineage's find bar:
   from the canvas, where a click on a box leaves the focus, with the
   lineage on screen and no dialog over it. In the bar, its own keys have
   closed it already. */
function escapesGraphFind(e) {
  const st = S.graphFind;
  if (!st || !st.open || e.defaultPrevented || !lineageSeen()) return false;
  if (isTyping(e.target) || !$('#modal').classList.contains('hidden')) return false;
  return (paneOf(e.target) || S.lastPane) === 'lineage';
}

const base = (path) => path.split('/').pop();
const fileName = (path) => path.split(/[\\/]/).pop();
const dirOf = (path) => {
  const d = path.slice(0, path.lastIndexOf('/'));
  return d.length > 36 ? '\u2026' + d.slice(-35) : d;
};

/* `preview` opens the file in the single reusable tab instead of stacking a new
   one, the way a single click does in VS Code. Editing it, or opening it again
   with preview off, pins it. */
async function openFile(path, { focusLineage = true, preview = false } = {}) {
  closeHoverCard();
  if (S.open.has(path)) {
    if (!preview && S.preview === path) S.preview = null;
    return activate(path, focusLineage);
  }
  let body;
  try { body = await api.get('/api/file?path=' + encodeURIComponent(path)); }
  catch (e) { return toast(`cannot open ${path}: ${e.message}`, 'err'); }

  const doc = CodeMirror.Doc(body.content, modeFor(path));
  let slot = S.order.length;
  const stale = S.preview && S.open.has(S.preview) && !S.open.get(S.preview).dirty;
  if (preview && stale) {
    slot = S.order.indexOf(S.preview);
    S.open.delete(S.preview);
    S.order.splice(slot, 1);
  }
  S.open.set(path, { doc, dirty: false, truncated: body.truncated, stamp: body.stamp, disk: '' });
  S.order.splice(slot, 0, path);
  if (preview) S.preview = path;
  markLinks(doc, path);
  activate(path, focusLineage);
}

/* Every kind of link a file's text carries, scanned again whenever the text
   changes: on opening, after typing, and after a reload from disk. */
function markLinks(doc, path) {
  markRefs(doc, path);
  markVars(doc);
  markMacros(doc, path);
  markProjectDirs(doc, path);
  markUnusedPaths(doc, path);
}

/* A diff tab holds no CodeMirror Doc: it owns a MergeView of HEAD against the
   working tree. Read-only on purpose, the file itself is one click away. */
async function openDiff(path) {
  const key = 'diff:' + path;
  if (!S.open.has(key)) {
    let view;
    try { view = await api.get('/api/git/diff?path=' + encodeURIComponent(path)); }
    catch (e) { return toast('diff: ' + e.message, 'err'); }
    S.open.set(key, { kind: 'diff', path, view, dirty: false, host: null, mv: null, icm: null, pane: null, layout: '' });
    S.order.push(key);
  }
  activate(key);
}

/* What the head of a diff says of the two sides it compares. */
function diffStateText(view) {
  const said = view.before_missing ? 'a new file, nothing in HEAD'
    : view.after_missing ? 'deleted from your working tree' : 'your working tree against HEAD';
  // A file changed only in its line endings is listed with no line marked: the head says why.
  const here = lineEnding(view.after), there = lineEnding(view.before);
  const ends = !view.before_missing && !view.after_missing && here && there && here !== there
    ? ` · line endings differ (${here} here, ${there} in HEAD)` : '';
  return said + ends + (view.truncated ? ' · truncated' : '');
}

/* How a text ends its lines: CRLF when any does, else LF, '' for a text of one
   line, which has no ending to compare. */
function lineEnding(text) {
  if (!text || !/[\r\n]/.test(text)) return '';
  return /\r\n/.test(text) ? 'CRLF' : 'LF';
}

/* The lines of both sides in order, for the inline layout: HEAD's lines that
   are gone ('del'), the working tree's that are new ('add'), and the ones both
   hold ('same'), each with its number in HEAD (`a`) and in the working tree
   (`b`), null on the side that has no such line. Built on diff_match_patch in
   line mode, which the side by side view uses too, so both layouts agree on
   what changed. A final newline ends its line and starts no other (0165). */
function inlineDiffLines(before, after) {
  // A line ends however it ends, and the CR of a CRLF is no part of it: under
  // core.autocrlf the working file is CRLF against an LF blob, and only the lines
  // that really changed are listed, as git and the side by side view do (0165).
  const split = (text) => {
    if (!text) return [];
    const parts = text.split(/\r\n|\r|\n/);
    if (parts[parts.length - 1] === '') parts.pop();
    return parts;
  };
  const keyOf = (l) => l + '\n';
  const dmp = new diff_match_patch();
  const packed = dmp.diff_linesToChars_(split(before).map(keyOf).join(''), split(after).map(keyOf).join(''));
  const diffs = dmp.diff_main(packed.chars1, packed.chars2, false);
  dmp.diff_charsToLines_(diffs, packed.lineArray);
  const out = [];
  // The operation is -1 for a deletion, 0 for text both hold, 1 for an insertion.
  for (const d of diffs) {
    // A Diff of the library is read by index: it is not iterable.
    const kind = d[0] === 0 ? 'same' : d[0] < 0 ? 'del' : 'add';
    // What the library hands back is made of the lines above, so it splits on LF alone.
    const lines = d[1].split('\n');
    lines.pop();
    for (const text of lines) out.push({ text, kind, a: null, b: null });
  }
  // A run of added or removed lines that begins with the line right after it
  // can be drawn two ways, the equal line first or last. git draws it with the
  // equal lines first, as the side by side view does: the run slides down.
  for (let i = 0; i < out.length; i++) {
    const kind = out[i].kind;
    if (kind === 'same') continue;
    let j = i;
    while (j + 1 < out.length && out[j + 1].kind === kind) j++;
    // The run is i..j; it slides while its first line equals the equal line after it.
    while (j + 1 < out.length && out[j + 1].kind === 'same' && out[i].text === out[j + 1].text) {
      out[i].kind = 'same';
      out[j + 1].kind = kind;
      i++;
      j++;
    }
    i = j;
  }
  let a = 1, b = 1;
  for (const l of out) {
    if (l.kind !== 'add') l.a = a++;
    if (l.kind !== 'del') l.b = b++;
  }
  return out;
}

/* The stretches of unchanged lines the inline layout folds: those more than
   `margin` lines from a change, kept only when longer than `margin`, as the
   side by side view's collapseIdentical does. `to` is exclusive. */
function inlineFolds(lines, margin) {
  const keep = lines.map(() => false);
  lines.forEach((l, i) => {
    if (l.kind === 'same') return;
    for (let k = Math.max(0, i - margin); k <= Math.min(lines.length - 1, i + margin); k++) keep[k] = true;
  });
  const folds = [];
  for (let i = 0; i < lines.length; i++) {
    if (keep[i]) continue;
    let j = i;
    while (j + 1 < lines.length && !keep[j + 1]) j++;
    if (j - i + 1 > margin) folds.push({ from: i, to: j + 1 });
    i = j;
  }
  return folds;
}

/* The runs of added lines and of removed lines, for the overview ruler. */
function inlineRuns(lines) {
  const runs = [];
  lines.forEach((l, i) => {
    if (l.kind === 'same') return;
    const last = runs[runs.length - 1];
    if (last && last.kind === l.kind && last.to === i) last.to = i + 1;
    else runs.push({ kind: l.kind, from: i, to: i + 1 });
  });
  return runs;
}

/* Where the first line in view lands when the layout changes: a line of the
   working tree (0-based) to its place among the inline lines, and back. A
   removed line has no number in the working tree, so it takes the next one's,
   and the way back takes the removed lines that precede a line with it. */
function inlineIndexFor(lines, workingLine) {
  let at = lines.findIndex((l) => l.b != null && l.b >= workingLine + 1);
  if (at < 0) {
    // Past the end: the last line the working tree has; a deleted file has none.
    at = lines.length - 1;
    while (at > 0 && lines[at].b == null) at--;
    if (at < 0 || lines[at].b == null) return 0;
    return at;
  }
  // The lines removed just before it belong to it: they stay in view with it.
  while (at > 0 && lines[at - 1].kind === 'del') at--;
  return at;
}

function workingLineFor(lines, index) {
  for (let i = Math.min(index, lines.length - 1); i < lines.length; i++) if (i >= 0 && lines[i].b != null) return lines[i].b - 1;
  for (let i = Math.min(index, lines.length - 1); i >= 0; i--) if (lines[i].b != null) return lines[i].b - 1;
  return 0;
}

/* The merge addon paints the changed backgrounds; these are the parts that make
   a diff readable at a glance: a +/- per line, and a ruler showing where the
   changes sit in a file too long to scroll through. */
/* Position of one chunk on the overview ruler, clamped so a mark can never
   escape the bar on a short file. */
function rulerMark(chunk, total) {
  const lines = Math.max(1, total);
  const span = Math.max(1, chunk.editTo - chunk.editFrom);
  const top = Math.min(99, Math.max(0, (100 * chunk.editFrom) / lines));
  return {
    kind: chunk.editTo > chunk.editFrom ? 'add' : 'del',
    top,
    height: Math.max(0.5, Math.min(100 - top, (100 * span) / lines)),
  };
}

function decorateDiff(mv, pane) {
  // leftChunks() computes the diff first, unlike reading mv.left.chunks raw.
  const chunks = (mv.leftChunks && mv.leftChunks()) || [];
  if (!chunks.length) return;
  const mark = (cm, line, sign) => {
    const el = document.createElement('div');
    el.className = 'diff-sign ' + (sign === '+' ? 'add' : 'del');
    el.textContent = sign;
    cm.setGutterMarker(line, 'diff-mark', el);
  };
  const leftCm = mv.leftOriginal(), rightCm = mv.editor();
  for (const c of chunks) {
    for (let l = c.origFrom; l < c.origTo && l < leftCm.lineCount(); l++) mark(leftCm, l, '−');
    for (let l = c.editFrom; l < c.editTo && l < rightCm.lineCount(); l++) mark(rightCm, l, '+');
  }

  const total = Math.max(1, rightCm.lineCount());
  drawRuler(pane, chunks.map((c) => {
    const g = rulerMark(c, total);
    g.title = g.kind === 'add' ? `lines ${c.editFrom + 1}-${c.editTo}` : `removed at line ${c.editFrom + 1}`;
    g.go = () => rightCm.scrollIntoView({ line: c.editFrom, ch: 0 }, 120);
    return g;
  }));
}

/* The overview ruler of a diff, one mark per change, clickable; both layouts
   hand it marks from rulerMark with a title and where a click goes. */
function drawRuler(pane, marks) {
  if (!marks.length) return;
  const ruler = document.createElement('div');
  ruler.className = 'diff-ruler';
  for (const g of marks) {
    const m = document.createElement('div');
    m.className = g.kind;
    m.style.top = g.top + '%';
    m.style.height = g.height + '%';
    m.title = g.title;
    m.addEventListener('click', g.go);
    ruler.appendChild(m);
  }
  pane.appendChild(ruler);
}

/* The collapsed stretches say how many lines they hide: the stylesheet draws
   the words from data-n. The merge addon makes the widgets, one per pane. */
function labelCollapsed(cm) {
  for (const m of cm.getAllMarks()) {
    const w = m.replacedWith;
    if (!m.collapsed || !w || !w.classList || !w.classList.contains('CodeMirror-merge-collapsed-widget')) continue;
    const at = m.find();
    if (!at) continue;
    const n = at.to.line - at.from.line + 1;
    w.dataset.n = String(n);
    w.title = `Show the ${n} unchanged lines`;
  }
}

/* The layout switch of a diff's head: two radios, arrows move and pick. */
function diffLayoutSwitch(key) {
  const seg = document.createElement('span');
  seg.className = 'seg2';
  seg.setAttribute('role', 'radiogroup');
  seg.setAttribute('aria-label', 'Diff layout');
  const pick = (layout) => {
    if (S.diffLayout !== layout) {
      S.diffLayout = layout;
      if (S.open.has(key)) mountDiff(key);
    }
  };
  const buttons = [['sbs', 'Side by side'], ['inline', 'Inline']].map(([layout, label]) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.setAttribute('role', 'radio');
    b.dataset.layout = layout;
    b.textContent = label;
    b.addEventListener('click', () => pick(layout));
    b.addEventListener('keydown', (e) => {
      if (!/^Arrow(Left|Right|Up|Down)$/.test(e.key)) return;
      e.preventDefault();
      const next = buttons[1 - buttons.indexOf(b)];
      pick(next.dataset.layout);
      next.focus();
    });
    return b;
  });
  seg.append(...buttons);
  return seg;
}

function syncDiffLayoutSwitch(f) {
  for (const b of f.host.querySelectorAll('.seg2 button')) {
    const on = b.dataset.layout === S.diffLayout;
    b.setAttribute('aria-checked', on ? 'true' : 'false');
    b.tabIndex = on ? 0 : -1;
  }
}

function mountDiff(key) {
  const f = S.open.get(key);
  const host = $('#diff-host');
  [...host.children].forEach((c) => c.classList.add('hidden'));
  if (!f.host) {
    f.host = document.createElement('div');
    f.host.className = 'diffpane';
    host.appendChild(f.host);

    // One row: the file, where it is, what is compared, then the controls.
    const head = document.createElement('div');
    head.className = 'diff-head';
    const title = document.createElement('div');
    title.className = 'diff-title';
    const icon = fileIcon(f.path, fileMark(f.path));
    title.append(icon);
    // A model's file in a folder the tree has not opened: its mark is asked once, by its folder.
    askMarks([f.path]).then((gained) => {
      if (gained && icon.isConnected) icon.replaceWith(fileIcon(f.path, fileMark(f.path)));
    });
    const nm = document.createElement('b');
    nm.textContent = base(f.path);
    title.append(nm);
    const folder = f.path.includes('/') ? dirOf(f.path) : '';
    if (folder) title.append(Object.assign(document.createElement('span'), { className: 'diff-dir', textContent: folder, title: folder }));
    title.append(Object.assign(document.createElement('span'), { className: 'diff-state', textContent: diffStateText(f.view) }));
    const lock = document.createElement('span');
    lock.className = 'diff-lock';
    lock.textContent = 'read only';
    lock.title = 'Open the file itself to edit it';
    title.append(lock, Object.assign(document.createElement('div'), { className: 'grow' }));
    if (!f.view.binary) title.append(diffLayoutSwitch(key));
    const open = document.createElement('button');
    open.className = 'btn';
    open.textContent = 'Open the file';
    open.addEventListener('click', () => openFile(f.path, { preview: true }));
    const close = document.createElement('button');
    close.className = 'icon';
    close.textContent = '×';
    close.title = 'Close this diff';
    close.addEventListener('click', () => closeFile(key));
    title.append(open, close);
    head.append(title);
    f.host.appendChild(head);

    if (f.view.binary) {
      f.host.append(Object.assign(document.createElement('div'), {
        className: 'compiled-empty', textContent: 'Binary file, nothing to show side by side.' }));
      return;
    }
  }
  f.host.classList.remove('hidden');
  if (f.view.binary) return;
  syncDiffLayoutSwitch(f);
  if (f.layout !== S.diffLayout) fillDiff(f);
  setTimeout(() => {
    if (!f.mv && !f.icm) return;
    if (f.mv) {
      f.mv.editor().refresh();
      if (f.mv.leftOriginal()) f.mv.leftOriginal().refresh();
    } else f.icm.refresh();
    if (f.scrollTo != null) {
      const cm = f.mv ? f.mv.editor() : f.icm;
      cm.scrollTo(null, cm.heightAtLine(Math.min(f.scrollTo, cm.lineCount() - 1), 'local'));
      f.scrollTo = null;
    }
  }, 0);
}

/* The body of a diff in the layout picked, in place of the one it had: the
   first line in view stays in view. The choice is the page's, one for every
   diff tab, so a tab opened before it is rebuilt when it is shown (0165). */
function fillDiff(f) {
  let line = null;
  if (f.mv || f.icm) {
    const cm = f.mv ? f.mv.editor() : f.icm;
    const first = cm.lineAtHeight(cm.getScrollInfo().top, 'local');
    const lines = f.inlineLines || (f.inlineLines = inlineDiffLines(f.view.before, f.view.after));
    line = f.mv ? inlineIndexFor(lines, first) : workingLineFor(lines, first);
  }
  if (f.ro) f.ro.disconnect();
  if (f.pane) f.pane.remove();
  f.mv = f.icm = f.ro = null;
  const pane = document.createElement('div');
  pane.className = 'mergepane';
  // Markdown reads the same here as in its own tab: bold headings, quiet marks (0165).
  pane.classList.toggle('md-doc', modeFor(f.path) === 'text/x-markdown');
  f.host.appendChild(pane);
  f.pane = pane;
  f.layout = S.diffLayout;
  f.scrollTo = line;
  if (S.diffLayout === 'inline') {
    f.inlineLines = f.inlineLines || inlineDiffLines(f.view.before, f.view.after);
    f.icm = mountInline(f, pane);
  } else {
    f.mv = CodeMirror.MergeView(pane, {
      // CodeMirror shows a CRLF file with plain line breaks: the addon is given the text it shows,
      // or it would compare the CRs and mark every line of an autocrlf file.
      value: f.view.after.replace(/\r\n?/g, '\n'),
      origLeft: f.view.before.replace(/\r\n?/g, '\n'),
      lineNumbers: true,
      lineWrapping: true,
      // Forwarded to both panes by the addon, so each gets a +/- column.
      gutters: ['CodeMirror-linenumbers', 'diff-mark'],
      mode: modeFor(f.path),
      highlightDifferences: true,
      // The changed lines are tinted in the number gutters too.
      chunkClassLocation: ['background', 'gutter'],
      connect: 'align',
      collapseIdentical: 12,
      revertButtons: false,
      readOnly: true,
    });
    labelCollapsed(f.mv.editor());
    labelCollapsed(f.mv.leftOriginal());
    decorateDiff(f.mv, pane);
  }
  watchDiffWidth(f, pane);
}

/* Wrapped lines change height with the pane's width, which the addon aligns
   once: when the width moves, both sides are laid out and aligned again. */
function watchDiffWidth(f, pane) {
  if (typeof ResizeObserver !== 'function') return;
  let width = 0, timer = 0;
  f.ro = new ResizeObserver(() => {
    const w = pane.clientWidth;
    // Hidden, or only its height moved.
    if (!w || w === width) return;
    const first = !width;
    width = w;
    if (first) return;
    clearTimeout(timer);
    timer = setTimeout(() => realignDiff(f), 80);
  });
  f.ro.observe(pane);
}

function realignDiff(f) {
  if (f.mv) {
    f.mv.editor().refresh();
    f.mv.leftOriginal().refresh();
    // The addon aligns only a view it knows is out of line.
    if (f.mv.left && f.mv.left.forceUpdate) {
      f.mv.left.dealigned = true;
      f.mv.left.forceUpdate();
    }
  } else if (f.icm) f.icm.refresh();
}

/* The inline layout: one read-only editor holding the lines of both sides in
   order, two number gutters (HEAD's and the working tree's), the sign, the
   changed rows tinted as in side by side, and the stretches far from a change
   folded behind the same words. */
function mountInline(f, pane) {
  const lines = f.inlineLines;
  const cm = CodeMirror(pane, {
    value: lines.map((l) => l.text).join('\n'),
    mode: modeFor(f.path),
    lineWrapping: true,
    readOnly: true,
    gutters: ['diff-a', 'diff-b', 'diff-mark'],
  });
  const cell = (className, text) => Object.assign(document.createElement('div'), { className, textContent: text });
  cm.operation(() => {
    lines.forEach((l, i) => {
      if (l.a != null) cm.setGutterMarker(i, 'diff-a', cell('diff-n', String(l.a)));
      if (l.b != null) cm.setGutterMarker(i, 'diff-b', cell('diff-n', String(l.b)));
      if (l.kind === 'same') return;
      cm.setGutterMarker(i, 'diff-mark', cell('diff-sign ' + l.kind, l.kind === 'add' ? '+' : '−'));
      cm.addLineClass(i, 'background', 'diff-line-' + l.kind);
      cm.addLineClass(i, 'gutter', 'diff-line-' + l.kind);
    });
    for (const fold of inlineFolds(lines, 12)) collapseInline(cm, fold.from, fold.to);
  });
  const total = Math.max(1, lines.length);
  drawRuler(pane, inlineRuns(lines).map((run) => {
    const g = rulerMark({ editFrom: run.from, editTo: run.to }, total);
    g.kind = run.kind;
    g.title = run.kind === 'add' ? `lines ${lines[run.from].b}-${lines[run.to - 1].b}`
      : `removed: lines ${lines[run.from].a}-${lines[run.to - 1].a} of HEAD`;
    g.go = () => cm.scrollIntoView({ line: run.from, ch: 0 }, 120);
    return g;
  }));
  return cm;
}

/* The same widget the merge addon puts on a stretch it collapses, so one
   stylesheet draws both; a click on it shows the lines. */
function collapseInline(cm, from, to) {
  const widget = document.createElement('span');
  widget.className = 'CodeMirror-merge-collapsed-widget';
  widget.dataset.n = String(to - from);
  widget.title = `Show the ${to - from} unchanged lines`;
  cm.addLineClass(from, 'wrap', 'CodeMirror-merge-collapsed-line');
  const mark = cm.markText({ line: from, ch: 0 }, { line: to - 1, ch: cm.getLine(to - 1).length },
    { replacedWith: widget, inclusiveLeft: true, inclusiveRight: true, clearOnEnter: true });
  mark.on('clear', () => cm.removeLineClass(from, 'wrap', 'CodeMirror-merge-collapsed-line'));
  widget.addEventListener('click', () => mark.clear());
}

/* A tab that owns a pane of its own in #diff-host rather than a CodeMirror
   Doc: a diff, or two collin versions compared. Neither has a cursor or a file
   to save. */
function ownsPane(f) {
  return !!f && (f.kind === 'diff' || collinTab(f));
}

/* A comparison of collin versions: a tab no file stands behind. collin's
   report is a section of the reports instead (0064). */
function collinTab(f) {
  return !!f && f.kind === 'compare';
}

/* Showing a tab is asking for the editor, so a panel over it rolls up: a
   file opened from the sidebar, the palette or a link lands here. `keepPanel`
   is for a tab shown because another was closed, from the sidebar while the
   panel stays down. */
function activate(path, focusLineage = true, keepPanel = false) {
  if (!keepPanel) closePanel();
  S.active = path;
  markGrepOpen();
  markGitCurrent();
  const f = S.open.get(path);
  $('#editor-empty').classList.add('hidden');
  if (ownsPane(f)) {
    $('#editor-host').style.display = 'none';
    $('#diff-host').classList.remove('hidden');
    if (f.kind === 'diff') mountDiff(path);
    else mountCollinTab(path);
  } else {
    $('#diff-host').classList.add('hidden');
    $('#editor-host').style.display = '';
    S.cm.swapDoc(f.doc);
    // A Markdown file reads as it does in its diff (0165).
    S.cm.getWrapperElement().classList.toggle('md-doc', modeFor(path) === 'text/x-markdown');
    paintCurLine();
    paintWarnGutter();
    S.cm.refresh();
  }
  renderTabs();
  updateStatus();
  refreshOutline();
  renderCrumbs();
  const inProject = projectPath(path);
  markTreeSelection(inProject);
  if (focusLineage && inProject) syncNode(inProject);
  // A tab clicked after a pull in the terminal is the moment it is looked at,
  // sooner than the next poll. A file that could not be read is tried again,
  // as when Excel lets go of a seed.
  if (f && !f.dirty && f.disk === 'changed') f.diskSeen = '';
  refreshOpenFiles();
}

/* The project path a tab points at, which is not its key: a diff is keyed
   `diff:<path>`, and a profile is not in the project at all, so no tree row and
   no node answer to it. */
function projectPath(key) {
  const f = S.open.get(key);
  if (!f) return '';
  return f.kind === 'profile' || collinTab(f) ? '' : f.kind === 'diff' ? f.path : key;
}

/* Takes one tab down without asking anything and without drawing: a diff owns
   a MergeView element outside the editor host, which has to go with it. The
   three close commands all come through here, so none of them can forget it. */
function dropTab(key) {
  const f = S.open.get(key);
  if (!f) return;
  if (f.ro) f.ro.disconnect();
  if (f.host) f.host.remove();
  S.open.delete(key);
  S.order = S.order.filter((p) => p !== key);
  if (S.preview === key) S.preview = null;
}

/* Where the editor lands once tabs have gone, and the one redraw a close does,
   however many tabs it took. */
function settleTabs() {
  if (!S.active || !S.open.has(S.active)) {
    S.active = S.order[S.order.length - 1] || null;
    if (S.active) activate(S.active, true, true);
    else {
      $('#editor-host').style.display = 'none';
      $('#diff-host').classList.add('hidden');
      $('#editor-empty').classList.remove('hidden');
      updateStatus();
      renderCrumbs();
      markGrepOpen();
      markGitCurrent();
    }
  }
  renderTabs();
}

/* Whether closing the tab would lose text: unsaved edits, or a file deleted
   on disk whose tab holds the last copy of it. */
function holdsWork(f) {
  return !!f && (f.dirty || f.disk === 'gone');
}

function closeFile(path) {
  const f = S.open.get(path);
  if (holdsWork(f) && !confirm(f.dirty ? `${path} has unsaved changes. Close anyway?`
    : `${path} was deleted on disk, and this tab holds the last copy of it. Close anyway?`)) return;
  dropTab(path);
  settleTabs();
}

/* One confirmation for the lot, naming the files that would lose work, rather
   than one dialog per tab. */
function closeMany(keys, what) {
  if (!keys.length) return;
  const dirty = keys.filter((p) => holdsWork(S.open.get(p)));
  if (dirty.length && !confirm(
    `${dirty.length} file${dirty.length > 1 ? 's have' : ' has'} unsaved changes.\n\n`
    + `${dirty.join('\n')}\n\n${what} The files themselves are not touched.`)) return;
  for (const key of keys) dropTab(key);
  settleTabs();
}

/* True once written, false when it failed, and null when the user chose to
   leave the disk as it is: Save all counts that apart, and Mark resolved does
   not stage a file that was not written. */
async function saveFile(path) {
  const f = S.open.get(path);
  if (ownsPane(f)) return true;
  // A second save while the first is out waits for it, then saves what was
  // typed since, if anything. Sent at once, it would carry the stamp the first
  // is replacing, and be refused as a change on disk.
  if (f && f.saving) { await f.saving; return saveFile(path); }
  // A struck-through tab is saved too: it writes the deleted file back.
  if (!f || (!f.dirty && f.disk !== 'gone')) return true;
  if (f.kind === 'profile') return saveProfile(path, f);
  // The poll leaves a tab alone while it saves: the stamp it would compare is
  // about to change.
  f.saving = writeTab(path, f);
  try { return await f.saving; } finally { f.saving = null; }
}

async function writeTab(path, f) {
  const content = f.doc.getValue();
  // What is typed while the request is out stays unsaved, and the tab edited:
  // a reload would otherwise take a tab marked clean for one with nothing to
  // lose.
  const gen = f.doc.changeGeneration(true);
  const put = (stamp) => api.send('/api/file', 'PUT', { path, content, stamp });
  try {
    let saved;
    try { saved = await put(f.stamp); }
    catch (e) {
      // The disk moved since the tab read it. Saving would put back, unseen,
      // whatever a pull just brought, so it asks, and on yes sends the stamp
      // it showed, empty for a file that was gone: a second change meanwhile
      // is refused too (0067).
      if (!e.changed) throw e;
      if (!confirm(diskMovedQuestion(path, e.stamp))) return null;
      saved = await put(e.stamp === null ? '' : e.stamp);
    }
    f.dirty = !f.doc.isClean(gen);
    f.stamp = saved.stamp;
    f.disk = '';
    f.diskSeen = '';
    if (feedsPayloads(path)) dropNodeCache();
    return true;
  } catch (e) {
    toast(`save failed for ${base(path)}: ${e.message}`, 'err');
    return false;
  }
}

/* Resolved locations and var values are derived from these files, so a cached
   payload would keep showing what they used to say once they change. */
function feedsPayloads(path) {
  return base(path).startsWith('.env') || base(path) === 'dbt_project.yml';
}

function diskMovedQuestion(path, stamp) {
  const keep = 'Cancel leaves the file as it is, and your edits in the tab, unsaved.';
  return stamp === null
    ? `${path} was deleted on disk since it was opened here.\n\nOK writes it back with your version. ${keep}`
    : `${path} changed on disk since it was opened here, by a pull, a checkout or another program.\n\n`
      + `OK writes your version over it. ${keep}`;
}

/* The one stretch of `next` that differs from `cur`, as the offsets of a
   single replace: what both begin and end with stays where it is, and with it
   a cursor, the scroll and the marks of the lines nobody changed. */
function changedSpan(cur, next) {
  const most = Math.min(cur.length, next.length);
  let head = 0;
  while (head < most && cur.charCodeAt(head) === next.charCodeAt(head)) head++;
  let tail = 0;
  while (tail < most - head && cur.charCodeAt(cur.length - 1 - tail) === next.charCodeAt(next.length - 1 - tail)) tail++;
  return { from: head, to: cur.length - tail, text: next.slice(head, next.length - tail) };
}

/* Follows the files open in tabs when something else rewrites them: a pull,
   a checkout, dbt or another editor. A tab with no unsaved edit takes the new
   text in place. One with edits keeps them, and says the disk moved, which its
   save then asks about rather than writing over it (0067). */
async function refreshOpenFiles() {
  // One look at a time, reloads included, or two could read one file and
  // land out of order. One asked meanwhile, after a pull from the panel
  // say, runs once this one is done rather than being dropped.
  if (S.stampsAsked) { S.stampsAgain = true; return; }
  S.stampsAsked = true;
  try {
    do { S.stampsAgain = false; await followDisk(); } while (S.stampsAgain);
  } finally { S.stampsAsked = false; }
}

async function followDisk() {
  const paths = S.order.filter((p) => S.open.get(p).stamp !== undefined);
  if (!paths.length) return;
  let stamps;
  try { stamps = await api.send('/api/file/stamps', 'POST', { paths }); }
  catch { return; }
  let repaint = false;
  for (const path of paths) {
    const f = S.open.get(path);
    // Closed or being saved while the answer was on its way.
    if (!f || f.saving || !(path in stamps)) continue;
    const now = stamps[path];
    if (now === f.stamp) {
      if (f.disk) { f.disk = ''; repaint = true; }
      continue;
    }
    // A deleted file leaves its tab as it was, text and all, since it may
    // be all that is left of it.
    if (now === null) {
      if (f.disk !== 'gone') { f.disk = 'gone'; repaint = true; }
      continue;
    }
    // Already said for this version: a tab with edits keeps them, and a file
    // that could not be read is not read again every poll.
    if (f.diskSeen === now) continue;
    if (f.dirty) {
      f.disk = 'changed';
      f.diskSeen = now;
      repaint = true;
      toast(`${base(path)} changed on disk: your unsaved edits are kept, and saving asks first`, 'warn');
      continue;
    }
    if (await reloadFromDisk(path, f, now)) repaint = true;
  }
  if (repaint) renderTabs();
}

/* True when the tab needs repainting. `now` is the stamp the poll saw, kept
   when the file cannot be read, so it is not read again until it changes. */
async function reloadFromDisk(path, f, now) {
  const seen = f.stamp;
  let body;
  try { body = await api.get('/api/file?path=' + encodeURIComponent(path)); }
  catch (e) {
    if (S.open.get(path) !== f || f.stamp !== seen) return false;
    // Turned binary, or held by another program on Windows: the tab keeps
    // its text and says the disk moved on without it.
    f.disk = 'changed';
    f.diskSeen = now;
    toast(`${base(path)} changed on disk and cannot be read again here: ${e.message}`, 'warn');
    return true;
  }
  // Edited, saved or closed during the read: the user's text wins, and a save
  // made and done meanwhile has moved the stamp.
  if (S.open.get(path) !== f || f.dirty || f.saving || f.stamp !== seen) return false;
  const next = editorText(body.content);
  const cur = f.doc.getValue();
  if (next !== cur) {
    const span = changedSpan(cur, next);
    f.doc.replaceRange(span.text, f.doc.posFromIndex(span.from), f.doc.posFromIndex(span.to), 'disk');
    // Undo would take the pull back out, and the next save, carrying the
    // pull's stamp, would write the old text over it without asking.
    f.doc.clearHistory();
    markLinks(f.doc, path);
    if (path === S.active) { refreshOutline(); renderCrumbs(); }
    if (feedsPayloads(path)) dropNodeCache();
  }
  f.stamp = body.stamp;
  f.truncated = body.truncated;
  f.disk = '';
  f.diskSeen = '';
  return true;
}

async function save() {
  if (!S.active) return;
  const ok = await saveFile(S.active);
  renderTabs();
  // The status bar carries the modified marker too, and it was keeping it.
  updateStatus();
  refreshGit();
  if (ok) toast('saved ' + base(S.active), 'ok');
}

async function saveAll() {
  const dirty = S.order.filter((p) => S.open.get(p).dirty);
  if (!dirty.length) return toast('nothing to save');
  let done = 0, kept = 0;
  for (const path of dirty) {
    const ok = await saveFile(path);
    if (ok) done++;
    else if (ok === null) kept++;
  }
  renderTabs();
  updateStatus();
  refreshGit();
  // A file left as the disk has it was the user's answer, not a failure.
  toast(`saved ${done} of ${dirty.length} file${dirty.length > 1 ? 's' : ''}`
    + (kept ? `, ${kept} left unsaved as you asked` : ''), done + kept === dirty.length ? 'ok' : 'err');
}

function closeAll() {
  closeMany([...S.order], 'Close every tab anyway?');
}

/* Which tabs a close command takes, in the order they would go. Pure, so the
   edges are checked rather than argued about: the kept tab, the last tab, a
   bar with one tab in it. */
function closeTargets(what, keep, order, open) {
  if (what === 'saved') return order.filter((p) => !(open.get(p) || {}).dirty);
  // A tab closed while its menu was open: indexOf would be -1 and `right`
  // would then slice from 0 and take the whole bar.
  const at = order.indexOf(keep);
  if (at < 0) return [];
  if (what === 'others') return order.filter((p) => p !== keep);
  if (what === 'right') return order.slice(at + 1);
  return [keep];
}

function renderTabs() {
  const bar = $('#tabbar');
  bar.textContent = '';
  for (const path of S.order) {
    const f = S.open.get(path);
    const t = document.createElement('div');
    t.dataset.key = path;
    t.className = 'ftab' + (path === S.active ? ' active' : '') + (f.dirty ? ' dirty' : '') + (f.disk ? ' disk-' + f.disk : '');
    const name = document.createElement('span');
    name.textContent = f.kind === 'diff' ? base(f.path) + '  ↔' : f.kind === 'profile' || collinTab(f) ? fileName(f.path) : base(path);
    name.title = f.kind === 'diff' ? f.path + '  (HEAD against the working tree)'
      : f.kind === 'profile' ? f.path + '  (the dbt profile, outside the project)'
      : f.kind === 'compare' ? 'What two collin versions read, from the runs kept in target/collin/'
      : path + diskNote(f);
    const x = document.createElement('span');
    x.className = 'x';
    if (!f.dirty) x.textContent = '×';
    // The pencil of unsaved edits is a drawing, so the words are here; the tab is
    // built again whenever dirty changes, as the Open editors row is.
    x.title = f.dirty ? 'Close, losing unsaved changes' : 'Close';
    x.addEventListener('click', (e) => { e.stopPropagation(); closeFile(path); });
    t.append(name, x);
    if (path === S.preview) t.classList.add('preview');
    t.addEventListener('click', () => activate(path));
    t.addEventListener('dblclick', () => { if (S.preview === path) { S.preview = null; renderTabs(); } });
    t.addEventListener('mousedown', (e) => { if (e.button === 1) { e.preventDefault(); closeFile(path); } });
    bar.appendChild(t);
    // The bar scrolls, so a tab reached by Cmd+K or from the sidebar list can
    // sit off screen. `nearest` so the page itself never moves, and no focus()
    // here: the cursor belongs to the editor.
    if (path === S.active) t.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  }
  renderOpenEditors();
  paintTree();
}

function diskNote(f) {
  return f.disk === 'gone' ? '  (deleted on disk)'
    : f.disk === 'changed' ? '  (changed on disk: saving asks before writing over it)' : '';
}

const SAVE_SVG = '<svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" ' +
  'stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M8 2v7M5 6.2l3 3 3-3M3 12.5h10"/></svg>';

function renderOpenEditors() {
  const list = $('#oe-list');
  list.textContent = '';
  const dirty = S.order.filter((p) => S.open.get(p).dirty).length;
  $('#oe-count').textContent = String(S.order.length);
  $('#save-all-btn').disabled = dirty === 0;
  $('#close-all-btn').disabled = S.order.length === 0;
  $('#reveal-btn').disabled = !S.active || !projectPath(S.active);

  for (const path of S.order) {
    const f = S.open.get(path);
    const row = document.createElement('div');
    row.dataset.key = path;
    row.className = 'oe-row'
      + (path === S.active ? ' active' : '')
      + (f.dirty ? ' dirty' : '')
      + (path === S.preview ? ' preview' : '');

    const state = document.createElement('span');
    state.className = 'state';
    // Unsaved edits show the pencil, drawn by the stylesheet; the pointer on it shows the ×.
    const paint = (hover) => {
      const editing = f.dirty && !hover;
      state.classList.toggle('editing', editing);
      state.textContent = editing ? '' : '\u00d7';
    };
    paint(false);
    state.title = f.dirty ? 'Close, losing unsaved changes' : 'Close';
    state.addEventListener('mouseenter', () => paint(true));
    state.addEventListener('mouseleave', () => paint(false));
    state.addEventListener('click', (e) => { e.stopPropagation(); closeFile(path); });

    const nm = document.createElement('span');
    nm.className = 'nm';
    // The comparison is keyed `collin:compare`, which is no path to show.
    const compare = collinTab(f);
    nm.textContent = compare ? f.path : base(path);
    const dir = document.createElement('span');
    dir.className = 'dir';
    dir.textContent = compare ? 'target/collin' : dirOf(path);

    const sv = document.createElement('button');
    sv.className = 'icon save';
    sv.title = 'Save this file';
    sv.innerHTML = SAVE_SVG;
    sv.addEventListener('click', async (e) => {
      e.stopPropagation();
      if (await saveFile(path)) { renderTabs(); toast('saved ' + base(path), 'ok'); }
    });

    row.append(state, nm, dir, sv);
    row.title = compare ? 'target/collin/' : path;
    row.addEventListener('click', () => activate(path));
    row.addEventListener('mousedown', (e) => { if (e.button === 1) { e.preventDefault(); closeFile(path); } });
    list.appendChild(row);
  }
}

/* The commands a tab's own menu offers, each with the tabs it would take.
   Right-click is the first context menu in the app; every other menu here is
   click-opened, and this one is the one people arrive expecting. */
function openTabMenu(anchor, key) {
  if (closePopup(anchor)) return;
  const menu = document.createElement('div');
  menu.className = 'envmenu';
  menu.setAttribute('role', 'menu');
  menu.append(Object.assign(document.createElement('div'),
    { className: 'menuhead', textContent: base(projectPath(key) || key) }));

  for (const [what, label, phrase] of [
    ['close', 'Close', 'Close it anyway?'],
    ['others', 'Close others', 'Close the other tabs anyway?'],
    ['right', 'Close to the right', 'Close them anyway?'],
    ['saved', 'Close saved', 'Close the saved tabs anyway?'],
  ]) {
    const keys = closeTargets(what, key, S.order, S.open);
    const b = document.createElement('button');
    b.type = 'button';
    b.setAttribute('role', 'menuitem');
    b.append(Object.assign(document.createElement('span'), { className: 'lbl', textContent: label }));
    if (keys.length > 1) {
      b.append(Object.assign(document.createElement('span'),
        { className: 'sub', textContent: String(keys.length) }));
    }
    // openPopup's roving focus skips these, so a command that would take
    // nothing is neither clickable nor reachable by arrow.
    if (!keys.length) b.setAttribute('aria-disabled', 'true');
    else b.addEventListener('click', () => { closePopup(); closeMany(keys, phrase); });
    menu.append(b);
  }
  openPopup(anchor, menu);
}

/* Following a ref(), a macro or a search hit moves the cursor somewhere nobody
   typed, and until now there was no way back. Two stacks, the way a browser
   keeps them: going somewhere new empties the forward one. */
const JUMPS = 50;

function here() {
  const f = S.active && S.open.get(S.active);
  if (!f) return null;
  // A diff and the profile have no cursor worth keeping, only the tab.
  const at = ownsPane(f) || !S.cm ? null : S.cm.getCursor();
  // And the lineage's depth, which going back puts back (jump).
  const depth = [$('#up').value, $('#down').value];
  return at ? { key: S.active, line: at.line, ch: at.ch, depth } : { key: S.active, depth };
}

/* Called before a jump, never after: afterwards the place left is gone. `pin`
   is off only for a move that is browsing rather than following a link, one
   click on a lineage box, which must leave the tabs as one click in the tree
   does. `at` is a place taken earlier by a caller that waits before it knows
   whether it jumps, so a move during the wait is not the one kept. */
function pushJump({ pin = true, at = here() } = {}) {
  if (!at) return;
  S.back.push(at);
  if (S.back.length > JUMPS) S.back.shift();
  S.fwd = [];
  if (pin && pinLeftPreview(S)) renderTabs();
  renderCrumbs();
}

/* The first entry still worth going to, with the rest of the stack. A tab
   closed since is skipped rather than purged on close, because closing a file
   and opening it again is the ordinary thing to do. */
function nextJump(stack, open) {
  const rest = stack.slice();
  while (rest.length) {
    const at = rest.pop();
    if (open.has(at.key)) return { at, rest };
  }
  return { at: null, rest };
}

/* The tab a link is followed from has to outlive the jump, or Back has nowhere
   to land. A preview tab would not: the link opens its target as a preview,
   which takes the one preview slot, and nextJump skips a closed tab. So the tab
   left is pinned first, as VS Code pins an editor a code navigation starts from
   (`workbench.editor.enablePreviewFromCodeNavigation`, off by default). A
   chain of links leaves a pinned tab per step; the target alone stays a
   preview, until a link is followed from it in turn. */
function pinLeftPreview(state) {
  if (!state.preview || state.preview !== state.active) return false;
  state.preview = null;
  return true;
}

function jump(from, to) {
  const { at, rest } = nextJump(S[from], S.open);
  S[from] = rest;
  if (!at) return renderCrumbs();
  const back = here();
  if (back) S[to].push(back);
  if (S.active !== at.key) {
    // The lineage follows the tab as it does a click on it, but a return is
    // not a model picked anew: it comes back at the depth it was left with.
    // The boxes take it at once, so a second jump before this one has drawn
    // records it, and a canvas the tab does not move is drawn again at it.
    activate(at.key, false);
    const deeper = !!at.depth && ($('#up').value !== at.depth[0] || $('#down').value !== at.depth[1]);
    if (at.depth) [$('#up').value, $('#down').value] = at.depth;
    const inProject = projectPath(at.key);
    const moved = inProject ? syncNode(inProject, { keepDepth: true }) : Promise.resolve(false);
    moved.then((did) => { if (!did && deeper) rerender(); });
  }
  if (at.line !== undefined) gotoPos(at.line, at.ch);
  renderCrumbs();
}

const jumpBack = () => jump('back', 'fwd');
const jumpForward = () => jump('fwd', 'back');

/* The left of the status bar (0166): in Code, the file in front with its cursor
   and the state of the buffer, the path in mono and the rest quieter; in another
   space, its name and the place in it, as the boards draw them. `selection` is the
   line the lineage last drew, `section` the title of the section in front in
   Reports or the settings. Pure: updateStatus() draws what it returns.
   `lead` is the space's name when the place is inside one, `notes` what goes
   after `here`. */
function statusWhere({ space, file, at, selection, section }) {
  if (space === 'lineage') return { lead: 'Lineage', here: selection || '', mono: true, notes: [] };
  if (space === 'reports') return { lead: 'Reports', here: section || '', mono: false, notes: [] };
  if (space === 'settings') return { lead: 'Settings', here: section || '', mono: false, notes: [] };
  if (!file) return { lead: '', here: 'no file', mono: false, notes: [] };
  const cursor = at ? `${at.line + 1}:${at.ch + 1}` : '';
  if (file.kind === 'diff') return { lead: '', here: file.path, mono: true, notes: ['diff against HEAD', 'read only'] };
  if (file.kind === 'compare') {
    return { lead: '', here: `target/collin/${file.pair.a} against target/collin/${file.pair.b}`, mono: true, notes: ['read only'] };
  }
  const notes = [cursor, file.dirty ? 'modified' : ''];
  if (file.kind === 'profile') {
    notes.push('outside the project');
    if (file.hidden) notes.push(`${file.hidden} secret${file.hidden === 1 ? '' : 's'} kept on the server`);
  } else if (file.truncated) {
    notes.push('truncated');
  }
  return { lead: '', here: file.path, mono: true, notes: notes.filter(Boolean) };
}

/* The kinds the counts name, in their order, with their plurals: "5 models · 3
   seeds". The status bar's, the top bar having given its chips up. */
function statusCounts(counts) {
  const c = counts || {};
  return ['model', 'source', 'seed', 'snapshot', 'test']
    .filter((k) => c[k])
    .map((k) => `${c[k]} ${k}${c[k] > 1 ? 's' : ''}`)
    .join(' · ');
}

/* The name of the section in front in Reports or the settings, as its rail says it. */
function sectionInFront(space) {
  if (space === 'reports') {
    const sec = reportsSections(S.reports, S.macroFocus).find((x) => x.key === S.reportsSection);
    return sec ? sec.label : '';
  }
  const sec = settingsSections({}).find((x) => x.key === S.settingsSection);
  return sec ? sec.label : '';
}

function updateStatus() {
  const space = spaceNow();
  const f = S.active && space === 'code' ? S.open.get(S.active) : null;
  const where = statusWhere({
    space,
    file: f && { kind: f.kind, path: f.kind === 'diff' || f.kind === 'profile' ? f.path : S.active, dirty: f.dirty,
      truncated: f.truncated, hidden: f.hidden, pair: f.pair },
    at: f && S.cm ? S.cm.getCursor() : null,
    selection: S.selectShown,
    section: space === 'reports' || space === 'settings' ? sectionInFront(space) : '',
  });
  const out = [];
  // The space's name alone while it has no place yet (an empty selector box).
  if (where.lead) out.push(Object.assign(document.createElement('span'), { className: 'lead', textContent: where.lead }));
  if (where.lead && where.here) out.push(Object.assign(document.createElement('span'), { className: 'sepa', textContent: '›' }));
  if (where.here) out.push(Object.assign(document.createElement('span'), { className: where.mono ? 'mono' : '', textContent: where.here }));
  for (const note of where.notes) out.push(Object.assign(document.createElement('span'), { className: 'note', textContent: ` · ${note}` }));
  $('#status-where').replaceChildren(...out);
}

// ------------------------------------------------------------ breadcrumbs --
/* The bar under the tabs: where the file sits in the project, then where the
   cursor sits inside the file. Both halves navigate, the way VS Code's
   breadcrumb does. The path half asks /api/dir; the symbol half is scanned in
   the browser, from the document CodeMirror already holds, so an unsaved edit
   is reflected without a round trip. */

/* One entry per path segment. `dir` is the folder that segment's menu lists,
   which is its parent, so the first segment lists the project root.

   Split on either separator and rejoin with `/`. The graph normalises what the
   manifest gave it, so this is belt and braces rather than the fix, but a bar
   that silently becomes one long segment is not a failure anyone would read as
   a path problem. */
function pathCrumbs(path) {
  if (!path) return [];
  const parts = path.split(/[\\/]/).filter((p) => p !== '');
  return parts.map((label, i) => ({
    label,
    path: parts.slice(0, i + 1).join('/'),
    dir: parts.slice(0, i).join('/'),
  }));
}

/* Leading spaces, or -1 when the indentation contains a tab. YAML forbids a tab
   there, and misreading the nesting is worse than dropping the line. The same
   refusal src/project.rs makes for dbt_project.yml. */
function yamlIndent(line) {
  let n = 0;
  while (line[n] === ' ') n++;
  return line[n] === '\t' ? -1 : n;
}

/* Splits `key: value` at the first `:` outside quotes. YAML only starts a
   mapping when the colon is followed by a space or ends the line, so `a:b` stays
   a scalar and `url: http://x` splits once, at the right colon. */
function yamlKey(s) {
  let quote = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (quote) { if (c === quote) quote = ''; continue; }
    if (c === '"' || c === "'") { quote = c; continue; }
    if (c !== ':') continue;
    const next = s[i + 1];
    if (next !== undefined && next !== ' ' && next !== '\t') continue;
    return { key: unquote(s.slice(0, i).trim()), value: s.slice(i + 1).trim() };
  }
  return null;
}

/* One layer of matching quotes, so a quoted key or list entry reads as itself. */
function unquote(s) {
  const q = s[0];
  return (q === '"' || q === "'") && s.length > 1 && s[s.length - 1] === q ? s.slice(1, -1) : s;
}

/* A file's text as CodeMirror hands it back: \n alone, whatever the file has.
   What is read from the disk goes through this before it is scanned or set
   beside a tab's text. In a CRLF file a `key:` ending its line is followed by
   a \r, which yamlKey takes for no key at all, so every folder written that
   way vanished and its configs piled onto the level above. */
function editorText(text) {
  return text.replace(/\r\n?/g, '\n');
}

/* Every node owns the lines up to the next node that is not below it. Filled in
   one pass so a cursor line resolves by containment rather than by guessing. */
function closeRanges(nodes, lastLine) {
  const open = [];
  for (let j = 0; j < nodes.length; j++) {
    while (open.length && nodes[open[open.length - 1]].depth >= nodes[j].depth) {
      const t = open.pop();
      nodes[t].endLine = Math.max(nodes[t].line, nodes[j].line - 1);
    }
    open.push(j);
  }
  for (const t of open) nodes[t].endLine = Math.max(nodes[t].line, lastLine);
  return nodes;
}

/* A flat outline of a YAML document: one node per mapping key and per sequence
   item, in line order, each pointing at its parent. Enough for a breadcrumb and
   no more. Flow collections, anchors and multi-document files are deliberately
   not modelled: a dbt properties file uses none of them, and a crumb that is
   sometimes wrong is worse than a crumb that is absent. */
function yamlOutline(text) {
  const lines = text.split('\n');
  const nodes = [];
  // The root frame is never popped, so every line has somewhere to attach.
  const stack = [{ indent: -1, node: -1, item: false, count: 0, leaf: false }];
  let block = -1;              // indent of the key owning a `|` or `>` body

  const add = (line, col, label, parent) => {
    nodes.push({ line, col, label, kind: 'scalar', depth: stack.length - 1, parent, endLine: line });
    return nodes.length - 1;
  };

  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    const trimmed = raw.trim();
    const ind = yamlIndent(raw);
    if (block >= 0) {
      // A description block is full of dashes and colons that are not structure.
      if (trimmed === '' || (ind > block && ind >= 0)) continue;
      block = -1;
    }
    if (trimmed === '' || trimmed[0] === '#' || ind < 0) continue;

    let col = ind;
    let rest = raw.slice(ind);
    let item = -1;               // the item opened on this line, if any
    // `- - a` opens two levels on one line, so the dashes are taken in a loop.
    while (rest === '-' || rest.startsWith('- ')) {
      while (stack.length > 1) {
        const top = stack[stack.length - 1];
        // A key frame at the same indent is kept: YAML lets a sequence sit at
        // its key's own column, and that is how dbt files are usually written.
        if (top.indent > col || top.leaf || (top.indent === col && top.item)) stack.pop();
        else break;
      }
      const parent = stack[stack.length - 1];
      const idx = add(i, col, String(parent.count++), parent.node);
      item = idx;
      if (parent.node >= 0) nodes[parent.node].kind = 'seq';
      stack.push({ indent: col, node: idx, item: true, count: 0, leaf: false });
      let k = 1;
      while (rest[k] === ' ') k++;
      col += k;
      rest = rest.slice(k);
      if (rest === '') break;
    }
    // `- # note` is an item with nothing on its line yet, not a string item
    // holding the comment: its keys follow on the lines below.
    if (rest === '' || rest === '-' || rest[0] === '#') continue;

    const kv = yamlKey(rest);
    if (!kv) {
      // A list of plain strings, which dbt files are full of, reads by value
      // rather than by index: `satellites > sat_web__order`, not `> 4`.
      if (item >= 0 && rest !== '') {
        nodes[item].label = unquote(rest);
        stack[stack.length - 1].leaf = true;
      }
      continue;
    }
    while (stack.length > 1) {
      const top = stack[stack.length - 1];
      if (top.indent >= col || top.leaf) stack.pop();
      else break;
    }
    const parent = stack[stack.length - 1];
    // A value that is only a comment leaves the key free to adopt children.
    const value = kv.value[0] === '#' ? '' : kv.value;
    const leaf = value !== '';
    const idx = add(i, col, kv.key, parent.node);
    if (parent.node >= 0) nodes[parent.node].kind = 'map';
    stack.push({ indent: col, node: idx, item: false, count: 0, leaf });
    if (leaf && (value[0] === '|' || value[0] === '>')) block = col;
  }
  return closeRanges(nodes, lines.length - 1);
}

/* Where a project var is defined: its key right under the top-level `vars:`,
   read from the buffer, since the line the server gives was read from the
   disk and an unsaved edit above it moves it. A var under a package's scope
   is not looked for, as the card does not show one (0018). The last of two
   keys of one name, which is the one YAML keeps and the card reads. */
function varDefLine(text, name) {
  const nodes = yamlOutline(text);
  const block = nodes.findIndex((n) => n.parent === -1 && n.label === 'vars');
  if (block < 0) return null;
  const hits = nodes.filter((n) => n.parent === block && n.label === name);
  const hit = hits[hits.length - 1];
  return hit ? { line: hit.line, ch: hit.col } : null;
}

/* Where a click on a var() lands: its key in the buffer, else the line the
   server read from the disk, `row`, when the buffer holds a key outline cannot
   place. `row` is null for a buffer with unsaved edits, which the disk no
   longer describes: a key renamed or deleted there lands nowhere. */
function varLanding(text, name, row) {
  return varDefLine(text, name) || (row ? { line: row.line - 1, ch: 0 } : null);
}

/* ATX headings, and none inside a fenced block: that is what a reader navigates
   a markdown file by. */
function mdOutline(text) {
  const lines = text.split('\n');
  const nodes = [];
  let fence = '';
  for (let i = 0; i < lines.length; i++) {
    const t = lines[i].trim();
    if (fence) { if (t.startsWith(fence)) fence = ''; continue; }
    if (t.startsWith('```')) { fence = '```'; continue; }
    if (t.startsWith('~~~')) { fence = '~~~'; continue; }
    if (t[0] !== '#') continue;
    let level = 0;
    while (t[level] === '#') level++;
    if (level > 6 || (t[level] !== undefined && t[level] !== ' ')) continue;
    const label = t.slice(level).trim();
    if (!label) continue;
    let parent = -1;
    for (let j = nodes.length - 1; j >= 0; j--) {
      if (nodes[j].depth < level - 1) { parent = j; break; }
    }
    nodes.push({
      line: i, col: lines[i].indexOf('#'), label,
      kind: 'heading', depth: level - 1, parent, endLine: i,
    });
  }
  return closeRanges(nodes, lines.length - 1);
}

/* SQL is absent on purpose. A CTE name can only be found honestly by masking
   strings and comments first, and a bar that occasionally names a case arm as a
   model section is worse than a bar with nothing after the file name. */
function documentOutline(path, text) {
  const mode = modeFor(path);
  if (mode === 'text/x-yaml') return yamlOutline(text);
  if (mode === 'text/x-markdown') return mdOutline(text);
  return [];
}

/* The nodes containing a line, outermost first. */
function outlineChainAt(nodes, line) {
  const out = [];
  for (let i = 0; i < nodes.length; i++) {
    if (nodes[i].line > line) break;
    if (nodes[i].endLine >= line) out.push(i);
  }
  return out;
}

function outlineSiblings(nodes, i) {
  const out = [];
  for (let j = 0; j < nodes.length; j++) if (nodes[j].parent === nodes[i].parent) out.push(j);
  return out;
}

/* The glyph stands for the kind of the node's value, which is what VS Code
   shows: a mapping, a sequence, or a plain scalar. */
function crumbIcon(kind) {
  if (kind === 'map') return '{ }';
  if (kind === 'seq') return '[ ]';
  if (kind === 'heading') return '#';
  return 'abc';
}

function renderCrumbs() {
  const bar = $('#crumbs');
  const f = S.active ? S.open.get(S.active) : null;
  /* Hidden for a diff, which holds two documents and no cursor, and for the
     profile, which lives outside the project where /api/dir cannot list. */
  bar.textContent = '';
  if (!f) {
    bar.classList.add('hidden');
    return;
  }
  bar.classList.remove('hidden');
  bar.append(navButton('back'), navButton('fwd'));
  /* A diff holds two documents and no cursor, and the profile lives outside
     the project where /api/dir cannot list, so neither gets a path. The
     chevrons stay: they are how you get back out of one. */
  if (ownsPane(f) || f.kind === 'profile') return;

  const segs = pathCrumbs(S.active);
  // A slash between the path's parts and the file's own in the text colour; the
  // chevron stays for what is inside the file, as it steps into it (0166).
  segs.forEach((seg, i) => {
    if (i) bar.appendChild(crumbSep('/'));
    const b = crumbButton(seg.label, '', (btn) =>
      openCrumbMenu(btn, { kind: 'path', dir: seg.dir, current: seg.path }));
    if (i === segs.length - 1) b.classList.add('cur');
    bar.appendChild(b);
  });

  const nodes = S.outline && S.outline.path === S.active ? S.outline.nodes : [];
  for (const idx of outlineChainAt(nodes, S.crumbLine)) {
    const n = nodes[idx];
    bar.appendChild(crumbSep());
    bar.appendChild(crumbButton(n.label, n.kind, (btn) =>
      openCrumbMenu(btn, { kind: 'symbol', index: idx })));
  }
  if (CONFIGURABLE.test(S.active)) {
    bar.append(Object.assign(document.createElement('span'), { className: 'crumb-gap' }), configCrumb(S.active));
  }
  // A deep path scrolls: the end is the part that says where you are.
  bar.scrollLeft = bar.scrollWidth;
}

/* Where following a link came from, and where it went. Greyed at the end of
   its stack rather than hidden, so the pair does not shift the path sideways
   as you move. */
function navButton(which) {
  const b = document.createElement('button');
  b.className = 'crumb nav';
  b.type = 'button';
  b.textContent = which === 'back' ? '\u2039' : '\u203a';
  const live = nextJump(S[which], S.open).at;
  b.disabled = !live;
  b.title = which === 'back'
    ? `Back${live ? ' to ' + base(projectPath(live.key) || live.key) : ''} (${keyLabel('Mod+Alt+P', IS_MAC)})`
    : `Forward${live ? ' to ' + base(projectPath(live.key) || live.key) : ''} (${keyLabel('Mod+Alt+N', IS_MAC)})`;
  b.setAttribute('aria-label', b.title);
  b.addEventListener('click', which === 'back' ? jumpBack : jumpForward);
  return b;
}

/* A file dbt builds a node from, by its extension. Whether it sits under a
   resource path is only known once the server names the roots, which is not
   worth a request on every render: the menu says so instead. */
const CONFIGURABLE = /\.(sql|py|csv)$/i;

/* The way from a file to the keys of dbt_project.yml that reach it (0038),
   at the far end of the bar, apart from the path it is not a segment of. A
   pill in the violet of dbt's own YAML, with the YAML file's icon and its
   name, the way the design draws it. */
function configCrumb(file) {
  const b = crumbButton('dbt_project.yml', '', (btn) => openCrumbMenu(btn, { kind: 'config', file }));
  b.classList.add('cfg');
  b.insertAdjacentHTML('afterbegin', YML_ICON);
  b.title = 'dbt_project.yml\nWhere it configures this file';
  b.setAttribute('aria-label', 'Where dbt_project.yml configures this file');
  b.setAttribute('aria-haspopup', 'dialog');
  b.setAttribute('aria-expanded', 'false');
  return b;
}

/* The dialog of configCrumb: the lines of dbt_project.yml that reach the file,
   as it writes them, the ones a deeper level replaces struck (0156). It is
   where dbt_project.yml configures the file, which is not the config the file
   ends up with: the footer says what still comes after. */
async function configMenu(file) {
  const open = S.open.get('dbt_project.yml');
  let raw;
  let roots;
  try {
    raw = open && open.doc ? open.doc.getValue() : (await api.get('/api/file?path=dbt_project.yml')).content;
    // No keys, so the server only names the roots and stats nothing.
    roots = (await api.send('/api/project/resolve', 'POST', { keys: [] })).roots;
  } catch (e) {
    toast(e.message, 'err');
    return null;
  }
  return configMenuFor(raw, file, roots);
}

/* configMenu once dbt_project.yml and the roots are read, apart so a test
   reaches it. The text comes from the tab when one is open and from the disk
   otherwise, in the endings the file was saved with, so it is read as the tab
   would hold it either way: a line is CodeMirror's line. With no line to show,
   `note` says why. */
function configMenuFor(raw, file, roots) {
  const name = file.slice(file.lastIndexOf('/') + 1);
  const menu = { name, title: `Where dbt_project.yml configures ${name}`, note: '', lines: [], tag: '', pkg: inPackage(file) };
  if (raw.length > OUTLINE_MAX) return { ...menu, note: 'dbt_project.yml is too large to scan.' };
  const text = editorText(raw);
  const at = fileFqn(file, roots, projectNameIn(text));
  if (!at) return { ...menu, note: 'Not a model, seed, snapshot, analysis or test under the paths dbt_project.yml sets.' };
  const levels = configLevels(projectPathKeys(text), at);
  if (!levels.length) return { ...menu, note: 'No key of dbt_project.yml reaches this file.' };
  return { ...menu, ...configExcerpt(text, levels, at, name) };
}

/* How dbt folds a deeper level's config into the upper ones (0156), from the
   merge metadata each field of dbt-core's config classes declares
   (`dbt/artifacts/resources/v1/config.py`, `model.py`): these add up or update
   key by key, `grants` per key unless the deeper key starts with `+`, and every
   other config, a field with no metadata, is replaced by the deepest level that
   sets it. */
const MERGE_APPEND = new Set(['tags', 'pre-hook', 'post-hook', 'packages']);
const MERGE_UPDATE = new Set(['meta', 'docs', 'quoting', 'column_types', 'contract', 'latest_version_pointer']);
const MERGE_BY_KEY = new Set(['grants']);

/* The config a key of a level names, as dbt names it: a `+` is dropped and
   the hooks' underscores are dashes, so `pre_hook` and `+pre-hook` are one. */
function configName(key) {
  const n = (key.startsWith('+') ? key.slice(1) : key).trim();
  return n === 'pre_hook' ? 'pre-hook' : n === 'post_hook' ? 'post-hook' : n;
}

/* The lines of dbt_project.yml that reach a file, as the file writes them: the
   key line of each level and every config set directly under it with all of its
   own lines. Plain data, one entry per line in the file's order:
   - `over`: the 1-based line of the deeper setting dbt keeps instead of this
     one (0 when none does), on each line struck, and `noted` on the first of
     them, which is where the note is written;
   - `here`: the level that names the folder holding the file;
   - `gapBefore`: a line holding YAML was left out between this one and the
     one before. */
function configExcerpt(text, levels, at, fileName) {
  const raw = text.split('\n');
  const nodes = yamlOutline(text);
  const kids = nodes.map(() => []);
  nodes.forEach((n, j) => { if (n.parent >= 0) kids[n.parent].push(j); });
  // The lines of a `|` or `>` block are its value, a `#` among them included.
  const inBlock = new Set();
  for (const n of nodes) {
    const kv = yamlKey(raw[n.line].slice(n.col));
    if (!kv || (kv.value[0] !== '|' && kv.value[0] !== '>')) continue;
    for (let l = n.line + 1; l <= n.endLine; l++) if (raw[l].trim() !== '' && yamlIndent(raw[l]) > n.col) inBlock.add(l);
  }
  const yamlLine = (l) => { const t = raw[l].trim(); return t !== '' && (t[0] !== '#' || inBlock.has(l)); };
  // A range ends where its last line of YAML does: a node owns the blank and
  // comment lines up to the next one, which are no part of its value.
  const lastOf = (n) => { let e = n.endLine; while (e > n.line && !yamlLine(e)) e--; return e; };

  const shown = new Map();
  const show = (from, to) => {
    for (let l = from; l <= to; l++) {
      if (yamlLine(l) && !shown.has(l)) shown.set(l, { over: 0, noted: false, here: false });
    }
  };
  const strike = (n, by) => {
    for (let l = n.line; l <= lastOf(n); l++) {
      const e = shown.get(l);
      if (e) { e.over = by + 1; e.noted = l === n.line; }
    }
  };

  // Per level, the settings by config. One written twice at a level is left
  // alone: YAML keeps the last, and which one the reader means is unknown.
  const byConfig = levels.map((k) => {
    const m = new Map();
    for (const s of k.sets) {
      const name = configName(s.name);
      if (!m.has(name)) m.set(name, []);
      m.get(name).push(s);
    }
    return m;
  });
  for (const k of levels) {
    show(k.line, k.line);
    if (k.chain.length === at.fqn.length - 1) shown.get(k.line).here = true;
    for (const s of k.sets) show(s.line, lastOf(nodes[s.node]));
  }

  const stripPlus = (key) => key.replace(/^\++/, '');
  levels.forEach((k, a) => {
    for (const [name, group] of byConfig[a]) {
      if (group.length !== 1 || MERGE_APPEND.has(name)) continue;
      const up = group[0];
      // Deepest first, since the deepest level's setting is the one dbt keeps.
      const deeper = [];
      for (let b = levels.length - 1; b > a; b--) {
        const g = byConfig[b].get(name);
        if (g && g.length === 1) deeper.push(g[0]);
      }
      if (!deeper.length) continue;
      if (!MERGE_UPDATE.has(name) && !MERGE_BY_KEY.has(name)) { strike(nodes[up.node], deeper[0].line); continue; }
      // Key by key; a value written in flow style on its key line has no key
      // line of its own to strike, on either side, and one line cannot be half
      // struck.
      if (nodes[up.node].kind !== 'map') continue;
      for (const c of kids[up.node]) {
        for (const d of deeper) {
          // A deeper value in flow style may hold the key, unread: nothing is
          // struck, since the line dbt keeps could be one shown nowhere.
          if (nodes[d.node].kind !== 'map') break;
          const hit = kids[d.node].find((j) => (MERGE_BY_KEY.has(name)
            ? !nodes[j].label.startsWith('+') && nodes[j].label === stripPlus(nodes[c].label)
            : nodes[j].label === nodes[c].label));
          if (hit !== undefined) { strike(nodes[c], nodes[hit].line); break; }
        }
      }
    }
  });

  const lines = [];
  const startAt = new Map();
  nodes.forEach((n) => { if (!startAt.has(n.line)) startAt.set(n.line, n); });
  let prev = -1;
  let owner = -1;
  for (const l of [...shown.keys()].sort((x, y) => x - y)) {
    const e = shown.get(l);
    let gapBefore = false;
    for (let m = prev + 1; prev >= 0 && m < l; m++) if (yamlLine(m)) { gapBefore = true; break; }
    prev = l;

    const col = raw[l].search(/\S/);
    const rest = raw[l].slice(col).trimEnd();
    const node = startAt.get(l);
    // A line no node starts is the text of a `|` block, one level in from its key.
    while (owner + 1 < nodes.length && nodes[owner + 1].line < l) owner++;
    const depth = node ? node.depth : (owner >= 0 ? nodes[owner].depth + 1 : 0);
    let key = '';
    let punct = '';
    let value = node ? yamlValueText(rest) : rest;
    const kv = node && !rest.startsWith('- ') && rest !== '-' ? yamlKey(rest) : null;
    if (kv) {
      key = kv.key;
      value = yamlValueText(kv.value);
      punct = value ? ': ' : ':';
    }
    lines.push({
      line: l, col, depth, key, punct, value, tpl: value.includes('{{'),
      over: e.over, noted: e.noted, here: e.here, gapBefore,
    });
  }
  return { lines, tag: `${fileName} is here` };
}

/* What the dialog's footer says wins over its lines. dbt applies the levels of
   the project that owns a file first, then the properties YAML, then the file's
   `config()`; a package's file is also reached by the root project's levels,
   which this dialog shows, and those come last (`calculate_node_config`, 0156). */
function configFooter(pkg) {
  if (!pkg) return 'A config() in the file, or in its properties YAML, wins over these lines.';
  return 'These are the root project\'s lines. dbt applies them after the package\'s own dbt_project.yml, '
    + 'properties YAML and config(), so they win over those.';
}

/* Where the dialog of configCrumb sits: under its button, its right edge on the
   button's, and held inside the editor pane, whose right edge it would run past
   when the button sits near it. Rectangles in, a corner out. */
function configDialogAt(button, pane, box, win) {
  const left = Math.max(pane.left + 8, Math.min(button.right - box.width, pane.right - 8 - box.width));
  const top = Math.max(8, Math.min(button.bottom + 4, win.height - box.height - 8));
  return { left, top };
}

/* dbt_project.yml at a key, as a link is followed: the chevrons lead back. */
async function openProjectAt(line, ch) {
  closeCrumbMenu();
  pushJump();
  await openFile('dbt_project.yml', { focusLineage: false, preview: true });
  const f = S.open.get('dbt_project.yml');
  if (S.active !== 'dbt_project.yml' || !f || !f.doc) return;  // it could not be opened
  revealInTree('dbt_project.yml');
  gotoPos(line, ch);
}

function crumbSep(mark = '›') {
  return Object.assign(document.createElement('span'), { className: mark === '/' ? 'crumb-sep sl' : 'crumb-sep', textContent: mark });
}

function crumbButton(label, kind, open) {
  const b = document.createElement('button');
  b.className = 'crumb';
  b.type = 'button';
  if (kind) {
    const ic = document.createElement('span');
    ic.className = 'sicon';
    ic.dataset.kind = kind;
    ic.textContent = crumbIcon(kind);
    b.appendChild(ic);
  }
  b.append(Object.assign(document.createElement('span'), { className: 'lbl', textContent: label }));
  b.addEventListener('click', () => {
    if (crumbMenu && crumbMenu.anchor === b) return closeCrumbMenu();
    open(b);
  });
  return b;
}

// A document larger than this is not worth scanning on every keystroke pause.
const OUTLINE_MAX = 2 * 1024 * 1024;

function refreshOutline() {
  S.outline = null;
  S.crumbLine = -1;
  const f = S.active ? S.open.get(S.active) : null;
  if (!f || f.kind === 'diff' || f.kind === 'profile' || !f.doc) return;
  const text = f.doc.getValue();
  if (text.length > OUTLINE_MAX) return;
  S.outline = { path: S.active, nodes: documentOutline(S.active, text) };
  S.crumbLine = S.cm ? S.cm.getCursor().line : 0;
}

/* Only a change of line can change the chain, and the cursor moves far more
   often than that. */
function crumbCursor() {
  if (!S.outline || S.outline.path !== S.active || !S.cm) return;
  const line = S.cm.getCursor().line;
  if (line === S.crumbLine) return;
  S.crumbLine = line;
  renderCrumbs();
}

/* Puts the cursor somewhere in the active document and shows it. Shared by the
   search results and the symbol crumbs, which want the same three steps. */
// `focus` false moves the cursor and the view and leaves the keyboard where
// it was, for a click on the canvas that shows a line without writing there.
function gotoPos(line, ch = 0, focus = true) {
  if (!S.cm) return;
  const pos = { line: Math.max(0, line), ch: Math.max(0, ch) };
  S.cm.setCursor(pos);
  S.cm.scrollIntoView({ from: pos, to: pos }, 120);
  if (focus) S.cm.focus();
}

let crumbMenu = null;                        // { el, anchor, off }
let crumbAsk = 0;                            // the latest menu asked for

function closeCrumbMenu({ refocus = false } = {}) {
  if (!crumbMenu) return;
  const { el, anchor, off } = crumbMenu;
  crumbMenu = null;
  off();
  el.remove();
  anchor.classList.remove('open');
  if (anchor.hasAttribute('aria-expanded')) anchor.setAttribute('aria-expanded', 'false');
  if (refocus) anchor.focus();
}

/* The dialog of configCrumb, built from configMenuFor's answer. Its own
   classes rather than the crumb menus' rows, since a line here is code: it
   wraps, and a number and a note sit beside it. */
function fillConfigDialog(el, menu) {
  const bold = (text) => Object.assign(document.createElement('b'), { textContent: text });
  const head = document.createElement('div');
  head.className = 'k-head';
  const sentence = document.createElement('span');
  sentence.append('Where ', bold('dbt_project.yml'), ' configures ', bold(menu.name));
  const open = document.createElement('button');
  open.type = 'button';
  open.className = 'k-open';
  open.append('Open', strokeIcon('0 0 16 16', 'k-ico', ['M6.5 3H3v10h10V9.5', 'M9 2.5h4.5V7M13.5 2.5L7.5 8.5']));
  open.addEventListener('click', () => openProjectAt(0, 0));
  head.append(sentence, open);
  el.setAttribute('role', 'dialog');
  el.setAttribute('aria-label', menu.title);
  el.append(head);
  if (!menu.lines.length) {
    el.append(Object.assign(document.createElement('div'), { className: 'k-note', textContent: menu.note }));
    return;
  }
  const box = document.createElement('div');
  box.className = 'yx';
  for (const l of menu.lines) {
    if (l.gapBefore) box.append(Object.assign(document.createElement('div'), { className: 'ygap', textContent: '\u22ef' }));
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'yl' + (l.over ? ' over' : '') + (l.here ? ' cur' : '');
    const code = document.createElement('span');
    code.className = 'yc';
    code.style.setProperty('--d', l.depth);
    const part = (cls, text) => Object.assign(document.createElement('span'), { className: cls, textContent: text });
    if (l.key) code.append(part('yk', l.key), part('yp', l.punct));
    if (l.value) code.append(part(l.tpl ? 'yv tpl' : 'yv', l.value));
    if (l.noted) code.append(part('ynote', `replaced on line ${l.over}`));
    if (l.here) code.append(part('ytag', menu.tag));
    b.append(part('yn', String(l.line + 1)), code);
    b.addEventListener('click', () => openProjectAt(l.line, l.col));
    box.append(b);
  }
  el.append(box, Object.assign(document.createElement('div'), {
    className: 'k-foot', textContent: configFooter(menu.pkg),
  }));
}

/* The menu a crumb opens. A path crumb lists the folder it sits in, so picking
   a sibling is one click; a folder inside it reopens the menu one level down,
   which is how VS Code lets you walk the tree without leaving the bar. */
async function openCrumbMenu(anchor, spec) {
  closeCrumbMenu();
  // A card that opened by accident must not sit over a menu opened on purpose.
  closeHoverCard();
  // The config menu waits on two requests: a second click, or a bar redrawn
  // under it, must not leave a menu floating nowhere.
  const ask = ++crumbAsk;

  let rows = [];
  let menu = null;
  if (spec.kind === 'config') {
    menu = await configMenu(spec.file);
    if (!menu) return;
  } else if (spec.kind === 'path') {
    let entries;
    try { entries = await api.get('/api/dir?path=' + encodeURIComponent(spec.dir)); }
    catch (e) { return toast(e.message, 'err'); }
    rememberMarks(entries);
    rows = entries.map((entry) => ({
      label: entry.name,
      dir: entry.dir,
      mark: markOf(entry),
      current: entry.path === spec.current,
      pick: () => {
        if (entry.dir) return openCrumbMenu(anchor, { kind: 'path', dir: entry.path, current: '' });
        closeCrumbMenu();
        pushJump();
        openFile(entry.path, { preview: true });
        revealInTree(entry.path);
      },
    }));
  } else {
    const nodes = S.outline ? S.outline.nodes : [];
    if (!nodes[spec.index]) return;
    rows = outlineSiblings(nodes, spec.index).map((j) => ({
      label: nodes[j].label,
      kind: nodes[j].kind,
      current: j === spec.index,
      pick: () => { closeCrumbMenu(); gotoPos(nodes[j].line, nodes[j].col); },
    }));
  }
  if ((!menu && !rows.length) || ask !== crumbAsk || !anchor.isConnected) return;

  const el = document.createElement('div');
  el.className = menu ? 'crumbmenu config' : 'crumbmenu';
  if (menu) fillConfigDialog(el, menu);
  for (const row of rows) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = row.current ? 'on' : '';
    const ic = document.createElement('span');
    if (row.kind) {
      ic.className = 'sicon';
      ic.dataset.kind = row.kind;
      ic.textContent = crumbIcon(row.kind);
      b.appendChild(ic);
    } else if (row.dir) {
      ic.className = 'caret';
      ic.innerHTML = CHEVRON;
      b.appendChild(ic);
    } else {
      b.appendChild(fileIcon(row.label, row.mark || null));
    }
    b.append(Object.assign(document.createElement('span'), { className: 'lbl', textContent: row.label }));
    b.addEventListener('click', row.pick);
    el.appendChild(b);
  }
  document.body.appendChild(el);
  anchor.classList.add('open');

  if (menu) {
    // Held to the editor it sits over, which a menu on the window is not.
    anchor.setAttribute('aria-expanded', 'true');
    const pane = (anchor.closest('#editor-pane') || document.body).getBoundingClientRect();
    el.style.maxWidth = `${Math.max(0, pane.width - 16)}px`;
    const box = el.getBoundingClientRect();
    const p = configDialogAt(anchor.getBoundingClientRect(), pane, box, { height: window.innerHeight });
    el.style.top = `${p.top}px`;
    el.style.left = `${p.left}px`;
  } else {
    const box = el.getBoundingClientRect();
    const p = placeFloating(anchor.getBoundingClientRect(), { width: box.width, height: box.height },
      { width: window.innerWidth, height: window.innerHeight }, 2);
    el.style.top = `${p.top}px`;
    el.style.left = `${p.left}px`;
  }

  const buttons = [...el.querySelectorAll('button')];
  const onKey = (e) => {
    if (e.key === 'Tab') return closeCrumbMenu();
    const i = buttons.indexOf(document.activeElement);
    const step = { ArrowDown: 1, ArrowUp: -1 }[e.key];
    if (e.key !== 'Escape' && !step) return;
    // Handled here only: the editor and the global shortcuts never see it.
    e.preventDefault();
    e.stopPropagation();
    if (e.key === 'Escape') closeCrumbMenu({ refocus: true });
    else buttons[(i + step + buttons.length) % buttons.length].focus();
  };
  const onDown = (e) => { if (!el.contains(e.target) && !anchor.contains(e.target)) closeCrumbMenu(); };
  // Scrolling the crumb bar away leaves the menu floating in the wrong place.
  const onScroll = (e) => {
    const t = e.target;
    if (t === document || (t instanceof Node && t.contains(anchor))) closeCrumbMenu();
  };
  const onResize = () => closeCrumbMenu();
  document.addEventListener('keydown', onKey, true);
  document.addEventListener('mousedown', onDown, true);
  document.addEventListener('scroll', onScroll, true);
  window.addEventListener('resize', onResize);
  crumbMenu = {
    el, anchor,
    off: () => {
      document.removeEventListener('keydown', onKey, true);
      document.removeEventListener('mousedown', onDown, true);
      document.removeEventListener('scroll', onScroll, true);
      window.removeEventListener('resize', onResize);
    },
  };
  // The dialog opens on the line that names the file's folder, else its first.
  (menu ? el.querySelector('.yl.cur') || el.querySelector('.yl') || buttons[0]
    : buttons.find((b) => b.classList.contains('on')) || buttons[0]).focus();
}

// ----------------------------------------------------------------- icons --
const CHEVRON = '<svg viewBox="0 0 16 16" width="11" height="11" fill="none" stroke="currentColor" ' +
  'stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M6 3.5L10.5 8 6 12.5"/></svg>';

/* The file glyphs are the design's: 16 by 16, stroked like every icon of the
   page. A model's .sql is a cylinder (a plain database drawn for this project,
   not derived from any vendor logo), coloured by what its node is built as. */
const FILE_SVG = (body) => '<svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" ' +
  'stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round">' + body + '</svg>';
const SQL_ICON = FILE_SVG('<ellipse cx="8" cy="4" rx="4.75" ry="1.9"/>' +
  '<path d="M3.25 4v8c0 1.05 2.1 1.9 4.75 1.9s4.75-.85 4.75-1.9V4M3.25 8c0 1.05 2.1 1.9 4.75 1.9s4.75-.85 4.75-1.9"/>');
/* A dotted list: dbt's YAML. */
const YML_ICON = FILE_SVG('<circle cx="2.75" cy="3.5" r="1" fill="currentColor" stroke="none"/>' +
  '<circle cx="5.25" cy="8" r="1" fill="currentColor" stroke="none"/><circle cx="5.25" cy="12.5" r="1" fill="currentColor" stroke="none"/>' +
  '<path d="M5.25 3.5h8.5M7.75 8h6M7.75 12.5h6"/>');
const MD_ICON = FILE_SVG('<rect x="1.25" y="3.5" width="13.5" height="9" rx="1.75"/>' +
  '<path d="M4 10.25v-4.5l2 2.5 2-2.5v4.5M11.5 5.75v4.5M10 8.75l1.5 1.5 1.5-1.5"/>');
const PY_ICON = FILE_SVG('<path d="M3 13V3.5h3a2.5 2.5 0 0 1 0 5H3"/><path d="M9 6.5l2.5 4.5M14 6.5L10 13.5"/>');
const SH_ICON = FILE_SVG('<rect x="1.25" y="2.75" width="13.5" height="10.5" rx="1.75"/><path d="M4 6l2.25 2L4 10M8 10.5h4"/>');
const DOC = FILE_SVG('<path d="M4 1.75h5l3 3v9.5H4z"/><path d="M9 1.75v3h3"/>');
const BRACES = FILE_SVG('<path d="M6.4 2.5C4.8 2.5 5 5 5 6.2S3.6 8 3.6 8 5 8.6 5 9.8 4.8 13.5 6.4 13.5"/>' +
  '<path d="M9.6 2.5c1.6 0 1.4 2.5 1.4 3.7S12.4 8 12.4 8 11 8.6 11 9.8s.2 3.7-1.4 3.7"/>');
const TABLE = FILE_SVG('<rect x="2.3" y="3.3" width="11.4" height="9.4" rx="1.2"/><path d="M2.3 6.6h11.4M6.4 6.6v6.1"/>');
const MACRO_ICON = '<svg viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" stroke-width="1.3" ' +
  'stroke-linecap="round"><path d="M11 2.6c-1.7-.5-2.9.2-3.2 2L6.4 11.4c-.3 1.8-1.5 2.5-3.2 2"/><path d="M5 6.5h5.5"/></svg>';

/* A macro in the palette, beside the files: not a file, so not a file's icon. */
function macroIcon() {
  const span = document.createElement('span');
  span.className = 'ficon macro';
  span.title = 'macro';
  span.innerHTML = MACRO_ICON;
  return span;
}

/* What the manifest makes of a file, by its path: {kind, materialized} for the
   file of a model, a seed or a snapshot, as /api/dir says it with each listing.
   A file the manifest does not define has none. */
const fileMark = (path) => S.fileMarks.get(path) || null;
const markOf = (entry) => (entry.kind ? { kind: entry.kind, materialized: entry.materialized || '' } : null);

/* Every file of a listing is remembered by its path, whether or not a row draws
   it: the tree, the breadcrumb's menu and a diff's title all read them. */
function rememberMarks(entries) {
  for (const e of entries) {
    if (e.dir) continue;
    const m = markOf(e);
    if (m) S.fileMarks.set(e.path, m); else S.fileMarks.delete(e.path);
  }
}

async function loadMarks(dir) {
  try { rememberMarks(await api.get('/api/dir?path=' + encodeURIComponent(dir))); } catch { /* a folder that is gone */ }
}

/* The folders asked of /api/dir for their marks alone, by folder, so each is
   asked once however many callers want it; forgotten with the marks. */
const marksAsked = new Map();

/* For a list of paths drawn outside the tree (the palette's file rows, a diff's
   title): asks each folder that could hold a model's, seed's or snapshot's file
   once, since S.fileMarks only knows the folders something has listed and a
   path with no mark cannot be told from one never asked about. Resolves true
   when one of the paths gained a mark, which is when its icon is to be drawn
   again. */
async function askMarks(paths) {
  const want = paths.filter((p) => /\.(sql|py|csv)$/i.test(p) && !S.fileMarks.has(p));
  const folders = new Set(want.map((p) => p.slice(0, Math.max(0, p.lastIndexOf('/')))));
  const asking = [];
  for (const dir of folders) {
    if (!marksAsked.has(dir)) marksAsked.set(dir, loadMarks(dir));
    asking.push(marksAsked.get(dir));
  }
  await Promise.all(asking);
  return want.some((p) => S.fileMarks.has(p));
}

/* A file's icon. Its shape says what the file is (a cylinder for SQL, a dotted
   list for YAML, a rounded M for Markdown, Py, a terminal, braces, a table, a
   page for the rest); its colour says only what the manifest builds it as, so
   it is neutral for every file but the one of a model, a seed or a snapshot,
   which takes the colour its box has on the canvas (0151). */
function fileIcon(name, mark) {
  const ext = name.slice(name.lastIndexOf('.') + 1).toLowerCase();
  const span = document.createElement('span');
  const [kind, svg] = ext === 'sql' ? ['sql', SQL_ICON]
    : ext === 'yml' || ext === 'yaml' ? ['yml', YML_ICON]
    : ext === 'md' ? ['md', MD_ICON]
    : ext === 'py' ? ['py', PY_ICON]
    : ext === 'sh' ? ['sh', SH_ICON]
    : ext === 'json' ? ['json', BRACES]
    : ext === 'csv' ? ['csv', TABLE]
    : ['other', DOC];
  span.className = 'ficon ' + kind;
  span.innerHTML = svg;
  // A Python model is a model: its Py glyph takes its box's colour too.
  if (mark && (kind === 'sql' || kind === 'csv' || kind === 'py')) {
    span.classList.add('node');
    span.style.color = Lineage.nodeColor(mark);
    span.title = Lineage.matLabel(mark);
  }
  return span;
}

// ------------------------------------------------------------------ tree --
async function loadDir(container, path, depth) {
  let entries;
  try { entries = await api.get('/api/dir?path=' + encodeURIComponent(path)); }
  catch (e) { return toast(e.message, 'err'); }
  rememberMarks(entries);
  for (const entry of entries) {
    const row = document.createElement('div');
    row.className = 'row ' + (entry.dir ? 'folder' : 'file');
    row.style.paddingLeft = 6 + depth * 12 + 'px';
    row.dataset.path = entry.path;
    const caret = document.createElement('span');
    caret.className = 'caret';
    if (entry.dir) caret.innerHTML = CHEVRON;
    const nm = document.createElement('span');
    nm.className = 'nm';
    nm.textContent = entry.name;
    row.append(caret);
    if (!entry.dir) {
      row.append(fileIcon(entry.name, markOf(entry)));
    }
    row.append(nm);
    container.appendChild(row);
    S.rows.set(entry.path, { el: row, dir: entry.dir });

    if (entry.dir) {
      const kids = document.createElement('div');
      kids.className = 'kids hidden';
      container.appendChild(kids);
      row.expand = async () => {
        if (!row.loading) row.loading = loadDir(kids, entry.path, depth + 1);
        await row.loading;
        kids.classList.remove('hidden');
        row.classList.add('open');
        return kids;
      };
      row.addEventListener('click', async () => {
        if (!kids.classList.contains('hidden')) {
          kids.classList.add('hidden');
          row.classList.remove('open');
          return;
        }
        await row.expand();
      });
    } else {
      row.addEventListener('click', () => openFile(entry.path, { preview: true }));
      row.addEventListener('dblclick', () => openFile(entry.path));
    }
  }
  paintTree();
}

/* A new manifest can change what a file is built as, or give a file a node it
   had none of: each folder the tree has opened is listed again and the icons
   whose mark moved are drawn again. Nothing is asked before a tree exists. */
async function refreshFileMarks() {
  const dirs = [''];
  for (const [path, row] of S.rows) if (row.dir && row.el.loading) dirs.push(path);
  // What was known of a file that no folder listed again is no longer known.
  const was = new Map(S.fileMarks);
  S.fileMarks.clear();
  marksAsked.clear();
  for (const dir of dirs) {
    let entries;
    try { entries = await api.get('/api/dir?path=' + encodeURIComponent(dir)); } catch { continue; }
    rememberMarks(entries);
    for (const e of entries) {
      if (e.dir) continue;
      const row = S.rows.get(e.path);
      if (!row || !row.el.isConnected) continue;
      const now = fileMark(e.path);
      if (JSON.stringify(now) === JSON.stringify(was.get(e.path) || null)) continue;
      const old = row.el.querySelector('.ficon');
      if (old) old.replaceWith(fileIcon(e.name, now));
    }
  }
}

// ------------------------------------------------------------ git status --
function ancestorsOf(paths) {
  const out = new Set();
  for (const p of paths) {
    const parts = p.replace(/\/$/, '').split('/');
    for (let i = 1; i < parts.length; i++) out.add(parts.slice(0, i).join('/'));
  }
  return out;
}

function applyGit(info) {
  const files = (list) => new Set(list.filter((p) => !p.endsWith('/')));
  // git collapses an untracked directory into a single entry ending in "/".
  S.gitPrefixes = [...info.modified, ...info.untracked].filter((p) => p.endsWith('/'));
  S.gitMod = files(info.modified);
  S.gitAdded = new Set((info.staged || []).filter((c) => c.code[0] === 'A').map((c) => c.path));
  S.gitUnt = files(info.untracked);
  S.gitModDirs = ancestorsOf(info.modified);
  S.gitUntDirs = ancestorsOf(info.untracked);
  for (const pre of S.gitPrefixes) S.gitUntDirs.add(pre.replace(/\/$/, ''));
  paintBranch(info);
  paintTree();
}

/* The status bar's branch: the branch glyph and its name; git being paused (0121)
   is no branch, so it keeps its words and no glyph. */
function paintBranch(info) {
  const el = $('#status-branch');
  const paused = !info.repo && !!info.paused;
  el.classList.toggle('hidden', !info.repo && !paused);
  el.dataset.paused = String(paused);
  el.querySelector('.bn').textContent = info.repo ? (info.branch || 'detached') : paused ? 'git paused' : '';
}

const underGitPrefix = (path) => S.gitPrefixes.some((pre) => (path + '/').startsWith(pre));

/* git's letter for a file, as the tree and the manifest's card draw it, or null
   for one git has no change in. An unsaved buffer is not git's, so it is not
   here. */
function gitFileMark(path) {
  if (S.gitMod.has(path)) return S.gitAdded.has(path) ? ['a', 'A', 'Added'] : ['m', 'M', 'Modified'];
  if (S.gitUnt.has(path) || underGitPrefix(path)) return ['u', 'U', 'Untracked'];
  return null;
}

function paintTree() {
  const dirtyFiles = new Set([...S.open].filter(([, f]) => f.dirty).map(([p]) => p));
  const dirtyDirs = ancestorsOf(dirtyFiles);
  for (const [path, row] of S.rows) {
    if (!row.el.isConnected) { S.rows.delete(path); continue; }
    let state = '';
    if (row.dir) {
      if (dirtyDirs.has(path)) state = 'unsaved';
      else if (S.gitModDirs.has(path)) state = 'modified';
      else if (S.gitUntDirs.has(path) || underGitPrefix(path)) state = 'untracked';
    } else {
      if (dirtyFiles.has(path)) state = 'unsaved';
      else if (S.gitMod.has(path)) state = 'modified';
      else if (S.gitUnt.has(path) || underGitPrefix(path)) state = 'untracked';
    }
    // git's letter, or the pencil of an unsaved buffer, at the end of the row (0151)
    const mark = state === 'unsaved' ? ['w', '', row.dir ? 'Holds unsaved changes' : 'Unsaved changes']
      : row.dir ? (state === 'modified' ? ['m', 'M', 'Holds changed files'] : state === 'untracked' ? ['u', 'U', 'Holds new files'] : null)
      : gitFileMark(path);
    if (!mark) {
      if (row.gs) { row.gs.remove(); row.gs = null; }
    } else {
      if (!row.gs) { row.gs = document.createElement('span'); row.el.append(row.gs); }
      row.gs.className = 'gs ' + mark[0];
      row.gs.textContent = mark[1];
      row.gs.title = mark[2];
      row.gs.setAttribute('aria-label', mark[2]);
    }
    row.el.classList.toggle('st-unsaved', state === 'unsaved');
    row.el.classList.toggle('st-modified', state === 'modified');
    row.el.classList.toggle('st-untracked', state === 'untracked');
    row.el.title = state === 'unsaved' ? path + '  (unsaved changes)'
      : state === 'modified' ? path + '  (modified, not committed)'
      : state === 'untracked' ? path + '  (untracked)'
      : path;
  }
}

async function refreshGit() {
  try {
    const info = await api.get('/api/git');
    const key = JSON.stringify(info);
    if (key === S.gitKey) return;
    S.gitKey = key;
    S.git = info;
    applyGit(info);
    renderGit(info);
  } catch { /* git missing or not a repo */ }
}

/* Repainted only when the answer changed, like the git poll above: this runs
   every few seconds and the badge is usually saying the same thing. */
async function refreshFreshness() {
  try {
    const f = await api.get('/api/freshness');
    // A poll that read run_results.json while dbt was writing it got the time
    // without the counts; if dbt finished within the same second, the stamp
    // did not move, so the index is asked again until it has them.
    const run = S.reports && S.reports.run;
    if (run && typeof run.error !== 'number') loadReportsIndex();
    const key = JSON.stringify(f);
    if (key === S.freshKey) return;
    S.freshKey = key;
    const was = S.fresh && S.fresh.state;
    S.fresh = f;
    paintFreshness(f);
    // The warnings wait for a manifest that matches the project (0103).
    if (was !== f.state) {
      paintReportsButton();
      remarkUnusedPaths();
    }
    // A run that writes a report moves this stamp, and the index is read again
    // only then. The first answer is only noted: boot has just read it.
    if (S.reportsAt !== undefined && f.reports_at !== S.reportsAt) loadReportsIndex();
    S.reportsAt = f.reports_at;
    // The watcher reloads the manifest when dbt rewrites it, and this poll is
    // the only way the page hears of it. Newer only: the answer is cached for
    // a moment, so it can trail a reload the button has just made. The canvas
    // is not redrawn beyond following the tab in front, because dbt run
    // rewrites the manifest too, and a graph reset under the pointer at every
    // run would be worse than one a click behind.
    if (S.meta && f.manifest_at > (S.meta.manifest_mtime || 0)) {
      applyInfo(await api.get('/api/meta'));
      followActive();
    }
  } catch { /* the badge is the one thing that must never interrupt anything */ }
}

function paintFreshness(f) {
  const el = $('#fresh-badge');
  const b = freshnessBadge(f, !freshnessRuns(S.pathReadsCwd));
  el.classList.remove('hidden');
  // On the pill as well as the badge: the pill's outline takes the tone, and
  // the tour and the pictures read the badge's.
  el.dataset.tone = b.tone;
  $('#manifest-pill').dataset.tone = b.tone;
  el.querySelector('.lbl').textContent = b.label;
  el.querySelector('.age').textContent = b.age;
  el.querySelector('.drift').textContent = b.drift;
  // No `title`: the card says all of this, and a native tooltip on top of it
  // would arrive a second later and say it again.
  el.setAttribute('aria-label', b.head + '. ' + b.desc);
  // An open card follows the answer, its focus kept on the same button.
  const card = S.freshCard;
  if (card && card.isConnected) {
    card.dataset.tone = b.tone;
    redrawFreshCard(card, f);
    markFreshCard(card, f);
    if (popup && popup.el === card) placePopup($('#manifest-pill'), card);
  }
}

/* The card's file icons take the colour the manifest builds each file as, which
   S.fileMarks only knows for the folders something has listed: the rest are
   asked once each, by their folder, and the card is drawn again when one
   answered (0151). */
function markFreshCard(card, f) {
  askMarks([...(f.committed || []), ...(f.edited || [])]).then((gained) => {
    if (gained && S.freshCard === card && card.isConnected) redrawFreshCard(card, S.fresh);
  });
}

/* The card drawn again, but not for its two ages ("written ..., 12s ago" and
   "last fetched 5s ago"), which move at every poll in the first minute: a
   redraw for those would replace every button under the pointer and drop a
   click half made. They are rewritten in place, and everything else goes
   through redrawIfChanged. */
function redrawFreshCard(card, f) {
  const ageless = (box) => {
    const copy = box.cloneNode(true);
    copy.querySelectorAll('[data-age]').forEach((e) => { e.textContent = ''; });
    return copy.outerHTML;
  };
  const probe = card.cloneNode(false);
  fillFreshCard(probe, f);
  if (ageless(probe) === ageless(card)) {
    const fresh = [...probe.querySelectorAll('[data-age]')];
    [...card.querySelectorAll('[data-age]')].forEach((e, i) => { e.textContent = fresh[i].textContent; });
    return;
  }
  redrawIfChanged(card, (box) => fillFreshCard(box, f));
}

function markTreeSelection(path) {
  $$('#tree .row').forEach((r) => r.classList.toggle('sel', r.dataset.path === path));
}

/* Reveals a path in the tree, expanding folders as needed. */
async function revealInTree(path, { expand = false } = {}) {
  const parts = path.split('/');
  let container = $('#tree');
  // `expand` walks one level further, so the folder clicked opens rather than
  // sitting selected and shut.
  for (let i = 0; i < parts.length - (expand ? 0 : 1); i++) {
    const sub = parts.slice(0, i + 1).join('/');
    const row = [...container.children].find((c) => c.dataset && c.dataset.path === sub);
    if (!row || !row.expand) return false;
    container = await row.expand();
  }
  markTreeSelection(path);
  const row = $$('#tree .row').find((r) => r.dataset.path === path);
  if (row) row.scrollIntoView({ block: 'nearest' });
  return !!row;
}

/* Everything the tree knows about what is open is in the DOM, from loadDir: a
   folder is open when its `.kids` is not hidden. So a global collapse is those
   two classes and nothing to keep in step. The children stay in the DOM, held
   by row.loading, so reopening a folder asks /api/dir nothing a second time. */
function collapseTree() {
  $$('#tree .kids').forEach((k) => k.classList.add('hidden'));
  $$('#tree .row.open').forEach((r) => r.classList.remove('open'));
}

/* The companion of the collapse: after flattening the tree, the file being
   edited is the one folder worth reopening. */
function revealActive() {
  const path = S.active ? projectPath(S.active) : '';
  if (!path) return toast('no file to reveal');
  revealInTree(path);
}

// ------------------------------------------------------------ model list --
let modelTimer = null;
async function refreshModels() {
  const q = $('#model-filter').value;
  const list = $('#model-list');
  const hits = await api.get(`/api/search?q=${encodeURIComponent(q)}&kind=model,source,seed,snapshot&limit=300`);
  list.textContent = '';
  for (const h of hits) {
    const row = document.createElement('div');
    row.className = 'row';
    const nm = document.createElement('span');
    nm.className = 'nm';
    nm.textContent = h.name;
    const sub = document.createElement('span');
    sub.className = 'sub';
    sub.textContent = h.disabled ? 'disabled' : h.kind === 'source' ? 'source' : (h.materialized || h.kind);
    if (h.disabled) row.classList.add('off');
    row.append(dot(h), nm, sub);
    row.title = h.file;
    // A click here asks for the lineage and the Catalog, which the reports
    // cover; focusNode cannot close them itself, since a run's end calls it.
    row.addEventListener('click', () => { closePanel(); focusNode(h.id, { open: false }); });
    row.addEventListener('dblclick', () => { closePanel(); focusNode(h.id, { open: true }); });
    list.appendChild(row);
  }
  if (!hits.length) list.innerHTML = '<p class="muted pad">No match.</p>';
}


// --------------------------------------------------------------- git panel --
/* A modal that resolves to the id of the button pressed, or null if dismissed.
   Used for every action that cannot simply be undone. */
function modal({ title, body, actions, wide = false, onOpen = null }) {
  return new Promise((resolve) => {
    const box = $('#modal');
    box.querySelector('.modal-box').classList.toggle('wide', wide);
    $('#modal-title').textContent = title;
    const host = $('#modal-body');
    host.textContent = '';
    host.append(body);
    const bar = $('#modal-actions');
    bar.textContent = '';
    // Taken here: nothing under the dialog closes on the same Escape.
    const esc = (e) => { if (e.key === 'Escape') { e.preventDefault(); close(null); } };
    let done = false;
    // Every way out removes the Escape listener. It used to be removed only on
    // Escape, so each button close left one behind.
    const close = (value) => {
      if (done) return;
      done = true;
      document.removeEventListener('keydown', esc);
      box.classList.add('hidden');
      resolve(value);
    };
    for (const a of actions) {
      const b = document.createElement('button');
      b.className = 'btn ' + (a.style || '');
      b.textContent = a.label;
      b.addEventListener('click', () => close(a.id));
      bar.appendChild(b);
    }
    box.classList.remove('hidden');
    box.onclick = (e) => { if (e.target === box) close(null); };
    document.addEventListener('keydown', esc);
    bar.lastChild && bar.lastChild.focus();
    // For a body that closes the modal on an answer of its own. This close
    // is this modal's alone: by the time an answer lands, the box may hold
    // another one, whose last button a click on the box would confirm.
    if (onOpen) onOpen(close);
  });
}

const para = (text) => { const p = document.createElement('p'); p.textContent = text; p.style.margin = '0 0 8px'; return p; };
const list = (items) => {
  const ul = document.createElement('ul');
  items.slice(0, 40).forEach((i) => { const li = document.createElement('li'); li.textContent = i; ul.appendChild(li); });
  if (items.length > 40) ul.appendChild(Object.assign(document.createElement('li'), { textContent: `… ${items.length - 40} more` }));
  return ul;
};
const pre = (text) => { const p = document.createElement('pre'); p.textContent = text.trim(); return p; };

/* Shows whatever git actually said. Pre-commit hooks fail here, so the output
   matters more than a tidy message. */
async function gitPost(path, body) {
  let res;
  try {
    res = await api.send('/api/git/' + path, 'POST', body || {});
  } catch (e) {
    toast('git: ' + e.message, 'err');
    return null;
  }
  await refreshGit();
  // A pull, a checkout or an abort rewrites files that may be open.
  refreshOpenFiles();
  return res;
}

async function showGitFailure(title, res) {
  const body = document.createElement('div');
  body.append(para('git exited with code ' + res.code + '.'));
  if (res.stderr.trim()) body.append(pre(res.stderr));
  if (res.stdout.trim()) body.append(pre(res.stdout));
  await modal({ title, body, actions: [{ id: 'ok', label: 'Close' }] });
}

/* What the branch row says of the distance to the upstream, in words: each
   part has its tone (the commits to pull are the ones to act on, so they take
   the warning colour), and the title names the upstream. Nothing when level or
   when there is no upstream (0165). */
function aheadBehindWords(info) {
  const ahead = (info && info.upstream && info.ahead) || 0;
  const behind = (info && info.upstream && info.behind) || 0;
  const commits = (n) => n + (n === 1 ? ' commit' : ' commits');
  const parts = [], said = [];
  if (ahead) {
    parts.push({ text: ahead + ' ahead', tone: 'ahead' });
    said.push(`this branch has ${commits(ahead)} ${info.upstream} does not have`);
  }
  if (behind) {
    parts.push({ text: behind + ' behind', tone: 'behind' });
    said.push(`${info.upstream} has ${commits(behind)} this branch does not have`);
  }
  return { parts, title: said.join('; ') };
}

/* What each of the three glyphs would do, as its title says, so that no badge
   has to carry the count. Push stays clickable with nothing to push: the modal
   says why. */
function gitActionTitles(info) {
  const ahead = (info && info.upstream && info.ahead) || 0;
  const behind = (info && info.upstream && info.behind) || 0;
  return {
    fetch: 'Fetch from origin',
    pull: behind ? `Pull ${behind} commit${behind === 1 ? '' : 's'} (fast-forward only)` : 'Pull (fast-forward only)',
    // Without an upstream the push publishes the branch, setting it (doPush).
    push: ahead ? `Push ${ahead} commit${ahead === 1 ? '' : 's'}`
      : info && info.repo && !info.upstream ? 'Push this branch to origin (sets its upstream)' : 'Nothing to push',
  };
}

/* What the push dialog says beside its list of commits: nothing when there are
   some, else a branch without an upstream publishes itself and one with an
   upstream has nothing to send, level or only behind. One reading used to cover
   both, and was false for the second. */
function pushNote(info, commits) {
  if (commits.length) return '';
  return info && info.upstream
    ? `${info.upstream} already has every commit of ${info.branch}: nothing to push.`
    : 'No upstream yet, so this is the first push of this branch.';
}

/* The commit button says what it would commit. During a merge it finishes the
   merge, once nothing is conflicted; with conflicts left it names the way out. */
function commitButtonText(info) {
  if (!info || !info.repo) return 'Commit';
  if (info.conflicted.length) return 'Resolve the conflicts first';
  if (info.merging) return 'Commit the merge';
  const n = info.staged.length;
  return n ? `Commit ${n} file${n === 1 ? '' : 's'}` : 'Stage a file to commit';
}

/* Whether a click would commit: files staged, or a merge with nothing conflicted. */
function commitReady(info) {
  return !!info && !!info.repo && !info.conflicted.length && (info.merging || info.staged.length > 0);
}

/* The letter git shows for a file, and the class that colours it: the tree's
   colours for a modified or new file, red for a deletion and for a conflicted
   file, the snapshot colour for a rename. */
function gitLetterClass(letter, conflicted) {
  if (conflicted) return 'x';
  return { M: 'm', A: 'a', U: 'u', D: 'd', R: 'r' }[letter] || 'q';
}

/* Whether a row (its top and bottom) is not wholly inside the list it sits in:
   only then does giving it the keyboard scroll the list. */
function outOfView(top, bottom, hostTop, hostBottom) {
  return top < hostTop || bottom > hostBottom;
}

function paintCommit() {
  const btn = $('#commit-btn');
  if (!btn) return;
  const ready = commitReady(S.git);
  btn.disabled = S.committing;
  btn.textContent = S.committing ? 'Fetching, then committing…' : commitButtonText(S.git);   // hooks can take a while
  btn.classList.toggle('primary', ready || S.committing);
  btn.setAttribute('aria-disabled', ready || S.committing ? 'false' : 'true');
}

/* The row of the diff tab in front is marked, as the tree marks its file. */
function markGitCurrent() {
  for (const r of $$('#git-body .git-row')) {
    if (r.dataset.path && S.active === 'diff:' + r.dataset.path) r.setAttribute('aria-current', 'true');
    else r.removeAttribute('aria-current');
  }
}

function renderGit(info) {
  const host = $('#git-body');
  if (!host) return;
  $('#branch-name').textContent = info.repo ? (info.branch || 'detached HEAD') : info.paused ? 'git paused' : 'no repository';
  const badge = $('#git-badge');
  const changes = info.staged.length + info.unstaged.length + info.untracked.length + info.conflicted.length;
  badge.textContent = String(changes);
  badge.classList.toggle('hidden', changes === 0);
  const ab = aheadBehindWords(info);
  const abEl = $('#git-ahead-behind');
  abEl.textContent = '';
  ab.parts.forEach((part, i) => {
    if (i) abEl.append(document.createTextNode(', '));
    abEl.append(Object.assign(document.createElement('span'), { className: 'ab-' + part.tone, textContent: part.text }));
  });
  abEl.title = ab.title;
  abEl.classList.toggle('hidden', !ab.parts.length);
  const titles = gitActionTitles(info);
  for (const [id, title] of [['#git-fetch', titles.fetch], ['#git-pull', titles.pull], ['#git-push', titles.push]]) {
    const el = $(id);
    el.title = title;
    el.setAttribute('aria-label', title);
  }
  paintCommit();

  // The rebuild below would drop the keyboard from a row or its action: it is
  // given back to the same path's row, in the same section when it is still there.
  // Only to one that held it by keyboard: a click on a button focuses it too,
  // and giving that back would scroll the list and leave the action shown.
  const was = document.activeElement;
  const had = host.contains(was) && was.matches(':focus-visible') ? was.closest('.git-row') : null;
  const keep = had && { path: had.dataset.path, sec: had.dataset.sec, act: was.classList.contains('act') };
  // Stage all and Unstage all are pressed from the keyboard too: the link is given back by its section.
  const keepLink = host.contains(was) && was.classList.contains('glink') && was.matches(':focus-visible')
    ? was.closest('.git-sec').dataset.sec : null;

  host.textContent = '';
  if (!info.repo) {
    const said = info.paused ? gitPausedNote(info.paused) : 'Not a git repository.';
    host.append(Object.assign(document.createElement('div'), { className: 'git-empty', textContent: said }));
    return;
  }

  if (info.merging) {
    const banner = document.createElement('div');
    banner.className = 'conflict-banner';
    banner.append(document.createTextNode(
      info.conflicted.length
        ? `Merge in progress, ${info.conflicted.length} file(s) still conflicted. Edit them, then mark each resolved.`
        : 'Merge in progress, all conflicts resolved. Commit to finish it.'));
    const abort = document.createElement('button');
    abort.className = 'btn sm danger';
    abort.style.marginTop = '7px';
    abort.textContent = 'Abort merge';
    abort.addEventListener('click', abortMerge);
    banner.append(document.createElement('br'), abort);
    host.append(banner);
  }

  let inSection = '';
  const section = (label, count, action) => {
    inSection = label;
    const h = document.createElement('div');
    h.className = 'git-sec';
    h.dataset.sec = label;
    h.append(document.createTextNode(label));
    const n = document.createElement('span');
    n.className = 'n';
    n.textContent = count;
    h.append(n, Object.assign(document.createElement('div'), { className: 'grow' }));
    if (action) {
      const a = document.createElement('button');
      a.type = 'button';
      a.className = 'glink';
      a.textContent = action.label;
      a.addEventListener('click', action.run);
      h.append(a);
    }
    host.append(h);
  };

  const row = (path, code, button, conflicted) => {
    const r = document.createElement('div');
    r.className = 'git-row';
    r.dataset.path = path;
    r.dataset.sec = inSection;
    r.tabIndex = 0;
    const letter = code.trim()[0] || '?';
    const c = document.createElement('span');
    c.className = 'gs ' + gitLetterClass(letter, conflicted);
    c.textContent = letter;
    const icon = fileIcon(path, fileMark(path));
    // A model's file in a folder the tree has not opened: its mark is asked once, by its folder.
    askMarks([path]).then((gained) => {
      if (gained && icon.isConnected) icon.replaceWith(fileIcon(path, fileMark(path)));
    });
    const nm = document.createElement('span');
    nm.className = 'nm';
    nm.textContent = base(path);
    const dir = document.createElement('span');
    dir.className = 'dir';
    dir.textContent = path.includes('/') ? dirOf(path) : '';
    r.append(c, icon, nm, dir);
    if (button) {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'act';
      b.title = button.title;
      b.setAttribute('aria-label', button.title);
      b.textContent = button.glyph;
      b.addEventListener('click', (e) => { e.stopPropagation(); button.run(); });
      r.append(b);
    }
    r.title = path + '  (click to see the changes)';
    r.addEventListener('click', () => openDiff(path));
    // The action is a stop of its own: Enter and Space on the row open the diff.
    r.addEventListener('keydown', (e) => {
      if (e.target !== r || (e.key !== 'Enter' && e.key !== ' ')) return;
      e.preventDefault();
      openDiff(path);
    });
    host.append(r);
  };

  if (info.conflicted.length) {
    section('Conflicts', info.conflicted.length);
    info.conflicted.forEach((p) => row(p, 'U', {
      glyph: '✓', title: 'Mark resolved (git add)',
      run: () => markResolved(p),
    }, true));
  }
  if (info.staged.length) {
    section('Staged', info.staged.length, { label: 'Unstage all', run: () => gitPost('unstage', { paths: info.staged.map((f) => f.path) }) });
    info.staged.forEach((f) => row(f.path, f.code[0], {
      glyph: '−', title: 'Unstage', run: () => gitPost('unstage', { paths: [f.path] }),
    }));
  }
  const pending = [...info.unstaged.map((f) => ({ path: f.path, code: f.code[1] })),
                   ...info.untracked.map((p) => ({ path: p, code: 'U' }))];
  if (pending.length) {
    section('Changes', pending.length, { label: 'Stage all', run: () => gitPost('stage', { paths: pending.map((f) => f.path) }) });
    pending.forEach((f) => row(f.path, f.code, {
      glyph: '+', title: 'Stage', run: () => gitPost('stage', { paths: [f.path] }),
    }));
  }
  if (!changes) {
    host.append(Object.assign(document.createElement('div'), { className: 'git-empty', textContent: 'Working tree clean.' }));
  }
  markGitCurrent();
  // The section may be gone once everything moved: then the keyboard has no link to return to.
  if (keepLink) {
    const link = host.querySelector(`.git-sec[data-sec="${keepLink}"] .glink`);
    if (link) link.focus({ preventScroll: true });
  }
  if (keep) {
    const rows = [...host.querySelectorAll('.git-row')].filter((r) => r.dataset.path === keep.path);
    const same = rows.find((r) => r.dataset.sec === keep.sec);
    const row = same || rows[0];
    // An action means another thing in another section: only the row is given back then.
    const act = same && keep.act && row.querySelector('.act');
    // The row first: the action is shown only while the row holds the keyboard.
    // The list stays where it is unless the row is out of its view.
    if (row) {
      const r = row.getBoundingClientRect(), h = host.getBoundingClientRect();
      row.focus({ preventScroll: !outOfView(r.top, r.bottom, h.top, h.bottom) });
    }
    if (act) act.focus({ preventScroll: true });
  }
}

async function markResolved(path) {
  const doc = S.open.get(path);
  if (doc && doc.dirty && !confirm(`${base(path)} has unsaved changes. Save it before marking resolved?`)) return;
  // Not written, failed or declined, the file still holds what it held: maybe
  // its markers, which staging would commit.
  if (doc && doc.dirty && !(await saveFile(path))) return;
  const res = await gitPost('stage', { paths: [path] });
  if (res && !res.ok) showGitFailure('Could not mark resolved', res);
  else toast('marked resolved: ' + base(path), 'ok');
  renderTabs();
}

async function abortMerge() {
  const body = document.createElement('div');
  body.append(para('This runs git merge --abort. The merge is undone and the working tree returns to where it was before it started.'));
  if (await modal({ title: 'Abort the merge?', body,
                    actions: [{ id: null, label: 'Cancel' }, { id: 'go', label: 'Abort merge', style: 'danger' }] }) !== 'go') return;
  const res = await gitPost('merge-abort');
  if (res && !res.ok) showGitFailure('Abort failed', res);
  else toast('merge aborted', 'ok');
}

async function doCommit() {
  const message = $('#commit-msg').value.trim();
  if (!message) return toast('write a commit message first');
  const info = S.git;
  if (info && info.conflicted.length) return toast('resolve the conflicts first', 'err');
  if (info && !info.staged.length && !info.merging) return toast('nothing staged: stage some files first', 'err');
  if (S.committing) return;

  S.committing = true;
  paintCommit();
  const res = await gitPost('commit', { message });
  S.committing = false;
  paintCommit();
  if (!res) return;
  if (!res.ok) return showGitFailure('Commit failed', res);
  $('#commit-msg').value = '';
  toast('committed', 'ok');
  if (res.fetch_note) toast(res.fetch_note, 'err');
}

async function doPush() {
  let commits = [];
  try { commits = await api.get('/api/git/outgoing'); } catch { /* no upstream yet */ }
  const info = S.git || {};
  const body = document.createElement('div');
  body.append(para(`Pushing ${info.branch} to origin${info.upstream ? '' : ' (and setting it as upstream)'}.`));
  body.append(commits.length ? list(commits) : para(pushNote(info, commits)));
  if (await modal({ title: 'Push to origin?', body,
                    actions: [{ id: null, label: 'Cancel' }, { id: 'go', label: 'Push', style: 'primary' }] }) !== 'go') return;
  const res = await gitPost('push');
  if (res && !res.ok) showGitFailure('Push failed', res);
  else toast('pushed', 'ok');
}

async function doPull() {
  const res = await gitPost('pull');
  if (!res) return;
  if (!res.ok) {
    if (/diverge|not possible to fast-forward/i.test(res.stderr)) {
      const body = document.createElement('div');
      body.append(para('Your branch and origin have diverged, so a fast-forward is impossible.'));
      body.append(para('dbt-edith will not pick a merge or a rebase for you: run the one you want in the terminal.'));
      body.append(pre(res.stderr));
      return modal({ title: 'Cannot fast-forward', body, actions: [{ id: 'ok', label: 'Close' }] });
    }
    return showGitFailure('Pull failed', res);
  }
  toast(res.stdout.includes('Already up to date') ? 'already up to date' : 'pulled', 'ok');
}

// ------------------------------------------------------------ branch picker --
let branchHits = [], branchIndex = 0;

async function openBranches() {
  const box = $('#branches');
  box.classList.remove('hidden');
  const input = $('#branch-filter');
  input.value = '';
  input.focus();
  try { branchHits = await api.get('/api/git/branches'); }
  catch (e) { return toast('git: ' + e.message, 'err'); }
  paintBranches('');
}

function paintBranches(query) {
  const q = query.trim().toLowerCase();
  const rows = branchHits.filter((b) => !q || b.name.toLowerCase().includes(q)).slice(0, 80);
  branchIndex = 0;
  const host = $('#branch-results');
  host.textContent = '';
  rows.forEach((b, i) => {
    const r = document.createElement('div');
    r.className = 'pres' + (i === 0 ? ' on' : '');
    const p1 = document.createElement('span');
    p1.className = 'p1';
    p1.textContent = b.name;
    if (b.current) p1.style.color = 'var(--accent)';
    const p2 = document.createElement('span');
    p2.className = 'p2';
    p2.textContent = (b.current ? 'current · ' : '') + b.when;
    r.append(p1, p2);
    r.addEventListener('click', () => chooseBranch(b));
    host.appendChild(r);
  });
  host.dataset.rows = rows.length;
  branchHits.visible = rows;
}

function moveBranch(delta) {
  const rows = $$('#branch-results .pres');
  if (!rows.length) return;
  rows[branchIndex].classList.remove('on');
  branchIndex = (branchIndex + delta + rows.length) % rows.length;
  rows[branchIndex].classList.add('on');
  rows[branchIndex].scrollIntoView({ block: 'nearest' });
}

async function chooseBranch(b) {
  $('#branches').classList.add('hidden');
  if (b.current) return;
  const res = await gitPost('checkout', { branch: b.name, stash: false });
  if (!res) return;
  if (res.ok) return toast('switched to ' + b.name, 'ok');

  // git refused. Never force: show what is in the way and let the user choose.
  const blocking = res.blocking || [];
  const body = document.createElement('div');
  body.append(para(`git will not switch to ${b.name} because local changes would be overwritten.`));
  if (blocking.length) body.append(list(blocking));
  else body.append(pre(res.stderr));
  body.append(para('Stashing puts those changes aside, tagged with the branch you are leaving, and git stash pop brings them back. Nothing is discarded.'));
  const choice = await modal({
    title: 'Switch blocked',
    body,
    actions: [{ id: null, label: 'Cancel' }, { id: 'stash', label: 'Stash and switch', style: 'primary' }],
  });
  if (choice !== 'stash') return;
  const second = await gitPost('checkout', { branch: b.name, stash: true });
  if (second && !second.ok) showGitFailure('Switch still failed', second);
  else toast('stashed, then switched to ' + b.name, 'ok');
}

// ------------------------------------------------------------- conflicts ----
/* Decorates the <<<<<<< ======= >>>>>>> blocks git leaves behind, and offers a
   one-click choice per block. */
/* Locates the conflict blocks in a text. A block only counts once all three
   markers have been seen in order, so half-edited files are simply ignored
   rather than half-resolved. */
function findConflicts(text) {
  const blocks = [];
  let open = null;
  text.split('\n').forEach((line, i) => {
    if (line.startsWith('<<<<<<<')) open = { start: i, mid: -1 };
    else if (line.startsWith('=======') && open && open.mid < 0) open.mid = i;
    else if (line.startsWith('>>>>>>>') && open && open.mid >= 0) { blocks.push({ start: open.start, mid: open.mid, end: i }); open = null; }
  });
  return blocks;
}

function decorateConflicts(cm) {
  (cm.state.conflictWidgets || []).forEach((w) => w.clear());
  cm.state.conflictWidgets = [];
  cm.eachLine((line) => {
    cm.removeLineClass(line, 'background', 'cm-conflict-head');
    cm.removeLineClass(line, 'background', 'cm-conflict-mid');
  });

  const blocks = findConflicts(cm.getValue());
  if (!blocks.length) return 0;

  for (const b of blocks) {
    cm.addLineClass(b.start, 'background', 'cm-conflict-head');
    cm.addLineClass(b.mid, 'background', 'cm-conflict-mid');
    cm.addLineClass(b.end, 'background', 'cm-conflict-head');
    const bar = document.createElement('div');
    bar.className = 'conflict-bar';
    for (const [label, side] of [['Keep ours', 'ours'], ['Keep theirs', 'theirs'], ['Keep both', 'both']]) {
      const btn = document.createElement('button');
      btn.textContent = label;
      btn.addEventListener('click', () => resolveBlock(cm, b, side));
      bar.appendChild(btn);
    }
    cm.state.conflictWidgets.push(cm.addLineWidget(b.start, bar, { above: true }));
  }
  return blocks.length;
}

function resolveBlock(cm, b, side) {
  const ours = cm.getRange({ line: b.start + 1, ch: 0 }, { line: b.mid, ch: 0 });
  const theirs = cm.getRange({ line: b.mid + 1, ch: 0 }, { line: b.end, ch: 0 });
  const keep = side === 'ours' ? ours : side === 'theirs' ? theirs : ours + theirs;
  cm.replaceRange(keep, { line: b.start, ch: 0 }, { line: b.end + 1, ch: 0 });
  decorateConflicts(cm);
}

// ---------------------------------------------------------------- lineage --
/* The depth is how far a walk on the canvas has looked around: a box
   double-clicked keeps it, as a +N badge raises it. A model reached any other
   way, from the palette, a tab, a link or the Catalog's lists, is a fresh
   start, and leaving the depth of the last one drew a graph nobody asked for.
   Back and Forward are returns, and bring back the depth they left (jump). */
async function focusNode(id, { open = false, keepDepth = false } = {}) {
  closeHoverCard();
  if (id !== S.focus && !keepDepth) {
    for (const el of [$('#up'), $('#down')]) el.value = el.defaultValue;
  }
  S.focus = id;
  S.jobsFor = null;
  S.unsynced = '';
  S.graphMode = 'model';
  S.colFocus = null;
  S.colDraw++;                                // a column answer still on its way is not drawn over this
  leaveColumnWait();
  askDepth('m|' + id);
  paintMode();
  const up = +$('#up').value, down = +$('#down').value;
  const tests = testsOn() ? 1 : 0;
  try {
    const [sub, detail] = await Promise.all([
      api.get(`/api/lineage?id=${encodeURIComponent(id)}&up=${up}&down=${down}&tests=${tests}`),
      nodeDetail({ id }),
    ]);
    // Another node, a column or a selection asked for since draws instead:
    // the selection's panel rolled up redraws the model it covered while the
    // file opened draws its own.
    if (S.graphMode !== 'model' || S.focus !== id) return;
    $('#lineage-empty').classList.add('hidden');
    const drawn = Lineage.render(sub, canvasOptions());
    $('#lineage-status').textContent = canvasStatus(sub, drawn);
    landDepth('m|' + id, sub);
    paintLegend(sub);
    paintTestsCount(sub);
    renderCatalog(detail);
    for (const kind of ['compiled', 'run']) {
      if (!$('#dock-' + kind).classList.contains('hidden')) loadArtifact(kind, id);
    }
    if (S.dock === 'jobs') loadJobs();
    if (open && detail.file) openFile(detail.file, { focusLineage: false });
  } catch (e) { toast('lineage: ' + e.message, 'err'); }
}

/* Column nodes carry a composite id, "<unique_id>::<column>". Model nodes carry
   a bare unique_id, and a dbt unique_id never contains "::". */
function splitColId(id) {
  const at = id.indexOf('::');
  return at < 0 ? { node: id, column: '' } : { node: id.slice(0, at), column: id.slice(at + 2) };
}

/* Whether a column asked for now would be drawn from a cache that is about to
   change: collin is the tool and a run is on. Only collin's cache is rewritten
   by a run, so no other tool waits (0042). */
function collinRunning(tool, collin) {
  return tool === 'collin' && !!collin && collin.state === 'running';
}

/* The canvas stops waiting for a collin run, however that came about: the
   hint and the status line it set go with it, so that nothing leaves a
   drawing that traces itself over a canvas that will not be drawn by itself. */
function leaveColumnWait() {
  if (!S.colWait) return;
  S.colWait = false;
  $('#lineage-empty').classList.add('hidden');
  $('#lineage-empty').classList.remove('waiting');
  dropWaitArm();
  $('#lineage-status').textContent = '';
}

/* Column-level lineage. Sibling of focusNode: same canvas, same pan/zoom, the
   nodes are columns instead of models. */
async function focusColumn(id, column) {
  S.graphMode = 'column';
  // The stop at menu counts the graph drawn: another column's says nothing
  // of this one, so a menu opened before the answer counts none.
  if (!S.colFocus || S.colFocus.id !== id || S.colFocus.column !== column) S.colSub = null;
  S.colFocus = { id, column };
  // The levels the depth menus list are this canvas's own: the roles stopped at,
  // the indirect button and the cap a click lifted change them (0158).
  // Not the depth downstream: the levels do not depend on it, so a pick there keeps them.
  const upNow = +$('#up').value;
  const askedKey = colAskKey(id, column, upNow, +$('#down').value, S.colCut, S.colIndirect);
  const depthKey = ['c', id, column, upNow, [...S.colCut].sort().join(','), S.colIndirect ? 1 : 0, colRaiseFor(S.colRaise, askedKey)].join('|');
  askDepth(depthKey);
  paintMode();
  // The cache on disk is the one the run is replacing, and drawing it would
  // show a column that is about to change, or the model's own canvas under a
  // column's chip. The canvas waits, cleared, and whatever column was asked for
  // last is drawn by the redraw the run's end makes (0042).
  if (collinRunning(S.cllTool, S.collin)) {
    ++S.colDraw;                              // a column answer still on its way is not drawn over the wait
    S.colWait = true;
    S.colSub = null;
    Lineage.clear();
    paintColCap(null);
    // Emptied here and not through paintLegend, which would drop the pick: the
    // column drawn at the end gets it back.
    $('#lineage-legend').textContent = '';
    paintTestsCount(null);
    if (stopAtMenu) stopAtMenu.recount([]);
    emptyHint(`collin is running over the compiled SQL: ${column}'s lineage is drawn once it ends`,
      { waiting: true, column });
    // The centre says it: the status line would say it twice.
    $('#lineage-status').textContent = '';
    showDock('lineage');
    return;
  }
  const up = +$('#up').value, down = +$('#down').value;
  // Drawing past the cap was asked for this request and no other: any change
  // of column, depth, stop or indirect button is cut at the cap again, so a
  // slow canvas never becomes the default (0118).
  const key = colAskKey(id, column, up, down, S.colCut, S.colIndirect);
  const raise = colRaiseFor(S.colRaise, key);
  if (!raise) S.colRaise = null;
  const ask = ++S.colDraw;
  try {
    const sub = await api.get(
      `/api/collineage?id=${encodeURIComponent(id)}&column=${encodeURIComponent(column)}&up=${up}&down=${down}`
      + (S.colCut.size ? `&cut=${encodeURIComponent([...S.colCut].join(','))}` : '')
      + (S.colIndirect ? '&indirect=1' : '')
      + (raise ? `&max=${raise}` : ''));
    if (ask !== S.colDraw) return;            // a later tick or click already asked
    S.colSub = sub;
    if (stopAtMenu) stopAtMenu.recount(sub.edge_kinds);
    S.colWait = false;
    $('#lineage-empty').classList.add('hidden');
    const drawn = Lineage.render(sub, canvasOptions());
    $('#lineage-status').textContent = canvasStatus(sub, drawn);
    landDepth(depthKey, sub);
    paintColCap(colCapOffer(sub, raise), (max) => {
      S.colRaise = { key, max };
      focusColumn(id, column);
    });
    paintLegend(sub);
    paintTestsCount(sub);
    showDock('lineage');
  } catch (e) {
    if (ask !== S.colDraw) return;
    toast('column lineage: ' + e.message, 'err');
    // The hint and the ring of a wait this draw followed go with it, and the
    // canvas, cleared for the wait, gets its model back.
    const fromWait = S.colWait;
    leaveColumnWait();
    S.graphMode = 'model';
    S.colFocus = null;
    S.colSub = null;
    closeStopAt();
    // The column's levels are not the model's: an answer under the same key
    // would otherwise leave them in the model's menus.
    askDepth('');
    paintMode();
    if (fromWait) focusNode(id);
  }
}

/* What a request for a column's canvas is, for the cap a click lifted: the
   column, how far each way, the roles stopped at and the indirect button.
   Anything else changed is another request. */
function colAskKey(id, column, up, down, cut, indirect) {
  return [id, column, up, down, [...cut].sort().join(','), indirect ? 1 : 0].join('|');
}

/* The ceiling a click lifted, `prev` being {key, max}: for that request and
   nothing else (0118), as raiseFor() is for a selection. */
function colRaiseFor(prev, key) {
  return prev && prev.key === key ? prev.max : 0;
}

/* The button beside a column canvas cut at the cap: the most the server says
   it draws, `most`, this time only, since past the cap every step of zoom and
   pan slows (0118, as capOffer() is for a selection). Nothing once it was
   drawn at that. Draws up to it, never "all": the walk does not know the
   total, only that it was turned away. */
function colCapOffer(sub, asked) {
  const most = (sub && sub.most) || 0;
  if (!sub || !sub.truncated || !most || asked >= most) return null;
  return {
    max: most,
    label: `Draw up to ${most}`,
    hint: 'slower to zoom and pan',
    title: `Draws up to ${most} boxes of this column's lineage, the most there is, this time only. `
      + 'Past the cap, zooming and panning slow down, a lot on a slow machine; '
      + 'another column, depth or stop cuts it at the cap again.',
  };
}

/* The offer's button, over the status line, or nothing. */
function paintColCap(offer, draw) {
  const host = $('#lineage-cap');
  if (!host) return;
  host.textContent = '';
  host.classList.toggle('hidden', !offer);
  if (!offer) return;
  const button = Object.assign(document.createElement('button'), {
    type: 'button', className: 'btn sm', textContent: offer.label, title: offer.title,
  });
  button.addEventListener('click', () => {
    button.disabled = true;
    button.textContent = 'Drawing…';
    draw(offer.max);
  });
  host.append(button, Object.assign(document.createElement('span'), { className: 'caphint', textContent: offer.hint }));
}

/* Every control that used to re-run focusNode has to respect the current mode. */
const rerender = () => S.graphMode === 'select'
  ? runSelection()
  : (S.graphMode === 'column' && S.colFocus)
    ? focusColumn(S.colFocus.id, S.colFocus.column)
    : (S.focus ? focusNode(S.focus) : undefined);

/* How the canvas draws what it is sent, in every mode. The by folder toggle
   hands the layout this project's package, which is how it tells the
   project's own folders from an installed package's (0029). */
function canvasOptions() {
  return {
    folders: foldersOn() ? ((S.meta && S.meta.project) || '') : null,
    levels: folderLevels(),
    adapter: (S.meta && S.meta.adapter) || '',
    builds: buildsSpec(),
  };
}

// ------------------------------------------------------------- selection --
/* A dbt selector expression, resolved by the server against the manifest and
   drawn as a set rather than as a neighbourhood of one node. dbt is never run
   for it (0024): the terminal button is how you check that against dbt itself. */
let selectTimer = null;

/* The Lineage space, over the whole window, in a panel of its own (0092, 0101,
   0140). The canvas is one: the dock's lineage pane, the selector bar over
   it, comes up into the panel while it is down, with the canvas's own tools
   and the Catalog, in a card beside the canvas once a box is clicked. All of
   it goes back to the dock as the panel rolls up. Moved rather than copied,
   so the canvas keeps its listeners, its find bar and its folder names. */
const SELECT_MOVES = [
  ['#dock-lineage', '#selpanel-canvas'],
  ['#with-tests', '#selpanel-tools'], ['#folder-tool', '#selpanel-tools'], ['#tools-sep', '#selpanel-tools'],
  ['#fit-btn', '#selpanel-tools'], ['#export-btn', '#selpanel-tools'],
  ['#catalog', '#selpanel-card'],
];

/* Called before anything changes the mode: what the dock showed, a column's
   lineage included, is what it gets back. */
function selectPanelDown() {
  if (panelOpen('select')) return;
  // Where each went from, taken before any moves: two of them sit side by side.
  const places = SELECT_MOVES.map(([sel]) => {
    const el = $(sel);
    return { el, parent: el.parentNode, next: el.nextSibling };
  });
  S.selectBack = { mode: S.graphMode, colFocus: S.colFocus, node: S.node, card: [...$('#catalog').childNodes], places };
  for (const [sel, to] of SELECT_MOVES) $(to).appendChild($(sel));
  // The card starts closed, and the canvas at the panel's width: the dock's
  // model, which the selection may not even hold, would read as a box clicked.
  S.cardAsk++;
  S.node = null;
  $('#catalog').replaceChildren();
  $('#selpanel-card').classList.add('hidden');
  $('#dock-lineage').classList.remove('hidden');
  openPanel('select');
  setTimeout(() => Lineage.fit(), 30);
}

/* What the panel took goes back where it was, the last first, so each lands
   before a neighbour that is back already. A selection typed and not yet
   asked for, or asked for and not yet answered, is dropped: the panel would
   come down again, or the dock's canvas get it. Rolled up with the selection
   still drawn, by Escape, its button or a file opened, the dock gets back
   what it showed, its card included. A double-click on a box, or a column
   clicked in the card, has drawn something else already, and the card stays
   on what was clicked. */
function selectPanelUp() {
  const back = S.selectBack;
  if (!back) return;
  S.selectBack = null;
  clearTimeout(selectTimer);
  clearTimeout(selCardWait);
  S.selectAsk++;
  for (const p of back.places.slice().reverse()) p.parent.insertBefore(p.el, p.next);
  $('#dock-lineage').classList.toggle('hidden', S.dock !== 'lineage');
  if (S.graphMode !== 'select') {
    // The Catalog comes back holding the card's narrow layout; a column drawn
    // from the card never redraws it, so it is laid out for the dock again (0160).
    if (S.node) renderCatalog(S.node);
    return;
  }
  S.cardAsk++;
  S.node = back.node;
  $('#catalog').replaceChildren(...back.card);
  // The card was kept as painted: builds read while the panel was down are not on it.
  const builds = $('#catalog .cat-builds');
  if (builds) paintCatalogBuilds(builds);
  if (back.mode === 'column' && back.colFocus) focusColumn(back.colFocus.id, back.colFocus.column);
  else if (S.focus) focusNode(S.focus, { keepDepth: true });
  else blankLineage();
}

/* No model to draw: the canvas empty, and saying how to fill it. */
function blankLineage() {
  leaveColumnWait();
  S.graphMode = 'model';
  paintMode();
  Lineage.clear();
  emptyHint('Select a model to see its lineage.');
  $('#lineage-status').textContent = '';
}

/* The card beside the selection's canvas, open from a click on a box until
   its ×, Escape or a drawing without that box (0101). Opening it narrows the
   canvas, which moves the box clicked back into sight if the card now covers
   it; closing it puts the box out of the light too, as no box is clicked. */
const selCardOpen = () => panelOpen('select') && !$('#selpanel-card').classList.contains('hidden');

/* The double-click a desktop counts by default, Windows' and macOS's: the
   page cannot read the one set. */
const DOUBLE_CLICK_MS = 500;
let selCardWait = null;
// False once the hand pans or zooms the canvas while a card waits, as
// Lineage's onMove says: moving it along then would jump it under the hand.
// A press alone, on a box, a chip or the background, leaves it true.
let selCardStill = true;

/* A double-click opens the box's file instead, and its first click must
   leave the box under the pointer for the second: a box the card would cover,
   or the canvas has to move to show, waits until a double-click is past. The
   card is tried and taken back in one go, which no frame ever shows. A card
   that waited asks for its jobs once shown: its Catalog may have landed while
   it was hidden, when nothing of it counted as seen. */
function openSelCard(id) {
  clearTimeout(selCardWait);
  const card = $('#selpanel-card');
  const shut = card.classList.contains('hidden');
  card.classList.remove('hidden');
  if (!Lineage.overrun(id)) return Lineage.placeHeads();
  if (shut) card.classList.add('hidden');
  selCardStill = true;
  // Another click, the card closed or the panel rolled up clears it first.
  selCardWait = setTimeout(() => {
    if (!panelOpen('select')) return;
    card.classList.remove('hidden');
    if (selCardStill) Lineage.reveal(id);
    else Lineage.placeHeads();
    fillCatalogJobs($('#catalog .cat-jobs'));
  }, DOUBLE_CLICK_MS);
}

/* The Catalog of a box clicked. Another click, the card closed or the panel
   going down or up since has taken its place, and the late answer is dropped:
   it would put back a box no longer clicked, in the card or the dock. */
function catalogFor(id) {
  const ask = ++S.cardAsk;
  return nodeDetail({ id }).then((n) => { if (ask === S.cardAsk) renderCatalog(n); });
}

/* Closed, it is emptied too: opened again on another box, it would show the
   last one's name and file until that box's answer, and keep them if none
   came. A card still waiting out a double-click is emptied the same way, and
   its answer dropped. The focus inside it goes to the panel, not to the page.
   True only when a card was showing, for Escape to stop there. */
function closeSelCard() {
  clearTimeout(selCardWait);
  if (!panelOpen('select')) return false;
  const card = $('#selpanel-card');
  const shown = !card.classList.contains('hidden');
  const hadFocus = shown && card.contains(document.activeElement);
  S.cardAsk++;
  $('#catalog').replaceChildren();
  S.node = null;
  if (!shown) return false;
  card.classList.add('hidden');
  Lineage.select(null);
  Lineage.placeHeads();
  if (hadFocus) $('#select-panel').focus({ preventScroll: true });
  return true;
}

/* The card's width for its edge dragged to `x`, in a row from `left` to
   `right`: 280px at least, and the canvas left 320px, as the stylesheet
   holds it too, so a drag past either end stops there. */
function selCardWidth(x, left, right) {
  return Math.round(Math.max(280, Math.min(right - left - 320, right - x)));
}

/* What an empty selector box is filled with when the space opens on a model:
   it and one level either side, the dock's default depth, in the name the
   Catalog copies, a version's included (0104). A source, a test or anything
   but the node the lineage is on gets nothing. Until the space has its own
   Models mode this is what it opens on (0140). */
function selectionSeed(node, focus) {
  if (!node || node.id !== focus || !['model', 'seed', 'snapshot'].includes(node.kind) || !node.name) return '';
  return `1+${node.name}+1`;
}

/* The way in: the top bar's tab, the dock's button, and the tour. A box that
   is empty or still holds the last seed is seeded again, from the model in
   front now, or emptied when there is none; a line typed or edited is kept
   as it is. */
function openSelection() {
  const box = $('#select-input');
  const seed = selectionSeed(S.node, S.focus);
  if (seed && (!box.value.trim() || box.value === S.selectSeed)) {
    box.value = seed;
    S.selectSeed = seed;
  } else if (!seed && S.selectSeed && box.value === S.selectSeed) {
    // Nothing to seed it from now: the old seed would name a model no longer in front.
    box.value = '';
    S.selectSeed = '';
  }
  const run = runSelection();
  box.focus();
  return run;
}

async function runSelection() {
  closeHoverCard();
  selectPanelDown();                          // noting the dock's mode before it changes
  S.graphMode = 'select';
  S.colFocus = null;
  S.colDraw++;                                // a column answer still on its way is not drawn over this
  leaveColumnWait();
  paintMode();
  const expr = $('#select-input').value.trim();
  const ask = ++S.selectAsk;
  const tests = testsOn() ? 1 : 0;
  // Drawing past the cap was asked for this line and this tests box only:
  // anything else, an emptied box included, is cut at the cap again, so a
  // slow canvas never becomes the default (0087). The by folder toggle draws
  // the same line, and keeps it.
  const raise = raiseFor(S.selectRaise, expr, tests);
  if (!raise) S.selectRaise = null;
  if (!expr) {
    S.selectSub = null;
    closeSelCard();
    Lineage.clear();
    emptyHint('Type a dbt selector, for example my_model+');
    $('#select-sum').textContent = '';
    $('#lineage-status').textContent = '';
    paintSelectWarnings([]);
    S.selectShown = '';
    updateStatus();
    return;
  }
  try {
    const sub = await api.get(`/api/select?q=${encodeURIComponent(expr)}&tests=${tests}${raise ? `&max=${raise}` : ''}`);
    if (ask !== S.selectAsk) return;          // a later keystroke already asked
    S.selectSub = sub;
    // A pasted command is written back as what was actually resolved, so the
    // box and the picture never say two different things.
    if (sub.stripped) $('#select-input').value = selectionText(sub);
    const line = $('#select-input').value.trim();
    // The status bar names what was drawn, not what is being typed.
    S.selectShown = selectionHere(line);
    updateStatus();
    // A seed was never typed: it is made again each time, and would only
    // push the lines that were out of the ArrowUp history.
    if (line !== S.selectSeed) rememberSelection(line);
    // The note names the button when there is one, so it is asked first.
    const offer = capOffer(sub, raise);
    // Before drawing: the warnings make the bar taller, and the folder names
    // are placed below it.
    paintSelectWarnings(selectWarnings(selectCapNote(sub, offer).concat(selectNotes(sub), sub.warnings || [])), false,
      offer, (max) => {
        // The line this answer was drawn for, not whatever the box holds
        // now: a line typed since was never offered, and its own run, still
        // waiting on the keystroke timer, would draw it a second time.
        clearTimeout(selectTimer);
        S.selectRaise = { expr: line, tests, max };
        runSelection();
      });
    let drawn = null;
    if (sub.nodes.length) {
      $('#lineage-empty').classList.add('hidden');
      drawn = Lineage.render(sub, canvasOptions());
      paintLegend(sub);
      paintTestsCount(sub);
      // The card stays with its box while the box is still drawn, lit as it
      // was; a drawing without it closes the card.
      const card = selCardOpen() && S.node && S.node.id;
      if (card && sub.nodes.some((n) => n.id === card)) Lineage.select(card);
      else closeSelCard();
    } else {
      closeSelCard();
      Lineage.clear();
      emptyHint(selectEmptyText(sub));
    }
    $('#select-sum').textContent = selectSummary(sub);
    // The whole sum is in the title: the bar may cut it short.
    $('#select-sum').title = [selectSummary(sub), sub.description].filter(Boolean).join('\n');
    $('#lineage-status').textContent = canvasStatus(sub, drawn);
  } catch (e) {
    if (ask !== S.selectAsk) return;
    S.selectSub = null;
    S.selectShown = '';
    updateStatus();
    $('#select-sum').textContent = '';
    $('#select-sum').title = '';
    paintSelectWarnings([e.message], true);
  }
}

/* `waiting` puts a lineage above the text, drawing itself around the
   column named, for a canvas that will be drawn by itself and is not empty for
   lack of a choice. Any other hint takes it away. */
const emptyHint = (text, { waiting = false, column = '' } = {}) => {
  const host = $('#lineage-empty');
  host.classList.remove('hidden');
  host.classList.toggle('waiting', waiting);
  const p = host.querySelector('p');
  p.textContent = text;
  dropWaitArm();
  if (waiting) host.insertBefore(waitArm(column), p);
};

function dropWaitArm() {
  const old = $('#lineage-empty').querySelector('.wait-arm');
  if (old) old.remove();
}

/* Where the small lineage of a wait puts its boxes: the column's own, as wide
   as its name needs between a minimum and a cap, truncated past that, with an
   unknown box either side whose x follows it. Measured at about 5.2px a
   character of the 8.5px mono text, which is near enough to fit a name in. */
function waitArmLayout(name) {
  const MIN = 58, MAX = 150, CHAR = 5.2, PAD = 16, GHOST = 58, GAP = 45, EDGE = 8;
  const room = Math.floor((MAX - PAD) / CHAR);
  const label = name.length > room ? name.slice(0, room - 1) + '\u2026' : name;
  const cw = Math.max(MIN, Math.round(label.length * CHAR + PAD));
  const cx0 = EDGE + GHOST + GAP, cx1 = cx0 + cw, ghostR = cx1 + GAP;
  return { label, cw, ghostW: GHOST, ghostL: EDGE, cx0, cx1, ghostR, width: ghostR + GHOST + EDGE, height: 100 };
}

/* The drawing itself, for the column named. The name is the project's: it goes
   in as text, never as markup. */
function waitArm(name) {
  const ns = 'http://www.w3.org/2000/svg';
  const L = waitArmLayout(name);
  const make = (tag, attrs, parent) => {
    const el = document.createElementNS(ns, tag);
    for (const k in attrs) el.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(el);
    return el;
  };
  const svg = make('svg', {
    class: 'wait-arm', viewBox: `0 0 ${L.width} ${L.height}`, 'aria-hidden': 'true',
  });
  // The size the stylesheet scales from; the viewBox keeps the proportions.
  svg.style.setProperty('--wait-w', L.width);
  // Upstream arms run from the column outwards, like the downstream ones.
  const arm = (x0, x1, y, down) => {
    const dir = x1 > x0 ? 1 : -1;
    const d = `M${x0},50 C${x0 + dir * 22},50 ${x1 - dir * 22},${y} ${x1},${y}`;
    make('path', { class: 'wait-base', d }, svg);
    make('path', { class: 'wait-grow' + (down ? ' wait-down' : ''), d, pathLength: 1 }, svg);
  };
  const ghost = (x, y, down, bar) => {
    const g = make('g', { class: 'wait-lit' + (down ? ' wait-down' : '') }, svg);
    make('rect', { class: 'wait-box' + (down ? ' wait-down' : ''), x, y, width: L.ghostW, height: 20, rx: 5 }, g);
    make('rect', { class: 'wait-bar' + (down ? ' wait-down' : ''), x: x + 10, y: y + 8, width: bar, height: 4, rx: 2 }, g);
  };
  arm(L.cx0, L.ghostL + L.ghostW, 24, false);
  arm(L.cx0, L.ghostL + L.ghostW, 76, false);
  arm(L.cx1, L.ghostR, 24, true);
  arm(L.cx1, L.ghostR, 76, true);
  ghost(L.ghostL, 14, false, 36);
  ghost(L.ghostL, 66, false, 28);
  ghost(L.ghostR, 14, true, 32);
  ghost(L.ghostR, 66, true, 38);
  make('rect', { class: 'wait-halo', x: L.cx0, y: 40, width: L.cw, height: 20, rx: 5 }, svg);
  make('rect', { class: 'wait-centre', x: L.cx0, y: 40, width: L.cw, height: 20, rx: 5 }, svg);
  make('text', { class: 'wait-name', x: L.cx0 + L.cw / 2, y: 53.5 }, svg).textContent = L.label;
  return svg;
}

/* Session history, and no further. Persisting it would need a settings route
   of its own (0011), which retyping a selector has not yet been worth. */
function rememberSelection(expr) {
  if (!expr) return;
  S.selectHistory = [expr].concat(S.selectHistory.filter((e) => e !== expr)).slice(0, 20);
  S.selectHistAt = -1;
}

/* A +N badge names its own box in the expression instead of bumping a depth
   box, because in this mode the text is what the picture is made of. */
function expandSelection(dir, node) {
  // A named selector is dbt's set as the project defined it: a term appended
  // to it would be refused, since --selector stands alone.
  if (S.selectSub && S.selectSub.selector) {
    toast('a named selector is the project\'s own set: type an expression to grow it', 'err');
    return;
  }
  const box = $('#select-input');
  box.value = expandTerm(box.value, node.name, dir);
  runSelection();
}

/* `offer`, from capOffer(), puts the button that draws the rest on the first
   line, the capped canvas's note, which selectCapNote() always puts first.
   The note gives way to it when the bar is narrow; the button and what it
   costs never do. `draw` gets the most it asks for. */
function paintSelectWarnings(lines, bad, offer, draw) {
  const host = $('#select-warn');
  host.textContent = '';
  host.classList.toggle('hidden', !lines.length);
  host.classList.toggle('bad', !!bad);
  const el = (tag, className, textContent) => Object.assign(document.createElement(tag), { className, textContent });
  lines.forEach((line, i) => {
    const row = document.createElement('div');
    row.title = line;
    host.appendChild(row);
    if (i || !offer) {
      row.textContent = line;
      return;
    }
    const button = el('button', 'btn sm', offer.label);
    button.type = 'button';
    button.title = offer.title;
    button.addEventListener('click', () => {
      button.disabled = true;
      button.textContent = 'Drawing…';
      draw(offer.max);
    });
    row.className = 'caprow';
    row.append(el('span', 'capnote', line), button, el('span', 'caphint', offer.hint));
  });
}

/* One place for the clipboard, because a Copy that silently does nothing is
   worse than no button: the browser refuses it often enough to need the toast. */
async function copyText(text, label) {
  try {
    await navigator.clipboard.writeText(text);
    toast('copied ' + (label || text), 'ok');
    return true;
  } catch { toast('clipboard unavailable', 'err'); return false; }
}

const COPY_SVG = '<svg viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" ' +
  'stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="5.5" y="5.5" width="8" height="8" rx="1.5"/>' +
  '<path d="M10.5 5.5v-2a1 1 0 0 0-1-1h-6a1 1 0 0 0-1 1v6a1 1 0 0 0 1 1h2"/></svg>';
const COPIED_SVG = '<svg viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" ' +
  'stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M3.5 8.5l3 3 6-7"/></svg>';

/* A copy button with no word on it, which answers with a check for a moment.
   The latest click decides the glyph: an earlier click's check, or the timer
   that takes it back, would otherwise stand beside a later refusal. */
function copyGlyph(text, title) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'icon';
  b.title = title;
  b.setAttribute('aria-label', 'Copy ' + text);
  b.innerHTML = COPY_SVG;
  let clicks = 0, back = 0;
  b.addEventListener('click', async () => {
    const mine = ++clicks;
    clearTimeout(back);
    b.innerHTML = COPY_SVG;
    if (!(await copyText(text)) || mine !== clicks) return;
    b.innerHTML = COPIED_SVG;
    back = setTimeout(() => { b.innerHTML = COPY_SVG; }, 1200);
  });
  return b;
}

/* What the selection is made of, by kind, biggest first. Counted by the server
   over everything that matched, so a capped canvas still reports the whole set. */
function selectKindCounts(counts) {
  return Object.entries(counts || {}).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
}

function selectSummary(sub) {
  if (!sub.matched) return 'nothing matched';
  return selectKindCounts(sub.counts).map(([kind, n]) => `${n} ${kind}${n > 1 ? 's' : ''}`).join('  ·  ');
}

/* What a selection's canvas holds against its answer. A model drawn only for
   a selected test's sake is no part of the answer, and a test the tests box
   keeps off the canvas still is, though no click can draw it (0032). */
function selectCounts(sub) {
  const nodes = (sub && sub.nodes) || [];
  const context = nodes.filter((n) => n && n.context).length;
  const hidden = (sub && sub.hidden_tests) || 0;
  return { context, drawn: nodes.length - context, hidden, drawable: ((sub && sub.matched) || 0) - hidden };
}

/* The canvas half of the answer, which is not the same number: what was drawn,
   against what matched, so a capped picture says so instead of looking whole. */
function selectStatus(sub, folded = 0) {
  if (!sub.matched) return '';
  const { context, drawn, hidden, drawable } = selectCounts(sub);
  const tally = sub.truncated ? null : testTally(sub, (n) => n && n.context);
  const parts = tally && tally.tests ? tally : null;
  // Of what could be drawn, as the note under the box and its button count:
  // the hidden tests are said apart, at the end of the line. A capped canvas
  // counts every box as it did (0087); an uncapped one counts its tests apart.
  const head = sub.truncated ? `${drawn} of ${drawable} drawn` : `${parts ? parts.nodes : drawn} node${(parts ? parts.nodes : drawn) === 1 ? '' : 's'}`;
  const nEdges = parts ? parts.edges : sub.edges.length;
  const edges = `${nEdges} edge${nEdges === 1 ? '' : 's'}`;
  const tests = hidden && `${hidden} test${hidden === 1 ? '' : 's'} hidden`;
  // Context alone on the canvas, a selector of tests with the tests box off,
  // leads with what is there: `0 nodes` above a canvas of boxes reads as a bug.
  if (!drawn && context && !sub.truncated) return [`${context} for context`, edges, tests].filter(Boolean).join(' · ');
  const tail = [context && `${context} for context`, tests].filter(Boolean).map((s) => ` · ${s}`).join('');
  return `${head} · ${edges}${parts ? testsStatus(parts.tests, folded) : foldedStatus(folded)}${tail}`;
}

/* The line under the canvas, whichever mode drew it. One function rather than
   a string at each caller, so an exported graph repeats the screen's words.
   `drawn` is what Lineage.render() said the folder bands added, if any. */
function canvasStatus(sub, drawn) {
  const folded = (drawn && drawn.folded) || 0;
  if (sub.mode === 'select') return selectStatus(sub, folded) + foldersStatus(drawn);
  // A stopped column's +N reads as the depth's limit otherwise (0083).
  const stopped = (sub.stopped_at || []).length ? ` · stopped downstream at ${sub.stopped_at.join(', ')}` : '';
  // collin's indirect edges, left out unless the indirect button is on (0097).
  const indirect = sub.indirect_hidden ? ' · indirect edges hidden' : '';
  // A column canvas is cut at a number of boxes the line names, the one a
  // click on its button lifts (0118); a model's, at the depth.
  const cut = sub.truncated ? (sub.mode === 'column' ? ` · truncated at ${sub.nodes.length}` : ' · truncated') : '';
  // A model canvas counts its tests apart; a column canvas has none.
  const tally = sub.mode === 'column' ? { tests: 0, edges: sub.edges.length } : testTally(sub);
  const edges = tally.edges !== 1 ? `${tally.edges} edges` : '1 edge';
  const tail = `${edges}${tally.tests ? testsStatus(tally.tests, folded) : foldedStatus(folded)}${stopped}${indirect}${cut}`;
  // The indirect edges' boxes stand for a model each, which no column is.
  const models = sub.mode === 'column' ? sub.nodes.filter((n) => n.id && !String(n.id).includes('::')).length : 0;
  // The columns collin traced only in part (0145), counted among those drawn.
  const partly = sub.mode === 'column' ? sub.nodes.filter((n) => n.partial && n.partial.length).length : 0;
  const modelNodes = tally.tests ? tally.nodes : sub.nodes.length;
  return (sub.mode === 'column'
    ? `${sub.focus_column} · ${sub.nodes.length - models} column${sub.nodes.length - models === 1 ? '' : 's'}${partly ? ` · ${partly} partly traced` : ''}${models ? ` · ${models} model${models === 1 ? '' : 's'}` : ''} · ${tail}`
    : `${modelNodes} node${modelNodes === 1 ? '' : 's'} · ${tail}`) + foldersStatus(drawn);
}

/* How many folders the canvas is drawn in, and the sub-folders inside them
   when more than one level is asked for (0080), and how many edges run from a
   later folder to an earlier one, which the canvas dashes: without the count,
   a dashed edge in model mode would look like a loop dbt does not allow. */
function foldersStatus(drawn) {
  if (!drawn) return '';
  const n = drawn.folders, sub = drawn.sub || 0, back = drawn.against;
  return n ? ` · ${n} folder${n === 1 ? '' : 's'}`
    + (sub ? ` · ${sub} sub-folder${sub === 1 ? '' : 's'}` : '')
    + (back ? ` · ${back} edge${back === 1 ? '' : 's'} against their order` : '') : '';
}

/* A model or selection canvas counted with its tests apart (0160): a test is a
   slip on its model's stem, not a box of the graph, and the stem not an edge
   of it. `edges` are those between boxes that are no test. Split only where a
   box that is no test is drawn (a selector of tests alone keeps them as the
   nodes it is made of) and, as every count here, with the tests folded under
   a chip still in, since they are in the answer (0035). `skip` is a node not
   to count, a selection's context. */
function testTally(sub, skip = () => false) {
  const nodes = (sub && sub.nodes) || [], edges = (sub && sub.edges) || [];
  // By index: a node list may be sparse, and filter() would pass over its holes.
  const test = [];
  let tests = 0, skipped = 0;
  for (let i = 0; i < nodes.length; i++) {
    test[i] = !!nodes[i] && nodes[i].kind === 'test';
    if (test[i]) tests++;
    else if (skip(nodes[i])) skipped++;
  }
  const boxes = nodes.length - tests - skipped;
  if (!tests || !boxes) return { nodes: nodes.length - skipped, edges: edges.length, tests: 0 };
  return { nodes: boxes, edges: edges.filter((e) => e && !test[e[0]] && !test[e[1]]).length, tests };
}

/* The tests of a canvas said apart, and how many of them are folded under a
   chip, so `11 tests · 3 folded` tells what the number holds. A fold with no
   tests clause to stand in (a capped selection's, which counts as it did) is
   said as it always was. */
function testsStatus(tests, folded) {
  return ` · ${tests} test${tests === 1 ? '' : 's'}${folded ? ` · ${folded} folded` : ''}`;
}

function foldedStatus(folded) {
  return folded ? ` · ${folded} test${folded === 1 ? '' : 's'} folded` : '';
}

/* Four at most: a selector with twenty bad terms has one mistake in it, not
   twenty, and a wall of amber hides the graph it is about. */
function selectWarnings(list) {
  const seen = [...new Set(list || [])];
  return seen.length <= 4 ? seen : seen.slice(0, 4).concat(`and ${seen.length - 4} more`);
}

/* What the shell still acts on between double quotes, and what the line
   editor acts on: a selection carrying one is not typed at all, since
   dropping the character would type a name other than the one resolved. The
   same set as the server's (src/command.rs), C1 controls and the typographic
   double quotes PowerShell reads as `"` included. */
const SHELL_ACTS_ON = /["$`\\!\u0000-\u001f\u007f-\u009f“”„]/;

/* The command that should print the same list, for checking this build against
   dbt itself, or nothing when it could not be typed as it is. */
function lsCommand(select, exclude) {
  if (SHELL_ACTS_ON.test(String(select)) || SHELL_ACTS_ON.test(String(exclude))) return '';
  const tail = exclude ? ` --exclude "${exclude}"` : '';
  return `dbt ls --select "${select}"${tail} --output name`;
}

/* A named selector's command has nothing else to carry: dbt ignores --select
   and --exclude beside --selector, and so does the box. */
function selectorCommand(name) {
  return SHELL_ACTS_ON.test(String(name)) ? '' : `dbt ls --selector "${name}" --output name`;
}

/* What was resolved, in the box's own words. */
function selectionText(sub) {
  if (sub.selector) return `--selector ${sub.selector}`;
  return (sub.select || '') + (sub.exclude ? ` --exclude ${sub.exclude}` : '');
}

/* The name in a `--selector NAME` in the box, so the dbt ls button can still
   type the command for a selector this build refused: dbt settles those too. */
function boxSelector(text) {
  const m = /(?:^|\s)--selector(?:=|\s+)["']?([^\s"']+)/.exec(String(text || ''));
  return m ? m[1] : '';
}

/* What the status bar says of a selection drawn: the line as typed, but for a
   line that is only `--selector X`, which is shown as X. */
function selectionHere(line) {
  const text = String(line || '').trim();
  const m = /^--selector(?:=|\s+)["']?([^\s"']+)["']?$/.exec(text);
  return m ? m[1] : text;
}

/* The menu's filter. A name that matches comes before a description that
   does, and each half keeps the list's order, which is by name. */
function filterSelectors(list, q) {
  const needle = String(q || '').trim().toLowerCase();
  if (!needle) return (list || []).slice();
  const byName = [];
  const byText = [];
  for (const s of list || []) {
    if (s.name.toLowerCase().includes(needle)) byName.push(s);
    else if ((s.description || '').toLowerCase().includes(needle)) byText.push(s);
  }
  return byName.concat(byText);
}

/* A capped canvas says so under the box, where it is read, and not only in
   the corner: a part drawn reads as the whole answer, a source whose children
   were left out as a source read by nothing (0087). On screen only: an
   exported page has no Copy names, and lists what was left out by name. Said
   first, so the cap on warnings can never drop it.

   When the starts take half the canvas or more, as `source:*+` can, it
   holds at most one other node per start, and the walk hands those out
   start by start, by name: the starts it never got to stand alone with a
   +N badge. "Those nearest what the selection names" then reads as if
   their lineage had been drawn, so the note says how many are starts, and
   what draws the rest, before Copy names, since a narrow bar cuts the end
   of the line. `offer` is capOffer()'s button, named when there is one. */
function selectCapNote(sub, offer) {
  if (!sub || !sub.truncated) return [];
  const { drawn, drawable } = selectCounts(sub);
  // The names sent are cut too, past a few thousand: say how far they go.
  const names = (sub.names || []).length;
  const copy = names >= sub.matched ? 'Copy names lists every one' : `Copy names lists the first ${names} by name`;
  const starts = sub.starts || 0;
  if (!starts || 2 * starts < drawn) {
    return [`Too large to draw whole: ${drawn} of ${drawable} on the canvas, those nearest what the selection names. `
      + `${copy}; a narrower selection draws the rest.`];
  }
  // Their lineage, not their children: `+tag:x` starts at models and grows
  // to their parents. A button that cannot draw it all draws more of it.
  const rest = offer && offer.all ? 'the rest of their lineage' : 'more of their lineage';
  const who = offer ? `${offer.all ? 'Draw all' : `Draw ${offer.max}`} or a narrower selection` : 'A narrower selection';
  return [`Too large to draw whole: ${drawn} of ${drawable} on the canvas, ${starts} of them what the selection names. `
    + `${who} draws ${rest}; ${copy}.`];
}

/* The button beside a capped canvas's note: the rest drawn, this time only.
   Past the cap every step of zoom and pan slows, a lot on a slow machine, so
   the button says so and is never remembered (0087). It asks for the most
   the server says it draws, `most`, and offers nothing once the canvas was
   drawn at that. Tests that Tests keeps off are not counted: no click
   draws them. */
function capOffer(sub, asked) {
  const most = (sub && sub.most) || 0;
  if (!sub || !sub.truncated || !most || asked >= most) return null;
  const { drawable } = selectCounts(sub);
  const all = drawable <= most;
  return {
    max: most,
    all,
    label: all ? `Draw all ${drawable}` : `Draw ${most}`,
    hint: 'slower to zoom and pan',
    title: `${all ? 'Draws every node of this selection' : `Draws ${most} nodes of this selection, the most there is`}, `
      + 'this time only. Past the cap, zooming and panning slow down, a lot on a slow machine; '
      + 'another selection, or Tests, cuts it at the cap again.',
  };
}

/* The ceiling a click lifted, `prev` being {expr, tests, max}: for the line
   and the tests box it was asked for, and nothing else, an empty box
   included (0087). */
function raiseFor(prev, expr, tests) {
  return prev && expr && prev.expr === expr && prev.tests === tests ? prev.max : 0;
}

/* Said before any warning, so the cap on warnings can never drop it: it
   changes what every test in the answer means (0032). The server sends it
   only for a selector the lost setting could change. */
function selectNotes(sub) {
  return sub && sub.lost_indirect
    ? ['This manifest lost the indirect_selection selectors.yml sets, and this selector\'s tests depend on it: '
      + 'they follow dbt\'s default here. Re-parse with a recent dbt Fusion to fix it; dbt ls settles any doubt.']
    : [];
}

/* The menu's footer, about the manifest rather than any one selector. */
function selectorsNote(body) {
  return body && body.lost_indirect
    ? ['This manifest lost the indirect_selection selectors.yml sets. '
      + 'A selector whose tests depend on it says so when drawn.']
    : [];
}

/* Why the canvas is empty. A selector that keeps only tests, with the tests
   box off, has not matched nothing, and saying so would send someone off to
   debug a selector that works. */
function selectEmptyText(sub) {
  const hidden = (sub && sub.hidden_tests) || 0;
  if (hidden && hidden === sub.matched) {
    return `This selector keeps only tests (${hidden}): press Tests to see them.`;
  }
  return 'Nothing matched.';
}

/* The tests toggle's words. Data tests can outnumber the models several times
   over, and every one is a box: the tooltip says so before a click draws them,
   and, once drawn, how many were sent, the number that decides how heavy the
   picture is. The button itself says only `Tests`. */
function testsTitle(on, n = 0) {
  return on
    ? `Data tests shown${n ? ` (${n})` : ''}: each one is a box on the canvas, and there can be hundreds, `
      + 'which slows the canvas and buries the models. Click to hide them.'
    : 'Data tests hidden. Click to draw them on the canvas: there can be hundreds, '
      + 'which slows it and buries the models.';
}

function expandTerm(expr, name, dir) {
  const term = dir === 'up' ? `+${name}` : `${name}+`;
  const terms = String(expr).split(/\s+/).filter(Boolean);
  return (terms.includes(term) ? terms : terms.concat(term)).join(' ');
}

/* Walking the history from the box: past the newest is the empty line you
   started on, and past the oldest stays on the oldest. */
function historyStep(list, at, dir) {
  if (!list.length) return -1;
  const next = at + dir;
  if (next < 0) return -1;
  return next >= list.length ? list.length - 1 : next;
}

// ------------------------------------------------------ column lineage tool --
/* Where the column lineage comes from: Fusion, Collin, or Snowflake fetched on
   click (0031). Picking Snowflake starts tools/sf_lineage.py, and the script
   connects on the first column click, never before (0016). */
async function loadSidecar() {
  const was = S.sidecar && S.sidecar.state;
  try { S.sidecar = await api.get('/api/sidecar'); } catch { S.sidecar = null; }
  paintSidecar(was);
}

/* Paints what the script's state shows in, and keeps asking while it starts:
   the server starts it in the background, and nothing else would come back to
   say how the start ended. */
function paintSidecar(was) {
  paintSourceButton();
  const sc = S.sidecar;
  const now = sc ? sc.state : '';
  if (now !== was && S.node) renderCatalog(S.node);
  if (was === 'starting' && now === 'failed') toast('Snowflake lineage: ' + (sc.error || 'the script could not start'), 'err');
  clearTimeout(S.sidecarPoll);
  if (now === 'starting') S.sidecarPoll = setTimeout(loadSidecar, 1500);
}

const sidecarOn = () => !!(S.sidecar && S.sidecar.enabled);

/* Label, tone and tooltip of the Snowflake script for one /api/sidecar payload. */
function sidecarLabel(sc) {
  if (!sc || !sc.enabled) {
    return {
      text: 'Snowflake lineage: off', tone: 'off',
      title: 'Pick Snowflake in the column lineage menu to fetch a column\'s lineage when you click it. '
        + 'dbt-edith starts tools/sf_lineage.py with your dbt profile, and nothing connects before the first click.',
    };
  }
  const who = [sc.profile && `profile ${sc.profile}`, sc.target && `target ${sc.target}`, sc.role && `role ${sc.role}`]
    .filter(Boolean).join(', ');
  const python = sc.python ? `Python: ${sc.python}` : '';
  switch (sc.state) {
    case 'ready':
      return { text: 'Snowflake lineage: on', tone: 'on',
        title: [`Click a column to fetch its lineage${who ? ` (${who})` : ''}.`, python].filter(Boolean).join('\n') };
    case 'busy':
      return { text: 'Snowflake lineage: querying', tone: 'busy', title: ['Waiting for Snowflake.', python].filter(Boolean).join('\n') };
    case 'starting':
      return { text: 'Snowflake lineage: starting', tone: 'busy', title: 'Starting tools/sf_lineage.py' };
    case 'failed':
      return { text: 'Snowflake lineage: failed', tone: 'failed',
        title: [sc.error, python, ...(sc.log || []).slice(-8)].filter(Boolean).join('\n') };
    default:
      return { text: 'Snowflake lineage: on', tone: 'on', title: 'The script starts with the next column click.' };
  }
}

/* What to say beside the menu in the Columns tab: the script's trouble, or what
   to do next. The tooltip alone was invisible, and a toast is gone in three
   seconds. */
function columnsHint(sc, cached) {
  if (!sc || !sc.enabled) return null;
  if (sc.state === 'failed') return { text: sc.error || 'the Snowflake script could not start', tone: 'failed' };
  if (sc.state === 'starting') return { text: 'starting the Snowflake script', tone: 'busy' };
  if (sc.state === 'busy') return { text: 'querying Snowflake', tone: 'busy' };
  return cached ? null : { text: 'click a column to fetch its lineage from Snowflake', tone: 'hint' };
}

/* Why a collin that was found does not run: git tracks it, so it came with a
   repository, as a venv git tracks never runs (0053, 0094). Said in the menu
   and the Columns tab, or a copy beside dbt-edith would sit there doing
   nothing and nobody would know why. */
function collinRefusedNote(cl) {
  if (!cl || !cl.refused) return '';
  // An install side by side another account could replace: the server wrote
  // the sentence, ending on the command that fixes it, so no full stop (0128).
  if (cl.refused_shared) {
    return cl.found && cl.path ? `Using ${cl.path}. Skipped ${cl.refused}: ${cl.refused_shared}` : `Not run: ${cl.refused_shared}`;
  }
  // Another collin runs: say which first, so the note does not read as if
  // collin were not running at all.
  // git said nothing: it sits in a repository, and may be the repository's.
  const why = cl.refused_why
    ? `${cl.refused} sits in a repository git could not answer for (${cl.refused_why})`
    : `git tracks ${cl.refused}, so it came with a repository`;
  if (cl.found && cl.path) return `Using ${cl.path}. Skipped ${cl.refused}: ${why}.`;
  return `Not run: ${why}. Keep your own collin in a folder git does not track.`;
}

/* The same, for collin while it is the tool picked: what it is doing, why it
   failed, or that its cache is behind the manifest (0042). */
function collinHint(tool, cl, kinds) {
  if (tool !== 'collin' || !cl) return null;
  if (cl.state === 'running') return { text: 'collin is reading the compiled SQL', tone: 'busy' };
  if (cl.state === 'failed') return { text: `collin: ${cl.error || 'the run failed'}`, tone: 'failed' };
  if (!cl.found && cl.refused) return { text: collinRefusedNote(cl), tone: 'hint' };
  if (!cl.found) return { text: 'collin is not installed: the column lineage menu installs it', tone: 'hint' };
  // Never set while a version installed by its tag runs, whatever its number:
  // no update reaches it, so this would promise one the menu lacks (0098).
  if (cl.outdated) {
    const v = shortVersion(cl.version);
    return { text: `${v ? `collin ${v} is` : 'this collin gives no version, so it is'} older than ${cl.wants}: `
      + 'the column lineage menu updates it', tone: 'hint' };
  }
  if (cl.stale) return { text: 'older than the manifest: the next column click runs collin again', tone: 'hint' };
  // Otherwise the one thing left to say is how far to trust what is drawn:
  // how many models collin read, when its report says, else the edges' share.
  const r = cl.report;
  const title = collinCaveat(kinds, r);
  const read = collinRead(r);
  if (r && r.models && read < r.models) {
    return { text: `alpha, can be wrong · SQL read for ${read} of ${r.models} models`, tone: 'alpha', title };
  }
  const { inferred, total } = inferredShare(kinds);
  const share = inferred ? Math.max(1, Math.round((100 * inferred) / total)) : 0;
  return { text: share ? `alpha, can be wrong · ${share}% guessed by name` : 'alpha, can be wrong', tone: 'alpha', title };
}

/* The models whose edges collin read from their SQL. collin counts a compiled
   file it set aside as parsed, though it matched that model's edges by name. */
function collinRead(r) {
  return r ? (r.parsed || 0) - (r.set_aside || 0) : 0;
}

/* What collin's report says about the run as a whole: how many models it read
   the SQL of, why the others were not read, where their SQL came from when the
   manifest had none, and what to do about the reasons that have a remedy here. */
function collinReadLines(r) {
  if (!r || !r.models) return [];
  const read = collinRead(r);
  const fromFiles = (r.from_files || 0) - (r.set_aside || 0);
  if (read >= r.models && !fromFiles) return [];
  const plural = (n) => `${n} model${n > 1 ? 's' : ''}`;
  const lines = read < r.models ? [`collin read the SQL of ${read} of ${r.models} models.`] : [];
  for (const x of r.reasons || []) lines.push(`${plural(x.models)}: ${x.why}`);
  if (r.set_aside) {
    lines.push(`${plural(r.set_aside)}: a file in target/compiled/ that reads a table the manifest does not give the model, `
      + 'compiled for another target or before a ref moved, so set aside');
  }
  if (fromFiles) {
    lines.push(`${plural(fromFiles)} read from target/compiled/, as the manifest has no compiled SQL for them: `
      + 'a file there can be older than the manifest.');
  }
  if (r.set_aside) lines.push('Run dbt compile with the target the manifest was written for, then Regenerate.');
  else if ((r.reasons || []).some((x) => /no compiled/.test(x.why))) {
    lines.push('Run dbt compile so target/compiled/ holds their SQL, then Regenerate.');
  }
  return lines;
}

/* The line over a model's columns when collin's report names it: why its SQL
   was not read, or how far its edges are a guess. Said on the model because
   that is where someone is about to trust an edge. */
function collinModelNote(note, columns) {
  if (!note) return null;
  const flagged = collinColumnsLine(note, columns);
  const said = collinModelSaid(note);
  return [said, flagged].filter(Boolean).join(' ') || null;
}

function collinModelSaid(note) {
  if (note.parse_error) {
    return `collin could not read this model's SQL: ${note.parse_error}. Its edges are matched by column name.`;
  }
  // Under the target directory, unless collin was handed a folder of its own.
  const file = note.sql_file && (note.sql_file.startsWith('compiled/') ? `target/${note.sql_file}` : note.sql_file);
  if (note.set_aside) {
    return `collin set aside this model's compiled file, ${file}: it reads a table the manifest does not give this model, `
      + 'so it was compiled for another target or before a ref moved. Its edges are matched by column name.';
  }
  const said = {
    inferred: "collin did not trust this model's compiled SQL: its edges are matched by column name.",
    per_column: "This model's table is behind its compiled SQL: collin read the columns both have and matched the others by name.",
    unresolved: "collin could not resolve this model's lineage.",
  }[note.provenance] || (note.issues ? `collin noted ${note.issues} issue${note.issues > 1 ? 's' : ''} reading this model, listed in target/collin.report.json.` : null);
  // Said with whatever else is, since a file older than the manifest may be the cause.
  const from = file && `collin read its SQL from ${file}, as the manifest has none: that file can be older than the manifest.`;
  return [said, from].filter(Boolean).join(' ') || null;
}

/* collin's notes on a model's columns, by lower-cased name, each worded. */
function collinColumnNotes(note) {
  const by = new Map();
  for (const cn of (note && note.columns) || []) {
    // A compile collin could not parse produced no column it knows of, so
    // every column of the table reads as missing from it, which says nothing.
    if (note.parse_error && (cn.kind === 'missing' || cn.kind === 'unexpected')) continue;
    const text = collinColumnText(cn);
    if (!by.has(cn.column)) by.set(cn.column, []);
    if (!by.get(cn.column).includes(text)) by.get(cn.column).push(text);
  }
  return by;
}

/* `model.shop.orders` to `orders`: the report names models by unique_id. */
function shortId(id) {
  return id.split('.').slice(2).join('.') || id;
}

function nameList(names, of, short) {
  const shown = (names || []).map((x) => (short ? shortId(x) : x));
  const more = of > shown.length ? ` and ${of - shown.length} more` : '';
  return shown.join(', ') + more;
}

/* What one entry of collin's report says about a column, in a sentence that
   says what to do where there is something to do. */
function collinColumnText(cn) {
  const names = nameList(cn.names, cn.of, false);
  switch (cn.kind) {
    case 'lost':
      if (cn.detail === 'phantom') {
        return `collin lost this column's lineage: it is copied from ${names ? `the CTE ${names}` : 'a CTE'}, which does not have it, `
          + 'the shape of a select * over a parent whose column list lacks it.';
      }
      if (cn.detail === 'names_unreached' && names) {
        return `collin lost this column's lineage: its expression reads ${names}, which collin never placed.`;
      }
      return "collin lost this column's lineage: the SQL has it, and no edge came out.";
    case 'missing':
      return 'In the warehouse, but the compiled SQL does not produce it: the table is older than the code, or the code dropped it.';
    case 'unexpected':
      return 'Produced by the compiled SQL, but not in the warehouse: the table has not been rebuilt since the code changed.';
    case 'unbacked':
      return `Read from ${cn.detail ? `the CTE ${cn.detail}` : 'a CTE'}, which does not have it, so this compile cannot run as it is: `
        + 'usually a macro that read the warehouse at compile time and found a relation missing.'
        + (names ? ` ${names} under it ${cn.names.length > 1 || cn.of ? 'have' : 'has'} the name.` : '');
    case 'read_downstream': {
      const list = { warehouse: "the warehouse's", computed: "the compiled SQL's", declared: "the YAML's" }[cn.detail] || 'the';
      return `Read by ${nameList(cn.names, cn.of, true)} downstream, but absent from ${list} column list collin had for this model.`;
    }
    case 'ambiguous': {
      const from = nameList(cn.names, cn.of, true);
      if (cn.detail === 'every') return `Matched by name to each of ${from}: right for a union, wrong for a lookup join. Check it in the SQL.`;
      if (cn.detail === 'order') return `Matched by name to ${from}, the first of several parents that have it.`;
      return `Matched by name to ${from}, of several parents that have it.`;
    }
    default:
      return `collin noted ${cn.kind} on this column, in target/collin.report.json.`;
  }
}

/* The sentence over the table that points at the marks, and names the columns
   the table has no row for: a column only collin's compile produced has none. */
function collinColumnsLine(note, columns) {
  const by = collinColumnNotes(note);
  if (!by.size) return null;
  const rows = new Set((columns || []).map((c) => c.name.toLowerCase()));
  const marked = [...by.keys()].filter((c) => rows.has(c));
  const absent = [...by.keys()].filter((c) => !rows.has(c));
  const bits = [];
  if (marked.length) bits.push(`collin flags ${marked.length} column${marked.length > 1 ? 's' : ''} of this model, marked ! in the Lineage column.`);
  if (absent.length) {
    // Grouped by what is said, since one cause usually covers several.
    const groups = new Map();
    for (const c of absent) {
      const why = by.get(c).join(' ');
      if (!groups.has(why)) groups.set(why, []);
      groups.get(why).push(c);
    }
    bits.push(`It also flags ${absent.length > 1 ? `${absent.length} columns` : 'a column'} this table has no row for. `
      + [...groups].map(([why, cs]) => `${cs.join(', ')}${cs.length > 1 ? ', each' : ''}: ${why}`).join(' '));
  }
  return bits.join(' ');
}

/* `0.2.0 (a142ee5)` to `0.2.0`. */
function shortVersion(v) {
  return (v || '').split(' ')[0];
}

/* The line under Collin in the menu, once collin is installed and Collin is the
   tool picked, the one moment updating it means anything: an update when it is
   older than this dbt-edith accepts, with --force so a collin installed any
   other way is replaced, and otherwise a check, which cargo answers by
   rebuilding when GitHub has a newer commit and by "already installed" when it
   does not. dbt-edith itself never asks GitHub (0043). */
function collinUpdateRow(cl, tool) {
  if (!cl || !cl.found || tool !== 'collin') return null;
  // A version installed side by side is pinned to its tag: there is nothing
  // newer to fetch for it, and these commands reach the default one.
  if ((cl.versions || []).some((v) => v.runs && v.origin === 'installed')) return null;
  const v = shortVersion(cl.version);
  if (cl.outdated) {
    // "needs 0.8.0" over "before 0.8.0 → 0.8.0", which read as a range.
    return { label: 'Update collin', urgent: true, sub: v ? `${v}, needs ${cl.wants}` : `needs ${cl.wants}`, command: cl.update,
      title: `This dbt-edith expects collin ${cl.wants} or later, and the one found `
        + (v ? `is ${cl.version}.` : `gives no version, so it is older than ${cl.wants}.`)
        + '\nClick to type the command that updates it into the terminal.' };
  }
  return { label: 'Check for a newer collin', urgent: false, sub: v, command: cl.install,
    title: `collin ${cl.version}.\nClick to type the install command into the terminal: cargo rebuilds collin when `
      + 'GitHub has a newer commit, and says it is already installed when it does not.' };
}

/* How many of a cache's edges collin did not read from the SQL but matched by
   column name, because the compile could not be trusted or did not parse. */
function inferredShare(kinds) {
  let inferred = 0;
  let total = 0;
  for (const k of kinds || []) {
    total += k.edges;
    if (k.kind === 'inferred') inferred += k.edges;
  }
  return { inferred, total };
}

/* What Collin's tooltips say first: it is alpha, and how much of what it drew
   is a guess. Its edges look exactly like read ones on the canvas. */
function collinCaveat(kinds, report) {
  const lines = ['Alpha: collin is new and can be wrong. Check an edge against the compiled SQL before relying on it.'];
  const { inferred, total } = inferredShare(kinds);
  if (total && inferred === total) lines.push(`None of the ${total} edges was read from the SQL: every one is a match by column name.`);
  else if (inferred) lines.push(`${inferred} of the ${total} edges are a match by column name, not read from the SQL.`);
  const read = collinReadLines(report);
  if (read.length) lines.push('', ...read);
  return lines.join('\n');
}

/* How old a cache is, in the shortest form that is still honest. */
function cacheAge(mtime) {
  if (!mtime) return '';
  const secs = Math.max(0, Math.floor(Date.now() / 1000) - mtime);
  if (secs < 60) return 'just now';
  if (secs < 3600) return `${Math.floor(secs / 60)}min ago`;
  if (secs < 86400) return `${Math.floor(secs / 3600)}h ago`;
  return `${Math.floor(secs / 86400)}d ago`;
}

/* What one cache reads as in the menu. A cache with no source field is not
   named "unknown" but by its file, which is the only true thing about it. */
function sourceLabel(src) {
  const name = src.source || src.file.replace(/^column_lineage\.?|\.json$/g, '') || src.file;
  const bits = [src.target, cacheAge(src.mtime)].filter(Boolean);
  return { name, sub: bits.join(' · ') };
}

/* The tools the menu offers, in its order. A function rather than a constant,
   because the harness evaluates this part of the file and a const does not
   outlive its eval. `missing` is what a greyed entry says. */
function lineageToolDefs() {
  return [
    { tool: 'fusion', label: 'Fusion',
      missing: 'No column_lineage.fusion.json beside the manifest. dbt Fusion keeps its lineage as parquet under '
        + 'target/index/, which nothing here converts yet.' },
    { tool: 'collin', label: 'Collin', alpha: true,
      missing: 'No column_lineage.collin.json beside the manifest, and collin is not installed. '
        + 'Click to type the command that installs it into the terminal.' },
    { tool: 'snowflake', label: 'Snowflake', alpha: true, missing: '' },
  ];
}

/* What the menu offers, from the caches the server found, newest first, and
   what the graph holds. Each tool stands for its newest cache; every other
   file, an older one of a tool's included, stays pickable under "other
   caches" (0021). Snowflake is left out entirely while its features are off,
   and is otherwise never greyed, since it can always fetch on click (0031).
   Collin is never greyed either: installed, picking it runs it, and otherwise
   its entry offers the install command (0042). */
function lineageTools(sources, active, live, snowflake, cl) {
  const tools = [];
  const taken = new Set();
  for (const def of lineageToolDefs()) {
    const snow = def.tool === 'snowflake';
    if (snow && !snowflake) continue;
    const src = sources.find((s) => s.tool === def.tool) || null;
    if (src) taken.add(src.file);
    const onScreen = !!src && src.file === active;
    const collin = def.tool === 'collin';
    const installed = !!(cl && cl.found);
    let title = def.missing;
    let sub = src ? sourceLabel(src).sub : (snow ? 'fetch on click' : 'no cache');
    if (collin && cl && cl.state === 'running') sub = 'running';
    else if (collin && !src) sub = installed ? 'runs on pick' : 'install';
    if (collin && !src && installed) {
      title = 'Runs collin over the compiled SQL, which writes column_lineage.collin.json.';
    } else if (collin && !src && cl && cl.refused) {
      title = `${collinRefusedNote(cl)}\nClick to type the command that installs it into the terminal.`;
    } else if (snow) {
      title = 'Fetches a column\'s lineage from Snowflake when you click it, under your dbt profile.'
        + (src ? `\nAdds to ${src.file}` : '');
    } else if (src) {
      title = src.file + (src.generated_at ? `\nwritten ${src.generated_at}` : '');
    }
    tools.push({
      tool: def.tool, label: def.label, src, alpha: !!def.alpha,
      available: snow || collin || !!src,
      install: collin && !src && !installed,
      active: snow ? live || onScreen : !live && (onScreen || (collin && !src && active === 'column_lineage.collin.json')),
      sub,
      title,
    });
  }
  const others = sources
    .filter((s) => !taken.has(s.file) && (snowflake || s.tool !== 'snowflake'))
    .map((src) => ({ src, active: !live && src.file === active }));
  return { tools, others };
}

/* Where the edges on screen came from, for a tooltip. Always the producer by
   name: mistaking synthetic or stale edges for warehouse truth is the
   expensive failure mode here. */
function cacheTitle(m) {
  return [
    `column lineage from ${m.cll_source || 'a cache that names no producer'}${m.cll_target ? `, target ${m.cll_target}` : ''}`,
    m.cll_file,
    m.cll_generated_at && `written ${m.cll_generated_at}`,
    m.cll_dropped && `${m.cll_dropped} row(s) dropped as unknown`,
  ].filter(Boolean).join('\n');
}

/* What the menu's button says: the tool whose edges are on screen, never what
   the menu merely offers. Snowflake picked says so before its first fetch,
   with the script's state beside it. */
function lineagePickLabel(meta, tool, live, sc, cl) {
  const m = meta || {};
  const count = m.cll_edges ? `${m.cll_edges} col edge${m.cll_edges > 1 ? 's' : ''}` : '';
  if (live) {
    const script = sidecarLabel(sc);
    const state = { starting: 'starting', busy: 'querying', failed: 'failed' }[sc && sc.state] || '';
    return { tool: 'snowflake', name: 'Snowflake', badge: 'alpha', detail: count || 'fetch on click', state, tone: script.tone,
      title: [script.title, m.cll_file && cacheTitle(m)].filter(Boolean).join('\n\n') };
  }
  const run = (tool === 'collin' && cl && cl.state) || '';
  const running = run === 'running';
  const failed = run === 'failed';
  const runState = running ? 'running' : failed ? 'failed' : '';
  const runTone = running ? 'busy' : failed ? 'failed' : '';
  if (tool === 'collin' && !m.cll_file) {
    return { tool: 'collin', name: 'Collin', badge: 'alpha', detail: running ? '' : 'no cache', state: runState,
      tone: runTone || 'off',
      title: running ? 'collin is reading the compiled SQL.' : (failed && cl.error) || 'collin has not written a cache yet.' };
  }
  if (!m.cll_file) {
    return { tool: '', name: 'column lineage: none', detail: '', state: '', tone: 'off',
      title: 'No column lineage on screen. Pick where it comes from in this menu.' };
  }
  const def = lineageToolDefs().find((d) => d.tool === tool);
  const name = def ? def.label : (m.cll_source || m.cll_file.split(/[\\/]/).pop());
  const title = [tool === 'collin' && collinCaveat(m.cll_kinds, cl && cl.report), failed && `The last run failed: ${cl.error}`, cacheTitle(m)]
    .filter(Boolean).join('\n\n');
  return { tool: def ? def.tool : '', name, badge: def && def.alpha ? 'alpha' : '', detail: count || 'no edges',
    state: runState, tone: runTone || 'on', title };
}

/* Why Snowflake's features are on or off, under the switch. */
function featureNote(f, adapter) {
  if (!f) return '';
  const now = f.snowflake ? 'on' : 'off';
  if (f.snowflake_set) return `${now}, as chosen for this project`;
  if (!adapter) return 'off: the manifest names no adapter';
  return `${now} because the manifest's adapter is ${adapter}`;
}

/* The column lineage menu's button, in the Columns tab. A class, so that every
   copy is painted at once; the settings list the same choices (0100). */
function sourceMenu() {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'btn sm cllpick';
  b.setAttribute('aria-haspopup', 'menu');
  b.addEventListener('click', (e) => {
    e.stopPropagation();
    openSourceMenu(b);
  });
  paintSourceButton(b);
  return b;
}

function paintSourceButton(only) {
  const label = lineagePickLabel(S.meta, S.cllTool, sidecarOn(), S.sidecar, S.collin);
  for (const b of only ? [only] : $$('.cllpick')) {
    fillSourceLabel(b, label);
    b.append(Object.assign(document.createElement('span'), { className: 'caret', textContent: ' ▾' }));
  }
  // The settings' Column lineage section says the same, a script starting or
  // collin running included.
  if (!only) repaintSettings();
}

/* What the column lineage on screen is, from lineagePickLabel: on the menu's
   button, and in the settings' Column lineage section, where the tool's name is
   a chip in its colour (`chip`) and the rest follows in the dim one. */
function fillSourceLabel(el, label, { chip = false } = {}) {
  const span = (className, textContent) => Object.assign(document.createElement('span'), { className, textContent });
  el.dataset.tool = label.tool;
  el.dataset.tone = label.tone;
  el.title = label.title;
  el.textContent = '';
  if (chip) el.append(span('toolchip', label.name));
  else el.append(span('tooldot', ''), span('tname', label.name));
  if (label.badge) el.append(span('alpha', label.badge));
  if (label.detail) el.append(span('tdetail', ` · ${label.detail}`));
  if (label.state) el.append(span('tstate', ` · ${label.state}`));
}

async function openSourceMenu(anchor) {
  if (closePopup(anchor)) return;
  // Asked again, so a cache written since the page loaded is offered too.
  try { applyLineage(await api.get('/api/meta')); } catch { /* what the page last knew still stands */ }
  const menu = document.createElement('div');
  menu.className = 'envmenu cllmenu';
  menu.setAttribute('role', 'menu');
  fillSourceMenu(menu, closePopup);
  openPopup(anchor, menu);
}

/* The menu's rows, in the menu or in the settings' Column lineage section:
   `done` runs before a pick, the menu closing on it. In the section (`cards`)
   a tool is a radio card, its sentence under its name, and what is done with it
   a plain button under the card. */
function fillSourceMenu(menu, done, { cards = false } = {}) {
  const snowflake = !!(S.features && S.features.snowflake);
  const { tools, others } = lineageTools(S.cllSources || [], S.cllActive, sidecarOn(), snowflake, S.collin);
  const add = ({ label, sub, tool, on, disabled, title, badge, pick, action, urgent, install }) => {
    const item = document.createElement('button');
    item.type = 'button';
    // An action is not one of the choices, so it carries no checked state,
    // and no glyph: it is something to do with the tool above it, drawn indented
    // under that tool rather than as another tool.
    const role = cards ? (action ? '' : 'radio') : (action ? 'menuitem' : 'menuitemradio');
    if (role) item.setAttribute('role', role);
    if (!action) item.setAttribute('aria-checked', String(on));
    item.dataset.tool = tool;
    // Where the focus comes back to once the settings draw the rows again.
    item.dataset.key = `${tool}:${label}`;
    if (on) item.classList.add('on');
    if (action) item.classList.add('subaction');
    if (urgent) item.dataset.urgent = 'true';
    if (install) item.dataset.install = 'true';
    // Not `disabled`: a disabled button swallows the hover, and its tooltip
    // is the only place that says what is missing.
    if (disabled) item.setAttribute('aria-disabled', 'true');
    if (title) item.title = title;
    const span = (className, textContent = '') => Object.assign(document.createElement('span'), { className, textContent });
    const card = cards && !action;
    if (card) item.classList.add('radio');
    else if (!action) item.append(span('check', on ? '✓' : ''), span('tooldot'));
    // A card: the ring, then the name and tags on a line, and the tool's sentence under them.
    const line = card ? span('rtop') : item;
    line.append(span('lbl', label));
    if (badge) line.append(span('alpha', badge));
    if (sub) line.append(span('sub', sub));
    if (card) {
      const text = span('rtext');
      text.append(line);
      if (title) text.append(span('rd', title));
      item.append(span('rb'), text);
    }
    item.addEventListener('click', () => {
      if (disabled) return;
      done();
      pick();
    });
    menu.appendChild(item);
  };
  // The same rows are in the menu and in the settings: the chip in the terminal names the one the person used.
  const where = cards ? 'the settings' : 'the column lineage menu';
  const update = collinUpdateRow(S.collin, S.cllTool);
  const report = collinReportRow(S.collin, S.cllTool);
  const versions = collinVersionRows(S.collin, S.cllTool);
  const install = collinInstallRow(S.collin, S.cllTool);
  const compare = collinCompareRow(S.collin, S.cllTool);
  for (const t of tools) {
    add({ label: t.label, sub: t.sub, tool: t.tool, on: t.active, disabled: !t.available, title: t.title,
      badge: t.alpha ? 'alpha' : '', install: t.install,
      pick: t.install ? () => installCollin(where) : () => switchLineage({ tool: t.tool }) });
    if (t.tool === 'collin' && report) {
      add({ label: report.label, sub: report.sub, tool: 'collin', on: false, title: report.title, action: true,
        pick: () => openReports('collin') });
    }
    if (t.tool === 'collin') {
      for (const v of versions) {
        add({ label: v.label, sub: v.sub, tool: 'collin', on: false, title: v.title, action: true,
          pick: v.runs ? () => {} : () => chooseCollinVersion(v.version) });
      }
      const gone = collinChosenGone(S.collin);
      if (gone && S.cllTool === 'collin') menu.appendChild(Object.assign(document.createElement('div'), { className: 'menunote', textContent: gone }));
      // Whatever the tool picked: it says why the entry offers an install,
      // or why the collin that runs is not the one beside dbt-edith.
      const refused = collinRefusedNote(S.collin);
      if (refused) menu.appendChild(Object.assign(document.createElement('div'), { className: 'menunote', textContent: refused }));
      if (compare) {
        add({ label: compare.label, sub: compare.sub, tool: 'collin', on: false, title: compare.title, action: true,
          pick: () => openCollinCompare() });
      }
      if (install) {
        add({ label: install.label, sub: install.sub, tool: 'collin', on: false, title: install.title, action: true,
          pick: () => askCollinVersion(where) });
      }
    }
    if (t.tool === 'collin' && update) {
      add({ label: update.label, sub: update.sub, tool: 'collin', on: false, title: update.title, action: true,
        urgent: update.urgent, pick: () => sendToTerminal(update.command, false, null, where) });
    }
  }
  if (others.length) {
    menu.appendChild(document.createElement('hr'));
    menu.appendChild(Object.assign(document.createElement('div'), { className: 'menuhead', textContent: 'other caches' }));
    for (const o of others) {
      const { name, sub } = sourceLabel(o.src);
      add({ label: name, sub, tool: o.src.tool || '', on: o.active, title: o.src.file,
        pick: () => switchLineage({ file: o.src.file }) });
    }
  }
  if (!snowflake) {
    menu.appendChild(Object.assign(document.createElement('div'), {
      className: 'menunote', textContent: 'Snowflake is off for this project: the Snowflake section of the settings turns it on.',
    }));
  }
}

/* One request switches the graph's column lineage and whether a click fetches
   from Snowflake, so the two can never disagree (0031). */
async function switchLineage(body) {
  try {
    applyInfo(await api.send('/api/collineage/source', 'POST', body));
    const label = lineagePickLabel(S.meta, S.cllTool, sidecarOn(), S.sidecar, S.collin);
    toast(`column lineage from ${label.name}`);
    await redrawLineage();
  } catch (e) {
    toast('column lineage: ' + e.message, 'err');
  }
}

/* Types the command that installs collin into the terminal and leaves it
   there: building it is the user's decision, and their cargo's download, never
   this server's (0042). */
function installCollin(from) {
  if (S.collin && S.collin.install) sendToTerminal(S.collin.install, false, null, from);
}

/* Runs collin and waits for it: the Regenerate button, and a column clicked
   while its cache is behind the manifest. True when the run succeeded. */
async function regenerateCollin() {
  // Painted here rather than through paintCollin: this waits for the run, so
  // nothing needs to poll for its end.
  S.collin = Object.assign({}, S.collin, { state: 'running', error: '' });
  followCollinWork();
  paintSourceButton();
  if (S.node) renderCatalog(S.node);
  try {
    const info = await api.send('/api/collineage/generate', 'POST', {});
    // Settled before applyInfo sees it, so the redraw below is the only one.
    S.collin = info.collin;
    followCollinWork();
    applyInfo(info);
    await redrawLineage();
    return true;
  } catch (e) {
    toast('collin: ' + e.message, 'err');
    // Forgotten first, so paintCollin does not say the failure a second time.
    S.collin = null;
    followCollinWork();
    try { applyInfo(await api.get('/api/meta')); } catch { /* the toast already said it */ }
    giveUpColumnWait();
    return false;
  }
}

/* A run that failed leaves nothing to wait for: the canvas goes back to the
   model of the column that was asked for, as it did before a column waited
   for the run. The toast says why. */
function giveUpColumnWait() {
  if (!S.colWait) return;
  leaveColumnWait();
  if (S.graphMode === 'column' && S.colFocus) focusNode(S.colFocus.id);
}

/* Paints what collin's state shows in, and keeps asking while a run started by
   a pick goes on, so its edges appear once it is done. */
function paintCollin(was) {
  followCollinWork();
  paintSourceButton();
  paintReportsButton();
  const now = S.collin ? S.collin.state : '';
  if (now !== was && S.node) renderCatalog(S.node);
  clearTimeout(S.collinPoll);
  if (now === 'running') {
    S.collinPoll = setTimeout(async () => {
      try {
        applyInfo(await api.get('/api/meta'));
      } catch {
        // Asked again at the same pace: a run whose end is never heard would
        // leave every column click waiting for it.
        // Only while the run is still the last thing known of: another
        // answer may have ended it, and replaying it would redraw twice.
        if (S.collin && S.collin.state === 'running') paintCollin('running');
      }
    }, 1500);
  } else if (was === 'running' && now === 'done') {
    redrawLineage();
    // The run wrote its report: the button says so now rather than at the
    // next poll.
    loadReportsIndex();
  } else if (was === 'running' && now === 'failed') {
    toast('collin: ' + (S.collin.error || 'the run failed'), 'err');
    giveUpColumnWait();
  }
}

/* What each kind of finding in collin's report is, and what would remove it,
   filed under who acts: the artifacts dbt wrote, the project itself, a reader,
   or collin. The server only files the report by kind (src/collin_report.rs);
   the words are the page's, as a column's notes are. */
function collinFindingText(kind) {
  const t = {
    no_compiled_sql: ['rerun', 'No compiled SQL',
      'dbt wrote no SQL for these models, so their edges are matched by column name. Run dbt compile, then Regenerate.'],
    compiled_elsewhere: ['rerun', 'Compiled for another target',
      'Their file in target/compiled/ reads a table the manifest does not give the model, so it was set aside. '
        + 'Run dbt compile with the target the manifest was written for, then Regenerate.'],
    catalog_elsewhere: ['rerun', 'Catalog entry for another table',
      'catalog.json describes another table than the manifest names, so nothing was checked against the warehouse. '
        + 'Run dbt docs generate with the target the manifest was written for.'],
    columns_missing: ['rerun', 'Columns the warehouse has and the SQL does not produce',
      'The table is older than the code, or the code dropped them. Running the model rebuilds the table.'],
    columns_unexpected: ['rerun', 'Columns the SQL produces and the warehouse lacks',
      'The table has not been rebuilt since the code changed. Running the model rebuilds it.'],
    yaml_stale: ['project', 'YAML behind the warehouse',
      'The columns the YAML documents disagree with the table. Update the model\'s YAML.'],
    thin: ['project', 'Compile far thinner than its YAML',
      'Either the YAML is stale, or a macro that reads the warehouse at compile time found its source missing.'],
    undeclared_relation: ['project', 'Tables dbt was not told of',
      'The SQL reads a table that is neither a source nor a ref, so the lineage stops there. '
        + 'Declare it as a source, or read it through ref.'],
    unknown_parent: ['project', 'Parents with no known columns',
      'collin had no column list for them. Document their columns in YAML, or build them so the catalog has them.'],
    unbacked_read: ['project', 'Read from a CTE that lacks the column',
      'This compile cannot run as it is: usually a macro that read the warehouse at compile time and found a relation missing.'],
    merged_scope: ['project', 'Two CTEs or subqueries of one name',
      'This collin read them as one, so it did not trust the compile. Renaming one of them is enough, '
        + 'and collin reads two CTEs of one name apart from 0.4.0.'],
    relation_collision: ['project', 'Tables claimed by several nodes',
      'More than one dbt node names this table, often a source declared twice. An edge from it names the node '
        + 'the reading model depends on, and the first by name when it depends on both or neither.'],
    short_upstream: ['project', 'Columns read downstream that this model\'s list lacks',
      'A child reads them, so they exist: the table or the YAML collin had for this model is behind its code.'],
    phantom: ['project', 'Columns copied from a CTE that lacks them',
      'The shape of a select * over a parent whose column list is short: that parent\'s YAML or table is behind.'],
    parse_failed: ['check', 'SQL collin could not parse',
      'Their edges are matched by column name. If the SQL runs, the parser is at fault, and collin wants to hear of it.'],
    ambiguous: ['check', 'Matched by name to every parent that has it',
      'Right for a union, wrong for a lookup join. Check it in the SQL.'],
    engine_issue: ['check', 'Noted while reading',
      'collin\'s engine raised these and nothing else is wrong with the model. The codes are in target/collin.report.json.'],
    lost_in_expression: ['collin', 'Columns lost inside an expression',
      'The SQL reads names collin never placed, in a form it does not read yet.'],
    lost_unresolved: ['collin', 'Columns the SQL has and no edge came out for',
      'collin lost their lineage. Nothing in the project explains it.'],
  }[kind];
  // A kind from a later collin is listed rather than dropped.
  const [group, title, lever] = t || ['check', kind, 'A kind of finding this dbt-edith does not know yet.'];
  return { group, title, lever };
}

function collinGroupText(group) {
  return {
    rerun: ['Rerun dbt', 'What dbt wrote is behind the project, or from another target.'],
    project: ['Fix in the project', 'The project says less than its SQL reads, or disagrees with its warehouse.'],
    check: ['Check by hand', 'collin read these, and a person has to say whether it read them right.'],
    collin: ["collin's to fix", 'The SQL is fine and collin lost the lineage.'],
  }[group] || [group, ''];
}

/* The report's findings under their group, in the order the groups are
   worked through: rerunning dbt first, since it can clear the rest. */
function collinReportGroups(findings) {
  const groups = ['rerun', 'project', 'check', 'collin'].map((group) => {
    const [label, desc] = collinGroupText(group);
    return { group, label, desc, findings: [] };
  });
  for (const f of findings || []) {
    const t = collinFindingText(f.kind);
    groups.find((g) => g.group === t.group).findings.push(Object.assign({}, f, { title: t.title, lever: t.lever }));
  }
  return groups.filter((g) => g.findings.length);
}

/* The findings collin wrote itself, from 0.5.0, under the same groups: its
   inputs, the manifest and catalog dbt wrote, are what rerunning dbt fixes.
   Its words are kept as written (0062). An owner this page does not know is
   checked by hand. */
function collinWrittenGroups(written) {
  const groupOf = { inputs: 'rerun', project: 'project', collin: 'collin' };
  const groups = ['rerun', 'project', 'check', 'collin'].map((group) => {
    const [label, desc] = collinGroupText(group);
    return { group, label, desc, findings: [] };
  });
  for (const f of written || []) {
    const group = groupOf[f.owner] || 'check';
    groups.find((g) => g.group === group).findings.push(f);
  }
  return groups.filter((g) => g.findings.length);
}

/* The kinds whose items are columns of the entry's model, which a click can
   point at in its Columns tab. */
function collinItemsAreColumns(kind) {
  return ['columns_missing', 'columns_unexpected', 'unbacked_read', 'short_upstream', 'phantom', 'ambiguous',
    'lost_in_expression', 'lost_unresolved'].includes(kind);
}

/* What follows an entry's columns: how many were cut, and the CTE they were
   read from or copied through. */
function collinEntryTail(kind, e) {
  const shown = (e.items || []).length;
  const more = e.of > shown ? ` and ${e.of - shown} more` : '';
  const via = e.detail && { unbacked_read: `from ${e.detail}`, phantom: `through ${e.detail}` }[kind];
  return more + (via ? `, ${via}` : '');
}

/* What follows the model's name on an entry's line, as text. */
function collinEntryText(kind, e) {
  if (collinItemsAreColumns(kind)) return (e.items || []).join(', ') + collinEntryTail(kind, e);
  switch (kind) {
    case 'no_compiled_sql':
    case 'parse_failed':
      return e.detail || '';
    case 'compiled_elsewhere':
      // Under the target directory, unless collin was handed a folder of its own.
      return e.detail ? (e.detail.startsWith('compiled/') ? `target/${e.detail}` : e.detail) : '';
    case 'catalog_elsewhere':
      return e.detail ? `the catalog describes ${e.detail}` : '';
    case 'thin':
      return e.detail ? `${e.detail} columns` : '';
    default:
      return (e.items || []).join(', ') + collinEntryTail(kind, e);
  }
}

/* The figures over the report, each only when the report has its counters:
   an older collin wrote fewer. A share is rounded down, so a run one column
   short never reads as 100%. */
function collinReportTiles(t) {
  if (!t) return [];
  const has = (...keys) => keys.every((k) => typeof t[k] === 'number');
  const pct = (a, b) => (b ? `${Math.floor((1000 * a) / b) / 10}%` : '');
  const tiles = [];
  if (has('models', 'parsed')) {
    const read = t.parsed - (t.sql_from_files_set_aside || 0);
    tiles.push({ label: 'SQL read', value: `${read} of ${t.models}`, sub: t.parse_failed ? `${t.parse_failed} did not parse` : 'models' });
  }
  if (has('columns_covered', 'columns_total') && t.columns_total) {
    tiles.push({ label: 'Columns with an edge', value: pct(t.columns_covered, t.columns_total),
      sub: `${t.columns_covered} of ${t.columns_total}` });
  }
  if (has('columns_covered_independent', 'columns_total_independent') && t.columns_total_independent) {
    // From 0.5.0 collin also sets aside the columns of a model reading only
    // its own table, which have no parent in dbt either.
    tiles.push({ label: 'Against the warehouse or YAML', value: pct(t.columns_covered_independent, t.columns_total_independent),
      sub: t.columns_self ? 'columns with no parent to find aside' : 'columns built from constants aside' });
  }
  if (has('edges_parsed', 'edges_inferred')) {
    tiles.push({ label: 'Edges', value: String(t.edges_parsed + t.edges_inferred),
      sub: t.edges_inferred ? `${t.edges_inferred} matched by name` : 'all read from the SQL' });
  }
  if (has('confirmed', 'degraded', 'unchecked')) {
    tiles.push({ label: 'Checked against the warehouse', value: `${t.confirmed} confirmed`,
      sub: `${t.degraded} behind their code · ${t.unchecked} not in the catalog` });
  }
  if (has('columns_root') && t.columns_root) {
    tiles.push({ label: 'Built from constants', value: String(t.columns_root), sub: 'columns with no parent to find' });
  }
  return tiles;
}

/* What a run leaves on the Reports button until its report is shown. Only a
   run finished since the page last looked: two runs in a row both read done,
   and the counter is what tells them apart. */
function collinBadge(cl, seen) {
  if (!cl || cl.state !== 'done' || !cl.report || !cl.report.to_investigate) return null;
  if ((cl.run || 0) <= (seen || 0)) return null;
  const n = cl.report.to_investigate;
  return { text: `${n} to investigate`, short: String(n),
    title: `collin's last run names ${n} model${n > 1 ? 's' : ''} or table${n > 1 ? 's' : ''} to look at.` };
}

/* The line under Collin in the menu that opens the report, whenever Collin's
   own cache is on screen and its report says something. */
function collinReportRow(cl, tool) {
  if (!cl || tool !== 'collin' || !cl.report) return null;
  const n = cl.report.to_investigate || 0;
  return { label: "Open collin's report", sub: n ? `${n} to investigate` : 'nothing to investigate',
    title: "What collin's last run found, grouped by what would fix it, in Reports." };
}

/* A model named in the report, opened with its Columns tab, where collin's
   notes on each column already are. */
function openReportNode(id, column) {
  openFromReport(id, { dock: 'catalog', column });
}

function mountCollinTab(key) {
  const f = S.open.get(key);
  const host = $('#diff-host');
  [...host.children].forEach((c) => c.classList.add('hidden'));
  if (!f.host) {
    f.host = collinComparePane(key, f.view, f.pair);
    host.appendChild(f.host);
  }
  f.host.classList.remove('hidden');
}

/* What the head of collin's section says about the run that wrote it. */
function collinReportAbout(view) {
  const written = view.generated_at ? cacheAge(Math.floor(Date.parse(view.generated_at) / 1000)) : '';
  return [view.producer, view.project, view.adapter, view.dbt_version && `dbt ${view.dbt_version}`,
    written && `written ${written}`].filter(Boolean).join(' · ');
}

/* collin's report, the body of its section in the reports: something to work
   through model by model, each opening in the editor as the panel rolls up. */
function collinReportBody(view) {
  const body = jel('div', 'reportbody');
  body.append(reportTiles(collinReportTiles(view.totals)));
  const n = view.to_investigate || 0;
  body.append(jel('p', 'rsummary', n
    ? `${n} model${n > 1 ? 's' : ''} or table${n > 1 ? 's' : ''} to look at. A name opens the model, whose Columns tab says what collin noted on each column.`
    : 'Nothing to investigate: every model collin read came out clean.'));
  // A short list is worth seeing at once; a long one is a count first.
  const few = (len) => len <= 5;
  const groups = (view.collin_findings || []).length
    ? collinWrittenSections(view.collin_findings)
    : collinReportGroups(view.findings).map((g) => ({ group: g.group, label: g.label, desc: g.desc,
      folds: g.findings.map((f) => ({
        title: f.title, tone: '', lever: f.lever, rows: f.entries, open: few,
        find: (e) => `${e.id} ${(e.items || []).join(' ')}`,
        draw: (hits, d) => [reportList(hits, (e) => collinEntryRow(f, e), d, CHECK_SHOWN)],
      })) }));
  reportLists(body, groups, 'Filter the findings');
  return body;
}

/* One model of a finding: its name opens it, then what collin says of it, the
   columns each pointing at theirs in the Columns tab. */
function collinEntryRow(f, e) {
  const li = jel('li', '');
  const node = f.kind !== 'relation_collision';
  const name = jel(node ? 'a' : 'span', node ? 'filelink' : 'rrel', node ? shortId(e.id) : e.id);
  if (node) {
    name.title = e.id;
    name.addEventListener('click', (ev) => { ev.preventDefault(); openReportNode(e.id); });
  }
  li.append(name);
  if (f.kind === 'relation_collision') {
    li.append(jel('span', 'muted', ' claimed by '));
    (e.items || []).forEach((id, i) => {
      if (i) li.append(jel('span', 'muted', ', '));
      const a = jel('a', 'filelink', shortId(id));
      a.title = id;
      a.addEventListener('click', (ev) => { ev.preventDefault(); openReportNode(id); });
      li.append(a);
    });
  } else if (collinItemsAreColumns(f.kind) && (e.items || []).length) {
    li.append(jel('span', 'muted', ': '));
    e.items.forEach((c, i) => {
      if (i) li.append(jel('span', 'muted', ', '));
      const a = jel('a', 'rcol', c);
      a.title = `Open ${shortId(e.id)} with ${c} picked out in its Columns tab`;
      a.addEventListener('click', (ev) => { ev.preventDefault(); openReportNode(e.id, c); });
      li.append(a);
    });
    const tail = collinEntryTail(f.kind, e);
    if (tail) li.append(jel('span', 'muted', tail));
  } else {
    const text = collinEntryText(f.kind, e);
    if (text) li.append(jel('span', 'muted', ': ' + text));
  }
  return li;
}

/* collin's own findings, as it worded them, under the same groups as folds:
   what it saw, what that usually means and what to do, then each model with
   what its entry says. */
function collinWrittenSections(written) {
  return collinWrittenGroups(written).map((g) => ({ group: g.group, label: g.label, desc: g.desc,
    folds: g.findings.map((f) => ({
      title: f.title, tone: '', severity: f.severity || undefined, lever: f.why || '',
      rows: f.models, open: (len) => len <= 5,
      find: (m) => `${m.name || ''} ${m.unique_id} ${m.detail || ''}`,
      // What to do is the fix, so it is read at once and not behind "why". The
      // chips are decided on the finding's every model, so a filter never
      // turns its list from lines to chips.
      draw: (hits, d) => {
        const names = reportNamesOnly(f.models.map((m) => m.detail || ''));
        return [...(f.action ? [jel('p', 'rlever', f.action)] : []), reportList(hits, (m) => {
          const li = jel('li', '');
          const name = m.name || shortId(m.unique_id);
          const open = () => openReportNode(m.unique_id);
          if (names) {
            li.append(reportModelChip(name, reportLook(m.materialized), m.unique_id, open));
            return li;
          }
          const a = jel('a', 'filelink', name);
          a.title = m.unique_id;
          a.addEventListener('click', (ev) => { ev.preventDefault(); open(); });
          li.append(a);
          if (m.detail) li.append(jel('span', 'muted', ': ' + m.detail));
          return li;
        }, d, CHECK_SHOWN, 0, names)];
      },
    })) }));
}

/* The collins there are to pick under Collin in the menu, once there is more
   than one, or a version was picked: the one beside dbt-edith or on the PATH,
   then those installed side by side (0060). The one that runs says so. */
function collinVersionRows(cl, tool) {
  if (!cl || tool !== 'collin') return [];
  const versions = cl.versions || [];
  if (versions.length < 2 && !cl.chosen) return [];
  return versions.map((v) => {
    const name = v.version ? `collin ${v.version}` : 'collin, no version given';
    const where = v.origin === 'installed' ? 'installed here' : 'beside dbt-edith or on the PATH';
    return { label: name, sub: v.runs ? 'runs' : where, runs: !!v.runs, version: v.origin === 'installed' ? v.version : '',
      title: v.runs ? `${name}, ${where}, is the one that runs for this project.`
        : `Run ${name}, ${where}, for this project. Collin's cache is written again by it.` };
  });
}

/* What the menu says when the version picked is no longer installed. */
function collinChosenGone(cl) {
  if (!cl || !cl.chosen || cl.chosen_refused) return null;
  const there = (cl.versions || []).some((v) => v.origin === 'installed' && v.version === cl.chosen);
  return there ? null : `collin ${cl.chosen}, picked for this project, is not installed here any more: the default one runs.`;
}

/* The line that installs another version beside the others, when there is a
   config directory to put it in. */
function collinInstallRow(cl, tool) {
  if (!cl || tool !== 'collin' || !cl.can_install) return null;
  return { label: 'Install another collin version…', sub: 'by tag',
    title: 'Type the cargo command that installs a collin version of your choice into its own folder, '
      + 'beside the one you have. Each can then be picked here.' };
}

/* A version as someone types it, `v0.4.0` or `0.4.0 `, to `0.4.0`, or '' when
   it is not three numbers. The server checks again. */
function collinVersionInput(text) {
  const v = String(text || '').trim().replace(/^v/i, '');
  return /^\d{1,5}\.\d{1,5}\.\d{1,5}$/.test(v) ? v : '';
}

/* Picks the collin that runs for this project. With Collin's cache on
   screen, the new one runs at once, and the page polls until it is done. */
async function chooseCollinVersion(version) {
  try {
    applyInfo(await api.send('/api/collin/version', 'POST', { version }));
    toast(version ? `collin ${version} runs for this project` : 'the default collin runs for this project');
  } catch (e) {
    toast('collin: ' + e.message, 'err');
  }
}

/* Asks which version to install, then types the command into the terminal,
   where the user runs it: dbt-edith never downloads anything (0042). */
async function askCollinVersion(from) {
  const body = document.createElement('div');
  body.append(Object.assign(document.createElement('p'), {
    textContent: 'Which collin version? It is installed from its tag into a folder of its own, beside the collin you have, '
      + 'and can then be picked under Collin. Building it takes a minute or two. Cargo then suggests adding that folder '
      + 'to your PATH: there is no need, dbt-edith finds it there.',
  }));
  const input = Object.assign(document.createElement('input'), { type: 'text', className: 'versioninput', placeholder: '0.4.0',
    spellcheck: false, autocomplete: 'off' });
  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') $('#modal-actions').lastChild.click(); });
  body.append(input);
  const asked = modal({ title: 'Install a collin version', body,
    actions: [{ id: 'no', label: 'Cancel' }, { id: 'ok', label: 'Type the command', style: 'primary' }] });
  input.focus();
  if (await asked !== 'ok') return;
  const version = collinVersionInput(input.value);
  if (!version) return toast('a collin version is three numbers, such as 0.4.0', 'err');
  try {
    const { command } = await api.get('/api/collin/install?version=' + encodeURIComponent(version));
    sendToTerminal(command, false, null, from);
  } catch (e) {
    toast('collin: ' + e.message, 'err');
  }
}

/* The line under Collin that compares two versions, once two have a kept run
   to compare (0061). */
function collinCompareRow(cl, tool) {
  const kept = (cl && cl.kept) || [];
  if (tool !== 'collin' || kept.length < 2) return null;
  return { label: 'Compare collin versions', sub: `${kept.length} kept`,
    title: 'What two collin versions read in this project, from the last run of each: figures, findings, '
      + 'edges gained and lost, and the models where they moved.' };
}

/* The pair a comparison starts on: the newest kept version against the one
   before it, B against A. */
function collinComparePair(kept) {
  const k = kept || [];
  return k.length < 2 ? null : { a: k[1], b: k[0] };
}

/* A counter of collin's report in words, for the ones a reader looks for
   first; any other keeps its name. */
function collinTotalLabel(key) {
  return {
    models: 'Models', parsed: 'SQL parsed', parse_failed: 'SQL that did not parse',
    sql_from_files: 'SQL from target/compiled/', sql_from_files_set_aside: 'Compiled files set aside',
    confirmed: 'Confirmed by the warehouse', degraded: 'Behind their code', unchecked: 'Not in the catalog',
    edges_parsed: 'Edges read from the SQL', edges_inferred: 'Edges matched by name', edges_indirect: 'Indirect edges',
    columns_covered: 'Columns with an edge', columns_total: 'Columns', columns_covered_independent:
      'Columns with an edge, against the warehouse or YAML', columns_total_independent: 'Columns in the warehouse or YAML',
    columns_root: 'Columns built from constants', columns_lost: 'Columns lost', yaml_stale: 'YAML behind the warehouse',
    undeclared: 'Models reading a table dbt was not told of', scope_merged: 'Models with two scopes of one name',
    catalog_elsewhere: 'Catalog entries for another table', thin: 'Compiles far thinner than their YAML',
  }[key] || key.replace(/_/g, ' ');
}

/* Figures on both sides as rows, the ones that moved first, each keeping its
   order otherwise. A figure one side lacks is shown as a dash, not a zero:
   that version's report does not count it. */
function collinDeltaRows(deltas, label) {
  const rows = (deltas || []).map((d, i) => {
    const a = typeof d.a === 'number' ? d.a : null;
    const b = typeof d.b === 'number' ? d.b : null;
    const diff = a !== null && b !== null ? b - a : null;
    // A counter one report lacks and the other has at zero has not moved.
    return { key: d.key, label: label ? label(d.key) : d.key, a, b, diff, moved: (a || 0) !== (b || 0), i };
  });
  rows.sort((x, y) => (y.moved - x.moved) || (x.i - y.i));
  return rows;
}

function signed(n) {
  return n === null ? '' : n > 0 ? `+${n}` : String(n);
}

/* One edge as a line: `orders.id → customers.id`, a relation no node owns
   kept whole. */
function collinEdgeText(e) {
  const end = (id, col) => `${id.startsWith('rel:') ? id : shortId(id)}.${col}`;
  return `${end(e.from, e.from_col)} → ${end(e.to, e.to_col)}`;
}

/* What one model's line says moved. */
function collinMoveText(m) {
  const bits = [];
  if (m.a !== m.b && m.a && m.b) bits.push(`${m.a} → ${m.b}`);
  if (m.gained) bits.push(`${m.gained} gained`);
  if (m.lost) bits.push(`${m.lost} lost`);
  if (m.changed) bits.push(`${m.changed} with another role`);
  return bits.join(' · ');
}

/* A kept run older than the manifest read another project than the one on
   screen, so a difference may be the project's and not collin's. */
function collinSideNote(side, manifestAt) {
  if (!side) return '';
  const age = cacheAge(side.mtime);
  const behind = manifestAt && side.mtime && side.mtime < manifestAt ? ', before the manifest was last written' : '';
  return `collin ${side.version}: ${side.edges} edges, run ${age}${behind}${side.report ? '' : ', no report kept'}`;
}

async function openCollinCompare(pair) {
  const key = 'collin:compare';
  const p = pair || (S.open.get(key) && S.open.get(key).pair) || collinComparePair(S.collin && S.collin.kept);
  if (!p) return toast('collin: two versions need a kept run each to compare', 'err');
  let view;
  try { view = await api.get(`/api/collin/compare?a=${encodeURIComponent(p.a)}&b=${encodeURIComponent(p.b)}`); }
  catch (e) { return toast('collin compare: ' + e.message, 'err'); }
  const f = S.open.get(key);
  if (f) {
    Object.assign(f, { view, pair: p });
    if (f.host) f.host.remove();
    f.host = null;
  } else {
    S.open.set(key, { kind: 'compare', path: 'collin versions', view, pair: p, dirty: false, host: null });
    S.order.push(key);
  }
  activate(key, false);
}

function collinComparePane(key, view, pair) {
  const el = (tag, className, textContent) => Object.assign(document.createElement(tag), className ? { className } : {},
    textContent !== undefined ? { textContent } : {});
  const pane = el('div', 'diffpane reportpane');
  const head = el('div', 'diff-head');
  const title = el('div', 'diff-title');
  const dot = el('span', 'tooldot');
  dot.dataset.tool = 'collin';
  title.append(dot, el('b', '', 'collin versions'));
  const kept = (S.collin && S.collin.kept) || [pair.a, pair.b];
  const pick = (side) => {
    const s = el('select', 'versionpick');
    for (const v of kept) s.append(Object.assign(el('option', '', v), { value: v, selected: v === pair[side] }));
    s.addEventListener('change', () => openCollinCompare(Object.assign({}, pair, { [side]: s.value })));
    return s;
  };
  title.append(el('span', 'diff-state', 'A'), pick('a'), el('span', 'diff-state', 'against B'), pick('b'),
    el('div', 'grow'));
  const close = el('button', 'icon', '×');
  close.title = 'Close the comparison';
  close.addEventListener('click', () => closeFile(key));
  title.append(close);
  head.append(title);

  const body = el('div', 'reportbody');
  const manifestAt = S.meta && S.meta.manifest_mtime;
  body.append(el('p', 'muted', `A, ${collinSideNote(view.a, manifestAt)}.`), el('p', 'muted', `B, ${collinSideNote(view.b, manifestAt)}.`));
  if (view.a.version === view.b.version) body.append(el('p', 'muted', 'A and B are one run: pick two versions.'));

  const table = (rows, unit) => {
    const t = el('table', 'cmptable');
    const hr = el('tr');
    hr.append(el('th', '', unit), el('th', 'num', `A ${view.a.version}`), el('th', 'num', `B ${view.b.version}`), el('th', 'num', 'B − A'));
    t.append(hr);
    for (const r of rows) {
      const tr = el('tr', r.moved ? 'moved' : '');
      tr.append(el('td', '', r.label), el('td', 'num', r.a === null ? '-' : String(r.a)),
        el('td', 'num', r.b === null ? '-' : String(r.b)), el('td', 'num', signed(r.diff)));
      t.append(tr);
    }
    return t;
  };
  const section = (heading, desc) => {
    const s = el('section', 'reportgroup');
    const gh = el('div', 'rg-head');
    gh.append(el('h3', '', heading));
    s.append(gh);
    if (desc) s.append(el('p', 'muted', desc));
    body.append(s);
    return s;
  };

  const edges = section('Edges', `B has ${view.gained} edge${view.gained === 1 ? '' : 's'} A lacks, A has ${view.lost} B lacks, `
    + `and ${view.changed} ${view.changed === 1 ? 'is' : 'are'} read with another role.`
    + (view.rows_left_out ? ' Only one run holds the indirect edges, a filter\'s, a join key\'s or a dedup key\'s, so both are compared without them.' : ''));
  edges.append(table(collinDeltaRows(view.kinds), 'By role'), table(collinDeltaRows(view.origins,
    (k) => ({ rel: 'a table no node owns' }[k] || k)), 'From'));

  if (view.models.length) {
    const s = section('Models that moved', `${view.models_moved} model${view.models_moved === 1 ? '' : 's'}, the most first`
      + (view.models_moved > view.models.length ? `, ${view.models.length} listed` : '') + '. A name opens the model.');
    const list = el('ul', 'rentries');
    for (const m of view.models) {
      const li = el('li');
      const a = el('a', 'filelink', shortId(m.id));
      a.title = m.id;
      a.addEventListener('click', (ev) => { ev.preventDefault(); openReportNode(m.id); });
      li.append(a, el('span', 'muted', ': ' + collinMoveText(m)));
      list.append(li);
    }
    s.append(list);
  }

  const edgeList = (heading, count, items, line) => {
    if (!count) return;
    const d = el('details', 'reportfinding');
    const sum = el('summary');
    sum.append(reportChevron(), el('span', 'rtitle', heading), el('span', 'tabbadge rcount', String(count)));
    d.append(sum);
    const list = el('ul', 'rentries');
    for (const e of items) list.append(el('li', 'rrel', line(e)));
    if (count > items.length) list.append(el('li', 'muted', `and ${count - items.length} more`));
    d.append(list);
    edges.append(d);
  };
  edgeList('Only in B', view.gained, view.gained_edges, (e) => `${collinEdgeText(e)}  ${e.kind}`);
  edgeList('Only in A', view.lost, view.lost_edges, (e) => `${collinEdgeText(e)}  ${e.kind}`);
  edgeList('Another role', view.changed, view.changed_edges, (e) => `${collinEdgeText(e)}  ${e.kind} → ${e.b_kind}`);

  if (view.findings.length) {
    section('Findings', 'Entries of each kind on the report page.')
      .append(table(collinDeltaRows(view.findings, (k) => collinFindingText(k).title), 'Kind'));
  }
  if (view.totals.length) {
    section('Figures', "Every counter in collin's report, those that moved first.")
      .append(table(collinDeltaRows(view.totals, collinTotalLabel), 'Counter'));
  }
  pane.append(head, body);
  return pane;
}

/* What a failed fetch should say. Only a connection Snowflake refused points at
   the profile: a query it rejected is about the object or the role, and a
   request this build got wrong is neither. */
function connectionAdvice(error, phase, profiles) {
  if (phase !== 'connect') return { text: `Snowflake: ${error}` };
  const text = `Snowflake refused the connection: ${error}`;
  return profiles ? { text, ask: 'check the user and account in', file: profiles } : { text };
}

/* The profile as a link, where dbt looks for it. Nothing to open when there is
   no file there. */
function profileLink() {
  const p = S.profiles;
  if (!p || !p.found || p.refused) return null;
  const a = document.createElement('a');
  a.className = 'filelink';
  a.textContent = fileName(p.path);
  a.title = `${p.path}\nThe dbt profile, outside the project. Click to open it here.`;
  a.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); openProfiles(); });
  return a;
}

/* What is wrong with the profile, '' while there is one to open, or nowhere
   to look for one. A missing one is why dbt would fail, and where it should be
   is the question the user would ask: the settings button carries a triangle for it, and the
   settings say where dbt looks (0049, 0100). A refused one has nothing to open
   either, and says why (0094). */
function profileWarning(p) {
  if (!p) return '';
  if (p.refused) return `profiles.yml not opened: ${p.refused}`;
  return p.found ? '' : `no profiles.yml at ${p.path}, where dbt looks for one`;
}

/* An icon drawn here rather than shipped, one stroked path per shape, its
   colour the button's own. */
function strokeIcon(viewBox, className, shapes) {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', viewBox);
  svg.setAttribute('class', className);
  svg.setAttribute('aria-hidden', 'true');
  for (const d of shapes) {
    const path = document.createElementNS(ns, 'path');
    path.setAttribute('d', d);
    svg.appendChild(path);
  }
  return svg;
}

/* The lineage fields of an /api/meta answer, which every route that switches
   the lineage or a feature answers with. */
function applyLineage(info) {
  const was = S.sidecar && S.sidecar.state;
  S.cllSources = info.cll_sources || [];
  S.cllActive = info.cll_active || '';
  S.cllTool = info.cll_tool || '';
  const sfWas = !!(S.features && S.features.snowflake), firstLoad = S.features === null;
  S.features = info.features || null;
  S.profiles = info.profiles || null;
  if (info.sidecar) S.sidecar = info.sidecar;
  // The builds follow the switch: the Reports entry is the index's to say, the
  // Catalog's section is drawn from it, and a read does not outlive the switch.
  // Not on the first load, which the page's start reads the index after anyway.
  if (!firstLoad && sfWas !== !!(S.features && S.features.snowflake)) followBuildsSwitch();
  const collinWas = S.collin && S.collin.state;
  if (info.collin) S.collin = info.collin;
  paintSidecar(was);
  paintCollin(collinWas);
  paintSettingsButton();
  repaintSettings();
  paintHistoryTab();
}

function followBuildsSwitch() {
  if (!(S.features && S.features.snowflake)) S.builds = null;
  loadReportsIndex().then(() => {
    if (S.node) renderCatalog(S.node);
    paintLineageBuilds();
  });
}

/* The settings button: a triangle while the profile is missing or refused (0100).
   It is lit by paintSpaces(), as a space. */
function paintSettingsButton() {
  const b = $('#settings-btn');
  const warn = profileWarning(S.profiles);
  b.dataset.warn = String(!!warn);
  b.title = ['Settings: the project\'s profile, environments and Python, column lineage, Snowflake, '
    + 'orchestration, updates, and help', warn].filter(Boolean).join('\n');
}

/* After the graph's column lineage changed: the Columns tab's counts, and the
   canvas, which cannot stay in column mode on edges that are gone. */
async function redrawLineage() {
  if (S.node) {
    try { renderCatalog(await nodeDetail({ id: S.node.id })); } catch { /* gone with the last manifest */ }
  }
  if (S.graphMode === 'column' && !(S.meta && S.meta.cll_edges)) {
    const id = S.focus || (S.colFocus && S.colFocus.id);
    if (id) focusNode(id);
    else { leaveColumnWait(); blankLineage(); }
  } else {
    rerender();
  }
}

/* One floating menu at a time, closed by a click outside it, Escape, a resize,
   or a second click on the button that opened it. `closed` runs once it is
   gone, however it went. One the pointer opened (openOnHover) also closes once
   the pointer has left it and its button, until a click holds it (0086). */
let popup = null;
const MENU_REST = 150;    // a pointer crossing the button on its way elsewhere opens nothing
const MENU_GRACE = 300;   // time to cross the gap between the button and its menu

/* Below the anchor when the menu fits there, above it otherwise, and inside
   the window either way. Again when a menu drawn anew has grown. A menu that
   says data-align=right sits under the right edge of its button, so it opens
   inward from the top bar's end. */
function placePopup(anchor, el) {
  const at = anchor.getBoundingClientRect();
  const box = el.getBoundingClientRect();
  const below = at.bottom + 4 + box.height <= window.innerHeight;
  el.style.top = `${below ? at.bottom + 4 : Math.max(4, at.top - 4 - box.height)}px`;
  const x = el.dataset.align === 'right' ? at.right - box.width : at.left;
  el.style.left = `${Math.min(Math.max(4, x), window.innerWidth - box.width - 4)}px`;
}

function openPopup(anchor, el, closed, hover = false) {
  closePopup();
  document.body.appendChild(el);
  placePopup(anchor, el);
  const live = () => [...el.querySelectorAll('button:not([aria-disabled="true"]), a[href]')];
  const onDown = (e) => {
    // A click in a menu the pointer opened holds it, so an answer it waits for is still read there.
    if (el.contains(e.target)) holdPopup();
    else if (!anchor.contains(e.target)) closePopup();
  };
  const onKey = (e) => {
    // Held by nothing, the menu has no focus: the keys go on to the editor or
    // the terminal that has it, and close the menu on their way, as they close
    // a hover card. Escape too, which vim in the terminal or the lineage's find
    // bar is waiting for. A modifier alone may be the start of a Cmd/Ctrl +
    // click on one of its links.
    if (me.hover) {
      if (['Shift', 'Control', 'Alt', 'Meta'].includes(e.key)) return;
      return closePopup();
    }
    if (e.key === 'Tab') {
      // A dialog's focus goes back to its button, so Tab goes on from there
      // and not from a card that is gone.
      const inside = el.getAttribute('role') === 'dialog' && el.contains(document.activeElement);
      closePopup();
      if (inside) anchor.focus();
      return;
    }
    const step = { ArrowDown: 1, ArrowUp: -1 }[e.key];
    if (e.key !== 'Escape' && !step) return;
    // Handled here only: the editor and the global shortcuts never see it.
    e.preventDefault();
    e.stopPropagation();
    if (e.key === 'Escape') {
      closePopup();
      anchor.focus();
      return;
    }
    const buttons = live();
    const i = buttons.indexOf(document.activeElement);
    if (buttons.length) buttons[(i + step + buttons.length) % buttons.length].focus();
  };
  const onResize = () => closePopup();
  document.addEventListener('mousedown', onDown, true);
  document.addEventListener('keydown', onKey, true);
  window.addEventListener('resize', onResize);
  const me = popup = {
    el, anchor, closed, hover, grace: null,
    focus: () => {
      const first = live();
      (first.find((b) => b.classList.contains('on') || 'first' in b.dataset) || first[0] || el).focus();
    },
    off: () => {
      clearTimeout(me.grace);
      document.removeEventListener('mousedown', onDown, true);
      document.removeEventListener('keydown', onKey, true);
      window.removeEventListener('resize', onResize);
    },
  };
  if (hover) {
    // Gone with the menu, so they need no taking off.
    el.addEventListener('mouseenter', () => clearTimeout(me.grace));
    el.addEventListener('mouseleave', popupLeft);
  } else {
    me.focus();
  }
}

/* The pointer left a menu it opened, or that menu's button: it closes unless
   the pointer comes back to either within MENU_GRACE. */
function popupLeft() {
  const p = popup;
  if (!p || !p.hover) return;
  clearTimeout(p.grace);
  p.grace = setTimeout(() => { if (popup === p && p.hover) closePopup(); }, MENU_GRACE);
}

/* A menu the pointer opened becomes one a click opened: it stays until a click
   elsewhere, Escape or its button again, and the keys reach it. */
function holdPopup() {
  if (!popup || !popup.hover) return;
  popup.hover = false;
  clearTimeout(popup.grace);
}

/* Whether any menu is open: the one popup, or one of the four that keep their
   own, with their own keys. */
function anyMenuOpen() {
  return !!(popup || crumbMenu || envMenu || selectorMenu || stopAtMenu);
}

/* `anchor`'s menu opens under the pointer, once the pointer has rested on it,
   unless another menu is open: one someone clicked open is not swapped for a
   pointer passing by, nor joined by a second taking the same keys.
   `open(true)` opens it unfocused, held by the pointer (0086). */
function openOnHover(anchor, open) {
  let timer = null;
  const mine = () => !!popup && popup.anchor === anchor;
  anchor.addEventListener('mouseenter', () => {
    clearTimeout(timer);
    if (mine()) return clearTimeout(popup.grace);
    timer = setTimeout(() => { if (!anyMenuOpen()) open(true); }, MENU_REST);
  });
  anchor.addEventListener('mouseleave', () => {
    clearTimeout(timer);
    if (mine()) popupLeft();
  });
  // A click opens it at once, without the rest.
  anchor.addEventListener('click', () => clearTimeout(timer));
}

/* Closes the open menu. True when `anchor` opened it, so the click on that
   button closes it rather than opening it again. The pointer having opened it
   already, that click holds it instead and gives it the focus, as a click
   that opened it would: a person reaching for the button out of habit has
   come to read it. */
function closePopup(anchor) {
  if (!popup) return false;
  const same = !!anchor && popup.anchor === anchor;
  if (same && popup.hover) {
    holdPopup();
    popup.focus();
    return true;
  }
  const { closed } = popup;
  popup.off();
  popup.el.remove();
  popup = null;
  if (closed) closed();
  return same;
}

/* The tests toggle above the lineage, an eye. Always open: the pressed look
   says whether the canvas draws data tests, the eye says which toggle this is.
   Its state lives on the button, read by testsOn(). */
function testsEye() {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 16 16');
  svg.setAttribute('aria-hidden', 'true');
  const draw = (tag, attrs) => {
    const e = document.createElementNS(ns, tag);
    for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, v);
    svg.appendChild(e);
  };
  draw('path', { d: 'M1.3 8C2.8 5.2 5.2 3.6 8 3.6S13.2 5.2 14.7 8C13.2 10.8 10.8 12.4 8 12.4S2.8 10.8 1.3 8Z' });
  draw('circle', { cx: 8, cy: 8, r: 2.1 });
  return svg;
}

/* The indirect toggle's glyph: a dashed line ending in an arrow head, as the
   edges it draws (0097, 0153). */
function indirectGlyph() {
  const svg = strokeIcon('0 0 16 16', '', ['M2 8h12', 'M10.5 5l3 3-3 3']);
  svg.firstChild.setAttribute('stroke-dasharray', '2 2');
  return svg;
}

/* How many tests the canvas was sent, in the tooltip of the tests toggle while
   it is on: the number that decides how heavy the picture is. */
function paintTestsCount(sub) {
  const b = $('#with-tests');
  if (b) b.title = testsTitle(testsOn(), testsOn() && sub ? sub.nodes.filter((n) => n && n.kind === 'test').length : 0);
}

function testsOn() {
  return $('#with-tests').getAttribute('aria-pressed') === 'true';
}

function foldersOn() {
  return $('#by-folder').getAttribute('aria-pressed') === 'true';
}

/* The levels, held to what is drawn: a 9 written into the input or a cleared
   one draws as its nearest bound rather than as nothing. */
function folderLevels() {
  const v = Math.round(+$('#folder-levels').value);
  return Number.isFinite(v) ? Math.min(4, Math.max(1, v)) : 1;
}

/* The levels one step further, held to what is drawn: 1 to 4, whatever the box
   held (0080). */
function stepLevels(v, dir) {
  const n = Math.round(+v);
  return Math.min(4, Math.max(1, (Number.isFinite(n) ? n : 1) + dir));
}

/* What the stepper beside By folder shows: only while the toggle is pressed,
   since without the bands the levels set nothing (0080), the number, and which
   of the two buttons still has somewhere to go. */
function levelsView(pressed, v) {
  return { shown: !!pressed, n: v, less: v > 1, more: v < 4 };
}

function paintLevels() {
  const v = levelsView(foldersOn(), folderLevels());
  $('#folder-steps').hidden = !v.shown;
  $('#levels-n').textContent = String(v.n);
  // aria-disabled, not disabled: a disabled button drops the keyboard's focus to the body.
  $('#levels-less').setAttribute('aria-disabled', String(!v.less));
  $('#levels-more').setAttribute('aria-disabled', String(!v.more));
}

/* By folder and its levels are one control: a minus, the number and a plus
   sit beside the toggle in the bar, so nothing opens over the canvas on a
   hover (0160, replacing the box of 0080). A click writes the hidden input
   that holds the number and fires the one change the canvas redraws on, as the
   depth does. */
function wireFolderLevels() {
  const input = $('#folder-levels');
  const step = (dir) => {
    const v = stepLevels(input.value, dir);
    if (v === folderLevels()) return;
    input.value = String(v);
    input.dispatchEvent(new Event('change'));
  };
  $('#levels-less').addEventListener('click', () => step(-1));
  $('#levels-more').addEventListener('click', () => step(1));
  // A number written some other way reads back as what is drawn.
  input.addEventListener('change', () => { input.value = String(folderLevels()); paintLevels(); });
  // After the toggle's own listener, so this reads the state it turned to.
  $('#by-folder').addEventListener('click', paintLevels);
  paintLevels();
}

function paintTestsToggle(on) {
  const b = $('#with-tests');
  b.setAttribute('aria-pressed', String(on));
  b.title = testsTitle(on);
  // The eye alone reads as nothing in particular: the word says what it shows.
  b.replaceChildren(testsEye(), Object.assign(document.createElement('span'), { textContent: 'Tests' }));
}

/* A snowflake drawn here, six arms and nothing more. Not Snowflake's logo:
   their marks are for uses they approve in writing, and this repository is
   public (0014). The name in text, and the colour, say which product it is. */
function snowflakeIcon() {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 16 16');
  svg.setAttribute('class', 'sficon');
  svg.setAttribute('aria-hidden', 'true');
  for (const turn of [0, 60, 120]) {
    const arm = document.createElementNS(ns, 'path');
    arm.setAttribute('d', 'M8 1.4v13.2M6.2 3.1 8 4.7l1.8-1.6M6.2 12.9 8 11.3l1.8 1.6');
    arm.setAttribute('transform', `rotate(${turn} 8 8)`);
    svg.appendChild(arm);
  }
  return svg;
}

/* Snowflake's features, in their section of the settings: a switch, what it
   covers and why it is on or off, kept per project (0011, 0031). Marked alpha,
   since none of it has been seen against a real warehouse yet (docs/state.md,
   Waiting on a human). */
function paintSetSnowflake(box) {
  const f = S.features || { snowflake: false, snowflake_set: false };
  const el = (tag, className, textContent = '') => Object.assign(document.createElement(tag), { className, textContent });
  // The switch's track takes the tool's colour from here.
  const main = el('section', 'sgroup');
  main.dataset.tool = 'snowflake';
  const { row, sc } = buildRow(['Snowflake features', el('span', 'alpha', 'alpha')],
    'With the profile\'s credentials, for this project only.');
  const toggle = el('button', 'switch');
  toggle.type = 'button';
  toggle.dataset.key = 'snowflake';
  toggle.setAttribute('role', 'switch');
  toggle.setAttribute('aria-checked', String(!!f.snowflake));
  toggle.setAttribute('aria-label', 'Snowflake features');
  toggle.title = f.snowflake ? 'Switch Snowflake\'s features off for this project' : 'Switch Snowflake\'s features on for this project';
  toggle.append(el('span', 'knob'));
  walkSwitch(toggle, 'snowflake', !!f.snowflake, box.isConnected);
  sc.append(toggle, el('span', 'fnote', featureNote(f, S.meta && S.meta.adapter)));
  // The whole row is the target, the name included, and the switch is what
  // the keyboard reaches. A second click while the first is on its way is
  // dropped, or the two would race to the server, whichever row a redraw
  // has put in its place meanwhile. The answer draws the section again, the
  // focus staying on the switch.
  row.classList.add('press');
  if (S.featuresBusy) row.setAttribute('aria-busy', 'true');
  row.addEventListener('click', async () => {
    if (S.featuresBusy) return;
    S.featuresBusy = true;
    repaintSettings();
    try { await setFeatures({ snowflake: !f.snowflake }); } finally {
      S.featuresBusy = false;
      repaintSettings();
    }
  });
  main.append(row);

  // After how many days without a success the builds call a model stale (0117).
  if (f.snowflake) {
    const days = setRow(main, 'Stale after', 'Days without a success after which a model reads stale.');
    const field = Object.assign(document.createElement('input'), {
      type: 'number', min: '1', max: '365', step: '1', value: String(f.builds_stale_days || 7), className: 'daysinput',
    });
    field.setAttribute('aria-label', 'Days without a success after which a model reads stale');
    field.addEventListener('change', () => {
      const n = Number(field.value);
      if (!Number.isInteger(n) || n < 1 || n > 365) {
        field.value = String(f.builds_stale_days || 7);
        return toast('stale after: a whole number of days from 1 to 365', 'err');
      }
      setStaleDays(n);
    });
    days.append(field, el('span', 'dim', 'days without a success'));
  }

  const adds = el('section', 'sgroup');
  setGroupHead(adds, 'What it adds');
  adds.append(el('p', 'sp2', 'Column lineage from Snowflake, fetched on click; the Query history tab, read from Snowflake '
    + 'when it opens; a Snowsight menu beside each relation in the Catalog; and Clone into my schema, '
    + 'under a model\'s location, which writes the statements that copy it and its direct parents '
    + 'from an environment into your schema, for you to run. With the dbt_artifacts package in the '
    + 'project, Last built in the Catalog and Builds by environment in Reports, read when asked.'));
  const warn = el('div', 'alphawarn');
  warn.append(el('b', '', 'Alpha.'), document.createTextNode(
    ' Snowflake\'s features are still being built, and have not yet been checked against a real warehouse. '
    + 'Expect rough edges, and check what they show against Snowflake itself.'));
  adds.append(warn);
  box.replaceChildren(main, adds);
}

/* A clock, for the jobs that run on one. */
function jobsIcon() {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 16 16');
  svg.setAttribute('class', 'sficon');
  svg.setAttribute('aria-hidden', 'true');
  for (const [tag, attrs] of [['circle', { cx: 8, cy: 8, r: 6.2 }], ['path', { d: 'M8 4.2V8l2.6 1.6' }]]) {
    const e = document.createElementNS(ns, tag);
    for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, v);
    svg.appendChild(e);
  }
  return svg;
}

async function setFeatures(body) {
  try {
    applyInfo(await api.send('/api/features', 'POST', body));
    await redrawLineage();
  } catch (e) {
    toast('settings: ' + e.message, 'err');
  }
}

/* The threshold of the builds, posted once the spinner rests: each click of it
   fires a change, and the last value wins. Nothing but the builds reads it, so
   they are painted again and the canvas is not drawn (0117). */
let staleDaysTimer = 0;
function setStaleDays(n) {
  clearTimeout(staleDaysTimer);
  staleDaysTimer = setTimeout(async () => {
    try {
      applyInfo(await api.send('/api/features', 'POST', { builds_stale_days: n }));
      repaintBuilds();
    } catch (e) {
      toast('settings: ' + e.message, 'err');
    }
  }, 400);
}

/* The profile lives outside the project, so it has its own route rather than a
   hole in the one that is confined to the project (0017). */
async function openProfiles() {
  const path = (S.profiles && S.profiles.path) || '';
  if (!path) return toast('no home directory to look for profiles.yml in: set DBT_PROFILES_DIR', 'err');
  const key = 'profile:' + path;
  if (!S.open.has(key)) {
    let body;
    try { body = await api.get('/api/profiles'); }
    catch (e) { return toast('profile: ' + e.message, 'err'); }
    S.open.set(key, { kind: 'profile', path: body.path, doc: CodeMirror.Doc(body.content, 'text/x-yaml'), dirty: false, hidden: body.hidden || 0 });
    S.order.push(key);
    // The secrets never reach the page (0054): saying so here is what keeps
    // anyone from thinking the password was wiped.
    if (body.hidden) toast(hiddenNote(body.hidden), 'ok');
  }
  activate(key, false);
}

function hiddenNote(n) {
  return `${n} secret value${n === 1 ? '' : 's'} hidden: leave the placeholder to keep one, or type over it to change it`;
}

/* The script reads the profile once, when it starts, so a correction that does
   not restart it changes nothing. The server restarts it and says so. */
async function saveProfile(key, f) {
  try {
    const saved = await api.send('/api/profiles', 'PUT', { content: f.doc.getValue() });
    f.dirty = false;
    // The next connection reads the new profile, maybe for another account.
    S.sfSession = null;
    await loadSidecar();
    if (S.node) renderCatalog(S.node);
    // The caller already says it saved; this is the part it cannot know.
    if (saved.restarted) toast('Snowflake script restarted on the new profile', 'ok');
    if (S.sidecar && S.sidecar.state === 'failed') toast('Snowflake lineage: ' + S.sidecar.error, 'err');
    return true;
  } catch (e) {
    toast(`save failed for ${fileName(key)}: ${e.message}`, 'err');
    return false;
  }
}

// -------------------------------------------------------------- Snowsight --
/* Snowsight is a link, never a call: built from the organization and account
   names the session reports, and opened by the browser in a new tab with no
   referrer (0048, 0051). */

/* The account's home in Snowsight, or '' while the organization is unknown: a
   link built from the account locator alone would open the wrong page, or none. */
function snowsightHome(session) {
  if (!session || !session.org || !session.account) return '';
  const seg = (s) => encodeURIComponent(String(s).toLowerCase());
  return `https://app.snowflake.com/${seg(session.org)}/${seg(session.account)}/#`;
}

/* A query's page in Snowsight. */
function snowsightUrl(session, queryId) {
  const home = snowsightHome(session);
  return home && queryId ? `${home}/compute/history/queries/${encodeURIComponent(queryId)}/detail` : '';
}

/* Where Snowsight files an object of one materialization, as its address
   spells it. The manifest does not say what a source is, so it is asked for as
   a table, which most are. */
function snowsightKind(materialized) {
  switch (materialized) {
    case 'view': return { path: 'view', label: 'view', guess: '' };
    case 'materialized_view': return { path: 'view', label: 'materialized view', guess: '' };
    case 'dynamic_table': return { path: 'dynamic-table', label: 'dynamic table', guess: '' };
    case 'source': return { path: 'table', label: 'table', guess: 'a source can be a view too: the manifest does not say' };
    default: return { path: 'table', label: 'table', guess: '' };
  }
}

/* One relation's pages in Snowsight, the object, its schema and its database,
   each named as Snowflake keeps it: unquoted in upper case, quoted as written.
   None while the account is unknown, or for a name that is not three parts. */
function snowsightPlaces(session, parts, materialized) {
  const home = snowsightHome(session);
  if (!home || !parts || parts.length !== 3 || parts.some((p) => !p.name)) return [];
  const [database, schema, object] = parts.map((p) => (p.quoted ? p.name : p.name.toUpperCase()));
  const kind = snowsightKind(materialized);
  const inDatabase = `${home}/data/databases/${encodeURIComponent(database)}`;
  const inSchema = `${inDatabase}/schemas/${encodeURIComponent(schema)}`;
  return [
    { what: kind.label, name: object, url: `${inSchema}/${kind.path}/${encodeURIComponent(object)}`, guess: kind.guess },
    { what: 'schema', name: schema, url: inSchema, guess: '' },
    { what: 'database', name: database, url: inDatabase, guess: '' },
  ];
}

// --------------------------------------------------------- query history --
/* The user's own queries, read live from Snowflake by the script, twenty at a
   time (0048). Nothing of it is kept: closing the page forgets it, and the
   detail of a query is Snowsight's, one link away. */

/* What the role menu offers. The connected target's role comes first, then the
   roles of the targets that sign in as it does, each once with every target
   that names it, then every role. A target that signs in as someone else, or
   whose role the profile does not spell out, is listed greyed with the reason:
   its queries are not in this user's history, or not under a name we know. */
function historyRoles(targets, target, sessionRole) {
  const list = targets || [];
  const own = list.find((t) => t.name === target);
  const ownRole = (own && own.role) || sessionRole || '';
  const first = { role: null, label: ownRole || 'the target\'s role', targets: target ? [target] : [] };
  const offered = [first];
  const seen = new Map([[ownRole.toUpperCase(), first]]);
  const greyed = [];
  for (const t of list) {
    if (t.name === target) continue;
    if (!t.same_login || !t.role) {
      greyed.push({ label: t.role || 'unknown role', targets: [t.name], why: t.why || 'its queries are not in this user\'s history' });
      continue;
    }
    const key = t.role.toUpperCase();
    if (seen.has(key)) {
      seen.get(key).targets.push(t.name);
      continue;
    }
    const o = { role: t.role, label: t.role, targets: [t.name] };
    seen.set(key, o);
    offered.push(o);
  }
  return { offered, all: { role: '*', label: 'All roles', targets: [] }, greyed };
}

/* Snowflake's execution status as one of a few states. A cancelled query is
   only told apart by its message, since its status says it failed. */
function queryState(row) {
  const s = (row && row.status) || '';
  if (s === 'success') return 'ok';
  if (s.startsWith('failed')) return /SQL execution canceled/i.test(row.error || '') ? 'cancelled' : 'failed';
  if (s === 'running' || s === 'resuming_warehouse') return 'running';
  if (s === 'queued' || s === 'blocked') return 'queued';
  return s || 'unknown';
}

function queryDuration(ms) {
  if (ms == null) return '';
  if (ms < 1000) return `${ms} ms`;
  if (ms < 60000) return `${(ms / 1000).toFixed(1)} s`;
  const mins = Math.floor(ms / 60000);
  if (mins < 60) return `${mins} min ${Math.round((ms % 60000) / 1000)} s`;
  return `${Math.floor(mins / 60)} h ${mins % 60} min`;
}

/* When a query started, on the reader's clock: the time alone today, the date
   too before, never an age. The offset is asked per moment, since a week can
   cross a change of summer time, and is an argument so tests do not depend on
   the machine running them. */
function historyTime(ms, nowMs, offsetAt) {
  const local = (t) => new Date(t + offsetAt(t) * 60000);
  const d = local(ms);
  const p = (x) => String(x).padStart(2, '0');
  const day = (x) => `${x.getUTCFullYear()}-${p(x.getUTCMonth() + 1)}-${p(x.getUTCDate())}`;
  const time = `${p(d.getUTCHours())}:${p(d.getUTCMinutes())}:${p(d.getUTCSeconds())}`;
  return day(d) === day(local(nowMs)) ? time : `${day(d)} ${time}`;
}

/* The line a statement is recognised by: dbt opens most of its own with a
   comment of metadata, so leading comments and blank lines are skipped. */
function sqlHead(text) {
  let s = String(text || '');
  for (;;) {
    const t = s.replace(/^\s+/, '');
    if (t.startsWith('/*')) {
      const end = t.indexOf('*/');
      if (end < 0) return '';
      s = t.slice(end + 2);
    } else if (t.startsWith('--')) {
      const end = t.indexOf('\n');
      if (end < 0) return '';
      s = t.slice(end + 1);
    } else {
      s = t;
      break;
    }
  }
  return s.split('\n')[0].replace(/\s+/g, ' ').trim();
}

async function loadHistory({ more = false } = {}) {
  const ask = ++S.historyAsk;
  const was = S.history || { rows: [] };
  const body = { role: S.historyRole };
  const last = was.rows[was.rows.length - 1];
  if (more && last) body.before = { at: last.at, query_id: last.query_id };
  S.history = { ...was, busy: more ? 'more' : 'page', error: null };
  renderHistory();
  try {
    const page = await api.send('/api/snowflake/history', 'POST', body);
    if (ask !== S.historyAsk) return;
    if (page.session) S.sfSession = page.session;
    S.history = {
      rows: more ? was.rows.concat(page.rows || []) : (page.rows || []),
      more: !!page.more,
      session: page.session || {},
      target: page.target || '',
      targets: page.targets || [],
      fetched: new Date(),
      busy: '',
      error: null,
    };
    S.colAnswered = true;
  } catch (e) {
    if (ask !== S.historyAsk) return;
    S.history = { ...was, busy: '', error: e };
  }
  renderHistory();
  // The script may have just started for this, which the settings show.
  loadSidecar();
}

/* Another role reads another history: it starts again from the newest. */
function pickHistoryRole(role) {
  S.historyRole = role;
  S.history = { ...(S.history || {}), rows: [], more: false };
  loadHistory();
}

function openHistoryRoles(anchor) {
  if (closePopup(anchor)) return;
  const h = S.history || {};
  const { offered, all, greyed } = historyRoles(h.targets, h.target, h.session && h.session.role);
  const menu = document.createElement('div');
  menu.className = 'envmenu histmenu';
  menu.setAttribute('role', 'menu');
  const add = (o, disabled) => {
    const item = document.createElement('button');
    item.type = 'button';
    item.setAttribute('role', 'menuitemradio');
    const on = !disabled && o.role === S.historyRole;
    item.setAttribute('aria-checked', String(on));
    if (on) item.classList.add('on');
    if (disabled) {
      item.setAttribute('aria-disabled', 'true');
      item.title = `Not readable from this connection: ${o.why}.`;
    }
    item.append(
      Object.assign(document.createElement('span'), { className: 'check', textContent: on ? '✓' : '' }),
      Object.assign(document.createElement('span'), { className: 'lbl', textContent: o.label }),
    );
    if (o.targets.length) {
      item.append(Object.assign(document.createElement('span'), { className: 'sub', textContent: o.targets.join(', ') }));
    }
    item.addEventListener('click', () => {
      if (disabled) return;
      closePopup();
      if (o.role !== S.historyRole) pickHistoryRole(o.role);
    });
    menu.appendChild(item);
  };
  offered.forEach((o) => add(o));
  menu.appendChild(document.createElement('hr'));
  add(all);
  if (greyed.length) {
    menu.appendChild(Object.assign(document.createElement('div'), {
      className: 'menuhead', textContent: 'not in this user\'s history',
    }));
    greyed.forEach((o) => add(o, true));
  }
  openPopup(anchor, menu);
}

/* The tab is offered only while Snowflake's features are on (0031). Switched
   off, what it held is forgotten, and a tab left open falls back to the
   lineage. */
function paintHistoryTab() {
  const on = !!(S.features && S.features.snowflake);
  $('#history-tab').classList.toggle('hidden', !on);
  if (on) return;
  S.history = null;
  S.historyRole = null;
  S.sfSession = null;
  if (S.dock === 'history') showDock('lineage');
}

function renderHistory() {
  const pane = $('#dock-history');
  const h = S.history || { rows: [] };
  const el = (tag, className, textContent = '') => Object.assign(document.createElement(tag), { className, textContent });
  const wrap = el('div', 'history');
  const tools = el('div', 'histtools');
  tools.dataset.tool = 'snowflake';

  const roles = historyRoles(h.targets, h.target, h.session && h.session.role);
  const current = S.historyRole === '*' ? roles.all.label
    : S.historyRole === null ? roles.offered[0].label : S.historyRole;
  const pick = el('button', 'btn sm', `Role: ${current} ▾`);
  pick.type = 'button';
  pick.setAttribute('aria-haspopup', 'menu');
  pick.title = 'Whose queries: the role of the target dbt-edith connects with, another target\'s, or every role';
  pick.addEventListener('click', () => openHistoryRoles(pick));
  const refresh = el('button', 'btn sm', 'Refresh');
  refresh.type = 'button';
  refresh.title = 'Ask Snowflake again for the twenty newest';
  refresh.disabled = !!h.busy;
  refresh.addEventListener('click', () => loadHistory());
  const said = el('span', 'histsaid muted');
  if (h.busy === 'page') said.textContent = 'asking Snowflake';
  else if (h.fetched) {
    const p = (x) => String(x).padStart(2, '0');
    const at = `${p(h.fetched.getHours())}:${p(h.fetched.getMinutes())}:${p(h.fetched.getSeconds())}`;
    said.textContent = [h.target && `target ${h.target}`, h.session && h.session.user, `read at ${at}`].filter(Boolean).join(' · ');
  }
  tools.append(snowflakeIcon(), pick, refresh, said);
  wrap.append(tools);

  const body = el('div', 'histbody');
  if (h.error) {
    const fail = el('div', 'histnote bad');
    fail.append(el('b', '', 'Snowflake did not answer. '), document.createTextNode(h.error.message));
    // A refused connection or a script that could not start is the profile's
    // business, so the file is one click away.
    const link = (h.error.phase === 'connect' || h.error.phase === 'start') && profileLink();
    if (link) fail.append(document.createTextNode(' The connection comes from '), link, document.createTextNode('.'));
    body.append(fail);
  }
  if (!h.rows.length) {
    if (h.busy) {
      body.append(el('p', 'muted pad', S.colAnswered
        ? 'Asking Snowflake for your queries.'
        : 'Asking Snowflake for your queries. A sign-in tab may open if the session needs one.'));
    } else if (h.fetched) {
      body.append(el('p', 'muted pad', `No query of yours under ${current === roles.all.label ? 'any role' : `role ${current}`} in the last 7 days.`));
    }
    wrap.append(body);
    pane.replaceChildren(wrap);
    return;
  }

  const table = el('table', 'cols histtable');
  const head = el('tr');
  for (const [name, title, className = ''] of [
    ['Started', 'On this machine\'s clock'], ['', 'How it ended'], ['Took', 'Total elapsed time', 'h-num'], ['Role', ''],
    ['Warehouse', ''], ['Type', ''], ['Query', 'The first line, comments left out. Click a row for more.'],
    ['Rows', 'Rows produced', 'h-num'], ['', ''],
  ]) {
    const th = el('th', className, name);
    if (title) th.title = title;
    head.append(th);
  }
  table.append(head);
  const now = Date.now();
  const offsetAt = (t) => -new Date(t).getTimezoneOffset();
  for (const row of h.rows) {
    const tr = el('tr', 'h-row');
    const state = queryState(row);
    const started = Date.parse(row.start);
    const when = el('td', 'h-when', historyTime(started, now, offsetAt));
    when.title = `${exportStamp(Math.floor(started / 1000), offsetAt(started))}\n${row.start}`;
    const dot = el('td', 'h-state');
    dot.append(Object.assign(el('span', 'qdot'), { title: state === 'ok' ? 'succeeded' : state }));
    dot.dataset.state = state;
    const query = el('td', 'h-sql');
    query.append(el('div', 'h-head', sqlHead(row.text) || '(empty)'));
    if (row.error) query.append(el('div', 'h-err', row.error));
    const link = el('td', 'h-link');
    const url = snowsightUrl(h.session, row.query_id);
    if (url) {
      const a = el('a', 'filelink', 'Snowsight ↗');
      a.href = url;
      a.target = '_blank';
      a.rel = 'noopener noreferrer';
      a.title = 'Open this query in Snowsight, in a new tab';
      a.addEventListener('click', (e) => e.stopPropagation());
      link.append(a);
    }
    tr.append(when, dot, el('td', 'h-num', queryDuration(row.ms)), el('td', 'h-mono', row.role || ''),
      el('td', 'h-mono', row.warehouse || ''), el('td', 'h-type', (row.type || '').toLowerCase().replace(/_/g, ' ')),
      query, el('td', 'h-num', row.rows == null ? '' : String(row.rows)), link);
    tr.addEventListener('click', () => toggleHistoryRow(tr, row, h.session));
    table.append(tr);
  }
  body.append(table);

  const foot = el('div', 'histfoot');
  if (h.more) {
    const more = el('button', 'btn sm', h.busy === 'more' ? 'Loading…' : 'Load 20 more');
    more.type = 'button';
    more.disabled = !!h.busy;
    more.addEventListener('click', () => loadHistory({ more: true }));
    foot.append(more);
  } else {
    foot.append(el('span', 'muted', 'Nothing older: Snowflake gives back your newest 10 000 queries of the last 7 days.'));
  }
  body.append(foot);
  wrap.append(body);
  pane.replaceChildren(wrap);
}

/* A row opens under itself to show the statement as far as it was sent, and
   what it takes to find it again: its id, copied in one click. */
function toggleHistoryRow(tr, row, session) {
  const next = tr.nextElementSibling;
  if (next && next.classList.contains('h-detail')) {
    next.remove();
    tr.classList.remove('h-open');
    return;
  }
  tr.classList.add('h-open');
  const detail = document.createElement('tr');
  detail.className = 'h-detail';
  const td = document.createElement('td');
  td.colSpan = tr.children.length;
  const pre = Object.assign(document.createElement('pre'), { className: 'h-text', textContent: row.text || '' });
  const bar = Object.assign(document.createElement('div'), { className: 'h-bar' });
  const id = Object.assign(document.createElement('code'), { textContent: row.query_id });
  const copyId = Object.assign(document.createElement('button'), { className: 'btn sm', type: 'button', textContent: 'Copy id' });
  copyId.addEventListener('click', () => copyText(row.query_id, 'the query id'));
  const copySql = Object.assign(document.createElement('button'), { className: 'btn sm', type: 'button', textContent: 'Copy SQL' });
  copySql.addEventListener('click', () => copyText(row.text || '', 'the SQL'));
  bar.append(id, copyId, copySql);
  const cut = (row.text || '').length < (row.length || 0);
  if (cut || !snowsightUrl(session, row.query_id)) {
    bar.append(Object.assign(document.createElement('span'), {
      className: 'muted',
      textContent: [
        cut && `the first ${(row.text || '').length.toLocaleString()} of ${row.length.toLocaleString()} characters`,
        snowsightUrl(session, row.query_id) ? 'the rest is in Snowsight' : 'no Snowsight link: the account\'s organization is unknown',
      ].filter(Boolean).join(': '),
    }));
  }
  td.append(bar, pre);
  detail.append(td);
  tr.after(detail);
}

/* A column clicked in the Catalog, or double-clicked on the canvas. With
   Snowflake picked, its lineage is fetched from Snowflake before it is drawn;
   otherwise the cache is drawn as it is. */
async function openColumn(n, column) {
  // Collin's cache is behind the manifest: one run brings it level first. The
  // run's state is set before it yields, so focusColumn puts the column on a
  // waiting canvas at once, and the run's end draws the column asked for last:
  // drawing here as well would put this one over a column clicked meanwhile.
  if (S.cllTool === 'collin' && S.collin && S.collin.found && S.collin.stale && S.collin.state !== 'running') {
    const run = regenerateCollin();
    focusColumn(n.id, column);
    await run;
    return;
  }
  if (!sidecarOn()) return focusColumn(n.id, column);
  const rel = lineageRelation(n, S.env);
  if (!rel.text) return toast(`no Snowflake lineage for ${column}: ${rel.reason}`, 'err');
  const ask = ++S.colAsk;
  const status = $('#lineage-status');
  showDock('lineage');
  status.title = '';
  status.textContent = `querying Snowflake for ${column} in ${rel.text}`
    + (S.colAnswered ? '' : ' (the first query of a session may open a sign-in tab)');
  S.sidecar = Object.assign({}, S.sidecar, { state: 'busy' });
  paintSourceButton();
  try {
    const res = await api.send('/api/collineage/fetch', 'POST', {
      id: n.id, column, relation: rel.text, env: rel.file, up: +$('#up').value, down: +$('#down').value,
    });
    if (ask !== S.colAsk) return;
    S.colAnswered = true;
    if (res.added) {
      applyInfo(await api.get('/api/meta'));
      if (S.node && S.node.id === n.id) {
        highlightColumn(column, n.id);
        renderCatalog(await nodeDetail({ id: n.id }));
      }
    }
    const outside = res.unmatched_total
      ? ` · ${res.unmatched_total} object${res.unmatched_total > 1 ? 's' : ''} outside the project`
      : '';
    if (!res.up && !res.down) {
      status.textContent = `Snowflake has no column lineage for ${column} in ${res.relation}${outside}`;
      status.title = res.unmatched.join('\n');
      return;
    }
    await focusColumn(n.id, column);
    if (ask !== S.colAsk) return;
    status.textContent += ` · from Snowflake, ${res.added} new${outside}`;
    status.title = res.unmatched.length ? 'Not nodes of this project:\n' + res.unmatched.join('\n') : '';
  } catch (e) {
    if (ask !== S.colAsk) return;
    const advice = connectionAdvice(e.message, e.phase, (S.sidecar && S.sidecar.profiles) || '');
    status.textContent = advice.ask ? `${advice.text}  ·  ${advice.ask} ` : advice.text;
    const link = advice.file ? profileLink() : null;
    if (link) status.appendChild(link);
    toast('Snowflake lineage: ' + e.message, 'err');
  } finally {
    await loadSidecar();
  }
}

/* Only what is actually on screen, so the legend stays short and always matches
   what is drawn.

   Model mode explains the boxes, whose colour is the materialization. Column
   mode explains the edges instead, whose colour is what happened to the column:
   that is the question the column graph exists to answer, and repeating the
   materializations there would explain something nobody is looking at. With
   no role on any edge, a lone column or a cache that names none, it explains
   the boxes again.

   The badges in column mode either way: `raw`, `generated` and `mixed` only
   ever appear on a box, and a legend that skipped them would leave their
   colours unexplained, a root nothing reads included, drawn with no edge.

   Pure, and shared with an exported graph, so the file and the screen explain
   the same colours. */
function legendEntries(sub) {
  const seen = new Map();
  const kinds = sub.edge_kinds || [];
  const badges = sub.mode === 'column' ? Lineage.nodeRoles(sub) : [];
  if (!kinds.length) {
    for (const n of sub.nodes) {
      const label = Lineage.matLabel(n);
      if (!seen.has(label)) seen.set(label, Lineage.nodeColor(n));
    }
  }
  // The indirect roles are told by their SQL clause and listed apart, at the
  // end, behind an `indirect` entry that lights all three (0097, 0118).
  const rows = Lineage.rowLegend(kinds);
  const apart = new Set(rows.map(([label]) => label));
  for (const k of kinds.map(Lineage.edgeLegendLabel).concat(badges)) {
    if (k && !apart.has(k) && !seen.has(k)) seen.set(k, Lineage.legendColour(k));
  }
  return [...seen].sort((a, b) => a[0].localeCompare(b[0])).concat(rows);
}

function paintLegend(sub) {
  const host = $('#lineage-legend'), entries = legendEntries(sub);
  host.textContent = '';
  // A pick the new graph has nothing of would fade the whole canvas.
  if (!entries.some(([label]) => label === Lineage.picked())) Lineage.pick(null);
  const mark = () => {
    host.classList.toggle('picking', !!Lineage.picked());
    [...host.children].forEach((chip) => {
      const on = chip.dataset.label === Lineage.picked();
      chip.classList.toggle('on', on);
      chip.setAttribute('aria-pressed', String(on));
      chip.title = on ? 'Show everything again' : `Highlight ${chip.dataset.label}, fade the rest`;
    });
  };
  entries.forEach(([label, colour]) => {
    const chip = document.createElement('span');
    chip.dataset.label = label;
    chip.setAttribute('role', 'button');
    chip.tabIndex = 0;
    const sq = document.createElement('i');
    const swatch = Lineage.legendSwatch(label, colour);
    if (swatch.cls) sq.className = swatch.cls;
    sq.setAttribute('style', swatch.style);
    chip.append(sq, document.createTextNode(label));
    const toggle = () => { Lineage.pick(Lineage.picked() === label ? null : label); mark(); };
    chip.addEventListener('click', toggle);
    chip.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(); } });
    host.appendChild(chip);
  });
  mark();
}

/* Where the column walk stops downstream (0083): an edge of a role ticked
   here is drawn with the column it reaches, and nothing past that column.
   Beside the depth rather than in the legend, being a depth of a kind:
   it changes what the server walks, where a legend click only repaints. */
function paintStopAt() {
  paintIndirectToggle();
  const b = $('#stop-at');
  b.classList.toggle('hidden', S.graphMode !== 'column');
  // Ticking a role outside column mode would redraw whatever mode is on.
  if (S.graphMode !== 'column') closeStopAt();
  const on = [...S.colCut].sort();
  // Short, the bar being full in column mode: one role by name, more counted.
  b.querySelector('span').textContent = !on.length ? '' : on.length === 1 ? on[0] : `${on.length} roles`;
  b.classList.toggle('on', on.length > 0);
  b.title = on.length
    ? `Downstream, the walk ends at the column each ${on.join(' or ')} edge reaches`
    : 'Pick roles the walk downstream stops at: their edges stay, what comes after them goes';
}

/* Whether the cache holds collin's indirect edges, by the roles /api/meta
   counts: what puts the indirect button in view (0097). */
function cacheHasIndirect(cllKinds) {
  return (cllKinds || []).some((k) => Lineage.isRowKind(k.kind));
}

/* The roles the stop at menu offers: never an indirect one, whether the
   button is on or not. Downstream such an edge ends on its model's box and
   walks no further, so a stop at it would stop nothing (0118). */
function stopAtKinds(cllKinds) {
  return (cllKinds || []).filter((k) => !Lineage.isRowKind(k.kind));
}

/* The stop at roles kept as the indirect button turns: an indirect role
   ticked, by a version that offered it, goes, since it would stop nothing and
   the menu no longer lists it. A new set, the one given left as it was. */
function cutsKept(cut) {
  return new Set([...cut].filter((r) => !Lineage.isRowKind(r)));
}

/* The indirect button, in column mode only, and only when the cache holds
   indirect edges, so a cache without them shows nothing new (0097). */
function paintIndirectToggle() {
  const b = $('#indirect-btn');
  if (!b) return;
  const shown = S.graphMode === 'column' && cacheHasIndirect(S.meta && S.meta.cll_kinds);
  b.classList.toggle('hidden', !shown);
  b.setAttribute('aria-pressed', String(S.colIndirect));
  b.title = S.colIndirect
    ? 'collin\'s indirect edges are drawn dashed, upstream from column to column, downstream to one box for the whole model, each named by its SQL clause: QUALIFY, JOIN or WHERE / HAVING. They say which rows a model keeps. Click to leave them out'
    : 'collin\'s indirect edges, a filter\'s, a join key\'s or a dedup key\'s, are left out: the walk, the edges and the counts are the values\' alone. Click to draw them';
  b.replaceChildren(indirectGlyph(), Object.assign(document.createElement('span'), { textContent: 'Indirect' }));
}

/* The roles the stop at menu lists: every one the cache holds, then any ticked
   that it lost, each with its edges on the canvas, so the menu adds up to the
   status line's count beside it rather than to the project's (0089). Busiest
   on the canvas first, then in the cache's order. */
function stopAtRoles(cacheKinds, edgeKinds, ticked) {
  const here = roleCounts(edgeKinds);
  const roles = cacheKinds.filter((k) => k.kind && k.kind !== 'unknown').map((k) => ({ role: k.kind, total: k.edges }));
  for (const r of ticked) if (!roles.some((x) => x.role === r)) roles.push({ role: r, total: 0 });
  // A stable sort, so a tie keeps the cache's order.
  return roles.map((x) => ({ ...x, here: here.get(x.role) || 0 })).sort((a, b) => b.here - a.here);
}

function roleCounts(edgeKinds) {
  const here = new Map();
  for (const k of edgeKinds || []) here.set(k, (here.get(k) || 0) + 1);
  return here;
}

/* The edges drawn that the cache names no role for, which no row can stop at:
   a line of their own, so the menu still adds up to the status line. */
function unroled(here) {
  return (here.get('') || 0) + (here.get('unknown') || 0);
}

/* The indirect edges drawn, which the menu lists no role for: an edge that
   ends on a model's box has nothing past it to stop (0118). A line of their
   own, so the menu still adds up to the status line's edge count. */
function indirectDrawn(here) {
  let n = 0;
  for (const [role, count] of here) if (Lineage.isRowKind(role)) n += count;
  return n;
}

let stopAtMenu = null;
function closeStopAt({ refocus = false } = {}) {
  if (!stopAtMenu) return;
  const { el, anchor, off } = stopAtMenu;
  stopAtMenu = null;
  off();
  el.remove();
  if (refocus && anchor.isConnected) anchor.focus();
}

function openStopAt(anchor) {
  if (stopAtMenu) return closeStopAt();
  const roles = stopAtRoles(stopAtKinds(S.meta && S.meta.cll_kinds), S.colSub && S.colSub.edge_kinds, S.colCut);
  // Each item's count, repainted when the graph a tick asked for arrives.
  const counts = [];
  const bare = Object.assign(document.createElement('div'), { className: 'menunote' });
  const rows = Object.assign(document.createElement('div'), { className: 'menunote' });
  const countBare = (here) => {
    const n = unroled(here), m = indirectDrawn(here);
    bare.textContent = n ? `${n} edge${n === 1 ? '' : 's'} with no role` : '';
    bare.classList.toggle('hidden', !n);
    rows.textContent = m ? `${m} indirect edge${m === 1 ? '' : 's'}, which no stop applies to` : '';
    rows.classList.toggle('hidden', !m);
  };
  const el = document.createElement('div');
  el.className = 'envmenu stopmenu';
  el.setAttribute('role', 'menu');
  el.setAttribute('aria-label', 'Roles the column walk stops at');
  el.append(Object.assign(document.createElement('div'), { className: 'menuhead', textContent: 'Stop downstream after' }));
  if (!roles.length) el.append(Object.assign(document.createElement('div'), { className: 'menunote', textContent: 'The column lineage names no roles.' }));
  roles.forEach(({ role, total, here }) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.setAttribute('role', 'menuitemcheckbox');
    const paint = () => {
      const on = S.colCut.has(role);
      b.setAttribute('aria-checked', String(on));
      b.querySelector('.check').textContent = on ? '✓' : '';
    };
    // A line, dashed for an indirect role, as its edges are drawn (0162).
    const sq = document.createElement('i');
    const line = Lineage.roleSwatch(role);
    sq.className = line.dashed ? 'rolesq dash' : 'rolesq';
    sq.setAttribute('style', line.style);
    b.append(Object.assign(document.createElement('span'), { className: 'check' }), sq,
      Object.assign(document.createElement('span'), { className: 'lbl', textContent: role }),
      Object.assign(document.createElement('span'), { className: 'sub' }));
    // Dimmed rather than left out: a deeper walk may still meet one.
    const count = (n) => {
      b.querySelector('.sub').textContent = n ? `${n} edge${n === 1 ? '' : 's'}` : '';
      b.classList.toggle('absent', !n);
      b.title = `${n ? n : 'none'} on the canvas, ${total} in the project`;
    };
    count(here);
    counts.push([role, count]);
    // Stays open: several roles can be ticked in a row.
    b.addEventListener('click', () => {
      if (S.colCut.has(role)) S.colCut.delete(role); else S.colCut.add(role);
      paint();
      paintStopAt();
      rerender();
    });
    paint();
    el.appendChild(b);
  });
  countBare(roleCounts(S.colSub && S.colSub.edge_kinds));
  el.append(bare, rows);
  document.body.appendChild(el);
  const place = placeFloating(anchor.getBoundingClientRect(), el.getBoundingClientRect(),
    { width: window.innerWidth, height: window.innerHeight }, 4);
  el.style.top = `${place.top}px`;
  el.style.left = `${place.left}px`;
  const onKey = (e) => {
    if (e.key === 'Tab') return closeStopAt();
    const step = { ArrowDown: 1, ArrowUp: -1 }[e.key];
    if (e.key !== 'Escape' && !step) return;
    e.preventDefault();
    e.stopPropagation();
    if (e.key === 'Escape') return closeStopAt({ refocus: true });
    const items = [...el.querySelectorAll('button')];
    const at = items.indexOf(document.activeElement);
    if (items.length) items[(at + step + items.length) % items.length].focus();
  };
  const onDown = (e) => { if (!el.contains(e.target) && !anchor.contains(e.target)) closeStopAt(); };
  const onResize = () => closeStopAt();
  document.addEventListener('keydown', onKey, true);
  document.addEventListener('mousedown', onDown, true);
  window.addEventListener('resize', onResize);
  stopAtMenu = {
    el, anchor,
    recount: (edgeKinds) => {
      const here = roleCounts(edgeKinds);
      for (const [role, count] of counts) count(here.get(role) || 0);
      countBare(here);
    },
    off: () => {
      document.removeEventListener('keydown', onKey, true);
      document.removeEventListener('mousedown', onDown, true);
      window.removeEventListener('resize', onResize);
    },
  };
  const first = el.querySelector('button');
  if (first) first.focus();
}

/* ---- the depth, in dbt's words (0158) ---------------------------------------
   `1+ customers +0`: each number opens a menu of the levels that exist, each
   saying what it adds, around the focus name (the column chip in column mode).
   #up and #down stay the inputs holding the depth, hidden: the rest of the page
   reads and writes them, and a pick writes one and fires one change. The pure
   parts run from cutMiddle to shownDepth, which web/tests/depth.js slices. */

/* A name past 24 characters is cut in the middle, 12 and 11 around the
   ellipsis, so its start and its end both stay (the board's own). */
function cutMiddle(name) {
  return name.length <= 24 ? name : name.slice(0, 12) + '…' + name.slice(-11);
}

/* What the copy button writes: dbt's own selector, with a side that is zero
   dropped. dbt's fqn method searches no source, so a source is named by the
   source: method; a model's version, orders.v2, is the name dbt reads (0104). */
function depthSelector(kind, name, up, down) {
  const sel = kind === 'source' ? `source:${name}` : name;
  return `${up ? up + '+' : ''}${sel}${down ? '+' + down : ''}`;
}

/* A label the server counted by, with the noun it takes: the known kinds and
   materializations in words, any other as a custom materialization is, a model
   of that kind. */
function depthWords(label, n) {
  const known = {
    view: ['view', 'views'], table: ['table', 'tables'], seed: ['seed', 'seeds'], source: ['source', 'sources'],
    snapshot: ['snapshot', 'snapshots'], exposure: ['exposure', 'exposures'], analysis: ['analysis', 'analyses'],
    column: ['column', 'columns'], model: ['model', 'models'],
    incremental: ['incremental model', 'incremental models'], ephemeral: ['ephemeral model', 'ephemeral models'],
    materialized_view: ['materialized view', 'materialized views'], other: ['other node', 'other nodes'],
  };
  const words = Object.prototype.hasOwnProperty.call(known, label) ? known[label] : [`${label} model`, `${label} models`];
  return words[n === 1 ? 0 : 1];
}

/* What one level adds, in a menu row: its nodes by label, a lone one by name,
   "or more" where the cap cut a column walk short, and "all" on the last level
   when the graph ends there. */
function levelAdds(level, last, more) {
  const kinds = (level && level.kinds) || [];
  let text;
  if (level && level.name) text = '+ ' + cutMiddle(level.name);
  else if (!kinds.length) text = '+ nothing new';
  else text = '+ ' + kinds.map(([label, n]) => `${n} ${depthWords(label, n)}`).join(', ');
  const cut = !!(level && level.cut);
  if (cut) text += ' or more';
  return last && !more && !cut ? text + ' · all' : text;
}

/* A menu's rows: the focus alone, then a row for each level that exists, the
   one drawn checked. A depth the graph does not reach, as 1 on a model with no
   children, checks the last row there is. `levels` is the answer's, both sides;
   nothing when the side has no level. `full` is the row whole, for its title. */
function depthRows(side, name, levels, current) {
  const list = (levels && levels[side]) || [];
  if (!list.length) return [];
  const more = !!levels[side + '_more'];
  const at = Math.min(+current || 0, list.length);
  const write = (n, shown) => {
    const bare = shown ? cutMiddle(name) : name;
    if (!n) return bare;
    return side === 'up' ? `${n}+${bare}` : `${bare}+${n}`;
  };
  const rows = [{ n: 0, sel: write(0, true), full: write(0, false), adds: 'alone', cur: at === 0 }];
  list.forEach((level, i) => {
    rows.push({ n: i + 1, sel: write(i + 1, true), full: write(i + 1, false),
      adds: levelAdds(level, i === list.length - 1, more), cur: at === i + 1 });
  });
  return rows;
}

/* The number a button shows: the depth the box holds, held to the levels that
   exist. The box keeps its value, so the depth still carries to the next model;
   unknown levels leave it as it is. `list` is one side's levels. */
function shownDepth(value, list) {
  const n = Math.max(0, Math.floor(+value) || 0);
  return list ? Math.min(n, list.length) : n;
}

/* What a lineage answer is for the depth control: its levels, kept under the
   ask that made them, so a menu opened before the answer waits for it and one
   opened after never lists another focus's levels. */
function askDepth(key) {
  if (S.depthLevels && S.depthLevels.key !== key) S.depthLevels = null;
  S.depthKey = key;
}

function landDepth(key, sub) {
  if (key !== S.depthKey) return;
  const f = sub.mode === 'model' && sub.nodes[sub.focus];
  S.depthLevels = { key, levels: sub.levels || null,
    kind: f ? f.kind : '', colour: f ? Lineage.nodeColor(f) : '' };
  paintDepth();
}

/* The kind of the focus for the copy: the answer's, and before it lands the
   unique_id's own prefix, so a source is never copied without `source:`. */
function depthKind() {
  if (S.graphMode === 'column') return '';
  if (/^source\./.test(S.focus || '')) return 'source';
  return S.depthLevels ? S.depthLevels.kind : '';
}

/* The name the control is about, and what it calls a side with nothing on it. */
function depthName() {
  if (S.graphMode === 'column' && S.colFocus) return S.colFocus.column;
  return S.focus ? nameOfId(S.focus, S.node) : '';
}

function paintDepth() {
  const col = S.graphMode === 'column' && !!S.colFocus;
  const selecting = S.graphMode === 'select';
  const name = depthName();
  const has = !!name;
  const held = S.depthLevels;
  const levels = !selecting && held ? held.levels : null;
  const input = { up: $('#up'), down: $('#down') };
  const group = $('#depth-sel');
  group.title = col
    ? 'How far the column lineage goes. No dbt selector says this, so there is nothing to copy.'
    : 'How far the lineage goes, as a dbt selector';
  const shown = {};
  for (const side of ['up', 'down']) {
    const list = levels ? levels[side] : null;
    shown[side] = shownDepth(input[side].value, list);
    const b = $(`#${side}-btn`);
    b.querySelector('b').textContent = String(shown[side]);
    // Empty only when the graph has nothing there: a side the cap emptied is cut, not childless.
    const empty = has && !!list && !list.length && !levels[`${side}_more`];
    const word = side === 'up' ? 'upstream' : 'downstream';
    b.disabled = selecting;
    b.setAttribute('aria-disabled', String(!selecting && (!has || empty)));
    b.setAttribute('aria-label', `Levels ${word}${empty ? ': none' : ''}`);
    if (empty) b.title = `${name} has no ${side === 'up' ? 'parents' : 'children'}`;
    else if (!has && !selecting) b.title = 'Select a model to see its lineage.';
    else b.removeAttribute('title');
  }
  const fn = $('#depth-name');
  fn.textContent = col ? '' : cutMiddle(name);
  fn.title = col || !has ? '' : name;
  const bar = $('#depth-bar');
  bar.classList.toggle('on', !col && has);
  bar.setAttribute('aria-label', name);
  bar.title = name;
  // The previous focus's colour is not this one's: none until the answer says.
  if (held && held.colour && !col) bar.style.setProperty('--kind', held.colour);
  else bar.style.removeProperty('--kind');
  const copy = $('#depth-copy');
  copy.classList.toggle('hidden', col || !has);
  copy.disabled = selecting;
  if (!col && has) {
    copy.setAttribute('aria-label', `Copy the selector ${depthSelector(depthKind(), name, shown.up, shown.down)}`);
  }
  if (depthMenu) fillDepthMenu();
}

/* The copy button: the selector as shown, in dbt's syntax. The clipboard being
   refused is said, as every other copy does. */
async function copyDepth() {
  const held = S.depthLevels;
  const sel = depthSelector(depthKind(), depthName(),
    shownDepth($('#up').value, held && held.levels ? held.levels.up : null),
    shownDepth($('#down').value, held && held.levels ? held.levels.down : null));
  try {
    await navigator.clipboard.writeText(sel);
    toast('Copied ' + sel, 'ok');
  } catch { toast('clipboard unavailable', 'err'); }
}

let depthMenu = null;      // {side, el, anchor} while a levels menu is open

function closeDepthMenu() {
  if (depthMenu && popup && popup.anchor === depthMenu.anchor) closePopup();
}

/* The menu's content from the levels held now: a wait while there are none, the
   rows once they land (this is also what refills it in place, keeping the focus
   on its row), and its footers. */
function fillDepthMenu() {
  const { side, el, anchor } = depthMenu;
  const name = depthName();
  const word = side === 'up' ? 'Upstream' : 'Downstream';
  const held = S.depthLevels;
  const levels = held ? held.levels : null;
  const was = [...el.querySelectorAll('button')].indexOf(document.activeElement);
  const had = document.activeElement === el || was >= 0;
  const make = (tag, className, text = '') => Object.assign(document.createElement(tag), { className, textContent: text });
  el.textContent = '';
  el.setAttribute('aria-label', `${word} of ${name}`);
  const head = make('div', 'menuhead', `${word} of ${cutMiddle(name)}`);
  head.title = `${word} of ${name}`;
  el.append(head);
  if (!levels) {
    el.append(make('div', 'lvwait', 'Counting the levels…'));
  } else {
    const input = $(side === 'up' ? '#up' : '#down');
    for (const r of depthRows(side, name, levels, input.value)) {
      const b = make('button', 'lvrow' + (r.cur ? ' on' : ''));
      b.type = 'button';
      b.setAttribute('role', 'menuitemradio');
      b.setAttribute('aria-checked', String(r.cur));
      b.setAttribute('aria-label', `${r.full}, ${r.adds}`);
      b.title = `${r.full}  ${r.adds}`;
      b.append(make('span', 's', r.sel), make('span', 'a', r.adds),
        strokeIcon('0 0 16 16', 'ck', ['M3.5 8.5l3 3 6-7']));
      b.addEventListener('click', () => pickDepth(side, r.n, r.cur));
      el.append(b);
    }
    const other = side === 'up' ? 'down' : 'up';
    const notes = [];
    if (!levels[other].length && !levels[`${other}_more`]) {
      notes.push(side === 'up' ? `Nothing downstream: ${name} has no children.` : `Nothing upstream: ${name} has no parents.`);
    }
    // The cap, only when it is what stopped the walk: a column graph can also
    // just go deeper than the menu lists.
    if (levels[side + '_cut']) notes.push('Cut at the canvas\'s cap');
    else if (levels[side + '_more']) notes.push('Goes on past 20 levels');
    if (notes.length) {
      const foot = make('div', 'lvfoot');
      foot.append(...notes.map((t) => make('div', '', t)));
      el.append(foot);
    }
  }
  if (had) {
    const rows = [...el.querySelectorAll('button')];
    (rows[was] || el.querySelector('button.on') || rows[0] || el).focus();
  }
  if (el.isConnected) placePopup(anchor, el);
}

/* A pick writes the box and fires one change, which redraws; the row already
   drawn only closes the menu. */
function pickDepth(side, n, current) {
  const anchor = depthMenu.anchor;
  closePopup();
  anchor.focus();
  if (current) return;
  const input = $(side === 'up' ? '#up' : '#down');
  input.value = String(n);
  input.dispatchEvent(new Event('change'));
}

function openDepthMenu(anchor, side) {
  if (anchor.disabled || anchor.getAttribute('aria-disabled') === 'true') return;
  if (closePopup(anchor)) return;
  const el = document.createElement('div');
  el.className = 'envmenu depthmenu';
  el.setAttribute('role', 'menu');
  el.tabIndex = -1;
  // The up menu opens from the button's left, the down one inward from its right.
  if (side === 'down') el.dataset.align = 'right';
  depthMenu = { side, el, anchor };
  fillDepthMenu();
  anchor.setAttribute('aria-expanded', 'true');
  openPopup(anchor, el, () => {
    anchor.setAttribute('aria-expanded', 'false');
    if (depthMenu && depthMenu.el === el) depthMenu = null;
  });
}

function paintMode() {
  noteLineage('');
  const selecting = S.graphMode === 'select';
  $$('#graph-mode .segbtn').forEach((b) => {
    b.classList.toggle('active', b.dataset.mode === S.graphMode);
    if (b.dataset.mode === 'column') {
      b.disabled = !S.colFocus;
      b.title = S.colFocus
        ? 'One column\'s lineage: the columns it is built from and the ones built from it.'
        : 'One column\'s lineage. Pick a column in Catalog > Columns first.';
    }
  });
  $('#select-bar').classList.toggle('hidden', !selecting);
  // Coming back to the selection draws it at the cap again, unasked (0087).
  if (!selecting) S.selectRaise = null;
  // A model or a column drawn, from a double-click on a box or a column in
  // the Catalog beside the canvas, is the dock's again.
  if (!selecting && panelOpen('select')) closePanel();
  // The depth has nothing to say about a selection: the + in the expression
  // carries it, and two places to set one would contradict. A menu of the
  // depth is for the focus it was opened on, so a new ask closes it.
  $('#up').disabled = $('#down').disabled = selecting;
  closeDepthMenu();
  paintDepth();
  paintStopAt();
  // A column canvas's offer, and the cap a click lifted, are for that canvas
  // alone, as a selection's is (0118).
  if (S.graphMode !== 'column') {
    S.colRaise = null;
    paintColCap(null);
  }
  const chip = $('#col-chip');
  chip.classList.toggle('hidden', !S.colFocus);
  if (S.colFocus) {
    chip.textContent = '';
    const b = document.createElement('b');
    b.textContent = S.colFocus.column;
    const x = document.createElement('button');
    x.type = 'button';
    x.className = 'x';
    x.textContent = '×';
    x.title = 'back to model lineage';
    x.setAttribute('aria-label', 'Leave column mode');
    x.addEventListener('click', () => { if (S.focus) focusNode(S.focus); });
    chip.title = `${nameOfId(S.colFocus.id, S.node)}.${S.colFocus.column}`;
    chip.append(b, x);
  }
}

/* Returns whether it moved the lineage, which is what tells a reload that
   the file it was waiting on has turned up. `keepDepth` draws the node it
   moves to at the depth the boxes hold, rather than the default. */
async function syncNode(path, { keepDepth = false } = {}) {
  noteLineage('');
  // A properties file declares many nodes, and the server answers for one of
  // them. When the lineage already shows another, most likely because it was
  // clicked in this file, coming back to the tab keeps it.
  let now = null;
  if (S.focus) {
    try {
      now = await nodeDetail({ id: S.focus });
      if (now.file === path || now.yml === path) return false;
    } catch { /* gone with the last manifest: sync as usual */ }
  }
  try {
    const detail = await nodeDetail({ file: path });
    if (detail.id === S.focus) return false;
    focusNode(detail.id, { keepDepth });
    return true;
  } catch {
    // Not a dbt node, or not one yet: the lineage stays as it is, and says
    // so. "Select a model" with a model open read as a bug, and so did the
    // last model left on screen with nothing to tell it from this file's.
    S.unsynced = path;
    if (S.graphMode !== 'model' || projectPath(S.active) !== path) return false;
    const f = S.open.get(S.active);
    const why = noNodeHint(path, S.fresh, {
      macros: !!(f && f.doc) && definesMacros(f.doc.getValue()),
      shown: S.focus && now ? now.name : '',
    });
    if (S.focus) noteLineage(why);
    else emptyHint(why || 'Select a model to see its lineage.');
    return false;
  }
}

/* A line over a canvas that is still drawn, saying what it is not: empty
   hides it. Every change of what the canvas shows clears it (paintMode). */
function noteLineage(text) {
  const el = $('#lineage-note');
  el.textContent = text;
  el.classList.toggle('hidden', !text);
  // With find open, its bar moves under the note, and the folder names too.
  Lineage.placeHeads();
}

/* The tab in front came up with no node, most often because it is newer than
   the last parse. A reload is when that can change, from the button or from
   the watcher once dbt rewrites the manifest, so the lineage follows it then
   rather than waiting for the tab to be clicked again. */
async function followActive() {
  const path = S.active && projectPath(S.active);
  if (!path || path !== S.unsynced || S.graphMode !== 'model') return false;
  return syncNode(path);
}

function relinkTools() {
  for (const el of [$('#up'), $('#down'), $('#folder-levels')]) {
    el.addEventListener('change', rerender);
  }
  $('#up-btn').addEventListener('click', (e) => openDepthMenu(e.currentTarget, 'up'));
  $('#down-btn').addEventListener('click', (e) => openDepthMenu(e.currentTarget, 'down'));
  $('#depth-copy').addEventListener('click', copyDepth);
  $('#with-tests').addEventListener('click', () => { paintTestsToggle(!testsOn()); rerender(); });
  $('#indirect-btn').addEventListener('click', () => {
    S.colIndirect = !S.colIndirect;
    S.colCut = cutsKept(S.colCut);
    closeStopAt();
    paintStopAt();
    rerender();
  });
  $('#by-folder').addEventListener('click', () => { $('#by-folder').setAttribute('aria-pressed', String(!foldersOn())); rerender(); });
  wireFolderLevels();
  $('#fit-btn').addEventListener('click', () => Lineage.fit());
  $('#export-btn').addEventListener('click', (e) => openExportMenu(e.currentTarget));
  $$('#graph-mode .segbtn').forEach((b) => b.addEventListener('click', () => {
    if (b.disabled) return;
    if (b.dataset.mode === 'select') { openSelection(); return; }
    emptyHint('Select a model to see its lineage.');
    if (b.dataset.mode === 'column' && S.colFocus) focusColumn(S.colFocus.id, S.colFocus.column);
    else if (S.focus) focusNode(S.focus);
    else blankLineage();
  }));

  const box = $('#select-input');
  box.addEventListener('input', () => {
    clearTimeout(selectTimer);
    selectTimer = setTimeout(runSelection, 500);
  });
  box.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') { clearTimeout(selectTimer); runSelection(); return; }
    if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
    e.preventDefault();
    S.selectHistAt = historyStep(S.selectHistory, S.selectHistAt, e.key === 'ArrowUp' ? 1 : -1);
    box.value = S.selectHistAt < 0 ? '' : S.selectHistory[S.selectHistAt];
  });
  $('#select-copy').addEventListener('click', () => {
    const sub = S.selectSub;
    if (!sub || !sub.names || !sub.names.length) return toast('nothing to copy', 'err');
    // The names sent stop past a few thousand: the toast says so.
    const n = sub.names.length;
    copyText(sub.names.join('\n'), n < sub.matched ? `the first ${n} of ${sub.matched} names` : `${n} names`);
  });
  $('#select-ls').addEventListener('click', () => {
    const sub = S.selectSub;
    const named = sub ? sub.selector : boxSelector(box.value);
    if (!named && !sub) return toast('run a selection first', 'err');
    const command = named ? selectorCommand(named) : lsCommand(sub.select, sub.exclude || '');
    if (!command) return toast('not typed: the selection holds a character the shell would act on', 'err');
    sendToTerminal(command, false, null, 'the selection');
  });
  $('#select-named').addEventListener('click', (e) => openSelectorMenu(e.currentTarget));
  $('#stop-at').addEventListener('click', (e) => openStopAt(e.currentTarget));
}

// ---------------------------------------------------------------- export --
/* What the canvas shows, as one file anyone can open with nothing installed:
   attached to a ticket and read in a browser, zoomed without blurring, printed
   to a one-page PDF, or pasted as an image (0026). Every word of it comes from
   the payload that was drawn, never from S or the boxes above the canvas: a
   rejected selector or a failed fetch leaves the last picture on screen while
   those already describe the next one.

   Pure from here to `exportLineage`, Save as HTML page, which is where the
   export harness stops reading. */

/* What the picture is of: the expression for a selection, the model for its
   neighbourhood, model.column for a column. A column box's `sub` starts with
   its owner's name, which is how the server builds it. */
function exportTitle(sub) {
  if (!sub || !sub.nodes || !sub.nodes.length) return '';
  if (sub.mode === 'select') return selectionText(sub);
  const f = sub.nodes[sub.focus];
  if (!f) return '';
  if (sub.mode !== 'column') return f.name;
  const owner = String(f.sub || '').split('  ·  ')[0];
  const column = sub.focus_column || f.name;
  return owner ? `${owner}.${column}` : column;
}

/* Short enough for a heading and a file name. A selection can run to dozens
   of terms and the command carries every one of them, so the heading keeps
   the first terms that fit and counts the rest. A first term too long to fit
   is cut itself rather than the count, which says more than its last letters
   would. An exclusion is never cut in half: it is named, or left to the
   command. */
function shortTitle(text, max) {
  const s = String(text || '').trim();
  if (s.length <= max) return s;
  const terms = s.split(/\s+/);
  const cut = terms.indexOf('--exclude');
  const inc = cut < 0 ? terms : terms.slice(0, cut);
  const rest = (k) => (k ? ` and ${k} more` : cut < 0 ? '' : ' --exclude …');
  let out = '';
  let n = 0;
  for (; n < inc.length; n++) {
    const next = out ? `${out} ${inc[n]}` : inc[n];
    if ((next + rest(inc.length - n - 1)).length > max) break;
    out = next;
  }
  if (out) return out + rest(inc.length - n);
  const tail = rest(inc.length - 1);
  return (inc[0] || s).slice(0, Math.max(1, max - tail.length - 1)) + '…' + tail;
}

/* The command that lists what the picture shows, for a reader who wants to
   check it against dbt itself (0024), in the words the dbt ls button types.
   When the set holds no test, tests are excluded outright: dbt ls would
   otherwise list the ones the tests checkbox kept off the canvas. A model's
   neighbourhood is written with dbt's own graph operators, from the depths
   actually drawn, and only for what dbt selects by a bare name. Column
   lineage has no dbt equivalent. */
function exportCommand(sub) {
  if (!sub || !sub.nodes || !sub.nodes.length) return '';
  // A named selector's own definition decides its tests, and dbt would ignore
  // an --exclude beside it anyway.
  if (sub.mode === 'select' && sub.selector) return selectorCommand(sub.selector);
  const tested = sub.mode === 'select'
    ? !!(sub.counts && sub.counts.test)
    : sub.nodes.some((n) => n.kind === 'test');
  const exclude = (ex) => (tested ? ex : [ex, 'resource_type:test'].filter(Boolean).join(' '));
  if (sub.mode === 'select') return lsCommand(sub.select || '', exclude(sub.exclude || ''));
  const f = sub.nodes[sub.focus];
  if (sub.mode !== 'model' || !f || !['model', 'seed', 'snapshot'].includes(f.kind)) return '';
  const depths = sub.nodes.map((n) => n.depth || 0);
  const up = Math.max(0, ...depths.map((d) => -d));
  const down = Math.max(0, ...depths);
  return lsCommand(`${up ? up + '+' : ''}${f.name}${down ? '+' + down : ''}`, exclude(''));
}

/* What matched but did not fit on the canvas, by name. A multiset difference,
   because a source and a model can share a name and each is a match. A box
   drawn as context matched nothing, so it accounts for no name. */
function undrawnNames(names, nodes) {
  const drawn = new Map();
  for (const n of nodes || []) if (!n.context) drawn.set(n.name, (drawn.get(n.name) || 0) + 1);
  const out = [];
  for (const name of names || []) {
    const left = drawn.get(name) || 0;
    if (left) drawn.set(name, left - 1);
    else out.push(name);
  }
  return out;
}

/* The manifest's state when the file was made, told to someone who was not
   there. The badge's own sentences speak to the person at the keyboard about
   files they can open, and carry an age, which is wrong by the time anyone
   reads this. */
function exportFreshness(f) {
  if (!f) return '';
  const n = (k) => f[k + '_n'] || 0;
  const files = (k) => `${k} file${k === 1 ? '' : 's'}`;
  const said = {
    fresh: 'The manifest then matched the project\'s files.',
    edited: `${files(n('edited'))} saved since the manifest was written had not been parsed, `
      + 'so the graph shows the project as it was before them.',
    stale: `${files(n('committed') + n('gone') + n('edited'))} had changed since the manifest was written, `
      + 'so some boxes may no longer match the code.',
  }[f.state] || '';
  const d = f.drift || {};
  const behind = d.base && d.behind
    ? `The branch was ${d.behind} commit${d.behind === 1 ? '' : 's'} behind ${d.base}.`
    : '';
  return [said, behind].filter(Boolean).join(' ');
}

/* The header's words, from the payload that was drawn and fields the caller
   fills in by name. S.meta itself never comes here: it also carries absolute
   paths, the manifest's and the column cache's, which have no business in a
   file that leaves the machine. */
function exportFacts(sub, ctx) {
  const kicker = { select: 'Selection', model: 'Lineage of a model', column: 'Column lineage' }[sub.mode] || 'Lineage';
  const depths = sub.nodes.map((n) => n.depth || 0);
  const up = Math.max(0, ...depths.map((d) => -d));
  const down = Math.max(0, ...depths);
  const counts = sub.mode === 'select'
    ? `${selectSummary(sub)}  ·  ${canvasStatus(sub, ctx.folders)}`
    : `${canvasStatus(sub, ctx.folders)}  ·  ${up} level${up === 1 ? '' : 's'} up, ${down} down`;
  const where = [
    ctx.project,
    ctx.dbtVersion && `dbt ${ctx.dbtVersion}`,
    ctx.manifestAt && `manifest written ${ctx.manifestAt}`,
    ctx.branch && `branch ${ctx.branch}${ctx.sha ? ` at ${ctx.sha}` : ''}`,
    sub.mode === 'column' && ctx.cllSource && `column lineage from ${ctx.cllSource}`,
  ].filter(Boolean).join('  ·  ');
  const when = [
    `Exported ${ctx.exportedAt}${ctx.version ? ` with dbt-edith ${ctx.version}` : ''}.`,
    exportFreshness(ctx.fresh),
  ].filter(Boolean).join(' ');
  return {
    kicker,
    lines: [sub.mode === 'select' && sub.description, counts, where, when].filter(Boolean),
    warnings: sub.mode === 'select' ? selectWarnings(selectNotes(sub).concat(sub.warnings || [])) : [],
    command: exportCommand(sub),
    undrawn: sub.mode === 'select' && sub.truncated ? undrawnNames(sub.names, sub.nodes) : [],
  };
}

/* An absolute moment with its offset: a reader elsewhere cannot tell 09/10
   from 10/09, and an age is wrong by the time anyone reads it. The offset is
   an argument so the answer does not depend on the machine running the tests. */
function exportStamp(secs, offsetMin) {
  const d = new Date((secs + offsetMin * 60) * 1000);
  const p = (x) => String(x).padStart(2, '0');
  const off = Math.abs(offsetMin);
  return `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1)}-${p(d.getUTCDate())} `
    + `${p(d.getUTCHours())}:${p(d.getUTCMinutes())} `
    + `UTC${offsetMin < 0 ? '-' : '+'}${p(Math.floor(off / 60))}:${p(off % 60)}`;
}

/* The day a file is named after, on the clock of whoever exported it. */
function localDay(d) {
  const p = (x) => String(x).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

/* A name every system accepts. Anything outside a short safe set becomes a
   dash, which covers all Windows forbids, and the cut comes before the final
   trim so a name never ends in a dash or a dot. */
function exportFileName(title, day, ext = '.html') {
  const slug = String(title || '')
    .replace(/[^A-Za-z0-9._+-]+/g, '-')
    .replace(/-{2,}/g, '-')
    .slice(0, 60)
    .replace(/^[-.]+|[-.]+$/g, '');
  return `lineage-${slug ? slug + '-' : ''}${day}${ext}`;
}

/* The name of a file the canvas leaves as, on the exporter's local `day`, with
   `ext` ('' for the name the menu shows before it is saved). The one name for
   all three outputs. */
function exportName(sub, day, ext = '.html') {
  return exportFileName(shortTitle(exportTitle(sub), 60), day, ext);
}

/* What the head of the Export menu says the canvas holds, folded tests
   included (0035): its nodes and edges, or the columns alone on a column
   canvas, whose model boxes are not columns. Tests are counted apart, as the
   line under the canvas counts them (0160). It is not always the line under
   the canvas, which also counts what a selection keeps for context or a cap
   leaves out. */
function exportCount(sub, folded = 0) {
  if (!sub || !sub.nodes || !sub.nodes.length) return 'nothing drawn';
  const n = (k, w) => `${k} ${w}${k === 1 ? '' : 's'}`;
  if (sub.mode === 'column') {
    return n(sub.nodes.length - sub.nodes.filter((b) => b.id && !String(b.id).includes('::')).length, 'column');
  }
  const t = testTally(sub);
  return [n(t.nodes, 'node'), t.edges && n(t.edges, 'edge'), t.tests && n(t.tests, 'test'), t.tests && folded && `${folded} folded`]
    .filter(Boolean).join(' · ');
}

/* The menu's three rows: the key a walk finds them by, the board's words, and
   the strokes of their glyph. Save as image is saved once the picture is drawn
   (0153); the other two keep the contents 0026 gave them. */
const EXPORT_ROWS = [
  { key: 'export-copy', label: 'Copy as image', fmt: 'PNG', say: 'On the clipboard, to paste into a ticket or a chat',
    glyph: ['M2 3.5H14V12.5H2Z', 'M2 11L5.75 7.25L9 10.5L10.75 8.75L14 12', 'M9.65 6a1.1 1.1 0 1 0 2.2 0a1.1 1.1 0 1 0-2.2 0'] },
  { key: 'export-png', label: 'Save as image', fmt: '.png', say: 'The same picture, as a file',
    glyph: ['M2 12.5V3.5H14V8.5', 'M2 11L5.75 7.25L8.75 10.25', 'M9.65 6a1.1 1.1 0 1 0 2.2 0a1.1 1.1 0 1 0-2.2 0', 'M12 9.75v4.5M10 12.5l2 2 2-2'] },
  { key: 'export-html', label: 'Save as HTML page', fmt: '.html', say: 'Opens offline, zooms without blurring, prints on one page',
    glyph: ['M3.75 1.75h5.5l3 3v9.5h-8.5z', 'M9.25 1.75v3h3', 'M6.75 8L5.25 9.75l1.5 1.75M9.25 8l1.5 1.75-1.5 1.75'] },
];

function escapeHtml(s) {
  const to = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  return String(s ?? '').replace(/[&<>"']/g, (c) => to[c]);
}

/* The variables a file opened elsewhere needs, which has no app.css: the ones
   the copied canvas rules and the page around the picture name, and the ones
   lineage.js's style strings name (the node kinds, the tests, the column
   roles, the label fills). Read from a probe that carries the theme on
   screen, Night under Halloween, whose art never leaves the page (0106,
   0150): the file is drawn in Light when Light is on, and in the usual
   colours with the Halloween theme on. */
function exportCanvasVars() {
  const names = [
    '--bg', '--bg-2', '--bg-3', '--line', '--fg', '--fg-dim', '--accent', '--warn', '--mono', '--ui',
    '--edge', '--edge-test', '--focus-bg', '--line-strong', '--accent-rgb',
    '--band', '--band-line', '--band-l1', '--band-l1-line', '--band-l2', '--band-l2-line', '--band-l3', '--band-l3-line',
    '--fg-2', '--edge-hot', 'color-scheme',
    '--k-view', '--k-table', '--k-incr', '--k-ephemeral', '--k-mview', '--k-seed', '--k-source', '--k-snapshot',
    '--k-exposure', '--k-other', '--k-custom',
    '--t-model', '--t-singular', '--t-column',
    '--r-passthrough', '--r-rename', '--r-cast', '--r-aggregate', '--r-window', '--r-transform', '--r-inferred',
    '--r-raw', '--r-generated', '--r-filter', '--r-join-key', '--r-dedup-key', '--r-indirect',
    '--r-passthrough-text', '--r-rename-text', '--r-cast-text', '--r-aggregate-text', '--r-window-text',
    '--r-transform-text', '--r-inferred-text', '--r-raw-text', '--r-generated-text',
  ];
  const probe = document.createElement('i');
  probe.hidden = true;
  probe.dataset.theme = exportTheme(document.documentElement.dataset.theme);
  document.body.append(probe);
  try {
    const style = getComputedStyle(probe);
    const out = {};
    names.forEach((name) => { out[name] = style.getPropertyValue(name).trim(); });
    return out;
  } finally { probe.remove(); }
}

/* The canvas rules, copied from app.css line for line, with the variables they
   and the page use, whose values are the current theme's (`vars`, read by
   exportCanvasVars at export time), so a theme reaches the file. The rules stay
   copied rather than read from the live stylesheet, which would hand over
   whatever the exporting browser made of them, rules it dropped included, to be
   opened in another browser. The export harness holds every copied line to
   app.css, so an edit there fails the check until it is made here too. */
function exportCanvasCss(vars = {}) {
  return [
    ':root { ' + Object.keys(vars).filter((k) => vars[k]).map((k) => `${k}: ${vars[k]}; `).join('') + '}',
    '#graph text { font-family: var(--ui); user-select: none; }',
    '.edge { fill: none; stroke: var(--edge-col, var(--edge)); stroke-width: 1.5; }',
    '.edge.test { stroke: var(--edge-test); stroke-dasharray: 1 3; stroke-linecap: round; }',
    '.edge.test.stem { stroke: var(--line-strong); stroke-width: 1; stroke-dasharray: 3 3; stroke-linecap: butt; }',
    '.edge.indirect { stroke-width: .9; stroke-dasharray: 3 2; }',
    '.edge.hi { stroke: var(--edge-col, var(--edge-hot)); stroke-width: 2; }',
    '.colcanvas .edge.hi { stroke-width: 3; }',
    '.edge.test.stem.hi { stroke: var(--edge-hot); stroke-width: 1.5; }',
    '.edge.back { stroke-dasharray: 5 4; }',
    '.edge.test.back { stroke-dasharray: 5 3 1 3; }',
    '.edge.indirect.back { stroke-dasharray: 9 2 3 2 3 2; }',
    '.edgelabel { font-size: 8px; letter-spacing: .4px; fill: var(--edge-col, var(--edge)); pointer-events: none; paint-order: stroke; stroke: var(--bg); stroke-width: 3px; stroke-linejoin: round; }',
    '.nd rect.box { fill: var(--bg-3); stroke: var(--line); stroke-width: 1; rx: 7; }',
    '.nd:hover rect.box { stroke: var(--line-strong); }',
    '.nd.focus rect.box, .nd.sel rect.box { stroke: rgba(var(--accent-rgb), .9); stroke-width: 1; fill: var(--focus-bg); }',
    '.nd.off rect.box { stroke-dasharray: 3 3; }',
    '.nd.off .t1, .nd.off .t2 { opacity: .55; }',
    '.nd.ctx { opacity: .45; }',
    '.nd.ctx:hover { opacity: .85; }',
    '.nd.rider rect.box { fill: var(--bg-2); rx: 5; }',
    '.nd.rider .t1 { font-size: 11.5px; font-weight: 400; }',
    '.nd .rc { fill: var(--fg-dim); font-size: 11px; }',
    '#graph .nd .rc { font-family: var(--mono); }',
    '.nd.fold { cursor: pointer; }',
    '.nd.fold rect.box { fill: transparent; stroke-dasharray: 3 3; }',
    '.nd.fold .t1 { fill: var(--fg-dim); }',
    '.nd.fold:hover .t1 { fill: var(--fg); }',
    '.nd.rider.singular rect.box { stroke-dasharray: 4 2; }',
    '.nd.group { cursor: pointer; }',
    '.nd .warnmark { fill: var(--warn); }',
    '.nd .warncount { font-size: 9px; }',
    '.nd .kindbar { stroke: none; rx: 2; }',
    '.nd .kindbar.seg { rx: 1; }',
    '.nd .t1 { fill: var(--fg); font-size: 13px; font-weight: 500; }',
    '.nd .t2 { fill: var(--fg-dim); font-size: 11px; }',
    '#graph .nd .t2 { font-family: var(--mono); }',
    '.colcanvas .nd .t1 { font-size: 12.5px; font-weight: 400; }',
    '#graph .colcanvas .nd .t1 { font-family: var(--mono); }',
    '.nd .t2 .struck { opacity: .6; text-decoration: line-through; }',
    '.nd .more-badge .pill { fill: var(--bg-2); stroke: var(--line); }',
    '.nd .more-badge:hover .pill { stroke: var(--line-strong); }',
    '.nd .more { fill: var(--fg-dim); font-size: 10px; }',
    '#graph .nd .more { font-family: var(--mono); }',
    '.nd .more-badge:hover .more { fill: var(--fg); }',
    '.band { fill: var(--band); stroke: var(--band-line); stroke-width: 1; }',
    '.band.l1 { fill: var(--band-l1); stroke: var(--band-l1-line); }',
    '.band.l2 { fill: var(--band-l2); stroke: var(--band-l2-line); }',
    '.band.l3 { fill: var(--band-l3); stroke: var(--band-l3-line); }',
    '.band-name { fill: var(--fg-dim); font-size: 13px; font-weight: 600; }',
    '.band-name.l1, .band-name.l2, .band-name.l3 { font-size: 12px; font-weight: 500; }',
    '.rolelabel { font: 8.5px var(--mono); letter-spacing: .4px; }',
    '.rolebadge rect { stroke-width: 1; }',
    '#graph .roletaglabel { font: 600 9.5px var(--mono); letter-spacing: .04em; }',
    '.roletag rect { fill: none; stroke-width: 1; }',
  ].join('\n');
}

/* The page around the picture, and its print. The page never scrolls, so the
   wheel over the graph always zooms. A print is one page whatever the graph:
   the body takes a fixed height that fits A4 and Letter alike, in millimetres
   because engines have measured `vh` against the screen when printing, and
   the graph gets what the header leaves. The zero page margin also keeps the
   browser from printing its own header and footer, which name where the file
   sat on the machine that printed it. */
function exportPageCss(orientation) {
  return `* { box-sizing: border-box; }
html { height: 100%; background: var(--bg); -webkit-print-color-adjust: exact; print-color-adjust: exact; }
body { height: 100%; margin: 0; display: flex; flex-direction: column; color: var(--fg); font: 13px/1.45 var(--ui); }
header { flex: 0 0 auto; padding: 10px 16px; background: var(--bg-2); border-bottom: 1px solid var(--line); }
.kicker { font: 600 10.5px var(--ui); letter-spacing: .7px; text-transform: uppercase; color: var(--fg-dim); }
h1 { margin: 1px 0 6px; font-size: 17px; font-weight: 600; overflow-wrap: anywhere; }
.cmd { display: flex; align-items: flex-start; gap: 8px; margin-bottom: 6px; }
.cmd code { flex: 1 1 auto; padding: 3px 8px; font: 12px/1.5 var(--mono); background: var(--bg-3); border: 1px solid var(--line); border-radius: 4px; white-space: pre-wrap; overflow-wrap: anywhere; }
.facts { margin: 0; padding: 0; list-style: none; font-size: 11.5px; color: var(--fg-dim); }
.facts .warn { color: var(--warn); }
.legend { display: flex; flex-wrap: wrap; gap: 4px 12px; margin-top: 6px; font: 10.5px var(--mono); color: var(--fg-dim); }
.legend i { display: inline-block; width: 8px; height: 8px; margin-right: 4px; border-radius: 2px; vertical-align: -1px; }
.legend i.dash { width: 14px; height: 2px; border-radius: 0; vertical-align: 3px; }
.legend i.role { width: 14px; height: 2px; border-radius: 1px; vertical-align: 3px; }
.legend i.kind { width: 3px; height: 10px; border-radius: 2px; vertical-align: -1px; }
.tools { display: none; align-items: center; gap: 10px; margin-top: 8px; font-size: 11px; color: var(--fg-dim); }
button { display: none; padding: 2px 8px; font: 11px var(--ui); color: var(--fg); background: var(--bg-3); border: 1px solid var(--line); border-radius: 4px; cursor: pointer; }
button:hover { border-color: var(--accent); }
.js .tools { display: flex; }
.js button { display: inline-block; }
main { position: relative; flex: 1 1 0; min-height: 0; }
#graph { display: block; width: 100%; height: 100%; }
.js #graph { cursor: grab; }
.js #graph.panning { cursor: grabbing; }
#nodes { position: absolute; top: 8px; right: 8px; max-width: min(440px, 60%); max-height: calc(100% - 16px); overflow: auto; font-size: 11.5px; background: var(--bg-2); border: 1px solid var(--line); border-radius: 6px; }
#nodes summary { padding: 4px 10px; color: var(--fg-dim); cursor: pointer; }
#nodes ol { margin: 0; padding: 0 0 6px; list-style: none; }
#nodes li { padding: 3px 10px; }
.js #nodes li[data-id] { cursor: pointer; }
.js #nodes li[data-id]:hover { background: var(--bg-3); }
#nodes .nm { overflow-wrap: anywhere; }
#nodes .sub, #nodes .file, #nodes .undrawn { font: 10.5px var(--mono); color: var(--fg-dim); overflow-wrap: anywhere; }
#nodes .more { padding: 6px 10px 2px; font-size: 10.5px; letter-spacing: .6px; text-transform: uppercase; color: var(--fg-dim); }
@page { size: ${orientation}; margin: 0; }
@media print {
  html, body { height: auto; }
  body { height: ${orientation === 'portrait' ? 270 : 200}mm; padding: 6mm; overflow: hidden; }
  .tools, button, #nodes { display: none !important; }
}`;
}

/* One zoom step around a point, as a new viewBox. The point stays where it
   was on screen: with preserveAspectRatio meet, a box scaled evenly keeps its
   letterbox. Clamped through the factor, never width and height apart, so the
   ratio survives the clamp. Zooming in stops at whichever of two limits lets
   the view come closer: a width of `minW`, which binds on a wide frame, and
   the on-screen scale `s` (px per user unit) at `maxS`, which a tall frame
   needs because its height sets the scale and a floor on the width alone
   stops far short of readable. A view already past both may still zoom out, it is never forced
   out. */
function zoomViewBox(vb, ux, uy, f, s, maxS, minW, maxW) {
  const [x, y, w, h] = vb;
  const k = Math.min(Math.max(f, w / maxW), Math.max(1, maxS / s, w / minW));
  return [ux - (ux - x) / k, uy - (uy - y) / k, w / k, h / k];
}

/* Runs inside the exported file and never here: the page is given this
   function's own source text, so it may name nothing else from this file.
   All it needs is in the page, and zoomViewBox arrives as its argument.

   Pan and zoom rewrite the viewBox, never a transform, so the page with
   scripts off still shows the whole graph fitted, and printing has one
   attribute to put back. */
function exportViewer(zoomViewBox) {
  const svg = document.getElementById('graph');
  const layer = svg && svg.querySelector('g');
  if (!layer) return;
  document.documentElement.classList.add('js');
  const home = svg.getAttribute('viewBox').split(/[\s,]+/).map(Number);
  let view = home.slice();
  const show = (v) => { view = v; svg.setAttribute('viewBox', v.join(' ')); };

  svg.addEventListener('wheel', (e) => {
    e.preventDefault();
    // Some mice report lines in Firefox, not pixels, and a notch would then
    // barely move the zoom.
    const dy = e.deltaY * (e.deltaMode === 1 ? 16 : e.deltaMode === 2 ? 400 : 1);
    // The inner group's matrix is the viewBox mapping itself. Engines have not
    // always agreed on whether the outer svg's includes it.
    const m = layer.getScreenCTM();
    const p = new DOMPoint(e.clientX, e.clientY).matrixTransform(m.inverse());
    // 3 px per unit is the canvas's own closest zoom (the wheel in lineage.js).
    show(zoomViewBox(view, p.x, p.y, Math.exp(-dy * 0.0015), m.a, 3, 120, home[2] * 4));
  }, { passive: false });

  let picked = null;
  const pick = (id) => {
    picked = id;
    svg.querySelectorAll('.nd').forEach((g) => g.classList.toggle('sel', g.dataset.id === id));
    svg.querySelectorAll('.edge').forEach((p) => {
      const hit = !!id && (p.dataset.a === id || p.dataset.b === id);
      p.classList.toggle('hi', hit);
      // On top, as on the canvas: edges sharing a lane lie on one line.
      if (hit) p.parentNode.appendChild(p);
    });
  };

  // Listening on the window, with no pointer capture: a captured pointer
  // sends its click to the svg, and the box under it would never hear of it.
  let drag = null;
  svg.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    const box = e.target.closest('.nd');
    drag = {
      x: e.clientX, y: e.clientY, from: view.slice(), k: layer.getScreenCTM().a,
      moved: false, id: box ? box.dataset.id : null,
    };
  });
  window.addEventListener('pointermove', (e) => {
    if (!drag) return;
    const dx = e.clientX - drag.x, dy = e.clientY - drag.y;
    // The canvas's own slop (`pastSlop` in lineage.js), written out: this
    // function may name nothing outside itself.
    if (!drag.moved && Math.abs(dx) <= 4 && Math.abs(dy) <= 4) return;
    drag.moved = true;
    svg.classList.add('panning');
    show([drag.from[0] - dx / drag.k, drag.from[1] - dy / drag.k, drag.from[2], drag.from[3]]);
  });
  const drop = () => { drag = null; svg.classList.remove('panning'); };
  window.addEventListener('pointerup', () => {
    if (drag && !drag.moved) pick(drag.id && drag.id !== picked ? drag.id : null);
    drop();
  });
  window.addEventListener('pointercancel', drop);
  svg.addEventListener('dblclick', (e) => { if (!e.target.closest('.nd')) show(home.slice()); });

  const fit = document.getElementById('fit');
  if (fit) fit.addEventListener('click', () => show(home.slice()));
  document.addEventListener('keydown', (e) => {
    if (e.key === '0') show(home.slice());
    if (e.key === 'Escape') pick(null);
  });

  // A row of the list selects its box and brings it to the middle, at the
  // zoom already chosen.
  document.querySelectorAll('#nodes li[data-id]').forEach((li) => li.addEventListener('click', () => {
    const g = [...svg.querySelectorAll('.nd')].find((x) => x.dataset.id === li.dataset.id);
    if (!g) return;
    pick(li.dataset.id);
    const t = g.transform.baseVal.consolidate();
    const box = g.querySelector('rect.box');
    const cx = (t ? t.matrix.e : 0) + box.width.baseVal.value / 2;
    const cy = (t ? t.matrix.f : 0) + box.height.baseVal.value / 2;
    show([cx - view[2] / 2, cy - view[3] / 2, view[2], view[3]]);
  }));

  // Copied where the clipboard is allowed; elsewhere selected, ready for the
  // keyboard.
  const copy = document.getElementById('copy');
  const code = document.querySelector('.cmd code');
  if (copy && code) copy.addEventListener('click', () => {
    const choose = () => {
      const range = document.createRange();
      range.selectNodeContents(code);
      getSelection().removeAllRanges();
      getSelection().addRange(range);
      copy.textContent = 'Selected';
    };
    if (!navigator.clipboard) return choose();
    navigator.clipboard.writeText(code.textContent).then(() => { copy.textContent = 'Copied'; }, choose);
  });

  let kept = null;
  window.addEventListener('beforeprint', () => { kept = view; show(home.slice()); });
  window.addEventListener('afterprint', () => { if (kept) show(kept); kept = null; });
}

/* The whole file. Every value from the project goes through escapeHtml; the
   SVG is the one thing inserted as it is, and XMLSerializer escaped it on the
   way out. The script is the same text whatever is drawn, so nothing from a
   project can end up running, and the policy forbids every fetch, which keeps
   the file working offline even after a later change reaches for a font. */
function exportDocument(o) {
  const e = escapeHtml;
  const f = o.facts;
  const legend = o.legend.map(([label, colour]) => {
    const swatch = Lineage.legendSwatch(label, colour);
    return `<span><i${swatch.cls ? ` class="${e(swatch.cls)}"` : ''} style="${e(swatch.style)}"></i>${e(label)}</span>`;
  }).join('');
  const facts = f.warnings.map((w) => `<li class="warn">${e(w)}</li>`)
    .concat(f.lines.map((l) => `<li>${e(l)}</li>`)).join('');
  // The struck strategy keeps its strike in the list, as it does on the picture.
  const sub = (n) => (n.parts
    ? Lineage.subJoin({ lead: e(n.parts.lead), struck: e(n.parts.struck), rest: e(n.parts.rest) }, (s) => `<s>${s}</s>`)
    : e(n.sub));
  const rows = o.nodes.map((n) => `<li data-id="${e(n.id)}"><div class="nm">${e(n.name)}</div>`
    + `<div class="sub">${sub(n)}</div><div class="file">${e(n.file)}</div></li>`).join('');
  const undrawn = f.undrawn.length
    ? `<div class="more">Matched, not drawn (${f.undrawn.length})</div>`
      + `<ol class="undrawn">${f.undrawn.map((n) => `<li>${e(n)}</li>`).join('')}</ol>`
    : '';
  const command = f.command
    ? `<div class="cmd"><code>${e(f.command)}</code><button id="copy" type="button">Copy</button></div>`
    : '';
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'">
<title>${e(o.heading)} · lineage</title>
<style>
${exportCanvasCss(exportCanvasVars())}
${exportPageCss(o.frame.h > o.frame.w ? 'portrait' : 'landscape')}
</style>
</head>
<body>
<header>
<div class="kicker">${e(f.kicker)}</div>
<h1>${e(o.heading)}</h1>
${command}
<ul class="facts">${facts}</ul>
<div class="legend">${legend}</div>
<div class="tools"><button id="fit" type="button">Fit</button><span>Wheel to zoom, drag to pan, click a box for its edges, 0 to fit. Ctrl+P saves a PDF.</span></div>
</header>
<main>
${o.svg}
<details id="nodes"><summary>${e(o.noun)} (${o.nodes.length})</summary><ol>${rows}</ol>${undrawn}</details>
</main>
<script>(${exportViewer})(${zoomViewBox});</script>
</body>
</html>
`;
}

/* Twice the size for a sharp paste, less for a graph so large that a canvas
   would refuse it or eat the memory of a small machine. */
function pngScale(w, h) {
  return Math.min(2, Math.sqrt(16e6 / (w * h)), 16384 / w, 16384 / h);
}

/* Save as HTML page, a row of the Export menu. Synchronous from the click to
   the download: a browser lets a page save an .html file only while the user's
   gesture lasts, and an await would spend it. */
function exportLineage(day = localDay(new Date())) {
  const shot = Lineage.snapshot();
  if (!shot) return toast('nothing drawn to export', 'err');
  const sub = shot.data;
  const meta = S.meta || {};
  const fresh = S.fresh || null;
  const stamp = (secs) => exportStamp(secs, -new Date(secs * 1000).getTimezoneOffset());
  const manifestAt = (fresh && fresh.manifest_at) || meta.manifest_mtime || 0;
  const facts = exportFacts(sub, {
    project: meta.project || '',
    dbtVersion: meta.dbt_version || '',
    manifestAt: manifestAt ? stamp(manifestAt) : '',
    branch: (S.git && S.git.repo && S.git.branch) || '',
    sha: (fresh && fresh.head && fresh.head.sha) || '',
    cllSource: meta.cll_source || '',
    fresh,
    version: S.version,
    exportedAt: stamp(Math.floor(Date.now() / 1000)),
    folders: shot.folders,
  });
  const heading = shortTitle(exportTitle(sub), 60);
  const nodes = sub.nodes
    .map((n) => ({ id: n.id, name: n.name, sub: Lineage.subtitle(n), parts: Lineage.subtitleParts(n), file: n.file }))
    .sort((a, b) => a.name.localeCompare(b.name));
  const html = exportDocument({
    heading, facts, nodes, legend: legendEntries(sub), svg: shot.svg, frame: shot.frame,
    noun: sub.mode !== 'column' ? 'Nodes' : sub.nodes.some((n) => Lineage.isModelBox(n)) ? 'Columns and models' : 'Columns',
  });
  const name = exportFileName(heading, day);
  saveBlob(new Blob([html], { type: 'text/html;charset=utf-8' }), name);
  toast('Saved ' + name, 'ok');
}

function saveBlob(blob, name) {
  const url = URL.createObjectURL(blob);
  const a = Object.assign(document.createElement('a'), { href: url, download: name });
  document.body.appendChild(a);
  a.click();
  a.remove();
  // Not at once: a download the browser has not started yet still needs it.
  setTimeout(() => URL.revokeObjectURL(url), 60000);
}

/* Rasterised from the standalone SVG, onto a canvas filled with the page's
   background first: an image has no page behind it. Loaded from a data: URL,
   because this page's policy takes images from data: and nowhere else (0015),
   so a blob: URL fails to load without saying why. */
function renderPng(shot, scale) {
  const bytes = new TextEncoder().encode(shot.svg);
  let bin = '';
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return new Promise((resolve, reject) => {
    const img = new Image();
    // Caught here, or a canvas that throws would leave the promise, and the
    // clipboard waiting on it, unsettled for good.
    img.onload = () => {
      try {
        const canvas = document.createElement('canvas');
        canvas.width = Math.round(shot.frame.w * scale);
        canvas.height = Math.round(shot.frame.h * scale);
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = exportCanvasVars()['--bg'];
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        canvas.toBlob((b) => (b ? resolve(b) : reject(new Error('the browser could not encode it'))), 'image/png');
      } catch (e) { reject(e); }
    };
    img.onerror = () => reject(new Error('the browser could not draw it'));
    img.src = 'data:image/svg+xml;base64,' + btoa(bin);
  });
}

/* The canvas as a PNG, started: the picture's promise and the name of its
   file, or null when nothing is drawn. The snapshots are taken at once, inside
   the click that asked. */
function lineagePng(day) {
  const first = Lineage.snapshot({ tight: true });
  if (!first) return null;
  const scale = pngScale(first.frame.w, first.frame.h);
  const shot = Lineage.snapshot({ css: exportCanvasCss(exportCanvasVars()), scale, tight: true });
  return { png: renderPng(shot, scale), name: exportName(shot.data, day, '.png') };
}

/* Copy as image, a row of the Export menu: the same picture as a PNG on the
   clipboard, for a ticket where an attachment takes a click to see. The
   clipboard item is made inside the click, holding a promise for its content,
   which is what Safari needs to count it as the user's gesture. Whatever
   refuses it gets the file instead. */
function copyLineageImage(day = localDay(new Date())) {
  const made = lineagePng(day);
  if (!made) return toast('nothing drawn to copy', 'err');
  const { png, name } = made;
  const save = () => png.then((blob) => {
    saveBlob(blob, name);
    toast(`The clipboard took no image, saved ${name} instead`, 'ok');
  }).catch((e) => toast('image: ' + e.message, 'err'));
  if (!window.ClipboardItem || !navigator.clipboard || !navigator.clipboard.write) return save();
  navigator.clipboard.write([new ClipboardItem({ 'image/png': png })])
    .then(() => toast('Image copied: paste it into the ticket', 'ok'), save);
}

/* Save as image, a row of the Export menu: the same PNG, as a file. Saved once
   the picture is drawn, after the click, as the clipboard's fallback always
   was; saveBlob is the download both reuse. */
function saveLineageImage(day = localDay(new Date())) {
  const made = lineagePng(day);
  if (!made) return toast('nothing drawn to save', 'err');
  made.png.then((blob) => {
    saveBlob(blob, made.name);
    toast('Saved ' + made.name, 'ok');
  }).catch((e) => toast('image: ' + e.message, 'err'));
}

/* The export menu (0153), under its button and held inside the window from the
   right: what the canvas shows and how much of it, the three ways out with
   their use and format, and the name the files take. With nothing drawn the
   rows are there but cannot be picked, and there is no name. A row acts inside
   its click, since the HTML download and the clipboard want the gesture. */
function openExportMenu(anchor) {
  if (closePopup(anchor)) return;
  const sub = Lineage.shown();
  const day = localDay(new Date());
  const el = (tag, className, textContent = '') => Object.assign(document.createElement(tag), { className, textContent });
  const menu = el('div', 'envmenu exportmenu');
  menu.setAttribute('role', 'menu');
  menu.setAttribute('aria-label', 'Export');
  menu.dataset.align = 'right';
  const head = el('div', 'menuhead', 'What the canvas shows');
  head.append(el('span', 'n', exportCount(sub, Lineage.folded())));
  menu.append(head);
  const act = { 'export-copy': copyLineageImage, 'export-png': saveLineageImage, 'export-html': exportLineage };
  for (const r of EXPORT_ROWS) {
    const item = el('button', 'xm-item');
    item.type = 'button';
    item.setAttribute('role', 'menuitem');
    item.dataset.key = r.key;
    item.append(strokeIcon('0 0 16 16', '', r.glyph), el('span', 'ml', r.label), el('span', 'fmt', r.fmt), el('span', 'ms', r.say));
    if (!sub) item.setAttribute('aria-disabled', 'true');
    else item.addEventListener('click', () => { closePopup(); anchor.focus(); act[r.key](day); });
    menu.append(item);
  }
  if (sub) menu.append(document.createElement('hr'), el('div', 'xm-foot', exportName(sub, day, '')));
  anchor.setAttribute('aria-expanded', 'true');
  openPopup(anchor, menu, () => anchor.setAttribute('aria-expanded', 'false'));
}

// -------------------------------------------------------------- artifacts --
/* The two files dbt leaves per node under target/: compiled/ holds the model's
   SQL with the Jinja gone, run/ the statement dbt executed to materialise it.
   They get a tab each and are never shown in each other's place, because
   "what does this model say" and "what did dbt send to the warehouse" are
   different questions and only one of them explains a table that looks wrong.

   Nothing is compiled here: dbt runs where the user runs it (0002), so a
   missing file is reported with the command that would produce it. */
async function loadArtifact(kind, id) {
  const head = $('#' + kind + '-head');
  const body = $('#' + kind + '-body');
  head.textContent = '';
  if (!id) {
    S.artifactAsk[kind]++;                    // an answer on its way is no longer wanted
    S.artifactInfo[kind] = null;
    body.textContent = '';
    body.append(Object.assign(document.createElement('div'), {
      className: 'compiled-empty', textContent: 'Select a model first.' }));
    return false;
  }
  const node = S.node && S.node.id === id ? S.node : null;
  const name = nameOfId(id, node);

  // Resolves to whether this load painted found SQL for `id` (0145).
  const ask = ++S.artifactAsk[kind];
  let info;
  try { info = await api.get('/api/compiled?kind=' + kind + '&id=' + encodeURIComponent(id)); }
  catch (e) { if (ask === S.artifactAsk[kind]) toast(kind + ': ' + e.message, 'err'); return false; }
  if (ask !== S.artifactAsk[kind]) return false;          // a later load has the pane

  // A test node even when the catalog is showing something else: a dbt
  // unique_id says what it is, and the id is all this has when they disagree.
  S.artifactInfo[kind] = { info, name, isTest: node ? node.kind === 'test' : id.startsWith('test.') };
  return paintArtifact(kind);
}

/* The Compiled or Run pane from the last answer, as it stands: the file as dbt
   left it, or, with an environment picked, the same SQL with its relations
   swapped for that file's (0139). The environments are offered on the pane
   itself whenever there are any (0147). Repainted from here when the
   environment changes, with no request. */
function paintArtifact(kind, keepScroll) {
  const held = S.artifactInfo[kind];
  if (!held) return false;
  const { info, name, isTest } = held;
  // Named in the terminal beside a command this pane types.
  const from = kind === 'run' ? 'the Run tab' : 'the Compiled tab';
  const head = $('#' + kind + '-head');
  const body = $('#' + kind + '-body');
  head.textContent = '';
  const said = artifactBar(info, name, isTest);

  if (!said.found) {
    if (S.artifactCm[kind]) S.artifactCm[kind].setValue('');
    body.textContent = '';
    const box = document.createElement('div');
    box.className = 'compiled-empty';
    box.append(Object.assign(document.createElement('p'), { textContent: said.head, style: 'margin:0 0 4px' }));
    const code = document.createElement('code');
    code.textContent = said.command;
    box.append(code, document.createElement('br'));
    const send = document.createElement('button');
    send.className = 'btn sm';
    send.textContent = 'Type it in the terminal';
    send.title = 'Puts the command in the integrated terminal without running it';
    send.addEventListener('click', () => sendToTerminal(said.command, false, null, from));
    box.append(send);
    const det = document.createElement('details');
    det.style.marginTop = '12px';
    det.append(Object.assign(document.createElement('summary'), {
      textContent: 'paths checked', style: 'cursor:pointer;font-size:11px' }));
    const ul = document.createElement('ul');
    said.candidates.forEach((c) => ul.append(Object.assign(document.createElement('li'), { textContent: c })));
    det.append(ul);
    box.append(det);
    body.append(box);
    return false;
  }

  const content = artifactContent(info);
  const env = activeEnv();
  const shown = envSql(content, info.relations || [], env, (S.meta && S.meta.sandbox) || '');
  const tone = env ? envTone(envDisplayName(env)) : 'manifest';
  // Also with none picked: the group is how a person who has not found the status
  // bar's pill learns the tab can switch (0147).
  const pick = envRowShown();

  // One line for when and where, the environment beside it, the button last (0164).
  const line = document.createElement('div');
  line.className = 'chead' + (info.stale ? ' stale' : '');
  const stat = document.createElement('span');
  stat.className = 'cstat';
  stat.dataset.tone = said.tone;
  stat.title = said.date;
  stat.append(Object.assign(document.createElement('span'), { className: 'dot' }), said.stat);
  line.append(stat);
  if (said.changed) {
    const why = Object.assign(document.createElement('span'), { className: 'cchanged', textContent: said.changed });
    why.dataset.tone = said.tone;
    line.append(why);
  }
  line.append(artifactPath(said), Object.assign(document.createElement('div'), { className: 'grow' }));
  if (pick) line.append(artifactEnvPick(kind));
  const redo = document.createElement('button');
  redo.className = 'btn sm ghost artifact-redo';
  redo.textContent = said.button;
  redo.title = 'Puts ' + said.command + ' in the integrated terminal without running it';
  redo.addEventListener('click', () => sendToTerminal(said.command, false, null, from));
  line.append(redo);
  head.append(line);
  if (pick) head.append(artifactEnvNote(shown, info.env_reads, env, tone));
  // What the row was last drawn from, so a reload of the list repaints only for
  // a change this row has not seen, and keeps the focus a click just restored.
  S.artifactRow = envRowKey();

  // Read while the editor is still attached: emptying the body detaches it, and
  // a detached editor reports no scroll. setValue then scrolls to the top, which
  // a change of environment on the SQL being read must not do.
  const scrolled = keepScroll && S.artifactCm[kind] ? S.artifactCm[kind].getScrollInfo() : null;
  body.textContent = '';
  if (!S.artifactCm[kind]) {
    S.artifactCm[kind] = CodeMirror(body, { lineNumbers: true, readOnly: true, mode: 'text/x-sql', lineWrapping: false });
  } else {
    body.appendChild(S.artifactCm[kind].getWrapperElement());
  }
  const cm = S.artifactCm[kind];
  // The environment's colour for the marks below, which read --env from here.
  cm.getWrapperElement().dataset.tone = tone;
  cm.setValue(shown.text);
  if (scrolled) cm.scrollTo(scrolled.left, scrolled.top);
  const doc = cm.getDoc();
  shown.swaps.forEach((w) => doc.markText(doc.posFromIndex(w.start), doc.posFromIndex(w.end), {
    className: 'cm-env-swap', title: swapTitle(w, envDisplayName(env)) }));
  shown.kept.forEach((k) => doc.markText(doc.posFromIndex(k.start), doc.posFromIndex(k.end), {
    className: 'cm-env-kept', title: `${k.name} stays as dbt compiled it: ${k.reason}` }));
  setTimeout(() => cm.refresh(), 0);
  return true;
}

/* "Relations for" and the environments as a radio group: each name in its
   colour, a tag and never a dot, the picked one tinted, in the order the menu
   lists them, the manifest's own last (0147). A pick sets the one shared
   choice, so the status bar, the Catalog and the Builds marks follow. The
   picked button is the group's one tab stop, and the arrow keys move and pick
   as in any radio group; selectEnv gives the focus back after the repaint. */
function artifactEnvPick(kind) {
  const box = Object.assign(document.createElement('span'), { className: 'cenv' });
  // One label per tab: both tabs can be in the page at once, so the id carries the kind.
  const label = Object.assign(document.createElement('span'), { id: kind + '-env-label', textContent: 'Relations for' });
  box.append(label);
  const group = document.createElement('span');
  group.className = 'envseg';
  group.setAttribute('role', 'radiogroup');
  group.setAttribute('aria-labelledby', label.id);
  const choices = envChoices();
  // With no choice current the first radio is the group's tab stop, as in the settings' picker.
  const stop = choices.some((c) => c.current) ? -1 : 0;
  choices.forEach((c, i) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.setAttribute('role', 'radio');
    b.setAttribute('aria-checked', String(c.current));
    b.tabIndex = c.current || i === stop ? 0 : -1;
    b.dataset.tone = c.tone;
    b.title = c.file ? (c.title || c.sub) : `${c.sub}: ${c.title}`;
    b.textContent = c.label;
    b.addEventListener('click', () => { if (!c.current) selectEnv(c.file); });
    group.append(b);
  });
  group.addEventListener('keydown', (e) => {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    const at = Math.max(0, choices.findIndex((c) => c.current));
    const to = radioStep(at, choices.length, e.key);
    if (to < 0) return;
    e.preventDefault();
    if (to !== at) selectEnv(choices[to].file);
  });
  box.append(group);
  return box;
}

/* The one note under the line: what the swap changed and what it could not,
   led by the environment's tag, then the fold of where the SQL may differ beyond
   its relations, one line per finding, open when drawn (0164). A macro's finding
   opens the macro at that line, as Cmd+K opens one. */
function artifactEnvNote(shown, envReads, env, tone) {
  const box = document.createElement('div');
  box.className = 'cnote';
  box.dataset.tone = tone;
  const words = env
    ? artifactEnvWords(shown, envDisplayName(env), env, envReads)
    : artifactOwnWords((S.meta && S.meta.sandbox) || '');
  const text = document.createElement('div');
  if (words.tag) {
    text.append(envTag(words.tag, tone), ' ');
  }
  text.append(Object.assign(document.createElement('b'), { textContent: words.head }), words.rest);
  box.append(text);
  if (words.findings.length) {
    // Open to start with: the list is what the person came to this note for,
    // and the SQL under it is long.
    const fold = document.createElement('details');
    fold.className = 'cdiffer';
    fold.open = true;
    fold.append(Object.assign(document.createElement('summary'), { textContent: words.differ }));
    const ul = document.createElement('ul');
    words.findings.forEach((f) => {
      const li = document.createElement('li');
      if (f.macro) {
        const a = Object.assign(document.createElement('a'), { className: 'filelink', textContent: f.text, title: f.macro.file });
        a.addEventListener('click', (ev) => { ev.preventDefault(); openMacro(f.macro); });
        li.append(a);
      } else {
        li.textContent = f.text;
      }
      ul.append(li);
    });
    fold.append(ul);
    box.append(fold);
  }
  return box;
}

/* The file's own line in the bar. A path dbt wrote is long and nobody retypes
   it, so it is a link: clicking brings the file tree back into view and walks
   it down to the row, which is the fastest way to reach the file itself, the
   ones beside it, or the folder to delete before a clean build. A target
   outside the project has no tree row, so it is shown and not linked. */
function artifactPath(said) {
  if (!said.link) {
    return Object.assign(document.createElement('div'),
      { className: 'artifact-path outside', textContent: said.path, title: said.pathTitle });
  }
  const link = document.createElement('button');
  link.className = 'artifact-path link';
  link.textContent = said.path;
  link.title = said.pathTitle;
  link.addEventListener('click', () => {
    showSide('files');
    revealInTree(said.path);
  });
  return link;
}

function humanAge(secs) {
  if (secs < 60) return secs + 's';
  if (secs < 3600) return Math.round(secs / 60) + 'min';
  if (secs < 86400) return Math.floor(secs / 3600) + 'h' + String(Math.floor((secs % 3600) / 60)).padStart(2, '0');
  return Math.floor(secs / 86400) + 'd';
}

/* The manifest card's "written ..., 2 min ago": the age spelled the way the card's
   board does, with a space before its unit and a moment for the first seconds.
   humanAge keeps the compact form the pill and the other screens use. */
function cardAge(secs) {
  return secs < 10 ? 'a moment ago' : humanAge(secs).replace(/^(\d+)(s|min|d)$/, '$1 $2') + ' ago';
}

/* Every word the Compiled or Run tab puts on screen for one file. The line
   answers, of a single file, the question the manifest badge answers of the
   whole project: is what you are reading still what the source says?

   It leads with the age, as the manifest card says one ("Compiled 2 min ago"),
   and keeps the date for the hover. The date is what you can compare with:
   "3h ago" does not say whether this predates the nightly build, the pull you
   did at nine, or the edit still open in the editor, whereas "22/09/2026
   08:14" does. It is one hover away rather than in the line, which the
   environment's picker shares (0164).

   Amber means something it was built from has moved since: the model, its
   schema file, dbt_project.yml, a macro, or for a run, a compile that happened
   after it. Never the age on its own, however large. Pure, so every state is
   testable without a DOM. */
function artifactBar(info, name, isTest) {
  const kind = info && info.kind === 'run' ? 'run' : 'compiled';
  const w = {
    compiled: {
      verb: 'Compiled', dir: 'target/compiled/', what: 'compiled SQL',
      cmd: 'dbt compile', fresh: 'Compile again', stale: 'Recompile',
    },
    // A test's run file is written by `dbt test` and never by `dbt run`, which
    // would select nothing and leave the tab saying the same thing afterwards.
    // Compiling is the same command for both.
    run: isTest ? {
      verb: 'Last run', dir: 'target/run/', what: 'run SQL',
      cmd: 'dbt test', fresh: 'Test again', stale: 'Test again',
    } : {
      verb: 'Last run', dir: 'target/run/', what: 'run SQL',
      cmd: 'dbt run', fresh: 'Run again', stale: 'Run again',
    },
  }[kind];
  const command = w.cmd + ' --select ' + name;

  if (!info || !info.found) {
    return { kind, found: false, command,
      head: 'No ' + w.what + ' for ' + name + '. dbt has not written it into ' + w.dir + ' yet.',
      candidates: (info && info.candidates) || [] };
  }

  // "changed since" once, then the list. Said per entry it ran to five copies
  // of "changed after this was run" and stopped being readable at a glance,
  // which is the only thing this line is for.
  const why = [];
  if ((info.changed || []).length) why.push('changed since: ' + info.changed.join(', '));
  (info.reasons || []).forEach((r) => why.push(r));
  // The absolute path is the tooltip either way: it is what you paste into a
  // terminal, and the only thing left to show when no link can be offered.
  return {
    kind, found: true, command,
    tone: info.stale ? 'stale' : 'ok',
    stat: w.verb + ' ' + cardAge(info.age_secs || 0),
    date: w.verb + ' ' + new Date((info.compiled_at || 0) * 1000).toLocaleString(),
    // What moved follows the age and is amber with it; a stale file that names
    // nothing still says what it costs.
    changed: why.join(' \u00b7 ') + (info.stale ? (why.length ? ' ' : '') + '(may be out of date)' : ''),
    button: info.stale ? w.stale : w.fresh,
    link: !!info.rel,
    path: info.rel || info.path,
    pathTitle: info.rel
      ? info.path + ' \u00b7 click to show it in the file tree'
      : info.path + ' \u00b7 outside the project, so the file tree cannot reach it',
  };
}

/* What the Git panel and the freshness card say when the repository's own
   configuration names a program, so dbt-edith runs no git in it (0121). The key
   is named so that whoever wrote it can find it. */
function gitPausedNote(key) {
  // The server's word for a configuration it could not list at all.
  if (key.startsWith('unreadable: ')) {
    return 'git is paused here: this repository\'s own configuration could not be read (' + key.slice(12)
      + '), so dbt-edith runs no git in it. git in the terminal is unaffected.';
  }
  return 'git is paused here: this repository\'s own configuration names a program (' + key
    + '), so dbt-edith runs no git in it. git in the terminal is unaffected.';
}

/* What the pill before the manifest's reload shows, and what its card says.
   The mark's shape and colour answer one question only, the one that decides whether the
   lineage on screen can be trusted: does this manifest still match the files
   dbt would parse? Drift from the default branch is reported in its own
   segment rather than in the colour, because a feature branch behind main
   still has a manifest that is true for the code in front of you.

   The card carries the words. "manifest 3d" and "main +10" are a reminder of
   something you already understand, not an explanation, so every number the
   pill shows is spelled out in a sentence here. `typed` says the card's button
   only types dbt parse, Enter left to the user (0130, 0157). `branch` is a list
   of lines, each a list of parts: text, or `{ code }` for a sha or a ref, which
   the card sets as a code element's text. Pure, so every state is testable
   without a DOM. */
function freshnessBadge(f, typed) {
  const n = (k) => f[k + '_n'] || 0;
  const plural = (k, one, many) => n(k) + ' ' + (n(k) === 1 ? one : many);
  const tone = { fresh: 'ok', edited: 'warn', stale: 'bad', missing: 'none' }[f.state] || 'none';
  const label = f.state === 'missing' ? 'no manifest' : 'manifest';
  const age = f.state === 'missing' ? '' : humanAge(f.age_secs || 0);

  const head = {
    fresh: 'The lineage matches your files',
    edited: 'Your saved edits are not in it yet',
    stale: 'The files moved under this manifest',
    missing: 'No manifest.json yet',
  }[f.state] || 'Unknown state';

  const desc = {
    fresh: 'Nothing dbt parses has changed since this manifest was written, so the graph shows what your project says.',
    edited: 'You have saved changes dbt has not parsed. The graph still shows the project as it was before them.',
    stale: 'Files changed and were committed after this manifest was written. The graph may be showing models that no longer look like this.',
    missing: 'There is nothing to draw a lineage from until dbt writes one.',
  }[f.state] || '';

  const when = f.state === 'missing' ? ''
    : 'written ' + new Date((f.manifest_at || 0) * 1000).toLocaleString() + ', ' + cardAge(f.age_secs || 0);

  // Split so the card can lead with the file name and dim the folder: these
  // paths run to eighty characters and the last segment is the one that reads.
  const split = (p) => {
    const cut = p.lastIndexOf('/');
    return { full: p, name: cut < 0 ? p : p.slice(cut + 1), dir: cut < 0 ? '' : p.slice(0, cut).split('/').pop() };
  };
  const group = (key, heading, extra) => {
    if (!n(key)) return null;
    const shown = (f[key] || []).map(split);
    return Object.assign({ key, head: heading, paths: shown, more: n(key) - shown.length }, extra);
  };
  const groups = [
    group('committed', plural('committed', 'file', 'files') + ' changed since, already committed',
      { note: 'A checkout, a pull or a merge brought them in.' }),
    group('gone', plural('gone', 'file', 'files') + ' the manifest names no longer exist'),
    group('edited', plural('edited', 'file', 'files') + ' saved since, not committed'),
  ].filter(Boolean);

  const d = f.drift || {};
  const h = f.head || {};
  const branch = [];
  if (h.sha) branch.push({ parts: ['Sits at ', { code: h.sha }, h.subject ? ', \u201c' + h.subject + '\u201d.' : '.'] });
  let drift = '';
  if (d.base && d.behind) {
    drift = d.base.replace(/^origin\//, '') + ' +' + d.behind;
    branch.push({ parts: [{ code: d.base }, ' has ' + d.behind + ' commit' + (d.behind === 1 ? '' : 's')
      + ' this branch does not have: the lineage is your branch, not production.'] });
  } else if (d.base) {
    branch.push({ parts: ['This branch has everything ', { code: d.base }, ' has.'] });
  }
  if (d.base) {
    // A count of commits is only as current as the refs it was counted from,
    // so the card says when they were last refreshed rather than implying now.
    branch.push({ dim: true, age: !!d.fetched_at, parts: [d.fetched_at
      ? 'Remote refs last fetched ' + humanAge(Math.max(0, Math.floor(Date.now() / 1000) - d.fetched_at)) + ' ago.'
      : 'Remote refs have never been fetched in this clone, so that comparison means little.'] });
  }

  // A manifest that matches has nothing to parse; one that does not gets the
  // button. The server's advice replaces the plain sentence when it has one
  // (the branch is behind: pulling comes first), as a line and not a button.
  const action = f.state === 'fresh' ? null : {
    label: 'Run dbt parse',
    hint: typed ? 'typed in the terminal below; Enter is left to you' : 'in the terminal below',
  };
  const done = f.state === 'fresh' ? f.advice || 'Nothing to do: the graph is up to date.' : '';
  return { tone, label, age, drift, head, when, desc, groups, paused: f.git_paused ? gitPausedNote(f.git_paused) : '',
    branch, action, done, doneOk: f.state === 'fresh' && !f.advice };
}

/* What the canvas says when the file in front has no node, or '' when it was
   never going to have one: a properties file, a macro, anything but a .sql,
   .py or .csv. `shown` names the model still drawn, since one named like this
   file is easily read as its lineage. A manifest older than the files is the
   usual reason and the one the user can act on, so it is named; dbt parse is
   only offered as a maybe, a .sql file outside every resource folder having
   no node either. The lineage follows by itself once the manifest reloads
   (followActive), so the sentence promises no click. */
function noNodeHint(path, f, { macros = false, shown = '' } = {}) {
  const name = path.split('/').pop();
  if (macros || !/\.(sql|py|csv)$/i.test(name)) return '';
  const head = `No node in the manifest comes from ${name}`
    + (shown ? `, so the lineage still shows ${shown}.` : '.');
  if (!f || f.state === 'fresh') return head;
  if (f.state === 'missing') return head + ' There is no manifest.json yet: dbt parse writes one.';
  return head + ' The manifest is older than the project\'s files: if this one is new, run dbt parse and its lineage follows.';
}

/* What Edith's menu says while the terminal's shell reads the current folder,
   by the reason the server gives (0130): a relative entry of the PATH, which
   it names as written, an empty one the shell keeps, or cmd.exe, which looks
   there first whatever the PATH holds. A program in the project could then run
   in place of git, dbt or cargo. The second line, for the two PATH reasons, is
   the limit of the check, which reads the PATH dbt-edith hands the shell, not
   the one its startup files leave. Empty when the shell does not. Pure, so the
   harness reads it without a DOM. Each line is a list of parts: text, or
   `{ code }` for the entry, which the menu sets as a code element's text. */
function pathWarning(why, entry) {
  const run = 'could run there in place of git, dbt or cargo.';
  const says = {
    relative: ['The terminal\'s PATH holds a relative entry', ...(entry ? [' (', { code: entry }, ')'] : []),
      ', which the shell reads from the current folder, so a program in the project ' + run],
    empty: ['The terminal\'s PATH holds an empty entry, which the shell reads as the current folder, so a program at the project\'s root ' + run],
    cmd: ['cmd.exe looks in the current folder before the PATH, so a program committed at the project\'s root ' + run],
  }[why];
  if (!says) return [];
  const lines = [says];
  if (why !== 'cmd') lines.push(['This reads the PATH dbt-edith hands the shell; its startup files may still change it.']);
  return lines;
}

/* Whether the manifest card's button presses Enter for the user: not while the shell
   could run a program from the project's root in place of dbt, so the line is
   seen before it runs (0130, 0071, 0157). */
function freshnessRuns(why) {
  return !why;
}

/* Types a command into the integrated terminal. It stops at the prompt by
   default, because running it is the user's decision and dbt is theirs to
   launch (0002). `run` is for the manifest card's button alone (0157): its dbt parse reaches
   no warehouse, and a command that can is never run for the user (0071), nor
   that button's while the shell reads the current folder (0130).
   `typed`, when given, is called once the command is in the terminal in place
   of the toast, for the update, whose card says what to do next (0111).
   `from` names the page that typed it, as the person saw it: the chip beside
   the line says so, in place of the toast, once the shell has echoed it (0161).
   For `run`, Enter follows the echo, so that the chip is placed on the line
   before its output scrolls it. */
function sendToTerminal(cmd, run, typed, from) {
  // Always on a click, and the terminal is what it asks to see.
  closePanel();
  showDock('terminal');
  let tries = 0;
  const attempt = () => {
    const ws = S.ws;
    if (ws && ws.readyState === 1) {
      S.termPrompt = promptAfter(S.termPrompt, run ? cmd + '\r' : cmd);
      // Where the line starts, as a row of the whole buffer: a shell that wraps a long line by moving the cursor leaves its rows unmarked as wrapped.
      const first = S.term ? S.term.buffer.active.baseY + S.term.buffer.active.cursorY : 0;
      const before = S.term ? termLineToCursor(first) : '';
      const keys = S.termKeys;
      ws.send(JSON.stringify({ t: 'i', d: cmd }));
      S.term && S.term.focus();
      if (typed) typed();
      const settle = (seen) => {
        const live = S.ws === ws && ws.readyState === 1;
        // Enter only for a line still as it was sent: a key typed since, or a new shell, may have changed what it would run.
        const ran = enterAfterEcho(run, keys, S.termKeys, live);
        const drawn = live && seen && showTypedChip(typedChipText(from, ran));
        if (ran) ws.send(JSON.stringify({ t: 'i', d: '\r' }));
        if (!drawn && live && !typed) toast(ran ? 'running ' + cmd + ' in the terminal' : 'command ready in the terminal, press Enter to run it');
      };
      if (S.term) awaitEcho(first, before, cmd, settle);
      else settle(false);
    } else if (tries++ < 40) setTimeout(attempt, 100);
    else toast('terminal is not connected', 'err');
  };
  setTimeout(attempt, 60);
}

// ---------------------------------------------------------------- catalog --
/* What the Catalog says beside a versioned model's name: where it stands
   against the latest, which a ref() naming no version reaches (0104). Null
   for any other node. Pure, so the harness reads it without a DOM. */
function versionChip(n) {
  if (!n || !n.version) return null;
  const base = n.name.endsWith('.v' + n.version) ? n.name.slice(0, -(n.version.length + 2)) : n.name;
  const latest = n.latest_version ? 'v' + n.latest_version : '';
  const reaches = latest ? `ref('${base}') reaches ${latest}` : `the manifest names no latest version of ${base}`;
  if (n.version_state === 'latest') {
    return { text: 'latest', title: `The latest version of ${base}: ${reaches}.` };
  }
  const state = n.version_state === 'old' ? 'old' : n.version_state === 'prerelease' ? 'prerelease' : 'version';
  return {
    text: latest ? `${state} · latest ${latest}` : state,
    title: `${reaches}; ref('${base}', v=${n.version}) reaches this one.`,
  };
}

/* The words after the name: the materialization and the schema, as the hover
   card's second line says them (an incremental model's strategy in place of
   the materialization), and nothing for a node that has neither. A disabled
   node keeps its materialization: its chip beside says it is disabled. The test count stays out: Context counts them. */
function catalogMeta(n) {
  return [Lineage.subtitleParts({ ...n, disabled: false }).lead, n.schema].filter(Boolean).join(' \u00b7 ');
}

/* The Catalog's tabs: a test has no columns of its own, so it has Preview
   alone; `count` is the badge after a label, none for Preview. */
function catalogTabList(n) {
  if (n.kind === 'test') return [{ key: 'preview', label: 'Preview', count: 0 }];
  return [{ key: 'preview', label: 'Preview', count: 0 }, { key: 'columns', label: 'Columns', count: n.columns.length }];
}

function renderCatalog(n) {
  S.node = n;
  const host = $('#catalog');
  if (envMenu && host.contains(envMenu.anchor)) closeEnvMenu();
  if (popup && host.contains(popup.anchor)) closePopup();
  // A node that lands while the filter is being typed in redraws the table,
  // and the box with it: the next key has to reach the new one.
  const typing = document.activeElement && document.activeElement.id === 'col-filter';
  host.textContent = '';

  const head = document.createElement('div');
  head.className = 'cat-head';
  const title = document.createElement('div');
  title.className = 'cat-title';
  // The name is what gets pasted next, into a --select, a ref() or a query.
  const copy = copyGlyph(n.name, 'Copy the name');
  copy.classList.add('cat-copy');
  const name = Object.assign(document.createElement('span'), { className: 'nm', textContent: n.name, title: n.name });
  title.append(dot(n), name, copy);
  const meta = catalogMeta(n);
  if (meta) title.append(Object.assign(document.createElement('span'), { className: 'meta', textContent: meta }));
  if (n.disabled) {
    const off = document.createElement('span');
    off.className = 'offchip';
    off.textContent = 'disabled';
    off.title = 'enabled: false, so dbt leaves this model out of the graph';
    title.appendChild(off);
  }
  const version = versionChip(n);
  if (version) {
    const chip = Object.assign(document.createElement('span'), { className: 'verchip', textContent: version.text });
    chip.title = version.title;
    title.appendChild(chip);
  }
  if (n.file) {
    const open = document.createElement('button');
    open.className = 'btn ghost';
    open.textContent = 'Open file';
    open.addEventListener('click', () => {
      if (n.kind === 'test' && n.test_name) return openTest(n, { pin: true });
      pushJump();
      openFile(n.file, { focusLineage: false });
      revealInTree(n.file);
    });
    title.appendChild(open);
  }
  const crumb = document.createElement('div');
  crumb.className = 'crumb';
  crumb.innerHTML = '';
  crumb.append(document.createTextNode(n.package || ''), document.createTextNode('  /  '));
  const b = document.createElement('b');
  b.textContent = n.file || n.id;
  crumb.appendChild(b);

  const tabs = document.createElement('div');
  tabs.className = 'cat-tabs';
  tabs.setAttribute('role', 'tablist');
  // The tab picked stays picked, for the next model shown.
  const test = n.kind === 'test';
  const shown = test ? 'preview' : S.catTab;
  for (const { key, label, count } of catalogTabList(n)) {
    // The dock's tab look; `ctab` stays for what finds the Catalog's tabs by it.
    const t = document.createElement('button');
    t.type = 'button';
    t.className = 'tab ctab' + (shown === key ? ' active' : '');
    t.setAttribute('role', 'tab');
    t.setAttribute('aria-selected', String(shown === key));
    t.append(label);
    if (count) t.append(Object.assign(document.createElement('span'), { className: 'tabbadge', textContent: String(count) }));
    t.addEventListener('click', () => (test ? renderCatalog(n) : showCatalogTab(n, key)));
    tabs.appendChild(t);
  }
  head.append(title, crumb, tabs);

  const body = document.createElement('div');
  body.className = 'cat-body';
  // In the Lineage space's card the Catalog is laid out for a narrow column (0160).
  (shown === 'columns' ? catalogColumns : test ? catalogTestPreview : catalogPreview)(body, n, !!host.closest('#selpanel-card'));
  host.append(head, body);
  const filter = typing && $('#col-filter');
  if (filter) {
    filter.focus();
    filter.setSelectionRange(filter.value.length, filter.value.length);
  }
}

/* A Catalog tab opened on the node it shows, from its button, a count in
   Preview or Cmd+F alike, so none of them can come to open it differently. */
function showCatalogTab(n, key) {
  S.catTab = key;
  renderCatalog(n);
}

function h3(label) {
  const h = document.createElement('h3');
  h.textContent = label;
  return h;
}

/* The lineage on a node and its direct parents, the upstream box set to 1
   and the downstream one left as it was. */
function lineageOneUp(n) {
  $('#up').value = 1;
  focusNode(n.id, { keepDepth: true });
  showDock('lineage');
}

/* A details list: a line per [key, value, dim] whose value is not empty. */
function kvLines(pairs) {
  const kv = document.createElement('dl');
  kv.className = 'kvline';
  for (const [k, v, dim] of pairs) {
    if (!v) continue;
    kv.append(jel('dt', dim ? 'muted' : '', k), jel('dd', dim ? 'muted' : '', v));
  }
  return kv;
}

function stat(label, value, onClick) {
  const s = document.createElement('div');
  s.className = 'stat';
  const k = document.createElement('div');
  k.className = 'k';
  k.textContent = label;
  const v = document.createElement('div');
  v.className = 'v' + (onClick ? ' link' : '');
  v.textContent = value;
  if (onClick) {
    // A div rather than a button, so the number keeps the type of the plain
    // stats beside it.
    v.setAttribute('aria-label', `${label}: ${value}`);
    linkLike(v, onClick);
  }
  s.append(k, v);
  return s;
}

// ------------------------------------------------------------------- jobs --
/* Which of the orchestrator's jobs act on a node, read from folders the user
   named outside the project (0063). The pure part runs from jobsScheduleText
   to loadJobs, which web/tests/jobs.js slices. */

/* How a job starts, in a few words. Manual is what is left when nothing
   starts it: no clock, no asset, no other job, no webhook. */
function jobsScheduleText(job) {
  const parts = jobsStartedBy(job);
  return parts.length ? parts.join(' · ') : 'manual';
}

function jobsStartedBy(job) {
  const parts = [];
  if (job.cron) parts.push(job.cron);
  if (job.assets && job.assets.length) {
    const unread = job.assets_unread || [];
    parts.push('on ' + job.assets.join(', ') + (!unread.length ? ''
      : job.assets.length === 1 ? ', which no file read updates' : `; no file read updates ${unread.join(', ')}`));
  }
  if (job.after) parts.push(job.after_unread ? `after job ${job.after}, which no file read defines` : `after ${job.after}`);
  if (job.ci) parts.push('CI');
  if (job.merge) parts.push('on merge');
  if (job.note) parts.push(job.note);
  return parts;
}

/* Scheduled runs on its own, manual is started by nothing at all, and
   between the two sits what something starts that never leads back to a
   clock: CI, a merge, an asset only a manual DAG updates, `@once`. Unread
   may run on its own, on what no file read says: a templated schedule, an
   asset no file read updates (0077). */
function jobsStart(job) {
  if (job.scheduled) return 'scheduled';
  if (job.schedule_unread) return 'unread';
  return jobsStartedBy(job).length ? 'other' : 'manual';
}

/* The jobs that run on their own first, then those that may, and the manual
   ones last, each class in the order the server sent, which is the files' own
   (0055). `job` finds the job in an item: a node's groups hold one each. */
function jobsByStart(items, job = (g) => g.job) {
  const rank = { scheduled: 0, unread: 1, other: 2, manual: 3 };
  return (items || []).map((item) => ({ item, rank: rank[jobsStart(job(item))] }))
    .sort((a, b) => a.rank - b.rank).map((d) => d.item);
}

/* How many steps not resolved could act on the node, for the tab's summary
   and the Catalog's chip alike. */
function jobsMaybeCount(maybe) {
  return (maybe || []).reduce((a, g) => a + g.steps.length, 0);
}

/* A step by its job and its own name, or its place in a dbt Cloud job: what
   a Catalog chip asks the Jobs tab to show. Not the step's index alone, which
   a read after a job file changed gives to another step; the index still tells
   apart two sources of one label holding the same file. */
function jobsStepKey(job, step) {
  return [job.source, job.file, job.ident || job.name, step.name || step.n].join('\n');
}

/* A DAG by its id, a dbt Cloud job by its name and the identifier
   dbt-jobs-as-code appends to it there. */
function jobsJobLabel(job) {
  return job.kind === 'airflow' ? 'DAG ' + job.name : 'Job ' + job.name + (job.ident ? ' [[' + job.ident + ']]' : '');
}

/* An Airflow task by its id; a dbt Cloud step by its place, since dbt Cloud
   names none. */
function jobsStepLabel(job, step) {
  if (job.kind === 'airflow') return 'task ' + (step.name || step.n);
  return `step ${step.n} of ${job.steps}` + (step.implicit ? ', from run_generate_sources' : '');
}

/* A step on a Catalog chip: its job and itself, without the DAG and the
   task the Jobs tab writes in front, which the section's title says. */
function jobsChipText(job, step) {
  return jobsChipParts(job, step).join(' › ');
}

/* The chip's two halves, drawn either side of its own arrow. */
function jobsChipParts(job, step) {
  return [job.name, job.kind === 'airflow' ? (step.name || 'task ' + step.n) : `step ${step.n}/${job.steps}`];
}

/* One chip per step that runs the node, scheduled jobs first, as the Jobs
   tab lists them, and each job's steps in their order. */
function jobsChips(groups) {
  return jobsByStart(groups).flatMap((g) => g.steps.map((step) => ({ job: g.job, step, text: jobsChipText(g.job, step), parts: jobsChipParts(g.job, step) })));
}

/* Said once where a reason for a job's start is longer than a pill. */
const JOBS_UNREAD_WHY = 'May start on its own, on what no file read says: a templated schedule, a schedule or an asset written as a mapping, '
  + 'an empty list of assets, an asset no file read updates, a job no file read defines. Counted neither as scheduled nor as unscheduled';

/* `a`, `a and b`, `a, b and c`. */
function jobsAnd(items) {
  return items.length < 2 ? items.join('') : items.slice(0, -1).join(', ') + ' and ' + items[items.length - 1];
}

/* The sources a read came from, for the tab's header, each named once: two
   sources may share a label. */
function jobsSourcesText(names) {
  return jobsAnd([...new Set(names || [])]);
}

function jobsOrdinal(n) {
  const rest = n % 100;
  return n + (rest >= 11 && rest <= 13 ? 'th' : ['th', 'st', 'nd', 'rd'][n % 10] || 'th');
}

/* The days a cron's weekday field names, or '' for a field that is not a few
   plain days: a step, which no day list would say. */
function jobsDaysWords(dow) {
  if (dow === '*') return 'Every day';
  if (!/^[a-z0-9,-]+$/i.test(dow)) return '';
  const fields = cronFields('0 0 * * ' + dow);
  if (!fields) return '';
  const days = fields.dow;
  if (days.size === 7) return 'Every day';
  if (days.size === 5 && [1, 2, 3, 4, 5].every((d) => days.has(d))) return 'Weekdays';
  if (days.size === 2 && days.has(0) && days.has(6)) return 'Weekends';
  const names = ['Sundays', 'Mondays', 'Tuesdays', 'Wednesdays', 'Thursdays', 'Fridays', 'Saturdays'];
  return jobsAnd([1, 2, 3, 4, 5, 6, 0].filter((d) => days.has(d)).map((d) => names[d]));
}

/* A cron as one short sentence, or '' when it does not read as one: a
   sentence longer than the cron would say less than the cron does, and a
   guess is worse than the cron. Only what cronFields accepts is worded, then
   only the plain shapes: a time or a few times a day, on every day, a few
   weekdays or one day of the month; every hour; every N hours or minutes where
   N divides the day or the hour, since a step of 5 hours is not every five hours.
   Times are 24 hour. */
function jobsCronWords(cron) {
  const text = String(cron || '').trim();
  const presets = { '@hourly': 'Every hour', '@daily': 'Every day at 00:00', '@midnight': 'Every day at 00:00', '@weekly': 'Sundays at 00:00',
    '@monthly': 'The 1st of each month at 00:00', '@yearly': 'Every 1 January at 00:00', '@annually': 'Every 1 January at 00:00' };
  if (presets[text.toLowerCase()]) return presets[text.toLowerCase()];
  if (!cronFields(text)) return '';
  const f = text.split(/\s+/);
  if (f.length !== 5 || f[3] !== '*') return '';
  const [minute, hour] = f;
  const dom = f[2] === '?' ? '*' : f[2];
  const dow = f[4] === '?' ? '*' : f[4];
  const two = (n) => String(Number(n)).padStart(2, '0');
  const number = (x) => /^\d+$/.test(x);
  const step = /^\*\/(\d+)$/;
  if (number(minute) && /^\d+(,\d+)*$/.test(hour)) {
    const hours = [...new Set(hour.split(',').map(Number))].sort((a, b) => a - b);
    if (hours.length > 4) return '';
    const times = jobsAnd(hours.map((h) => two(h) + ':' + two(minute)));
    if (dom === '*') {
      const days = jobsDaysWords(dow);
      return days ? `${days} at ${times}` : '';
    }
    // The 29th to the 31st are skipped by the months without them: no sentence says "each month" then.
    return number(dom) && Number(dom) <= 28 && dow === '*' ? `The ${jobsOrdinal(Number(dom))} of each month at ${times}` : '';
  }
  if (dom !== '*' || dow !== '*') return '';
  const past = number(minute) && Number(minute) ? ` at :${two(minute)}` : '';
  if (number(minute) && hour === '*') return 'Every hour' + past;
  const hours = step.exec(hour);
  if (number(minute) && hours && Number(hours[1]) >= 2 && Number(hours[1]) <= 12 && 24 % Number(hours[1]) === 0) {
    return `Every ${hours[1]} hours` + past;
  }
  if (hour !== '*') return '';
  if (minute === '*') return 'Every minute';
  const minutes = step.exec(minute);
  if (minutes && Number(minutes[1]) >= 1 && 60 % Number(minutes[1]) === 0) {
    return Number(minutes[1]) === 1 ? 'Every minute' : `Every ${minutes[1]} minutes`;
  }
  return '';
}

/* How a job starts, for its card: what starts it in words, the cron and its
   zone beside them (always, as the builds judge it: UTC where the source names none, 0119,
   and only after a string that is a cron), and the tooltip saying what the clock's presence means.
   CI and a merge are tags of the card, not words here (0159). */
function jobsSchedule(job) {
  const start = jobsStart(job);
  const pieces = [];
  const clock = job.cron ? jobsCronWords(job.cron) : '';
  if (clock) pieces.push(clock);
  if (job.after) pieces.push(job.after_unread ? `After the job ${job.after}, which no file read defines` : `After the job ${job.after}`);
  if (job.assets && job.assets.length) {
    const unread = job.assets_unread || [];
    pieces.push((job.assets.length === 1 ? 'On the asset ' : 'On the assets ') + job.assets.join(', ') + (!unread.length ? ''
      : job.assets.length === 1 ? ', which no file read updates' : `; no file read updates ${unread.join(', ')}`));
  }
  if (job.note) pieces.push(job.note.charAt(0).toUpperCase() + job.note.slice(1));
  if (!jobsStartedBy(job).length) pieces.push('Manual');
  const title = start === 'scheduled' ? 'Runs on its own'
    : start === 'unread' ? JOBS_UNREAD_WHY
    : start === 'other' ? 'Started by something, never by a clock'
    : 'Nothing starts it: run by hand';
  return { start, words: pieces.join(' · '), cron: job.cron ? job.cron + (cronFields(job.cron) ? ` ${job.kind === 'airflow' ? (job.timezone || 'UTC') : 'UTC'}` : '') : '', title };
}

/* The tags of a card's head for what starts a job but no clock, each saying so
   in its tooltip, since the card draws no schedule for it. */
function jobsTags(job) {
  const tags = [];
  if (job.ci) tags.push({ text: 'CI', title: 'Started on each pull request, never by a clock' });
  if (job.merge) tags.push({ text: 'Merge', title: 'Started on each merge, never by a clock' });
  return tags;
}

/* What the header says of where the jobs came from: the sources read, and
   apart the ones that were not, with the reason the server gave. Either part is
   '' when it has nothing to say. */
function jobsReadLine(view) {
  const some = (a) => a && a.length;
  const gone = some(view.not_read_names)
    ? `${jobsSourcesText(view.not_read_names)} not read` + (view.not_read && view.not_read.reason ? ` (${view.not_read.reason})` : '') : '';
  return { read: some(view.sources) ? 'read from ' + jobsSourcesText(view.sources) : '', unread: gone };
}

/* The line under a card's head: where the job runs and what ties it to
   others. */
function jobsMeta(job) {
  const parts = [];
  if (job.env) parts.push('environment ' + job.env);
  if (job.target) parts.push('target ' + job.target);
  if (job.waits_for && job.waits_for.length) parts.push('waits for ' + job.waits_for.join(', '));
  if (job.triggers && job.triggers.length) parts.push('starts ' + job.triggers.join(', ') + ' when it ends');
  if (job.ci) parts.push('on each pull request');
  if (job.merge) parts.push('on each merge');
  return parts.join(' · ');
}

/* Why a step is listed under the node and what it sits beside, as segments
   of parts: `{ text }`, `{ code }`, or `{ chip: true }` for the node. What in
   its selection reached the node is said by name for the node's own name,
   `+tag:daily` says why a staging model is in a marts task. */
function jobsWhy(step, name) {
  const some = (a) => a && a.length;
  const codes = (list) => list.flatMap((t, i) => (i ? [{ text: ', ' }, { code: t }] : [{ code: t }]));
  const many = (list, one, more) => [{ text: list.length === 1 ? one : more }, ...codes(list)];
  const segments = [];
  if (some(step.via)) {
    const through = step.via.filter((t) => t !== name);
    if (step.via.length === 1 && step.via[0] === 'no --select: everything') {
      segments.push([{ text: 'selects everything (no --select)' }]);
    } else {
      const byName = through.length < step.via.length;
      const parts = [{ text: 'selects ' }, { chip: true }];
      if (byName) parts.push({ text: through.length ? ' by name and through ' : ' by name' });
      else parts.push({ text: ' through ' });
      segments.push(parts.concat(codes(through)));
    }
  }
  if (some(step.upstream)) segments.push(many(step.upstream, 'runs after the task ', 'runs after the tasks '));
  if (some(step.downstream)) segments.push(many(step.downstream, 'runs before the task ', 'runs before the tasks '));
  if (some(step.waited_by)) segments.push([{ text: 'awaited by ' }, ...codes(step.waited_by)]);
  if (some(step.outlets)) {
    const parts = [{ text: 'updates ' }, ...codes(step.outlets)];
    if (some(step.feeds)) parts.push({ text: ', which starts ' }, ...codes(step.feeds));
    segments.push(parts);
  }
  return segments;
}

/* The header's counts: the jobs that run the node, then the steps not
   resolved, the figure the Catalog's chip shows. Nothing when there is neither. */
function jobsHeadCounts(view) {
  const jobs = (view.groups || []).length;
  const steps = jobsMaybeCount(view.maybe);
  const parts = [];
  if (jobs) parts.push(jobs === 1 ? '1 runs it' : `${jobs} run it`);
  if (steps) parts.push(`${steps} not resolved`);
  return parts.join(' · ');
}

/* Coverage rows by folder, in the order the server sorted them. A folder is
   a level of its own only where it holds two of the rows or more: on a
   project with a folder per model, every model would otherwise be a folder to
   unfold. Each row goes under the deepest folder that gathers it with
   another, `rest` saying its path below that one. A row nothing gathers ends
   up alone, or under no folder, and the page lists it bare. */
function jobsCoverageGroups(rows) {
  const parts = (r) => (r.folder || '').split('/').filter(Boolean);
  const held = new Map();
  for (const r of rows || []) {
    const p = parts(r);
    for (let i = 1; i <= p.length; i++) {
      const f = p.slice(0, i).join('/');
      held.set(f, (held.get(f) || 0) + 1);
    }
  }
  const out = new Map();
  for (const r of rows || []) {
    const p = parts(r);
    let at = p.length;
    while (at > 0 && held.get(p.slice(0, at).join('/')) < 2) at--;
    const folder = p.slice(0, at).join('/');
    if (!out.has(folder)) out.set(folder, { folder, rows: [] });
    out.get(folder).rows.push(Object.assign({}, r, { rest: p.slice(at).join('/') }));
  }
  return [...out.values()];
}

/* A text with spans between backticks cut into its parts, `{text, code}`, so
   that what the server quoted can be drawn as code. An unmatched backtick
   stays as it is. */
function jobsBackticks(text) {
  const parts = [];
  String(text || '').split(/`([^`]+)`/).forEach((piece, i) => {
    if (piece) parts.push({ text: piece, code: i % 2 === 1 });
  });
  return parts;
}

/* The figures over the coverage: how many models, seeds and snapshots run in a
   scheduled job, in unscheduled ones only, in none, and the jobs and steps
   behind them. The schedule not read and the steps only when there is
   something to say. */
function jobsCoverageTiles(cov) {
  const unread = (cov.unread || []).length;
  const covered = cov.total - cov.never.length - cov.unscheduled.length - unread;
  const tiles = [
    { label: 'In a scheduled job', value: `${covered} of ${cov.total}`, sub: 'models, seeds and snapshots', tone: '' },
    { label: 'Only in unscheduled jobs', value: String(cov.unscheduled.length), sub: 'no clock starts them', tone: '' },
    { label: 'In no job', value: String(cov.never.length), sub: 'run by none of the jobs read', tone: cov.never.length ? 'warn' : '' },
  ];
  if (unread) tiles.push({ label: 'Schedule not read', value: String(unread), sub: 'only in jobs that may start on their own', tone: '' });
  const jobs = cov.jobs || [];
  tiles.push({ label: 'Jobs read', value: String(jobs.length), sub: `${jobs.filter((j) => jobsStart(j) === 'scheduled').length} scheduled`, tone: '' });
  const steps = (cov.empty || []).length + (cov.unresolved || []).length;
  if (steps) tiles.push({ label: 'Steps to look at', value: String(steps), sub: 'select nothing, or are not resolved', tone: '' });
  return tiles;
}

/* What PUT /api/jobs/sources takes from what the form holds. A key left at
   the proposed shape is not sent, so a source lists only what differs. `place`
   says where they are kept, `project` for .dbt-edith/jobs.yml or `settings`,
   and `seen` the version of that file the form was shown, so that a file
   changed since is not written over (0115). */
function jobSourcesBody(forms, defaults, place, seen) {
  return {
    sources: forms.map((f) => {
      const keys = {};
      if (f.kind === 'airflow') {
        for (const [k, d] of defaults) {
          const v = String((f.keys || {})[k] || '').trim();
          if (v && v !== d) keys[k] = v;
        }
      }
      const source = { kind: f.kind, path: String(f.path || '').trim(), label: String(f.label || '').trim(), keys };
      // The zone the DAGs' crons run in, one for the source; empty is UTC and
      // is not sent (0119).
      const zone = f.kind === 'airflow' ? String(f.timezone || '').trim() : '';
      if (zone) source.timezone = zone;
      return source;
    }),
    place,
    seen,
  };
}

/* Why a source's time zone cannot be saved, or '': this browser has to know
   the name, which the server, with no tz database, cannot say (0119). */
function jobsZoneIssue(form) {
  const zone = form.kind === 'airflow' ? String(form.timezone || '').trim() : '';
  return zone && !zoneKnown(zone) ? `${zone} is not a time zone this browser knows: write it as Europe/London does.` : '';
}

/* Why a path may not go in the project's .dbt-edith/jobs.yml, or '' (0115):
   that file comes with the repository, so it holds only a path from the
   project, at most two folders above it, with no hidden folder or file in it
   and no profiles.yml. The server holds it to the same, with the same rules. */
function jobsProjectPathIssue(path) {
  const p = String(path || '').trim();
  if (!p) return '';
  if (p.startsWith('/') || p.startsWith('\\') || /^[A-Za-z]:/.test(p)) return 'an absolute path';
  let depth = 0;
  let last = '';
  for (const seg of p.split(/[\\/]/).filter((x) => x && x !== '.')) {
    if (seg === '..') {
      depth--;
      if (depth < -2) return 'more than two folders above the project';
    } else {
      if (seg.startsWith('.')) return 'a hidden folder or file';
      depth++;
    }
    last = seg;
  }
  return /^profiles\.ya?ml$/i.test(last) ? 'a profiles.yml' : '';
}

/* Whether Save is held back: while a save is on its way, whatever else is
   typed meanwhile, or while a path cannot go in the project's file. A second
   click on the way would send the version the first is about to change. */
function jobsSaveDisabled(busy, issue) {
  return !!busy || !!issue;
}

function jobsPlural(n, word) {
  return `${n} ${word}${n === 1 ? '' : 's'}`;
}

/* What one source read, counted in its own words: DAGs and tasks, or jobs
   and steps. */
function jobsReadCounts(s) {
  const word = s.kind === 'airflow' ? ['DAG', 'task'] : ['job', 'step'];
  return `${jobsPlural(s.jobs, word[0])}, ${jobsPlural(s.steps, word[1])}`;
}

/* What a source's row says beside its name once it is read: its counts, the
   files refused and a walk stopped at its bound (in the warning tone); the
   error alone, in the warning tone, when nothing was read.
   Nothing before a read. Pure, for web/tests/settings.js. */
function jobSourceSummary(s) {
  if (!s) return { text: '', tone: '' };
  if (s.error) return { text: s.error, tone: 'warn' };
  const refused = (s.refused || []).length;
  const parts = [jobsReadCounts(s).replace(', ', ' \u00b7 ')];
  if (refused) parts.push(`${jobsPlural(refused, 'file')} refused`);
  // The walk stopped at its bound: some files were never read, which is worth the warning tone.
  if (s.capped) parts.push('stopped at 5 000 files');
  return { text: parts.join(' \u00b7 '), tone: s.capped ? 'warn' : '' };
}

/* Whether the Reports index, which the settings' rail counts the job sources
   from, no longer says how many the sources' own read found: the file changed
   outside the form. An index not yet loaded says nothing, so nothing is read
   for it. */
function jobsIndexBehind(index, found) {
  return !!index && (index.jobs ? index.jobs.sources : 0) !== found;
}

/* Whether a save read every source with nothing left to correct: each one
   found jobs, none failed, had a file refused or stopped at a bound. */
function jobsReadClean(sources) {
  return sources.length > 0
    && sources.every((s) => !s.error && !(s.refused || []).length && !s.capped && s.jobs > 0);
}

/* Whether a save closes the sources form. Only a clean read that was kept
   does, and only while the form still holds what was sent: the answer is
   then in the coverage. Anything else stays open on what went wrong, which
   is the answer to whether the keys are right, or on the edits made while
   the read ran, which the answer does not describe. */
function jobsSaveCloses(answer, sent, now) {
  return !!answer.saved && jobsReadClean(answer.sources || []) && JSON.stringify(sent) === JSON.stringify(now);
}

/* A save's toast, with its kind, once the form is no longer there to say it. */
function jobsSaveToast(answer) {
  const sources = answer.sources || [];
  if (!sources.length) return [answer.saved ? 'Saved: no job source left.' : 'No job source left, until dbt-edith stops.', 'ok'];
  if (!jobsReadClean(sources)) {
    return [`${answer.saved ? 'Saved' : 'Kept until dbt-edith stops'}, but not every source read cleanly: Orchestration says why.`, 'err'];
  }
  const read = sources.map(jobsReadCounts).join('; ');
  return answer.saved ? [`Saved and read: ${read}.`, 'ok'] : [`Read, but kept only until dbt-edith stops: ${read}.`, 'err'];
}

/* A small mapping as YAML lines, each list item a mapping of its own. */
function jobsYaml(value, depth) {
  const pad = ' '.repeat(depth);
  const lines = [];
  for (const [k, v] of Object.entries(value)) {
    if (Array.isArray(v)) {
      lines.push(pad + k + ':');
      for (const item of v) {
        const inner = jobsYaml(item, depth + 4);
        if (inner.length) inner[0] = pad + '  - ' + inner[0].slice(depth + 4);
        lines.push(...inner);
      }
    } else if (v && typeof v === 'object') {
      lines.push(pad + k + ':', ...jobsYaml(v, depth + 2));
    } else {
      lines.push(pad + k + ': ' + v);
    }
  }
  return lines;
}

/* The file each format is expected to look like. An Airflow one is drawn with
   the keys this source names, so the example reads in the user's own words:
   `pipeline.name` puts the id under a `pipeline:` of its own. */
function jobsExample(kind, keys, defaults) {
  if (kind === 'dbt_cloud') {
    return [
      '# dbt-jobs-as-code, as dbt Labs publishes it',
      'jobs:',
      '  daily:',
      '    name: Daily build',
      '    execute_steps:',
      '      - dbt build --select tag:daily',
      '    triggers:',
      '      schedule: true',
      '    schedule:',
      '      cron: "0 6 * * *"',
    ].join('\n');
  }
  const named = (k) => {
    const own = keys && String(keys[k] || '').trim();
    if (own) return own;
    const d = (defaults || []).find((p) => p[0] === k);
    return d ? d[1] : k;
  };
  const put = (into, path, value) => {
    const parts = path.split('.');
    let at = into;
    for (const p of parts.slice(0, -1)) {
      if (!at[p] || typeof at[p] !== 'object' || Array.isArray(at[p])) at[p] = {};
      at = at[p];
    }
    at[parts[parts.length - 1]] = value;
  };
  const task = {};
  put(task, named('task_id'), 'build_sales');
  put(task, named('command'), 'dbt run --select tag:sales');
  put(task, named('depends_on'), '[stage_sales]');
  const sensor = {};
  put(sensor, named('sensor_id'), 'wait_crm');
  put(sensor, named('external_dag_id'), 'crm_daily');
  put(sensor, named('external_task_id'), 'crm_load');
  const doc = {};
  put(doc, named('dag_id'), 'sales_daily');
  put(doc, named('schedule'), '"0 6 * * *"');
  put(doc, named('tasks'), [task]);
  put(doc, named('sensors'), [sensor]);
  return '# one file per DAG\n' + jobsYaml(doc, 0).join('\n');
}

/* The node the Jobs tab is about: the focus, or the one a Catalog chip
   opened it on, which a single click on a box puts in the Catalog without
   moving the focus, for as long as the Catalog still shows it. */
const jobsNode = () => (S.jobsFor && S.node && S.node.id === S.jobsFor ? S.jobsFor : S.focus);

/* A node's name as its box shows it: the node's own when the page holds it,
   else read off its unique_id, where what follows the package is the name of
   a model, `orders.v2` for a version, or of a source, `crm.customers`. A
   generic test's id ends in a hash, which is left off. Pure. */
function nameOfId(id, node) {
  if (node && node.id === id && node.name) return node.name;
  const parts = String(id || '').split('.');
  if (parts.length < 3) return parts[parts.length - 1] || '';
  if (parts[0] === 'test' && parts.length > 3) return parts[2];
  return parts.slice(2).join('.');
}

/* `look` asks the server to look at the job files first, and read them again
   if one moved: done when the tab is opened, never on a click inside it. Only
   the first request of a run carries it. A Catalog chip's step is taken here,
   so a run that ends early leaves none behind for a later one to light. */
async function loadJobs({ look = false } = {}) {
  const run = ++S.jobsRun;
  const body = $('#jobs-body');
  const reveal = S.jobsReveal;
  S.jobsReveal = null;
  // What the Catalog drew came from the read this may replace.
  if (look) forgetCatalogJobs();
  paintJobsHead();
  const id = jobsNode();
  const ask = (url) => {
    const looks = look;
    const asked = looks ? url + (url.includes('?') ? '&' : '?') + 'look=true' : url;
    look = false;
    return looks ? jobsLookGet(asked) : api.get(asked);
  };
  // The proposed shape is the server's, so the example cannot drift from it.
  // With no node, whether any source is set decides what the tab offers.
  let summary = null;
  if (!S.jobsKeys || !id) {
    try { summary = await ask('/api/jobs'); }
    catch (e) { if (run === S.jobsRun) toast('jobs: ' + e.message, 'err'); return; }
    if (run !== S.jobsRun) return;
    S.jobsKeys = summary.airflow_keys;
  }
  if (!id) {
    if (summary.refused) return jobsRefusedFile(body, summary.refused);
    if (!summary.sources.length) return jobsNoSource(body);
    body.replaceChildren(jel('div', 'compiled-empty', 'Select a model first, or open Reports for the coverage of the whole project.'));
    return;
  }
  let view;
  try { view = await ask('/api/jobs/node?id=' + encodeURIComponent(id)); }
  catch (e) { if (run === S.jobsRun) toast('jobs: ' + e.message, 'err'); return; }
  if (run !== S.jobsRun) return;
  paintJobsHead(view);
  renderJobs(body, view, id, reveal);
}

const jel = (tag, className, textContent = '') => Object.assign(document.createElement(tag), { className, textContent });

/* How a job starts, as a pill that says scheduled, not read or manual in a
   word, so they can be told apart at a glance down the Reports' lists. */
const JOBS_WORD = { scheduled: 'Scheduled', unread: 'Not read', manual: 'Manual' };
function jobsWhen(job) {
  const start = jobsStart(job);
  const pill = jel('span', 'jobwhen');
  pill.dataset.start = start;
  if (JOBS_WORD[start]) pill.append(jel('b', '', JOBS_WORD[start]));
  if (start !== 'manual') pill.append(jel('span', '', jobsScheduleText(job)));
  if (start === 'unread') pill.title = JOBS_UNREAD_WHY;
  return pill;
}

/* The head of the tab: one line naming the node, how many jobs run it and
   where they were read from, how long ago. The coverage of every model lives
   in Reports (0064) and the sources form beside it, in the dock's tab row
   (0159). The counts and the sources come with the answer, so the line is
   drawn with the name alone first. */
function paintJobsHead(view = null) {
  const id = jobsNode();
  const line = jel('div', 'jobs-headline');
  if (id) {
    // One item for the flex gap, which would otherwise fall between the words and the name.
    const about = jel('span', 'jobs-title', 'Jobs that run ');
    about.append(jel('b', 'jobs-about', nameOfId(id, S.node)));
    line.append(about);
    const counts = view ? jobsHeadCounts(view) : '';
    if (counts) line.append(jel('span', 'dim', counts));
    line.append(jel('span', 'grow'));
    const said = view ? jobsReadLine(view) : { read: '', unread: '' };
    if (said.read || said.unread) {
      // The part not read is an item of its own that does not shrink: in a narrow dock the part read is cut first.
      const where = jel('span', 'jobs-where');
      where.title = [said.read, said.unread].filter(Boolean).join(' · ');
      if (said.read) {
        const read = jel('span', 'dim jobs-read', said.read);
        if (S.jobsLooked) read.append(', ', jel('span', 'jobs-age', jobsAgeText()));
        where.append(read);
      }
      // The dot is an item of its own: a flex item loses a space at its edge, and the gap spaces the three.
      if (said.read && said.unread) where.append(jel('span', 'dim jobs-sep', '·'));
      if (said.unread) where.append(jel('span', 'dim jobs-unread', said.unread));
      line.append(where);
    }
  }
  $('#jobs-head').replaceChildren(...(id ? [line] : []));
  paintJobsTools();
}

/* A request that asks the server to look at the job files: the age the Jobs
   tab's header gives is of the last answer to one, whichever page sent it,
   since the files were compared then. */
async function jobsLookGet(url) {
  const got = await api.get(url);
  S.jobsLooked = Date.now();
  return got;
}

/* How long ago the job files were last compared, spelled as the manifest's
   card does. */
function jobsAgeText() {
  return cardAge(Math.max(0, Math.round((Date.now() - S.jobsLooked) / 1000)));
}

/* The tab's tools, in the dock's tab row where the lineage's are. */
function paintJobsTools() {
  const out = [];
  if (S.reports && S.reports.jobs) {
    const coverage = jel('button', 'btn sm icobtn', 'Coverage in Reports');
    coverage.type = 'button';
    coverage.title = 'Which models every job read runs, and which none does';
    coverage.addEventListener('click', () => openReports('jobs'));
    out.push(coverage);
  }
  const sources = jel('button', 'btn sm icobtn', 'Sources…');
  sources.type = 'button';
  sources.title = 'Where the jobs are read from, and how';
  sources.addEventListener('click', openJobSources);
  out.push(sources);
  $('#jobs-tools').replaceChildren(...out);
}

/* No source yet: what the Jobs tab and the coverage in Reports read, and what
   they expect to find. */
function jobsNoSource(body) {
  const box = jel('div', 'compiled-empty jobs-none');
  box.append(
    jel('p', '', 'Which jobs run a model is read from your orchestrator\'s YAML, wherever it lives, '
      + 'often in another repository. Name the folder, and say which format it is in.'),
  );
  const add = jel('button', 'btn primary', 'Add a source');
  add.addEventListener('click', () => openJobSources({ add: true }));
  box.append(add);
  // Folded, so the one thing to do stays in the middle of the tab.
  const formats = jel('details', 'jobs-formats');
  formats.append(jel('summary', '', 'The two formats read'));
  const figs = jel('div', 'jobs-figs');
  for (const [title, kind] of [['Airflow, one file per DAG; every key can be renamed', 'airflow'], ['dbt Cloud, in dbt-jobs-as-code\'s schema', 'dbt_cloud']]) {
    const fig = jel('figure', 'jobs-example');
    fig.append(jel('figcaption', '', title), jel('pre', '', jobsExample(kind, {}, (S.jobsKeys || []))));
    figs.append(fig);
  }
  formats.append(figs);
  box.append(formats);
  body.replaceChildren(box);
}

/* The project's own file, there and not readable: no source, and the reason
   in place of the invitation to add one, in the Jobs tab and the coverage
   alike (0115). */
function jobsRefusedFile(body, why) {
  const sources = jel('button', 'btn sm', 'Sources…');
  sources.addEventListener('click', openJobSources);
  body.replaceChildren(jel('div', 'jobs-warn', `.dbt-edith/jobs.yml is not read: ${why}. `
    + 'No job is known until it is: Sources… writes it again.'), sources);
}

/* A clock for the jobs that run on their own, the one mark of them (0159). */
function jobsClock() {
  const clock = strokeIcon('0 0 16 16', 'jobico', ['M8 2.25a5.75 5.75 0 1 0 0 11.5a5.75 5.75 0 1 0 0-11.5z', 'M8 4.75V8l2.25 1.5']);
  // The one mark, so it is named for whoever does not see it, not only by the title.
  clock.removeAttribute('aria-hidden');
  clock.setAttribute('role', 'img');
  clock.setAttribute('aria-label', 'Runs on its own');
  return clock;
}

/* What a step selects, said once under its command: the segments of jobsWhy
   joined by a dot, the node as a chip with its kind's bar. */
function jobsWhyLine(segments, mark, name) {
  const line = jel('div', 'jobwhy');
  segments.forEach((parts, i) => {
    if (i) line.append(' · ');
    for (const part of parts) {
      if (part.chip) {
        const chip = jel('span', 'jobchip-node');
        chip.append(dot(mark), name);
        line.append(chip);
      } else if (part.code) line.append(jel('code', '', part.code));
      else line.append(part.text);
    }
  });
  return line;
}

/* A reason the server gave, in the warning's box; what it quoted between
   backticks is code. */
function jobsWarn(text) {
  const box = jel('div', 'jobwarn');
  box.append(strokeIcon('0 0 16 16', 'jobico', ['M8 2.25L14.25 13H1.75z', 'M8 6.5v3M8 11.25v.1']));
  const said = jel('span', '');
  said.append(...jobsBackticks(text).map((x) => (x.code ? jel('code', '', x.text) : x.text)));
  box.append(said);
  return box;
}

/* One job and the steps of it that act on the node, as a card: its tool's
   colour down its side, then its start said in words (0159). `mark` is what
   the node's chip draws its kind from, `name` the node's name. */
function jobsCard(group, { reason = false, mark = 'model', name = '' } = {}) {
  const { job } = group;
  const sched = jobsSchedule(job);
  const card = jel('div', 'jobcard');
  card.dataset.kind = job.kind;
  const head = jel('div', 'jobhead');
  head.append(jel('span', 'jobkind', job.kind === 'airflow' ? 'Airflow' : 'dbt Cloud'), jel('b', 'jobname', job.name));
  if (job.kind === 'dbt_cloud' && job.ident) head.append(jel('span', 'jobid', job.ident));
  for (const tag of jobsTags(job)) {
    const tagEl = jel('span', 'jobtag', tag.text);
    tagEl.title = tag.title;
    head.append(tagEl);
  }
  if (sched.words || sched.cron) {
    const when = jel('span', 'jobsched');
    when.dataset.start = sched.start;
    when.title = sched.title;
    if (sched.start === 'scheduled') when.append(jobsClock());
    if (sched.words) when.append(sched.words);
    if (sched.cron) when.append(jel('span', 'jobcron', sched.cron));
    head.append(when);
  }
  head.append(jel('span', 'grow'), jobsFileButton(job.source, job.file, job.line, true));
  card.append(head);
  const meta = jobsMeta(job);
  if (meta) card.append(jel('div', 'jobmeta', meta));
  const steps = jel('div', 'jobsteps');
  for (const step of group.steps) {
    const row = jel('div', 'jobstep');
    row.dataset.key = jobsStepKey(job, step);
    row.dataset.step = step.index;
    row.append(jel('span', 'steplbl', jobsStepLabel(job, step)), jel('code', 'stepcmd', step.shown));
    if (step.ls) {
      const ls = jel('button', 'btn sm icobtn jobls');
      ls.type = 'button';
      ls.append(strokeIcon('0 0 16 16', 'jobico', ['M2.5 4l4 4-4 4M8.5 12.25h5']), 'dbt ls');
      ls.title = 'Type the dbt ls that lists what this step selects, without running it';
      ls.addEventListener('click', () => sendToTerminal(step.ls, false, null, 'the Jobs tab'));
      row.append(ls);
    } else {
      // The grid has a third column: a step without the button keeps it.
      row.append(jel('span', ''));
    }
    const why = reason ? [] : jobsWhy(step, name);
    if (why.length) row.append(jobsWhyLine(why, mark, name));
    for (const w of reason ? [step.unresolved] : step.warnings || []) if (w) row.append(jobsWarn(w));
    steps.append(row);
  }
  card.append(steps);
  return card;
}

function renderJobs(body, view, id, reveal) {
  // The project's own file, there and not readable: no source, and the reason
  // rather than the invitation to add one (0115).
  if (view.sources_refused) return jobsRefusedFile(body, view.sources_refused);
  if (!view.configured) return jobsNoSource(body);
  const out = [];
  if (view.refused) {
    out.push(jobsWarn(`${view.refused} file${view.refused === 1 ? '' : 's'} could not be read and may hold more: Sources… says which.`));
  }
  if (!view.groups.length) {
    out.push(jel('div', 'compiled-empty', `No step of the jobs read acts on ${nameOfId(id, S.node)}.`));
  }
  const name = nameOfId(id, S.node);
  const mark = S.node && S.node.id === id ? S.node : view.kind || 'model';
  for (const g of jobsByStart(view.groups)) out.push(jobsCard(g, { mark, name }));
  if (view.maybe && view.maybe.length) {
    const more = jel('details', 'jobs-maybe');
    const summary = jel('summary', '');
    summary.append(reportChevron('jobchev'), 'Not resolved, and could run it',
      jel('span', 'n', String(jobsMaybeCount(view.maybe))));
    more.append(summary);
    for (const g of jobsByStart(view.maybe)) more.append(jobsCard(g, { reason: true, mark, name }));
    out.push(more);
  }
  body.replaceChildren(...out);
  revealJobStep(body, id, reveal);
}

/* The step a Catalog chip was clicked for, scrolled to and lit once, or the
   steps not resolved, unfolded, and only on the node it was asked for: a
   step runs under every node it selects. By its key, and by its index among
   steps of one key, which only two sources of one label give. Within the
   tab's own scroll alone: scrollIntoView would also move the page's hidden
   overflows. */
function revealJobStep(body, id, want) {
  if (!want || want.id !== id) return;
  const maybe = want.maybe && body.querySelector(':scope > .jobs-maybe');
  if (maybe) maybe.open = true;
  const lines = [...body.querySelectorAll(':scope > .jobcard .jobstep')].filter((l) => l.dataset.key === want.key);
  const line = maybe || lines.find((l) => l.dataset.step === String(want.index)) || lines[0];
  if (!line) return;
  const at = maybe || line.closest('.jobcard');
  body.scrollTop += at.getBoundingClientRect().top - body.getBoundingClientRect().top - 8;
  if (!maybe) line.classList.add('jobs-hit');
}

/* What a coverage row adds after the name: the folder it sits in. */
function coverageSays(r, path) {
  return path || '';
}

/* A model of the coverage, its kind's bar first: the name opens it with the
   Jobs tab listing its jobs, and its folder follows, muted. */
function coverageRow(r, path, chip = false) {
  const li = jel('li', '');
  const title = `Open ${r.name}, with the Jobs tab listing its jobs`;
  const open = () => openFromReport(r.id, { dock: 'jobs' });
  // The row says what its bar is drawn from; the kind alone is what it falls back to.
  const node = reportLook(r.materialized) || r.kind;
  if (chip) {
    // A chip has no folder after it, so its tooltip names the folder.
    li.append(reportModelChip(r.name, node, r.folder ? `${title}\n${r.folder}` : title, open));
    return li;
  }
  const link = jel('a', 'filelink', r.name);
  link.title = title;
  link.addEventListener('click', (ev) => { ev.preventDefault(); open(); });
  li.append(dot(node), ' ', link);
  if (path) li.append(jel('span', 'muted', ' · ' + path));
  return li;
}

/* One step of a job: where it is, why it is listed, then its command in full
   and the file it is in, copied on a click. */
function jobsStepRow(r) {
  const li = jel('li', '');
  li.append(jel('span', 'rstep', `${r.job} › ${r.name || 'step ' + r.n}`));
  // The server quotes a selector or a flag between backticks: as code here.
  if (r.why) li.append(jel('span', 'muted', ' · '), ...jobsBackticks(r.why).map((x) => (x.code ? jel('code', 'rquote', x.text) : x.text)));
  const line = jel('div', 'rline rstepline');
  line.append(jel('code', 'rcmd', r.shown), jobsFileButton(r.source, r.file, r.line));
  li.append(line);
  return li;
}

/* Steps as a fold: those that select nothing they act on, those not resolved. */
function jobsStepList(title, refs, lever = '') {
  return { title, tone: '', lever, rows: refs, open: (n) => n <= 20,
    find: (r) => `${r.job} ${r.name || 'step ' + r.n} ${r.shown} ${r.why || ''}`,
    draw: (hits, d) => [reportList(hits, jobsStepRow, d)] };
}

function renderCoverage(body, cov) {
  if (cov.sources_refused) return jobsRefusedFile(body, cov.sources_refused);
  if (!cov.configured) return jobsNoSource(body);
  const folds = [];
  // A group with nothing in it is not drawn (reportFiltered).
  const models = (title, rows, tone, lever, open) => folds.push({ title, tone, lever, rows, open,
    find: (r) => `${r.name} ${r.folder || ''}`,
    draw: (hits, d, more) => checkFoldList(hits, d, more, coverageRow, coverageSays, rows) });
  const short = (n) => n <= 50;
  models('Run by no job', cov.never, 'warn', '', short);
  models('Only in unscheduled jobs', cov.unscheduled, '',
    'In jobs, but only ones nothing starts on its own: no schedule, @once, CI or merge, or an asset or a job that never leads back to a clock', short);
  models('Only in jobs whose schedule is not read', cov.unread || [], '', JOBS_UNREAD_WHY, short);
  models('Ephemeral, so never run on their own', cov.ephemeral, '', '', false);
  folds.push(jobsStepList('Steps that select nothing they act on', cov.empty));
  folds.push(jobsStepList('Steps not resolved', cov.unresolved));
  folds.push({ title: 'Jobs read', tone: '', rows: jobsByStart(cov.jobs, (j) => j), open: false,
    find: (j) => `${jobsJobLabel(j)} ${jobsScheduleText(j)} ${j.source}`,
    draw: (hits, d) => [reportList(hits, (j) => {
      const li = jel('li', '');
      const line = jel('div', 'rline');
      line.append(jobsWhen(j), jobsFileButton(j.source, j.file, j.line));
      li.append(jel('span', 'rstep', jobsJobLabel(j)), line);
      return li;
    }, d)] });
  // The figures (jobsCoverageTiles) say what a sentence over the lists would.
  body.replaceChildren(reportTiles(jobsCoverageTiles(cov)));
  reportLists(body, [{ folds }], 'Filter the models and steps');
}

/* What one source read, under its form once saved. */
function jobsReadNote(s) {
  if (s.error) return jel('div', 'jobs-warn', s.error);
  const box = jel('div', 'jobs-read');
  box.append(jel('div', '', `${jobsPlural(s.files, 'file')} read: ${jobsReadCounts(s)}`
    + (s.skipped ? `; ${s.skipped} without one` : '') + (s.capped ? '; stopped at 5 000 files' : '') + '.'));
  for (const r of s.refused || []) {
    box.append(jel('div', 'jobs-warn', `${r.file}${r.line ? ':' + r.line : ''}: ${r.message}`));
  }
  return box;
}

/* The folder picker under a source's path. A page is never told where a file
   it is handed sits, so the server lists one folder at a time, with what the
   walk would read there (0070). A click opens a folder or picks a file; Use
   writes the place the way the server spelled it, from the project when it
   is near. What it shows goes to `keep`, and comes back as `kept` to draw it
   again without asking the server. */
function browseJobSource(box, from, { use, cancel, kept, keep }) {
  let at = null;
  let picked = '';
  let asked = '';
  let ask = 0; // the last listing asked for: an answer to an earlier one is dropped
  let climbing = ''; // where ↑ goes, while its listing is on its way
  let first = null; // the row a double click began on
  const up = jel('button', 'btn sm', '↑');
  up.title = 'The folder above';
  up.setAttribute('aria-label', 'The folder above');
  up.disabled = true;
  const where = jel('input', 'grow');
  where.type = 'text';
  where.spellcheck = false;
  where.title = 'A folder, relative to the project or absolute: Enter goes there';
  const note = jel('p', 'jobsrc-note', '');
  const list = jel('div', 'jobsrc-entries');
  const as = jel('span', 'jobsrc-as', '');
  const useBtn = jel('button', 'btn sm primary', 'Use this folder');
  const cancelBtn = jel('button', 'btn sm', 'Cancel');
  const choice = () => (picked && at ? at.entries.find((e) => e.name === picked) : null);
  const paintChoice = () => {
    const file = choice();
    useBtn.textContent = file ? 'Use this file' : 'Use this folder';
    useBtn.disabled = !at;
    const written = file ? file.written : at && at.written;
    as.textContent = !at ? '' : written === '.' ? 'Saved as . (the project)' : 'Saved as ' + written;
    for (const r of list.children) r.classList.toggle('sel', !!picked && r.dataset.name === picked);
    if (keep) keep({ at, picked, asked });
  };
  const show = (next, path) => {
    at = next;
    asked = path;
    where.value = at.path;
    where.scrollLeft = where.scrollWidth; // a long path ends with the folder shown
    up.disabled = !at.up;
    note.textContent = [
      at.moved ? `${path} is not a folder this picker lists, so this is the nearest one above it.` : '',
      at.refused ? `This folder cannot be listed: ${at.refused}.` : '',
      at.capped ? `Only the first ${at.entries.length} entries are shown.` : '',
    ].filter(Boolean).join(' ');
    list.replaceChildren(...at.entries.map(row));
    if (!at.entries.length && !at.refused) list.append(jel('div', 'jobsrc-none', 'No folder and no YAML file here.'));
    paintChoice();
    list.scrollTop = 0;
    const sel = list.querySelector('.row.sel');
    if (sel) sel.scrollIntoView({ block: 'nearest' });
  };
  const go = async (path, climb = false) => {
    const mine = ++ask;
    climbing = climb ? path : '';
    let next;
    let failed = null;
    try { next = await api.get('/api/jobs/browse?path=' + encodeURIComponent(path)); }
    catch (e) { failed = e; }
    // A later listing was asked for, or this picker was closed, meanwhile.
    if (mine !== ask || !list.isConnected) return;
    climbing = '';
    if (failed) { note.textContent = failed.message; return; }
    picked = next.picked || '';
    show(next, path);
  };
  // Rows as the explorer draws them: a folder by its chevron, a file by its icon.
  const row = (e) => {
    const r = jel('div', 'row ' + (e.dir ? 'folder' : 'file'));
    r.tabIndex = 0;
    r.dataset.name = e.name;
    r.title = e.written;
    const caret = jel('span', 'caret');
    if (e.dir) caret.innerHTML = CHEVRON;
    r.append(caret);
    if (!e.dir) r.append(fileIcon(e.name));
    r.append(jel('span', 'nm', e.name));
    const act = (twice) => {
      if (e.dir) return go(e.written);
      if (twice) return use(e.written);
      picked = picked === e.name ? '' : e.name;
      paintChoice();
    };
    // The second click of a double click can land on a row of the folder the
    // first one opened, so it counts only on the row the first one hit.
    r.addEventListener('click', (ev) => { if (ev.detail > 1) return; first = r; act(false); });
    r.addEventListener('dblclick', () => { if (!e.dir && first === r) use(e.written); });
    r.addEventListener('keydown', (ev) => {
      if (ev.key !== 'Enter') return;
      ev.preventDefault();
      act(!e.dir && picked === e.name);
    });
    return r;
  };
  // Clicked again before the folder above is listed: one more up from there.
  up.addEventListener('click', () => {
    const to = climbing ? climbing + '/..' : at && at.up;
    if (to) go(to, true);
  });
  // Typing a place drops a listing on its way, which would overwrite it.
  where.addEventListener('input', () => { ask++; climbing = ''; });
  where.addEventListener('keydown', (ev) => { if (ev.key === 'Enter') { ev.preventDefault(); go(where.value); } });
  useBtn.addEventListener('click', () => { const file = choice(); if (at) use(file ? file.written : at.written); });
  cancelBtn.addEventListener('click', cancel);
  // Escape leaves the picker, not the form around it.
  box.addEventListener('keydown', (ev) => { if (ev.key === 'Escape') { ev.stopPropagation(); cancel(); } });
  const bar = jel('div', 'jobsrc-browse-bar');
  bar.append(up, where);
  const foot = jel('div', 'jobsrc-browse-foot');
  foot.append(as, cancelBtn, useBtn);
  box.replaceChildren(bar, note, list, foot);
  if (kept && kept.at) {
    picked = kept.picked;
    show(kept.at, kept.asked);
    return;
  }
  paintChoice();
  go(from || '');
}

/* The sources are edited in the settings' Orchestration section (0100), from
   every button that says Sources… or Add a source. */
function openJobSources({ add = false } = {}) {
  openSettings('jobs', { add: add === true });
}

/* The sources, in that section, one row each with the form of the one being
   edited unfolded under it. The form stays as it was left while a read leaves
   something to correct: saving reads the sources at once, and what was read
   is the answer to whether the keys are right. A clean read goes on to the
   coverage (jobsSaveCloses), since a form that only repaints the same line
   looked like a save that did nothing. `add` opens it on a new source, its
   picker open, for the buttons that say so. */
async function jobSourcesForm(box, { add = false } = {}) {
  box.replaceChildren(jel('p', 'setnote', 'Reading the sources…'));
  let summary;
  try { summary = await jobsLookGet('/api/jobs?look=true'); } catch (e) {
    // Not kept: the section asks again the next time it is shown.
    if (S.settingsKept.jobs && S.settingsKept.jobs.contains(box)) delete S.settingsKept.jobs;
    return box.replaceChildren(jel('div', 'jobs-warn', 'jobs: ' + e.message));
  }
  forgetCatalogJobs();
  // The rail counts from the index: read it again when the sources moved without the form.
  if (jobsIndexBehind(S.reports, summary.sources.length)) loadReportsIndex();
  const defaults = summary.airflow_keys || [];
  S.jobsKeys = defaults;
  // Where the sources are kept (0115). Once the project has its file, it is
  // the file that is edited and the settings are ignored; before, the person
  // chooses, and a list already in the settings stays there unless they move it.
  let from = summary.from;
  let hasFile = from === 'project';
  let refusedWhy = summary.refused || '';
  let seen = summary.stamp || '';
  let persist = !!summary.saved;
  let place = hasFile || summary.from !== 'settings' ? 'project' : 'settings';
  const forms = summary.sources.map((s) => ({ kind: s.kind, path: s.path, label: s.label || '', keys: Object.assign({}, s.keys), timezone: s.timezone || '' }));
  // A source being added has its picker open, and what the picker shows is
  // kept, so that drawing the rows again leaves it as it was without asking
  // the server again. It is unfolded, as a source being edited is.
  const fresh = (kind) => ({ kind, path: '', label: '', keys: {}, timezone: '', open: true, browsing: true, browsed: null });
  if (add) forms.push(fresh('airflow'));
  let reads = summary.sources;
  // Anything added, removed or typed since the last save: what the foot waits to save.
  let changed = add;
  const group = jel('section', 'sgroup jobsrc');
  const head = jel('div', 'sghead', 'Sources');
  const kept = jel('span', 'sgnote', '');
  head.append(kept);
  // Why the file is not read, under the head whether or not the foot shows.
  const refused = jel('div', 'jobs-warn srcrefused', '');
  const list = jel('div', 'srclist');
  const addRow = jel('div', 'srcadd');
  const foot = jel('div', 'srcfoot');
  const saved = jel('p', 'muted', '');
  const where = jel('div', 'jobsrc-place');
  const issue = jel('div', 'jobs-warn', '');
  let busy = false; // a save is on its way

  const input = (value, placeholder, onInput, cls = '') => {
    const i = jel('input', cls);
    i.type = 'text';
    i.spellcheck = false;
    i.value = value || '';
    i.placeholder = placeholder;
    i.addEventListener('input', () => { changed = true; onInput(i.value); });
    return i;
  };
  // What a source is called in its row: the label, else its kind.
  const called = (f) => f.label || (f.kind === 'airflow' ? 'Airflow' : 'dbt Cloud');
  // The form of one source: the card it was before, unfolded under its row.
  const formOf = (f, i) => {
    const card = jel('div', 'srcform');
    const top = jel('div', 'jobsrc-top');
    const kind = jel('select', '');
    for (const [v, label] of [['airflow', 'Airflow'], ['dbt_cloud', 'dbt Cloud']]) {
      kind.append(Object.assign(document.createElement('option'), { value: v, textContent: label, selected: f.kind === v }));
    }
    kind.addEventListener('change', () => { f.kind = kind.value; changed = true; paint(); refreshIssue(); });
    const remove = jel('button', 'btn sm', 'Remove');
    remove.addEventListener('click', () => { forms.splice(i, 1); reads = []; changed = true; paint(); refreshIssue(); });
    const path = input(f.path, '../orchestration/dags, or an absolute path', (v) => { f.path = v; refreshIssue(); }, 'grow');
    const browse = jel('button', 'btn sm', 'Browse…');
    browse.title = 'Pick the folder or the file from a list';
    let picker = null;
    const closePicker = () => {
      f.browsing = false;
      f.browsed = null;
      if (picker) picker.remove();
      picker = null;
      browse.classList.remove('on');
      browse.focus();
    };
    const openPicker = () => {
      f.browsing = true;
      browse.classList.add('on');
      // A picker of its own each time, so nothing of the last one is left.
      picker = jel('div', 'jobsrc-browse');
      top.after(picker);
      browseJobSource(picker, f.path, {
        kept: f.browsed,
        keep: (k) => { f.browsed = k; },
        use: (w) => { f.path = w; path.value = w; changed = true; closePicker(); refreshIssue(); },
        cancel: closePicker,
      });
    };
    browse.addEventListener('click', () => (f.browsing ? closePicker() : openPicker()));
    top.append(kind, path, browse, input(f.label, 'label', (v) => { f.label = v; }, 'jobsrc-label'), remove);
    card.append(top);
    if (f.browsing) openPicker();
    const example = jel('pre', 'jobs-example-text', jobsExample(f.kind, f.keys, defaults));
    if (f.kind === 'airflow') {
      const grid = jel('div', 'jobsrc-keys');
      for (const [k, d] of defaults) {
        grid.append(jel('label', '', k), input(f.keys[k], d, (v) => {
          f.keys[k] = v;
          example.textContent = jobsExample(f.kind, f.keys, defaults);
        }));
      }
      // Not a key of the files: the zone their crons are read in.
      const zone = input(f.timezone, 'UTC', (v) => { f.timezone = v; refreshIssue(); }, 'jobsrc-zone');
      zone.title = "The time zone the DAGs' schedules run in, such as Europe/London, one for every DAG of this source. Airflow takes it from each "
        + "DAG's start_date: default_timezone for a start_date with no zone; with dag-factory, the timezone beside the start_date it sets (the DAG's own, "
        + "or default_args.timezone), UTC when absent. Empty is UTC. It decides when a job's builds are late in Reports.";
      zone.setAttribute('aria-label', 'Time zone of the schedules');
      grid.append(jel('label', '', 'time zone'), zone,
        jel('span', 'jobsrc-zonehint', "The zone of the DAGs' start_date, such as Europe/London: default_timezone, or with dag-factory the timezone beside start_date, UTC when absent. Empty is UTC."));
      const cols = jel('div', 'jobsrc-cols');
      cols.append(grid, example);
      card.append(cols);
    } else {
      card.append(example);
    }
    if (reads[i]) card.append(jobsReadNote(reads[i]));
    return card;
  };
  const paint = () => {
    list.replaceChildren();
    forms.forEach((f, i) => {
      const item = jel('div', 'srcitem');
      const line = jel('div', 'srcline');
      const ico = jel('span', 'srcico');
      ico.append(strokeIcon('0 0 16 16', 'setglyph', f.kind === 'airflow' ? ['M2 4.5h12M2 8h12M2 11.5h7'] : ['M8 2l5.5 3v6L8 14l-5.5-3V5z']));
      const names = jel('span', 'srcname');
      names.append(jel('b', '', called(f)), jel('span', 'srcpath', f.path || 'no path yet'));
      const read = jobSourceSummary(reads[i]);
      const edit = jel('button', 'btn', 'Edit');
      edit.type = 'button';
      edit.dataset.key = 'src:' + i;
      edit.setAttribute('aria-label', `Edit ${called(f)}`);
      edit.setAttribute('aria-expanded', String(!!f.open));
      edit.addEventListener('click', () => {
        f.open = !f.open;
        paint();
        refreshIssue();
        // The row is drawn again with the form: the focus stays on its button.
        const back = list.querySelector(`[data-key="src:${i}"]`);
        if (back) back.focus();
      });
      line.append(ico, names, jel('span', read.tone === 'warn' ? 'srcsum warn' : 'srcsum', read.text), edit);
      item.append(line);
      if (f.open) item.append(formOf(f, i));
      list.append(item);
    });
    if (!forms.length) list.append(jel('p', 'srcnone', 'No source yet.'));
    paintFoot();
  };

  // The file takes only paths it may hold: a path that is not one says why
  // under the choice, and nothing is sent until it is mended or "For me only"
  // is picked, which keeps any path.
  const refreshIssue = () => {
    const bad = forms.find((f) => jobsProjectPathIssue(f.path));
    const pathWhy = bad && (hasFile || place === 'project')
      ? `${bad.path} is ${jobsProjectPathIssue(bad.path)}, which the project's file may not hold. `
        + 'Write the path from the project, or pick "For me only".'
      : '';
    const odd = forms.find((f) => jobsZoneIssue(f));
    const why = pathWhy || (odd ? jobsZoneIssue(odd) : '');
    issue.textContent = why;
    issue.hidden = !why;
    save.disabled = jobsSaveDisabled(busy, why);
  };

  // Read-only, the group is the rows and the button to add one. A source
  // unfolded, or the list changed, or a save answered, brings the foot.
  const paintFoot = () => {
    foot.hidden = !(forms.some((f) => f.open) || changed || saved.textContent);
  };

  // Where they are kept, beside the head: where the server last said they are,
  // not the choice a radio holds before a save.
  const paintKept = () => {
    kept.textContent = from === 'project' ? 'in .dbt-edith/jobs.yml'
      : from === 'settings' ? (persist ? 'for you only, outside the project' : 'until dbt-edith stops') : '';
    refused.textContent = refusedWhy ? `.dbt-edith/jobs.yml is not read: ${refusedWhy}. Saving writes it again.` : '';
    refused.hidden = !refusedWhy;
  };

  // The choice, or what the file already says. Painted again after a save,
  // since the first one writes the file and the form then edits it.
  const paintPlace = () => {
    where.replaceChildren();
    paintKept();
    if (hasFile) {
      where.append(jel('p', 'setnote', 'Kept in the project, in .dbt-edith/jobs.yml, which whoever has the repository shares. '
        + 'Saving rewrites that file; the settings are ignored while it exists, and nothing deletes it.'));
      return;
    }
    for (const [v, text] of [
      ['project', 'In the project, .dbt-edith/jobs.yml (shared, committed)'],
      ['settings', 'For me only (kept outside the project)'],
    ]) {
      const label = jel('label', 'jobsrc-choice');
      const radio = jel('input', '');
      radio.type = 'radio';
      radio.name = 'jobsrc-place';
      radio.checked = place === v;
      radio.addEventListener('change', () => { if (radio.checked) { place = v; refreshIssue(); } });
      label.append(radio, jel('span', '', text));
      where.append(label);
    }
  };

  const adder = jel('button', 'btn', 'Add a source');
  adder.type = 'button';
  adder.prepend(strokeIcon('0 0 16 16', 'setglyph', ['M8 3.5v9M3.5 8h9']));
  adder.addEventListener('click', () => { forms.push(fresh('airflow')); changed = true; paint(); refreshIssue(); });
  addRow.append(adder);
  const save = jel('button', 'btn sm primary', 'Save and read');
  save.addEventListener('click', async () => {
    if (busy) return;
    busy = true;
    save.disabled = true;
    const sent = jobSourcesBody(forms, defaults, hasFile ? 'project' : place, seen);
    try {
      const answer = await api.send('/api/jobs/sources', 'PUT', sent);
      reads = answer.sources;
      forgetCatalogJobs();
      // Kept while the panel is down, or by the tour that rolled it up, to
      // put back as it was left.
      const tourKept = S.tour && S.tour.saved && S.tour.saved.panelSaved && S.tour.saved.panelSaved.kept;
      const store = [S.settingsKept, tourKept].find((k) => k && k.jobs && k.jobs.contains(box));
      const kept2 = !!store;
      const route = jobsSaveRoute({ kept: kept2, shown: box.isConnected,
        clean: jobsSaveCloses(answer, sent, jobSourcesBody(forms, defaults, hasFile ? 'project' : place, seen)) });
      // The file now exists, with this version, whichever way the form goes on.
      from = answer.from;
      hasFile = from === 'project';
      refusedWhy = answer.refused || '';
      seen = answer.stamp || '';
      persist = hasFile || !!answer.saved;
      changed = false;
      if (route === 'gone') {
        // A form read cleanly behind another section is done with: its
        // section reads the sources afresh when it is shown again.
        if (kept2) delete store.jobs;
        toast(...jobsSaveToast(answer));
        if (S.dock === 'jobs') loadJobs();
        if (panelOpen('reports') && S.reportsSection === 'jobs') return showReportSection('jobs');
        return loadReportsIndex();
      }
      if (route === 'read') return jobSourcesRead(answer);
      saved.textContent = answer.from === 'project'
        ? 'Saved in .dbt-edith/jobs.yml. Only YAML files are read, never through a symlink.'
        : answer.saved
          ? 'Saved for this project, outside it. Only YAML files are read, never through a symlink.'
          : 'No config directory is available, so these sources last until dbt-edith stops.';
      paintPlace();
      paint();
      if (S.dock === 'jobs') loadJobs();
      loadReportsIndex();
    } catch (e) {
      // The file moved on since the form read it (a pull, an edit in the
      // editor): left as it is, and said, since a second save would fail the same way.
      if (e.changed) saved.textContent = '.dbt-edith/jobs.yml changed on disk since this form read it. Close this section and open it again to read it, and nothing is written over it until then.';
      paintFoot();
      toast('sources: ' + e.message, 'err');
    } finally {
      busy = false;
      refreshIssue();
    }
  });
  const bar = jel('div', 'srcsave');
  bar.append(save, saved);
  foot.append(where, issue, bar);
  group.append(head, refused, list, addRow, foot);
  paintPlace();
  paint();
  refreshIssue();
  box.replaceChildren(group);
}

/* Where a save goes once the server has answered. `gone`: the form rolled
   up with the panel while it read, or was put aside behind another section
   and read cleanly, so a toast says what it did. `read`: on screen and read
   cleanly, so it moves on (jobSourcesRead). `paint`: the form stays, saying
   what each source read. */
function jobsSaveRoute({ kept, shown, clean }) {
  if (!kept || (clean && !shown)) return 'gone';
  return clean ? 'read' : 'paint';
}

/* A clean read: the form is done, and the answer is in the Jobs tab of the
   model under the panel, or else in the coverage. The settings roll up onto
   the Jobs tab, or give their place to the coverage, which is where they
   came from when a Sources… there opened them. The Jobs tab reads its
   sources again either way, shown now or once the coverage rolls up. */
function jobSourcesRead(answer) {
  toast(...jobsSaveToast(answer));
  delete S.settingsKept.jobs;
  const back = S.settingsFrom !== 'reports' && S.dock === 'jobs' && jobsNode();
  if (back) closePanel({ restore: true });
  if (S.dock === 'jobs') loadJobs();
  return back ? loadReportsIndex() : openReports('jobs');
}


// ----------------------------------------------------------------- spaces --
/* The top bar's tabs (0140): Code, Lineage and Reports, and the settings
   button among the squares. A space is a panel without an ×, and Code is no
   panel down. A tab is a place, never a switch: the one in front does nothing
   when clicked, and what takes you back to Code is its tab or Escape. */
const SPACE_OF = { '': 'code', select: 'lineage', reports: 'reports', settings: 'settings' };

const spaceNow = () => SPACE_OF[S.panel] || 'code';

function goSpace(name) {
  if (name === spaceNow()) return;
  if (name === 'code') {
    // Cleared first: the settings opened from Reports would give Reports back.
    S.settingsFrom = '';
    closePanel({ restore: true });
  } else if (name === 'lineage') {
    openSelection();
  } else if (name === 'reports') {
    openReports();
  } else if (name === 'settings') {
    openSettings();
  }
}

/* Lights the tab of the space in front, and the settings button while the settings are
   open; the dock's Selection button says whether its space is. Called
   by every panel's paint. */
function paintSpaces() {
  const now = spaceNow();
  for (const b of $$('#spaces .sp')) {
    if (b.dataset.space === now) b.setAttribute('aria-current', 'page');
    else b.removeAttribute('aria-current');
  }
  const gear = $('#settings-btn');
  gear.classList.toggle('on', now === 'settings');
  gear.setAttribute('aria-expanded', String(now === 'settings'));
  $('#graph-mode [data-mode=select]').setAttribute('aria-expanded', String(now === 'lineage'));
  // The status bar says where the space in front puts you.
  updateStatus();
}

// ----------------------------------------------------------------- panels --
/* What rolls down over the editor and the dock, the sidebar staying beside
   it unless the panel is wide (0064, 0091, 0101, 0137, 0140): what speaks of
   the whole project, or wants the window's height. What follows the file in front
   stays in the dock. One panel at a
   time, opening one rolls up the one that was down. Each names its element,
   what paints its button, what it does once rolled up, and how the tour puts
   it back. */
const PANELS = {
  reports: {
    el: '#reports',
    // Over the sidebar too: a list of hundreds is read at full width (0137).
    wide: true,
    paint: () => { paintReportsButton(); paintSpaces(); },
    // The Catalog it covered asks for its jobs if it has not, once it is
    // seen again: not when another panel takes this one's place (0063).
    closed: () => fillCatalogJobs($('#catalog .cat-jobs')),
    save: () => ({ section: S.reportsSection }),
    reopen: (saved) => openReports(saved.section, { reread: false }),
  },
  select: {
    el: '#select-panel',
    // Over the sidebar too: a selection is read across the whole window (0101).
    wide: true,
    paint: () => paintSpaces(),
    // Its card closes first, as it opened inside the panel.
    escape: () => closeSelCard(),
    closed: () => selectPanelUp(),
    // Its line is the tour's to put back, with the selector box's history.
    save: () => ({}),
    reopen: () => openSelection(),
  },
  settings: {
    el: '#settings',
    // Over the sidebar too, as every space but Code is (0140).
    wide: true,
    paint: () => { paintSettingsButton(); paintSpaces(); },
    // A form left half filled goes with the panel, as it went with its
    // dialog, but for the tour's, which puts it back as it was left. Rolled
    // down over Reports, by a Sources… there or the settings button, a close from the
    // keyboard or its own buttons gives Reports back, as the dialog left it
    // down under it.
    closed: ({ restore } = {}) => {
      S.settingsKept = {};
      if (!restore || S.settingsFrom !== 'reports' || S.panel) return;
      // Down at once, as it was left, so nothing under it takes a key while
      // the index is read again; its section is drawn afresh then, unless
      // another panel has taken its place meanwhile.
      openPanel('reports');
      loadReportsIndex().then(() => { if (panelOpen('reports')) showReportSection(S.reportsSection); });
    },
    save: () => ({ section: S.settingsSection, kept: S.settingsKept, from: S.settingsFrom }),
    reopen: (saved) => {
      S.settingsKept = saved.kept || {};
      openSettings(saved.section);
      S.settingsFrom = saved.from || '';
    },
  },
};

/* Inert while a panel is down, so nothing under it takes a key or a Tab: the
   editor and the terminal would otherwise go on typing under it. A wide
   panel covers the sidebar too, and only it does (0101). */
const PANEL_COVERS = ['#editor-pane', '#gutter-dock', '#dock'];
const PANEL_WIDE = ['#sidebar', '#gutter-side'];

/* What panel `name` covers made inert and the rest not, none for ''. */
function coverFor(name) {
  for (const id of PANEL_COVERS) $(id).inert = !!name;
  for (const id of PANEL_WIDE) $(id).inert = !!name && !!PANELS[name].wide;
}

const panelOpen = (name) => S.panel === name;

/* Rolls a panel down over the editor and the dock, the one already down
   rolling up first. A close from the keyboard sends the focus back to where
   it was before the first of them came down. */
function openPanel(name) {
  if (S.panel === name) return;
  closeHoverCard();
  closePopup();
  // Read once the popups are closed: a button in one would be gone by the
  // time the focus is given back.
  const back = S.panel ? S.panelReturn : document.activeElement;
  if (S.panel) closePanel({ next: name });
  S.panel = name;
  S.panelReturn = back;
  coverFor(name);
  const p = PANELS[name];
  const el = $(p.el);
  el.classList.add('open');
  el.setAttribute('aria-hidden', 'false');
  el.focus({ preventScroll: true });
  p.paint();
}

/* Rolls the panel up. `restore` gives the focus back to where it was when the
   panel came down, for a close from the keyboard or from its own buttons; a
   file opened from it is where the reader goes next instead. `next` is the
   panel taking its place: what is under them stays inert, and the hooks run
   with it already down, so nothing under it counts as seen in between. The
   `closed` hook is told whether the close was one that gives the focus back. */
function closePanel({ restore = false, next = '' } = {}) {
  const name = S.panel;
  if (!name) return;
  const p = PANELS[name];
  const el = $(p.el);
  S.panel = next;
  el.classList.remove('open');
  el.setAttribute('aria-hidden', 'true');
  coverFor(next);
  const back = S.panelReturn;
  S.panelReturn = null;
  if (el.contains(document.activeElement)) document.activeElement.blur();
  if (restore && back && back.focus && document.body.contains(back) && !el.contains(back)) back.focus();
  p.paint();
  p.closed({ restore });
}

/* Escape in a panel: what it opened inside itself closes first, the
   selection's card, and the panel only with nothing such left open. */
function escapePanel() {
  const p = PANELS[S.panel];
  if (!(p.escape && p.escape())) closePanel({ restore: true });
}

// ---------------------------------------------------------------- reports --
/* Reports on the whole project, in one panel rolled down over the editor and
   the dock from the top bar (0064). The pure part runs from reportsSections to
   loadReportsIndex, which web/tests/reports.js slices. */

/* The sections there are, in the order they are worked through, each only
   while it has something to show: the warnings once a config path applies to
   nothing, collin's report once a run wrote one, the coverage of the jobs
   once a source is named, the macros while one of the project's is reached by
   no node and nothing explains it, and, empty, once a macro's card asked for
   its callers, `focus` (0105), and last the tool's own checks while one finds
   a node (0116) and the builds of each environment once the index says
   Snowflake is on and the manifest holds the dbt_artifacts tables (0117), and
   those of each job once a source is named as well (0119), and the order of
   the jobs' steps once a source is named (0126),
   each `quiet`: listed, but it never lights the button nor opens the panel
   (0116, 0117, 0119, 0126). Before
   that the coverage is listed all the same, `empty`, as the place a source is
   added from (0070), but it is not opened on for itself, and the button stays
   dimmed (0075). */
function reportsSections(index, focus) {
  const all = [
    { key: 'run', label: 'Last run', tool: 'dbt',
      title: 'What the last dbt command ran and how each node ended, from target/run_results.json' },
    { key: 'warnings', label: 'Warnings', tool: 'dbt',
      title: 'What dbt warns of as it parses, worked out without a run: config paths of dbt_project.yml that apply to no resource' },
    { key: 'collin', label: "collin's report", tool: 'collin',
      title: 'What collin found reading the compiled SQL, from target/collin.report.json' },
    { key: 'jobs', label: 'Job coverage', tool: 'jobs',
      title: "Which models the orchestrator's jobs run, read from the sources the Jobs tab names" },
    { key: 'joborder', label: 'Job order', tool: 'jobs',
      title: "Which steps build a model whose dbt parent another job's step builds, without the job files ordering that step first" },
    { key: 'macros', label: 'Macros', tool: 'dbt',
      title: "The project's macros no node reaches, and who calls a macro, from what the manifest records each node and macro calling" },
    { key: 'checks', label: 'Checks', tool: 'dbt',
      title: "This tool's own checks on the project, which dbt warns of none of: sources without freshness, models with no test or no description, sources no node reads" },
    { key: 'builds', label: 'Builds by environment', tool: 'snowflake',
      title: "When each model last ran in each environment and how it ended, read from Snowflake when asked, from the tables of the dbt_artifacts package" },
    { key: 'jobbuilds', label: 'Builds by job', tool: 'snowflake',
      title: "How each job's models last ended in each environment, judged by the job's own schedule, from the same read as the builds by environment" },
  ];
  // The builds of a job want both what the jobs run and the builds' tables,
  // and are an index entry of neither (0119). The order of the steps wants the
  // jobs and is no entry of its own: the index is polled, and it would work
  // the order out on every poll (0126).
  const has = (key) => !!(index && (key === 'jobbuilds' ? index.builds && index.jobs : key === 'joborder' ? index.jobs : index[key]));
  // The last run's mark says how it ended, from the counts the index carries;
  // none while dbt is still writing the file and the index lists its time alone,
  // nor when the run did nothing a pass could be said of.
  const run = index && index.run;
  if (run && typeof run.error === 'number') all.find((s) => s.key === 'run').tone = runEndTone(run);
  // A card's focus lists the macros all the same, `empty` unless one lights
  // the button: what lights it is the user's rule, not a click (0105).
  const listed = (key) => key === 'jobs' || has(key) || (key === 'macros' && !!focus);
  // The checks are listed in the rail and never light the button or open the
  // panel, `quiet`: they would be there on nearly every project (0116). The
  // builds are too, since they hold nothing until the user's click reads them,
  // which is no file's news (0117). The order of the steps is a question
  // asked, and a project with jobs would nearly always have an answer, so it
  // is no news either (0126).
  const quiet = (key) => key === 'checks' || key === 'builds' || key === 'jobbuilds' || key === 'joborder';
  return all.filter((sec) => listed(sec.key))
    .map((sec) => Object.assign(sec, has(sec.key) ? (quiet(sec.key) ? { quiet: true } : {}) : { empty: true }));
}

/* Whether a section lights the button and may be the one the panel opens on:
   one with something, and not a quiet one (0075, 0116). */
function lights(sec) {
  return !sec.empty && !sec.quiet;
}

/* What is new in the reports since each was last shown, in the sections'
   order: what runBadge says of the last run, warningsBadge of the warnings,
   collinBadge of collin's, jobsBadge of the coverage. The button carries it,
   and nothing opens by itself (0059). */
function reportsNews(collin, run, jobs, warnings) {
  const news = [];
  if (run) news.push({ key: 'run', tone: 'bad', text: run.text, short: run.short, title: run.title });
  if (warnings) news.push({ key: 'warnings', tool: 'dbt', text: warnings.text, short: warnings.short, title: warnings.title });
  if (collin) news.push({ key: 'collin', tool: 'collin', text: collin.text, short: collin.short, title: collin.title });
  if (jobs) news.push({ key: 'jobs', tone: 'warn', text: jobs.text, short: jobs.short, title: jobs.title });
  return news;
}

/* What the chips on the button say: a report's words when it is the only one
   with news, its count alone when several are, so the button stays short;
   the tooltip has the words either way. */
function reportsChipTexts(news) {
  return (news || []).map((n) => (news.length > 1 ? n.short : n.text));
}

/* How many more models, seeds and snapshots no scheduled job runs than when
   the coverage was last shown (0066). Fewer is no news, and the page lowers
   what it last saw to match, so that a later rise counts from there. */
function jobsBadge(jobs, seen) {
  if (!jobs || typeof jobs.never !== 'number' || typeof seen !== 'number') return null;
  const now = jobs.never + (jobs.unscheduled || 0);
  if (now <= seen) return null;
  const n = now - seen;
  return { text: `${n} more unscheduled`, short: `+${n}`,
    title: `${n} more model${n > 1 ? 's' : ''}, seed${n > 1 ? 's' : ''} or snapshot${n > 1 ? 's' : ''} than when you last looked `
      + `${n > 1 ? 'are' : 'is'} run by no scheduled job: ${jobs.never} in no job, ${jobs.unscheduled || 0} only in unscheduled jobs.` };
}

/* Whether the manifest is behind what the warnings hold it against:
   dbt_project.yml saved after it, or other files, by the freshness badge.
   A folder added since the last parse is in no manifest, so a key naming it
   reads unused though dbt will not warn of it (0103). Just after a parse the
   freshness answer is ahead of the index: a manifest newer than the one the
   index was read with makes the warnings behind until the index is read again. */
function warningsStale(w, fresh) {
  return !!w && (w.at > w.manifest_at || !!(fresh && ((fresh.state && fresh.state !== 'fresh') || fresh.manifest_at > w.manifest_at)));
}

/* How many config paths of dbt_project.yml apply to nothing beyond what the
   section showed last (0103). A page starts from none seen: dbt says this
   only once, as it parses, so a path stays news until the section has been
   looked at, and a count that falls lowers what was seen with it. None while
   the manifest is behind: the count may be the manifest's age, not the
   project's. */
function warningsBadge(w, seen, fresh) {
  if (!w || typeof w.unused !== 'number' || w.unused <= (seen || 0) || warningsStale(w, fresh)) return null;
  const n = w.unused - (seen || 0);
  const more = seen ? `, ${n} more than when you last looked` : '';
  return { text: `${n} unused path${n > 1 ? 's' : ''}`, short: seen ? `+${n}` : String(n),
    title: `dbt_project.yml has ${w.unused} config path${w.unused > 1 ? 's' : ''} that apply to no resource${more}, `
      + 'which dbt warns of as it parses.' };
}

/* What a reader has to know before trusting the warnings: a file that could
   not be read, then a manifest older than what it is held against, since a
   folder added after the last parse is in no manifest and its key reads
   unused until dbt parses again (0103). `fresh` is the freshness badge's. */
function warningsNotes(r, fresh) {
  const out = [];
  if (r.unread) {
    out.push({ tone: 'warn', text: `dbt_project.yml could not be read here, at line ${r.unread.line}: ${r.unread.message}. `
      + 'Nothing is worked out from it until it can be.' });
  } else if (r.at > r.manifest_at) {
    out.push({ tone: 'warn', text: 'dbt_project.yml was saved after the manifest was written: a key added or moved since may name '
      + 'nodes the manifest does not hold yet, until dbt parses again.' });
  } else if (fresh && fresh.state && fresh.state !== 'fresh') {
    out.push({ tone: 'warn', text: 'Files changed since the manifest was written: a folder added since is in no manifest, '
      + 'so its key reads unused until dbt parses again.' });
  }
  if (!r.unread && !(r.unused || []).length) {
    out.push({ tone: '', text: `Each of the ${r.checked} config paths of dbt_project.yml applies to a resource.` });
  }
  return out;
}

/* What the last run leaves on the button until its section is shown: its
   errors and failed tests, only for a file written since the page last
   looked, as collin's badge (0059). Warnings are for the section to say. */
function runBadge(run, seen) {
  if (!run || !(run.error || run.fail)) return null;
  if ((run.at || 0) <= (seen || 0)) return null;
  const errors = run.error ? `${run.error} error${run.error > 1 ? 's' : ''}` : '';
  const what = run.command ? `dbt ${run.command}` : 'The last dbt command';
  const said = [errors, run.fail ? `${run.fail} failed test${run.fail > 1 ? 's' : ''}` : ''].filter(Boolean);
  return { text: [errors, run.fail ? `${run.fail} failed` : ''].filter(Boolean).join(', '),
    short: String((run.error || 0) + (run.fail || 0)), title: `${what} ended with ${said.join(' and ')}.` };
}

/* A dbt outcome as the section says it. One it does not know is shown as
   dbt wrote it. */
function runStatusWord(status) {
  return { ok: 'ok', error: 'error', fail: 'failed', warn: 'warned', skipped: 'skipped', partial: 'partly done',
    noop: 'nothing to do', reused: 'reused' }[status] || status;
}

/* The order outcomes are listed in: what to look at first. */
function runStatusRank(status) {
  const at = ['error', 'fail', 'warn', 'partial', 'skipped', 'ok', 'noop', 'reused'].indexOf(status);
  return at < 0 ? 99 : at;
}

function runSecs(s) {
  if (typeof s !== 'number' || !isFinite(s)) return '';
  if (s < 1) return `${s.toFixed(2)} s`;
  if (s < 10) return `${s.toFixed(1)} s`;
  if (s < 60) return `${Math.round(s)} s`;
  return `${Math.floor(s / 60)} min ${Math.round(s % 60)} s`;
}

/* `model` as a heading: `Models`; `unit_test` as `unit tests`. */
function runKindPlural(kind, capital) {
  const words = String(kind || 'node').replace(/_/g, ' ') + 's';
  return capital ? words[0].toUpperCase() + words.slice(1) : words;
}

/* What the head says of the run: the command as dbt was given it, the
   selection only, then the dbt that ran it and how long it took. */
function runAbout(run) {
  const cmd = run.command ? ['dbt ' + run.command].concat(run.selection || []).join(' ') : 'a dbt command';
  // Fusion writes no time for a command that ran nothing, as a zero.
  return [cmd, run.dbt_version && `dbt ${run.dbt_version}`, run.elapsed > 0 && runSecs(run.elapsed)].filter(Boolean).join(' · ');
}

/* What a reader has to know before trusting the section, warnings first. A
   node the run did not reach is said in a count, never listed: absent from
   the file, it was not run, which says nothing about it. */
function runNotes(run) {
  const warn = [], dim = [];
  const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
  const ran = (run.kinds || []).reduce((a, k) => a + k.ran, 0);
  if (run.older_than_manifest) {
    warn.push('The manifest was written after this run: a parse or another command since may have changed what the project holds.');
  }
  if (run.other_target) {
    warn.push(`${plural(run.other_target, 'result names a table', 'results name tables')} the manifest names otherwise: this run was likely for another target.`);
  }
  if (run.unknown && run.unknown.of) {
    warn.push(`${plural(run.unknown.of, 'result names a node', 'results name nodes')} the manifest no longer has.`);
  }
  // Commands that build nothing, and still write the file over the last run.
  if (['compile', 'show', 'docs generate', 'run-operation'].includes(run.command)) {
    dim.push(`dbt ${run.command} wrote this file over the one before, so what the last run did is no longer in it.`);
  }
  if (!ran) dim.push('It ran no node.');
  else {
    const short = (run.kinds || []).filter((k) => k.of > k.ran);
    if (short.length) {
      dim.push(`It ran ${short.map((k) => `${k.ran} of ${k.of} ${runKindPlural(k.kind)}`).join(', ')}: `
        + 'a node it did not reach is not in it, which says nothing about that node.');
    }
  }
  if (run.command === 'test') dim.push('dbt test runs tests alone: no model was built by it.');
  return warn.map((text) => ({ tone: 'warn', text })).concat(dim.map((text) => ({ tone: '', text })));
}

/* The counts of a status map (the run's or a kind's, word to count) in the
   shape the index carries: error, fail, warn, partial, ok for what passed,
   was reused or had nothing to do, and other for a word this page does not
   know. A skipped result is none of them. */
function runEndCounts(st) {
  const c = { error: 0, fail: 0, warn: 0, partial: 0, ok: 0, other: 0 };
  for (const [word, n] of Object.entries(st || {})) {
    if (['error', 'fail', 'warn', 'partial'].includes(word)) c[word] += n;
    else if (['ok', 'noop', 'reused'].includes(word)) c.ok += n;
    else if (word !== 'skipped') c.other += n;
  }
  return c;
}

/* How a run ended, from those counts: bad on an error or a failed test, warn
   on a warning, a partial success or a status nobody here knows, ok when
   something ran and all of it passed (what it skipped does not spoil that),
   and none, '', when nothing ran or all it did was skip: no mark is drawn then,
   rather than claim a pass, and the section keeps its tool's colour. */
function runEndTone(c) {
  return c.error || c.fail ? 'bad' : c.warn || c.partial || c.other ? 'warn' : c.ok ? 'ok' : '';
}

/* The words for a tone, on the mark and in the rail row's tooltip. */
function runEndWords(tone) {
  return { bad: 'Ended with errors or failed tests', warn: 'Not everything passed', ok: 'All passed' }[tone] || '';
}

/* The figures over the section: a tile per kind that ran, then the time. */
function runTiles(run) {
  const tiles = (run.kinds || []).map((k) => {
    const st = k.statuses || {};
    const sub = Object.keys(st).sort((a, b) => runStatusRank(a) - runStatusRank(b))
      .map((s) => `${st[s]} ${runStatusWord(s)}`).join(' · ');
    const end = runEndTone(runEndCounts(st));
    const tone = end === 'ok' ? '' : end;
    return { label: runKindPlural(k.kind, true), value: k.of ? `${k.ran} of ${k.of}` : String(k.ran), sub, tone };
  });
  if (run.elapsed > 0) tiles.push({ label: 'Took', value: runSecs(run.elapsed), sub: 'for the whole command', tone: '' });
  return tiles;
}

/* What follows a node's name in a list: how it ended, how many rows a test
   found, and how long it took. */
function runEntryText(e) {
  const bits = [runStatusWord(e.status)];
  if (typeof e.failures === 'number' && e.failures > 0) bits.push(`${e.failures} row${e.failures > 1 ? 's' : ''}`);
  if (e.secs) bits.push(runSecs(e.secs));
  return bits.join(' · ');
}

/* An explanation split at its first sentence: that one is read at once, the
   rest sits behind "why" (reportLever). A text with one sentence has no rest. */
function leverSplit(text) {
  const s = String(text || '');
  const m = /^([\s\S]*?[.!?])\s+(\S[\s\S]*)$/.exec(s);
  return m ? { first: m[1], rest: m[2] } : { first: s, rest: '' };
}

/* The folds of a section, filtered on their data and not on the rows drawn:
   a list capped at a hundred rows is searched whole. A group is
   `{group?, label?, desc?, head?, folds}`; a fold is `{title, tone, lever,
   badge?, rows, of?, open, find, draw}` where `of` is the total found when the
   server sent fewer rows, `open` a boolean or a function of the rows it would
   list, and `find` the text of a row a filter is held against. Each fold comes
   back with its `hits`, its `count` (the total, or `n of m` while filtered)
   and whether it is `open`, and a fold or a group with nothing to show is
   left out. A group with only a `head`, such as an environment that could not
   be read, stays. */
function reportFiltered(groups, q) {
  const needle = String(q || '').trim().toLowerCase();
  const out = [];
  for (const g of groups) {
    const folds = [];
    for (const f of g.folds || []) {
      const of = f.of === undefined ? f.rows.length : f.of;
      if (!of) continue;
      const hits = needle ? f.rows.filter((row) => String(f.find(row)).toLowerCase().includes(needle)) : f.rows;
      if (needle && !hits.length) continue;
      const n = needle ? hits.length : of;
      folds.push(Object.assign({}, f, {
        hits, of,
        count: needle && hits.length < of ? `${hits.length} of ${of}` : String(f.badge !== undefined ? f.badge : of),
        open: typeof f.open === 'function' ? !!f.open(n) : !!f.open,
        // A filter searches the rows sent, so it cannot say how many the server held back.
        more: needle ? 0 : Math.max(0, of - f.rows.length),
      }));
    }
    if (folds.length || g.head) out.push(Object.assign({}, g, { folds }));
  }
  return out;
}

/* What a key row of the Checks says after its name: the server words it
   `key K: no not_null on M`. A key of one column is the column the row names
   already, so only what is wrong remains. A composite key is not drawn
   anywhere else, so its columns stay, and two keys of one model missing the
   same column read apart; when every column of it lacks the test, saying them
   twice is replaced by saying so. Anything else is as sent. */
function checkDetail(row) {
  const d = row.detail || '';
  const key = Array.isArray(row.key) ? row.key : [];
  if (key.length === 1) {
    const lead = `key ${key[0]}: `;
    return d.startsWith(lead) ? d.slice(lead.length) : d;
  }
  const all = key.join(', ');
  return key.length > 1 && d === `key ${all}: no not_null on ${all}` ? `no not_null on any column of key ${all}` : d;
}

/* The figures over the Warnings: how many paths dbt_project.yml holds, and how
   many of them apply to nothing. None while the file could not be read. */
function warningsTiles(r) {
  if (r.unread) return [];
  const unused = (r.unused || []).length;
  return [
    { label: 'Config paths', value: String(r.checked), sub: 'in dbt_project.yml' },
    { label: 'Apply to no resource', value: String(unused), sub: 'what they set reaches nothing', tone: unused ? 'warn' : '' },
  ];
}

/* Who reads the files a section is made of, in the order the rail lists them,
   with the word that names each: the rail's heads and the chip in a section's
   head say the same one, beside the colour the source has. */
function reportSources() {
  return [['dbt', 'dbt'], ['collin', 'collin'], ['jobs', 'Jobs'], ['snowflake', 'Snowflake']];
}

function reportSourceLabel(tool) {
  const found = reportSources().find(([key]) => key === tool);
  return found ? found[1] : tool;
}

/* The rail's groups, by who reads the files: the order of the sections is kept
   inside each, and a group without a section is not listed. */
function reportsRailGroups(sections) {
  return reportSources()
    .map(([tool, label]) => ({ tool, label, sections: sections.filter((sec) => sec.tool === tool) }))
    .filter((g) => g.sections.length);
}

/* The count beside a section in the rail and what its tooltip says it counts,
   from what the page already holds: the index, collin's state and, for the
   order of the steps, the count the section left behind when it was last
   drawn (`kept`). None for zero. A count that needs a read, the job files',
   is never fetched for the rail, and the builds have none: a number across
   environments would match nothing on the page. */
function reportsRailCount(key, index, collin, kept) {
  const i = index || {};
  const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
  let n = 0;
  let title = '';
  if (key === 'run') {
    const r = i.run || {};
    n = (r.error || 0) + (r.fail || 0) + (r.warn || 0) + (r.partial || 0) + (r.other || 0);
    title = `${plural(n, 'result', 'results')} of the last run did not pass`;
  } else if (key === 'warnings') {
    n = (i.warnings && i.warnings.unused) || 0;
    title = `${plural(n, 'config path', 'config paths')} of dbt_project.yml that ${n === 1 ? 'applies' : 'apply'} to no resource`;
  } else if (key === 'collin') {
    n = (collin && collin.report && collin.report.to_investigate) || 0;
    title = `${plural(n, 'model or table', 'models or tables')} collin's last run names to look at`;
  } else if (key === 'jobs') {
    n = ((i.jobs && i.jobs.never) || 0) + ((i.jobs && i.jobs.unscheduled) || 0);
    title = `${plural(n, 'model, seed or snapshot', 'models, seeds or snapshots')} run by no scheduled job`;
  } else if (key === 'macros') {
    n = (i.macros && i.macros.unexplained) || 0;
    title = `${plural(n, 'macro', 'macros')} no node reaches and nothing explains`;
  } else if (key === 'checks') {
    n = (i.checks && i.checks.count) || 0;
    title = `${plural(n, 'finding', 'findings')} in this tool's own checks`;
  } else if (key === 'joborder') {
    n = (kept && kept.joborder) || 0;
    title = `${plural(n, 'pair', 'pairs')} of steps found when the section was last drawn`;
  }
  return n > 0 ? { n, title } : null;
}

/* The section the panel opens on: one with news, then the one read last this
   session unless it is empty, then the first that is not, and the first there
   is, the empty coverage, only when every one is (0070, 0075): the macros come
   after the coverage, so the first listed is not always the one to open on.
   A quiet section is none of them. */
function reportsDefaultSection(sections, news, last) {
  const has = (key) => sections.some((sec) => sec.key === key);
  const fresh = (news || []).find((n) => has(n.key));
  if (fresh) return fresh.key;
  if (last && sections.some((sec) => sec.key === last && lights(sec))) return last;
  const full = sections.find(lights);
  return full ? full.key : sections.length ? sections[0].key : '';
}

/* The button's tooltip: what the reports hold, then what is new in them, or
   what will fill them while nothing does, since the button is dimmed then
   rather than hidden (0075). */
function reportsButtonTitle(sections, news, key) {
  const names = sections.filter(lights).map((sec) => sec.label).join(', ');
  const none = 'Nothing yet: the last dbt run fills one, from target/run_results.json, a config path of dbt_project.yml '
    + 'that applies to nothing another, collin\'s report another, the job coverage once the Jobs tab has a source, '
    + 'which is added here, and a macro of the project no node reaches that nothing explains.';
  return [`Reports on the whole project${names ? ': ' + names : ''} (${key})`]
    .concat(names ? (news || []).map((n) => n.title) : [none]).join('\n');
}

/* Whether the file behind the section on screen changed after it was read:
   the head then says so, rather than the section redrawing under the reader
   (0059). A section whose report has gone is stale too. */
function reportsStale(shown, index, key) {
  if (!shown) return false;
  return JSON.stringify(shown) !== JSON.stringify((index && index[reportsEntry(key)]) || null);
}

/* The index entry a section is kept fresh against: the order of the steps is
   read from the same files as the coverage, so it moves with the coverage's
   entry (0126). */
function reportsEntry(key) {
  return key === 'joborder' ? 'jobs' : key;
}

async function loadReportsIndex() {
  try { S.reports = await api.get('/api/reports'); }
  catch { return; }   // what the button said still stands: a poll never interrupts
  // The gutter of dbt_project.yml follows the same count, read again only
  // when it moved (0103).
  const unused = JSON.stringify(S.reports.warnings || null);
  if (unused !== S.unusedKey) {
    S.unusedKey = unused;
    remarkUnusedPaths();
  }
  paintReportsButton();
  // Only the buttons that hang on the reports: the head holds the answer's counts and sources.
  if (S.dock === 'jobs') paintJobsTools();
  if (panelOpen('reports')) paintReportsNav();
  // The settings' rail counts the job sources from the same index.
  repaintSettings();
}

function newsChip(n) {
  const chip = jel('span', 'rnew', n.text);
  if (n.tool) chip.dataset.tool = n.tool;
  if (n.tone) chip.dataset.tone = n.tone;
  chip.title = n.title || '';
  return chip;
}

function reportsNow() {
  // A run finished before the page loaded is not news to anyone.
  if (S.collinSeen === undefined && S.collin) S.collinSeen = S.collin.run || 0;
  if (S.runSeen === undefined && S.reports) S.runSeen = S.reports.run ? S.reports.run.at : 0;
  const jobs = S.reports && S.reports.jobs;
  if (jobs && typeof jobs.never === 'number') {
    const now = jobs.never + (jobs.unscheduled || 0);
    if (S.jobsSeen === undefined || now < S.jobsSeen) S.jobsSeen = now;
  }
  const warnings = S.reports && S.reports.warnings;
  const unused = warnings ? warnings.unused : 0;
  if (S.warningsSeen === undefined) S.warningsSeen = 0;
  if (unused < S.warningsSeen) S.warningsSeen = unused;
  const run = runBadge(S.reports && S.reports.run, S.runSeen);
  return { sections: reportsSections(S.reports, S.macroFocus),
    news: reportsNews(collinBadge(S.collin, S.collinSeen), run, jobsBadge(jobs, S.jobsSeen),
      warningsBadge(warnings, S.warningsSeen, S.fresh)) };
}

function paintReportsButton() {
  const btn = $('#space-reports');
  const { sections, news } = reportsNow();
  // In view from the first paint, so the panel is found before it has
  // anything, and dimmed until a section does, with no chip until then:
  // news of a report the index does not list yet would say the opposite of
  // its tooltip (0075).
  const some = sections.some(lights);
  btn.classList.remove('hidden');
  const open = panelOpen('reports');
  btn.classList.toggle('dim', !some && !open);
  if (!some) news.length = 0;
  btn.title = reportsButtonTitle(sections, news, keyLabel('Mod+Alt+R', IS_MAC));
  const texts = reportsChipTexts(news);
  btn.querySelector('.rnews').replaceChildren(...news.map((n, i) => newsChip(Object.assign({}, n, { text: texts[i] }))));
}

/* Rolls the panel down over the editor and the dock, on the section asked
   for or the one reportsDefaultSection picks. The index is read first, so a
   report written since the last poll is there to pick. */
async function openReports(section, { reread = true } = {}) {
  await loadReportsIndex();
  const { sections, news } = reportsNow();
  // The coverage is always listed, empty before any source, so there is
  // always a section to open on (0070).
  const key = sections.some((sec) => sec.key === section) ? section : reportsDefaultSection(sections, news, S.reportsSection);
  openPanel('reports');
  // Put back by the tour as it was left (0075): the section is still drawn,
  // so it is not read again, and its Read again says when its file changed.
  if (!reread && key === S.reportsDrawn) {
    S.reportsSection = key;
    paintReportsNav();
    updateStatus();
    return;
  }
  showReportSection(key);
}

/* The rail: the sections under who reads their files, each with what it
   counts when it counts something (0137). The mark is the last run's alone,
   saying how it ended; the tool is the group's. */
function paintReportsNav() {
  const { sections, news } = reportsNow();
  $('#reports-nav').replaceChildren(...reportsRailGroups(sections).map((g) => {
    const group = jel('div', 'reports-navgroup');
    // Its rows take the source's colour from it.
    group.dataset.tool = g.tool;
    group.setAttribute('role', 'group');
    group.setAttribute('aria-label', g.label);
    group.append(jel('div', 'reports-navhead', g.label));
    for (const sec of g.sections) {
      const row = jel('button', 'reports-navrow' + (sec.empty ? ' empty' : ''));
      row.type = 'button';
      row.dataset.key = sec.key;
      const sourceless = sec.empty && sec.key === 'jobs';
      row.title = sourceless ? 'No source named yet: add the folders your jobs are in' : sec.title;
      if (sec.key === S.reportsSection) row.setAttribute('aria-current', 'true');
      const words = runEndWords(sec.tone);
      if (words) {
        const dot = jel('span', 'tooldot');
        dot.dataset.tool = sec.tool;
        // Inside a button, the mark is not read: the row's title says the outcome.
        dot.dataset.tone = sec.tone;
        dot.setAttribute('aria-hidden', 'true');
        dot.title = words;
        row.title += '\n' + words;
        row.append(dot);
      }
      row.append(jel('span', '', sec.label));
      const count = reportsRailCount(sec.key, S.reports, S.collin, S.reportsCounts);
      if (count) {
        const n = jel('span', 'tabbadge', String(count.n));
        n.title = count.title;
        row.append(n);
      }
      if (sourceless) row.append(jel('span', 'rhint', 'add a source'));
      // The rail is narrow: the count alone, the words being on the button.
      const chip = news.find((x) => x.key === sec.key);
      if (chip) row.append(newsChip(Object.assign({}, chip, { text: chip.short })));
      row.addEventListener('click', () => showReportSection(sec.key));
      group.append(row);
    }
    return group;
  }));
  paintReportStale();
}

function paintReportStale() {
  const again = $('#reports-view .reports-again');
  if (!again) return;
  const stale = reportsStale(S.reportsShown, S.reports, S.reportsSection);
  again.classList.toggle('stale', stale);
  again.textContent = stale ? 'Newer results: read again' : 'Read again';
}

/* The head every section shares: what it is, what it was read from, and its
   buttons, Read again saying when the file has changed since. */
function reportHead({ title, tool, tone, about, again, extra = [] }) {
  const head = jel('div', 'rhead');
  const row = jel('div', 'rhead-row');
  row.append(jel('span', 'ttl', title));
  // The source, named in its colour. The mark stays only to say how the last
  // run ended: the colour is never all that says whose a section is.
  const chip = jel('span', 'srcchip', reportSourceLabel(tool));
  chip.dataset.tool = tool;
  row.append(chip);
  const words = runEndWords(tone);
  if (words) {
    const dot = jel('span', 'tooldot');
    dot.dataset.tool = tool;
    dot.dataset.tone = tone;
    dot.setAttribute('role', 'img');
    dot.setAttribute('aria-label', words);
    dot.title = words;
    row.append(dot);
  }
  row.append(jel('div', 'grow'), ...extra);
  if (typeof again === 'function') {
    const read = jel('button', 'btn reports-again', 'Read again');
    read.addEventListener('click', again);
    row.append(read);
  }
  head.append(row);
  // What it was read from, on a line of its own; a section with nothing to say
  // of that has no line.
  if (about) head.append(jel('div', 'sub', about));
  return head;
}

/* A fold of a section, known by its summary and those of the folds around
   it, without the count a run changes. */
function reportFoldKey(d) {
  const names = [];
  for (let at = d; at; at = at.parentElement ? at.parentElement.closest('details') : null) {
    const sum = at.querySelector(':scope > summary');
    const title = sum && (sum.querySelector('.rtitle') || sum);
    names.unshift(title ? title.textContent.replace(/ \(\d+\)$/, '') : '');
  }
  return names.join(' › ');
}

/* Which folds of the section on screen are open, the "why" of which lever is
   unfolded, what its filter holds, and where its list is scrolled: a list of
   hundreds is gone through one model at a time, each opened from it, and
   coming back must find it as it was left. */
function keepReportPlace(view) {
  const scroller = view.querySelector('.reportbody');
  if (!scroller) return null;
  const open = {};
  const all = {}; // the folds whose capped list was shown whole
  const touched = {}; // the folds the reader opened or shut, which a filter leaves as they are
  for (const d of scroller.querySelectorAll('details')) {
    const key = reportFoldKey(d);
    open[key] = d.open;
    if (d.dataset.all) all[key] = true;
    if (d.dataset.touched) touched[key] = true;
  }
  const whys = {};
  for (const b of scroller.querySelectorAll('.rmorebtn')) whys[b.closest('[data-key]').dataset.key] = b.getAttribute('aria-expanded') === 'true';
  const find = view.querySelector('.reportfilter');
  return { open, all, touched, whys, filter: find ? find.value : '', scroll: scroller.scrollTop };
}

function restoreReportPlace(view, place) {
  const scroller = view.querySelector('.reportbody');
  if (!place || !scroller) return;
  // The filter first: it draws the lists again, at once and not after the
  // wait a typed key has, and what follows is put back on the lists as they
  // come out. A place without one (the filter's own redraw) leaves it alone.
  const find = view.querySelector('.reportfilter');
  if (find && place.filter !== undefined && find.value !== place.filter) find.redraw(place.filter);
  // Show all first: a list drawn again brings folds of its own, whose state
  // is then put back from a fresh look at the folds.
  for (const d of scroller.querySelectorAll('details')) {
    const more = place.all && place.all[reportFoldKey(d)] && d.querySelector('.showall');
    if (more) more.click();
  }
  for (const d of scroller.querySelectorAll('details')) {
    const key = reportFoldKey(d);
    if (key in place.open) {
      d.open = place.open[key];
      if (place.touched && place.touched[key]) d.dataset.touched = '1';
      // A fold that makes its list when first opened (Builds by job) has to
      // have it before the scroll is put back, which the event it fires on
      // its own, a task later, would not.
      if (d.open) d.dispatchEvent(new Event('toggle'));
    }
  }
  for (const b of scroller.querySelectorAll('.rmorebtn')) {
    const want = place.whys && place.whys[b.closest('[data-key]').dataset.key];
    if (want !== undefined && want !== (b.getAttribute('aria-expanded') === 'true')) b.click();
  }
  scroller.scrollTop = place.scroll;
}

/* The pieces every section is made of (0137): figures, a lever folded to its
   first sentence, folds of entries, a filter over them. web/tests/joborder.js
   evaluates this block, so it holds functions only. */

/* The figures over a section, a tile each. */
function reportTiles(tiles) {
  const box = jel('div', 'reporttiles');
  // How many, so that a strip of one or two figures is not stretched across the page.
  box.setAttribute('style', `--n: ${Math.max(tiles.length, 1)}`);
  for (const t of tiles) {
    const tile = jel('div', 'reporttile');
    if (t.tone) tile.dataset.tone = t.tone;
    // A label that is a node (an environment's tag) is drawn as it is; its words stay in `label`.
    const lab = jel('div', 'rlabel', t.head ? '' : t.label);
    if (t.head) lab.append(t.head);
    tile.append(lab, jel('div', 'rvalue', t.value), jel('div', 'rsub', t.sub || ''));
    box.append(tile);
  }
  return box;
}

/* What explains a finding or a section: its first sentence, and the rest
   behind "why". The sentence is the key the open "why"s are kept by. */
function reportLever(text, cls = 'rlever') {
  const { first, rest } = leverSplit(text);
  const p = jel('p', cls, first);
  p.dataset.key = first;
  if (rest) {
    // The last word goes with the button, so that a sentence filling the line
    // never leaves "why" alone at the start of the next.
    const at = first.lastIndexOf(' ') + 1;
    p.textContent = first.slice(0, at);
    const tail = jel('span', 'rtail', first.slice(at));
    const more = jel('span', 'rmore', ' ' + rest);
    more.hidden = true;
    const btn = jel('button', 'rmorebtn', 'why');
    btn.type = 'button';
    btn.setAttribute('aria-expanded', 'false');
    btn.addEventListener('click', () => {
      more.hidden = !more.hidden;
      btn.setAttribute('aria-expanded', String(!more.hidden));
      btn.textContent = more.hidden ? 'why' : 'less';
    });
    tail.append(btn);
    p.append(tail, more);
  }
  return p;
}

/* The chevron before a fold's title, a folder's name or a job's, turned down
   by the stylesheet while it is open: Reports has this one only. The Jobs tab's
   own fold gives it its class. */
function reportChevron(className = 'rchev') {
  return strokeIcon('0 0 16 16', className, ['M6 4l4 4-4 4']);
}

/* A folder inside a fold: its name and how many it holds, behind a chevron. */
function reportFolderSummary(text) {
  const sum = jel('summary', '');
  sum.append(reportChevron(), text);
  return sum;
}

/* A fold as reportFiltered hands it back: its title and count, then its lever.
   Its list is the caller's, appended to it. A finding that has a severity
   (collin's) says it in a tag after the count. Opened or shut by the reader,
   it is `touched`, and the filter then keeps it as it was left. */
function reportFold(f) {
  const d = jel('details', 'reportfinding');
  d.open = f.open;
  if (f.tone) d.dataset.tone = f.tone;
  const sum = jel('summary', '');
  // A count is a pill; a phrase in its place (a macro's "used by 3 models, 2
  // tests") stays text, which a pill would squeeze.
  const counted = /^\d[\d,. ]*(of \d[\d,. ]*)?$/.test(String(f.count || ''));
  sum.append(reportChevron(), jel('span', 'rtitle', f.title), jel('span', counted ? 'tabbadge rcount' : 'rcount', f.count));
  if (f.severity) sum.append(jel('span', 'sevtag', f.severity));
  sum.addEventListener('click', () => { d.dataset.touched = '1'; });
  d.append(sum);
  if (f.lever) d.append(reportLever(f.lever));
  return d;
}

/* Whether a list says nothing of its models but their names, `says` being what
   each entry adds after the name: such a list is drawn as chips in a wrapping
   row, one that says more stays a line an entry. */
function reportNamesOnly(says) {
  return says.length > 0 && says.every((x) => !x);
}

/* The node a chip's bar is drawn from, in the shape `dot` takes, out of what
   the server says a row's bar is drawn from (`Node::look`): a model's
   materialization, or the kind itself for a source, a seed or a snapshot.
   Null when the row says nothing: its chip has no bar. */
function reportLook(look) {
  if (!look) return null;
  return ['source', 'seed', 'snapshot'].includes(look) ? { kind: look } : { kind: 'model', materialized: look };
}

/* A model as a chip: its kind's bar, then its name, a button the keyboard
   reaches. The bar is the tree's and the boxes' (`dot`). */
function reportModelChip(name, node, title, open) {
  const chip = jel('button', 'mlink', '');
  chip.type = 'button';
  chip.title = title;
  if (node) chip.append(dot(node));
  chip.append(name);
  chip.addEventListener('click', open);
  return chip;
}

/* A fold's entries: the first `cap`, a button for the rest, and how many the
   server held back (`more`). Show all is remembered on the fold. `chips` draws
   the entries side by side, as reportNamesOnly says of them. */
function reportList(rows, rowFn, d, cap = Infinity, more = 0, chips = false) {
  const ul = jel('ul', 'rentries' + (chips ? ' models' : ''));
  const paint = (upTo) => {
    const items = rows.slice(0, upTo).map(rowFn);
    if (rows.length > upTo) {
      const li = jel('li', 'muted');
      const all = jel('button', 'btn sm showall', `Show all ${rows.length}`);
      all.addEventListener('click', () => {
        d.dataset.all = '1';
        d.dataset.touched = '1';
        paint(Infinity);
      });
      li.append(all);
      items.push(li);
    }
    if (more > 0) items.push(jel('li', 'muted', `and ${more} more`));
    ul.replaceChildren(...items);
  };
  paint(cap);
  return ul;
}

/* The lists of a section, drawn from its groups through the filter. A group
   with a label is a section of its own under its heading; one with a `head`
   brings that, as an environment that could not be read brings its reason. */
function drawReportLists(host, groups, q) {
  const out = [];
  for (const g of reportFiltered(groups, q)) {
    let section = null;
    if (g.label) {
      section = jel('section', 'reportgroup');
      section.dataset.group = g.group || '';
      const gh = jel('div', 'rg-head');
      gh.append(jel('h3', '', g.label));
      section.append(gh, jel('p', 'muted', g.desc || ''));
      out.push(section);
    } else if (g.head) {
      out.push(...[].concat(g.head));
    }
    for (const f of g.folds) {
      const d = reportFold(f);
      d.append(...f.draw(f.hits, d, f.more));
      if (section) section.append(d);
      else out.push(d);
    }
  }
  // A section with no fold filters its own table (`also`), which says what is
  // left itself: nothing here was searched, so nothing is "not found".
  if (!out.length && groups.length && String(q || '').trim()) out.push(jel('p', 'runnote', 'Nothing here matches the filter.'));
  host.replaceChildren(...out);
}

/* The filter over a section's lists. Drawing replaces the folds, so the place
   is kept first and put back after: the folds the reader opened or shut or
   showed whole stay so, though a filter hid them for a while (`seen`), and the
   scroll and the "why"s stay where they were. A key typed waits a moment for
   the next, so that a word is searched once; putting a section back as it was
   left (`redraw`) does not wait. */
function reportFilterBox(placeholder, draw) {
  const box = jel('div', 'reportfind');
  const field = jel('label', 'reportbox');
  const input = jel('input', 'reportfilter');
  input.type = 'search';
  input.placeholder = placeholder;
  input.setAttribute('aria-label', placeholder);
  const seen = { open: {}, all: {}, touched: {}, whys: {} };
  const run = () => {
    const view = box.closest('.reports-view');
    const place = view && keepReportPlace(view);
    if (place) {
      // Only what the reader did: a fold's own default opening follows the
      // rows it lists, which a filter changes.
      for (const d of view.querySelectorAll('.reportbody details')) {
        if (!d.dataset.touched) continue;
        const key = reportFoldKey(d);
        seen.open[key] = d.open;
        seen.touched[key] = true;
        if (d.dataset.all) seen.all[key] = true;
      }
      Object.assign(seen.whys, place.whys);
    }
    draw(input.value);
    if (place) restoreReportPlace(view, Object.assign({}, place, { open: seen.open, all: seen.all, touched: seen.touched, whys: seen.whys, filter: undefined }));
  };
  let timer = 0;
  input.addEventListener('input', () => {
    clearTimeout(timer);
    timer = setTimeout(run, 80);
  });
  input.redraw = (value) => {
    clearTimeout(timer);
    input.value = value;
    run();
  };
  field.append(strokeIcon('0 0 16 16', 'reportbox-ico', ['M7 2.25a4.75 4.75 0 1 0 0 9.5 4.75 4.75 0 0 0 0-9.5z', 'M10.5 10.5l3.5 3.5']), input);
  box.append(field);
  return box;
}

/* A section's lists, and a filter above them when there is anything to
   filter. `also` draws what else the filter drives, as the grid of every
   model under Builds by environment, and is what a section without folds
   (Builds by job) filters by. */
function reportLists(body, groups, placeholder, also) {
  const lists = jel('div', 'reportlists');
  const draw = (q) => {
    drawReportLists(lists, groups, q);
    if (also) also(q);
  };
  if (also || reportFiltered(groups, '').some((g) => g.folds.length)) body.append(reportFilterBox(placeholder, draw));
  body.append(lists);
  draw('');
}

/* Draws one section, read again on every showing so a run since the last
   one shows, with the folds and the scroll it was left with: every showing
   but the tour's putting back of a panel it rolled up (0075). Only the
   latest of two quick clicks is drawn. */
async function showReportSection(key) {
  const view = $('#reports-view');
  // Kept before anything replaces it, the placeholder included.
  if (S.reportsDrawn) S.reportsPlace[S.reportsDrawn] = keepReportPlace(view) || S.reportsPlace[S.reportsDrawn];
  S.reportsSection = key;
  paintReportsNav();
  updateStatus();
  const ask = ++S.reportsAsk;
  if (key !== S.reportsDrawn) {
    view.replaceChildren(jel('div', 'compiled-empty', 'Reading…'));
    S.reportsDrawn = '';
  }
  const shown = (S.reports && S.reports[reportsEntry(key)]) || null;
  const again = () => showReportSection(key);
  const drawn = key === 'run' ? await runSection(again) : key === 'warnings' ? await warningsSection(again)
    : key === 'collin' ? await collinSection(again)
      : key === 'macros' ? await macrosSection(again) : key === 'checks' ? await checksSection(again)
        : key === 'builds' ? await buildsSection() : key === 'jobbuilds' ? await jobBuildsSection()
          : key === 'joborder' ? await jobOrderSection(again)
            : await jobsCoverageSection(again);
  if (ask !== S.reportsAsk) return;
  S.reportsShown = shown;
  view.replaceChildren(...drawn);
  S.reportsDrawn = key;
  restoreReportPlace(view, S.reportsPlace[key]);
  if (key === 'collin' && S.collin) S.collinSeen = S.collin.run || 0;
  if (key === 'run' && shown) S.runSeen = shown.at;
  if (key === 'warnings') S.warningsSeen = shown ? shown.unused : 0;
  // The coverage is counted by the index only once the jobs were read, which
  // this section has just done: read again, so the counts it shows are seen.
  // The order of the steps reads the same files and is kept fresh against the
  // same entry, but it is not the coverage: what the button says of the
  // coverage stays unseen (0126).
  if (key === 'jobs' || key === 'joborder') {
    await loadReportsIndex();
    if (ask !== S.reportsAsk) return;
    const jobs = S.reports && S.reports.jobs;
    S.reportsShown = jobs || null;
    if (key === 'jobs' && jobs && typeof jobs.never === 'number') S.jobsSeen = jobs.never + (jobs.unscheduled || 0);
  }
  paintReportsButton();
  paintReportsNav();
}

async function runSection(again) {
  let run;
  try { run = await api.get('/api/reports/run'); }
  catch (e) { return [reportHead({ title: 'Last run', tool: 'dbt', about: '', again }), jel('div', 'compiled-empty', e.message)]; }
  const about = [runAbout(run), run.at ? `written ${cacheAge(run.at)}` : ''].filter(Boolean).join(' · ');
  const body = jel('div', 'reportbody');
  body.append(reportTiles(runTiles(run)));
  for (const n of runNotes(run)) {
    const p = jel('p', 'runnote', n.text);
    if (n.tone) p.dataset.tone = n.tone;
    body.append(p);
  }
  // `cap` lists the first rows only, and a button under them the rest.
  const spec = (title, list, open, tone, cap = Infinity) => ({
    title, tone, rows: list.items, of: list.of, open,
    find: (e) => `${e.name} ${e.id} ${e.message || ''}`,
    draw: (hits, d, more) => [reportList(hits, runEntryRow, d, cap, more)],
  });
  const unknown = run.unknown;
  reportLists(body, [{ folds: [
    spec('Errors and failed tests', run.problems, true, 'bad'),
    spec('Warnings', run.warned, (n) => n <= 20, 'warn'),
    spec('Skipped', run.skipped, (n) => n <= 20, ''),
    spec('Slowest', { items: run.slowest, of: run.slowest.length }, true, '', 5),
    { title: 'Not in the manifest', tone: '', rows: unknown.items, of: unknown.of, open: false, find: (id) => id,
      draw: (hits, d, more) => [reportList(hits, (id) => jel('li', 'rrel', id), d, Infinity, more)] },
  ] }], 'Filter the results');
  return [reportHead({ title: 'Last run', tool: 'dbt', tone: runEndTone(runEndCounts(run.statuses)), about, again }), body];
}

/* One node of the run: its name opens it, then how it ended, then dbt's
   message under it. */
function runEntryRow(e) {
  const li = jel('li', '');
  const known = !!e.file;
  const name = jel(known ? 'a' : 'span', known ? 'filelink' : 'rrel', e.name);
  name.title = e.id;
  if (known) name.addEventListener('click', (ev) => { ev.preventDefault(); openRunEntry(e); });
  li.append(name, jel('span', 'muted', ' · ' + runEntryText(e)));
  if (e.message) li.append(jel('div', 'rmsg', e.message));
  return li;
}

/* A test opens at its line in its YAML (0041); a model with the SQL dbt ran
   for it, which is where an error is read. */
function openRunEntry(e) {
  if (e.kind === 'test') {
    closePanel();
    openTest(e, { pin: true });
    return;
  }
  // A unit test is no node of the graph: its YAML is all there is to open.
  if (e.kind === 'unit_test') {
    closePanel();
    pushJump();
    openFile(e.file);
    revealInTree(e.file);
    return;
  }
  openFromReport(e.id, { dock: e.kind === 'model' || e.kind === 'snapshot' ? 'run' : '' });
}

async function warningsSection(again) {
  const about = 'dbt_project.yml against the manifest, as dbt warns when it parses, without a run';
  let r;
  try { r = await api.get('/api/reports/warnings'); }
  catch (e) { return [reportHead({ title: 'Warnings', tool: 'dbt', about, again }), jel('div', 'compiled-empty', e.message)]; }
  const body = jel('div', 'reportbody');
  body.append(reportTiles(warningsTiles(r)));
  for (const n of warningsNotes(r, S.fresh)) {
    const p = jel('p', 'runnote', n.text);
    if (n.tone) p.dataset.tone = n.tone;
    body.append(p);
  }
  reportLists(body, [{ folds: [{
    title: 'Config paths that apply to no resource', tone: 'warn', rows: r.unused, open: true,
    // What each row shows, its file and line included.
    find: (u) => `dbt_project.yml:${u.line} ${unusedSays(u)}`,
    lever: 'dbt applies a key of dbt_project.yml to every node whose fqn its keys begin, and no fqn '
      + 'begins these: what they set reaches nothing. dbt says so once, as it parses (UnusedResourceConfigPath); this is the '
      + 'same list, read off the manifest.',
    // The reason is the same for most paths: said once over them, and the
    // folders a path shares with the one above it dimmed.
    draw: (hits, d) => unusedByWhy(hits).map((g) => {
      const shared = unusedShared(g.rows);
      const block = jel('div', '');
      block.append(jel('p', 'rlever', g.why),
        reportList(g.rows.map((u, i) => ({ u, shared: shared[i] })), (x) => unusedRow(x.u, x.shared), d));
      return block;
    }),
  }] }], 'Filter the paths');
  return [reportHead({ title: 'Warnings', tool: 'dbt', about, again }), body];
}

/* One path: its line opens dbt_project.yml there, then the path as dbt
   writes it, the keys it shares with the path above (`shared`) dimmed. The
   line is the open text's when the file is open, which an edit not saved yet
   may have moved. */
function unusedRow(u, shared = 0) {
  const li = jel('li', 'unusedrow');
  const at = jel('a', 'filelink', `dbt_project.yml:${u.line}`);
  at.title = 'Open dbt_project.yml at this key';
  at.addEventListener('click', (e) => {
    e.preventDefault();
    const f = S.open.get('dbt_project.yml');
    const found = f && f.doc ? unusedLines(f.doc.getValue(), [u], !f.dirty)[0] : null;
    openProjectAt(found ? found.line : u.line - 1, 0);
  });
  const keys = [u.block].concat(u.chain);
  const path = jel('span', 'rrel', '');
  if (shared) path.append(jel('span', 'rdim', keys.slice(0, shared).join('.') + '.'));
  path.append(keys.slice(shared).join('.'));
  li.append(at, ' ', path);
  return li;
}

async function collinSection(again) {
  const head = (about) => reportHead({ title: "collin's report", tool: 'collin', about, again });
  let view;
  try { view = await api.get('/api/collineage/report'); }
  catch (e) { return [head(''), jel('div', 'compiled-empty', e.message)]; }
  return [head(collinReportAbout(view)), collinReportBody(view)];
}

/* The project's macros no node reaches, grouped by why each may still run,
   and above them, once a card asked, every node reaching one macro (0105).
   Each name opens its file: a node's, or a macro's at its line. */
async function macrosSection(again) {
  const head = (about) => reportHead({ title: 'Macros', tool: 'dbt', about, again });
  let r;
  try { r = await api.get('/api/reports/macros' + (S.macroFocus ? '?focus=' + encodeURIComponent(S.macroFocus) : '')); }
  catch (e) { return [head(''), jel('div', 'compiled-empty', e.message)]; }
  const none = r.unreached.length;
  const about = [`${counted(r.own, 'macro', 'macros')} in ${r.project}`,
    none ? `${none} with no reference found` : 'every one reached by a node'].join(' · ');
  const body = jel('div', 'reportbody');
  const macroLink = (m) => {
    if (!m.file) return jel('span', 'rrel', m.call);
    const a = jel('a', 'filelink', m.call);
    a.title = m.file;
    a.addEventListener('click', (ev) => { ev.preventDefault(); closePanel(); openMacro({ file: m.file, name: m.name }); });
    return a;
  };
  const groups = macroGroups(r.unreached);
  body.append(reportTiles(macrosTiles(r)));
  if (!none) body.append(jel('p', 'runnote', `Every macro of ${r.project} is reached by a node, itself or through other macros.`));
  const folds = [];
  if (r.focus) {
    const f = r.focus;
    const use = macroUseText(f.used, r.adapter);
    const where = jel('p', 'rlever', 'defined in ');
    where.append(macroLink(Object.assign({}, f, { call: f.file || f.call })));
    // The nodes reaching it, then the macros calling it, in one list.
    const rows = f.users.map((u) => ({ u })).concat(f.callers.map((c) => ({ c })));
    folds.push({
      // A macro nothing reaches has no row and still shows its card, so the total is never zero.
      title: f.call, tone: '', badge: use.head, rows, of: f.users_of + f.callers.length || 1, open: true,
      find: (x) => (x.u ? `${x.u.name} ${x.u.id}` : `${x.c.call} ${x.c.name || ''}`),
      draw: (hits, d, more) => [where, ...use.notes.map((n) => jel('p', 'rlever', n)), reportList(hits, (x) => {
        const li = jel('li', '');
        if (x.c) {
          li.append(macroLink(x.c), jel('span', 'muted', ' · macro calling it'));
          return li;
        }
        const u = x.u;
        const name = jel(u.file ? 'a' : 'span', u.file ? 'filelink' : 'rrel', u.name);
        name.title = u.id;
        if (u.file) name.addEventListener('click', (ev) => { ev.preventDefault(); openFromReport(u.id); });
        li.append(name, jel('span', 'muted', ` · ${useKind(u.kind, 1)}${userHow(u)}`));
        return li;
      }, d, Infinity, rows.length ? more : 0)],
    });
  }
  for (const g of groups) {
    folds.push({
      title: g.title, tone: '', open: (len) => len <= 30, rows: g.items,
      lever: g.why === 'dispatch' ? `${g.lever} ${r.adapter || 'an adapter it does not name'}.` : g.lever,
      find: (m) => `${m.name} ${m.call} ${m.extra || ''}`,
      draw: (hits, d) => [reportList(hits, (m) => {
        const li = jel('li', '');
        li.append(macroLink(m));
        if (m.extra) li.append(jel('span', 'muted', ' · ' + m.extra));
        return li;
      }, d)],
    });
  }
  reportLists(body, [{ folds }], 'Filter the macros');
  return [head(about), body];
}

/* The tool's own checks, apart from what dbt would warn of: one fold per
   rule with its count, open while it lists fifty or fewer, rows grouped by
   folder as the job coverage groups its own. A name opens the node with its
   Catalog tab, as the other reports' rows do (0116). */
const CHECKS = [
  { key: 'sources_without_freshness', title: 'Sources without freshness',
    why: 'No freshness threshold dbt counts: neither warn_after nor error_after holds both a count and a period, on the table or inherited from its source.' },
  { key: 'models_without_test', title: 'Models with no test',
    why: 'No generic test declared on the model or one of its columns, no singular test selecting from it and no unit test of it. A test that only points at it, a relationships target, does not count.' },
  { key: 'models_without_description', title: 'Models with no description',
    why: 'An empty description once doc blocks are resolved.' },
  { key: 'sources_not_read', title: 'Sources no node reads',
    why: 'No node has it as a parent, a test of it aside: a model, snapshot, analysis or exposure reading it counts.' },
  { key: 'keys_maybe_null', title: 'Keys with a column not tested not_null',
    why: 'A key is a unique_key, a unique test or a unique_combination_of_columns test, composites included. dbt\'s unique skips nulls and a merge on a null key matches nothing and inserts the row again, so each column of a key wants an enabled not_null test with no where. A model that appends or overwrites ignores its unique_key, so one only the config declares is not looked at. A row opens the first column left.' },
  { key: 'unique_keys_untested', title: 'Incremental unique_key no uniqueness test checks',
    why: 'No unique test on the column, nor unique_combination_of_columns on the same columns in any order, so a duplicate the merge lets in is not caught. A unique_key written as an expression is checked only by a unique test written on the same text. A model that appends or overwrites ignores its unique_key and is not listed.' },
  { key: 'models_without_key', title: 'Models with no key test',
    why: 'No enabled unique test on a column and no unique_combination_of_columns test, a test with a where aside. A unique_key alone does not count: nothing checks it.' },
];

async function checksSection(again) {
  const about = "this tool's own rules, read off the manifest: dbt warns of none of them";
  const head = () => reportHead({ title: 'Checks', tool: 'dbt', about, again });
  let r;
  try { r = await api.get('/api/reports/checks'); }
  catch (e) { return [head(), jel('div', 'compiled-empty', e.message)]; }
  const body = jel('div', 'reportbody');
  const tiles = [];
  const folds = [];
  for (const c of CHECKS) {
    // `rows` is what the server sent, at most its cap of the `total` found.
    const { total = 0, rows = [] } = r[c.key] || {};
    if (!total) continue;
    tiles.push({ label: c.title, value: String(total), sub: '', tone: '' });
    folds.push({
      title: c.title, tone: '', lever: c.why, rows, of: total, open: (n) => n <= 50,
      find: (row) => `${row.name} ${row.id} ${row.folder || ''} ${checkDetail(row)}`,
      draw: (hits, d, more) => checkFoldList(hits, d, more, checkRow, checkSays, rows),
    });
  }
  body.append(reportTiles(tiles), jel('p', 'runnote', "Only the project's own enabled models and sources are looked at, never an installed package's."));
  if (!folds.length) body.append(jel('p', 'runnote', 'Nothing to list: every check comes out clean.'));
  reportLists(body, [{ folds }], 'Filter the models and sources');
  return [head(), body];
}

/* How many rows of a check are drawn before Show all. */
const CHECK_SHOWN = 100;

/* A fold of rows by folder: the first CHECK_SHOWN, a button for the rest, and
   how many the server held back. A list of thousands draws its first rows, as
   Slowest does: the folds that are closed would draw them all the same. */
function checkFoldList(hits, d, more, row = checkRow, says = checkSays, all = hits) {
  const groups = jel('div', '');
  const draw = (shown) => groups.replaceChildren(...checkGroups(hits, shown, d.open, row, says, all));
  draw(CHECK_SHOWN);
  const out = [groups];
  const rest = hits.length - CHECK_SHOWN;
  if (rest > 0 || more > 0) {
    const tail = jel('ul', 'rentries');
    if (rest > 0) {
      const li = jel('li', 'muted');
      const all = jel('button', 'btn sm showall', `Show all ${hits.length}`);
      all.addEventListener('click', () => {
        d.dataset.all = '1';
        d.dataset.touched = '1';
        draw(hits.length);
        li.remove();
      });
      li.append(all);
      tail.append(li);
    }
    if (more > 0) tail.append(jel('li', 'muted', `and ${more} more`));
    out.push(tail);
  }
  return out;
}

/* The first `shown` of a check's rows, by folder as the job coverage groups its
   own. The folders are made of every row the server sent, so a folder's count
   is the whole of it, drawn or not. `row` draws one: a check's by default, the
   coverage's for the models no job runs; `says` is what it adds to the name,
   and a list whose rows add nothing is drawn as chips. A list is chips only
   when none of its rows says more than a name in the fold's unfiltered rows
   (`all`), so that a filter or Show all never turns lines into chips, and none
   says more where it is drawn now: a filter that gathers rows of two folders
   under the folder above gives them back their path, as lines. */
function checkGroups(rows, shown, open, row = checkRow, says = checkSays, all = rows) {
  const out = [];
  const drawn = new Set(rows.slice(0, shown).map((r) => r.id));
  // The rows of every list of the unfiltered fold that has one saying more than a name.
  const lines = new Set();
  for (const g of jobsCoverageGroups(all)) {
    const bare = g.rows.length === 1 || !g.folder;
    if (!reportNamesOnly(g.rows.map((r) => says(r, bare ? r.folder : r.rest)))) g.rows.forEach((r) => lines.add(r.id));
  }
  const chips = (list, bare) => !list.some((r) => lines.has(r.id) || says(r, bare ? r.folder : r.rest));
  for (const g of jobsCoverageGroups(rows)) {
    const here = g.rows.filter((r) => drawn.has(r.id));
    if (!here.length) continue;
    // A folder of one is no level to unfold: the row is listed bare.
    if (g.rows.length === 1 || !g.folder) {
      const names = chips(g.rows, true);
      const ul = jel('ul', 'rentries' + (names ? ' models' : ''));
      for (const r of here) ul.append(row(r, r.folder, names));
      out.push(ul);
      continue;
    }
    const folder = jel('details', 'checkfolder');
    folder.open = open;
    folder.append(reportFolderSummary(`${g.folder} (${g.rows.length})`));
    const names = chips(g.rows, false);
    const ul = jel('ul', 'rentries' + (names ? ' models' : ''));
    for (const r of here) ul.append(row(r, r.rest, names));
    folder.append(ul);
    out.push(folder);
  }
  return out;
}

/* What a check's row adds after the name: its detail, else the folder it sits in. */
function checkSays(row, path) {
  return checkDetail(row) || path || '';
}

function checkRow(row, path, chip = false) {
  const li = jel('li', '');
  const title = row.file ? `${row.id} · ${row.file}` : row.id;
  // A key row opens the Columns tab on the column it left untested.
  const open = () => openReportNode(row.id, row.column);
  if (chip) {
    li.append(reportModelChip(row.name, reportLook(row.materialized), title, open));
    return li;
  }
  const name = jel('a', 'filelink', row.name);
  name.title = title;
  name.addEventListener('click', (ev) => { ev.preventDefault(); open(); });
  li.append(name);
  const detail = checkDetail(row);
  if (detail) li.append(jel('span', '', ': ' + detail));
  if (path) li.append(jel('span', 'muted', ' · ' + path));
  return li;
}

/* A macro card's first line: the Reports panel, on the nodes reaching it. */
function openMacroUse(id) {
  S.macroFocus = id;
  // The new focus is drawn at the top: the place kept from browsing the list
  // before would leave it out of view.
  if (S.reportsDrawn === 'macros') S.reportsDrawn = '';
  delete S.reportsPlace.macros;
  openReports('macros');
}

async function jobsCoverageSection(again) {
  const sources = jel('button', 'btn sm', 'Sources…');
  sources.title = 'Where the jobs are read from, and how';
  sources.addEventListener('click', openJobSources);
  const head = reportHead({ title: 'Job coverage', tool: 'jobs', about: 'every job read, against every model of the project',
    again, extra: [sources] });
  // The job files are looked at as the section opens, never on a click in it
  // (0063).
  let cov;
  try { cov = await jobsLookGet('/api/jobs/coverage?look=true'); }
  catch (e) { return [head, jel('div', 'compiled-empty', e.message)]; }
  forgetCatalogJobs();
  const body = jel('div', 'reportbody');
  renderCoverage(body, cov);
  return [head, body];
}

/* Job order (0126): the steps of jobs that start on their own which build a
   model whose dbt parent another job's step builds, with no task, sensor or
   start of the files putting that step after it. The answer is the command
   line's --job-order, drawn. The lines it says are pure functions, and
   web/tests/joborder.js slices them and the drawing, from jobOrderLine to
   jobOrderSection. */

/* The first line: how many pairs, and of which kind. With none, only what
   holds is said, as the command line says it: a step not looked at waits for
   nothing known. */
function jobOrderLine(a) {
  const c = a.counts;
  if (!a.pairs.length) {
    // A source that could not be walked may have held the pair, and a step it
    // held was not looked at: nothing else is claimed.
    if (a.not_read) return 'No pair in what was read';
    if (a.unresolved && a.unresolved.length) return 'No pair among the steps resolved';
    if (!a.checked) return 'No step of a job that starts on its own builds a node';
    return 'Every step waits for the steps that build its parents';
  }
  return `${jobsPlural(a.pairs.length, 'pair')}: ${c.none} nothing orders them, ${c.clock} only the clock, ${c.reversed} the other way`;
}

/* The groups there are, in the order the answer lists them, each with the
   pairs of it and whether it is open. */
function jobOrderGroups(a) {
  const kinds = [
    { key: 'none', title: 'Nothing orders them',
      hint: 'No task, sensor or start of the job files puts the first step after the second' },
    { key: 'clock', title: 'Only the clock orders them',
      hint: 'The crons differ, so the clock may order them; nothing in the files does' },
    { key: 'reversed', title: 'Ordered the other way',
      hint: 'The files order them, the other way round' },
  ];
  return kinds.map((k) => Object.assign({ pairs: a.pairs.filter((p) => p.group === k.key) }, k))
    .filter((g) => g.pairs.length)
    .map((g) => Object.assign(g, { open: g.pairs.length <= 50 }));
}

/* A step as the Jobs tab names it: its job and itself. */
function jobOrderSide(side) {
  return `${jobsJobLabel({ kind: side.kind, name: side.job })} › ${side.label}`;
}

function jobOrderSensor(id) {
  return id ? 'sensor ' + id : 'a sensor';
}

/* Which schedule is whose: the step's, then those of the steps it should wait
   for, each under its job's name when there are several. */
function jobOrderSchedules(p) {
  const many = p.waits_for.length > 1;
  const waits = p.waits_for.map((s) => (many ? `${s.job}: ` : '') + s.schedule).join(', ');
  return `this step: ${p.step.schedule}  ·  waits for: ${waits}`;
}

/* What a pair has to say beyond its edges, a line each. */
function jobOrderNotes(p) {
  return (p.later || []).map((s) => `${jobOrderSide(s)} runs after it`)
    .concat((p.idle_sensors || []).map((s) =>
      `Note: ${jobOrderSensor(s.id)} of this DAG waits for ${s.waits.join(', ')}; this task does not depend on it`))
    .concat((p.group_sensors || []).map((s) =>
      `Note: ${s.task} depends on ${jobOrderSensor(s.id)}, which waits for ${s.waits.join(', ')}, whose tasks are not read`));
}

/* The sources that could not be read, as the command line words them. */
function jobOrderUnread(u) {
  const which = u.sources === u.of ? (u.of === 1 ? 'the source' : `all ${u.of} sources`) : `${u.sources} of ${u.of} sources`;
  return `${which} (${u.reason})`;
}

/* What the answer leaves out, a line each: the DAGs that loop, the jobs
   nothing starts, the sources not read. A job is named with its source when
   two sources hold one of the name. */
function jobOrderCaveats(a) {
  const named = (list, l) => (list.filter((o) => o.job === l.job).length > 1 ? `${l.source}: ${l.job}` : l.job);
  const out = (a.cyclic || []).map((c) => ({ warn: true,
    text: `DAG ${named(a.cyclic, c)} has a depends_on cycle, which Airflow does not load: left out` }));
  const left = a.left_out || [];
  if (left.length) {
    const names = left.map((l) => named(left, l));
    const more = names.length > 5 ? `, +${names.length - 5} more` : '';
    out.push({ warn: false,
      text: `${left.length} ${left.length === 1 ? 'job' : 'jobs'} nothing starts left out: ${names.slice(0, 5).join(', ')}${more}` });
  }
  if (a.not_read) out.push({ warn: true, text: 'Not read: ' + jobOrderUnread(a.not_read) });
  return out;
}

/* The figures over the order: the steps looked at, the pairs of each kind and
   the steps not resolved. None while there is no pair and nothing unresolved:
   the line under says what holds. */
function jobOrderTiles(a) {
  const lost = (a.unresolved || []).length;
  if (!a.pairs.length && !lost) return [];
  const tiles = [{ label: 'Steps looked at', value: String(a.checked), sub: 'of jobs that start on their own, building a node', tone: '' }];
  for (const g of jobOrderGroups(a)) {
    tiles.push({ label: g.title, value: String(g.pairs.length), sub: 'pairs of steps', tone: g.key === 'none' || g.key === 'reversed' ? 'warn' : '' });
  }
  if (lost) tiles.push({ label: 'Steps not resolved', value: String(lost), sub: 'could hide more pairs', tone: '' });
  return tiles;
}

/* The steps a step should wait for: by their own label when they are in its
   job, which its fold already names, else with their job. */
function jobOrderTargets(p) {
  return p.waits_for.map((s) => (s.source === p.step.source && s.job === p.step.job ? s.label : jobOrderSide(s)));
}

/* The schedules of a fold's pairs when they all say the same, to say them once. */
function jobOrderShared(pairs) {
  if (!pairs.length) return '';
  const first = jobOrderSchedules(pairs[0]);
  return pairs.every((p) => jobOrderSchedules(p) === first) ? first : '';
}

/* A pair's edges by the model that reads, in the order they were found: one
   model often reads several parents of the other step. */
function jobOrderEdgeRows(edges) {
  const rows = new Map();
  for (const e of edges) {
    if (!rows.has(e.node)) rows.set(e.node, { node: e.node, node_name: e.node_name, edges: [] });
    rows.get(e.node).edges.push(e);
  }
  return [...rows.values()];
}

/* Where a step is written, outside the project and so copied rather than
   opened. */
function jobsFileButton(source, file, line, short = false) {
  // The Jobs tab's card names the source in the tooltip, the reports in the text.
  const where = jel('button', 'jobfile', short ? `${file}:${line}` : `${source} · ${file}:${line}`);
  where.type = 'button';
  where.title = (short ? `From ${source}. ` : '') + 'Outside the project, so it does not open here. Click to copy where it is.';
  where.addEventListener('click', () => copyText(`${file}:${line}`));
  return where;
}

/* What the answer says before its pairs, in the order it is read: the figures,
   the line, then what was left out, the warnings first in the colour of one. */
function renderJobOrder(body, a) {
  if (a.sources_refused) return jobsRefusedFile(body, a.sources_refused);
  if (!a.configured) return jobsNoSource(body);
  const out = [reportTiles(jobOrderTiles(a)), jel('p', 'runnote', jobOrderLine(a))];
  for (const c of jobOrderCaveats(a)) {
    const note = jel('p', 'runnote', c.text);
    if (c.warn) note.dataset.tone = 'warn';
    out.push(note);
  }
  const folds = jobOrderGroups(a).map((g) => {
    // What a filter is held against, made once: a keystroke would otherwise
    // join the names of every edge of every pair again.
    const text = new Map(g.pairs.map((p) => [p, [jobOrderSide(p.step), ...p.waits_for.map(jobOrderSide),
      ...p.edges.map((e) => [e.node_name, e.parent_name, ...(e.through || []).map((t) => t.name)].join(' '))].join(' ')]));
    return { title: g.title, tone: g.key === 'none' || g.key === 'reversed' ? 'warn' : '', lever: g.hint, rows: g.pairs, open: (n) => n <= 50,
      find: (p) => text.get(p), draw: (hits, d) => jobOrderFoldList(hits, d) };
  });
  // The steps not resolved are listed as the coverage lists its own.
  if (a.unresolved && a.unresolved.length) {
    folds.push(jobsStepList('Steps not resolved, which could hide more pairs',
      // An Airflow task by its id, as the coverage names it; a dbt Cloud step
      // keeps its place, which it has no name for.
      a.unresolved.map((u) => Object.assign({}, u, { name: u.label.replace(/^task /, '') }))));
  }
  body.replaceChildren(...out);
  reportLists(body, [{ folds }], 'Filter the steps and models');
}

/* A model of an edge, opened in the editor with the Jobs tab, which lists the
   steps that build it. */
function jobOrderModel(id, name) {
  const link = jel('button', 'jobs-model', name);
  link.title = `Open ${name}, with the Jobs tab listing its jobs`;
  link.addEventListener('click', () => openFromReport(id, { dock: 'jobs' }));
  return link;
}

/* One model and what it reads from the other step's: a single parent as
   "x reads a through t", several as "x reads a, b (through t)", the views and
   ephemerals between them opening too, since one is often what to look at. */
function jobOrderEdge(row) {
  const line = jel('div', 'joblink');
  line.append(jobOrderModel(row.node, row.node_name), ' reads ');
  row.edges.forEach((e, i) => line.append(...(i ? [', '] : []), jobOrderModel(e.parent, e.parent_name)));
  const through = [];
  for (const t of row.edges.flatMap((e) => e.through || [])) if (!through.some((x) => x.id === t.id)) through.push(t);
  if (!through.length) return line;
  line.append(row.edges.length > 1 ? ' (through ' : ' through ');
  through.forEach((t, i) => line.append(...(i ? [', '] : []), jobOrderModel(t.id, t.name)));
  if (row.edges.length > 1) line.append(')');
  return line;
}

/* One pair: the step, the steps it should wait for and where the step is
   written, on one line, then the clocks of both unless its fold says them
   once (`shared`), what else the files say, and the models it reads from them,
   a line each model, the first ten with a button for the rest (the JSON has
   them all). Inside its job's fold (`inFold`) the step is its task alone. */
function jobOrderPair(p, { inFold = false, shared = false } = {}) {
  const li = jel('li', '');
  // The file is pinned right on the head's own line, not the clocks': inside
  // a fold that draws no clocks, that line held only the file and read as a
  // blank one with a path far off to the right.
  const head = jel('div', 'rpairhead');
  const said = jel('div', 'rpairtext');
  said.append(jel('span', 'rstep', inFold ? p.step.label : jobOrderSide(p.step)),
    p.waits_for.length === 1 ? ' should wait for ' : ' should wait for one of ', jobOrderTargets(p).join(', '));
  head.append(said, jobsFileButton(p.step.source, p.step.file, p.step.line));
  li.append(head);
  if (!shared) {
    const clocks = jel('div', 'rline');
    clocks.append(jel('span', 'rsched muted', jobOrderSchedules(p)));
    li.append(clocks);
  }
  for (const note of jobOrderNotes(p)) li.append(jel('div', 'joblink', note));
  const rows = jobOrderEdgeRows(p.edges);
  const edges = jel('div', '');
  for (const row of rows.slice(0, 10)) edges.append(jobOrderEdge(row));
  if (rows.length > 10) {
    const more = jel('button', 'btn sm', `+${rows.length - 10} more`);
    more.addEventListener('click', () => {
      more.remove();
      for (const row of rows.slice(10)) edges.append(jobOrderEdge(row));
    });
    edges.append(more);
  }
  li.append(edges);
  return li;
}

/* The pairs of a group by the DAG or job the step is in, so that its name and
   its clocks are said once over its steps. A job with a single pair is listed
   bare, with its whole name. */
function jobOrderFolders(hits, open, shown = Infinity) {
  const drawn = new Set(hits.slice(0, shown));
  const byJob = new Map();
  for (const p of hits) {
    const key = `${p.step.source}\n${p.step.job}`;
    if (!byJob.has(key)) byJob.set(key, []);
    byJob.get(key).push(p);
  }
  const out = [];
  for (const pairs of byJob.values()) {
    // A job's count is the whole of its pairs, drawn or not, as a folder of a
    // check's rows says it.
    const first = pairs.filter((p) => drawn.has(p));
    if (!first.length) continue;
    if (pairs.length === 1) {
      const ul = jel('ul', 'rentries');
      ul.append(jobOrderPair(pairs[0]));
      out.push(ul);
      continue;
    }
    const shared = jobOrderShared(pairs);
    const folder = jel('details', 'checkfolder');
    folder.open = open;
    folder.append(reportFolderSummary(`${jobsJobLabel({ kind: pairs[0].step.kind, name: pairs[0].step.job })} (${pairs.length})`));
    if (shared) folder.append(jel('p', 'rline', shared));
    const ul = jel('ul', 'rentries');
    for (const p of first) ul.append(jobOrderPair(p, { inFold: true, shared: !!shared }));
    folder.append(ul);
    out.push(folder);
  }
  return out;
}

/* The pairs of a fold: the first CHECK_SHOWN, a button for the rest, so that a
   filter run over thousands of pairs draws a few hundred elements, not all. */
function jobOrderFoldList(hits, d) {
  const box = jel('div', '');
  const paint = (n) => box.replaceChildren(...jobOrderFolders(hits, d.open, n));
  paint(CHECK_SHOWN);
  const out = [box];
  if (hits.length > CHECK_SHOWN) {
    const tail = jel('ul', 'rentries');
    const li = jel('li', 'muted');
    const all = jel('button', 'btn sm showall', `Show all ${hits.length}`);
    all.addEventListener('click', () => {
      d.dataset.all = '1';
      d.dataset.touched = '1';
      paint(Infinity);
      li.remove();
    });
    li.append(all);
    tail.append(li);
    out.push(tail);
  }
  return out;
}

async function jobOrderSection(again) {
  const head = reportHead({ title: 'Job order', tool: 'jobs', about: 'what each step builds, against what the job files order before it', again });
  // The job files are looked at as the section opens, never on a click in it
  // (0063).
  let order;
  try { order = await jobsLookGet('/api/jobs/order?look=true'); }
  catch (e) { return [head, jel('div', 'compiled-empty', e.message)]; }
  // The look may have read the files again. Nothing else is drawn again for
  // it: the section is read again on every showing.
  forgetCatalogJobs();
  S.reportsCounts.joborder = (order.pairs || []).length;
  const body = jel('div', 'reportbody');
  renderJobOrder(body, order);
  return [head, body];
}

/* A node named in a report, opened in the editor with the dock tab that says
   the most about it. The panel rolls up first: the file is what was asked
   for, and focusNode opens none for a node without one (0064). */
async function openFromReport(id, { dock = '', column = '' } = {}) {
  // The Catalog is about to draw this node: the one it holds asks for no jobs
  // as the panel rolls up or the tab comes forward.
  const stale = $('#catalog .cat-jobs');
  if (stale) stale.dataset.asked = '1';
  closePanel();
  pushJump();
  if (dock === 'catalog') {
    S.catTab = 'columns';
    highlightColumn(column || null, id);
    showDock('catalog');
  }
  await focusNode(id, { open: true });
  // Once the focus has moved, so the tab reads the node once, and without
  // looking at the job files again: the section looked as it opened (0063).
  if (dock === 'jobs' && S.dock !== 'jobs') showDock('jobs', { look: false });
  else if (dock && dock !== 'catalog' && dock !== 'jobs' && S.dock !== dock) showDock(dock);
}

// --------------------------------------------------------------- settings --
/* Every setting, in one panel rolled down from the sliders in the top bar, a
   section at a time, as the reports are (0100): the project's profile,
   environments and Python, the column lineage, Snowflake, the orchestration,
   the updates, the theme, and help. A section is one column of rows, a
   setting's name and why on the left and its control on the right (0163). The
   venv and update pills open their section, the env pill its menu (0142). A
   section is drawn from what the page knows, and drawn again when that
   changes, but a form being filled stays as it was left, through another
   section and back, until the panel rolls up. settingsSections and
   settingsSection are what web/tests/settings.js slices. */

/* The sections, in the rail's order, from what `c` says the page knows: what
   each row says beside its name, the column lineage on screen, Snowflake on
   or off, how many job sources there are, a newer release, and the profile's
   triangle when it is missing. */
function settingsSections(c) {
  const sources = c.sources;
  return [
    { key: 'project', label: 'Project', warn: c.profile || '',
      title: 'The dbt profile, the .env files the Catalog resolves locations with, and the Python the terminal runs.' },
    { key: 'columns', label: 'Column lineage', tool: c.cllTool || '', hint: c.cll || '',
      title: 'Where the edges between columns come from. A click on a column in Catalog > Columns follows it from model to model.' },
    { key: 'snowflake', label: 'Snowflake', tool: 'snowflake', hint: c.snowflake ? 'on' : 'off',
      title: 'Column lineage from Snowflake, the Query history tab, Snowsight links and Clone into my schema, for this project.' },
    { key: 'jobs', label: 'Orchestration', tool: 'jobs',
      hint: typeof sources === 'number' ? `${sources} source${sources === 1 ? '' : 's'}` : '',
      title: 'Where the Airflow DAGs or dbt Cloud jobs that run each model are read from. The Jobs tab and the job reports use them.' },
    // The hint is the newest version, in the accent, or the restart that is left.
    { key: 'updates', label: 'Updates', hint: c.update || '', news: !!c.update,
      title: 'Which build serves this page, a newer release, and how to install it.' },
    { key: 'theme', label: 'Theme', hint: c.theme || '',
      title: 'The colours of the whole app, the canvas included. Each keeps the same meaning colours: materializations, tests, ok, warn and bad.' },
    { key: 'help', label: 'Help and tour',
      title: 'The tour, every shortcut, and dbt-edith on GitHub.' },
  ];
}

/* The section to open on: the one asked for, else the one last shown, else
   the project. */
function settingsSection(asked, last) {
  const keys = settingsSections({}).map((sec) => sec.key);
  if (keys.includes(asked)) return asked;
  return keys.includes(last) ? last : 'project';
}

/* What the rail says, from the page's state. */
function settingsNow() {
  const pick = lineagePickLabel(S.meta, S.cllTool, sidecarOn(), S.sidecar, S.collin);
  const o = updateOffer(S.update);
  return {
    profile: profileWarning(S.profiles),
    cllTool: pick.tool,
    cll: pick.tool ? pick.name : 'none',
    snowflake: !!(S.features && S.features.snowflake),
    update: o ? (o.installed ? 'restart' : S.update.latest) : '',
    // From the Reports index, which reads no job file: an index without the
    // jobs entry has no source (0063, 0066).
    sources: S.reports ? (S.reports.jobs ? S.reports.jobs.sources : 0) : null,
    theme: THEMES.find((t) => t.id === themeNow()).name,
  };
}

/* Rolls the settings down on the section asked for, else the one last shown.
   `add` opens Orchestration on a new source, its picker open, in place of a
   form left there. */
function openSettings(section, { add = false } = {}) {
  const key = settingsSection(section, S.settingsSection);
  if (!panelOpen('settings')) S.settingsFrom = S.panel;
  openPanel('settings');
  showSettingsSection(key, { add });
}

/* A glyph per section, as the menus they replace drew them. */
function settingsIcon(sec) {
  const wrap = jel('span', 'seticon');
  if ('tool' in sec) wrap.dataset.tool = sec.tool;
  // A tool's glyph takes its colour, the others stay quiet.
  if (sec.tool) wrap.classList.add('tinted');
  const draw = { snowflake: snowflakeIcon, jobs: jobsIcon }[sec.key];
  if (sec.key === 'theme') {
    wrap.append(themeGlyph());
    return wrap;
  }
  if (draw) wrap.append(draw());
  else if (sec.key === 'project') wrap.append(strokeIcon('0 0 16 16', 'setglyph', ['M2 4.75L8 2.25l6 2.5-6 2.5z', 'M2 4.75v6.5l6 2.5 6-2.5v-6.5M8 7.25v6.5']));
  else if (sec.key === 'columns') wrap.append(jel('span', 'tooldot'));
  else if (sec.key === 'updates') wrap.append(strokeIcon('0 0 16 16', 'setglyph', ['M8 2.5v8M4.75 7.25L8 10.5l3.25-3.25M2.5 13.5h11']));
  else wrap.append(strokeIcon('0 0 16 16', 'setglyph', ['M8 1.8a6.2 6.2 0 1 1 0 12.4a6.2 6.2 0 1 1 0-12.4z',
    'M6.1 6.2a1.9 1.9 0 1 1 2.7 1.7c-.5.25-.8.6-.8 1.1v.6', 'M8 11.3v.2']));
  return wrap;
}

function paintSettingsNav(nav = $('#settings-nav')) {
  const head = jel('div', 'setnav-head', 'Settings');
  nav.replaceChildren(head, ...settingsSections(settingsNow()).map((sec) => {
    const row = jel('button', 'reports-navrow setnavrow');
    row.type = 'button';
    row.dataset.key = sec.key;
    row.title = sec.title;
    if (sec.key === S.settingsSection) row.setAttribute('aria-current', 'true');
    row.append(settingsIcon(sec), jel('span', '', sec.label));
    if (sec.warn) {
      const dot = jel('span', 'setwarn');
      dot.title = sec.warn;
      row.append(dot);
    } else if (sec.hint) {
      row.append(jel('span', sec.news ? 'sethint new' : 'sethint', sec.hint));
    }
    row.addEventListener('click', () => showSettingsSection(sec.key));
    return row;
  }));
}

/* The head of a section: its name, and in a line what it holds. A tool's
   carries that tool's colour as a bar before the name (0148). */
function setHead(sec) {
  const head = jel('header', 'sethead');
  if ('tool' in sec) head.dataset.tool = sec.tool;
  head.append(jel('h2', '', sec.label), jel('p', '', sec.title));
  if (sec.key === 'jobs') {
    head.append(jel('p', '', 'Read from their YAML wherever it lives, often in another repository, for the Jobs tab and the '
      + 'job coverage in Reports. Folders or files holding your jobs, relative to the project or absolute. An Airflow '
      + 'key is a dotted path: pipeline.name is the key name inside pipeline. Leave one empty for the shape shown.'));
  }
  return head;
}

/* Draws one section, or puts back the one kept with its form as it was left. */
function showSettingsSection(key, { add = false } = {}) {
  S.settingsSection = key;
  updateStatus();
  redrawIfChanged($('#settings-nav'), paintSettingsNav);
  if (add) delete S.settingsKept.jobs;
  const sec = settingsSections(settingsNow()).find((x) => x.key === key);
  let body = S.settingsKept[key];
  if (!body) {
    body = jel('div', 'setinner');
    body.append(setHead(sec));
    drawSettingsSection(key, body, { add });
    if (key === 'project' || key === 'jobs') S.settingsKept[key] = body;
  }
  const view = $('#settings-view');
  view.replaceChildren(body);
  view.scrollTop = 0;
  paintSettingsLive();
  // Read again each time, kept or not, for a venv made in the terminal
  // since: the venv pill read it on every click.
  if (key === 'project') api.get('/api/venv').then((v) => { S.venv = v; paintVenv(); }).catch(() => {});
}

/* A card of rows under an optional head, with a note beside the head. A live
   one is drawn again by paintSettingsLive whenever what it shows changes. */
function setGroup(body, head = '', note = '', live = '') {
  const group = jel('section', 'sgroup');
  if (live) group.dataset.live = live;
  setGroupHead(group, head, note);
  body.append(group);
  return group;
}

function setGroupHead(group, head, note = '') {
  if (!head) return;
  const h = jel('div', 'sghead', head);
  if (note) h.append(jel('span', 'sgnote', note));
  group.append(h);
}

/* One row: `name` and `about` on the left, the control on the right. A name
   is a string or the nodes that make it up (a tag after it); `about` is a
   string, or paragraphs, each a string or an array of strings and nodes. A
   `wide` row puts the control under the text across both columns, for what is
   a table or a form. Returns the row and its control box. */
function buildRow(name, about, { wide = false } = {}) {
  const row = jel('div', wide ? 'srow wide' : 'srow');
  const left = jel('div', 'sl');
  const st = jel('div', 'st');
  st.append(...[].concat(name).map((n) => (typeof n === 'string' ? document.createTextNode(n) : n)));
  left.append(st);
  if (about) {
    const sd = jel('div', 'sd');
    for (const para of [].concat(about)) {
      const p = jel('p', '');
      p.append(...[].concat(para).map((n) => (typeof n === 'string' ? document.createTextNode(n) : n)));
      sd.append(p);
    }
    left.append(sd);
  }
  const sc = jel('div', 'sc');
  row.append(left, sc);
  return { row, sc };
}

/* A row added to `group`; returns its control box, which a live row marks
   with its data-live. */
function setRow(group, name, about, opts) {
  const { row, sc } = buildRow(name, about, opts);
  group.append(row);
  return sc;
}

/* A state as the shapes rule draws it: a pictogram (ok, warn, none) and a
   word, never a coloured dot. */
function okLine(tone, text) {
  const line = jel('span', 'okline');
  line.dataset.tone = tone;
  line.append(jel('span', 'dot'), jel('span', '', text));
  return line;
}

function drawSettingsSection(key, body, { add }) {
  switch (key) {
    case 'project': {
      const dbt = setGroup(body, 'dbt');
      setRow(dbt, 'Profile', ['Who dbt connects as, and how, read by every dbt command in the terminal.',
        'Its passwords and keys never reach this page: the editor shows a placeholder in their place, and leaving it keeps the value.'])
        .dataset.live = 'profile';
      drawSetEnvs(setGroup(body));
      const py = setGroup(body, 'Python');
      setRow(py, 'Interpreter', 'The Python the terminal runs dbt with.').dataset.live = 'python';
      break;
    }
    case 'columns': {
      const group = setGroup(body);
      const now = setRow(group, 'On screen', 'What the canvas draws now.');
      now.classList.add('cllnow');
      now.dataset.live = 'cllnow';
      const radios = jel('div', 'radios');
      radios.dataset.live = 'columns';
      setRow(group, 'Where it comes from', 'One source at a time.').append(radios);
      // Asked again, so a cache written since the page loaded is offered too.
      api.get('/api/meta').then(applyLineage).catch(() => {});
      break;
    }
    case 'snowflake': {
      const box = jel('div', 'setlive');
      box.dataset.live = 'snowflake';
      body.append(box);
      break;
    }
    case 'jobs': {
      const holder = jel('div', 'setlive');
      body.append(holder);
      jobSourcesForm(holder, { add });
      break;
    }
    case 'updates': {
      const box = jel('div', 'setlive');
      box.dataset.live = 'updates';
      body.append(box);
      freshenUpdate();
      break;
    }
    case 'theme': {
      const cards = jel('div', 'tcards');
      cards.dataset.live = 'themecards';
      body.append(cards);
      setGroup(body, '', '', 'themefollow');
      setGroup(body, '', '', 'themehw');
      break;
    }
    case 'help':
      drawSetHelp(body);
      break;
  }
}

function paintSettingsBlock(box) {
  switch (box.dataset.live) {
    case 'profile': return paintSetProfile(box);
    case 'envpick': return paintSetEnvPick(box);
    case 'python': return paintSetPython(box);
    case 'cllnow': return fillSourceLabel(box, lineagePickLabel(S.meta, S.cllTool, sidecarOn(), S.sidecar, S.collin), { chip: true });
    case 'columns':
      box.replaceChildren();
      box.setAttribute('role', 'radiogroup');
      box.setAttribute('aria-label', 'Column lineage source');
      fillSourceMenu(box, () => {}, { cards: true });
      return rovingCards(box);
    case 'snowflake': return paintSetSnowflake(box);
    case 'themecards': return paintThemeCards(box);
    case 'themefollow': return paintThemeFollow(box);
    case 'themehw': return paintThemeHalloween(box);
    case 'updates': return paintSetUpdates(box);
  }
}

/* Which of the Column lineage cards are tab stops. `cards` say whether each is
   `checked` and whether it is `left` out of the arrow steps (greyed, or the one
   that only types the install). A card left out keeps tabindex 0, since Tab is
   the only way to it, the install card being the only place that types collin's
   install; among the others the checked one is the stop, else the first. Pure,
   for web/tests/settings.js. */
function cardTabStops(cards) {
  const steps = cards.map((c, i) => (c.left ? -1 : i)).filter((i) => i >= 0);
  const stop = steps.find((i) => cards[i].checked);
  const first = stop === undefined ? steps[0] : stop;
  return cards.map((c, i) => (c.left || i === first ? 0 : -1));
}

/* The tool cards of Column lineage as radios, for the keyboard: the arrows move
   the focus over the cards and pick nothing, since a pick regenerates collin's
   cache or starts Snowflake's script on the server. Enter or Space, the
   button's own click, picks. */
function rovingCards(box) {
  const cards = [...box.querySelectorAll('.radio')];
  const left = (c) => c.getAttribute('aria-disabled') === 'true' || !!c.dataset.install;
  cardTabStops(cards.map((c) => ({ checked: c.getAttribute('aria-checked') === 'true', left: left(c) })))
    .forEach((tab, i) => { cards[i].tabIndex = tab; });
  const steps = cards.filter((c) => !left(c));
  box.onkeydown = (e) => {
    const at = steps.indexOf(document.activeElement);
    const to = { ArrowRight: at + 1, ArrowDown: at + 1, ArrowLeft: at - 1, ArrowUp: at - 1, Home: 0, End: steps.length - 1 }[e.key];
    if (at < 0 || to === undefined) return;
    e.preventDefault();
    steps[(to + steps.length) % steps.length].focus();
  };
}

/* Draws `box` again with `paint`, unless it would come out the same: then
   what is there stays, with its listeners, its tooltip, and a click half
   made on it, which a poll answering every second and a half would
   otherwise lose. The box's own attributes count, a block's tooltip being
   one. Drawn again, the focus goes back to the control with the same key. */
function redrawIfChanged(box, paint) {
  const probe = box.cloneNode(false);
  paint(probe);
  if (probe.outerHTML === box.outerHTML) return;
  const had = box.contains(document.activeElement) ? document.activeElement.dataset.key : '';
  paint(box);
  const back = had && [...box.querySelectorAll('[data-key]')].find((e) => e.dataset.key === had);
  if (back) back.focus({ preventScroll: true });
}

/* The rail and every live block of the section on screen, drawn again from
   what the page knows where that changed. */
function paintSettingsLive() {
  if (!panelOpen('settings')) return;
  redrawIfChanged($('#settings-nav'), paintSettingsNav);
  // The tool whose edges are on screen colours the head of its section.
  const head = $('#settings-view .sethead');
  const sec = settingsSections(settingsNow()).find((x) => x.key === S.settingsSection);
  if (head && sec && 'tool' in sec && head.dataset.tool !== sec.tool) head.dataset.tool = sec.tool;
  for (const box of $$('#settings-view [data-live]')) redrawIfChanged(box, paintSettingsBlock);
}

/* For whatever changes what a section shows: one redraw for every call a
   change makes, once it has made them. */
function repaintSettings() {
  if (!panelOpen('settings') || S.settingsRepaint) return;
  S.settingsRepaint = true;
  Promise.resolve().then(() => {
    S.settingsRepaint = false;
    paintSettingsLive();
  });
}

/* Where dbt looks for the profile, and the button that opens it (0049). */
function paintSetProfile(box) {
  const p = S.profiles;
  const where = 'dbt looks for it in DBT_PROFILES_DIR, then in the project, then in .dbt in your home folder';
  const warn = (text) => jel('span', 'setnote warn', text);
  if (!p) return box.replaceChildren(warn(`Nowhere to look for one: ${where}, and there is no home folder. `
    + 'Set DBT_PROFILES_DIR before starting dbt-edith.'));
  const shown = [jel('code', 'mono', p.path)];
  if (p.found && !p.refused) {
    const open = jel('button', 'btn sm', 'Open profiles.yml');
    open.type = 'button';
    open.dataset.key = 'profile';
    // Its tab rolls the panel up, as any file opened does.
    open.addEventListener('click', openProfiles);
    shown.push(open, okLine('ok', 'found'));
  } else {
    shown.push(warn(p.refused ? `Not opened: ${p.refused}.`
      : `None there: ${where}, and a dbt command that connects fails until there is one.`));
  }
  box.replaceChildren(...shown);
}

/* What a .env file line says beside its name: the DBT_TARGET it holds, how
   many of the variables the location config reads it defines, and how often
   it reproduces what dbt parsed, each left out while unknown. A hidden file
   says so instead. `refs` is the variables the config reads. */
function envLineSummary(f, refs) {
  if (f.hidden) return 'hidden';
  const parts = [];
  if (f.target) parts.push(`DBT_TARGET=${f.target}`);
  if (f.coverage && refs.length) parts.push(`${f.coverage.defined}/${refs.length} variables`);
  const a = f.agreement;
  if (a && a.checked) parts.push(`${Math.round((1000 * a.equal) / a.checked) / 10}% as parsed`);
  return parts.join(' · ');
}

/* The environments, once the .env files are read again, as the dialog this
   replaces read them, for a file added or edited since: the files, which one
   resolves the Catalog's locations, then what each is named and whether it is
   offered. A save has read them already. */
async function drawSetEnvs(group, { read = true } = {}) {
  group.replaceChildren();
  setGroupHead(group, 'Environments');
  const about = 'Where the Catalog resolves each model\'s database and schema, one environment per file.';
  const files = setRow(group, '.env files', about);
  files.append(jel('span', 'setnote', 'Reading the .env files…'));
  if (read || !S.envs) await loadEnvs();
  if (!S.envs) return files.replaceChildren(jel('span', 'setnote warn', 'The .env files could not be read.'));
  if (!envsInUse()) {
    return files.replaceChildren(jel('span', 'setnote', 'No location config reads an env var, so no .env file changes '
      + 'what the Catalog shows.'));
  }
  const list = jel('div', 'envlist');
  for (const f of S.envs.files) {
    const line = jel('div', 'envline');
    const said = envLineSummary(f, S.envs.referenced);
    const sum = jel('span', 'dim mono');
    said.split(' · ').forEach((part, i) => sum.append(...(i ? [' · '] : []), jel('span', '', part)));
    line.append(envTag(f.name, envTone(f.name)), jel('span', 'mono', f.file), sum);
    list.append(line);
  }
  files.replaceChildren(list);
  const pick = setRow(group, 'In the status bar', ['The environment the Catalog and the status bar show first.',
    'Which .env file the Catalog\'s Location resolves database, schema and alias with, its env vars in place of the ones dbt '
    + 'had when it parsed, as the env pill in the status bar says.']);
  pick.dataset.live = 'envpick';
  paintSetEnvPick(pick);
  setRow(group, 'Names', 'Leave a name empty for the automatic one, the file\'s suffix in capitals. A hidden file is not offered, '
    + 'here or in the Catalog\'s environment menu.', { wide: true })
    .append(envManageForm(() => drawSetEnvs(group, { read: false })));
}

/* The environment the Catalog shows, one radio each, in the colour of its
   name; the manifest, or the developer's own compile, only outlined. The
   arrows move and pick together, as the theme cards do. */
function paintSetEnvPick(box) {
  if (!envsInUse()) return box.replaceChildren();
  // The manifest first, as the board orders it; the menus keep theirs.
  const listed = envChoices();
  const choices = [...listed.filter((c) => c.file === ''), ...listed.filter((c) => c.file !== '')];
  const seg = jel('div', 'seg2 envseg');
  seg.setAttribute('role', 'radiogroup');
  seg.setAttribute('aria-label', 'Environment shown');
  const stop = choices.some((c) => c.current) ? -1 : 0;
  choices.forEach((c, i) => {
    const b = jel('button', '', c.label);
    b.type = 'button';
    b.setAttribute('role', 'radio');
    b.setAttribute('aria-checked', String(c.current));
    b.dataset.key = 'env:' + c.label;
    b.dataset.tone = c.tone;
    b.tabIndex = c.current || i === stop ? 0 : -1;
    b.title = c.title || c.sub;
    b.addEventListener('click', () => selectEnv(c.file));
    seg.append(b);
  });
  seg.onkeydown = (e) => {
    const all = [...seg.querySelectorAll('button')];
    const at = all.indexOf(document.activeElement);
    const to = { ArrowRight: at + 1, ArrowDown: at + 1, ArrowLeft: at - 1, ArrowUp: at - 1, Home: 0, End: all.length - 1 }[e.key];
    if (at < 0 || to === undefined) return;
    e.preventDefault();
    const next = (to + all.length) % all.length;
    // Focused first: the redraw the pick causes puts the focus back by data-key.
    all[next].focus();
    selectEnv(choices[next].file);
  };
  box.replaceChildren(seg);
}

/* The venv the status bar names, why, and the line that activates each one
   a click can offer (0072). */
function paintSetPython(box) {
  const v = venvStatus(S.venv || {}, S.termVenv);
  const path = jel('div', 'pyline');
  path.append(v.path ? jel('code', 'mono', v.path) : jel('span', 'dim', 'no venv'));
  const chips = jel('div', 'chips');
  if (v.python) chips.append(jel('span', 'chip', 'py ' + v.python));
  for (const d of v.dbt.split(', ').filter(Boolean)) chips.append(jel('span', 'chip', d));
  chips.append(okLine({ on: 'ok', off: 'warn' }[v.state] || 'none', v.say));
  box.replaceChildren(path, chips, ...v.notes.split('\n').filter(Boolean).map((l) => jel('p', 'setnote', l)));
  if (!v.offer.length) return;
  const bar = jel('div', 'setactions');
  for (const e of v.offer) {
    const b = jel('button', 'btn sm', `Activate ${e.name} in the terminal`);
    b.type = 'button';
    b.dataset.key = 'venv:' + e.path;
    b.title = [e.activation, e.dbt && 'dbt: ' + e.dbt].filter(Boolean).join('\n');
    b.addEventListener('click', () => sendToTerminal(e.activation, false, null, 'the settings'));
    bar.append(b);
  }
  box.append(bar, jel('p', 'setnote', 'Each types the line that activates it, and leaves Enter to you.'));
}

/* When the next look for a newer release is due, in the Updates section's
   foot: updateLook says it with the last one, for Edith's menu. */
function nextLook(u, now) {
  if (!u || u.off || u.checking) return '';
  if (u.next > now) return `The next look at GitHub is ${whenLooked(u.next, now)}.`;
  return u.next ? 'The next look at GitHub is due now.' : '';
}

/* The Updates section: this build and the newest, the releases since, how to
   install the one on offer, and the look for a newer one. Edith's menu draws
   the same answers in a popup (paintUpdateMenu). */
function paintSetUpdates(box) {
  const u = S.update || { current: S.version };
  const o = updateOffer(u, S.os);
  const now = Math.floor(Date.now() / 1000);
  const kids = [];
  const card = (head, value, under, fresh, figure) => {
    const c = jel('div', fresh ? 'vcard new' : 'vcard');
    c.append(jel('div', 'vk', head), jel('div', figure ? 'vv mono' : 'vv words', value), jel('div', 'vs', under));
    return c;
  };
  const cards = jel('div', 'vcards');
  // The next look is the foot's to say, so the card names the last one only.
  const last = updateLook(Object.assign({}, u, { next: 0 }), now);
  const newest = u.newer ? u.latest : u.off ? 'Not looked for' : u.latest ? (u.latest === u.current ? 'This is the newest' : u.latest)
    : u.checking ? 'Looking…' : u.failed ? 'No answer from GitHub' : 'Not looked for yet';
  // A version is a figure; anything else is words, which the card does not say
  // twice: with no look made, nor failed, nor on its way, there is nothing to add.
  const figure = !!(u.newer || (u.latest && u.latest !== u.current && !u.off));
  const under = !u.off && !u.checking && !u.checked && !u.failed ? '' : last;
  cards.append(card('This build', u.current || S.version || '?', S.build || '', false, true),
    card('Newest', newest, under, !!u.newer, figure));
  kids.push(cards);
  const unsafe = pathWarning(S.pathReadsCwd, S.pathEntry);
  if (unsafe.length) {
    const g = jel('section', 'sgroup');
    unsafe.forEach((parts, i) => {
      const p = jel('p', i ? 'sp2' : 'sp2 pathwarn');
      for (const part of parts) p.append(part.code === undefined ? document.createTextNode(part) : jel('code', '', part.code));
      g.append(p);
    });
    kids.push(g);
  }
  if (o) {
    const link = (href, className, title, key) => {
      const a = jel('a', className);
      a.href = href;
      a.target = '_blank';
      a.rel = 'noopener noreferrer';
      if (title) a.title = title;
      a.dataset.key = key;
      return a;
    };
    const listed = releaseRows(u);
    const rel = jel('section', 'sgroup');
    if (listed) {
      setGroupHead(rel, listed.head);
      for (const r of listed.rows) {
        const a = link(r.href, 'relline', r.tip, 'rel:' + r.version);
        a.append(jel('span', 'mono', r.version), jel('span', '', r.title));
        rel.append(a);
      }
      if (listed.older) {
        const a = link(listed.older.href, 'relline', listed.older.tip, 'rel:older');
        a.append(jel('span', 'mono', ''), jel('span', '', listed.older.label));
        rel.append(a);
      }
      kids.push(rel);
    } else if (o.notes) {
      const a = link(o.notes, 'relline', 'The release notes, on GitHub', 'rel:notes');
      a.append(jel('span', 'mono', ''), jel('span', '', 'What changed'));
      rel.append(a);
      kids.push(rel);
    }
    const how = jel('section', 'sgroup');
    setGroupHead(how, 'How to install it');
    if (o.installed) how.append(jel('p', 'sp2 updready', 'Installed: restart dbt-edith to run it'));
    if (o.step) how.append(jel('p', 'sp2', o.step));
    // One command per button, the recommended first and drawn as the primary
    // one; each types its line into the terminal and leaves Enter to you (0123).
    o.options.forEach((option, i) => {
      const run = jel('button', i ? 'btn' : 'btn primary', option.button);
      run.type = 'button';
      run.dataset.key = 'upd:' + option.kind;
      run.title = option.command;
      run.addEventListener('click', () => {
        sendToTerminal(option.command, false, () => notice(updateNotice('typed', option.kind)), 'the settings');
        watchInstall();
      });
      const cmd = jel('div', 'codebox');
      cmd.append(jel('div', 'pre', option.command), run);
      how.append(cmd);
    });
    for (const line of o.lines) how.append(jel('p', 'sp2', line));
    kids.push(how);
  }
  if (!u.off) {
    const foot = jel('div', 'setfoot');
    // Not `disabled`, which takes no focus: the focus goes back to it once drawn.
    const look = jel('button', 'btn', u.checking ? 'Looking…' : 'Check for updates');
    look.type = 'button';
    look.dataset.key = 'upd-check';
    if (u.checking) look.setAttribute('aria-disabled', 'true');
    look.addEventListener('click', () => { if (!u.checking) checkForUpdate(); });
    foot.append(jel('span', 'dim', nextLook(u, now)), jel('div', 'grow'), look);
    kids.push(foot);
  }
  box.replaceChildren(...kids);
}

/* The tour, the shortcut list and GitHub, each one click away. */
function drawSetHelp(body) {
  const group = setGroup(body);
  const go = jel('button', 'btn primary', 'Give me a tour');
  go.type = 'button';
  go.addEventListener('click', startTour);
  setRow(group, 'Tour', ['A walk through the app, one step per part, on your own project.',
    'It opens a model of this project and points at what each part of the page does with it. It runs nothing and '
    + 'changes no setting, and puts the page back as it was when it ends.']).append(go);
  const list = jel('button', 'btn', 'Show them');
  list.type = 'button';
  list.addEventListener('click', toggleShortcuts);
  setRow(group, 'Keyboard shortcuts', [['Every key the app answers to. ', jel('kbd', '', keyLabel('?', IS_MAC)),
    ' outside a text box, ', jel('kbd', '', keyLabel('F1', IS_MAC)), ' from anywhere.']]).append(list);
  const sc = setRow(group, 'dbt-edith on GitHub', ['Issues, releases and the README.',
    'Both open GitHub in a new tab; an issue or a star needs a GitHub account.']);
  const links = githubLinks(S.repo, S.version, S.build, S.os);
  for (const [href, label, title] of [[links.issue, 'Raise an issue or a request', 'A new issue on GitHub, your version already in it'],
    [links.star, 'Give dbt-edith a star', 'The repository on GitHub, whose Star button is at the top right']]) {
    const a = jel('a', 'btn', label);
    a.href = href;
    a.target = '_blank';
    a.rel = 'noopener noreferrer';
    a.title = title;
    sc.append(a);
  }
  sc.append(jel('span', 'dim mono', 'v' + (S.version || '?')));
}

// -------------------------------------------------------------- hover card --
/* One floating card, shared by the lineage boxes and the editor's marks. It is
   hoverable, so its text can be read and selected, but holds no focusable
   control: a surface that opens by accident should not also own a focus trap
   and an Escape contract the way the env menu has to. */
const HOVER_DELAY = 350;   // a sweep across a dense graph must open nothing
const HOVER_GRACE = 180;   // time for the pointer to cross the gap into the card
const HOVER_COLS = 8;      // the card never scrolls: the rest is counted, not listed

/* Where a box of size `box` goes next to `at`, inside `view`. Below when it
   fits, above when it does not, clamped rather than clipped when neither works.
   `view` is a parameter rather than a read of `window` so this can be checked
   without a DOM; its `top` and `left` are optional (0 by default) and place it
   somewhere other than the window's corner, as the editor's card is (0167). */
function placeFloating(at, box, view, gap = 8) {
  const vt = view.top || 0, vl = view.left || 0;
  const below = at.bottom + gap + box.height <= vt + view.height;
  const above = at.top - gap - box.height >= vt;
  let top;
  if (below) top = at.bottom + gap;
  else if (above) top = at.top - gap - box.height;
  else top = Math.max(vt + 4, Math.min(at.bottom + gap, vt + view.height - box.height - 4));
  // A box wider than the viewport pins to the left edge rather than going negative.
  const left = Math.max(vl + 4, Math.min(at.left, vl + view.width - box.width - 4));
  return { top, left, above: !below && above };
}

/* The room a hover card may take: the window, or, for a card opened from the
   editor, the part of the editor that is in the window (0167). A card taller
   than that falls back to the window rather than overflow the editor, since a
   card must be read whole. */
function hoverView(win, within, box) {
  const whole = { top: 0, left: 0, width: win.width, height: win.height };
  if (!within) return whole;
  const left = Math.max(0, within.left), top = Math.max(0, within.top);
  const right = Math.min(win.width, within.right), bottom = Math.min(win.height, within.bottom);
  if (box.height > bottom - top || box.width > right - left) return whole;
  return { top, left, width: Math.max(0, right - left), height: bottom - top };
}

/* The head every card shares. Returns the element so a filler can keep appending. */
/* What a test checks, for its hover card: the generic and where it applies,
   the package it was named through when dbt recorded one, and a warn
   severity. `level` is the canvas's word for the kind of test (0040). A bare
   generic may still live in a package, so without a namespace the card names
   none rather than claim the project's own. */
function testFacts(n, level) {
  if (!n || n.kind !== 'test') return [];
  const facts = [{
    text: level === 'column' ? `${n.test_name} on ${n.column}`
      : level === 'model' ? `${n.test_name} on the whole model`
        : 'A singular test: SQL of its own, no generic',
  }];
  if (n.namespace) facts.push({ text: `generic from ${n.namespace}` });
  if (n.warn) facts.push({ text: 'severity: warn', warn: true });
  return facts;
}

/* What an incremental model's strategy does, for its hover card: where it
   comes from and the key it works on, or, when the macros dbt runs insert
   every row for want of a key, why, in the warning colour and worded by the
   macro that inserts. Painted from the box and again from /api/node, which
   carry the same fields, so the line does not change under the pointer. */
const KEYED_STRATEGIES = ['merge', 'delete+insert'];
const INSERT_REASONS = {
  snowflake__get_merge_sql: 'so Snowflake runs a plain insert into',
  default__get_merge_sql: 'on FALSE, so every row is inserted',
  default__get_delete_insert_merge_sql: 'so nothing is deleted before the insert',
};
function strategyFacts(n, adapter) {
  if (!n || n.kind !== 'model' || n.materialized !== 'incremental' || n.disabled) return [];
  const name = Lineage.adapterName(adapter);
  if (!n.strategy_shown) {
    return [{ text: `${name}'s default strategy, which could not be read from its macros`, muted: true }];
  }
  const origin = n.strategy_default ? `, ${name}'s default` : '';
  if (n.strategy_insert) {
    const reason = INSERT_REASONS[n.strategy_insert] || 'so every row is inserted';
    return [{ text: `append in effect: ${n.strategy_named}${origin}${origin && ','} with no unique key, ${reason}`, warn: true }];
  }
  if (!KEYED_STRATEGIES.includes(n.strategy_shown)) return [{ text: n.strategy_shown + origin }];
  const key = n.unique_key || [];
  return [{ text: key.length ? `${n.strategy_shown} on ${key.join(', ')}${origin}` : `${n.strategy_shown}${origin}, no unique key` }];
}

/* A second line for HTML: the parts subtitleParts() gives, the struck word in
   an <s>. */
function subNodes(p) {
  if (!p.struck) return [[p.lead, p.rest].filter(Boolean).join('  ·  ')];
  return [`${p.lead} `, Object.assign(document.createElement('s'), { textContent: p.struck }), p.rest ? `  ·  ${p.rest}` : ''];
}

function hoverCardBody(el, { title, tone, sub, crumb, node }) {
  el.textContent = '';
  el.classList.toggle('hc-node', !!node);
  const head = document.createElement('div');
  head.className = 'hc-head';
  if (tone) head.appendChild(tone);
  head.append(Object.assign(document.createElement('span'), { className: 'hc-name', textContent: title }));
  el.appendChild(head);
  // A string, or the nodes subNodes() makes of a box's line. A node's card
  // (0166) puts it at the head's right and its file on a row of its own, where
  // the tags join it; the other cards keep a line under the name.
  if (sub) {
    const line = Object.assign(document.createElement(node ? 'span' : 'div'), { className: node ? 'hc-mt' : 'hc-sub' });
    line.append(...[].concat(sub));
    (node ? head : el).append(line);
  }
  if (crumb && node) {
    const row = Object.assign(document.createElement('div'), { className: 'hc-path' });
    row.append(Object.assign(document.createElement('span'), { className: 'hc-file', textContent: crumb }));
    el.append(row);
  } else if (crumb) el.append(Object.assign(document.createElement('div'), { className: 'hc-crumb', textContent: crumb }));
  return el;
}

let hoverCard = null;                        // { el, at, within, off }
let hoverTimer = null, hoverGrace = null;
let hoverKey = '';                           // what the card shows, or is about to

function closeHoverCard() {
  clearTimeout(hoverTimer);
  clearTimeout(hoverGrace);
  hoverTimer = hoverGrace = null;
  hoverKey = '';
  if (!hoverCard) return;
  const { el, off } = hoverCard;
  hoverCard = null;
  off();
  el.remove();
}

/* Re-measured after every paint: a card that grows when the payload lands would
   otherwise keep the position its first, shorter self was given. */
function placeHoverCard() {
  if (!hoverCard) return;
  const box = hoverCard.el.getBoundingClientRect();
  const size = { width: box.width, height: box.height };
  const win = { width: window.innerWidth, height: window.innerHeight };
  const within = hoverCard.within ? hoverCard.within() : null;
  const p = placeFloating(hoverCard.at, size, hoverView(win, within, size));
  hoverCard.el.style.top = `${p.top}px`;
  hoverCard.el.style.left = `${p.left}px`;
}

function openHoverCard(at, fill, within) {
  const el = document.createElement('div');
  el.className = 'hovercard';
  el.setAttribute('role', 'tooltip');
  document.body.appendChild(el);
  hoverCard = { el, at, within, off: () => {} };
  fill(el);
  placeHoverCard();

  el.addEventListener('mouseenter', () => { clearTimeout(hoverGrace); hoverGrace = null; });
  el.addEventListener('mouseleave', hoverLeave);

  // Typing means the card is not being read.
  const onKey = () => closeHoverCard();
  // Deliberately no preventDefault: a click on a ref() still has to reach wireRefClicks.
  const onDown = (e) => { if (!el.contains(e.target)) closeHoverCard(); };
  const onScroll = (e) => { if (!el.contains(e.target)) closeHoverCard(); };
  const onResize = () => closeHoverCard();
  document.addEventListener('keydown', onKey, true);
  document.addEventListener('mousedown', onDown, true);
  document.addEventListener('scroll', onScroll, true);
  window.addEventListener('resize', onResize);
  hoverCard.off = () => {
    document.removeEventListener('keydown', onKey, true);
    document.removeEventListener('mousedown', onDown, true);
    document.removeEventListener('scroll', onScroll, true);
    window.removeEventListener('resize', onResize);
  };
}

/* `key` identifies what is under the pointer, so a mousemove that stays on the
   same thing neither restarts the delay nor repaints. Moving to a different one
   while a card is open swaps it without waiting again, the way a group of
   tooltips behaves. `within`, when given, returns the rect the card stays
   inside: the editor's for a card it opens, the window's for the canvas's. */
function hoverEnter(key, getRect, fill, within) {
  clearTimeout(hoverGrace);
  hoverGrace = null;
  if (key === hoverKey) return;
  const swap = !!hoverCard;
  clearTimeout(hoverTimer);
  hoverTimer = null;
  hoverKey = key;
  // The rect is read when the card opens, not now: a pan during the delay would
  // otherwise anchor it where the box used to be.
  const show = () => {
    hoverTimer = null;
    if (hoverCard) { hoverCard.off(); hoverCard.el.remove(); hoverCard = null; }
    openHoverCard(getRect(), fill, within);
  };
  if (swap) show();
  else hoverTimer = setTimeout(show, HOVER_DELAY);
}

function hoverLeave() {
  clearTimeout(hoverTimer);
  hoverTimer = null;
  if (!hoverCard) { hoverKey = ''; return; }
  clearTimeout(hoverGrace);
  hoverGrace = setTimeout(closeHoverCard, HOVER_GRACE);
}

/* A column's box, when it has more to say than the box shows: what the SQL
   sets a generated column to (0096), what computes a column that is more than
   a copy (0138), and apart from it what keeps the rows it is in (0097), and
   the models it keeps the rows of (0118), so "from no column" and a filter on
   another column are two facts rather than one contradiction. All in the
   box's payload, so it paints once. */
function fillColumnCard(el, n, rows) {
  // The line is the role the card is about, as the stop at menu draws one
  // (dashed for the rows it keeps), not a kind's bar; a card opened only by an
  // expression is neither generated nor kept by anything, and gets none.
  let tone = null;
  if (Array.isArray(n.generated) || rows) {
    const line = Lineage.roleSwatch(Array.isArray(n.generated) ? 'generated' : 'indirect');
    tone = Object.assign(document.createElement('span'), { className: line.dashed ? 'rolesq dash' : 'rolesq' });
    tone.setAttribute('style', line.style);
  }
  hoverCardBody(el, { title: n.name, tone, sub: subNodes(Lineage.subtitleParts(n)), crumb: n.file });
  // The card's lines, one box each: what sets the column, what computes it
  // (0138), and the two lines of rows, kept by and kept of (0118).
  const lines = (Array.isArray(n.generated) ? [Lineage.generatedSaid(n.generated).long] : [])
    .concat(Lineage.expressionSaid(n.expression), rows ? rows.split('\n') : []);
  // A rule under "keeps the rows of" is a sub-line: its indent is padding,
  // since the note collapses leading spaces.
  for (const line of lines) {
    const sub = /^ {2}/.test(line);
    el.append(Object.assign(document.createElement('div'), { className: 'hc-note' + (sub ? ' hc-rule' : ''), textContent: sub ? line.slice(2) : line }));
  }
  fillPartialCard(el, n);
}

/* The names collin gave up on inside this column's model (0145), in the warn
   colour, what to do about it, and the two places the SQL is: the model's
   file and its compiled text, each lit on the names. */
function fillPartialCard(el, n) {
  const said = Lineage.partialSaid(n.partial);
  if (!said.length) return;
  el.append(Object.assign(document.createElement('div'), { className: 'hc-note warn', textContent: said[0] }));
  el.append(Object.assign(document.createElement('div'), { className: 'hc-note muted', textContent: said[1] }));
  const row = document.createElement('div');
  row.className = 'hc-counts';
  const link = (text, title, run) => {
    const a = Object.assign(document.createElement('span'), { className: 'hc-link', textContent: text, title });
    a.addEventListener('click', () => { closeHoverCard(); run(); });
    return a;
  };
  row.append(
    link('open the file', 'Open the model and find these names', () => openFileOnNames(n.file, n.partial)),
    '  ·  ',
    link('compiled SQL', 'Open the compiled SQL of the model and find these names', () => openCompiledOnNames(splitColId(n.id).node, n.partial)),
  );
  el.append(row);
}

/* Painted twice: once from what the caller already holds, so the card appears
   with the pointer, and again when /api/node answers with the description and
   the columns. */
function fillNodeCard(el, id, seed) {
  const paint = (n, full) => {
    if (!hoverCard || hoverCard.el !== el) return;   // closed, or swapped for another
    const tone = dot(n);
    tone.removeAttribute('title');           // no native tooltip inside the card
    // The box's line without its test count, which the stats below say.
    hoverCardBody(el, { title: n.name || id, tone, sub: subNodes(Lineage.subtitleParts({ ...n, tests: 0 })), crumb: n.file || id, node: true });
    if (n.tags && n.tags.length) {
      const tags = document.createElement('span');
      tags.className = 'hc-tags';
      for (const t of n.tags) tags.append(Object.assign(document.createElement('span'), { className: 'tagchip', textContent: t }));
      el.querySelector('.hc-path').append(tags);
    }
    if (n.disabled) {
      const off = Object.assign(document.createElement('span'), { className: 'offchip', textContent: 'disabled' });
      el.querySelector('.hc-head').appendChild(off);
    }
    // Painted from the box and again from the detail, which carry the same
    // facts, so the card does not change under the pointer.
    const facts = testFacts(n, Lineage.testLevel(n)).concat(strategyFacts(n, S.meta && S.meta.adapter));
    for (const f of facts) {
      el.append(Object.assign(document.createElement('div'), {
        className: 'hc-note' + (f.warn ? ' warn' : '') + (f.muted ? ' muted' : ''), textContent: f.text,
      }));
    }
    // The last build in the environment the canvas shows (0117), a line a
    // target: the mark has no title of its own, which would land over the card.
    const spec = n.kind === 'model' && !n.disabled && n.materialized !== 'ephemeral' ? buildsSpec() : null;
    if (spec) {
      for (const line of spec.of(id).title.split('\n')) {
        el.append(Object.assign(document.createElement('div'), { className: 'hc-note muted', textContent: line }));
      }
    }
    if (!full) return;

    // A test keeps no description and has no columns, downstream or tests of
    // its own: only what it reads is worth a count.
    const test = n.kind === 'test';
    if (!test) {
      el.append(Object.assign(document.createElement('div'), {
        className: 'hc-desc' + (n.description ? '' : ' muted'),
        textContent: n.description || 'No description in the YAML.',
      }));
    }

    // The numbers in the text colour, their words quieter; a test's card says
    // only what it reads.
    const stat = (num, word) => {
      const one = document.createElement('span');
      one.append(Object.assign(document.createElement('b'), { textContent: String(num) }), ` ${word}`);
      return one;
    };
    const stats = document.createElement('div');
    stats.className = 'hc-stats' + (n.columns.length ? ' ruled' : '');
    if (test) stats.append(stat(n.upstream_total, 'up'));
    else {
      stats.append(stat(n.columns.length, n.columns.length === 1 ? 'column' : 'columns'), stat(n.upstream_total, 'up'),
        stat(n.downstream_total, 'down'), stat(n.tests.length, n.tests.length === 1 ? 'test' : 'tests'));
    }
    el.append(stats);

    if (n.columns.length) {
      const list = document.createElement('div');
      list.className = 'hc-cols';
      for (const c of n.columns.slice(0, HOVER_COLS)) {
        const row = document.createElement('div');
        row.className = 'hc-col';
        row.append(Object.assign(document.createElement('span'), { className: 'c-name', textContent: c.name }));
        row.append(Object.assign(document.createElement('span'), { className: 'c-type', textContent: c.data_type || '' }));
        list.appendChild(row);
      }
      if (n.columns.length > HOVER_COLS) {
        list.append(Object.assign(document.createElement('div'), {
          className: 'hc-more', textContent: `+${n.columns.length - HOVER_COLS} more`,
        }));
      }
      el.appendChild(list);
    }

    placeHoverCard();
  };

  paint(seed, false);
  nodeDetail({ id }).then((n) => paint(n, true)).catch(() => {});
}

/* A variable's value. The head is painted at once and the value replaces a
   placeholder line when /api/vars answers. */
function fillVarCard(el, t) {
  const call = `${t.kind}('${t.name}')`;
  const envLabel = S.env || '';
  hoverCardBody(el, { title: call, sub: t.kind === 'env_var' ? 'environment variable' : 'project var' });
  el.append(Object.assign(document.createElement('div'), { className: 'hc-note muted', textContent: 'reading...' }));

  const show = (value, sub, crumb, tone) => {
    if (!hoverCard || hoverCard.el !== el) return;   // closed, or swapped for another
    el.textContent = '';
    hoverCardBody(el, { title: call, sub: t.kind === 'env_var' ? 'environment variable' : 'project var', crumb });
    if (value !== null) {
      el.append(Object.assign(document.createElement('div'), {
        className: 'hc-value' + (value === '' ? ' muted' : ''),
        textContent: value === '' ? '(empty)' : value,
      }));
    }
    if (sub) el.append(Object.assign(document.createElement('div'), { className: 'hc-note ' + (tone || 'muted'), textContent: sub }));
    placeHoverCard();
  };

  fetchVars(t.kind === 'env_var' ? t.name : '').then((body) => {
    if (t.kind === 'env_var') {
      const row = (body.env_vars || [])[0];
      if (!row) return show(null, 'no answer for this name', '', 'warn');
      const fallback = t.fallback ? `\ndefault written in this call: ${t.fallback}` : '';
      return show(row.value === undefined ? null : row.value, varNote(row, envLabel) + fallback,
        envLabel || 'no environment selected', row.redacted ? 'warn' : '');
    }
    const row = (body.vars || []).find((v) => v.name === t.name);
    if (!row) {
      const miss = t.fallback
        ? `not in the vars: block, so the default in this call is used: ${t.fallback}`
        : 'not in the vars: block of dbt_project.yml';
      return show(null, miss, body.file, 'warn');
    }
    const lines = [];
    // A redacted value is never shown, nor the expression that produced it:
    // the server blanks `raw` too, since an `env_var()` default may be the
    // secret itself.
    const value = row.null || row.redacted ? null : (row.resolved !== undefined ? row.resolved : row.raw);
    if (row.null) lines.push('declared with no value, so var() returns null');
    if (row.status) lines.push(varNote(row, envLabel));
    else if (row.redacted) lines.push(hiddenWhy(row));
    if (row.status && row.raw) lines.push('as written: ' + row.raw);
    show(value, lines.filter(Boolean).join('\n'), `${body.file}:${row.line}`, row.redacted ? 'warn' : '');
  }).catch(() => show(null, 'could not read dbt_project.yml', '', 'warn'));
}

/* A macro, from what its link already carries, so there is nothing to wait
   for. The package is the line that matters: a project and a package can both
   define `hub`, and this says which of the two the call reached. */
/* A folder key in dbt_project.yml. The crumb is the folder itself, which is
   what the click opens; the rest is what the key could not say on its own:
   that the config reaches no resource, or that the same chain exists under
   another root. A key the server could not place says where it looked. */
function fillDirCard(el, t) {
  const chain = t.chain.length ? t.chain.join(' > ') : t.block;
  if (!t.path) {
    hoverCardBody(el, { title: chain, sub: `${t.block} config` });
    el.append(Object.assign(document.createElement('div'), { className: 'hc-desc muted', textContent: missingKeyNote(t) }));
    return;
  }
  hoverCardBody(el, { title: chain, sub: t.dir ? `${t.block} config` : `${t.block} config · one file`, crumb: t.path });
  // Only a manifest that matches the project can turn "nothing under it" into
  // "this config reaches nothing". A folder added since the last parse is in no
  // manifest either, and saying it configures nothing would be a lie (0025).
  if (t.nodes === 0) {
    const fresh = S.fresh && S.fresh.state === 'fresh';
    el.append(Object.assign(document.createElement('div'), {
      className: 'hc-desc muted',
      textContent: fresh
        ? 'The folder is there, and no resource in the manifest sits under it: this config reaches nothing, which is what dbt warns about when it parses.'
        : 'The folder is there, and no resource in the manifest sits under it. The manifest no longer matches the project, so a folder added since the last parse is the likelier reason.',
    }));
  }
  if (t.also && t.also.length) {
    el.append(Object.assign(document.createElement('div'), {
      className: 'hc-counts',
      textContent: 'also under: ' + t.also.join(', '),
    }));
  }
}

/* The keys dbt would warn of on a line, from its mark in the gutter (0103),
   each with its reason. As for a folder with nothing under it, a manifest
   behind the project makes a folder added since the last parse the likelier
   reason. */
function fillUnusedCard(el, paths, stale) {
  const many = paths.length > 1;
  hoverCardBody(el, { title: paths.map(unusedSays).join(', '),
    sub: `${many ? 'apply' : 'applies'} to no resource, dbt warns as it parses` });
  for (const u of paths) {
    el.append(Object.assign(document.createElement('div'), { className: 'hc-desc muted',
      textContent: many ? `${unusedSays(u)}: ${unusedWhy(u)}` : unusedWhy(u) }));
  }
  if (stale) {
    el.append(Object.assign(document.createElement('div'), { className: 'hc-note warn',
      textContent: 'The manifest no longer matches the project: a folder added since the last parse is the likelier reason.' }));
  }
  el.append(Object.assign(document.createElement('div'), { className: 'hc-counts', textContent: 'click: the Warnings report' }));
}

/* What a macro's callers are called, one and several. A hook is an
   operation node to dbt, and reads as what it was written as. */
const USE_KINDS = {
  model: ['model', 'models'], snapshot: ['snapshot', 'snapshots'], seed: ['seed', 'seeds'], test: ['test', 'tests'],
  analysis: ['analysis', 'analyses'], operation: ['hook', 'hooks'], exposure: ['exposure', 'exposures'],
  source: ['source', 'sources'], other: ['node', 'nodes'],
};
const useKind = (kind, n) => (USE_KINDS[kind] || USE_KINDS.other)[n === 1 ? 0 : 1];
const counted = (n, one, many) => `${n} ${n === 1 ? one : many}`;

/* What dbt runs a macro for, in the card's words: `run` names the config key
   and the value the nodes carry (0105). */
function runSaid(run) {
  const what = { materialized: ['model materialized', 'models materialized'],
    incremental_strategy: ['incremental model with strategy', 'incremental models with strategy'],
    strategy: ['snapshot with strategy', 'snapshots with strategy'] }[run.key] || ['node named', 'nodes named'];
  return { each: `${what[0]} ${run.name}`, count: `${counted(run.nodes, what[0], what[1])} ${run.name}` };
}

/* What a macro's card, its palette row and its report entry say of who calls
   it, from the `used` the server sends with it (0105): `head` the line a
   click on the card opens the list from, `notes` the lines under it, `short`
   the palette's. A macro no node reaches has no reference found, never
   unused, and the likeliest reason it may still run: a run-operation or
   another package's call, which leave the manifest no trace, or dbt running
   it itself. `used_text` in src/describe.rs words the same lines for the
   command line (a copy of 0105's wording): change them together. */
function macroUseText(used, adapter) {
  const u = used || {};
  const by = u.by || [];
  const total = by.reduce((sum, k) => sum + k.n, 0);
  const callers = (u.callers || []).join(', ') + ((u.callers_of || 0) > (u.callers || []).length
    ? ` and ${u.callers_of - u.callers.length} more` : '');
  const notes = [];
  if (total) {
    if (u.through) notes.push(u.through === total ? 'all of them through other macros' : `${u.through} of them through other macros`);
    if (u.written) {
      notes.push(`${u.written === total ? 'all of them' : `${u.written} of them`} only where dbt recorded no call, read from their SQL`);
    }
    if (callers) notes.push(`called by ${callers}`);
    return { head: 'used by ' + by.map((k) => `${k.n} ${useKind(k.kind, k.n)}`).join(', '), notes, short: `used by ${total}` };
  }
  const ran = u.run && runSaid(u.run);
  const why = {
    dbt: u.from ? `called by ${u.from}, which dbt runs itself` : 'dbt calls it itself by its name, and records no call',
    run: ran && `dbt runs it for each ${ran.each}, and ${u.run.nodes ? counted(u.run.nodes, 'is', 'are') : 'none is'}`,
    dispatch: `a variant adapter.dispatch did not pick for ${adapter || 'the adapter'}, the one this manifest was parsed for`,
    test: 'a generic test no enabled test uses',
    macros: `called only by ${callers}, which no node reaches either`,
    none: 'nothing in the manifest calls it: dbt run-operation or another package may',
  }[u.why];
  return { head: 'no reference found', notes: why ? [why] : [], short: 'no reference found' };
}

/* The report's groups of macros no node reaches, in the order the server
   sends them (0105), each with what its title cannot say. */
const MACRO_GROUPS = {
  none: ['Nothing in the manifest calls them',
    'dbt run-operation or another package may still call them: neither call is in the manifest, nor in any node\'s SQL or hooks.'],
  macros: ['Called only by macros no node reaches', 'Each is called by the macros named beside it, and no node reaches those either.'],
  test: ['Generic tests no test uses', 'No enabled test is built from them.'],
  dispatch: ['Dispatch variants not picked',
    'adapter.dispatch picks one variant per adapter: not another adapter\'s, nor a default the adapter\'s own shadows. This manifest was parsed for'],
  run: ['Run by dbt for the nodes that name them',
    'dbt runs a materialization for each model of its name, and a strategy macro for each model or snapshot naming the strategy, and records no call.'],
  dbt: ['Called by dbt itself',
    'dbt calls these itself and records no call: by their name, as generate_schema_name or a macro of its own the project overrides, or from what it runs, its own macros included.'],
};

function macroGroups(unreached) {
  const groups = [];
  for (const m of unreached || []) {
    const why = (m.used && m.used.why) || 'none';
    let g = groups[groups.length - 1];
    if (!g || g.why !== why) {
      const [title, lever] = MACRO_GROUPS[why] || MACRO_GROUPS.none;
      g = { why, title, lever, items: [] };
      groups.push(g);
    }
    const u = m.used || {};
    const extra = why === 'macros' ? `called by ${(u.callers || []).join(', ')}`
      + ((u.callers_of || 0) > (u.callers || []).length ? ` and ${u.callers_of - u.callers.length} more` : '')
      : why === 'run' && u.run ? runSaid(u.run).count
        : why === 'dbt' && u.from ? `called by ${u.from}` : '';
    g.items.push({ id: m.id, name: m.name, call: m.call, file: m.file || '', extra });
  }
  return groups;
}

/* The figures over the macros: how many the project has, how many no node
   reaches, and how many of those nothing explains, which is the count the
   rail and the button carry: a macro called only by macros no node reaches or a
   generic test no test uses is unexplained, as is a materialization or
   strategy macro no node names. Worked out from the same payload, so it is the
   index's number. */
function macrosTiles(r) {
  const unreached = r.unreached || [];
  const unexplained = unreached.filter((m) => {
    const u = m.used || {};
    return ['none', 'macros', 'test'].includes(u.why || 'none') || (u.why === 'run' && !!u.run && !u.run.nodes);
  }).length;
  return [
    { label: 'Macros', value: String(r.own), sub: `in ${r.project}`, tone: '' },
    { label: 'No reference found', value: String(unreached.length), sub: 'reached by no node', tone: '' },
    { label: 'Left unexplained', value: String(unexplained), sub: 'and nothing explains them', tone: '' },
  ];
}

/* How a node in a macro's list reaches it, after its kind: through a macro,
   read from its SQL where dbt recorded no call, or both. */
function userHow(u) {
  if (u.how === 'written') return ` · ${u.via ? `through ${u.via}, ` : ''}read from its SQL, dbt recorded no call`;
  return u.via ? ` · through ${u.via}` : '';
}

/* A macro's card says who calls it, and its first line opens the list in the
   Reports panel: a list of hundreds belongs there, not in a card, which holds
   no focusable control. */
function fillMacroCard(el, t) {
  hoverCardBody(el, { title: t.name, sub: `macro · ${t.package}`, crumb: t.file });
  el.append(Object.assign(document.createElement('div'), {
    className: 'hc-desc' + (t.description ? '' : ' muted'),
    textContent: t.description || 'No description in the YAML.',
  }));
  if (t.args && t.args.length) {
    el.append(Object.assign(document.createElement('div'), { className: 'hc-counts', textContent: 'arguments: ' + t.args.join(', ') }));
  }
  if (!t.used) return;
  const use = macroUseText(t.used, S.meta && S.meta.adapter);
  const head = Object.assign(document.createElement('div'), {
    className: 'hc-counts hc-link' + (t.used.why ? ' muted' : ''), textContent: use.head, title: 'Open the list in Reports',
  });
  head.addEventListener('click', () => { closeHoverCard(); openMacroUse(t.id); });
  el.append(head);
  for (const n of use.notes) el.append(Object.assign(document.createElement('div'), { className: 'hc-note muted', textContent: n }));
}

/* The manifest pill's card (0157), drawn into the popup `openFreshCard` makes.
   Built from `freshnessBadge`, which decides every word: this only lays them
   out. Every control has a data-key, so a poll that changes the answer redraws
   it under the focus (redrawIfChanged). */
function fillFreshCard(el, f) {
  const b = freshnessBadge(f, !freshnessRuns(S.pathReadsCwd));
  const make = (tag, className, textContent = '') => Object.assign(document.createElement(tag), { className, textContent });
  el.replaceChildren();

  const head = make('div', 'mc-head');
  head.append(make('span', 'dot'), b.head);
  el.append(head);
  if (b.when) {
    const when = make('div', 'mc-when', b.when);
    when.dataset.age = '';
    el.append(when);
  }
  el.append(make('p', 'mc-desc', b.desc));
  if (b.paused) el.append(make('p', 'mc-note warn', b.paused));

  for (const g of b.groups) {
    el.append(make('div', 'mc-sec', g.head));
    for (const p of g.paths) {
      // A file the manifest names that no longer exists has nothing to open.
      const row = make(g.key === 'gone' ? 'div' : 'button', 'mc-file' + (g.key === 'gone' ? ' gone' : ''));
      row.title = p.full;
      row.append(fileIcon(p.name, fileMark(p.full)), make('span', 'nm', p.name));
      // git's letter is only meaningful for a file edited and not committed.
      const letter = g.key === 'edited' ? gitFileMark(p.full) : null;
      if (letter) {
        const gs = make('span', 'gs ' + letter[0], letter[1]);
        gs.title = letter[2];
        gs.setAttribute('aria-label', letter[2]);
        row.append(gs);
      }
      if (p.dir) row.append(make('span', 'dir', p.dir));
      if (g.key !== 'gone') {
        row.type = 'button';
        row.dataset.key = 'file:' + p.full;
        row.addEventListener('click', () => { closePopup(); openFile(p.full, { preview: true }); });
      }
      el.append(row);
    }
    if (g.more > 0) el.append(make('div', 'mc-more', 'and ' + g.more + ' more'));
    if (g.note) el.append(make('p', 'mc-note', g.note));
  }

  if (b.branch.length) {
    el.append(make('div', 'mc-sec', 'This branch'));
    const list = make('ul', 'mc-facts');
    for (const line of b.branch) {
      const li = make('li', line.dim ? 'dim' : '');
      if (line.age) li.dataset.age = '';
      for (const part of line.parts) li.append(part.code === undefined ? part : make('code', '', part.code));
      list.append(li);
    }
    el.append(list);
  }

  const act = make('div', 'mc-act');
  if (b.action) {
    const run = make('button', 'btn mc-run');
    run.type = 'button';
    run.dataset.key = 'parse';
    // The button is what the card is for: the focus a click gives it goes here
    // and not to the first file, so Enter twice opens no file (openPopup).
    run.dataset.first = '';
    run.append(strokeIcon('0 0 16 16', 'mc-ico', ['M2.5 4l4 4-4 4M8.5 12.25h5']), b.action.label);
    // The 0071 exception, moved here from the badge by 0157: dbt parse reaches
    // no warehouse, so Enter is pressed for the user unless the shell reads the
    // current folder (0130).
    run.addEventListener('click', () => { closePopup(); sendToTerminal('dbt parse', freshnessRuns(S.pathReadsCwd), null, 'the manifest\'s card'); });
    act.append(run, make('span', 'hint', b.action.hint));
  } else if (b.doneOk) {
    const ok = make('span', 'mc-ok');
    ok.append(strokeIcon('0 0 16 16', 'mc-ico', ['M3.5 8.5l3 3 6-7']), b.done);
    act.append(ok);
  } else if (b.done) {
    act.append(make('span', 'hint', b.done));
  }
  if (act.children.length) el.append(act);
}

// ------------------------------------------------------------ environments --
/* Which .env file resolves locations. The choice lives in this tab: the stored
   one is only where a fresh tab starts, so two tabs never draw one environment's
   values under the other's name. */
/* A colour family for an environment name, so the one in use is recognisable
   at a glance. Matched on whole words, trailing digits ignored ("DEV2"), and
   pre-production is checked before production. */
function envTone(name) {
  if (!name) return 'manifest';
  const upper = name.toUpperCase();
  const words = upper.split(/[^A-Z0-9]+/).map((w) => w.replace(/\d+$/, ''));
  const has = (...list) => words.some((w) => list.includes(w));
  if (upper.replace(/[^A-Z]/g, '').includes('PREPROD') || has('UAT', 'ACC', 'ACCEPTANCE')) return 'uat';
  if (has('PROD', 'PRD', 'PRODUCTION', 'LIVE')) return 'prod';
  if (has('STG', 'STAGING', 'STAGE')) return 'stg';
  if (has('QA', 'TEST', 'TST', 'SIT')) return 'qa';
  if (has('DEV', 'DEVELOPMENT', 'LOCAL', 'SANDBOX')) return 'dev';
  if (has('CI')) return 'ci';
  return 'other';
}

function envDisplayName(file) {
  const f = S.envs && S.envs.files.find((e) => e.file === file);
  return f ? f.name : file;
}

/* An environment by its name, in its colour (envTone): a tag, never a dot. */
function envTag(name, tone) {
  const t = Object.assign(document.createElement('span'), { className: 'envtag', textContent: name });
  t.dataset.tone = tone;
  return t;
}

async function loadEnvs() {
  // Re-reading the env list means the .env files were re-read too, so any
  // resolution cached against the old ones is stale.
  dropNodeCache();
  try { S.envs = await api.get('/api/envs'); } catch { S.envs = null; }
  // The stored choice is where a fresh tab starts, and nothing more: after the
  // first load this tab keeps its own.
  if (!S.envsLoaded) {
    S.envsLoaded = true;
    if (S.envs && S.envs.selected) S.env = S.envs.selected;
  }
  paintEnvSelect();
  if (S.node) renderCatalog(S.node);
  // The row on a Compiled or Run tab lists the files shown, which the settings
  // may have just renamed or hidden (0147). Only then: the settings' Project
  // section reloads on every opening, and a repaint would drop the text selected
  // in the SQL and a find's cursor for nothing.
  if (envRowKey() !== S.artifactRow) repaintArtifacts();
}

function paintEnvSelect() {
  const pill = $('#status-env');
  // No location config reads an env var: the selector could change nothing.
  if (!envsInUse()) { pill.classList.add('hidden'); return; }
  const visible = S.envs.files.filter((f) => !f.hidden);
  if (S.env && !visible.some((f) => f.file === S.env)) S.env = '';
  fillEnvPill(pill, 'env', false);
  pill.classList.remove('hidden');
  repaintSettings();
}

/* A button showing the environment in use, coloured by envTone: the Catalog's and
   the status bar's both open the menu (0142). The Catalog's keeps its caret; the
   status bar's has none (0166), the pill being a notch smaller there. */
function fillEnvPill(el, prefix, caret = true) {
  const own = manifestChoice((S.meta && S.meta.sandbox) || '');
  const name = S.env ? envDisplayName(S.env) : own.label;
  el.textContent = '';
  el.dataset.tone = S.env ? envTone(name) : 'manifest';
  if (prefix) el.append(Object.assign(document.createElement('span'), { className: 'envpill-k', textContent: prefix }));
  el.append(document.createTextNode(name));
  if (caret) el.append(Object.assign(document.createElement('span'), { className: 'envpill-caret', textContent: '▾' }));
  const now = S.env ? `Catalog locations are resolved with ${S.env}.` : own.now;
  el.title = `${now} Click to pick an environment.`;
}

/* The visible Compiled or Run tab again from the answer it holds, with no request. */
function repaintArtifacts() {
  ['compiled', 'run'].forEach((kind) => { if (!$('#dock-' + kind).classList.contains('hidden')) paintArtifact(kind, true); });
}

function selectEnv(file) {
  // A click or an arrow on the group of the Compiled or Run pane rebuilds the
  // row it was made in, so the keyboard would lose its place without this (0147, 0164).
  const group = document.activeElement && document.activeElement.closest ? document.activeElement.closest('.envseg') : null;
  const held = group ? group.closest('#compiled-head, #run-head') : null;
  const heldIn = held ? held.id : '';
  S.env = file;
  paintEnvSelect();
  if (S.node) renderCatalog(S.node);
  // The marks follow the environment, painted over the canvas as it stands (0117).
  paintLineageBuilds();
  // So does the SQL of the visible Compiled or Run tab, from the answer it holds
  // (0139), and the buttons on it (0147).
  repaintArtifacts();
  const back = heldIn && $('#' + heldIn + ' .envseg [aria-checked=true]');
  if (back) back.focus();
  // Remembered as the starting point for the next tab; failure is harmless.
  api.send('/api/envs/select', 'POST', { file: file || null }).catch(() => {});
}

/* The environment menu, shared by the status bar pill and the catalog header.
   Opens below its anchor, or above when there is no room (the status bar). */
let envMenu = null;

function closeEnvMenu({ refocus = false } = {}) {
  if (!envMenu) return;
  const { el, anchor, off } = envMenu;
  envMenu = null;
  off();
  el.remove();
  if (refocus && anchor.isConnected) anchor.focus();
}

/* What an environment pick offers: the files shown, then the config as dbt
   parsed it. The menu and the settings' Project section list the same. */
function envChoices() {
  const own = manifestChoice((S.meta && S.meta.sandbox) || '');
  return S.envs.files.filter((e) => !e.hidden).map((f) => ({
    label: f.name + (f.target_mismatch ? ' ⚠' : ''),
    sub: f.file,
    tone: envTone(f.name),
    current: S.env === f.file,
    title: f.target_mismatch ? `DBT_TARGET in ${f.file} is ${f.target}, which does not match the name` : '',
    file: f.file,
  })).concat([{
    label: own.label, sub: own.sub, tone: 'manifest', current: !S.env, title: own.title, file: '',
  }]);
}

/* The choice of no file, which shows the manifest as its target built it. On a
   sandbox manifest that is the developer's own compile, and the name says where
   it is (0143). One place, so the menu, the settings' pick and the pill agree. */
function manifestChoice(sandbox) {
  if (!sandbox) {
    return {
      label: 'manifest', sub: 'as dbt parsed it',
      title: 'the config with the env vars dbt had loaded when it parsed this manifest',
      now: 'Catalog locations are shown as dbt parsed them.',
    };
  }
  return {
    label: 'my compile', sub: `${sandbox}, as dbt wrote it`,
    title: `the Catalog's locations as dbt parsed them, the SQL and the Built column as this manifest's target wrote them, into ${sandbox}`,
    now: `Catalog locations are shown as dbt parsed them, the SQL as your own compile wrote it, into ${sandbox}.`,
  };
}

/* One row of it, coloured by envTone. */
function envRow({ label, sub = '', tone = '', current = false, title = '' }, pick) {
  const b = document.createElement('button');
  b.type = 'button';
  b.setAttribute('role', 'menuitemradio');
  b.setAttribute('aria-checked', String(current));
  b.dataset.key = 'env:' + label;
  if (current) b.classList.add('on');
  if (title) b.title = title;
  const check = Object.assign(document.createElement('span'), { className: 'check', textContent: current ? '✓' : '' });
  b.append(check);
  // The name is the tag: a dot before it said the colour twice.
  const lbl = tone ? envTag(label, tone) : Object.assign(document.createElement('span'), { textContent: label });
  lbl.classList.add('lbl');
  b.append(lbl);
  if (sub) b.append(Object.assign(document.createElement('span'), { className: 'sub', textContent: sub }));
  b.addEventListener('click', pick);
  return b;
}

function openEnvMenu(anchor) {
  const reopen = envMenu && envMenu.anchor === anchor;
  closeEnvMenu();
  if (reopen || !envsInUse()) return;   // a second click on the same anchor closes it

  const el = document.createElement('div');
  el.className = 'envmenu';
  el.setAttribute('role', 'menu');
  const item = (c, pick) => el.appendChild(envRow(c, () => { closeEnvMenu(); pick(); }));
  for (const c of envChoices()) item(c, () => selectEnv(c.file));
  el.appendChild(document.createElement('hr'));
  item({ label: 'Manage environments...' }, () => openSettings('project'));
  document.body.appendChild(el);

  const at = anchor.getBoundingClientRect();
  const box = el.getBoundingClientRect();
  const below = at.bottom + 4 + box.height <= window.innerHeight;
  el.style.top = `${below ? at.bottom + 4 : Math.max(4, at.top - 4 - box.height)}px`;
  el.style.left = `${Math.min(Math.max(4, at.left), window.innerWidth - box.width - 4)}px`;

  const buttons = [...el.querySelectorAll('button')];
  const onKey = (e) => {
    if (e.key === 'Tab') return closeEnvMenu();
    const i = buttons.indexOf(document.activeElement);
    const step = { ArrowDown: 1, ArrowUp: -1 }[e.key];
    if (e.key !== 'Escape' && !step) return;
    // Handled here only: the editor and the global shortcuts never see it.
    e.preventDefault();
    e.stopPropagation();
    if (e.key === 'Escape') closeEnvMenu({ refocus: true });
    else buttons[(i + step + buttons.length) % buttons.length].focus();
  };
  const onDown = (e) => { if (!el.contains(e.target) && !anchor.contains(e.target)) closeEnvMenu(); };
  // Scrolling the anchor away leaves the menu floating in the wrong place. Only
  // a container of the anchor counts: a terminal printing output scrolls too.
  const onScroll = (e) => {
    const t = e.target;
    if (t === document || (t instanceof Node && t.contains(anchor))) closeEnvMenu();
  };
  const onResize = () => closeEnvMenu();
  document.addEventListener('keydown', onKey, true);
  document.addEventListener('mousedown', onDown, true);
  document.addEventListener('scroll', onScroll, true);
  window.addEventListener('resize', onResize);
  envMenu = {
    el, anchor,
    off: () => {
      document.removeEventListener('keydown', onKey, true);
      document.removeEventListener('mousedown', onDown, true);
      document.removeEventListener('scroll', onScroll, true);
      window.removeEventListener('resize', onResize);
    },
  };
  (buttons.find((b) => b.classList.contains('on')) || buttons[0]).focus();
}

/* The named selectors, in a menu beside the Selection box. The environment
   menu's rows with a filter on top, since a project can name dozens. Fetched
   on every open rather than kept: the manifest reloads itself when dbt
   rewrites it, and the list is short. A selector this build cannot resolve is
   listed anyway, with the reason, so dbt ls can still settle it. */
let selectorMenu = null;
let selectorAsk = 0;

function closeSelectorMenu({ refocus = false } = {}) {
  if (!selectorMenu) return;
  const { el, anchor, off } = selectorMenu;
  selectorMenu = null;
  off();
  el.remove();
  if (refocus && anchor.isConnected) anchor.focus();
}

async function openSelectorMenu(anchor) {
  const reopen = selectorMenu && selectorMenu.anchor === anchor;
  closeSelectorMenu();
  const ask = ++selectorAsk;
  if (reopen) return;                         // a second click on the button closes it
  let body;
  try { body = await api.get('/api/selectors'); } catch (e) { toast(e.message, 'err'); return; }
  if (ask !== selectorAsk) return;
  const all = body.selectors || [];

  const el = document.createElement('div');
  el.className = 'envmenu selmenu';
  el.setAttribute('role', 'menu');
  el.setAttribute('aria-label', 'Named selectors');
  const filter = Object.assign(document.createElement('input'), {
    type: 'text', spellcheck: false, autocomplete: 'off',
    placeholder: `Filter ${all.length} selector${all.length === 1 ? '' : 's'}`,
  });
  filter.setAttribute('aria-label', 'Filter the named selectors');
  const rows = Object.assign(document.createElement('div'), { className: 'selrows' });
  el.append(filter, rows);
  for (const note of selectorsNote(body)) {
    el.append(Object.assign(document.createElement('div'), { className: 'selnote', textContent: note }));
  }

  let hits = [];
  let at = 0;
  const pick = (s) => {
    closeSelectorMenu();
    $('#select-input').value = `--selector ${s.name}`;
    clearTimeout(selectTimer);
    runSelection();
  };
  const mark = () => {
    [...rows.children].forEach((b, i) => b.classList.toggle('cur', i === at));
    const cur = rows.children[at];
    if (cur) cur.scrollIntoView({ block: 'nearest' });
  };
  const paint = () => {
    hits = filterSelectors(all, filter.value);
    rows.textContent = '';
    if (!hits.length) {
      const empty = all.length ? 'No selector matches.' : 'This manifest records no selectors.';
      rows.append(Object.assign(document.createElement('div'), { className: 'selempty', textContent: empty }));
      return;
    }
    hits.forEach((s, i) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.setAttribute('role', 'menuitem');
      if (s.unsupported) b.classList.add('off');
      b.title = s.unsupported ? `Cannot be resolved here: ${s.unsupported}` : (s.description || s.name);
      b.append(Object.assign(document.createElement('span'), { className: 'lbl', textContent: s.name }));
      if (s.default) b.append(Object.assign(document.createElement('span'), { className: 'tag', textContent: 'default' }));
      const sub = s.unsupported || s.description;
      if (sub) b.append(Object.assign(document.createElement('span'), { className: 'sub', textContent: sub }));
      b.addEventListener('click', () => pick(s));
      b.addEventListener('mousemove', () => { if (at !== i) { at = i; mark(); } });
      rows.appendChild(b);
    });
    mark();
  };
  filter.addEventListener('input', () => { at = 0; paint(); });
  document.body.appendChild(el);
  paint();
  const place = placeFloating(anchor.getBoundingClientRect(), el.getBoundingClientRect(),
    { width: window.innerWidth, height: window.innerHeight }, 4);
  el.style.top = `${place.top}px`;
  el.style.left = `${place.left}px`;

  const onKey = (e) => {
    if (e.key === 'Tab') return closeSelectorMenu();
    const step = { ArrowDown: 1, ArrowUp: -1 }[e.key];
    if (e.key !== 'Escape' && e.key !== 'Enter' && !step) return;
    // Handled here only: the box, the editor and the global shortcuts never see it.
    e.preventDefault();
    e.stopPropagation();
    if (e.key === 'Escape') closeSelectorMenu({ refocus: true });
    else if (e.key === 'Enter') { if (hits[at]) pick(hits[at]); }
    else if (hits.length) { at = (at + step + hits.length) % hits.length; mark(); }
  };
  const onDown = (e) => { if (!el.contains(e.target) && !anchor.contains(e.target)) closeSelectorMenu(); };
  const onScroll = (e) => {
    const t = e.target;
    if (t === document || (t instanceof Node && t.contains(anchor))) closeSelectorMenu();
  };
  const onResize = () => closeSelectorMenu();
  document.addEventListener('keydown', onKey, true);
  document.addEventListener('mousedown', onDown, true);
  document.addEventListener('scroll', onScroll, true);
  window.addEventListener('resize', onResize);
  selectorMenu = {
    el, anchor,
    off: () => {
      document.removeEventListener('keydown', onKey, true);
      document.removeEventListener('mousedown', onDown, true);
      document.removeEventListener('scroll', onScroll, true);
      window.removeEventListener('resize', onResize);
    },
  };
  filter.focus();
}

/* What each .env file is named and whether the menu shows it, in the
   settings' Project section (0100), from the envs last read. Only real
   overrides are stored: a name equal to the automatic one, or a visibility
   equal to what detection would decide, is sent as "automatic" so later
   detection changes still apply. `saved` runs once a save is read back. */
function envManageForm(saved) {
  const refs = S.envs.referenced;
  const nodesFor = (v) => (refs.find((r) => r.var === v) || { nodes: 0 }).nodes;

  const body = document.createElement('div');
  body.className = 'envpanel';
  const table = document.createElement('table');
  table.className = 'loc';
  const head = document.createElement('tr');
  for (const [label, tip] of [
    ['file', ''],
    ['name', 'leave empty for the automatic name, the uppercased file suffix'],
    ['shown', 'a hidden file is not offered, here or in the Catalog\'s environment menu'],
    ['DBT_TARGET', 'read from the file as a cross-check against the name'],
    ['variables', `how many of the ${refs.length} variables your location config reads this file defines`],
    ['matches manifest', 'how often this file reproduces what dbt parsed. The file dbt had loaded scores 100%.'],
  ]) {
    const th = document.createElement('th');
    th.textContent = label;
    if (tip) th.title = tip;
    head.appendChild(th);
  }
  table.appendChild(head);

  const inputs = [];
  for (const f of S.envs.files) {
    const tr = document.createElement('tr');
    const td = (content, cls) => {
      const cell = document.createElement('td');
      if (cls) cell.className = cls;
      cell.append(content);
      return cell;
    };

    const name = document.createElement('input');
    name.type = 'text';
    name.maxLength = 32;
    name.placeholder = f.auto_name;
    name.value = f.name === f.auto_name ? '' : f.name;

    const shown = document.createElement('input');
    shown.type = 'checkbox';
    shown.checked = !f.hidden;
    const shownCell = td(shown);
    if (f.hidden_reason) shownCell.title = f.hidden_reason;

    const target = document.createElement('span');
    target.textContent = f.target || '-';
    if (f.target_mismatch) {
      target.className = 'env-placeholder';
      target.title = `DBT_TARGET is ${f.target}, which does not match ${f.file}`;
    }

    const cov = f.coverage;
    const vars = document.createElement('span');
    vars.textContent = `${cov.defined}/${refs.length}`;
    const notes = [];
    if (cov.missing.length) notes.push(`missing: ${cov.missing.join(', ')}`);
    if (cov.placeholders.length) {
      notes.push(`placeholder: ${cov.placeholders.map((v) => `${v} (${nodesFor(v)} nodes)`).join(', ')}`);
      vars.className = 'env-placeholder';
    }
    if (cov.missing.length && !cov.placeholders.length) vars.className = 'env-missing';
    if (notes.length) vars.title = notes.join('\n');

    const a = f.agreement;
    const match = document.createElement('span');
    match.textContent = a.checked ? `${Math.round((1000 * a.equal) / a.checked) / 10}%` : '-';
    match.title = a.checked ? `${a.equal} of ${a.checked} env-driven values equal what dbt parsed` : 'no env-driven values to compare';

    tr.append(td(f.file, 'k'), td(name), shownCell, td(target), td(vars), td(match));
    table.appendChild(tr);
    inputs.push({ f, name, shown });
  }
  body.appendChild(table);
  const foot = document.createElement('div');
  foot.className = 'setactions';
  foot.append(Object.assign(document.createElement('span'), {
    className: 'setnote',
    textContent: S.envs.persist
      ? `Saved in ${S.envs.settings_path}, outside the project.`
      : 'No config directory is available, so these settings cannot be saved.',
  }));
  body.appendChild(foot);
  if (!S.envs.persist) return body;

  const save = Object.assign(document.createElement('button'), { type: 'button', className: 'btn sm primary', textContent: 'Save' });
  foot.prepend(save);
  save.addEventListener('click', async () => {
    const envs = {};
    for (const { f, name, shown } of inputs) {
      const typed = name.value.trim();
      const hidden = !shown.checked;
      envs[f.file] = {
        name: typed && typed !== f.auto_name ? typed : null,
        hidden: hidden === !!f.auto_hidden_reason ? null : hidden,
      };
    }
    save.disabled = true;
    try {
      await api.send('/api/envs', 'PUT', { envs });
      await loadEnvs();
      toast('environments saved', 'ok');
      saved();
    } catch (e) {
      toast('could not save: ' + e.message, 'err');
    } finally {
      save.disabled = false;
    }
  });
  return body;
}

/* One row per location key, across the stages dbt goes through. `envFile`
   picks a .env resolution when the node carries one; without it, the resolved
   column is the config as dbt parsed it. Rows empty at every stage are dropped. */
function locationRows(loc, envFile) {
  if (!loc) return [];
  const parsed = loc.parsed || loc.resolved || {};   // payloads before the rename
  const env = envFile && loc.envs ? loc.envs[envFile] : null;
  return ['database', 'schema', 'alias']
    .map((key) => {
      const cell = env && env.status ? env.status[key] : null;
      const row = {
        key,
        written: loc.written[key] || '',
        parsed: parsed[key] || '',
        resolved: (env ? env.place : parsed)[key] || '',
        built: loc.built[key] || '',
        status: cell ? cell.kind : '',
        vars: cell && cell.vars ? cell.vars : [],
        branch: !!(cell && cell.branch),
      };
      row.templated = /\{[{%]/.test(row.written);
      // Moved compares parsed with built, never the selected environment with
      // built: both come from the same parse, so the answer does not change
      // when another environment is picked.
      row.redirected = !!row.parsed && !!row.built && !sameIdent(row.parsed, row.built);
      return row;
    })
    .filter((row) => row.written || row.parsed || row.resolved || row.built);
}

/* Same warehouse identifier: Snowflake folds unquoted names, and dbt Fusion
   drops a pair of literal quotes that the written config may still carry. */
function sameIdent(a, b) {
  const bare = (s) => (s.length > 1 && s[0] === '"' && s[s.length - 1] === '"' ? s.slice(1, -1) : s);
  return bare(a).toLowerCase() === bare(b).toLowerCase();
}

/* Whether dbt built the node into the developer sandbox (0010): its built
   database.schema, lowercased as S.meta.sandbox is, is that one. */
function builtInSandbox(loc, sandbox) {
  return !!sandbox && !!loc && `${loc.built.database}.${loc.built.schema}`.toLowerCase() === sandbox;
}

/* Text, class and tooltip for one resolved cell. `file` is the chosen .env
   file, empty in manifest mode. */
function resolvedCell(row, envName, file) {
  const vars = row.vars.join(', ');
  const branchNote = row.branch
    ? '\nPicked the branch dbt took when it parsed; the condition itself is not evaluated.'
    : '';
  const empty = { text: 'default', cls: 'nul', title: 'not set here, inherited from the target' };
  switch (row.status) {
    case 'missing':
      return { text: `missing ${vars}`, cls: 'env-missing', title: `${vars} is not defined in ${file}` };
    case 'placeholder':
      return {
        text: `${row.resolved || 'empty'} (placeholder)`,
        cls: 'env-placeholder',
        title: `${vars} is set to a placeholder in ${file}, not a real name`,
      };
    case 'unevaluated':
      return {
        text: row.resolved || 'not evaluated',
        cls: 'env-unevaluated',
        title: 'Contains Jinja that dbt-edith does not evaluate.' + branchNote,
      };
    case 'env':
      return { text: row.resolved, cls: '', title: `${vars} from ${file}` + branchNote };
    case 'literal':
      return row.resolved
        ? { text: row.resolved, cls: '', title: `written as a plain value, the same in every environment${branchNote}` }
        : empty;
    case 'parsed':
      return { text: row.resolved, cls: '', title: 'nothing written for this key: value as dbt parsed it' };
    default:
      return row.resolved
        ? { text: row.resolved, cls: '', title: `as dbt parsed it for ${envName || 'this manifest'}` }
        : empty;
  }
}

/* The lines one location key takes in the narrow card (0160): a value written
   once where the stages agree, a line per run of equal stages where they do
   not, so nothing is cut at 280px as a three-column table was. The stages are
   as written, resolved and built, in that order. A stage with nothing in it
   says nothing (not written in this file, not set anywhere), and when
   neither the file nor the config sets the key the target decides, so the
   built value stands alone, dimmed `(default)`. Two stages share a line only
   when their text and their class agree, so a mark such as `env-unevaluated`
   is never lost to a neighbour. A run is labelled by its last stage; a lone
   line has no label. Each title names the stages it stands for.
   `inSandbox`: a move is expected there and only a model built outside the
   sandbox stands out. */
function locationLines(row, envName, file, inSandbox) {
  const rc = resolvedCell(row, envName, file);
  const resolved = rc.cls === 'nul' ? null : rc;
  const moved = row.redirected ? (inSandbox ? 'moved expected' : 'moved') : '';
  const built = row.built
    ? { label: 'built', text: row.built, cls: moved,
      title: row.redirected ? `dbt parsed ${row.parsed}, built in ${row.built}` : 'where the target that produced this manifest built it' }
    : null;
  if (!row.written && !resolved) {
    return built ? [{ label: '', value: built.text, dim: ' (default)', cls: moved, title: 'not set in the config: the target decides, and built it here' }]
      : [{ label: '', value: 'default', dim: '', cls: 'nul', title: 'not set here, inherited from the target' }];
  }
  const stages = [
    row.written && { label: 'written', text: row.written, cls: row.templated ? 'tpl' : '', title: 'the config as it appears in YAML, SQL or dbt_project.yml' },
    resolved && { label: 'resolved', text: resolved.text, cls: resolved.cls, title: resolved.title },
    built,
  ].filter(Boolean);
  const runs = [];
  for (const st of stages) {
    const last = runs[runs.length - 1];
    if (last && last.text === st.text && last.cls === st.cls) { last.names.push(st.label); last.title = st.title; } else runs.push({ text: st.text, cls: st.cls, title: st.title, names: [st.label] });
  }
  const say = (names) => (names.length < 2 ? names[0] : `${names.slice(0, -1).join(', ')} and ${names[names.length - 1]}`);
  return runs.map((r) => ({
    label: runs.length > 1 ? r.names[r.names.length - 1] : '',
    value: r.text, dim: '', cls: r.cls,
    title: r.names.length > 1 ? `${say(r.names)}: ${r.title}` : r.title,
  }));
}

/* A relation name split into its parts, each remembering whether it was
   quoted. Inside quotes, "" stands for one literal quote. */
function splitRelation(text) {
  const parts = [];
  let name = '', quoted = false, inside = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inside) {
      if (ch === '"' && text[i + 1] === '"') { name += '"'; i++; }
      else if (ch === '"') inside = false;
      else name += ch;
    } else if (ch === '"') { inside = true; quoted = true; }
    else if (ch === '.') { parts.push({ name, quoted }); name = ''; quoted = false; }
    else name += ch;
  }
  parts.push({ name, quoted });
  return parts;
}

/* The relation the resolved column points at, quoted part by part the way the
   built relation is, or the reason it cannot be written. Database and schema
   must come from the config: left unset, they fall back to the target profile,
   which dbt-edith does not read. An unset alias is the one dbt built, since dbt
   derives it from the node, not from the environment. */
function resolvedRelation(rows, builtRelation, file) {
  const names = [];
  for (const key of ['database', 'schema', 'alias']) {
    const r = rows.find((row) => row.key === key) || { resolved: '', built: '', status: '', vars: [] };
    const vars = r.vars.join(', ');
    if (r.status === 'missing') return { text: '', reason: `${vars} is not defined in ${file}` };
    if (r.status === 'placeholder') return { text: '', reason: `${key} is a placeholder in ${file}, not a real name` };
    if (r.status === 'unevaluated') return { text: '', reason: `${key} contains Jinja that dbt-edith does not evaluate` };
    if (r.resolved) names.push(r.resolved);
    else if (key === 'alias' && r.built) names.push(r.built);
    // `unset` says it in a flag, so the card need not read this sentence.
    else return { text: '', reason: `${key} is not set in the config, so it comes from the target profile, which dbt-edith does not read`, unset: true };
  }
  const parts = builtRelation ? splitRelation(builtRelation) : [];
  const bare = (s) => (s.length > 1 && s[0] === '"' && s[s.length - 1] === '"' ? s.slice(1, -1) : s);
  const write = (name, i) => (parts.length === 3 && parts[i].quoted
    ? `"${bare(name).replace(/"/g, '""')}"`
    : name);
  return { text: names.map(write).join('.'), reason: '' };
}

/* The relation Snowflake is asked about for a column's lineage, the .env file
   actually used, or why there is none. With no file chosen it is where this
   manifest's target built the node, since that object exists. A chosen file
   gives the relation the Location table resolves, and a file this node was
   not resolved against falls back to the manifest, as that table does. */
function lineageRelation(n, env) {
  if (!n.relation) {
    return { text: '', file: '', reason: n.materialized === 'ephemeral'
      ? `${n.name} is ephemeral, so it is not in the warehouse`
      : `${n.name} has no relation in the warehouse` };
  }
  const file = env && n.location && n.location.envs && n.location.envs[env] ? env : '';
  if (!file) return { text: n.relation, file: '', reason: '' };
  const rel = resolvedRelation(locationRows(n.location, file), n.relation, file);
  return { text: rel.text, file, reason: rel.reason };
}

/* The Compiled and Run tabs for another environment (0139): the SQL dbt left
   under target/ with each relation it holds swapped for the one the Location
   table resolves for the chosen .env file. Nothing is compiled; a relation
   that file cannot place stays as dbt wrote it and is marked. */

/* One relation the SQL can hold, for `env`: the text to write, or why it stays
   as compiled. Beyond what lineageRelation refuses, a relation dbt built
   elsewhere than its config says went through a generate_*_name macro, which
   is not evaluated, so what the file resolves is not where dbt would put it.
   In a sandbox manifest a move of the database or schema into it is the norm,
   the developer target having put every model there, and what the file
   resolves is where the config places it; the sandbox says nothing of an alias
   that moved. When an override reads the target, the finding under the bar
   still says the macro is not evaluated (0143). */
function envArtifactRelation(rel, env, sandbox) {
  const r = lineageRelation(rel, env);
  if (r.reason) return { text: '', reason: r.reason };
  if (env && r.file !== env) return { text: '', reason: `not resolved against ${env}` };
  const inSandbox = builtInSandbox(rel.location, sandbox);
  const moved = locationRows(rel.location, env).some((row) => row.redirected && (row.key === 'alias' || !inSandbox));
  if (moved) {
    return { text: '', reason: 'dbt built it elsewhere than configured, through a macro that is not evaluated' };
  }
  return { text: r.text, reason: '' };
}

/* A relation with `suffix` on its last part, each part quoted as it was. */
function relationWithSuffix(text, suffix) {
  const parts = splitRelation(text);
  const last = parts.length - 1;
  return parts.map((p, i) => {
    const name = i === last ? p.name + suffix : p.name;
    return p.quoted ? '"' + name.replace(/"/g, '""') + '"' : name;
  }).join('.');
}

/* What the editor is given of a file: one line break each, as CodeMirror counts
   them. dbt on Windows writes these files with \r\n, and a position counted
   over two characters per line would drift one character further for every
   line above a relation. */
function artifactContent(info) {
  return (info.content + (info.truncated ? '\n\n-- truncated by dbt-edith\n' : '')).replace(/\r\n?/g, '\n');
}

/* The call a relation was written as in the model, from its node id and name:
   `ref('stg_customers')`, `ref('orders', v=2)` for a versioned model (its name
   carries `.v2`), `source('jaffle_shop', 'raw_orders')` for a source table.
   A source whose own name holds a dot cannot be split back, and is named by the
   node's name alone. */
function relationRef(rel) {
  const parts = String(rel.id || '').split('.');
  if (parts[0] === 'source') {
    return parts.length === 4 ? `source('${parts[2]}', '${parts[3]}')` : `source('${rel.name}')`;
  }
  const m = /^([^.]+)\.v(.+)$/.exec(rel.name);
  if (!m) return `ref('${rel.name}')`;
  return /^\d+(\.\d+)?$/.test(m[2]) ? `ref('${m[1]}', v=${m[2]})` : `ref('${m[1]}', v='${m[2]}')`;
}

/* The hover on a swapped relation: the call it stands for and the environment,
   then what the file dbt wrote had there. */
function swapTitle(swap, envName) {
  return `${swap.ref}, for ${envName}\nwas ${swap.was} as compiled`;
}

/* `content` with each relation in `relations` replaced by the one `env`
   resolves for it. Every occurrence is found first, on identifier boundaries
   and longest first at one position, and the output is built in one pass, so a
   swapped name is never read again: QA to UAT cannot chain. The node's own
   relation is also looked for with the suffixes a run's statement gives it.
   Positions in `swaps` and `kept` are in the returned text, and each carries the
   name of the node whose relation it is, for the hover. `unseen` names the
   parents the SQL never mentions, a node's own relation never being one. */
function envSql(content, relations, env, sandbox = '') {
  const out = { text: content, swaps: [], kept: [], unseen: [], counts: { swapped: 0, kept: 0, same: 0 } };
  if (!env) return out;
  const word = /[A-Za-z0-9_$."]/, tail = /[A-Za-z0-9_$"]/;
  const cands = [];
  relations.forEach((rel, id) => {
    if (!rel.relation) return;
    const to = envArtifactRelation(rel, env, sandbox);
    const forms = [{ from: rel.relation, to: to.text }];
    if (rel.own) {
      ['__dbt_tmp', '__dbt_backup'].forEach((suffix) => forms.push({
        from: relationWithSuffix(rel.relation, suffix), to: to.text ? relationWithSuffix(to.text, suffix) : '',
      }));
    }
    forms.forEach((f) => cands.push({ id, name: rel.name, ref: relationRef(rel), from: f.from, to: f.to, reason: to.reason }));
  });
  const hits = [];
  cands.forEach((c) => {
    for (let at = content.indexOf(c.from); at >= 0; at = content.indexOf(c.from, at + 1)) {
      const end = at + c.from.length;
      if (at > 0 && word.test(content[at - 1])) continue;
      if (end < content.length && tail.test(content[end])) continue;
      hits.push({ at, end, c });
    }
  });
  hits.sort((a, b) => a.at - b.at || (b.end - b.at) - (a.end - a.at));
  const seen = new Set(), swapped = new Set(), kept = new Set(), same = new Set();
  let text = '', read = 0, took = null;
  hits.forEach((h) => {
    // Another entry naming the same table (a source and a model on one
    // relation) found it too: it was seen, though only the first is written.
    if (took && h.at === took.at && h.end === took.end) seen.add(h.c.id);
    if (h.at < read) return;
    took = h;
    seen.add(h.c.id);
    text += content.slice(read, h.at);
    read = h.end;
    const was = h.c.from;
    if (!h.c.to) {
      kept.add(h.c.id);
      out.kept.push({ start: text.length, end: text.length + was.length, name: h.c.name, reason: h.c.reason });
      text += was;
    } else if (h.c.to === was) {
      same.add(h.c.id);
      text += was;
    } else {
      swapped.add(h.c.id);
      out.swaps.push({ start: text.length, end: text.length + h.c.to.length, was, name: h.c.name, ref: h.c.ref });
      text += h.c.to;
    }
  });
  out.text = text + content.slice(read);
  out.counts = { swapped: swapped.size, kept: kept.size, same: same.size };
  relations.forEach((rel, id) => { if (rel.relation && !rel.own && !seen.has(id)) out.unseen.push(rel.name); });
  return out;
}

/* One finding of env_reads as a sentence tail: what it reads. */
function envReadWords(f) {
  switch (f.kind) {
    case 'target': return `reads target.${f.detail}`;
    case 'env_var': return f.detail ? `reads the environment variable ${f.detail}` : 'reads an environment variable';
    case 'warehouse': return `asks the warehouse with ${f.detail}()`;
    case 'incremental': return 'branches on is_incremental(), which depends on the table existing there';
    case 'placing': return 'follows the target to decide where a model builds, which is not evaluated';
    default: return 'reads the environment';
  }
}

/* The note under the line for one environment: its tag, what was swapped in
   bold, the rest of what is known as one sentence, and where the SQL may
   differ beyond its relations. The tag and the bold part are separate so the
   page can set each; nothing says "to <database>", because a swap can move
   relations to several, and the counts and the file are what is known for sure
   (0164). A finding in a macro carries what a click needs to open it. */
function artifactEnvWords(result, envName, file, envReads) {
  const c = result.counts;
  // With something swapped or kept the file follows the bold part as its source;
  // with nothing to swap the bold part is a whole sentence, and the file closes it.
  const rest = [c.swapped || c.kept ? `, read from ${file}` : ` (read from ${file})`];
  if (c.kept) rest.push(`; ${c.kept} kept as compiled`);
  if (result.unseen.length) rest.push(`; ${result.unseen.length} not found in this SQL`);
  let head;
  if (c.swapped) head = `${c.swapped} ${c.swapped === 1 ? 'relation' : 'relations'} swapped`;
  else if (c.kept) head = 'No relation swapped';
  else head = c.same ? 'Every relation reads the same as compiled' : 'No relation in this SQL to swap';
  const findings = (envReads || []).map((f) => ({
    text: f.through
      ? `${f.macro_name}, ${envReadWords(f)}, through ${f.through}`
      : `${f.macro_id ? f.macro_name : 'this model'}, line ${f.line}, ${envReadWords(f)}`,
    macro: f.macro_id && f.file ? { file: f.file, name: f.macro_name, line: f.line || 1 } : null,
  }));
  return {
    tag: envName,
    head,
    rest: rest.join('') + '.',
    differ: findings.length ? `May differ beyond its relations (${findings.length})` : '',
    findings,
  };
}

/* The note when no .env file is picked: nothing is swapped, so it says whose
   placement the SQL carries. On a sandbox manifest that is the developer's own
   compile, named as the menu names it (0143). */
function artifactOwnWords(sandbox) {
  return sandbox
    ? { tag: '', head: 'As your own compile wrote it,', rest: ` into ${sandbox}, nothing swapped.`, differ: '', findings: [] }
    : { tag: '', head: 'As dbt compiled it.', rest: ' The relations are the manifest\'s own, nothing swapped.', differ: '', findings: [] };
}

/* Where a key moves the picked one in a radio group of `count` from `at`: the
   arrows step and wrap, Home and End go to the ends; -1 for any other key. */
function radioStep(at, count, key) {
  if (key === 'ArrowRight' || key === 'ArrowDown') return (at + 1) % count;
  if (key === 'ArrowLeft' || key === 'ArrowUp') return (at + count - 1) % count;
  if (key === 'Home') return 0;
  if (key === 'End') return count - 1;
  return -1;
}

/* True when switching environment can change something on screen. */
function envsInUse() { return !!(S.envs && S.envs.referenced.length); }

/* The choice in effect: a stored one outlives the environments in use (the list
   failed to load, or no config reads an env var any more), and then nothing
   could name the file, so the tab, the Catalog's location and the Builds marks
   all fall back to the manifest's own. */
function activeEnv() { return envsInUse() ? S.env : ''; }

/* The radio group on the Compiled and Run tabs is drawn when there is a file
   to pick: a project that reads env_var with a default and has no .env file, or
   hides them all, has nothing to offer (0147). */
function envRowShown() { return envsInUse() && S.envs.files.some((f) => !f.hidden); }

/* What the radio group and the swap are drawn from, to tell a reload that
   changed them from one that did not. */
function envRowKey() {
  return JSON.stringify([!!S.envs, envsInUse(), envRowShown(), activeEnv(),
    S.envs ? S.envs.files.map((f) => [f.file, f.name, !!f.hidden, !!f.target_mismatch, f.target]) : []]);
}

/* The last build of each model per environment is read on a click from the
   tables of the dbt_artifacts package (0117). The pure part runs from here to
   catalogLocation, which web/tests/builds.js slices with the location code
   above: where the two tables are in each environment, what the rows of a
   model add up to, and how that reads on a box. */

/* The package's two models the read joins, by their ids in the manifest. A
   function, not a constant, which a harness's eval would not keep. */
function buildsIds() {
  return { executions: 'model.dbt_artifacts.model_executions', invocations: 'model.dbt_artifacts.invocations' };
}

/* Where the two tables are in the manifest's own build ('') and in each .env
   file, each placed the way the Location table places any relation. A file
   that cannot place them carries why and is shown, not asked: the package's
   schema comes from config before generate_schema_name runs, so a placement
   the table could not make would be a guess (0113). */
function buildsTargets(execNode, invNode, envFiles, manifestName = 'manifest') {
  const envs = [{ env: '', name: manifestName, target: '' }]
    .concat((envFiles || []).map((f) => ({ env: f.file, name: f.name || f.file, target: f.target || '' })));
  return envs.map(({ env, name, target }) => {
    const place = (n, table) => {
      if (!n) return { text: '', reason: `${table} is not in the manifest` };
      const rel = lineageRelation(n, env);
      if (rel.reason) return { text: '', reason: rel.reason };
      // A file the package's model was not resolved against falls back to the
      // built relation there, which says nothing about this environment.
      if (env && rel.file !== env) return { text: '', reason: `${table} was not resolved against ${env}` };
      return { text: rel.text, reason: '' };
    };
    const exe = place(execNode, 'model_executions'), inv = place(invNode, 'invocations');
    const reason = exe.reason || inv.reason;
    return { env, name, target, executions: reason ? '' : exe.text, invocations: reason ? '' : inv.text, reason };
  });
}

/* One query per distinct pair of tables, with the environments it answers for:
   two files that place the package in one schema are read once. */
function buildsQueries(targets) {
  const byKey = new Map();
  for (const t of targets) {
    if (t.reason) continue;
    const key = t.executions + '\n' + t.invocations;
    if (!byKey.has(key)) byKey.set(key, { executions: t.executions, invocations: t.invocations, envs: [] });
    byKey.get(key).envs.push(t.env);
  }
  return [...byKey.values()];
}

/* The rows of an answer by node id: one per target that built it. */
function buildsByNode(rows) {
  const by = new Map();
  for (const r of rows || []) {
    if (!by.has(r.node)) by.set(r.node, []);
    by.get(r.node).push(r);
  }
  return by;
}

/* The rows of a file that sets DBT_TARGET: only the runs under that target,
   since dbt runs with it when the file is loaded (0117). A model left with
   none is dropped, so it reads as not built there. A new map: the answer is
   shared by every file that placed the tables in the same schema. */
function buildsOfTarget(rowsByNode, target) {
  const out = new Map();
  for (const [id, rows] of rowsByNode) {
    const kept = rows.filter((r) => r.target === target);
    if (kept.length) out.set(id, kept);
  }
  return out;
}

/* The names of the targets a table holds runs of besides `target`, sorted, for
   the note that says which runs a file kept to its target left out. A file
   whose DBT_TARGET no run used (an orchestrator's own target name, or a value
   left unexpanded) would otherwise read as never built (0117). */
function buildsOtherTargets(rowsByNode, target) {
  const names = new Set();
  for (const rows of rowsByNode.values()) {
    for (const r of rows) if (r.target && r.target !== target) names.add(r.target);
  }
  return [...names].sort();
}

/* That note, or nothing: what an environment kept to `target` left out of its
   rows, `rows` being how many models it kept runs of. */
function buildsOthersNote(target, others, rows) {
  if (!target || !others || !others.length) return '';
  const names = others.join(', ');
  return rows
    ? `The table also holds runs under target ${names}, not counted here.`
    : `No run under target ${target} in the table, which holds runs under ${names}: not counted.`;
}

/* When a run happened, the clock the script orders by: the end of the model,
   else its start (a model that failed while it ran has no end), else the
   invocation's, which is the earliest the run can have been. */
function buildsWhen(r) {
  return r.completed || r.compiled || r.started || '';
}

/* An environment as the Reports section and the Catalog name it: the target
   its file keeps the runs to, when it sets one. */
function buildsEnvLabel(t) {
  return t.target ? `${t.name} · target ${t.target}` : t.name;
}

/* buildsEnvLabel laid out: the name as its tag, the target it is kept to after
   it, with the " · " the label has so that copied text reads the same. */
function buildsEnvHead(t) {
  const tag = envTag(t.name, t.env ? envTone(t.name) : 'manifest');
  return t.target ? [tag, jel('span', 'muted', ` · target ${t.target}`)] : [tag];
}

/* The same as one box, for a table's head or a tile's label, where the tag and
   the target sit side by side whatever lays them out. */
function buildsEnvHeading(t) {
  const box = jel('span', 'envhead');
  box.append(...buildsEnvHead(t));
  return box;
}

/* What a run that did not end well is called. Skipped is not one: it built
   nothing that time, and the last success still decides. A partial success is
   one (dbt 1.9's microbatch): some of the batches failed, so the table is
   missing rows. */
function buildsFailed(status) {
  return ['error', 'fail', 'runtime error', 'partial success'].includes(status);
}

/* One model in one environment: error when its last attempt failed, stale
   when its last success is older than `staleDays` or there is none in the
   window, ok, or none when no run is recorded. `now` is in milliseconds. */
function buildVerdict(rows, staleDays, now) {
  const list = rows || [];
  if (!list.length) return { verdict: 'none', last: null, success: '' };
  const at = (r) => Date.parse(buildsWhen(r)) || 0;
  const last = list.reduce((a, b) => (at(b) > at(a) ? b : a));
  let success = list.map((r) => r.last_success || '').reduce((a, b) => (Date.parse(b) > (Date.parse(a) || 0) ? b : a), '');
  if (!success && last.status === 'success') success = buildsWhen(last);
  if (buildsFailed(last.status)) return { verdict: 'error', last, success };
  const t = Date.parse(success);
  const old = !(t > 0) || now - t > staleDays * 86400000;
  return { verdict: old ? 'stale' : 'ok', last, success };
}

/* The same for a model one table holds runs of several targets for: each
   target is judged on its own, and the worst of them is the model's, in the
   order error, stale, none, ok, since a box has room for one colour. `parts`
   keeps each, by target name, for the words a box's hover card lists. */
function buildsWorst(rows, staleDays, now) {
  const by = new Map();
  for (const r of rows || []) {
    const key = r.target || '';
    if (!by.has(key)) by.set(key, []);
    by.get(key).push(r);
  }
  if (!by.size) return buildVerdict([], staleDays, now);
  const parts = [...by.keys()].sort().map((k) => buildVerdict(by.get(k), staleDays, now));
  const rank = { error: 0, stale: 1, none: 2, ok: 3 };
  const worst = parts.reduce((a, b) => (rank[b.verdict] < rank[a.verdict] ? b : a));
  return Object.assign({}, worst, { parts });
}

/* How long ago, in the words the cache ages use. */
function buildsAge(iso, now) {
  const t = Date.parse(iso || '');
  if (!(t > 0)) return '';
  const secs = Math.max(0, Math.floor((now - t) / 1000));
  if (secs < 60) return 'just now';
  if (secs < 3600) return `${Math.floor(secs / 60)}min ago`;
  if (secs < 86400) return `${Math.floor(secs / 3600)}h ago`;
  return `${Math.floor(secs / 86400)}d ago`;
}

/* What "no run" says: under which target when the environment was kept to
   one, since the table may hold runs of others (0117). */
function buildsNoRun(target) {
  return `no run ${target ? `under target ${target}` : 'recorded'} in the last ${buildsWindowDays()} days`;
}

/* The line a mark's hover card and a Catalog row open with: the last attempt,
   and the last success when it was not that one. `kept` is the target the
   environment was kept to, if any. */
function buildsSaid(v, envName, now, kept) {
  if (v.parts && v.parts.length > 1) return v.parts.map((p) => buildsSaid(p, envName, now, kept)).join('\n');
  if (v.verdict === 'none') return `${envName}: ${buildsNoRun(kept)}`;
  const l = v.last;
  const target = l.target ? ` (target ${l.target})` : '';
  const head = `${envName}: ${l.status || 'unknown'} ${buildsAge(buildsWhen(l), now)}${target}`;
  const apart = v.success && (buildsFailed(l.status) || l.status === 'skipped' || v.verdict === 'stale');
  return apart ? `${head}, last success ${buildsAge(v.success, now)}` : head;
}

/* The same without the environment's name, each target's line in one: a line
   of a list under that environment's own heading. */
function buildsSaidBare(v, envName, now, kept) {
  return buildsSaid(v, envName, now, kept).split('\n').map((l) => l.replace(`${envName}: `, '')).join(' · ');
}

/* The days of runs the script reads, which a "no run" answer is about. */
function buildsWindowDays() {
  return 90;
}

/* What the canvas paints for one environment: `of(id)` gives the worst
   verdict across a model's targets and its words, or "none" for a model the
   read has no rows for. Judged when a box asks, once each, since a canvas
   draws a few boxes of a read that may hold every model. Null when that
   environment was not read, or was read with an error, so a canvas never says
   "no run" of a table it could not ask. */
function buildsDots(read, env, staleDays, envName, now) {
  const got = read && read.byEnv && read.byEnv[env];
  if (!got || got.error || !got.rows) return null;
  const memo = new Map();
  return {
    of(id) {
      if (!memo.has(id)) {
        const v = buildsWorst(got.rows.get(id), staleDays, now);
        memo.set(id, { verdict: v.verdict, title: buildsSaid(v, envName, now, got.target) });
      }
      return memo.get(id);
    },
  };
}

/* The Reports section's numbers and lists for one environment: the models
   whose last attempt failed, the stale ones, those with no run, and how many
   are fine. `models` is the project's list ({id, name, package}), `own` the
   package to count, or '' for all of them. */
function buildsVerdicts(got, models, own, staleDays, now) {
  const out = { error: [], stale: [], none: [], ok: [], total: 0 };
  if (!got || got.error || !got.rows) return out;
  for (const m of models) {
    if (own && m.package !== own) continue;
    const v = buildsWorst(got.rows.get(m.id), staleDays, now);
    out[v.verdict].push(Object.assign({ v }, m));
    out.total++;
  }
  const byAge = (a, b) => (Date.parse(a.v.success) || 0) - (Date.parse(b.v.success) || 0);
  out.stale.sort(byAge);
  return out;
}

/* ------------------------------------------------------ builds by job -- */
/* Each job's models against the same read, judged by the job's own clock
   (0119). Pure, so web/tests/jobbuilds.js slices it with the code above. */

/* A cron expression as sets of what each field allows, or null for what this
   cannot walk (L, W, #, six fields, @once, @continuous): the caller then
   judges the job on the global threshold. Five fields, `*`, lists, ranges,
   `/n` steps, month and weekday names, Sunday as 0 or 7, Airflow's presets,
   and `?` for a day. A weekday step runs to 6, Sunday being 7 only where it
   is written. A day of the month and a day of the week are read the way
   croniter, which Airflow uses, reads them: a field is unrestricted when it
   is `*` or `?`, or when it spans its whole range and the other field has a
   `*` in it (every other day of the month with any weekday is every other
   day, every other weekday with any day every other weekday); both
   restricted match either.
   `fixed` is a cron whose hour field is not every hour, which Airflow (2.7
   and later) places on the wall clock of its zone rather than counts in
   elapsed time; only a cron that runs every hour counts elapsed time. */
function cronFields(expr) {
  const cache = cronFields.cache || (cronFields.cache = new Map());
  const key = String(expr || '');
  if (!cache.has(key)) cache.set(key, cronParse(key));
  return cache.get(key);
}

function cronParse(expr) {
  const presets = { '@hourly': '0 * * * *', '@daily': '0 0 * * *', '@midnight': '0 0 * * *', '@weekly': '0 0 * * 0',
    '@monthly': '0 0 1 * *', '@quarterly': '0 0 1 */3 *', '@yearly': '0 0 1 1 *', '@annually': '0 0 1 1 *' };
  let text = String(expr || '').trim();
  if (text.startsWith('@')) text = presets[text.toLowerCase()] || '';
  const parts = text.split(/\s+/);
  if (parts.length !== 5) return null;
  // `?` is `*` for a day, which is the only place croniter takes it.
  parts[2] = parts[2] === '?' ? '*' : parts[2];
  parts[4] = parts[4] === '?' ? '*' : parts[4];
  const months = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
  const days = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
  // `open` is where a range with no end runs to: the weekday's is 6.
  const parse = (field, min, max, names, first, open) => {
    const out = new Set();
    for (const item of field.split(',')) {
      const m = /^(\*|[a-z0-9]+(?:-[a-z0-9]+)?)(?:\/(\d+))?$/i.exec(item);
      if (!m) return null;
      const num = (t) => {
        if (/^\d+$/.test(t)) return Number(t);
        const at = names ? names.indexOf(t.toLowerCase()) : -1;
        return at < 0 ? NaN : at + first;
      };
      const end = open === undefined ? max : open;
      let lo = min, hi = end;
      if (m[1] !== '*') {
        const [a, b] = m[1].split('-');
        lo = num(a);
        hi = b === undefined ? (m[2] ? end : lo) : num(b);
      }
      const step = m[2] === undefined ? 1 : Number(m[2]);
      if (!(lo >= min && hi <= max && lo <= hi && step >= 1)) return null;
      for (let v = lo; v <= hi; v += step) out.add(v);
    }
    return out;
  };
  const minute = parse(parts[0], 0, 59), hour = parse(parts[1], 0, 23), dom = parse(parts[2], 1, 31);
  const month = parse(parts[3], 1, 12, months, 1), dow = parse(parts[4], 0, 7, days, 0, 6);
  if (!minute || !hour || !dom || !month || !dow) return null;
  if (dow.delete(7)) dow.add(0);
  const domAny = parts[2] === '*' || (dom.size === 31 && parts[4].includes('*'));
  const dowAny = parts[4] === '*' || (dow.size === 7 && parts[2].includes('*'));
  return { minute, hour, dom, month, dow, domAny, dowAny, fixed: hour.size < 24 };
}

/* A zone's wall clock at an instant, as if it were UTC, through a formatter
   made once per zone: building one costs far more than using it. */
function zoneWall(tz, ms) {
  const cache = zoneWall.cache || (zoneWall.cache = new Map());
  if (!cache.has(tz)) {
    cache.set(tz, new Intl.DateTimeFormat('en-US', { timeZone: tz, hourCycle: 'h23', year: 'numeric', month: 'numeric',
      day: 'numeric', hour: 'numeric', minute: 'numeric' }));
  }
  const p = {};
  for (const x of cache.get(tz).formatToParts(new Date(ms))) p[x.type] = Number(x.value);
  return Date.UTC(p.year, p.month - 1, p.day, p.hour % 24, p.minute);
}

/* Whether this browser knows the zone's name. */
function zoneKnown(tz) {
  try { zoneWall(tz || 'UTC', 0); return true; } catch (e) { return false; }
}

/* The last time the cron fires at or before `beforeMs`, in milliseconds, read
   on the wall clock of `tz`; null when none is found within the bound or the
   zone is not known. It walks back by what does not match, a month, a day, an
   hour, then minutes, so a daily job costs a few steps. Where a clock changes
   it does what Airflow does. A cron whose hour is not every hour is placed
   on the wall clock: a time the clock repeats fires once, at its later
   instant, and one it skips fires shifted forward by the gap (01:30 on the
   night the clocks go forward is 02:30). A cron that runs every hour counts
   in elapsed time, so a wall time that does not exist is passed over and one
   that happens twice fires at both instants. */
function cronPrevious(fields, tz, beforeMs) {
  if (!fields) return null;
  const zone = tz || 'UTC';
  const minute = 60000, day1 = 86400000;
  let wall;
  // Begun two hours past the wall clock of that instant: where a clock was put
  // back, the first pass over an hour lies ahead of the wall time of the
  // second, and `instants` leaves out whatever is after `beforeMs`.
  try { wall = Math.floor(zoneWall(zone, beforeMs) / minute) * minute + 2 * 3600000; } catch (e) { return null; }
  const instants = (w) => {
    // The offset before and after: a day either side is past any change.
    const before = w - (zoneWall(zone, w - day1) - (w - day1)), after = w - (zoneWall(zone, w + day1) - (w + day1));
    const real = [...new Set([before, after])].filter((t) => zoneWall(zone, t) === w).sort((a, b) => b - a);
    // One time of day: the later of the instants it happens at, and for a wall
    // time that never happened the one the offset before the gap gives.
    const found = fields.fixed ? [real.length ? real[0] : Math.max(before, after)] : real;
    return found.filter((t) => t <= beforeMs);
  };
  // Where a clock was put back, a wall time earlier than the one found can be
  // the later instant, so the walk goes on two hours of wall time past the
  // first match and keeps the latest instant of them.
  let best = null, floor = 0;
  for (let i = 0; i < 12000; i++) {
    if (best !== null && wall < floor) return best;
    const d = new Date(wall);
    const y = d.getUTCFullYear(), mo = d.getUTCMonth(), day = d.getUTCDate(), h = d.getUTCHours();
    if (!fields.month.has(mo + 1)) { wall = Date.UTC(y, mo, 1) - minute; continue; }
    const byDom = fields.dom.has(day), byDow = fields.dow.has(d.getUTCDay());
    const dayOk = fields.domAny && fields.dowAny ? true : fields.domAny ? byDow : fields.dowAny ? byDom : byDom || byDow;
    if (!dayOk) { wall = Date.UTC(y, mo, day) - minute; continue; }
    if (!fields.hour.has(h)) { wall = Date.UTC(y, mo, day, h) - minute; continue; }
    if (!fields.minute.has(d.getUTCMinutes())) { wall -= minute; continue; }
    const at = instants(wall);
    if (at.length) {
      if (best === null) floor = wall - 2 * 3600000;
      best = best === null ? at[0] : Math.max(best, at[0]);
    }
    wall -= minute;
  }
  return best;
}

/* What a job's own clock is: its cron read in its source's zone, UTC when the
   source names none and for dbt Cloud. Null for a job without one of its own
   (manual, CI, merge, an asset or another job starting it), for one whose
   start is not read (a templated trigger), and for one this cannot walk,
   which are judged on the global threshold. */
function jobClock(job) {
  if (!job || !job.cron || !job.scheduled) return null;
  const fields = cronFields(job.cron);
  const tz = job.kind === 'airflow' ? (job.timezone || 'UTC') : 'UTC';
  if (!fields || !zoneKnown(tz)) return null;
  return { fields, tz, said: `${job.cron} ${tz}` };
}

/* The last two fires of a clock before `now`, worked out once and kept on the
   clock: a section judges a job in each environment against the same two. */
function jobFires(clock, now) {
  if (!clock) return null;
  if (clock.at !== now) {
    clock.at = now;
    clock.last = cronPrevious(clock.fields, clock.tz, now);
    clock.before = clock.last === null ? null : cronPrevious(clock.fields, clock.tz, clock.last - 1);
  }
  return clock;
}

/* Why a job with a cron is not judged on it, for a tooltip; '' when it is, or
   when it has none to speak of. */
function jobClockWhy(job) {
  if (!job || !job.cron || jobClock(job)) return '';
  if (!job.scheduled) return job.schedule_unread ? 'Whether it runs on its cron is not read.' : 'Nothing starts it on its cron.';
  const tz = job.kind === 'airflow' ? (job.timezone || 'UTC') : 'UTC';
  return zoneKnown(tz) ? `${job.cron} is a cron this cannot read.` : `${tz} is not a time zone this browser knows.`;
}

/* The words for a time in the job's zone: 2026-10-26 05:00 Europe/London. */
function zoneStamp(ms, tz) {
  const d = new Date(zoneWall(tz || 'UTC', ms));
  const two = (n) => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}-${two(d.getUTCMonth() + 1)}-${two(d.getUTCDate())} ${two(d.getUTCHours())}:${two(d.getUTCMinutes())} ${tz || 'UTC'}`;
}

/* The same as a person says it, with the day when the job does not run daily
   or hourly: "05:00 Europe/London", else "Mon 26 Oct 05:00 Europe/London";
   `bare` leaves the zone out, which the schedule cell says once. */
function zoneClock(ms, tz, dated, bare) {
  const d = new Date(zoneWall(tz || 'UTC', ms));
  const two = (n) => String(n).padStart(2, '0');
  const time = `${two(d.getUTCHours())}:${two(d.getUTCMinutes())}${bare ? '' : ' ' + (tz || 'UTC')}`;
  if (!dated) return time;
  const names = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return `${names[d.getUTCDay()]} ${d.getUTCDate()} ${months[d.getUTCMonth()]} ${time}`;
}

/* "N of M built since the start", the start named with its day unless the
   job runs at least daily and that start is the last day's (a day and an
   hour, for a clock that changed): a weekday job on a Sunday says Friday.
   The zone is the schedule cell's to say. */
function jobSinceText(res, tz) {
  const c = res.counts, day = 25 * 3600000;
  return `${c.since} of ${c.total} since ${zoneClock(res.last, tz, res.last - res.before > day || res.at - res.last > day, true)}`;
}

/* A job's models as the page judges them, from what the server sends: the
   steps that run models, each with the ids (by position in the table `ids`)
   of the models it runs. Each model comes with the numbers of the steps that
   run it, in id order. */
function jobBuildsJobs(ids, jobs) {
  return (jobs || []).map((j) => {
    const by = new Map();
    for (const s of j.by_step || []) {
      for (const m of s.models) {
        if (!by.has(m)) by.set(m, []);
        by.get(m).push(s.n);
      }
    }
    const models = [...by.keys()].sort((a, b) => a - b).map((m) => ({ id: ids[m], steps: by.get(m) }));
    return Object.assign({}, j, { models, step_names: (j.by_step || []).map((s) => ({ n: s.n, name: s.name })) });
  });
}

/* What tells apart jobs that share a name (a dbt Cloud job in two projects, a
   dag_id in two sources), by job: the source, then the job's identifier as the
   Jobs tab writes it (`[[ident]]`) or its file, then its line, then its
   place in the list (two sources of one label over one file). Only the jobs
   sharing a name have one, and each the shortest that is its own. */
function jobsTwinTags(jobs) {
  const count = (key) => {
    const by = new Map();
    for (const j of jobs) by.set(key(j), (by.get(key(j)) || 0) + 1);
    return (j) => by.get(key(j));
  };
  const named = count((j) => j.name), inSource = count((j) => `${j.name}\u0000${j.source}`);
  const inFile = count((j) => `${j.name}\u0000${j.source}\u0000${j.ident || j.file}`);
  const inLine = count((j) => `${j.name}\u0000${j.source}\u0000${j.file}:${j.line}`);
  const out = new Map();
  for (const j of jobs) {
    if (named(j) < 2) continue;
    const here = `${j.source} · ${j.file}:${j.line}`;
    out.set(j, inSource(j) < 2 ? j.source : inFile(j) < 2 ? `${j.source} · ${j.ident ? `[[${j.ident}]]` : j.file}`
      : inLine(j) < 2 ? here : `${here} · #${jobs.indexOf(j) + 1}`);
  }
  return out;
}

/* The target a job's runs are kept to: the one it names, none when it names
   none or one only the vars file knows (Jinja, which no run is recorded
   under). */
function jobTarget(job) {
  const t = (job && job.target) || '';
  return t.includes('{{') || t.includes('{%') ? '' : t;
}

/* Why an environment says nothing of a job: it keeps the runs of one target
   (its file sets DBT_TARGET) and the job runs under another, so every model
   would read as not built. '' when the two agree or either names none. */
function jobBuildsTargetClash(job, got) {
  const target = jobTarget(job);
  return got && got.target && target && got.target !== target
    ? `runs under target ${target}; this environment keeps ${got.target}` : '';
}

/* How a job's models stand in one environment. `job.models` are `{id, steps}`
   with the node id in full. With a clock, a model is late when no success
   came since the fire before the last one, so a whole scheduled run went by
   without building it; a run that began at the last fire may still be going,
   and no file says how long it takes, so whether a model was built since that
   fire is only counted, never an alarm. Without one, late is no success
   within `staleDays`. Error is a last attempt that failed and not built is no
   row in the window, as in buildVerdict. A job that names a target is judged
   on that target's runs alone, and says nothing of an environment kept to
   another. `worst` is a map the caller keeps for one answer and one day
   count, so a model several jobs run is judged once per target. */
function jobBuildVerdicts(job, got, clock, staleDays, now, worst) {
  const rank = { error: 0, late: 1, none: 2, ok: 3 };
  const counts = { error: 0, late: 0, none: 0, ok: 0, since: 0, total: 0 };
  const clash = jobBuildsTargetClash(job, got);
  if (clash) return { items: [], counts, tone: 'none', basis: '', last: null, before: null, at: now, clash };
  const fires = jobFires(clock, now);
  // A cron with no fire before the last leaves no earlier run to hold a model
  // to: the global threshold then.
  const judged = fires && fires.before !== null ? fires : null;
  const items = [];
  const target = jobTarget(job);
  for (const m of job.models || []) {
    const key = `${target}\u0000${m.id}`;
    let v = worst && worst.get(key);
    if (!v) {
      const all = (got && got.rows && got.rows.get(m.id)) || [];
      v = buildsWorst(target ? all.filter((r) => r.target === target) : all, staleDays, now);
      if (worst) worst.set(key, v);
    }
    let bad = null, verdict = '';
    const parts = v.parts && v.parts.length ? v.parts : [v];
    for (const p of parts) {
      const at = Date.parse(p.success);
      let late = p.verdict;
      if (late !== 'error' && late !== 'none') late = (judged ? !(at >= judged.before) : p.verdict === 'stale') ? 'late' : 'ok';
      if (bad === null || rank[late] < rank[verdict]) { bad = p; verdict = late; }
    }
    // Built since the start only where every target was, as the verdict is the
    // worst target's: another target's build is not this one's.
    const since = !!judged && parts.every((p) => Date.parse(p.success) >= judged.last);
    items.push({ id: m.id, steps: m.steps || [], verdict, since, v, worst: bad });
    counts[verdict]++;
    counts.total++;
    if (since) counts.since++;
  }
  const tone = counts.error ? 'error' : counts.late ? 'late' : counts.none ? 'none' : 'ok';
  items.sort((a, b) => rank[a.verdict] - rank[b.verdict] || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  return { items, counts, tone, basis: judged ? 'clock' : 'threshold', last: judged ? judged.last : null, before: judged ? judged.before : null, at: now, clash: '' };
}

function catalogLocation(body, n, inCard = false) {
  // A chosen file this node was not resolved against (none discovered at the
  // time, or the file was removed) quietly falls back to manifest mode.
  const chosen = activeEnv();
  const file = chosen && n.location && n.location.envs && n.location.envs[chosen] ? chosen : '';
  const envName = file ? envDisplayName(file) : '';
  const rows = locationRows(n.location, file);
  if (!rows.length) return;
  // In a sandbox manifest every model is built away from its config, so a move
  // is expected there and only a model built outside the sandbox stands out.
  const sandbox = (S.meta && S.meta.sandbox) || '';
  const inSandbox = builtInSandbox(n.location, sandbox);
  const title = h3('location');
  // In the space's card the environment is picked beside the heading, as the
  // design draws it, where the table keeps it in its resolved column (0160).
  const pill = envsInUse() && file === S.env;
  // Beside the heading rather than in the relation row, which an ephemeral
  // model lacks: copying what it reads is just what developing one needs
  // (0058). Under the table, it sat a whole table lower. A sibling of the
  // heading rather than inside it, so the heading still reads "location"
  // alone.
  if (S.features && S.features.snowflake && ['model', 'seed', 'snapshot'].includes(n.kind) && !n.disabled) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'btn sm sfopen clonebtn';
    b.dataset.tool = 'snowflake';
    b.title = `write the statements that copy ${n.name} and its direct parents from an environment into your schema, for you to run`;
    b.append(snowflakeIcon(), document.createTextNode('Clone into my schema'));
    b.addEventListener('click', () => openClonePlan(n));
    const row = document.createElement('div');
    row.className = 'sechead';
    row.append(title, b);
    if (inCard) title.after(locationPill(pill));
    body.appendChild(row);
  } else if (inCard) {
    const row = document.createElement('div');
    row.className = 'sechead';
    row.append(title, locationPill(pill));
    body.appendChild(row);
  } else {
    body.appendChild(title);
  }
  if (inCard) {
    body.appendChild(locationList(rows, n, { file, envName, inSandbox, pill }));
    locationFoot(body, rows, { file, envName, inSandbox });
    return;
  }

  const table = document.createElement('table');
  table.className = 'loc';
  const head = document.createElement('tr');
  // The environment switch sits in the header of the column it changes. It
  // shows only when this node follows the choice, so its label never differs
  // from the values underneath.
  for (const [label, tip] of [
    ['', ''],
    ['as written', 'the config as it appears in YAML, SQL or dbt_project.yml'],
    file
      ? [pill ? 'resolved' : `resolved (${envName})`, `the config evaluated with ${file} alone, before the generate_*_name macros`]
      : [pill ? 'resolved' : 'resolved (manifest)', 'the config with the env vars dbt had loaded when it parsed this manifest, '
        + 'before the generate_*_name macros. Not necessarily any particular environment.'],
    ['built (manifest)', 'where the target that produced this manifest actually built it'],
  ]) {
    const th = document.createElement('th');
    th.textContent = label;
    if (tip) th.title = tip;
    head.appendChild(th);
  }
  if (pill) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'envpill sm';
    b.setAttribute('aria-haspopup', 'menu');
    fillEnvPill(b, '');
    b.addEventListener('click', () => openEnvMenu(b));
    head.children[2].append(b);
  }
  table.appendChild(head);

  const cell = (value, cls) => {
    const td = document.createElement('td');
    if (value) {
      td.textContent = value;
      if (cls) td.className = cls;
    } else {
      td.textContent = 'default';
      td.className = 'nul';
      td.title = 'not set here, inherited from the target';
    }
    return td;
  };
  for (const r of rows) {
    const tr = document.createElement('tr');
    const k = document.createElement('td');
    k.className = 'k';
    k.textContent = r.key;
    const built = cell(r.built, r.redirected ? (inSandbox ? 'moved expected' : 'moved') : '');
    if (r.redirected) built.title = `dbt parsed ${r.parsed}, built in ${r.built}`;
    const rc = resolvedCell(r, envName, file);
    const resolved = document.createElement('td');
    resolved.textContent = rc.text;
    if (rc.cls) resolved.className = rc.cls;
    resolved.title = rc.title;
    tr.append(k, cell(r.written, r.templated ? 'tpl' : ''), resolved, built);
    table.appendChild(tr);
  }
  // Ephemeral models have no relation, in any environment.
  if (n.relation) {
    const tr = document.createElement('tr');
    tr.className = 'rel';
    const k = document.createElement('td');
    k.className = 'k';
    k.textContent = 'relation';
    const rel = resolvedRelation(rows, n.relation, file);
    tr.append(k, document.createElement('td'),
      relationCell(rel.text, rel.reason,
        file ? `resolved with ${file}, before the generate_*_name macros` : 'as dbt parsed it, before the generate_*_name macros',
        n.materialized),
      relationCell(n.relation, '', 'where this manifest\'s target built it', n.materialized));
    table.appendChild(tr);
  }
  body.appendChild(table);
  locationFoot(body, rows, { file, envName, inSandbox });
}

/* The notes under the location: what the environment does not give, that this
   is a sandbox, or that the node was built outside its configured place. */
function locationFoot(body, rows, { file, envName, inSandbox }) {
  const sandbox = (S.meta && S.meta.sandbox) || '';
  const foot = document.createElement('div');
  foot.className = 'loc-foot';
  const unresolved = rows.filter((r) => r.status === 'missing' || r.status === 'placeholder');
  if (unresolved.length) {
    foot.append(Object.assign(document.createElement('span'), {
      className: 'moved-note',
      textContent: `${file} does not give a usable value for ${unresolved.map((r) => r.key).join(' and ')}.`,
    }));
  } else if (inSandbox) {
    foot.append(Object.assign(document.createElement('span'), {
      className: 'sandbox-note',
      textContent: `Sandbox manifest: ${S.meta.sandbox_models} models are built into ${sandbox}. `
        + (file
          ? `Resolved shows ${envName}; built still shows where this manifest's target built it.`
          : 'Resolved is the config with the env vars dbt had when it parsed. Pick an environment in the status bar to see another.'),
    }));
  } else if (rows.some((r) => r.redirected)) {
    foot.append(Object.assign(document.createElement('span'), {
      className: 'moved-note',
      textContent: 'Built outside its configured location: the generate_*_name macros redirect it for this target.',
    }));
  }
  if (foot.children.length) body.appendChild(foot);
}

/* The environment the location is resolved in, beside the heading of the
   space's card: a button that opens the menu where this node follows the
   choice, a plain mark of the one it was resolved with where it does not. */
function locationPill(pill) {
  const b = document.createElement(pill ? 'button' : 'span');
  b.className = 'envpill sm';
  if (pill) {
    b.type = 'button';
    b.setAttribute('aria-haspopup', 'menu');
    fillEnvPill(b, 'env');
    b.addEventListener('click', () => openEnvMenu(b));
    return b;
  }
  // Named as the rest of the page names this manifest: on a sandbox one,
  // "my compile" (0143).
  const own = manifestChoice((S.meta && S.meta.sandbox) || '');
  b.dataset.tone = 'manifest';
  b.append(Object.assign(document.createElement('span'), { className: 'envpill-k', textContent: 'env' }), document.createTextNode(own.label));
  b.title = own.now;
  return b;
}

/* The location as a definition list, for a card too narrow for a table of
   three columns (0160): a key, then its lines (locationLines), then the
   relation. The relation is one line where the resolved and built names
   agree, a line of each where they do not, each with its Copy and, with
   Snowflake's features on, its Snowsight menu. */
function locationList(rows, n, { file, envName, inSandbox, pill }) {
  const dl = document.createElement('dl');
  dl.className = 'loc2';
  const line = (l) => {
    const v = document.createElement('span');
    v.textContent = l.value;
    if (l.cls) v.className = l.cls;
    v.title = l.title;
    if (l.dim) v.append(jel('span', 'dim', l.dim));
    if (!l.label) return v;
    const wrap = document.createElement('div');
    wrap.className = 'lv';
    wrap.append(jel('span', 'lk', l.label), v);
    return wrap;
  };
  for (const r of rows) {
    dl.append(jel('dt', '', r.key));
    const dd = document.createElement('dd');
    dd.append(...locationLines(r, envName, file, inSandbox).map(line));
    dl.append(dd);
  }
  // Ephemeral models have no relation, in any environment.
  if (n.relation) {
    const rel = resolvedRelation(rows, n.relation, file);
    const where = file ? `resolved with ${file}, before the generate_*_name macros` : 'as dbt parsed it, before the generate_*_name macros';
    const dd = document.createElement('dd');
    // A key set nowhere is the target's to decide, as the key rows say with (default): no resolved line to show.
    if (rel.text === n.relation || rel.unset) {
      dd.append(relationBody(n.relation, '', rel.unset
        ? 'where this manifest\'s target built it: the config leaves the rest to the target'
        : 'where this manifest\'s target built it, the same as resolved', n.materialized));
    } else {
      for (const [label, text, reason, what] of [['resolved', rel.text, rel.reason, where], ['built', n.relation, '', 'where this manifest\'s target built it']]) {
        const wrap = document.createElement('div');
        wrap.className = 'lv';
        wrap.append(jel('span', 'lk', label), relationBody(text, reason, what, n.materialized));
        dd.append(wrap);
      }
    }
    dl.append(jel('dt', '', 'relation'), dd);
  }
  return dl;
}

/* A full relation name with its own Copy button, and with Snowflake's
   features on its Snowsight menu, or why there is none. */
function relationCell(text, reason, what, materialized) {
  const td = document.createElement('td');
  if (!text) {
    td.className = 'nul';
    td.textContent = 'not available';
    td.title = reason;
    return td;
  }
  td.appendChild(relationBody(text, reason, what, materialized));
  return td;
}

/* What a relation row holds, in a cell or in the card's list: the name and its
   buttons, or why there is none. */
function relationBody(text, reason, what, materialized) {
  if (!text) {
    return Object.assign(document.createElement('span'), { className: 'nul', textContent: 'not available', title: reason });
  }
  const wrap = document.createElement('div');
  wrap.className = 'relcell';
  const name = document.createElement('span');
  name.textContent = text;
  name.title = what;
  const copy = document.createElement('button');
  copy.type = 'button';
  copy.className = 'btn sm';
  copy.textContent = 'Copy';
  copy.title = 'copy ' + text;
  copy.addEventListener('click', () => copyText(text));
  wrap.append(name, copy);
  if (S.features && S.features.snowflake) {
    const open = document.createElement('button');
    open.type = 'button';
    open.className = 'btn sm sfopen';
    open.dataset.tool = 'snowflake';
    open.setAttribute('aria-haspopup', 'menu');
    open.title = `open ${text} in Snowsight: the ${snowsightKind(materialized).label}, its schema or its database`;
    open.append(snowflakeIcon(), document.createTextNode('Snowsight ▾'));
    open.addEventListener('click', () => openSnowsightMenu(open, text, materialized));
    wrap.append(open);
  }
  return wrap;
}

/* Where one relation opens in Snowsight. The account comes from the script's
   session, so the first menu of a page may connect, and open a sign-in tab:
   it waits for this click (0016, 0051). Its entries are links the browser
   opens, never requests of ours. */
async function openSnowsightMenu(anchor, relation, materialized) {
  if (closePopup(anchor)) return;
  const menu = document.createElement('div');
  menu.className = 'envmenu sfmenu';
  menu.dataset.tool = 'snowflake';
  menu.setAttribute('role', 'menu');
  if (S.sfSession) {
    paintSnowsightMenu(menu, relation, materialized, {});
    return openPopup(anchor, menu);
  }
  paintSnowsightMenu(menu, relation, materialized, { busy: true });
  openPopup(anchor, menu);
  let error = null;
  try {
    const body = await api.send('/api/snowflake/session', 'POST', {});
    S.sfSession = body.session || {};
    S.colAnswered = true;
  } catch (e) {
    error = e;
  }
  // Closed while Snowflake was asked, or another menu opened since.
  if (!popup || popup.el !== menu) return;
  paintSnowsightMenu(menu, relation, materialized, { error });
  // Placed again for its new size. The script may have started for this, which
  // the settings show once the menu is gone: repainting the Catalog now would
  // close it.
  openPopup(anchor, menu, loadSidecar);
}

function paintSnowsightMenu(menu, relation, materialized, { busy, error }) {
  const note = (text, className = 'menunote') => Object.assign(document.createElement('div'), { className, textContent: text });
  menu.replaceChildren(note('open in Snowsight', 'menuhead'));
  if (busy) {
    menu.append(note('Asking Snowflake which account the profile reaches.'
      + (S.colAnswered ? '' : ' A sign-in tab may open if the session needs one.')));
    return;
  }
  if (error) {
    menu.append(note(`Snowflake did not answer: ${error.message}`));
    // A refused connection or a script that could not start is the profile's
    // business, so the file is one click away.
    const link = (error.phase === 'connect' || error.phase === 'start') && profileLink();
    if (link) {
      const where = note('The connection comes from ');
      where.append(link, document.createTextNode('.'));
      menu.append(where);
    }
    return;
  }
  const places = snowsightPlaces(S.sfSession, splitRelation(relation), materialized);
  if (!places.length) {
    menu.append(note(snowsightHome(S.sfSession)
      ? `${relation} is not a database.schema.object name.`
      : 'No Snowsight link: the account\'s organization is unknown.'));
    return;
  }
  for (const place of places) {
    const a = document.createElement('a');
    a.className = 'menulink';
    a.setAttribute('role', 'menuitem');
    a.href = place.url;
    a.target = '_blank';
    a.rel = 'noopener noreferrer';
    a.title = [place.url, place.guess].filter(Boolean).join('\n');
    a.append(
      Object.assign(document.createElement('span'), { className: 'lbl', textContent: place.name }),
      Object.assign(document.createElement('span'), { className: 'sub', textContent: place.what }),
    );
    // After the click, so the link is still in the page when the browser follows it.
    a.addEventListener('click', () => setTimeout(closePopup));
    menu.append(a);
  }
}

// ------------------------------------------------------------ clone (0058) --
/* Statements that copy a model and its direct parents from an environment into
   the developer's own schema. Written here, from the relations the Location
   table resolves, and run by the user: dbt-edith sends them nowhere. The
   functions down to openClonePlan are pure, and web/tests/clone.js slices them
   out by those two names. */

/* What one materialization is copied as. A table-like object is cloned, which
   is instant and costs nothing until either side changes. A view becomes a
   table, since a cloned view would go on reading the environment it came from,
   and the object of that kind a local run may have left is dropped first: a
   CREATE OR REPLACE TABLE does not replace an object of another kind. */
function cloneShape(materialized, mode) {
  const m = materialized || '';
  if (m === 'semantic_view') return { action: 'skip', drop: '', reason: 'a semantic view holds no rows to copy' };
  if (['table', 'incremental', 'snapshot', 'seed'].includes(m)) {
    return { action: mode === 'ctas' ? 'ctas' : 'clone', drop: '', reason: '' };
  }
  const drop = { view: 'view', materialized_view: 'materialized view', dynamic_table: 'dynamic table' }[m] || '';
  return { action: 'ctas', drop, reason: '' };
}

/* Where one node is copied from. Under a chosen file it is the relation the
   Location table resolves with that file, and never the manifest's instead: a
   copy from the wrong environment is worse than none. A database or schema
   the config leaves unset is the target's, which the file does not say. With
   no file, it is where this manifest's target built the node. */
function cloneSource(item, file) {
  if (!item.relation) return { text: '', reason: `${item.name} has no relation in the warehouse` };
  if (!file) return { text: item.relation, reason: '' };
  const env = item.location && item.location.envs ? item.location.envs[file] : null;
  if (!env) return { text: '', reason: `${item.name} was not resolved against ${file}` };
  // The table's own refusals first: a missing variable is the one to fix.
  const rel = resolvedRelation(locationRows(item.location, file), item.relation, file);
  if (!rel.text) return rel;
  for (const key of ['database', 'schema']) {
    if (env.status && env.status[key] && env.status[key].kind === 'parsed') {
      return { text: '', reason: `${key} is not set in the config, so it comes from the target profile, not from ${file}` };
    }
  }
  return rel;
}

/* The destination as typed: two names, each quoted or not. */
function cloneInto(text) {
  const t = (text || '').trim();
  if (!t) return { text: '', reason: 'type the database.schema to clone into' };
  const parts = splitRelation(t);
  if (t.length > 255 || /[\u0000-\u001f\u007f]/.test(t) || parts.length !== 2 || parts.some((p) => !p.name.trim())) {
    return { text: '', reason: 'the destination is a database and a schema: database.schema' };
  }
  return { text: t, reason: '' };
}

/* The destination before the user types one, and where it came from: what
   they typed last time, then the profile's active target, then the sandbox
   this manifest was built into, which only a manifest parsed with their own
   target has. */
function cloneIntoDefault(into) {
  const i = into || {};
  const p = i.profile || {};
  if (i.remembered) return { text: i.remembered, from: 'what you typed last time' };
  if (p.database && p.schema) {
    const picked = p.target_from === 'DBT_TARGET' ? ', picked by DBT_TARGET' : '';
    return { text: `${p.database}.${p.schema}`, from: `profile ${p.profile}, target ${p.target}${picked}` };
  }
  const why = p.why || 'the profile gives no target';
  if (i.sandbox) return { text: i.sandbox, from: `where this manifest built nearly every model, since ${why}: confirm it` };
  return { text: '', from: why };
}

/* One statement. Always TRANSIENT: dbt creates tables transient unless told
   otherwise, Snowflake refuses to clone a transient table into a permanent
   one, and a copy in a sandbox needs no Fail-safe. */
function cloneStatement(source, target, shape) {
  const drop = shape.drop ? `drop ${shape.drop} if exists ${target};\n` : '';
  if (shape.action === 'clone') return `${drop}create or replace transient table ${target}\n    clone ${source};`;
  return `${drop}create or replace transient table ${target} as\nselect * from ${source};`;
}

/* Two relations naming one object: an unquoted name is upper-cased by
   Snowflake, a quoted one kept as written. */
function cloneSameObject(a, b) {
  const key = (t) => splitRelation(t).map((p) => (p.quoted ? p.name : p.name.toUpperCase())).join('\u0000');
  return key(a) === key(b);
}

/* One row per node of the plan, with its statement or why there is none. The
   copy keeps the source's own name, quotes included, so a local ref() finds it. */
function cloneRows(plan, file, dest, mode) {
  return plan.items.map((item) => {
    const shape = cloneShape(item.materialized, mode);
    const row = {
      id: item.id, name: item.name, kind: item.kind, materialized: item.materialized,
      why: item.why, via: item.via || '', changed: !!item.changed,
      action: shape.action, source: '', target: '', sql: '', reason: '',
    };
    if (item.disabled) return Object.assign(row, { action: 'refused', reason: `${item.name} is disabled, so it is not built` });
    if (shape.action === 'skip') return Object.assign(row, { reason: shape.reason });
    const src = cloneSource(item, file);
    if (!src.text) return Object.assign(row, { action: 'refused', reason: src.reason });
    row.source = src.text;
    if (!dest.text) return row;
    const last = splitRelation(src.text).pop();
    row.target = `${dest.text}.${last.quoted ? `"${last.name.replace(/"/g, '""')}"` : last.name}`;
    if (cloneSameObject(row.source, row.target)) {
      return Object.assign(row, { action: 'refused', reason: 'it already is where the copy would go' });
    }
    row.sql = cloneStatement(row.source, row.target, shape);
    return row;
  });
}

/* What the user should know before running them, only where it applies. */
function cloneNotes(plan, rows, ctx) {
  const notes = [];
  const names = (list) => list.map((r) => r.name).join(', ');
  const changed = rows.filter((r) => r.changed);
  if (changed.length) {
    notes.push(`${names(changed)} changed after this manifest was written: run dbt parse, or the parents listed may not be the ones it reads now.`);
  } else if (ctx.stale) {
    notes.push(`${ctx.stale}: the parents listed are the ones this manifest knew.`);
  }
  if (plan.ephemeral.includes(plan.name)) {
    notes.push(`${plan.name} is ephemeral, so nothing of it is copied: only what it reads.`);
  }
  const through = plan.ephemeral.filter((e) => e !== plan.name);
  if (through.length) {
    notes.push(`${through.join(', ')} ${through.length === 1 ? 'is' : 'are'} ephemeral, with no object of ${through.length === 1 ? 'its' : 'their'} own: what ${through.length === 1 ? 'it reads' : 'they read'} is copied instead.`);
  }
  const copied = rows.filter((r) => r.sql);
  if (copied.some((r) => cloneShape(r.materialized, 'clone').drop === 'view')) {
    notes.push('A view is copied as a table of its rows today: a cloned view would go on reading the environment it came from.');
  }
  if (copied.some((r) => r.materialized === 'incremental')) {
    notes.push('An incremental model is copied with the rows it holds, so a local dbt run adds to the copy rather than rebuilding it.');
  }
  if (copied.some((r) => r.materialized === 'snapshot')) {
    notes.push('A snapshot is copied with its history.');
  }
  if (ctx.file) {
    notes.push(`Locations are the config resolved with ${ctx.file}, before the generate_*_name macros: check them if your macros move schemas for that target.`);
  } else if (ctx.sandbox && rows.some((r) => r.action === 'refused' && r.source && cloneSameObject(r.source, r.target))) {
    notes.push('This manifest was built into the destination: pick an environment to copy from.');
  }
  if (ctx.dotenvTarget && ctx.profileTarget && ctx.dotenvTarget !== ctx.profileTarget) {
    notes.push(`Your .env sets DBT_TARGET=${ctx.dotenvTarget}, which dbt reads only once your shell exports it: the destination comes from target ${ctx.profileTarget}.`);
  }
  notes.push('Copies are transient and not managed by dbt: a local dbt run into the same schema replaces them. '
    + 'Running the statements needs a role that reads the source databases and writes the destination.');
  return notes;
}

/* The comment the script opens with. No date, so the same plan reads the same. */
function cloneHead(plan, file, dest) {
  const from = file ? `where ${file} puts them` : 'where this manifest built them';
  return [
    `-- ${plan.name} and its direct parents, from ${from}, into ${dest.text || 'a destination still to type'}.`,
    '-- Written by dbt-edith, which runs none of it: read it, then run it yourself.',
  ];
}

/* The whole script: the picked statements, parents first and the model last,
   and a line for every node that cannot be copied, so nothing goes missing
   unnoticed. A node the user unticked is simply left out. */
function cloneScript(rows, picked, head, blocked) {
  const out = [...head, ''];
  if (blocked) return out.concat(`-- ${blocked}`).join('\n') + '\n';
  for (const r of rows) {
    if (!r.sql) out.push(`-- skipped ${r.name}: ${r.reason}`, '');
    else if (picked.has(r.id)) out.push(r.sql, '');
  }
  if (!rows.some((r) => r.sql && picked.has(r.id))) out.push('-- nothing to run');
  return out.join('\n').replace(/\n+$/, '') + '\n';
}

/* The plan, asked again on every opening so it follows the manifest and the
   .env files, in a modal the user reads and copies from. The destination they
   type is kept for the project once the modal closes (0011). */
async function openClonePlan(n) {
  let plan;
  try {
    plan = await api.get('/api/snowflake/clone?id=' + encodeURIComponent(n.id));
  } catch (e) {
    toast('clone: ' + e.message, 'err');
    return;
  }
  const files = S.envs ? S.envs.files.filter((f) => !f.hidden).map((f) => f.file) : [];
  const was = S.cloneFrom;
  const file = was !== null && (was === '' || files.includes(was)) ? was : (files.includes(S.env) ? S.env : '');
  const first = cloneIntoDefault(plan.into);
  const st = { plan, file, mode: S.cloneMode, into: first.text, from: first.from, unpicked: new Set(), script: '' };

  const body = document.createElement('div');
  body.className = 'envpanel clonepanel';
  const seg = (choices, current, pick) => {
    const box = document.createElement('div');
    box.className = 'seg';
    for (const [value, label, tip] of choices) {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'segbtn' + (value === current() ? ' active' : '');
      b.textContent = label;
      if (tip) b.title = tip;
      b.addEventListener('click', () => {
        pick(value);
        box.querySelectorAll('.segbtn').forEach((x) => x.classList.toggle('active', x === b));
        paintClonePlan(view, st);
      });
      box.append(b);
    }
    return box;
  };
  const line = (label, ...parts) => {
    const row = document.createElement('div');
    row.className = 'clonehead';
    row.append(Object.assign(document.createElement('span'), { className: 'k', textContent: label }), ...parts);
    return row;
  };
  const sources = files.map((f) => [f, envDisplayName(f), `copy from where ${f} puts each node`]);
  sources.push(['', 'built (manifest)', 'copy from where the target that produced this manifest built each node']);
  const input = Object.assign(document.createElement('input'), { type: 'text', value: st.into, spellcheck: false });
  input.setAttribute('aria-label', 'destination, database.schema');
  input.placeholder = 'DATABASE.schema';
  const from = Object.assign(document.createElement('span'), { className: 'muted' });
  input.addEventListener('input', () => { st.into = input.value; paintClonePlan(view, st); });
  body.append(
    line('from', seg(sources, () => st.file, (v) => { st.file = v; })),
    line('into', input, from),
    line('as', seg([
      ['clone', 'Clone', 'zero-copy clones for tables, seeds, snapshots and incremental models'],
      ['ctas', 'Create as select', 'a real copy of the rows of every node'],
    ], () => st.mode, (v) => { st.mode = v; })),
  );
  const view = {
    from,
    table: document.createElement('div'),
    sources: Object.assign(document.createElement('p'), { className: 'muted' }),
    notes: document.createElement('div'),
    sql: Object.assign(document.createElement('pre'), { className: 'clonesql' }),
  };
  const copy = Object.assign(document.createElement('button'), { type: 'button', className: 'btn sm', textContent: 'Copy statements' });
  // Straight from the click, before anything awaits, or the browser may
  // refuse the clipboard.
  copy.addEventListener('click', () => copyText(st.script, 'the statements'));
  body.append(view.table, view.sources, view.notes, line('sql', copy), view.sql);
  paintClonePlan(view, st);

  await modal({ title: `Clone ${n.name} into your schema`, body, wide: true, actions: [{ id: 'close', label: 'Close' }] });
  S.cloneFrom = st.file;
  S.cloneMode = st.mode;
  if (!plan.into.persist) return;
  const typed = st.into.trim();
  if (typed && cloneInto(typed).reason) return;
  const p = plan.into.profile || {};
  // The profile's own value, typed back, means "follow the profile" again.
  const keep = !typed || (p.database && typed === `${p.database}.${p.schema}`) ? null : typed;
  if (keep === (plan.into.remembered || null)) return;
  try { await api.send('/api/snowflake/clone/into', 'POST', { into: keep }); } catch (e) { toast('clone: ' + e.message, 'err'); }
}

/* The parts of the modal that follow the choices: the destination's origin,
   the table of nodes, the sources, the notes and the script. */
function paintClonePlan(view, st) {
  const dest = cloneInto(st.into);
  const rows = cloneRows(st.plan, st.file, dest, st.mode);
  view.from.textContent = dest.reason && st.into.trim() ? dest.reason : (st.into.trim() === cloneIntoDefault(st.plan.into).text ? st.from : 'typed here');
  view.from.className = dest.reason && st.into.trim() ? 'env-missing' : 'muted';

  const table = document.createElement('table');
  table.className = 'loc';
  const head = document.createElement('tr');
  for (const label of ['', 'node', 'materialized', 'from', 'action']) head.append(Object.assign(document.createElement('th'), { textContent: label }));
  table.append(head);
  for (const r of rows) {
    const tr = document.createElement('tr');
    const box = Object.assign(document.createElement('input'), { type: 'checkbox' });
    box.disabled = !r.source || r.action === 'refused' || r.action === 'skip';
    box.checked = !box.disabled && !st.unpicked.has(r.id);
    box.setAttribute('aria-label', 'copy ' + r.name);
    box.addEventListener('change', () => {
      if (box.checked) st.unpicked.delete(r.id); else st.unpicked.add(r.id);
      paintClonePlan(view, st);
    });
    const pick = document.createElement('td');
    pick.append(box);
    const name = document.createElement('td');
    name.textContent = r.name;
    name.title = r.why === 'model' ? 'the node asked for' : r.why === 'via' ? `read through ${r.via}, which is ephemeral` : 'a direct parent';
    if (r.why !== 'parent') name.append(Object.assign(document.createElement('span'), { className: 'why', textContent: r.why === 'via' ? ` via ${r.via}` : ' (this one)' }));
    const mat = Object.assign(document.createElement('td'), { className: 'k', textContent: r.materialized });
    const src = document.createElement('td');
    if (r.source && r.action !== 'refused') src.textContent = r.source;
    else { src.textContent = r.reason; src.className = r.action === 'skip' ? 'nul' : 'env-missing'; }
    const act = Object.assign(document.createElement('td'), { className: 'k' });
    act.textContent = { clone: 'clone', ctas: 'create as select', skip: 'nothing to copy', refused: 'not copied' }[r.action] || r.action;
    tr.append(pick, name, mat, src, act);
    table.append(tr);
  }
  view.table.replaceChildren(table);

  const srcs = st.plan.sources.map((s) => {
    const at = cloneSource(s, st.file);
    return `${s.name} (${at.text || at.reason})`;
  });
  view.sources.textContent = srcs.length ? `Read where they are, never copied: ${srcs.join('; ')}.` : '';
  if (st.plan.other.length) view.sources.textContent += ` Also among the parents, with nothing to copy: ${st.plan.other.join(', ')}.`;

  const dotenv = S.envs && S.envs.files.find((f) => f.file === '.env');
  const p = st.plan.into.profile || {};
  const fresh = S.fresh && S.fresh.state && S.fresh.state !== 'fresh' && S.fresh.state !== 'missing' ? freshnessBadge(S.fresh).head : '';
  const notes = cloneNotes(st.plan, rows, {
    file: st.file, stale: fresh, sandbox: st.plan.into.sandbox || '',
    dotenvTarget: dotenv ? dotenv.target || '' : '', profileTarget: p.database ? p.target : '',
  });
  view.notes.replaceChildren(...notes.map((t) => Object.assign(document.createElement('p'), { className: 'clonenote', textContent: t })));

  const picked = new Set(rows.filter((r) => r.sql && !st.unpicked.has(r.id)).map((r) => r.id));
  st.script = cloneScript(rows, picked, cloneHead(st.plan, st.file, dest), dest.reason);
  view.sql.textContent = st.script;
}

/* dbt's own materializations that use no incremental strategy, and the kinds
   of node that have none; a snapshot uses a key and its own `strategy`. */
const UNUSED_BY = ['view', 'table', 'ephemeral', 'seed', 'test', 'snapshot', 'materialized_view'];

/* `a view`, `an ephemeral`. */
function article(word) {
  return (/^[aeiou]/i.test(word) ? 'an ' : 'a ') + word;
}

/* A column name or a key entry as Snowflake compares them: case aside and
   quotes off, since it upper-cases what the YAML declares in lower case. */
function columnKey(name) {
  const s = String(name || '').trim();
  const q = s.match(/^"(.*)"$|^`(.*)`$|^\[(.*)\]$/);
  return (q ? q[1] ?? q[2] ?? q[3] : s).toLowerCase();
}

/* Each entry of a unique key, in the key's order, with the column it names,
   or null for an expression or a name no column of the node has: an
   expression is not parsed, so `order_id || '-' || line_number` marks none. */
function keyColumns(key, columns) {
  const by = new Map(columns.map((c) => [columnKey(c.name), c]));
  return (key || []).map((entry) => ({ entry, column: by.get(columnKey(entry)) || null }));
}

/* The letter of the `i`th of `total` keys of a node: none while the node has
   one key, `A`, `B`... from two, and the number past `Z`. */
function keyLetter(i, total) {
  if (total < 2) return '';
  return i < 26 ? String.fromCharCode(65 + i) : String(i + 1);
}

/* The tag of one key on one of its columns (0127): `KEY`, `KEY 1/2` for a
   column of several, `KEY A` and `KEY A 1/2` once the node has two keys.
   Dashed when a column of the key has no not_null test, and the title says
   what declares the key and which columns are left. `key` is the payload's,
   `entries` its columns in the order of the first declaration. */
function keyTag(key, letter, column) {
  const entries = key.entries || [];
  const at = entries.findIndex((e) => columnKey(e) === columnKey(column));
  const text = ['KEY', letter, entries.length > 1 && at >= 0 ? `${at + 1}/${entries.length}` : ''].filter(Boolean).join(' ');
  const lines = [`${letter ? `key ${letter}` : 'key'}: ${entries.join(', ')}`];
  for (const f of key.from || []) {
    lines.push(f.kind === 'unique_key' ? 'declared by unique_key'
      : `declared by the ${f.kind === 'combination' ? 'unique_combination_of_columns' : 'unique'} test ${f.name}`);
  }
  const nullable = key.nullable || [];
  if (nullable.length) lines.push(`no not_null test on ${nullable.join(', ')}`);
  return { text, title: lines.join('\n'), dashed: nullable.length > 0 };
}

/* Marks a column for the Columns table of node `id` to scroll to, once, the
   next time that node's table is drawn with the Catalog in front. Tied to the
   node, so a table drawn meanwhile, the one a report's link opens over or one
   with a column of the same name, neither takes the scroll nor loses its own. */
function highlightColumn(column, id) {
  S.colHighlight = column;
  S.colReveal = column ? id : '';
}

/* Strategy, as the box reads it: `append merge` with `merge` struck when the
   macros dbt runs insert every row, and the adapter's default said under it. */
function strategyStat(n) {
  const adapter = S.meta && S.meta.adapter;
  const s = stat('Strategy', n.strategy_shown || 'default');
  const v = s.querySelector('.v');
  if (n.strategy_named) v.replaceChildren(...subNodes({ lead: n.strategy_shown, struck: n.strategy_named, rest: '' }));
  if (!n.strategy_shown) v.classList.add('none');
  const under = !n.strategy_shown ? 'not read from the macros'
    : n.strategy_default ? `${Lineage.adapterName(adapter)}'s default` : '';
  if (under) s.append(Object.assign(document.createElement('div'), { className: 'under', textContent: under }));
  const fact = strategyFacts(n, adapter)[0];
  if (fact) s.title = fact.text;
  return s;
}

/* Unique key, one entry per line in the key's order, so a key of long names
   does not stretch the row. Past three, the first two and a link to the rest
   in the Columns tab. Each entry that names a column opens it there. */
function keyStat(n) {
  const key = n.unique_key || [];
  const s = stat('Unique key', key.length ? '' : 'none');
  const v = s.querySelector('.v');
  if (!key.length) {
    v.classList.add('none');
    return s;
  }
  v.classList.add('keys');
  const entries = keyColumns(key, n.columns);
  for (const { entry, column } of entries.length > 3 ? entries.slice(0, 2) : entries) {
    const line = Object.assign(document.createElement('div'), { textContent: entry });
    if (column) {
      line.className = 'keylink';
      line.title = `show ${column.name} in the Columns tab`;
      linkLike(line, () => { highlightColumn(column.name, n.id); showCatalogTab(n, 'columns'); });
    } else {
      line.title = /^["`[]?\w+["`\]]?$/.test(entry.trim())
        ? 'no column of this name, neither declared in the YAML nor in catalog.json'
        : 'an expression, not a column: it is not read';
    }
    v.append(line);
  }
  if (entries.length > 3) {
    const more = Object.assign(document.createElement('div'), {
      className: 'keymore', textContent: `+${entries.length - 2} more, in Columns`,
      title: ['unique_key, in order'].concat(key).join('\n'),
    });
    linkLike(more, () => { S.colSort = 'key'; showCatalogTab(n, 'columns'); });
    v.append(more);
  }
  return s;
}

/* A div that answers a click and the keys a button does, the role and the
   keys giving a keyboard what a button would, so a stat's number or a key
   name keeps the type of the stat it sits in. */
function linkLike(node, onClick) {
  node.tabIndex = 0;
  node.setAttribute('role', 'button');
  node.addEventListener('click', onClick);
  node.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' && e.key !== ' ') return;
    e.preventDefault();
    onClick(e);
  });
}

function catalogPreview(body, n, inCard = false) {
  const desc = document.createElement('p');
  desc.className = 'cat-desc';
  if (n.description) desc.textContent = n.description;
  else { desc.classList.add('muted'); desc.textContent = 'No description in the YAML.'; }
  body.appendChild(desc);

  body.appendChild(h3('context'));
  const stats = document.createElement('div');
  stats.className = 'stats';
  // The strategy and the key where they are used, beside Materialization; elsewhere
  // they were inherited, and "details" says so.
  // A disabled model is never run, so nothing is said of how.
  const incremental = n.kind === 'model' && n.materialized === 'incremental' && !n.disabled;
  const keyed = incremental || (n.kind === 'snapshot' && !n.disabled);
  // Each of Upstream and Downstream sets the box it names and leaves the other:
  // the Catalog shows another node than the canvas's only when a box was
  // clicked on it.
  const columns = stat('Columns', String(n.columns.length), n.columns.length ? () => showCatalogTab(n, 'columns') : null);
  const up = stat(inCard ? 'Upstream' : 'Upstream models', `${n.parents.length}`, () => lineageOneUp(n));
  const down = stat(inCard ? 'Downstream' : 'Downstream models', `${n.children.length}`, () => { $('#down').value = 1; focusNode(n.id, { keepDepth: true }); showDock('lineage'); });
  const tests = stat('Tests', String(n.tests.length), n.tests.length ? () => {
    const h = [...body.querySelectorAll('h3')].find((e) => e.textContent.startsWith('tests on'));
    if (h) h.scrollIntoView({ block: 'start' });
  } : null);
  stats.append(
    stat('Materialization', n.materialized || n.kind),
    ...(incremental ? [strategyStat(n)] : []),
    ...(keyed ? [keyStat(n)] : []),
    // The card reads Columns, Tests, Upstream, Downstream, as the design lists them (0160).
    ...(inCard ? [columns, tests, up, down] : [columns, up, down, tests]),
  );
  const totals = document.createElement('div');
  totals.className = 'stats-under';
  totals.textContent = `${n.upstream_total} models upstream in total, ${n.downstream_total} downstream (whole graph).`;
  body.append(stats, totals);
  catalogLocation(body, n, inCard);
  catalogJobs(body, n);
  catalogBuilds(body, n);

  catalogTags(body, n);

  // A folder's config reaches every node under it. What a node of dbt's own
  // materializations does not use stays said, dimmed, since a selection by it
  // still picks the node; a custom materialization may read either, so its
  // line says what is set and no more.
  const key = (n.unique_key || []).join(', ');
  const mat = n.materialized || n.kind;
  const unused = UNUSED_BY.includes(mat) && !n.disabled ? `, unused by ${article(mat)}` : '';
  const kv = kvLines([
    ['incremental_strategy', !incremental && n.strategy ? n.strategy + unused : '', !!unused],
    ['unique_key', !keyed && key ? key + unused : '', !!unused],
    ['model file', n.file],
    ['schema file', n.yml],
    ['unique id', n.id],
  ]);
  if (kv.children.length) { body.appendChild(h3('details')); body.appendChild(kv); }

  catalogRefs(body, 'upstream', n.parents);
  catalogRefs(body, 'downstream', n.children);
  const guards = splitTests(n.tests);
  // The model's own tests come first, and they are the point of this section:
  // guarding no column, they have no row in the Columns table and are named
  // nowhere else at all. The column ones follow for completeness, each saying
  // which column, because a relationships test counts on both models it joins
  // and reads as a stranger on the one that did not declare it.
  catalogRefs(body, 'tests on the model', guards.model, (r) => r.test_name || r.name);
  catalogRefs(body, 'tests on a column', guards.column, (r) => `${r.test_name || r.name} · ${r.column}`);
}

/* Nodes linked from the Catalog, under a heading that counts them. */
function catalogRefs(body, label, items, text) {
  if (!items.length) return;
  body.appendChild(h3(`${label} (${items.length})`));
  const box = document.createElement('div');
  box.className = 'links';
  // Same gestures as a box in the graph: click moves the lineage and the
  // catalog to that node, double-click also opens its file.
  items.slice(0, 300).forEach((r) => {
    const a = document.createElement('span');
    a.className = 'link';
    a.append(dot(r), document.createTextNode(text ? text(r) : r.name));
    const test = r.kind === 'test' && r.test_name;
    a.title = `${r.id}\nclick: show it here and in the lineage`
      + (r.file ? `\ndouble-click: also open ${test ? 'where it is declared' : 'its file'}` : '');
    a.addEventListener('click', () => focusNode(r.id));
    a.addEventListener('dblclick', () => {
      if (!r.file) return;
      if (test) return openTest(r, { pin: true });
      pushJump();
      openFile(r.file, { focusLineage: false });
      revealInTree(r.file);
    });
    box.appendChild(a);
  });
  body.appendChild(box);
}

/* A test, which builds nothing of its own to read about: what it checks and
   on what come first, as its hover card says it, then the jobs that run it
   and the models it reads. No location table, since a relation is built for
   it only to store its failures, which its config section names, and no
   columns, downstream or tests of its own. */
const HOST_LABELS = { model: 'Model', source: 'Source', seed: 'Seed', snapshot: 'Snapshot' };

function catalogTestPreview(body, n) {
  if (n.description) body.appendChild(jel('p', 'cat-desc', n.description));
  body.appendChild(h3('what it checks'));
  const stats = document.createElement('div');
  stats.className = 'stats';
  const level = Lineage.testLevel(n);
  const severity = stat('Severity', n.warn ? 'warn' : 'error');
  if (n.warn) severity.querySelector('.v').classList.add('warn');
  // The node whose YAML declares it, a model or a source, found by id: two
  // parents can share a name. A singular test has none, and the models it
  // reads say the rest.
  const host = level !== 'singular' && n.host_id && n.parents.find((p) => p.id === n.host_id);
  const hostLabel = host && (HOST_LABELS[host.kind] || 'Declared on');
  stats.append(
    stat('Test', level === 'singular' ? 'singular' : n.test_name),
    ...(host ? [stat(hostLabel, host.name, () => focusNode(host.id))] : []),
    ...(n.column ? [stat('Column', n.column)] : []),
    severity,
    stat('Models read', `${n.parents.length}`, () => lineageOneUp(n)),
  );
  const totals = document.createElement('div');
  totals.className = 'stats-under';
  totals.textContent = `${n.upstream_total} models upstream in total (whole graph).`;
  body.append(stats, totals);
  catalogTestConfig(body, n);
  catalogJobs(body, n);
  catalogTags(body, n);

  body.append(h3('details'), kvLines([
    [level === 'singular' ? 'test file' : 'declared in', n.file],
    ['generic from', n.namespace],
    ['unique id', n.id],
  ]));
  catalogRefs(body, 'reads', n.parents);
}

/* The config the test moved off dbt's defaults, which the server alone
   sends, and where its failing rows go when it keeps them: the one relation a
   test builds. store_failures_as wins over store_failures when both are set,
   and keeps nothing as ephemeral. */
function testStoresFailures(settings) {
  const get = (k) => ((settings || []).find((s) => s.key === k) || {}).value;
  const as = get('store_failures_as');
  return as ? as.toLowerCase() !== 'ephemeral' : (get('store_failures') || '').toLowerCase() === 'true';
}

function catalogTestConfig(body, n) {
  const settings = n.settings || [];
  if (!settings.length) return;
  body.appendChild(h3('config'));
  // dbt's relation_name, quoted as dbt writes it, and the parts it was built
  // from only where a manifest lacks it. It is the manifest's: an environment
  // picked in the Catalog resolves a model's location, never a test's.
  const built = n.location && n.location.built;
  const at = n.relation || (built && built.schema ? [built.database, built.schema, built.alias].filter(Boolean).join('.') : '');
  body.appendChild(kvLines(settings.map((s) => [s.key, s.value])
    .concat([['failures stored in', testStoresFailures(settings) ? at : '']])));
}

function catalogTags(body, n) {
  if (!n.tags.length) return;
  body.appendChild(h3('tags'));
  const box = document.createElement('div');
  box.className = 'links';
  n.tags.forEach((t) => {
    const c = document.createElement('span');
    c.className = 'tagchip';
    c.textContent = t;
    box.appendChild(c);
  });
  body.appendChild(box);
}

/* The steps that run the node, one chip each, a click away from their card
   in the Jobs tab. The jobs are asked for only once the Catalog is seen, as
   the tab asks once it is opened (0063): one drawn behind another tab, or
   under a panel, is filled in by showDock or as the panel rolls up. An answer is kept
   per node, so drawing the Catalog again asks nothing until the jobs may have
   changed (forgetCatalogJobs). Nothing shows until a source is named. */
function catalogJobs(body, n) {
  const box = jel('div', 'cat-jobs');
  box.dataset.node = n.id;
  body.appendChild(box);
  fillCatalogJobs(box);
}

const catalogSeen = () => selCardOpen() || (S.dock === 'catalog' && !S.panel);

async function fillCatalogJobs(box) {
  if (!box || box.dataset.asked) return;
  const id = box.dataset.node;
  const known = S.catJobs.get(id);
  if (known) {
    box.dataset.asked = '1';
    return paintCatalogJobs(box, known);
  }
  if (!catalogSeen()) return;
  box.dataset.asked = '1';
  const gen = S.catJobsGen;
  let view;
  // What went wrong is the Jobs tab's to say, with the sources at hand; the
  // next time the Catalog is seen asks again.
  try { view = await api.get('/api/jobs/node?id=' + encodeURIComponent(id)); }
  catch { if (gen === S.catJobsGen) delete box.dataset.asked; return; }
  if (gen !== S.catJobsGen) return;
  S.catJobs.set(id, view);
  if (box.isConnected) paintCatalogJobs(box, view);
}

/* The jobs may have changed: the sources were saved, a look at their files
   may have read them again, or a new manifest moved what each step selects.
   What the Catalog shows stays until its next answer replaces it. */
function forgetCatalogJobs() {
  S.catJobs.clear();
  S.catJobsGen++;
  // What Builds by job holds of the jobs is as old as they are: asked again
  // by the section on screen, or the next time it is shown (0119).
  if (S.builds) S.builds.jobsAsked = null;
  if (panelOpen('reports') && S.reportsSection === 'jobbuilds') showReportSection('jobbuilds');
  const box = $('#catalog .cat-jobs');
  if (!box) return;
  delete box.dataset.asked;
  fillCatalogJobs(box);
}

function paintCatalogJobs(box, view) {
  if (!view.configured) return box.replaceChildren();
  const id = box.dataset.node;
  const list = jel('div', 'links');
  // A step's chip carries the Jobs tool's glyph (the clock) and its arrow in
  // the dim colour; the notes beside them are words alone.
  const chip = (cls, text, title, reveal) => {
    const b = jel('button', cls, Array.isArray(text) ? '' : text);
    if (Array.isArray(text)) {
      b.dataset.tool = 'jobs';
      b.append(jel('span', 'tooldot', ''), text[0], jel('span', 'sl', '\u203a'), text[1]);
    }
    b.type = 'button';
    b.title = title;
    b.addEventListener('click', () => showJobsFor(id, reveal));
    list.append(b);
    return b;
  };
  const chips = jobsChips(view.groups);
  for (const c of chips) {
    const start = jobsStart(c.job);
    const word = { scheduled: 'scheduled, ', unread: 'schedule not read, ' }[start] || '';
    chip('jobchip', c.parts,
      `${jobsJobLabel(c.job)}: ${word}${jobsScheduleText(c.job)}\n${c.step.shown}\nclick: show it in the Jobs tab`,
      { key: jobsStepKey(c.job, c.step), index: c.step.index }).dataset.start = start;
  }
  const maybe = jobsMaybeCount(view.maybe);
  if (maybe) {
    chip('jobchip more', `${maybe} not resolved`,
      `${jobsPlural(maybe, 'step')} the tool could not resolve, which could act on it\nclick: show them in the Jobs tab`,
      { maybe: true });
  }
  // A refused file may run the node too, which the tab says above its cards.
  if (view.refused) {
    chip('jobchip more', `${jobsPlural(view.refused, 'file')} not read`,
      `${jobsPlural(view.refused, 'file')} could not be read and may hold more\nclick: open the Jobs tab, whose Sources… says which`, null);
  }
  if (!chips.length) list.prepend(jel('span', 'muted', 'No job read runs it.'));
  box.replaceChildren(h3('jobs'), list);
}

/* ---------------------------------------------------------- last builds -- */
/* The read is the user's: a button in the Catalog or in Reports asks
   Snowflake once per distinct pair of tables, one after the other, and each
   answer is drawn as it lands. It lives in S.builds until the page closes and
   is written nowhere (0117). */

const buildsStaleDays = () => (S.features && S.features.builds_stale_days) || 7;

/* Whether there is anything to read: Snowflake's features are on and the
   manifest holds the package's two tables, which the index says. */
const buildsOffered = () => !!(S.features && S.features.snowflake && S.reports && S.reports.builds);

function buildsEnvName(env) {
  return env ? envDisplayName(env) : manifestChoice((S.meta && S.meta.sandbox) || '').label;
}

async function readBuilds() {
  if (S.buildsBusy || !buildsOffered()) return;
  S.buildsBusy = true;
  const next = { readAt: Date.now(), byEnv: {}, targets: [], pending: true, failed: '' };
  S.builds = next;
  repaintBuilds();
  try {
    const ids = buildsIds();
    const [exe, inv] = await Promise.all([nodeDetail({ id: ids.executions }), nodeDetail({ id: ids.invocations })]);
    const files = envsInUse() ? S.envs.files.filter((f) => !f.hidden) : [];
    next.targets = buildsTargets(exe, inv, files, buildsEnvName(''));
    for (const t of next.targets) if (t.reason) next.byEnv[t.env] = { error: t.reason, placed: false, rows: new Map() };
    repaintBuilds();
    const queries = buildsQueries(next.targets);
    for (let i = 0; i < queries.length; i++) {
      const q = queries[i];
      let entry;
      try {
        const r = await api.send('/api/snowflake/builds', 'POST', { executions: q.executions, invocations: q.invocations });
        S.colAnswered = true;
        entry = { relation: q.executions, cut: !!r.cut, rows: buildsByNode(r.rows) };
      } catch (e) {
        entry = { relation: q.executions, error: e.message, phase: e.phase || '', rows: new Map() };
      }
      // A file that sets DBT_TARGET keeps that target's runs; one that does not
      // (and the manifest's own build) keeps every target (0117).
      for (const env of q.envs) {
        const t = next.targets.find((x) => x.env === env);
        next.byEnv[env] = t && t.target ? Object.assign({}, entry, {
          rows: buildsOfTarget(entry.rows, t.target), target: t.target, others: buildsOtherTargets(entry.rows, t.target),
        }) : entry;
      }
      repaintBuilds();
      // A connection Snowflake refuses, a script that would not start, or one
      // that stopped or timed out would fail the rest the same way, and a
      // sign-in could open for each: they are not asked. A query's own failure,
      // or a request refused for one odd relation, says nothing of the next.
      if (entry.error && ['connect', 'start', 'script'].includes(entry.phase)) {
        for (const later of queries.slice(i + 1)) {
          const skipped = { relation: later.executions, error: entry.error, phase: entry.phase, skipped: true, rows: new Map() };
          for (const env of later.envs) next.byEnv[env] = skipped;
        }
        break;
      }
    }
  } catch (e) {
    next.failed = e.message;
  } finally {
    next.pending = false;
    S.buildsBusy = false;
    repaintBuilds();
    // The script may have just started for this, which the settings show.
    loadSidecar();
  }
}

/* Everything that shows the read, drawn again from memory: the Catalog's
   section, the Reports section when it is the one on screen, and the marks. */
function repaintBuilds() {
  const box = $('#catalog .cat-builds');
  if (box) paintCatalogBuilds(box);
  if (panelOpen('reports') && (S.reportsSection === 'builds' || S.reportsSection === 'jobbuilds')) {
    // The grid is drawn again as each environment lands: a filter being typed
    // in keeps its focus and its caret.
    const f = document.activeElement;
    const typing = f && f.classList && f.classList.contains('reportfilter') ? [f.selectionStart, f.selectionEnd] : null;
    showReportSection(S.reportsSection).then(() => {
      const again = typing && $('#reports-view .reportfilter');
      if (again) { again.focus(); again.setSelectionRange(typing[0], typing[1]); }
    });
  } else paintReportsButton();
  paintLineageBuilds();
}

/* What the canvas paints for the environment this tab picked, or nothing. */
function buildsSpec() {
  if (!S.builds || !(S.features && S.features.snowflake)) return null;
  return buildsDots(S.builds, activeEnv(), buildsStaleDays(), buildsEnvName(activeEnv()), Date.now());
}

function paintLineageBuilds() {
  Lineage.paintBuilds(buildsSpec());
}

/* The button both places share: Read before any, Refresh after. */
function buildsReadButton() {
  const label = S.buildsBusy ? 'Reading…' : S.builds ? 'Refresh' : 'Read from Snowflake';
  const b = jel('button', 'btn sm sfopen', '');
  b.type = 'button';
  b.dataset.tool = 'snowflake';
  b.append(snowflakeIcon(), document.createTextNode(label));
  b.disabled = !!S.buildsBusy;
  b.title = 'Ask the dbt_artifacts tables of each environment in Snowflake when each model last ran. '
    + 'Asked now and only now: nothing is kept past this page, and a sign-in tab may open if the session needs one.';
  b.addEventListener('click', () => readBuilds());
  return b;
}

/* What one environment's failure says. A pure sentence, so the card can keep
   it for a hover and Reports can print it whole. */
function buildsFailureText(entry) {
  // An environment that could not place the tables was never asked, and one
  // after a failed connection was spared: neither is Snowflake's answer.
  return entry.placed === false ? entry.error
    : entry.skipped ? `Not asked, since an earlier environment could not be reached: ${entry.error}`
      : `Snowflake did not answer for ${entry.relation || 'this environment'}: ${entry.error}`;
}

/* A refused connection or a script that could not start is the profile's
   business, so the file is one click away. */
function buildsFailure(entry) {
  const p = jel('p', 'runnote', '');
  p.dataset.tone = 'warn';
  p.append(document.createTextNode(buildsFailureText(entry)));
  const link = (entry.phase === 'connect' || entry.phase === 'start') && profileLink();
  if (link) p.append(document.createTextNode(' The connection comes from '), link, document.createTextNode('.'));
  return p;
}

/* The card says an environment was not read in one line. The message is the
   same on every model, and Builds by environment says it once per
   environment, so the line opens that and keeps the message for a hover. */
function buildsWarning(text, entry) {
  const w = jel('span', 'buildwarn', `⚠ ${text} · details in Reports`);
  w.title = buildsFailureText(entry);
  // A held key must not open the panel again and again.
  linkLike(w, (ev) => { if (!ev.repeat) openReports('builds'); });
  return w;
}

/* The Catalog's section, after the jobs: one block per environment, the
   last attempt on its first line and the last success beside it. */
function catalogBuilds(body, n) {
  if (!buildsOffered() || n.kind !== 'model' || n.disabled || n.materialized === 'ephemeral') return;
  const box = jel('div', 'cat-builds');
  box.dataset.node = n.id;
  body.appendChild(box);
  paintCatalogBuilds(box);
}

function paintCatalogBuilds(box) {
  const id = box.dataset.node;
  const read = S.builds;
  const head = jel('div', 'sechead');
  const about = read
    ? (read.pending ? 'reading…' : `read ${buildsAge(new Date(read.readAt).toISOString(), Date.now())}`)
    : 'not read';
  head.append(h3('last built'), jel('span', 'muted buildsabout', about), buildsReadButton());
  const parts = [head];
  if (!read) {
    parts.push(jel('p', 'muted', 'When this model last ran in each environment, read from the dbt_artifacts tables in Snowflake. '
      + 'Nothing is asked until you press the button.'));
  } else if (read.failed) {
    parts.push(buildsWarning('the builds could not be read', { placed: false, error: read.failed }));
  } else {
    const now = Date.now();
    for (const t of read.targets) {
      const got = read.byEnv[t.env];
      const block = jel('div', 'buildenv');
      const name = jel('span', 'buildname');
      name.append(...buildsEnvHead(t));
      if (!got) {
        block.append(name, jel('span', 'muted', read.pending ? 'waiting for Snowflake…' : ''));
      } else if (got.error) {
        block.append(name, buildsWarning('could not be read', got));
      } else {
        const rows = (got.rows.get(id) || []).slice().sort((a, b) => (Date.parse(buildsWhen(b)) || 0) - (Date.parse(buildsWhen(a)) || 0));
        const v = buildsWorst(rows, buildsStaleDays(), now);
        block.dataset.verdict = v.verdict;
        block.append(name);
        const note = buildsOthersNote(got.target, got.others, got.rows.size);
        if (note) block.append(jel('div', 'muted', note));
        if (!rows.length) {
          block.append(jel('span', 'muted', buildsNoRun(got.target)
            + (got.cut ? ', but the table held more models than are read' : '')));
        } else {
          rows.forEach((r) => block.append(buildRunLine(r, v, now)));
        }
      }
      parts.push(block);
    }
  }
  box.replaceChildren(...parts);
}

/* One run: how it ended and when, then what the invocation says of itself. */
function buildRunLine(r, v, now) {
  const line = jel('div', 'buildrun');
  const when = buildsWhen(r);
  const state = jel('span', 'bstate', r.status || 'unknown');
  state.dataset.status = buildsFailed(r.status) ? 'error' : r.status === 'success' ? 'ok' : 'other';
  const ago = jel('span', '', buildsAge(when, now));
  // run_started_at is the invocation's, not this model's: said as such.
  ago.title = [r.started && `invocation started ${new Date(r.started).toLocaleString()}`,
    r.compiled && `model started ${new Date(r.compiled).toLocaleString()}`,
    r.completed && `model finished ${new Date(r.completed).toLocaleString()}`].filter(Boolean).join('\n');
  line.append(state, ago);
  const bits = [];
  if (r.last_success && (r.status !== 'success')) bits.push(`last success ${buildsAge(r.last_success, now)}`);
  if (r.target) bits.push(`target ${r.target}`);
  if (r.command) bits.push(`dbt ${r.command}`);
  if (r.full_refresh) bits.push('full refresh');
  if (typeof r.rows === 'number') bits.push(`${r.rows} rows`);
  if (r.cloud_job) bits.push(`dbt Cloud job ${r.cloud_job}${r.cloud_run ? `, run ${r.cloud_run}` : ''}`);
  if (bits.length) line.append(jel('span', 'muted', '· ' + bits.join(' · ')));
  if (r.invocation) {
    line.append(jel('code', 'binv', r.invocation), copyGlyph(r.invocation, 'Copy the invocation id'));
  }
  if (r.message && buildsFailed(r.status)) line.append(jel('div', 'rmsg', r.message));
  return line;
}

/* Every model the project builds, by name, asked once per read: each
   environment that lands redraws the section, and a list fetched again each
   time would be a request per environment for the same answer. The server's
   bound is far above any project, and `cut` says when the raw answer reached
   it, before the disabled and ephemeral are filtered out. */
const BUILDS_MODELS_MAX = 200000;

function buildsModels(read) {
  if (!read.modelsAsked) {
    read.modelsAsked = api.get(`/api/search?kind=model&limit=${BUILDS_MODELS_MAX}`).then((hits) => ({
      modelsCut: hits.length >= BUILDS_MODELS_MAX,
      models: hits.filter((h) => !h.disabled && h.materialized !== 'ephemeral')
        .map((h) => ({ id: h.id, name: h.name, package: h.id.split('.')[1] || '' }))
        .sort((a, b) => a.name.localeCompare(b.name) || a.id.localeCompare(b.id)),
    })).catch((e) => { read.modelsAsked = null; throw e; });
  }
  return read.modelsAsked;
}

/* The Reports section: per environment, what needs looking at, then every
   model against every environment. Nothing in it asks Snowflake but the
   button, so showing it again is free. */
async function buildsSection() {
  const read = S.builds;
  const days = buildsStaleDays();
  const about = read
    ? `${read.pending ? 'reading…' : `read ${buildsAge(new Date(read.readAt).toISOString(), Date.now())}`} · stale after ${counted(days, 'day', 'days')}`
    : 'not read';
  const head = reportHead({ title: 'Builds by environment', tool: 'snowflake', about, extra: [buildsReadButton()] });
  const body = jel('div', 'reportbody');
  if (!read) {
    body.append(reportLever('When each model last ran in each environment and how it ended, from the model_executions and '
      + 'invocations tables of the dbt_artifacts package, in the schema each environment places it in. Nothing is asked until you '
      + 'press the button, and nothing of the answer is kept past this page.', 'runnote'));
    return [head, body];
  }
  if (read.failed) {
    body.append(buildsFailure({ error: read.failed }));
    return [head, body];
  }
  let models, modelsCut;
  try {
    ({ models, modelsCut } = await buildsModels(read));
  } catch (e) {
    body.append(jel('p', 'runnote', `The list of models could not be read: ${e.message}`));
    return [head, body];
  }
  const own = (S.meta && S.meta.project) || '';
  const now = Date.now();
  const groups = [];
  for (const t of read.targets) {
    const got = read.byEnv[t.env];
    const title = jel('h3', 'buildsenv', '');
    title.append(...buildsEnvHead(t));
    if (!got) { groups.push({ head: [title, jel('p', 'runnote', read.pending ? 'Waiting for Snowflake…' : '')], folds: [] }); continue; }
    if (got.error) { groups.push({ head: [title, buildsFailure(got)], folds: [] }); continue; }
    const head = [title];
    const others = buildsOthersNote(got.target, got.others, got.rows.size);
    if (others) head.push(jel('p', 'runnote', others));
    if (got.cut) head.push(jel('p', 'runnote', 'The table held more models than are read, so some below may read as not built.'));
    const lists = buildsVerdicts(got, models, own, days, now);
    head.push(reportTiles([
      { label: 'Errored', value: String(lists.error.length), sub: 'last attempt failed', tone: lists.error.length ? 'bad' : '' },
      { label: 'Stale', value: String(lists.stale.length), sub: `no success in ${counted(days, 'day', 'days')}`, tone: lists.stale.length ? 'warn' : '' },
      { label: 'Not built', value: String(lists.none.length), sub: `no run in ${buildsWindowDays()} days`, tone: '' },
      { label: 'Fine', value: String(lists.ok.length), sub: 'built within the threshold', tone: '' },
    ]));
    const fold = (title2, key, tone, open) => ({
      title: title2, tone, rows: lists[key], open, find: (item) => `${item.name} ${item.id}`,
      draw: (hits, d, more) => [reportList(hits, (item) => {
        const li = jel('li', '');
        const link = jel('a', 'filelink', item.name);
        link.title = item.id;
        link.addEventListener('click', (ev) => { ev.preventDefault(); openFromReport(item.id); });
        li.append(link);
        if (key !== 'none') li.append(jel('span', 'muted', ' · ' + buildsSaidBare(item.v, t.name, now, got.target)));
        if (key === 'error' && item.v.last.message) li.append(jel('div', 'rmsg', item.v.last.message));
        return li;
      }, d, 300, more)],
    });
    groups.push({ head, folds: [fold('Errored', 'error', 'bad', true), fold('Stale', 'stale', 'warn', (n) => n <= 20), fold('Not built', 'none', '', false)] });
  }
  const grid = buildsGrid(read, models, own, days);
  // The one filter drives the folds of each environment and the grid under them.
  reportLists(body, groups, 'Filter the models', grid.draw);
  body.append(grid.el);
  if (modelsCut) body.append(jel('p', 'runnote', 'The project holds more models than the server lists at once, so the rest are left out.'));
  return [head, body];
}

/* Every model against every environment: its last attempt and how long ago,
   filtered by name through the section's filter, the project's own models
   unless the packages are asked for. Only the rows on screen are made. */
function buildsGrid(read, models, own, days) {
  const wrap = jel('div', 'buildsgrid');
  const tools = jel('div', 'buildstools');
  const pk = jel('label', 'buildspk');
  const box = jel('input', '');
  box.type = 'checkbox';
  box.checked = !!S.buildsPackages;
  pk.append(box, document.createTextNode(' include packages'));
  const count = jel('span', 'muted', '');
  tools.append(jel('b', '', 'Every model'), pk, count);
  const table = jel('table', 'buildstable');
  wrap.append(tools, table);
  const envs = read.targets;
  // The section's filter, kept here for a change of the checkbox, which draws
  // the grid without the filter being typed in.
  let query = '';
  const draw = (q = query) => {
    query = q;
    S.buildsPackages = box.checked;
    const needle = q.trim().toLowerCase();
    const now = Date.now();
    const shown = models.filter((m) => (box.checked || !own || m.package === own)
      && (!needle || m.name.toLowerCase().includes(needle) || m.id.toLowerCase().includes(needle)));
    const head = jel('tr', '');
    head.append(jel('th', '', 'model'));
    envs.forEach((t) => { const th = jel('th', ''); th.append(buildsEnvHeading(t)); head.append(th); });
    const rows = shown.slice(0, 500).map((m) => {
      const tr = jel('tr', '');
      const link = jel('a', 'filelink', m.name);
      link.title = m.id;
      link.addEventListener('click', (ev) => { ev.preventDefault(); openFromReport(m.id); });
      const first = jel('td', 'bname', '');
      first.append(link);
      tr.append(first);
      envs.forEach((t) => {
        const got = read.byEnv[t.env];
        const td = jel('td', '', '');
        if (!got || got.error) { td.className = 'bnone'; td.textContent = got ? 'not read' : ''; tr.append(td); return; }
        const v = buildsWorst(got.rows.get(m.id), days, now);
        td.dataset.verdict = v.verdict;
        td.title = buildsSaid(v, t.name, now, got.target);
        td.textContent = v.verdict === 'none' ? '-' : `${v.last.status} ${buildsAge(buildsWhen(v.last), now)}`;
        tr.append(td);
      });
      return tr;
    });
    table.replaceChildren(head, ...rows);
    count.textContent = shown.length > 500 ? `${shown.length} models, 500 shown: filter to see the rest` : counted(shown.length, 'model', 'models');
  };
  box.addEventListener('change', () => draw());
  return { el: wrap, draw };
}

/* ------------------------------------------------------- builds by job -- */
/* The same read as Builds by environment, cut by job (0119). The jobs ask the
   server which models each runs; nothing more is asked of Snowflake. */

/* What each job runs, asked once per read for the same reason as the models
   (buildsModels): each environment landing draws the section again. It is
   forgotten when the jobs may have changed (forgetCatalogJobs), and carries
   the verdicts worked out from it, by the answer of each environment. */
function jobBuildsLoad(read) {
  if (!read.jobsAsked) {
    read.jobsAsked = jobsLookGet('/api/jobs/models?look=true').then((r) => ({
      configured: !!r.configured,
      refused: r.sources_refused || '',
      jobs: jobBuildsJobs(r.ids || [], r.jobs),
      memo: new WeakMap(),
    })).catch((e) => { read.jobsAsked = null; throw e; });
  }
  return read.jobsAsked;
}

/* A job's schedule as the Reports' lists draw their pill, and under it, small, the
   zone its cron is read in and so what the verdicts are judged against. A job
   whose cron never fires has a clock and no start to hold a run to, and is
   judged on the threshold like one with no clock. */
function jobBuildsWhen(job, clock) {
  const cell = jel('div', 'jbwhen');
  const pill = jobsWhen(job);
  cell.append(pill);
  const judged = clock && clock.before !== null;
  const threshold = `Late here means no success in ${counted(buildsStaleDays(), 'day', 'days')}.`;
  // The pill's own words first, which its ellipsis may cut (a list of assets),
  // then what the verdicts are judged against.
  const said = [jobsStart(job) !== 'manual' ? jobsScheduleText(job) : 'Manual', jobsStart(job) === 'unread' ? JOBS_UNREAD_WHY : ''].filter(Boolean).join('. ');
  let rule;
  if (judged) {
    cell.append(jel('span', 'jbzone', clock.tz));
    rule = `Late here means no success since the run before the last start of ${clock.said}.`;
  } else if (clock) {
    rule = `${job.cron} does not fire twice in the years this looks back over, so there is no earlier run to hold a model to. ${threshold}`;
  } else {
    rule = `${jobClockWhy(job) || 'No clock of its own.'} ${threshold}`;
  }
  pill.title = `${said}\n${rule}`;
  return cell;
}

/* A job's name, which may break after an underscore, a dot or a dash and
   nowhere else. */
function jobBreakable(name, tag) {
  const box = jel('b', 'rtitle', '');
  for (const piece of name.match(/[^_.-]*[_.-]?/g).filter(Boolean)) box.append(document.createTextNode(piece), document.createElement('wbr'));
  // A name another job has too is told apart, inside the title: the fold is
  // known by it (reportFoldKey).
  if (tag) box.append(jel('span', 'jbalso', ` · ${tag}`));
  return box;
}

/* How one job stands in one environment, in a few words. */
function jobBuildsCell(res, clock) {
  const c = res.counts;
  const cell = jel('div', 'jbcell');
  cell.dataset.verdict = res.tone;
  if (res.clash) { cell.append(jel('span', 'muted', res.clash)); return cell; }
  if (!c.total) { cell.append(jel('span', 'muted', 'no model')); return cell; }
  const bits = [];
  if (c.error) bits.push(`${c.error} errored`);
  if (c.late) bits.push(`${c.late} late`);
  if (c.none) bits.push(`${c.none} not built`);
  // The mark stays on the first line of the words, which may run over several.
  const top = jel('span', 'jbtop');
  top.append(jel('span', 'jobdot'), jel('span', 'jbsay', bits.length ? bits.join(' · ') : c.total === 1 ? 'built' : `all ${c.total} built`));
  cell.append(top);
  if (clock && res.last !== null) cell.append(jel('span', 'muted jbsince', jobSinceText(res, clock.tz)));
  // A cell with models to list opens the row on its environment; the row's
  // handler wires the click, since it knows the fold.
  cell.classList.add('pick');
  cell.setAttribute('role', 'button');
  cell.tabIndex = 0;
  cell.setAttribute('aria-expanded', 'false');
  return cell;
}

/* Which environment a job's row opens on. `listable` is the row's environments
   that have something to list, in column order, as { key, tone }. A pick made
   on this row wins, then the one last made anywhere in the section, then the
   worst, so that a click on the name lands where the eye is likely to be. A
   pick with nothing to list for this job falls through, and a tie in tone
   takes the first column. Pure, so the order is checked without a DOM
   (web/tests/jobbuilds.js). */
function jobBuildsPick(listable, kept, last) {
  const has = (k) => k !== null && k !== undefined && listable.some((e) => e.key === k);
  if (has(kept)) return kept;
  if (has(last)) return last;
  const rank = { error: 3, late: 2, none: 1, ok: 0 };
  let best = null;
  for (const e of listable) {
    if (best === null || (rank[e.tone] || 0) > (rank[best.tone] || 0)) best = e;
  }
  return best === null ? null : best.key;
}

/* The figure of one environment over the jobs: how many of the jobs judged
   there have every model built, with what ails the rest. A job whose models
   cannot be told apart across targets (`clash`) or that runs no model is
   judged by nothing, and `out` counts those left out. */
function jobBuildsTile(label, results, head) {
  const judged = results.filter((r) => !r.clash && r.counts.total);
  const by = (tone) => judged.filter((r) => r.tone === tone).length;
  const error = by('error'), late = by('late'), none = by('none');
  return { label, value: `${by('ok')} of ${judged.length} ${judged.length === 1 ? 'job' : 'jobs'}`,
    sub: [error && `${error} errored`, late && `${late} late`, none && `${none} not built`].filter(Boolean).join(' · '),
    tone: error ? 'bad' : late ? 'warn' : '', out: results.length - judged.length, head };
}

/* The tiles of every environment, and the line under them saying what ok
   means and how many jobs were left out, once when it is the same number
   everywhere; else each tile says its own. `entries` are `{label, results, head}`,
   `head` being the label laid out as nodes, when it is one. */
function jobBuildsTiles(entries) {
  const tiles = entries.map((e) => jobBuildsTile(e.label, e.results, e.head));
  const outs = [...new Set(tiles.map((t) => t.out))];
  const same = outs.length === 1 ? outs[0] : 0;
  if (outs.length > 1) for (const t of tiles) if (t.out) t.sub = [t.sub, `${t.out} left out`].filter(Boolean).join(' · ');
  const said = 'The first figure counts the jobs whose models were all built in time.';
  const left = same ? ` ${same} ${same === 1 ? 'job is' : 'jobs are'} left out of each count: no model, or a target clash.` : '';
  return { tiles, note: tiles.length ? said + left : '' };
}

/* What the environments' tables leave out, a line each kind: those kept to a
   target that built models there count only that target's runs, while the
   table also holds the others'; one with no run under its target says so, as
   Builds by environment does. `envs` are `{name, target, others, rows}`, `rows`
   being how many models it kept runs of; "each" only when every one is kept. */
function jobBuildsTargetsNote(envs) {
  const kept = envs.filter((e) => e.target && e.others && e.others.length);
  const notes = [];
  const counting = kept.filter((e) => e.rows);
  if (counting.length) {
    const named = counting.map((e) => `${e.name}: ${e.target}`).join(', ');
    notes.push(counting.length === envs.length
      ? `Each environment counts only the runs under its own target (${named}); its table also holds runs under other targets, not counted here.`
      : counting.length === 1
        ? `An environment kept to a target counts only the runs under it (${named}); its table also holds runs under other targets, not counted here.`
        : `Environments kept to a target count only the runs under their own target (${named}); their tables also hold runs under other targets, not counted here.`);
  }
  for (const e of kept.filter((x) => !x.rows)) {
    notes.push(`${e.name}: no run under target ${e.target} in the table, which holds runs under ${e.others.join(', ')}: not counted.`);
  }
  return notes;
}

/* What a read cut short leaves out, said of the environments it happened to. */
function jobBuildsCutNote(labels) {
  return labels.length ? `${labels.join(', ')}: The table held more models than are read, so some models may read as not built.` : '';
}

/* The models of one environment worth a look: errored, late, not built. */
function jobBuildsEnv(job, t, res, got, names, now) {
  const d = jel('div', 'jbenv');
  const head = jel('div', 'jbenvhead');
  head.append(...buildsEnvHead(t));
  d.append(head);
  const stepName = new Map((job.step_names || []).map((s) => [s.n, s.name]));
  let listed = 0;
  for (const [label, key] of [['Errored', 'error'], ['Late', 'late'], ['Not built', 'none']]) {
    const items = res.items.filter((i) => i.verdict === key);
    if (!items.length) continue;
    listed++;
    d.append(jel('div', 'jbkind', `${label} (${items.length})`));
    const ul = jel('ul', 'rentries');
    for (const item of items.slice(0, 100)) {
      const li = jel('li', '');
      const link = jel('a', 'filelink', names.get(item.id) || item.id.split('.').slice(2).join('.'));
      link.title = item.id;
      link.addEventListener('click', (ev) => { ev.preventDefault(); openFromReport(item.id); });
      li.append(link);
      const where = item.steps.map((n) => stepName.get(n) || `step ${n}`).join(', ');
      if (where) li.append(jel('span', 'muted', ` · ${where}`));
      if (key !== 'none') li.append(jel('span', 'muted', ' · ' + buildsSaidBare(item.v, t.name, now, got.target)));
      if (key === 'error' && item.worst.last && item.worst.last.message) li.append(jel('div', 'rmsg', item.worst.last.message));
      ul.append(li);
    }
    if (items.length > 100) ul.append(jel('li', 'muted', `and ${items.length - 100} more`));
    d.append(ul);
  }
  if (!listed) d.append(jel('p', 'muted jbfine', res.counts.total === 1 ? 'Built.' : `All ${res.counts.total} models built.`));
  return d;
}

async function jobBuildsSection() {
  const read = S.builds;
  const days = buildsStaleDays();
  const about = read
    ? `${read.pending ? 'reading…' : `read ${buildsAge(new Date(read.readAt).toISOString(), Date.now())}`} · stale after ${counted(days, 'day', 'days')}`
    : 'not read';
  const head = reportHead({ title: 'Builds by job', tool: 'snowflake', about, extra: [buildsReadButton()] });
  const body = jel('div', 'reportbody');
  const intro = reportLever((read ? '' : 'How each job\'s models last ended in each environment, against the job\'s own schedule, from the same read '
    + 'as Builds by environment. Nothing is asked until you press the button. ')
    + 'A model\'s status is its last build, whichever job ran it: dbt_artifacts does not record which job did, so a job is the models its '
    + 'selections reach. Late means no success since the run before the last start of the job\'s schedule, in the zone its source names; '
    + 'a job with no schedule of its own is held to the days set in the Snowflake settings. A model built since the last start is only counted.', 'runnote');
  // The figures come first once there are some: the intro follows them.
  const early = (...els) => { body.append(intro, ...els); return [head, body]; };
  if (!read) return early();
  if (read.failed) return early(buildsFailure({ error: read.failed }));
  let cfg, models;
  try {
    [cfg, { models }] = await Promise.all([jobBuildsLoad(read), buildsModels(read)]);
  } catch (e) {
    return early(jel('p', 'runnote', `The jobs could not be read: ${e.message}`));
  }
  if (cfg.refused) return early(jel('div', 'jobs-warn', `.dbt-edith/jobs.yml is not read: ${cfg.refused}.`));
  if (!cfg.jobs.length) return early(jel('p', 'runnote', 'No job was read from the sources.'));
  const names = new Map(models.map((m) => [m.id, m.name]));
  const now = Date.now();
  const ready = read.targets.filter((t) => read.byEnv[t.env] && !read.byEnv[t.env].error);
  // Each job's clock and its last two starts are worked out once for the
  // section, and its verdicts once per environment's answer: a new answer is
  // a new object, so an environment landing judges its own and no other.
  const clocks = new Map(cfg.jobs.map((j) => [j, jobFires(jobClock(j), now)]));
  const stamp = `${days}|${Math.floor(now / 60000)}`;
  const verdictsOf = (job, t) => {
    const got = read.byEnv[t.env];
    let kept = cfg.memo.get(got);
    if (!kept || kept.stamp !== stamp) { kept = { stamp, byJob: new Map(), worst: new Map() }; cfg.memo.set(got, kept); }
    if (!kept.byJob.has(job)) kept.byJob.set(job, jobBuildVerdicts(job, got, clocks.get(job), days, now, kept.worst));
    return kept.byJob.get(job);
  };
  const figures = jobBuildsTiles(ready.map((t) => ({ label: buildsEnvLabel(t), head: buildsEnvHeading(t), results: cfg.jobs.map((j) => verdictsOf(j, t)) })));
  body.append(reportTiles(figures.tiles));
  if (figures.note) body.append(jel('p', 'runnote', figures.note));
  body.append(intro);
  // An environment that could not be read says so once, above the jobs.
  for (const t of read.targets) {
    const got = read.byEnv[t.env];
    if (got && !got.error) continue;
    const title = jel('h3', 'buildsenv', '');
    title.append(...buildsEnvHead(t));
    body.append(title, got ? buildsFailure(got) : jel('p', 'runnote', read.pending ? 'Waiting for Snowflake…' : ''));
  }
  // What the environments' rows leave out, said once for those that share the words.
  const notes = jobBuildsTargetsNote(ready.map((t) => ({ name: t.name, target: read.byEnv[t.env].target, others: read.byEnv[t.env].others,
    rows: read.byEnv[t.env].rows.size })));
  notes.push(jobBuildsCutNote(ready.filter((t) => read.byEnv[t.env].cut).map(buildsEnvLabel)));
  for (const note of notes.filter(Boolean)) body.append(jel('p', 'runnote', note));
  const count = jel('p', 'runnote', '');
  const list = jel('div', 'jobbuilds');
  list.style.setProperty('--envs', String(Math.max(1, ready.length)));
  // The schedule column is as wide as its longest pill, which stays on one
  // line: each row is a grid of its own, so the width is given to all of them.
  const widest = Math.max(0, ...cfg.jobs.map((j) => jobsScheduleText(j).length));
  list.style.setProperty('--sched', `${Math.min(560, Math.ceil(widest * 6.8) + 110)}px`);
  // The table takes the panel's width and shrinks to it; many environments
  // scroll it sideways.
  const scroll = jel('div', 'jbscroll');
  scroll.append(list);
  const head2 = jel('div', 'jbrow jbheads');
  head2.append(jel('span', '', 'job'), jel('span', '', 'kind'), jel('span', '', 'schedule'), jel('span', '', 'models'));
  ready.forEach((t) => {
    const h = jel('span', 'jbenvh');
    h.append(buildsEnvHeading(t));
    h.title = buildsEnvLabel(t);
    head2.append(h);
  });
  // Every row is made once; the filter only hides them. The detail of a job,
  // the lists of one environment, is made when the row opens.
  const twins = jobsTwinTags(cfg.jobs);
  const rows = jobsByStart(cfg.jobs, (j) => j).map((job) => {
    const clock = clocks.get(job);
    const d = jel('details', 'jobbuild');
    const row = jel('summary', 'jbrow');
    const nameBox = jel('span', 'jbname');
    const nm = jobBreakable(job.name, twins.get(job));
    nm.title = `${job.source} · ${job.file}:${job.line}`;
    nameBox.append(reportChevron(), nm);
    const meta = jel('span', 'jbmodels', counted(job.models.length, 'model', 'models'));
    const apart = (job.seeds || 0) + (job.snapshots || 0);
    if (apart) meta.append(jel('span', 'muted', ` + ${counted(apart, 'seed or snapshot', 'seeds and snapshots')} not read`));
    row.append(nameBox, jel('span', 'muted jbtag', job.kind === 'dbt_cloud' ? 'dbt Cloud job' : 'DAG'), jobBuildsWhen(job, clock), meta);
    // A job has something to open only where an environment judged its models.
    const nameKey = `${job.name} ${twins.get(job) || ''}`.toLowerCase();
    // Case-sensitive and per file, unlike the filter's name: two jobs that differ
    // only in case must not share a pick.
    const pickKey = `${job.source}|${job.file}:${job.line}|${job.name}|${twins.get(job) || ''}`;
    const listable = [];
    const cells = new Map();
    for (const t of ready) {
      const res = verdictsOf(job, t);
      const cell = jobBuildsCell(res, clock);
      cell.title = `${buildsEnvLabel(t)}: ${res.clash ? res.clash : res.basis === 'clock' ? 'judged by ' + clock.said : 'judged on the threshold'}`;
      row.append(cell);
      if (!res.clash && res.counts.total) {
        listable.push({ key: t.env || '', tone: res.tone, t, res });
        cells.set(t.env || '', cell);
        cell.title += '\nClick to list its models here.';
      }
    }
    d.append(row);
    if (!listable.length) {
      d.classList.add('empty');
      // Nothing to open: a click on the row does not.
      row.addEventListener('click', (ev) => ev.preventDefault());
    }
    const picks = S.jobBuildsPick;
    let detail = null;
    // The row shows one environment at a time; drawing replaces what it held.
    const draw = (key) => {
      const e = listable.find((x) => x.key === key);
      if (!e) return;
      if (!detail) { detail = jel('div', 'jbdetail'); d.append(detail); }
      if (detail.dataset.env === key) return;
      detail.dataset.env = key;
      detail.replaceChildren();
      // The rule late is judged by is the job's, said once.
      if (clock && clock.before !== null) {
        detail.append(jel('div', 'jbrule', `Late: no success since ${zoneStamp(clock.before, clock.tz)}, the run before the last start.`));
      }
      detail.append(jobBuildsEnv(job, e.t, e.res, read.byEnv[e.t.env], names, now));
      for (const [k, cell] of cells) {
        cell.classList.toggle('picked', k === key);
        cell.setAttribute('aria-expanded', k === key ? 'true' : 'false');
      }
    };
    for (const [key, cell] of cells) {
      const act = (ev) => {
        // Else the summary the cell sits in toggles the row on its own.
        ev.preventDefault();
        ev.stopPropagation();
        if (d.open && detail && detail.dataset.env === key) { d.open = false; return; }
        picks.rows[pickKey] = key;
        picks.last = key;
        draw(key);
        d.open = true;
      };
      cell.addEventListener('click', act);
      cell.addEventListener('keydown', (ev) => {
        if (ev.key !== 'Enter' && ev.key !== ' ') return;
        // A held key must not open and close the row in turn.
        if (ev.repeat) { ev.preventDefault(); return; }
        act(ev);
      });
    }
    d.addEventListener('toggle', (ev) => {
      // A fold the place restored on a row with nothing to open now closes.
      if (d.open && !listable.length) { d.open = false; return; }
      if (!d.open) {
        delete picks.rows[pickKey];
        if (detail) { detail.remove(); detail = null; }
        for (const cell of cells.values()) { cell.classList.remove('picked'); cell.setAttribute('aria-expanded', 'false'); }
        return;
      }
      // Already drawn: the native toggle that follows a cell click or the
      // place's own dispatch.
      if (detail) return;
      // Only restoreReportPlace dispatches a toggle by hand, and it reopens
      // only folds that were open when the place was kept: so an entry in
      // picks.rows, which a draw that dropped the rows without closing them
      // may have left stale, is read only there, where it is not stale. A
      // click on the row, the name included, takes the last pick or the worst.
      const key = jobBuildsPick(listable, ev.isTrusted ? null : picks.rows[pickKey], picks.last);
      if (key === null) return;
      picks.rows[pickKey] = key;
      draw(key);
    });
    return { name: nameKey, el: d };
  });
  list.replaceChildren(head2, ...rows.map((r) => r.el));
  const apply = (text = '') => {
    const q = text.trim().toLowerCase();
    let shown = 0;
    for (const r of rows) {
      r.el.hidden = !!q && !r.name.includes(q);
      if (!r.el.hidden) shown++;
    }
    count.textContent = counted(shown, 'job', 'jobs');
  };
  // No fold to filter: the filter hides rows of the table.
  reportLists(body, [], 'Filter the jobs', apply);
  body.append(count, scroll);
  return [head, body];
}

/* The Jobs tab on a node, which may not be the focus, at the step a chip
   names. */
function showJobsFor(id, reveal) {
  S.jobsFor = id === S.focus ? null : id;
  S.jobsReveal = reveal ? Object.assign({ id }, reveal) : null;
  showDock('jobs');
}

/* Which tests a Tests cell shows, and what the +N stands for. Pure, so the cap
   and its edge cases are checked without a DOM (web/tests/testchips.js). Each
   entry is one test node, so two `relationships` on one column are two entries:
   the cell used to hold names, and a name cannot tell them apart. */
function testChips(tests, max, chars) {
  const all = tests || [];
  // Both caps live here rather than beside the cell, so the harness pins the
  // numbers the cell actually uses: a `const` next to it would not survive the
  // slice the harness evaluates.
  const cap = max || 3;
  // Counting chips is not enough. Three of dbt_expectations' names are longer
  // than the Description column and wrap the row to three lines, while three of
  // not_null, unique and one more sit on one. The budget is what keeps every
  // row the same height, whatever the names happen to be.
  const room = chars || 48;
  let used = 0;
  let n = 0;
  while (n < all.length && n < cap) {
    used += (all[n].label || '').length;
    // The first chip is shown however long its name: a cell that says only +4
    // names nothing at all.
    if (n && used > room) break;
    n++;
  }
  if (n >= all.length) return { shown: all, hidden: [] };
  return { shown: all.slice(0, n), hidden: all.slice(n) };
}

/* A node's tests, split by what each one guards. A test naming a column is
   already a chip in that column's row; one naming none guards the whole table
   and has no row it could ever appear in, which is why the two are listed apart
   rather than in one list where the difference is a missing suffix. */
function splitTests(tests) {
  const all = tests || [];
  return { model: all.filter((t) => !t.column), column: all.filter((t) => t.column) };
}

/* Every test guarding one column, behind the +N chip. Unlike fillNodeCard there
   is nothing to fetch: /api/node already sent all of them. */
function fillTestsCard(el, n, c) {
  hoverCardBody(el, { title: c.name, sub: `${c.tests.length} tests`, crumb: n.name });
  const list = document.createElement('div');
  list.className = 'hc-tests';
  for (const t of c.tests) {
    const row = document.createElement('div');
    row.className = 'hc-test';
    row.append(Object.assign(document.createElement('span'), { className: 't-label', textContent: t.label }));
    // dbt's generated name carries what the generic was given: which table a
    // relationships points at, which column it joins on.
    row.append(Object.assign(document.createElement('span'), { className: 't-name', textContent: t.name }));
    list.appendChild(row);
  }
  el.appendChild(list);
  // The list is taller than the head the card was placed with.
  placeHoverCard();
}

/* Fills one Tests cell, collapsed or expanded. Repaints itself rather than
   keeping the expansion in S: sorting or reopening the node rebuilds the table
   anyway, and a key in S would only be there to go stale. */
function paintTests(td, n, c, expanded) {
  td.textContent = '';
  // The chips wrap in a box of their own: a cell cannot be a flex box and stay a cell.
  const box = td.appendChild(Object.assign(document.createElement('div'), { className: 'testchips' }));
  const all = c.tests || [];
  if (!all.length) {
    box.append(Object.assign(document.createElement('span'), { className: 'nul', textContent: '–' }));
    return;
  }
  const cut = expanded ? { shown: all, hidden: [] } : testChips(all);
  for (const t of cut.shown) {
    const chip = document.createElement('span');
    chip.className = 'testchip' + (t.label === 'not_null' ? ' nn' : t.label === 'unique' ? ' un' : '');
    chip.textContent = t.label;
    box.appendChild(chip);
    if (!t.file) { chip.title = `${t.name}\n${t.id}`; continue; }
    // A chip opens its test where it is declared (0041): a chip hangs on the
    // model whose YAML declares it, the one this Catalog shows.
    chip.title = `${t.name}\n${t.id}\nclick: open where it is declared`;
    chip.tabIndex = 0;
    chip.setAttribute('role', 'button');
    const go = (e) => {
      e.stopPropagation();
      openTest({ kind: 'test', file: t.file, host: n.name, column: c.name, test_name: t.label, name: t.name });
    };
    chip.addEventListener('click', go);
    chip.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      e.preventDefault();
      go(e);
    });
  }
  if (!cut.hidden.length && !expanded) return;

  const more = document.createElement('span');
  more.className = 'testchip more';
  more.textContent = expanded ? '−' : `+${cut.hidden.length}`;
  more.tabIndex = 0;
  more.setAttribute('role', 'button');
  more.setAttribute('aria-expanded', String(expanded));
  more.setAttribute('aria-label', expanded
    ? `show fewer tests on ${c.name}`
    : `show all ${all.length} tests on ${c.name}`);
  // No native title here: one under a hover card is two tooltips.
  const open = () => hoverEnter(`tests:${n.id}:${c.name}`, () => more.getBoundingClientRect(), (el) => fillTestsCard(el, n, c));
  more.addEventListener('mouseenter', open);
  more.addEventListener('mouseleave', hoverLeave);
  // A hover is no affordance on a touch screen and no route from a keyboard, so
  // the click expands the chips in the cell itself and focus opens the card for
  // whoever tabbed here. Reopening the card on a second click cannot work: the
  // card closes on any outside mousedown, so the click would close and reopen it
  // forever rather than toggle.
  more.addEventListener('focus', open);
  more.addEventListener('blur', hoverLeave);
  const toggle = (e) => {
    e.stopPropagation();
    closeHoverCard();
    paintTests(td, n, c, !expanded);
    const next = td.querySelector('.testchip.more');
    if (next && e.type !== 'click') next.focus();
  };
  more.addEventListener('click', toggle);
  more.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' && e.key !== ' ') return;
    e.preventDefault();
    toggle(e);
  });
  box.appendChild(more);
}

/* Whether a column answers the Columns filter: its name holds the text, in any
   case. The name alone, because that is what the filter is for finding, and a
   description mentioning the same word would bury the column called that
   under every column that talks about it. */
function columnMatches(c, query) {
  return !query || c.name.toLowerCase().includes(query.toLowerCase());
}

/* Cmd+F in the Catalog. The columns are what there is to find there, so the
   Preview tab gives way to the Columns one. */
function focusColumnFilter() {
  const n = S.node;
  if (!n || !n.columns.length) return false;
  if (S.catTab !== 'columns') showCatalogTab(n, 'columns');
  const box = $('#col-filter');
  if (!box) return false;
  box.focus();
  box.select();
  return true;
}

/* The whole chain of each column of a node, asked for by the Columns table
   alone (0089). Kept with the /api/node payload it completes: sorting or
   filtering the table paints it again at once, and a payload asked for again,
   as the node cache does every few seconds, asks again too. */
function columnReaches(n) {
  let hit = S.colReach.get(n);
  if (!hit) {
    hit = { v: null };
    hit.p = api.get('/api/colreach?id=' + encodeURIComponent(n.id))
      .then((rows) => (hit.v = new Map(rows.map((r) => [r.name, r]))))
      .catch((e) => { S.colReach.delete(n); throw e; });
    S.colReach.set(n, hit);
  }
  return hit;
}

/* A column's Lineage cell: the whole chain on each side, as the Preview's
   "in total" is for a model, and one level on hover (0089). One level alone
   reads as how far the column goes, and the canvas goes further. `r` is the
   chain, undefined while it is on its way, null when it could not be had.
   The figures are the default canvas's: with `indirect`, a cache holding
   collin's indirect edges, the hover says they are left out (0097). */
function columnReach(c, r, indirect) {
  const one = `directly: ${c.up} column${c.up === 1 ? '' : 's'} upstream, ${c.down} downstream`;
  const left = indirect ? '\nindirect edges left out, as on the canvas with its indirect button off' : '';
  if (r === undefined) return { up: '\u2190\u2026', down: '\u2026\u2192', title: one + left };
  if (!r) return { up: `\u2190${c.up}`, down: `${c.down}\u2192`, title: `${one}\nthe whole chain could not be counted${left}` };
  return { up: `\u2190${r.up}`, down: `${r.down}\u2192`, title: `${one}\nin all: ${r.up} upstream, ${r.down} downstream${left}` };
}

/* One side of a Lineage cell, `\u21902` or `2\u2192`, as its arrow and its
   figure apart, so the figure can be the one to stand out. */
function reachParts(text) {
  const figure = (t) => Object.assign(document.createElement('b'), { textContent: t });
  return text.startsWith('\u2190') ? ['\u2190', figure(text.slice(1))] : [figure(text.slice(0, -1)), text.slice(-1)];
}

/* Whether the Columns table has a Lineage column: Snowflake picked, or a
   column with an edge, a mark of collin's, or a value it is generated from,
   which a column nothing reads still has (0096). */
function lineageColumnShown(columns, live, flags) {
  return live || columns.some((c) => c.up || c.down || c.indirect || Array.isArray(c.generated) || flags.has(c.name.toLowerCase()));
}

/* Whether a click on a column's row opens its lineage: an edge, Snowflake to
   ask, or a root nothing reads, drawn alone with its badge and its value on
   hover, as every filled Lineage cell opens. So does a column only collin's
   indirect edges reach or leave, which `up` and `down` leave out: its box,
   with a card saying what keeps its rows when they reach it, and the indirect
   button draws them (0097). A mark of collin's alone does not: there is
   nothing to draw. */
function columnOpens(c, live) {
  return !!(c.up || c.down || live || c.indirect || Array.isArray(c.generated));
}

/* The Lineage cell of a column only collin's indirect edges reach or leave:
   not the "-" of a column with nothing, since its row opens and the indirect
   button draws them (0097). Null for any other column. */
function indirectOnlyCell(c) {
  if (!c.indirect || c.up || c.down) return null;
  return { text: 'indirect only', title: 'only indirect edges reach or leave it; turn indirect on to draw them' };
}

/* What the filter box says at its right edge: how many columns the word kept
   (only while one is typed), then how many have a type from catalog.json. No
   types at all is a sentence of its own beside the box, so nothing here. */
function columnCountText(kept, total, typed, filtering) {
  return [filtering ? `${kept} of ${total}` : '', typed ? `${typed}/${total} typed` : ''].filter(Boolean).join(' \u00b7 ');
}

function catalogColumns(body, n) {
  if (!n.columns.length) {
    if (S.colReveal === n.id && S.dock === 'catalog') S.colReveal = '';
    const p = document.createElement('p');
    p.className = 'muted';
    p.textContent = 'No column is declared for this node. Document them in the YAML, or run dbt docs generate so catalog.json lists the warehouse columns.';
    body.appendChild(p);
    return;
  }

  const tools = document.createElement('div');
  tools.className = 'coltools';
  // Kept from one node to the next, so a column can be followed through the
  // lineage: click the next model and the filter is already asking for it.
  const filter = document.createElement('input');
  filter.id = 'col-filter';
  filter.className = 'colfilter';
  filter.placeholder = 'Filter columns';
  filter.setAttribute('aria-label', 'Filter columns by name');
  filter.value = S.colFilter;
  filter.spellcheck = false;
  filter.autocomplete = 'off';
  filter.title = `Filter the columns by name (${keyLabel('Mod+F', IS_MAC)}). ${keyLabel('Escape', IS_MAC)} clears it.`;
  // The count of columns kept and the count typed sit together inside the box,
  // at its right edge.
  const shown = document.createElement('span');
  shown.className = 'colcount';
  const box = document.createElement('label');
  box.className = 'colfind';
  box.append(strokeIcon('0 0 16 16', 'colfind-ico', ['M7 2.25a4.75 4.75 0 1 0 0 9.5 4.75 4.75 0 0 0 0-9.5z', 'M10.5 10.5l3.5 3.5']), filter, shown);
  tools.append(box);
  const untyped = n.columns.filter((c) => !c.data_type).length;
  const typed = n.columns.length - untyped;
  if (!typed) {
    tools.append(Object.assign(document.createElement('span'), {
      textContent: 'no types: run dbt compile --write-catalog to pull them from Snowflake',
    }));
  }
  tools.append(sourceMenu());
  // This table can only ever show the tests that name a column. Saying how many
  // it cannot show is what stops it from reading as the whole story.
  const onModel = splitTests(n.tests).model.length;
  if (onModel) {
    const span = document.createElement('span');
    span.className = 'colhint modeltests';
    span.textContent = `${onModel} guard the model itself`;
    span.title = 'a singular test, or a generic naming no column: no column row can hold it.\nclick to list them in Preview';
    span.addEventListener('click', () => showCatalogTab(n, 'preview'));
    tools.appendChild(span);
  }
  const hint = columnsHint(S.sidecar, n.columns.some((c) => c.up || c.down))
    || collinHint(S.cllTool, S.collin, S.meta && S.meta.cll_kinds);
  if (hint) {
    const span = document.createElement('span');
    span.className = 'colhint';
    span.dataset.tone = hint.tone;
    span.textContent = hint.text;
    if (hint.title) span.title = hint.title;
    if (hint.tone === 'failed') span.title = (((sidecarOn() ? S.sidecar : S.collin) || {}).log || []).join('\n');
    tools.appendChild(span);
  }
  if (S.cllTool === 'collin' && S.collin && S.collin.found) {
    const again = document.createElement('button');
    again.className = 'btn sm ghost';
    again.textContent = 'Regenerate';
    again.disabled = S.collin.state === 'running';
    again.title = 'Run collin again over the compiled SQL. Run dbt compile first for SQL that changed.';
    again.addEventListener('click', () => regenerateCollin());
    tools.appendChild(again);
  }
  // Each column of a key, by the key's letter and its place in the key,
  // expressions included; a column named twice in a key keeps its first place.
  const keys = n.keys || [];
  const keyed = new Map();
  keys.forEach((key, ki) => {
    const letter = keyLetter(ki, keys.length);
    key.entries.forEach((entry, at) => {
      const name = columnKey(entry);
      const here = keyed.get(name) || [];
      if (!here.some((h) => h.ki === ki)) keyed.set(name, here.concat({ key, letter, ki, at }));
    });
  });
  // Kept from node to node like the others; a node with no key naming a column
  // of the table, an expression or a column listed nowhere, has no Key button
  // that would move nothing, and sorts A-Z until the next one that has.
  const keyShown = keys.some((k) => keyColumns(k.entries, n.columns).some((e) => e.column));
  const sort = S.colSort === 'key' && !keyShown ? 'az' : S.colSort;
  tools.append(Object.assign(document.createElement('div'), { className: 'grow' }));
  tools.appendChild(document.createTextNode('Sort'));
  const seg = document.createElement('span');
  seg.className = 'seg';
  seg.setAttribute('role', 'group');
  seg.setAttribute('aria-label', 'Sort the columns');
  for (const [key, label] of [['az', 'A\u2013Z'], ['tests', 'Tests'], ...(keyShown ? [['key', 'Key']] : [])]) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'segbtn' + (sort === key ? ' active' : '');
    b.textContent = label;
    b.setAttribute('aria-pressed', String(sort === key));
    if (key === 'key') b.title = 'the columns of the keys first, by key and place in it, then the rest A-Z';
    b.addEventListener('click', () => { S.colSort = key; renderCatalog(n); });
    seg.appendChild(b);
  }
  tools.appendChild(seg);
  body.appendChild(tools);
  const said = S.cllTool === 'collin' && collinModelNote(n.collin, n.columns);
  const flags = S.cllTool === 'collin' ? collinColumnNotes(n.collin) : new Map();
  if (said) body.appendChild(Object.assign(document.createElement('div'), { className: 'colnote', textContent: said }));

  const cols = [...n.columns];
  // A column with no test has no `tests` at all: the payload skips it empty.
  if (sort === 'tests') cols.sort((a, b) => (b.tests || []).length - (a.tests || []).length || a.name.localeCompare(b.name));
  else if (sort === 'key') {
    const first = (c) => (keyed.get(columnKey(c.name)) || [{ ki: Infinity, at: Infinity }])[0];
    cols.sort((a, b) => first(a).ki - first(b).ki || first(a).at - first(b).at || a.name.localeCompare(b.name));
  } else cols.sort((a, b) => a.name.localeCompare(b.name));

  // With Snowflake picked, every column can be asked about, not just the cached ones.
  const live = sidecarOn();
  const linked = lineageColumnShown(n.columns, live, flags);
  const reaches = n.columns.some((c) => c.up || c.down) ? columnReaches(n) : null;
  const table = document.createElement('table');
  table.className = 'cols';
  const head = document.createElement('tr');
  (linked ? ['Column', 'Type', 'Description', 'Tests', 'Lineage'] : ['Column', 'Type', 'Description', 'Tests']).forEach((t) => {
    const th = document.createElement('th');
    th.textContent = t;
    head.appendChild(th);
  });
  table.appendChild(head);

  const nul = () => {
    const s = document.createElement('span');
    s.className = 'nul';
    s.textContent = "\u2013";
    return s;
  };
  const rows = [];
  let focused = null;
  for (const c of cols) {
    const tr = document.createElement('tr');
    if (c.undeclared) tr.className = 'c-undeclared';
    const name = document.createElement('td');
    name.className = 'c-name';
    // The filter rewrites the name to mark what matched; the KEY tag sits
    // beside it, out of reach of that rewrite.
    const text = Object.assign(document.createElement('span'), { textContent: c.name });
    name.append(text);
    for (const { key, letter } of keyed.get(columnKey(c.name)) || []) {
      const tag = keyTag(key, letter, c.name);
      name.append(Object.assign(document.createElement('span'), {
        className: tag.dashed ? 'keytag dashed' : 'keytag', textContent: tag.text, title: tag.title,
      }));
    }
    rows.push({ tr, name: text, c });
    if (c.undeclared) name.title = 'in the warehouse but not declared in YAML';
    const type = document.createElement('td');
    type.className = 'c-type';
    type.append(c.data_type || nul());
    const desc = document.createElement('td');
    desc.className = 'c-desc';
    desc.append(c.description || nul());
    const tests = document.createElement('td');
    tests.className = 'c-tests';
    paintTests(tests, n, c, false);
    tr.append(name, type, desc, tests);
    if (linked) {
      const lin = document.createElement('td');
      lin.className = 'c-lin';
      const action = live ? `fetch the lineage of ${c.name} from Snowflake` : `column lineage for ${c.name}`;
      // Where the column comes from, so before the counts: a root's upstream
      // is its value. Its own title, so hovering it says what it is.
      if (Array.isArray(c.generated)) {
        const said = Lineage.generatedSaid(c.generated);
        lin.append(Object.assign(document.createElement('span'), { className: 'c-gen', textContent: said.short, title: said.long }));
        if (c.up || c.down || live) lin.append(document.createTextNode('  '));
      }
      if (c.up || c.down) {
        // The figure alone is bold, the arrow stays dim (reachParts).
        const u = document.createElement('span');
        const dn = document.createElement('span');
        lin.append(u, document.createTextNode('  '), dn);
        // The cell's title wins over the row's, so it says what a click does too.
        const fill = (r) => {
          const reach = columnReach(c, r, cacheHasIndirect(S.meta && S.meta.cll_kinds));
          u.replaceChildren(...reachParts(reach.up));
          dn.replaceChildren(...reachParts(reach.down));
          lin.title = `${reach.title}\n${action}`;
        };
        if (reaches.v) fill(reaches.v.get(c.name) || null);
        else {
          fill(undefined);
          reaches.p.then((v) => fill(v.get(c.name) || null), () => fill(null));
        }
      } else if (live) {
        const ask = document.createElement('span');
        ask.className = 'c-ask';
        ask.textContent = 'fetch';
        lin.append(ask);
      } else if (!lin.firstChild && indirectOnlyCell(c)) {
        const only = indirectOnlyCell(c);
        lin.append(Object.assign(document.createElement('span'), { className: 'c-ask', textContent: only.text, title: only.title }));
      } else if (!lin.firstChild) {
        lin.append(nul());
      }
      const flagged = flags.get(c.name.toLowerCase());
      if (flagged) {
        // In the Lineage cell because it is the lineage it qualifies; its own
        // title, so hovering it says why rather than what a click does.
        const mark = document.createElement('span');
        mark.className = 'c-flag';
        mark.textContent = '!';
        mark.title = flagged.join('\n');
        lin.append(mark);
        tr.classList.add('c-flagged');
      }
      if (columnOpens(c, live)) {
        tr.classList.add('c-linked');
        tr.title = action;
        // The name cell is left out of the click target on purpose: copying a
        // column name is the more common thing to want, and a click target
        // makes the text impossible to select. The Tests cell is left out
        // because its +N chip owns the click. The rest of the row still opens
        // the lineage, so column mode stays reachable from here.
        tr.addEventListener('click', (e) => {
          if (e.target.closest('.c-name, .c-tests')) return;
          openColumn(n, c.name);
        });
      }
      tr.appendChild(lin);
    }
    // Compared as Snowflake compares names, since a report, a column box or
    // Snowflake's own lineage may spell it in another case.
    if (S.colHighlight && columnKey(c.name) === columnKey(S.colHighlight)) {
      tr.classList.add('c-focus');
      focused = rows[rows.length - 1];
    }
    table.appendChild(tr);
  }
  body.appendChild(table);
  const none = document.createElement('p');
  none.className = 'muted';
  body.appendChild(none);

  // Rows are hidden in place rather than the table redrawn, so the box keeps
  // the focus and a +N chip opened further down stays open.
  const apply = () => {
    const q = S.colFilter.trim();
    let kept = 0;
    for (const r of rows) {
      const hit = columnMatches(r.c, q);
      r.tr.classList.toggle('hidden', !hit);
      if (!hit) continue;
      kept++;
      const [before, match, after] = splitMatch(r.c.name, q);
      r.name.textContent = before;
      if (match) r.name.append(Object.assign(document.createElement('mark'), { textContent: match }));
      r.name.append(after);
    }
    shown.textContent = columnCountText(kept, rows.length, typed, !!q);
    none.textContent = q && !kept ? `No column name contains "${q}".` : '';
    none.classList.toggle('hidden', !none.textContent);
  };
  filter.addEventListener('input', () => {
    S.colFilter = filter.value;
    apply();
  });
  filter.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    e.preventDefault();
    if (filter.value) {
      filter.value = S.colFilter = '';
      apply();
    } else {
      filter.blur();
    }
  });
  apply();
  // A column just asked for is brought into view, once, on the node it was
  // asked on: a filter hiding it is cleared, and typing in the filter
  // afterwards is left alone. It waits for the Catalog to be in front, and is
  // spent on that node even when the table has no such row.
  if (S.colReveal === n.id && S.dock === 'catalog') {
    S.colReveal = '';
  } else {
    focused = null;
  }
  if (focused) {
    if (focused.tr.classList.contains('hidden')) {
      filter.value = S.colFilter = '';
      apply();
    }
    // The row on screen at the next frame: a second draw before it replaces
    // this table.
    requestAnimationFrame(() => {
      const row = $('#catalog .cols tr.c-focus');
      if (row) row.scrollIntoView({ block: 'nearest' });
    });
  }
}

// --------------------------------------------------------------- terminal --
/* What a key in the terminal does to the clipboard, or '' to leave it to the
   shell. On a Mac, Cmd+C and Cmd+V already reach the browser, and Ctrl+C has to
   stay an interrupt. Elsewhere xterm.js sends both to the shell, as ^C and ^V,
   so neither copies nor pastes. This is what Windows Terminal does instead:
   Ctrl+C copies when something is selected and interrupts otherwise, Ctrl+V
   pastes, and Ctrl+Shift+C and Ctrl+Shift+V always copy and paste, the first
   of which would otherwise open the browser's element picker. Ctrl with Alt is
   AltGr on Windows, a character on the layouts that have one (0044). */
function termClipboard(e, mac, selected) {
  if (mac || e.type !== 'keydown' || !e.ctrlKey || e.altKey || e.metaKey) return '';
  const key = (e.key || '').toLowerCase();
  if (key === 'c' && (selected || e.shiftKey)) return 'copy';
  if (key === 'v') return 'paste';
  return '';
}

/* What a line key sends the shell in place of what xterm.js sends, or ''.
   `at` says where it lands: `os` as KEYS_OS, `shell` as /api/meta names it,
   `prompt` as S.termPrompt, `screen`, xterm.js's buffer type, and
   `appCursor`, whether a program asked for application cursor keys.
   On a Mac, xterm.js drops every key held with Cmd, so Cmd+Left and Cmd+Right
   did nothing, and Cmd+Backspace deleted one character. They get the bytes VS
   Code's terminal sends: Ctrl+A, Ctrl+E and Ctrl+U, start of line, end of line,
   and the line deleted back to its start (all of it, in zsh). Option+Left and
   Option+Right already move by word, as ESC b and ESC f; Option+Delete, the
   forward one, gets ESC d, where xterm.js sends a sequence zsh leaves unbound.
   On the Windows VM, Ctrl+Left, Ctrl+Right and Home did nothing in Git Bash.
   xterm.js sends them as CSI sequences, which ConPTY turns into keys and back
   into sequences for bash, whose readline looks them up in Git's inputrc.
   To bash they now go as keys readline binds by itself: Ctrl+A and Ctrl+E for
   Home and End, ESC b and ESC f for Ctrl+Left and Ctrl+Right, and VS Code's
   Ctrl+W and ESC d for Ctrl+Backspace and Ctrl+Delete. The ESC ones still
   cross ConPTY as escape sequences, read there as Alt with a letter.
   A program reading the keys itself gets xterm.js's: one on the alternate
   screen, and anything bash started, a pager less -X keeps on the normal
   screen, PowerShell typed at its prompt, or a prompt of its own. On Windows,
   when bash never reported its prompt, application cursor keys stand in for
   that, as less asks for them and Git Bash's prompt does not. Not on a Mac,
   where oh-my-zsh asks for them at every prompt, and where a pager reading
   Ctrl+E as a line down is little worse than Cmd doing nothing, as in VS
   Code. PowerShell as the shell, and Linux, keep xterm.js's keys (0073). */
function termLineKey(e, at) {
  if (e.type !== 'keydown' || e.shiftKey || e.isComposing) return '';
  if (at.screen !== 'normal' || at.prompt === false) return '';
  if (at.os === 'mac') {
    if (e.ctrlKey) return '';
    if (e.metaKey && !e.altKey) return { ArrowLeft: '\x01', ArrowRight: '\x05', Backspace: '\x15' }[e.key] || '';
    if (e.altKey && !e.metaKey && e.key === 'Delete') return '\x1bd';
    return '';
  }
  // Ctrl with Alt is AltGr, a character on the layouts that have one (0044).
  if (at.os !== 'windows' || at.shell !== 'bash' || e.altKey || e.metaKey) return '';
  if (at.prompt === undefined && at.appCursor) return '';
  if (e.ctrlKey) return { ArrowLeft: '\x1bb', ArrowRight: '\x1bf', Backspace: '\x17', Delete: '\x1bd' }[e.key] || '';
  return { Home: '\x01', End: '\x05' }[e.key] || '';
}

/* Whether bash is still at its prompt after `d` is typed: Enter hands the line
   to a command, which reads the keys itself until the next prompt's OSC says
   bash has them back. A bracketed paste keeps its newlines in the line. */
function promptAfter(prompt, d) {
  if (prompt !== true || d.startsWith('\x1b[200~')) return prompt;
  return /[\r\n]/.test(d) ? false : prompt;
}

/* xterm.js's colours from the page's variables, `read` giving the value of
   one by its name. Every theme reaches the terminal this way, all sixteen
   ANSI colours included (0161). The selection is the theme's own, translucent,
   so the text under it keeps its colour. */
function termTheme(read) {
  const ansi = (n) => read('--ansi-' + n);
  return {
    background: read('--bg'), foreground: read('--fg'), cursor: read('--accent'), cursorAccent: read('--bg'),
    selectionBackground: read('--select'), selectionInactiveBackground: read('--select'),
    black: ansi('k'), red: ansi('r'), green: ansi('g'), yellow: ansi('y'),
    blue: ansi('b'), magenta: ansi('m'), cyan: ansi('c'), white: ansi('w'),
    brightBlack: ansi('k-hi'), brightRed: ansi('r-hi'), brightGreen: ansi('g-hi'), brightYellow: ansi('y-hi'),
    brightBlue: ansi('b-hi'), brightMagenta: ansi('m-hi'), brightCyan: ansi('c-hi'), brightWhite: ansi('w-hi'),
  };
}

function cssVar(name) {
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
}

/* What the chip beside a command typed for you says, and where it came from:
   the page that typed it, as the person saw it. `run` is for the one command
   whose Enter the app presses (0157). */
function typedChipText(from, run) {
  if (run) return from ? `run from ${from}` : 'run for you';
  return (from ? `typed from ${from}` : 'typed for you') + ' · Enter is yours';
}

/* Whether the shell has echoed `cmd` since the line read `before` up to the
   cursor: longer by its length, and ending in it. Compared on the line and not
   looked for in it, so a command typed twice is seen twice. */
function echoed(before, now, cmd) {
  return now.length >= before.length + cmd.length && now.endsWith(cmd);
}

/* Whether Enter is pressed for a command the page typed with `run`: only on a
   line nobody has touched since (`keysBefore` and `keysNow` count the person's
   keys) and in the shell it was typed into (`live`). */
function enterAfterEcho(run, keysBefore, keysNow, live) {
  return !!run && live && keysBefore === keysNow;
}

/* Whether `d`, which xterm.js hands to onData, is a key or a paste and not its
   own answer to the shell: a device or cursor report, a focus report, or a
   reply to a colour query. Only the first takes the chip away. */
function typedByPerson(d) {
  return !/^\x1b(?:\[[?>]?[\d;]*[cnRIO]|[P\]])/.test(d);
}

/* The OSC number pty.rs has bash print its VIRTUAL_ENV under. */
const VENV_OSC = 6973;

function initTerm() {
  if (S.term) return;
  S.term = new Terminal({
    fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace',
    // xterm.js multiplies the font's own cell height (15px at 12.5px on macOS) by lineHeight: 19 / 15 is the design's 19px rows.
    fontSize: 12.5, lineHeight: 19 / 15, cursorBlink: true, scrollback: 5000,
    theme: termTheme(cssVar),
    // registerDecoration, which holds the chip of a command typed for you, is a proposed API.
    allowProposedApi: true,
  });
  S.fit = new FitAddon.FitAddon();
  S.term.loadAddon(S.fit);
  S.term.open($('#term'));
  S.fit.fit();
  // bash says which venv it has before each prompt (0069). Any program can
  // print the same sequence, which is why it only ever changes words on screen.
  S.term.parser.registerOscHandler(VENV_OSC, (data) => {
    // Sent before each of bash's prompts, so bash reads its line again (0073).
    S.termPrompt = true;
    // The next prompt: whatever was typed for the person has been dealt with.
    dropTypedChip();
    if (data.length <= 4096 && !/[\x00-\x1f]/.test(data)) heardVenv(data);
    return true;
  });
  connectTerm();
  S.term.onData((d) => {
    if (typedByPerson(d)) { S.termKeys++; dropTypedChip(); }
    S.termPrompt = promptAfter(S.termPrompt, d);
    if (S.ws && S.ws.readyState === 1) S.ws.send(JSON.stringify({ t: 'i', d }));
  });
  S.term.attachCustomKeyEventHandler((e) => {
    const act = termClipboard(e, IS_MAC, S.term.hasSelection());
    // A paste is the browser's to do: refused by xterm.js, the key fires a
    // paste event on its textarea, which it reads as typing, bracketed paste
    // included. Reading the clipboard from here would ask for a permission.
    if (act === 'paste') return false;
    if (act === 'copy') {
      e.preventDefault();
      copyTermSelection();
      return false;
    }
    const sent = termLineKey(e, {
      os: KEYS_OS, shell: S.shellName, prompt: S.termPrompt, screen: S.term.buffer.active.type,
      appCursor: S.term.modes.applicationCursorKeysMode,
    });
    if (sent) {
      e.preventDefault();
      // Fires onData, which sends it, and not onKey: no key of these is Enter,
      // the one onKey listens for.
      S.term.input(sent);
      return false;
    }
    return true;
  });
  S.term.onKey(({ domEvent }) => {
    if (domEvent.key === 'Enter' && (!S.ws || S.ws.readyState > 1)) { S.term.reset(); connectTerm(); }
  });
  new ResizeObserver(() => {
    if ($('#dock-terminal').classList.contains('hidden')) return;
    try { S.fit.fit(); } catch {}
    if (S.ws && S.ws.readyState === 1) S.ws.send(JSON.stringify({ t: 'r', cols: S.term.cols, rows: S.term.rows }));
  }).observe($('#dock-terminal'));
}

/* Without a toast, as in any terminal. The selection goes, so that the next
   Ctrl+C interrupts. */
function copyTermSelection() {
  const text = S.term.getSelection();
  S.term.clearSelection();
  if (!text) return;
  if (!navigator.clipboard) return toast('clipboard unavailable', 'err');
  navigator.clipboard.writeText(text).catch(() => toast('clipboard unavailable', 'err'));
}

/* The text from buffer row `first` to the cursor, the rows between included,
   whether or not the shell marked them as one wrapped line. */
function termLineToCursor(first) {
  const buf = S.term.buffer.active;
  const last = buf.baseY + buf.cursorY;
  let text = '';
  for (let y = first; y <= last; y++) {
    const line = buf.getLine(y);
    if (line) text += y === last ? line.translateToString(false, 0, buf.cursorX) : line.translateToString(false);
  }
  return text;
}

/* Waits for the shell to echo `cmd`, which comes back through the socket and
   the parser, a moment after it was sent; `done` hears whether it did. A shell
   that does not echo it (a program reading the keys itself) gives up after
   the time a slow link takes. */
function awaitEcho(first, before, cmd, done) {
  const from = Date.now();
  const look = () => {
    if (S.term.buffer.active.type === 'normal' && echoed(before, termLineToCursor(first), cmd)) return done(true);
    if (Date.now() - from > 800) return done(false);
    setTimeout(look, 30);
  };
  look();
}

/* The chip beside a command typed for you, at the end of its line. One at a
   time: a second command replaces it. It sits on a marker, which the terminal
   moves with the line as output scrolls it, and which goes with the line when
   it leaves the scrollback. False when it could not be made. */
function showTypedChip(label) {
  dropTypedChip();
  const marker = S.term.registerMarker(0);
  if (!marker) return false;
  const deco = S.term.registerDecoration({ marker, x: S.term.buffer.active.cursorX, width: 1, layer: 'top' });
  if (!deco) { marker.dispose(); return false; }
  // The element is made and moved by xterm.js, at every render.
  deco.onRender((el) => {
    if (el.firstChild) return;
    el.append(Object.assign(document.createElement('span'), { className: 'termtyped', textContent: label }));
  });
  S.typedChip = { deco, marker };
  return true;
}

/* Gone at the next key, the next prompt, Clear and Restart. */
function dropTypedChip() {
  const held = S.typedChip;
  if (!held) return;
  S.typedChip = null;
  held.deco.dispose();
  held.marker.dispose();
}

/* The tab's tools in the dock's row: the venv the terminal runs dbt with, and
   the shell with the folder it starts in. */
function paintTermTools() {
  const status = venvStatus(S.venv || {}, S.termVenv);
  const chip = $('#term-venv');
  chip.textContent = termVenvText(status);
  chip.dataset.state = status.state;
  chip.title = status.title;
  const project = (S.meta && S.meta.project) || '';
  const shell = $('#term-shell');
  shell.textContent = project ? `${S.shellName} · ${project}` : S.shellName;
  shell.classList.toggle('hidden', !S.shellName);
}

function clearTerm() {
  dropTypedChip();
  S.term.clear();
  S.term.focus();
}

/* A new shell in the same terminal. Closing the socket ends the old shell
   (the server kills it when its socket goes), so there is nothing to wait for.
   S.ws is the new socket before the old one's close lands, which is what
   tells its onclose to say nothing of the shell that was left. */
function restartShell() {
  dropTypedChip();
  if (S.ws) S.ws.close();
  S.term.reset();
  // No shell yet: what the new one will say at its first prompt.
  S.termVenv = undefined;
  S.termPrompt = undefined;
  connectTerm();
  paintVenv();
  S.term.focus();
}

function connectTerm() {
  const proto = location.protocol === 'https:' ? 'wss' : 'ws';
  // A browser cannot set a header on a socket, so the key rides in its address (0122).
  const key = launchKey ? '&key=' + encodeURIComponent(launchKey) : '';
  S.ws = new WebSocket(`${proto}://${location.host}/ws/pty?cols=${S.term.cols}&rows=${S.term.rows}${key}`);
  S.ws.binaryType = 'arraybuffer';
  S.ws.onmessage = (e) => {
    if (typeof e.data === 'string') S.term.write(e.data);
    else S.term.write(new Uint8Array(e.data));
  };
  const ws = S.ws;
  ws.onclose = () => {
    // A socket already replaced, closing late, says nothing of the shell now.
    if (S.ws !== ws) return;
    S.term.write(S.keyless
      ? '\r\n\x1b[90m[no shell: this tab has no key for this server, see the bar at the top]\x1b[0m\r\n'
      : '\r\n\x1b[90m[disconnected - press Enter to start a new shell]\x1b[0m\r\n');
    // No shell any more: back to what the next one would be handed.
    S.termVenv = undefined;
    S.termPrompt = undefined;
    paintVenv();
  };
}

// ---------------------------------------------------------------- palette --
let palIndex = 0, palHits = [];
/* The answer on screen, and which of its groups showed all their rows. */
let palAnswer = null, palGroupsOpen = new Set();
/* Bumped each time the box opens or closes, so an Enter still waiting for its
   answer acts only in the box it was pressed in. */
let palOpened = 0;
/* Set by an arrow key, cleared when rows are drawn or a key is typed: the row
   it moved to was picked from what is shown, not from a list still coming. */
let palMoved = false;
function openPalette() {
  palOpened++;
  closeCrumbMenu();
  $('#palette').classList.remove('hidden');
  const input = $('#palette-input');
  input.value = ''; input.focus();
  runPalette('');
}
function closePalette() { palOpened++; $('#palette').classList.add('hidden'); }

/* Answers shown in the order their queries were asked, whatever order they come
   back in: typing outruns the server, and an answer to fewer letters, or the
   empty box's own listing, can come back after the one to what is typed.
   `settled` waits for the last query asked, so Enter pressed right after a key
   picks from what that key lists rather than from the rows still shown. */
function lastAsked(fetch, show) {
  let asked = 0, last = Promise.resolve();
  return {
    ask(q) {
      const mine = ++asked;
      last = fetch(q).then((answer) => { if (mine === asked) show(answer, q); });
      return last;
    },
    async settled() {
      let seen;
      do { seen = last; await seen; } while (seen !== last);
    },
  };
}

/* Nodes first, then macros, then the files that are not already represented by
   one: a model would otherwise appear twice, once as a node and once as its own
   .sql, and so would a macro in the file named after it, a generic test's
   `test_` aside. A file named otherwise stays when a macro in it matched, as it
   holds more than that macro. */
function mergeHits(nodes, macros, paths) {
  const taken = new Set();
  for (const n of nodes) {
    if (n.file) taken.add(n.file);
  }
  for (const m of macros) {
    const stem = base(m.file).replace(/\.[^.]*$/, '');
    if (m.name === stem || m.name === 'test_' + stem) taken.add(m.file);
  }
  return [
    ...nodes.map((n) => ({ kind: 'node', node: n, label: n.name, sub: n.file })),
    ...macros.map((m) => ({ kind: 'macro', macro: m, label: m.call, sub: m.file })),
    ...paths.filter((p) => !taken.has(p)).map((p) => ({ kind: 'file', path: p, label: base(p), sub: p })),
  ];
}

/* Five rows a group and a server that answers 40 at most (0154): each request
   asks for one more than it shows, so a group that came back with 41 is known
   to hold more than the box can say. */
const PALETTE_ROWS = 5, PALETTE_CAP = 40;

/* What the node group holds, said in its title: "Models and seeds", "Sources".
   The order is the one the canvas's legend uses. */
function nodeGroupTitle(kinds) {
  const names = ['model', 'source', 'seed', 'snapshot', 'exposure'].filter((k) => kinds.includes(k)).map((k) => k + 's');
  if (!names.length) return 'Nodes';
  const text = names.length === 1 ? names[0] : names.slice(0, -1).join(', ') + ' and ' + names[names.length - 1];
  return text[0].toUpperCase() + text.slice(1);
}

/* The palette's rows by group, in the order the box draws them. A group shows
   its first five and a row that shows the rest; `opened` holds the groups
   whose rest was asked for. The rows are the hits themselves, plus `more`,
   `grep` (the one that hands the letters to the Search tab) and `note` (a line
   that cannot be picked). `count` is said as the header says it: "40+" for a
   group the server cut, never a number it does not know. */
function paletteGroups(hits, q, capped, opened) {
  const word = q.trim();
  const groups = [];
  const add = (key, title, list, cut) => {
    if (!list.length) return;
    let rows = list;
    const all = opened.has(key) || list.length <= PALETTE_ROWS;
    if (!all) {
      const rest = list.length - PALETTE_ROWS;
      rows = list.slice(0, PALETTE_ROWS).concat({
        kind: 'more', group: key, label: `${cut ? rest + '+' : '+' + rest} more ${title.toLowerCase()}`,
      });
    } else if (cut) {
      // Said for any count: a file hit already shown as a node is dropped, so
      // the rows left can be fewer than the 40 the server was asked for.
      rows = list.concat({ kind: 'note', label: `The search stops at ${PALETTE_CAP} a group: type more letters for the rest.` });
    }
    groups.push({ key, title, count: list.length + (cut ? '+' : ''), rows });
  };
  const nodes = hits.filter((h) => h.kind === 'node');
  add('nodes', nodeGroupTitle(nodes.map((h) => h.node.kind)), nodes, !!capped.nodes);
  if (word) add('macros', 'Macros', hits.filter((h) => h.kind === 'macro'), !!capped.macros);
  add('files', 'Files', hits.filter((h) => h.kind === 'file'), !!capped.files);
  // The Search tab's own minimum, so the hand-over never lands on its refusal.
  if (word.length >= 3) groups.push({ key: 'grep', title: 'Inside the files', count: '', rows: [{ kind: 'grep', q: word }] });
  return groups;
}

/* The foot's count: the hits of the three groups, not the rows that open
   something else. A cut group makes it a floor, "41+ results". */
function paletteCount(hits, capped) {
  const n = hits.length;
  const more = !!(capped.nodes || capped.macros || capped.files);
  return `${n}${more ? '+' : ''} ${n === 1 && !more ? 'result' : 'results'}`;
}

/* Where the letters typed are marked: in the name, or, for a hit the server
   found by its path alone, in the path. Each is [before, match, after]. */
function paletteMarks(name, path, q) {
  const word = q.trim();
  const inName = splitMatch(name, word);
  if (inName[1] || !path) return { name: inName, path: [path || '', '', ''] };
  return { name: inName, path: splitMatch(path, word) };
}

/* One box for everything: dbt nodes from the manifest, the macros by name, and
   every file in the project. A generic test definition or a dotfile is not a
   node, and used to be unfindable. Macros wait for a query: the empty box lists
   nodes and files, as before. Each request asks for one more than the box
   keeps, which is how it knows a group was cut. */
async function fetchPalette(q) {
  const ask = PALETTE_CAP + 1;
  const [nodes, macros, paths] = await Promise.all([
    api.get(`/api/search?q=${encodeURIComponent(q)}&kind=model,source,seed,snapshot,exposure&limit=${ask}`).catch(() => []),
    q.trim() ? api.get(`/api/macros/search?q=${encodeURIComponent(q)}&limit=${ask}`).catch(() => []) : [],
    api.get(`/api/files?q=${encodeURIComponent(q)}&limit=${ask}`).catch(() => []),
  ]);
  const capped = { nodes: nodes.length > PALETTE_CAP, macros: macros.length > PALETTE_CAP, files: paths.length > PALETTE_CAP };
  return {
    hits: mergeHits(nodes.slice(0, PALETTE_CAP), macros.slice(0, PALETTE_CAP), paths.slice(0, PALETTE_CAP)),
    capped,
  };
}

const palAnswers = lastAsked(fetchPalette, showPalette);
function runPalette(q) { palMoved = false; return palAnswers.ask(q); }

/* Enter right after a key picks from what that key lists, in the box it was
   pressed in. A row the arrows moved to is opened at once. */
async function enterPalette() {
  if (palMoved) return choosePalette();
  const opened = palOpened;
  await palAnswers.settled();
  if (opened === palOpened) choosePalette();
}

const GREP_GLYPH = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2 3.5h8M2 7h5M2 10.5h4"/>' +
  '<circle cx="11" cy="10" r="2.75"/><path d="M13 12l1.75 1.75"/></svg>';

/* Text with the letters typed in a mark, built from text nodes: a name or a
   path is data, never markup. */
function markedText(host, [before, match, after]) {
  host.append(before);
  if (match) host.append(jel('mark', '', match));
  host.append(after);
}

/* One pickable row. A more row has an empty icon box, so its words line up
   with the rows above it. */
function paletteRow(h, i, q) {
  const row = jel('div', `pal-row t-${h.kind}` + (h.kind === 'node' && h.node.disabled ? ' off' : ''));
  row.id = 'pal-row-' + i;
  row.setAttribute('role', 'option');
  const icon = jel('span', 'pal-ic');
  const name = jel('span', 'pal-nm');
  const use = jel('span', 'pal-use');
  const path = jel('span', 'pal-path');
  if (h.kind === 'grep') {
    icon.innerHTML = GREP_GLYPH;
    name.textContent = `Search “${h.q}” in every file`;
    path.textContent = 'Search tab';
  } else if (h.kind === 'more') {
    name.textContent = h.label;
  } else {
    const where = h.kind === 'node' ? h.node.file : h.kind === 'file' ? h.path.slice(0, Math.max(0, h.path.lastIndexOf('/'))) : h.macro.file;
    const marks = paletteMarks(h.label, where, q);
    icon.append(h.kind === 'node' ? dot(h.node) : h.kind === 'macro' ? macroIcon() : fileIcon(h.path, fileMark(h.path)));
    markedText(name, marks.name);
    markedText(path, marks.path);
    if (h.kind === 'node') use.textContent = Lineage.matLabel(h.node);
    // Who calls a macro, the row's count, the card and the report saying more.
    if (h.kind === 'macro' && h.macro.used) use.textContent = macroUseText(h.macro.used).short;
  }
  row.append(icon, name, use, path);
  row.addEventListener('click', () => choosePalette(i));
  // Not mouseenter: a list scrolling under a still pointer must not take the
  // selection away from the arrows.
  row.addEventListener('mousemove', () => { if (palIndex !== i) selectPalette(i, false); });
  return row;
}

/* The answer on screen, from `palAnswer` and the groups asked for so far. */
function drawPalette() {
  const { answer, q } = palAnswer;
  const groups = paletteGroups(answer.hits, q, answer.capped, palGroupsOpen);
  palHits = groups.flatMap((g) => g.rows).filter((r) => r.kind !== 'note');
  palIndex = Math.min(palIndex, Math.max(0, palHits.length - 1));
  $('#palette-count').textContent = paletteCount(answer.hits, answer.capped);

  const box = $('#palette-results');
  const kept = box.scrollTop;
  box.textContent = '';
  if (!groups.length) {
    box.append(jel('div', 'pal-empty', q.trim() ? `Nothing matches “${q.trim()}”.`
      : 'Type to search models, sources, macros and every file in the project.'));
    $('#palette-input').removeAttribute('aria-activedescendant');
    return;
  }
  let i = 0;
  for (const g of groups) {
    const head = jel('div', 'pal-head', g.title);
    head.setAttribute('role', 'presentation');
    if (g.count) head.append(jel('span', 'n', g.count));
    box.append(head);
    for (const r of g.rows) {
      if (r.kind === 'note') { box.append(jel('div', 'pal-note', r.label)); continue; }
      box.append(paletteRow(r, i, q));
      i++;
    }
  }
  box.scrollTop = kept;
  markPalette();
  paletteFileMarks();
}

/* A file row is drawn before its folder's marks are known when no folder of it
   was listed: ask, and draw the icons that gained one in place, so the
   selection and the scroll stay. Dropped if another answer or a new box came. */
function paletteFileMarks() {
  const mine = palAnswer, opened = palOpened;
  askMarks(palHits.filter((h) => h.kind === 'file').map((h) => h.path)).then((gained) => {
    if (!gained || palAnswer !== mine || opened !== palOpened) return;
    const rows = $$('#palette-results .pal-row');
    palHits.forEach((h, i) => {
      const mark = h.kind === 'file' && fileMark(h.path);
      if (mark && rows[i]) rows[i].querySelector('.pal-ic').replaceChildren(fileIcon(h.path, mark));
    });
  });
}

/* The selected row lit and announced. */
function markPalette() {
  const rows = $$('#palette-results .pal-row');
  rows.forEach((r, i) => {
    r.classList.toggle('on', i === palIndex);
    r.setAttribute('aria-selected', String(i === palIndex));
  });
  if (rows[palIndex]) $('#palette-input').setAttribute('aria-activedescendant', rows[palIndex].id);
}

function showPalette(answer, q) {
  palAnswer = { answer, q };
  // A group opened belongs to the answer it was opened in: a new key asks again.
  palGroupsOpen = new Set();
  palIndex = 0;
  palMoved = false;
  // Row 0 is what Enter opens: it must be in view. Only an expand keeps the scroll.
  $('#palette-results').scrollTop = 0;
  drawPalette();
}

function movePalette(delta) {
  const rows = $$('#palette-results .pal-row');
  if (!rows.length) return;
  // Only the arrows say the row was picked from what is shown: a pointer
  // moving over rows of an answer about to be replaced says nothing.
  palMoved = true;
  selectPalette((palIndex + delta + rows.length) % rows.length);
}

/* `scroll` is off for the pointer, which selects what it is already over. */
function selectPalette(i, scroll = true) {
  const rows = $$('#palette-results .pal-row');
  if (!rows[i]) return;
  if (rows[palIndex]) {
    rows[palIndex].classList.remove('on');
    rows[palIndex].setAttribute('aria-selected', 'false');
  }
  palIndex = i;
  rows[i].classList.add('on');
  rows[i].setAttribute('aria-selected', 'true');
  $('#palette-input').setAttribute('aria-activedescendant', rows[i].id);
  if (scroll) rows[i].scrollIntoView({ block: 'nearest' });
}

function choosePalette(i) {
  const h = palHits[i ?? palIndex];
  if (!h) return;
  if (h.kind === 'more') {
    // Shows the rest where it is: the box stays open, the focus in the input,
    // and the selection stays on the same index.
    palGroupsOpen.add(h.group);
    // A click selects its row, as a pointer that moved would have.
    if (i !== undefined) palIndex = i;
    drawPalette();
    $('#palette-input').focus();
    $$('#palette-results .pal-row')[palIndex]?.scrollIntoView({ block: 'nearest' });
    return;
  }
  closePalette();
  // A node without a file opens nothing, so activate() would not close it.
  closePanel();
  if (h.kind === 'grep') {
    showSide('search');
    $('#grep-input').value = h.q;
    runGrep();
    return;
  }
  // It records its own place to come back to.
  if (h.kind === 'macro') { openMacro(h.macro); return; }
  pushJump();
  if (h.kind === 'file') {
    openFile(h.path, { preview: true });
    revealInTree(h.path);
    return;
  }
  focusNode(h.node.id);
  if (h.node.file) { openFile(h.node.file, { focusLineage: false, preview: true }); revealInTree(h.node.file); }
}

// ------------------------------------------------------------------ tabs --
/* Search across file contents, which the path index cannot answer. The server
   finds the lines; the match inside one is found here, because the browser knows
   the query and a byte offset from Rust would not survive into a UTF-16 string. */
function splitMatch(text, query) {
  if (!query) return [text, '', ''];
  // Matched on the text itself: lowercasing it first can change its length ("İ"
  // lowercases to two characters), which would slide the cut.
  const m = new RegExp(query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i').exec(text);
  if (!m) return [text, '', ''];
  return [text.slice(0, m.index), m[0], text.slice(m.index + m[0].length)];
}

/* What the status line says about a result. Pure, so the wording is checkable. */
function grepSummary(result, query) {
  if (!query) return '';
  if (query.length < 3) return 'three letters or more';
  if (!result) return 'searching…';
  const files = result.files.length;
  if (!files) return `no match for “${query}”`;
  const hits = result.total;
  const bits = [`${hits} match${hits > 1 ? 'es' : ''} in ${files} file${files > 1 ? 's' : ''}`];
  if (result.capped) bits.push('showing the first found');
  if (result.skipped) bits.push(`${result.skipped} file${result.skipped > 1 ? 's' : ''} skipped`);
  return bits.join(' · ');
}

/* A line as the list shows it, [before, match, after]: indentation dropped,
   and a match that ends past column 24 brought back into the row by cutting the
   front off at a word edge, 2 to 16 characters before it, or 8 before it when
   there is none. A narrow sidebar would otherwise hide the very letters that
   were searched for, behind an ellipsis at the end of the row. */
function grepLine(text, query) {
  const trimmed = text.replace(/^\s+/, '');
  const [before, hit, after] = splitMatch(trimmed, query);
  const at = before.length;
  if (!hit || at + hit.length <= 24) return [before, hit, after];
  let from = Math.max(0, at - 8);
  for (let j = at - 2; j >= Math.max(0, at - 16); j -= 1) {
    if (' .(,'.includes(trimmed.charAt(j))) { from = j + 1; break; }
  }
  // A cut between the halves of an emoji would show a broken glyph.
  if (from && trimmed.charCodeAt(from) >= 0xDC00 && trimmed.charCodeAt(from) <= 0xDFFF) from -= 1;
  if (!from) return [before, hit, after];
  return ['…' + trimmed.slice(from, at), hit, after];
}

let grepTimer = null;
let grepRun = 0;
/* The files folded in the list, kept from one query to the next and emptied
   with the box; the hit opened last, as "path:line"; and the result on screen,
   so a fold redraws without asking the server again. */
const grepFolded = new Set();
let grepCur = '';
let grepLast = { result: null, query: '' };

const GREP_CHEVRON = '<svg class="chev" viewBox="0 0 16 16" aria-hidden="true"><path d="M6 4l4 4-4 4"/></svg>';

function paintGrep(result, query) {
  grepLast = { result, query };
  $('#grep-status').textContent = grepSummary(result, query);
  const files = result ? result.files : [];
  $('#grep-clear').classList.toggle('hidden', !$('#grep-input').value);
  const fold = $('#grep-fold');
  fold.classList.toggle('hidden', !files.length);
  const label = files.every((f) => grepFolded.has(f.path)) ? 'Unfold every file' : 'Fold every file';
  fold.title = label;
  fold.setAttribute('aria-label', label);
  const host = $('#grep-results');
  host.textContent = '';
  if (!result) return;
  if (!files.length) {
    host.append(jel('div', 'gempty', `Nothing in the project holds “${query}”.`));
    return;
  }
  for (const f of files) {
    const open = !grepFolded.has(f.path);
    const head = jel('button', 'gfile');
    head.type = 'button';
    head.dataset.path = f.path;
    head.title = f.path;
    head.setAttribute('aria-expanded', String(open));
    head.insertAdjacentHTML('beforeend', GREP_CHEVRON);
    head.firstElementChild.classList.toggle('open', open);
    head.append(fileIcon(f.path, fileMark(f.path)), jel('span', 'nm', base(f.path)), jel('span', 'opn', '\u00b7 open'),
      jel('span', 'dir', f.path.includes('/') ? dirOf(f.path) : ''), jel('span', 'cnt', String(f.hits.length + (f.more || 0))));
    head.addEventListener('click', () => toggleGrepFile(f.path));
    host.appendChild(head);
    if (!open) continue;
    for (const h of f.hits) {
      const row = jel('button', 'ghit');
      row.type = 'button';
      row.dataset.path = f.path;
      row.dataset.line = h.line;
      row.setAttribute('aria-current', String(grepCur === `${f.path}:${h.line}`));
      row.append(jel('span', 'ln', String(h.line)));
      const body = jel('span', 'tx');
      markedText(body, grepLine(h.text, query));
      row.appendChild(body);
      row.addEventListener('click', () => {
        grepCur = `${f.path}:${h.line}`;
        for (const r of host.querySelectorAll('.ghit')) r.setAttribute('aria-current', String(r === row));
        openAt(f.path, h.line);
      });
      host.appendChild(row);
    }
    // The server stops at 20 lines a file, so these are not on the page to show.
    if (f.more) host.append(jel('div', 'gmore', `+${f.more} more in this file`));
  }
  markGrepOpen();
  // A model's file in a folder the tree never opened is drawn grey until its
  // mark is asked for: the icons that gained one are redrawn in place, if this
  // is still the answer on screen.
  const shown = grepLast;
  askMarks(files.map((f) => f.path)).then((gained) => {
    if (!gained || grepLast !== shown) return;
    for (const head of $$('#grep-results .gfile')) {
      const mark = fileMark(head.dataset.path);
      if (mark) head.querySelector('.ficon').replaceWith(fileIcon(head.dataset.path, mark));
    }
  });
}

/* The header of the file open in the editor says so. Called when the active tab
   changes, which can be while the Search tab is hidden. */
function markGrepOpen() {
  // As the tree marks it: a diff tab stands for the file it compares.
  const open = projectPath(S.active);
  for (const head of $$('#grep-results .gfile')) head.classList.toggle('cur', !!open && head.dataset.path === open);
}

/* Folding redraws from the result on screen. The scroll and the focus stay where
   they were, so the header pressed is still the one under the finger. */
function redrawGrep(focusPath) {
  const host = $('#grep-results');
  const top = host.scrollTop;
  paintGrep(grepLast.result, grepLast.query);
  host.scrollTop = top;
  const head = focusPath && [...host.querySelectorAll('.gfile')].find((h) => h.dataset.path === focusPath);
  if (head) focusGrepRow(head);
}

/* Headers are siblings in one scroll box, so one scrolled past the top stays
   stuck under the next, and focusing it would leave it hidden behind that one.
   Where it sits unstuck is the height of the rows before it: when that is above
   the scroll, the list goes back up to it first. */
function focusGrepRow(row) {
  const host = $('#grep-results');
  let at = 0;
  if (row.classList.contains('gfile')) {
    for (let r = row.previousElementSibling; r; r = r.previousElementSibling) at += r.offsetHeight;
  }
  if (at < host.scrollTop && row.classList.contains('gfile')) {
    host.scrollTop = at;
    row.focus({ preventScroll: true });
  } else row.focus();
}

function toggleGrepFile(path, open = grepFolded.has(path)) {
  if (open) grepFolded.delete(path); else grepFolded.add(path);
  redrawGrep(path);
}

function foldAllGrep() {
  const files = grepLast.result ? grepLast.result.files : [];
  if (files.every((f) => grepFolded.has(f.path))) grepFolded.clear();
  else for (const f of files) grepFolded.add(f.path);
  redrawGrep();
}

/* The list's keys: the arrows move over the visible rows, headers and hits, and
   the box is one step above the first. Left and right fold a header and
   unfold it; left on a hit goes to its header. Enter and Space are the buttons'
   own. */
function grepKey(e) {
  const rows = $$('#grep-results .gfile, #grep-results .ghit');
  const at = rows.indexOf(document.activeElement);
  if (at < 0) return;
  const row = rows[at];
  const head = row.classList.contains('gfile');
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    e.preventDefault();
    if (e.key === 'ArrowUp' && !at) $('#grep-input').focus();
    else focusGrepRow(rows[Math.min(rows.length - 1, Math.max(0, at + (e.key === 'ArrowDown' ? 1 : -1)))]);
  } else if (e.key === 'Escape') {
    // Handled here only, as the app's menus do: nothing behind the list acts on it.
    e.preventDefault();
    e.stopPropagation();
    $('#grep-input').focus();
  } else if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
    e.preventDefault();
    const folded = row.getAttribute('aria-expanded') === 'false';
    if (head && e.key === 'ArrowLeft' && !folded) toggleGrepFile(row.dataset.path, false);
    else if (head && e.key === 'ArrowRight' && folded) toggleGrepFile(row.dataset.path, true);
    else if (!head && e.key === 'ArrowLeft') {
      const owner = rows.slice(0, at).reverse().find((r) => r.classList.contains('gfile'));
      if (owner) focusGrepRow(owner);
    }
  }
}

function runGrep() {
  const query = $('#grep-input').value.trim();
  clearTimeout(grepTimer);
  // An answer still on its way for what was typed before must not land on
  // a box that has changed since, a cleared one above all.
  const run = ++grepRun;
  if (!query) grepFolded.clear();
  if (query.length < 3) {
    paintGrep(null, query);
    return;
  }
  paintGrep(null, query);
  // A full scan of a large project is well under a second, so a short pause is
  // enough to keep a burst of typing down to one request.
  grepTimer = setTimeout(() => {
    api.get('/api/grep?q=' + encodeURIComponent(query))
      .then((result) => { if (run === grepRun) paintGrep(result, query); })
      .catch((e) => { if (run === grepRun) $('#grep-status').textContent = 'search failed: ' + e.message; });
  }, 250);
}

/* Opens a file and puts the cursor on one of its lines, which is what a search
   result is for. Preview, like a single click in the explorer: browsing results
   should not leave a dozen pinned tabs behind. */
async function openAt(path, line) {
  await openFile(path, { focusLineage: false, preview: true });
  if (!S.cm || S.active !== path) return;
  gotoPos(line - 1, 0);
}

function wireTabs() {
  $$('[data-side]').forEach((b) => b.addEventListener('click', () => showSide(b.dataset.side)));
  $$('[data-dock]').forEach((b) => b.addEventListener('click', () => showDock(b.dataset.dock)));
  // Each tab's name and description, read once: foldDockTabs() writes the
  // tooltip from them.
  $$('#dock > .tabs .tab').forEach((t) => {
    t.dataset.name = t.querySelector('span').textContent;
    t.dataset.about = t.title;
  });
  // The row's width moves with the window, the sidebar and the dock. Only the
  // row is observed for size: the fold never changes it, so the observer
  // never loops on its own change.
  // The witch is placed again after the fold, which moves the tabs she stands over.
  const refold = () => { foldDockTabs(); placeWitch(false); };
  new ResizeObserver(refold).observe($('#dock > .tabs'));
  // What the tools hold moves too, the column chip, a mode, the indirect button,
  // and it changes while another tab is open, when the tools are hidden and a
  // hidden element reports no resize. So it is watched as markup. A change of
  // the tools' own class is left out: showDock hides and shows them, which
  // moves nothing the fold measures, and foldDockTabs shows them for its
  // measure, which would call it again.
  const tools = $('#lineage-tools');
  const watch = new MutationObserver((records) => {
    if (records.some((r) => r.target !== tools || r.type !== 'attributes')) refold();
  });
  watch.observe(tools, { subtree: true, childList: true, characterData: true, attributes: true });
  watch.observe($('#history-tab'), { attributes: true, attributeFilter: ['class'] });
  $('#term-clear').addEventListener('click', clearTerm);
  $('#term-restart').addEventListener('click', restartShell);
  wireTopbar();
}

/* Pulled out of wireTabs because a link into the file tree has to bring the
   tree back into view before there is anything to reveal. */
function showSide(which) {
  $$('[data-side]').forEach((x) => x.classList.toggle('active', x.dataset.side === which));
  $('#side-files').classList.toggle('hidden', which !== 'files');
  $('#side-models').classList.toggle('hidden', which !== 'models');
  $('#side-git').classList.toggle('hidden', which !== 'git');
  $('#side-search').classList.toggle('hidden', which !== 'search');
  if (which === 'models' && !$('#model-list').children.length) refreshModels();
  if (which === 'git') refreshGit();
  if (which === 'search') $('#grep-input').focus();
}

/* What the Compiled and Run tabs are, in the dock's row at the right while one
   is open: the tab button's own tooltip, read once into data-about by
   wireTabs, so the two cannot drift (0164). */
function paintArtifactTools(which) {
  const tab = $('#dock > .tabs .tab[data-dock="' + which + '"]');
  const text = (tab && tab.dataset.about) || '';
  const about = $('#artifact-about');
  about.textContent = text;
  about.title = text;
}

/* `look` is off for a tab brought forward by a click in a report that has
   just looked at the job files itself (0063), and for the tour's Jobs step
   and its putting back of the dock, which ask for none (0075). The reports
   are left as they are: a column's lineage brings the canvas forward when
   its answer lands, seconds later with Snowflake, and must not roll up a
   panel opened since. What the user asks for rolls them up itself. */
function showDock(which, { look = true, id = '' } = {}) {
  let loading = null;
  S.dock = which;
  $$('[data-dock]').forEach((x) => x.classList.toggle('active', x.dataset.dock === which));
  // Up in the selection's panel, the canvas is not the dock's to hide.
  if (!panelOpen('select')) $('#dock-lineage').classList.toggle('hidden', which !== 'lineage');
  $('#dock-terminal').classList.toggle('hidden', which !== 'terminal');
  $('#dock-catalog').classList.toggle('hidden', which !== 'catalog');
  $('#dock-compiled').classList.toggle('hidden', which !== 'compiled');
  $('#dock-run').classList.toggle('hidden', which !== 'run');
  $('#dock-history').classList.toggle('hidden', which !== 'history');
  $('#dock-jobs').classList.toggle('hidden', which !== 'jobs');
  // `id` is a model other than the focused one, asked for by a card that
  // points at its SQL (0145); the load is returned so the card can wait for it.
  if (which === 'compiled' || which === 'run') loading = loadArtifact(which, id || S.focus);
  if (which === 'jobs') loading = loadJobs({ look });
  if (which === 'catalog') fillCatalogJobs($('#catalog .cat-jobs'));
  // A column box clicked with the lineage in front asked for its row.
  if (which === 'catalog' && S.node && S.colReveal === S.node.id && S.catTab === 'columns') renderCatalog(S.node);
  // Read when the tab is first opened, never before: that click is what may
  // bring a sign-in tab (0016).
  if (which === 'history' && !S.history) loadHistory();
  $('#lineage-tools').classList.toggle('hidden', which !== 'lineage');
  $('#jobs-tools').classList.toggle('hidden', which !== 'jobs');
  $('#term-tools').classList.toggle('hidden', which !== 'terminal');
  $('#artifact-tools').classList.toggle('hidden', which !== 'compiled' && which !== 'run');
  if (which === 'compiled' || which === 'run') paintArtifactTools(which);
  placeWitch(true);
  if (which === 'terminal') { initTerm(); paintTermTools(); setTimeout(() => { try { S.fit.fit(); } catch {} S.term.focus(); }, 30); }
  if (which === 'lineage') setTimeout(() => Lineage.fit(), 30);
  // The tour waits on it, to point at the tab once it is filled.
  return loading;
}

/* The dock's tabs share their row with the lineage's tools, and the glyphs
   made each tab wider. Once the row cannot hold everything on one line, things
   fold one at a time, cheapest first, each step measured and then kept only if
   the row still broke without it, rather than the tools breaking onto a second
   line the 30px row cannot show: first the depth control's name gives way to
   the bar of its kind (`noname`; it repeats the editor's tab and the focus box,
   and stays whole in the bar's tooltip, the menus and the copy), then the tabs
   not in front keep their glyph alone, named by their tooltip, the one in
   front keeping its name (`folded`), then the front tab folds as well
   (`bare`), and last Export keeps its glyph and chevron alone too (`iconic`;
   Fit has no label), the action that matters least to what is drawn (0166).
   It is measured, never set at a width, because the room moves with the
   sidebar, Query history and the column chip. It is measured with the
   lineage's tools shown and any other tab's hidden (the Jobs tab's two
   buttons, the terminal's chip and two buttons and the Compiled tab's one
   line of text are far fewer or give way with an ellipsis, and a fold they
   caused would move the tabs when it opens), and with the widest tab's name in
   front, whichever is, so that a click on a tab never changes what folds:
   wireTabs() calls it when the row or the tools change, and never on a tab
   change. The tools' own class is the one change of theirs it does not hear,
   which is why the other folds are set there. Only the tools are asked
   whether they broke, since a tab cannot, and a tab taller than the row, under
   a large minimum font, would keep the labels folded at any width. Past every
   fold, the tools still break: docs/state.md has the rest. */
function foldDockTabs() {
  const row = $('#dock > .tabs');
  const tools = $('#lineage-tools');
  const away = tools.classList.contains('hidden');
  const others = [$('#jobs-tools'), $('#term-tools'), $('#artifact-tools')];
  const othersAway = others.map((e) => e.classList.contains('hidden'));
  const was = row.classList.contains('folded');
  row.classList.remove('folded', 'bare', 'measure');
  others.forEach((e) => e.classList.add('hidden'));
  tools.classList.remove('hidden', 'noname', 'iconic');
  const tabs = $$('#dock > .tabs .tab');
  // With every name shown, before anything folds: the tab the others are measured against.
  const widest = tabs.reduce((best, t) => (t.offsetWidth > (best ? best.offsetWidth : 0) ? t : best), null);
  tabs.forEach((t) => t.classList.toggle('widest', t === widest));
  const fit = () => {
    // Without the strip the Halloween theme adds over the tabs, whose room the witch has.
    const h = row.getBoundingClientRect().height - parseFloat(getComputedStyle(row).paddingTop);
    return row.scrollWidth <= row.clientWidth
      && $$('#lineage-tools > *').every((e) => e.getBoundingClientRect().height <= h);
  };
  if (!fit()) {
    tools.classList.add('noname');
    if (!fit()) {
      row.classList.add('folded', 'measure');
      if (!fit()) {
        row.classList.add('bare');
        if (!fit()) tools.classList.add('iconic');
      }
      row.classList.remove('measure');
    }
  }
  const folded = row.classList.contains('folded');
  tools.classList.toggle('hidden', away);
  others.forEach((e, i) => e.classList.toggle('hidden', othersAway[i]));
  if (was === folded) return;
  tabs.forEach((t) => {
    const { name, about } = t.dataset;
    if (folded) t.title = about ? `${name}: ${about}` : name;
    else if (about) t.title = about;
    else t.removeAttribute('title');
  });
}

/* The top bar never breaks onto a second line, and never runs past the
   window (docs/state.md had it do both on a narrow one). Cheapest first:
   the search field shrinks with the window down to 200px (app.css; the
   project's name does not give until then), its placeholder cut with an
   ellipsis; then `nosearch` takes the words away and leaves the glyph and
   the key; then the project's name gives way, cut with an ellipsis down to
   PROJECT_MIN; then the tabs not lit keep their glyph alone, named by their
   tooltip and still read out. Measured, never set at a width, because the
   room moves with the name, the news on the Reports tab and the theme's
   button: it is measured with every tab's name shown, whichever is lit, so
   a click on a tab never changes what folds (0140, 0166). Only the bar's
   own classes change, so the observers below never hear it. */
const PROJECT_MIN = 120;

function foldTopbar() {
  const bar = $('#topbar');
  const name = $('#project');
  bar.classList.remove('nosearch', 'folded');
  // Nothing past the window, and the name either whole or cut no further than PROJECT_MIN.
  const fits = () => bar.scrollWidth <= bar.clientWidth
    && (name.scrollWidth <= name.clientWidth || name.clientWidth >= PROJECT_MIN);
  if (fits()) return;
  bar.classList.add('nosearch');
  if (fits()) return;
  bar.classList.add('folded');
}

function wireTopbar() {
  const bar = $('#topbar');
  const brand = $('#brand');
  new ResizeObserver(foldTopbar).observe(bar);
  new MutationObserver((records) => {
    /* The mark's `working` and `flowing` toggle often and change no size: a
       layout pass for each would be spent for nothing. */
    if (records.some((r) => r.target !== bar && !(r.target === brand && r.type === 'attributes'))) foldTopbar();
  }).observe(bar, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['class', 'hidden'] });
}

/* The theme (0150, 0106): data-theme on <html>, which the variable blocks at
   the top of app.css and every rule of the Halloween theme hang from, so
   exportCanvasCss() and the snapshot, which carry none of it, can never pick
   any up. Kept per machine by /api/look; a failed answer leaves the state as it
   is and says nothing, the theme being a nicety.
   The pure parts run from THEMES to placeWitch, which web/tests/themes.js and
   web/tests/halloween.js slice. */

const THEMES = [
  { id: 'night', name: 'Night', about: 'Deep blue, the default' },
  { id: 'graphite', name: 'Graphite', about: 'Neutral grey, no tint' },
  { id: 'light', name: 'Light', about: 'For daylight and screenshots' },
  { id: 'halloween', name: 'Halloween', about: 'Orange and black, a ghost and a witch' },
];

/* A theme as /api/look said it: one of the four, Night for anything else, as
   for a server that does not say. */
function themeId(v) { return THEMES.some((t) => t.id === v) ? v : 'night'; }

/* The theme on screen: Follow the system shows Light while the system is
   light and Night once it is dark, else the one picked. */
function shownTheme(look, dark) { return look.follow ? (dark ? 'night' : 'light') : themeId(look.theme); }

/* The theme an export is drawn in: the one on screen, Night under Halloween,
   whose art never leaves the page (0106, 0150). */
function exportTheme(shown) { return shown === 'halloween' ? 'night' : themeId(shown); }

const DARK = window.matchMedia ? matchMedia('(prefers-color-scheme: dark)') : null;
function hwOn() { return document.documentElement.dataset.theme === 'halloween'; }
/* The theme on screen, from the state and the system. */
function themeNow() { return shownTheme(S.look, !DARK || DARK.matches); }

/* After dark by the browser's own clock, the user's timezone: 20h to 6h59. */
function isNightHour(h) { return h >= 20 || h < 7; }

/* The style of the lineage boxes, from what /api/look said: one of the three,
   the tombstone for anything else, as for a server that does not say. */
function hwBoxes(v) { return v === 'coffin' || v === 'grimoire' ? v : 'tombstone'; }

/* How long to wait for the next apparition, in ms, from a range in minutes
   and r in [0, 1) (Math.random()). */
function nextApparitionDelay(min, max, r) {
  const t = Math.min(1, Math.max(0, r));
  return Math.round((min + (max - min) * t) * 60 * 1000);
}

/* Which way the witch flies from one place to the next: 1 right, -1 left, 0
   when she has not moved or has nowhere she came from, so she keeps facing the
   way she did. */
function witchFacing(fromX, toX) {
  if (!(fromX >= 0) || !(toX >= 0)) return 0;
  return toX > fromX ? 1 : toX < fromX ? -1 : 0;
}

/* Whether a switch drawn again walks: it has been seen on the other side, and
   the look is on. A switch seen for the first time just stands. */
function switchWalks(prev, now, themed) {
  return !!themed && prev !== undefined && prev !== now;
}

/* Over the open dock tab. Out of the flow (position: absolute), clamped to the
   row, so the fold, which asks whether the row overflows, never sees her.
   `animate` is off for a resize or for the first place she is put. */
function placeWitch(animate) {
  const w = $('#hw-witch');
  if (!w || !hwOn()) return;
  const row = $('#dock > .tabs');
  const tab = row.querySelector('.tab.active');
  if (!tab) return;
  const r = row.getBoundingClientRect();
  const t = tab.getBoundingClientRect();
  if (!r.width || !t.width) return;
  const half = w.offsetWidth / 2;
  const x = Math.round(Math.max(0, Math.min(r.width - w.offsetWidth, t.left - r.left + t.width / 2 - half)));
  const first = S.hw.witchX === undefined;
  const facing = witchFacing(S.hw.witchX, x);
  const fly = animate && !first && facing !== 0;
  // Turned only by a flight: a resize that nudges her a few pixels is no journey.
  if (fly) w.classList.toggle('back', facing < 0);
  w.style.transition = fly ? '' : 'none';
  w.style.transform = `translateX(${x}px)`;
  if (!fly) { void w.offsetWidth; w.style.transition = ''; }
  S.hw.witchX = x;
  clearTimeout(S.hw.flyTimer);
  w.classList.toggle('flying', fly);
  if (fly) S.hw.flyTimer = setTimeout(() => w.classList.remove('flying'), 650);
}

function paintNight() {
  document.documentElement.classList.toggle('hw-night', hwOn() && isNightHour(new Date().getHours()));
}

/* The theme as S.look says it: <html>'s attribute and the box style's class,
   the button, and the timers of the apparitions, which only run while the
   Halloween theme and its apparitions are both on. */
function applyLook() {
  const theme = themeNow();
  const root = document.documentElement;
  const was = root.dataset.theme === 'halloween';
  root.dataset.theme = theme;
  const on = theme === 'halloween';
  // The box style's class only while the theme is on, so that any other costs the page nothing.
  for (const b of ['tombstone', 'coffin', 'grimoire']) root.classList.toggle('hw-boxes-' + b, on && b === hwBoxes(S.look.boxes));
  paintNight();
  // The terminal's colours are the theme's, and xterm.js repaints at once.
  if (S.term) S.term.options.theme = termTheme(cssVar);
  // The boxes' art, drawn by the lineage itself, which keeps it through its own redraws.
  Lineage.setSkin(on ? hwBoxes(S.look.boxes) : null);
  $('#theme-btn').title = 'Theme: ' + THEMES.find((t) => t.id === theme).name;
  if (on !== was) {
    S.hw.witchX = undefined;
    if (on) placeWitch(false);
  }
  // The timers follow what is wanted, so a switch flipped in the settings
  // that changes nothing about them leaves them running.
  const want = on && S.look.apparitions !== false;
  if (want && !S.hw.running) startApparitions();
  else if (!want && S.hw.running) stopApparitions();
}

/* One chain, so two quick choices reach the server in the order they were
   made and the last one is what is kept. */
function saveLook() {
  const body = { theme: themeId(S.look.theme), follow: !!S.look.follow, apparitions: S.look.apparitions !== false, boxes: hwBoxes(S.look.boxes) };
  S.hw.saving = S.hw.saving.then(() => api.send('/api/look', 'POST', body)).then(() => {}, () => {});
}

function loadLook() {
  api.get('/api/look').then((r) => {
    S.look = { theme: themeId(r && r.theme), follow: !!(r && r.follow), apparitions: !r || r.apparitions !== false, boxes: hwBoxes(r && r.boxes) };
    applyLook();
    repaintSettings();
  }).catch(() => {});
}

/* A choice made by a click, in the top bar or in the settings: kept, drawn. */
function setLook(patch) {
  Object.assign(S.look, patch);
  applyLook();
  saveLook();
  repaintSettings();
}

/* A theme picked, from the menu or a card: it is the one kept, and the system
   no longer chooses. */
function pickTheme(id) { setLook({ theme: id, follow: false }); }

function wireLook() {
  $('#theme-btn').addEventListener('click', (e) => openThemeMenu(e.currentTarget));
  // While Follow is on, the page tracks the system as it turns.
  // An open theme menu would keep the tick of the theme that was on screen, so it closes.
  if (DARK) DARK.addEventListener('change', () => { if (S.look.follow) { closePopup(); applyLook(); repaintSettings(); } });
}

/* The theme menu (0150), under its button and held inside the window from the
   right: one row per theme, drawn in its own colours by a swatch that carries
   its data-theme. */
function openThemeMenu(anchor) {
  if (closePopup(anchor)) return;
  const el = (tag, className, textContent = '') => Object.assign(document.createElement(tag), { className, textContent });
  const shown = themeNow();
  const menu = el('div', 'envmenu thememenu');
  menu.setAttribute('role', 'menu');
  menu.setAttribute('aria-label', 'Theme');
  menu.dataset.align = 'right';
  menu.append(el('div', 'menuhead', 'Theme'));
  for (const t of THEMES) {
    const item = el('button', t.id === shown ? 'on' : '');
    item.type = 'button';
    item.setAttribute('role', 'menuitemradio');
    item.setAttribute('aria-checked', String(t.id === shown));
    item.dataset.key = 'theme-' + t.id;
    const sw = el('span', 'tm-sw');
    sw.dataset.theme = t.id;
    sw.setAttribute('aria-hidden', 'true');
    sw.append(el('i', 'v'), el('i', 't'), el('b'));
    item.append(sw, el('span', 'lbl', t.name), strokeIcon('0 0 16 16', 'tm-check', ['M3.5 8.5l3 3 6-7']));
    item.addEventListener('click', () => { closePopup(); anchor.focus(); pickTheme(t.id); });
    menu.append(item);
  }
  anchor.setAttribute('aria-expanded', 'true');
  openPopup(anchor, menu, () => anchor.setAttribute('aria-expanded', 'false'));
}

/* A switch that walks. A section is drawn again whenever what it shows
   changes, which makes a new switch already on its new side, so the knob is
   walked from the side it was last seen on by an animation of its own: the
   markup, aria-checked included, always says the real state, and is the same
   for the probe redrawIfChanged compares with, so a walk is never cut short by
   a redraw. Only the real box is told apart from that probe, which must
   neither walk nor remember. */
function walkSwitch(toggle, key, now, real) {
  if (!real) return;
  const prev = S.hw.sides.get(key);
  S.hw.sides.set(key, now);
  if (!switchWalks(prev, now, hwOn()) || hwReduced()) return;
  const knob = toggle.firstChild;
  // A frame later: an animation on a node not yet in the page starts too early.
  requestAnimationFrame(() => {
    if (!knob.isConnected || !knob.animate) return;
    // The run is the track's width less the zombie's: a narrower track sets its own.
    const there = `translateX(${getComputedStyle(toggle).getPropertyValue('--zrun').trim() || '15px'}) scaleX(-1)`;
    const opts = { duration: 300, easing: 'ease-out' };
    knob.animate([{ transform: now ? 'none' : there }, { transform: now ? there : 'none' }], opts);
    knob.animate([{ top: '-2px' }, { top: '-5px', offset: 0.4 }, { top: '-2px' }], opts);
    // The sprite's poses (stand, then the two strides) stepped through, one per fifth of the walk.
    const stride = ['0px', '-20px', '-40px', '-20px', '-40px', '0px'].map((y) => ({ backgroundPositionY: y, easing: 'steps(1, end)' }));
    knob.animate(stride, opts);
  });
}

/* A switch row of the Theme section, drawn as Snowflake's is, the zombie of
   the Halloween theme walking its knob. `real` tells the box in the page from
   the probe redrawIfChanged compares with; `tag` follows the name. */
function switchRow(key, label, about, on, onClick, real, tag = null) {
  const { row, sc } = buildRow(tag ? [label, tag] : label, about);
  const toggle = jel('button', 'switch');
  toggle.type = 'button';
  toggle.dataset.key = key;
  toggle.setAttribute('role', 'switch');
  toggle.setAttribute('aria-checked', String(on));
  toggle.setAttribute('aria-label', label);
  toggle.append(jel('span', 'knob'));
  walkSwitch(toggle, key, on, real);
  sc.append(toggle);
  row.classList.add('press');
  row.addEventListener('click', onClick);
  return row;
}

/* The half-filled circle of the Theme button and the rail. */
function themeGlyph() {
  const svg = strokeIcon('0 0 16 16', 'setglyph', ['M8 2.25a5.75 5.75 0 1 0 0 11.5a5.75 5.75 0 1 0 0-11.5z']);
  const half = document.createElementNS('http://www.w3.org/2000/svg', 'path');
  half.setAttribute('d', 'M8 2.25a5.75 5.75 0 0 1 0 11.5z');
  half.setAttribute('fill', 'currentColor');
  half.setAttribute('stroke', 'none');
  svg.append(half);
  return svg;
}

/* The Theme section's cards, one radio each. Each preview carries its own
   data-theme, so it paints itself in that theme's variables. The arrows move
   and pick together, as radios do. */
function paintThemeCards(box) {
  const shown = themeNow();
  box.setAttribute('role', 'radiogroup');
  box.setAttribute('aria-label', 'Theme');
  box.replaceChildren(...THEMES.map((t) => {
    const card = jel('button', 'tcard');
    card.type = 'button';
    card.setAttribute('role', 'radio');
    card.setAttribute('aria-checked', String(t.id === shown));
    card.dataset.key = 'theme-' + t.id;
    card.tabIndex = t.id === shown ? 0 : -1;
    const prev = jel('span', 'tprev');
    prev.dataset.theme = t.id;
    prev.setAttribute('aria-hidden', 'true');
    prev.append(jel('i', 'tb'), jel('i', 'ts'), jel('i', 'tn v'), jel('i', 'tn t'), jel('i', 'te'));
    card.append(prev, jel('span', 'tname', t.name), jel('span', 'tdesc', t.about));
    card.addEventListener('click', () => pickTheme(t.id));
    return card;
  }));
  // Assigned, not added: the box is drawn again and keeps its one listener.
  box.onkeydown = (e) => {
    const cards = [...box.querySelectorAll('.tcard')];
    const at = cards.indexOf(document.activeElement);
    const to = { ArrowRight: at + 1, ArrowDown: at + 1, ArrowLeft: at - 1, ArrowUp: at - 1, Home: 0, End: cards.length - 1 }[e.key];
    if (at < 0 || to === undefined) return;
    e.preventDefault();
    const next = cards[(to + cards.length) % cards.length];
    // Focused first: the redraw the pick causes puts the focus back by data-key.
    next.focus();
    pickTheme(THEMES[cards.indexOf(next)].id);
  };
}

/* Follow the system, a switch of its own. */
function paintThemeFollow(box) {
  // The switch's track takes its colour from --tool, whatever the theme: a group sets one.
  box.dataset.tool = 'theme';
  box.replaceChildren(switchRow('theme-follow', 'Follow the system', 'Light while the system is light, Night once it turns dark.', !!S.look.follow,
    // Off, it keeps the theme on screen.
    () => setLook(S.look.follow ? { follow: false, theme: themeNow() } : { follow: true }), box.isConnected, jel('span', 'newtag', 'new')));
}

/* What only the Halloween theme has: its apparitions and its box style.
   Dimmed while another theme is on, its controls still usable. */
function paintThemeHalloween(box) {
  const on = themeNow() === 'halloween';
  box.dataset.tool = 'theme';
  box.classList.toggle('faded', !on);
  box.replaceChildren();
  setGroupHead(box, 'With Halloween', on ? '' : 'once the Halloween theme is on');
  box.append(switchRow('look-apparitions', 'Random apparitions', 'A ghost crossing the page and a pair of eyes in the dark, now and then.',
    S.look.apparitions !== false, () => setLook({ apparitions: S.look.apparitions === false }), box.isConnected));
  // The lineage's boxes, one of three: a pure CSS switch, so the canvas is not drawn again.
  const styles = [['tombstone', 'Headstone'], ['coffin', 'Coffin'], ['grimoire', 'Spellbook']];
  const now = hwBoxes(S.look.boxes);
  const seg = jel('div', 'seg2');
  seg.setAttribute('role', 'radiogroup');
  seg.setAttribute('aria-label', 'Box style');
  for (const [value, label] of styles) {
    const b = jel('button', '', label);
    b.type = 'button';
    b.dataset.key = 'look-boxes-' + value;
    b.setAttribute('role', 'radio');
    b.setAttribute('aria-checked', String(now === value));
    b.tabIndex = now === value ? 0 : -1;
    b.addEventListener('click', () => setLook({ boxes: value }));
    seg.append(b);
  }
  // On the group built here: it is drawn again with it, so no listener piles up.
  seg.onkeydown = (e) => {
    const all = [...seg.querySelectorAll('button')];
    const at = all.indexOf(document.activeElement);
    const to = { ArrowRight: at + 1, ArrowDown: at + 1, ArrowLeft: at - 1, ArrowUp: at - 1, Home: 0, End: all.length - 1 }[e.key];
    if (at < 0 || to === undefined) return;
    e.preventDefault();
    const next = (to + all.length) % all.length;
    // Focused first: the redraw the pick causes puts the focus back by data-key.
    all[next].focus();
    setLook({ boxes: styles[next][0] });
  };
  const { row, sc } = buildRow('Box style', 'How the lineage draws its boxes.');
  sc.append(seg);
  box.append(row);
}

const HW_GHOST = '<svg viewBox="0 0 84 90"><use href="#hw-s-cross"/></svg>';

function hwReduced() { return !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches); }

/* A ghost drifting across the window, left to right or back, at a random
   height. Skipped for someone who asked for no motion. */
function showGhost() {
  const layer = $('#hw-layer');
  if (!layer || hwReduced()) return;
  const g = document.createElement('div');
  g.className = 'hw-cross' + (Math.random() < 0.5 ? ' rtl' : '');
  g.style.top = `${10 + Math.random() * 70}vh`;
  g.innerHTML = HW_GHOST;
  g.addEventListener('animationend', (e) => { if (e.target === g) g.remove(); });
  layer.appendChild(g);
}

/* A pair of eyes in the dark, blinking twice. */
function showEyes() {
  const layer = $('#hw-layer');
  if (!layer) return;
  const e = document.createElement('div');
  e.className = 'hw-eyes';
  e.style.left = `${8 + Math.random() * 80}vw`;
  e.style.top = `${15 + Math.random() * 70}vh`;
  // Open and shut, both drawn: the blink swaps one for the other, so the lid is a drawing and not a squashed scale.
  e.innerHTML = '<svg class="open" viewBox="0 0 40 16"><use href="#hw-s-eyes"/></svg><svg class="shut" viewBox="0 0 40 16"><use href="#hw-s-eyes-shut"/></svg>';
  e.addEventListener('animationend', () => e.remove());
  layer.appendChild(e);
}

/* Each kind comes back at a random time of its own range, a turn skipped
   while the tab is hidden (nobody to see it) and the next one set as usual. */
function scheduleApparition(kind) {
  const [min, max, show] = kind === 'ghost' ? [4, 9, showGhost] : [15, 20, showEyes];
  S.hw[kind + 'Timer'] = setTimeout(() => {
    if (!S.hw.running) return;
    // The next one is set first, so a drawing that fails ends nothing.
    scheduleApparition(kind);
    if (document.hidden) return;
    try { show(); } catch { /* a missing layer, not worth a word */ }
  }, nextApparitionDelay(min, max, Math.random()));
}

function startApparitions() {
  stopApparitions();
  S.hw.running = true;
  scheduleApparition('ghost');
  scheduleApparition('eyes');
}

function stopApparitions() {
  S.hw.running = false;
  clearTimeout(S.hw.ghostTimer);
  clearTimeout(S.hw.eyesTimer);
  const layer = $('#hw-layer');
  if (layer) layer.replaceChildren();
}

// -------------------------------------------------------------- splitters --
function wireSplitters() {
  // `refit` fits the canvas to its new size once let go; the selection's card
  // does not ask for it, as the reader may have zoomed into the part beside it.
  const drag = (gutter, onMove, { refit = true } = {}) => {
    gutter.addEventListener('mousedown', (e) => {
      e.preventDefault();
      gutter.classList.add('drag');
      const move = (ev) => onMove(ev);
      const up = () => {
        gutter.classList.remove('drag');
        window.removeEventListener('mousemove', move);
        window.removeEventListener('mouseup', up);
        S.cm && S.cm.refresh();
        if (S.fit && !$('#dock-terminal').classList.contains('hidden')) { try { S.fit.fit(); } catch {} }
        if (refit) Lineage.fit();
      };
      window.addEventListener('mousemove', move);
      window.addEventListener('mouseup', up);
    });
  };
  drag($('#gutter-side'), (e) => {
    const w = Math.min(520, Math.max(150, e.clientX));
    document.documentElement.style.setProperty('--side-w', w + 'px');
  });
  drag($('#gutter-dock'), (e) => {
    const body = $('#body').getBoundingClientRect();
    const pct = Math.min(85, Math.max(10, ((body.bottom - e.clientY) / body.height) * 100));
    document.documentElement.style.setProperty('--dock-h', pct + '%');
  });
  // On the card rather than the page, and once a frame: each width lays the
  // canvas and the card out again, and the band names are placed again.
  let gripAt = null;
  drag($('#selpanel-grip'), (e) => {
    if (gripAt === null) {
      requestAnimationFrame(() => {
        const card = $('#selpanel-card'), body = card.parentNode.getBoundingClientRect();
        card.style.setProperty('--selcard-w', selCardWidth(gripAt, body.left, body.right) + 'px');
        gripAt = null;
        Lineage.placeHeads();
      });
    }
    gripAt = e.clientX;
  }, { refit: false });
}

// ------------------------------------------------------------------ tour --
/* "Give me a tour", from the shortcut list, and offered once on its own
   (0074). Each step points at a part of the page and says what it is for,
   on a model the server picks with parents and children. It runs nothing and
   changes no setting: it opens a file as a preview, moves the lineage and the
   dock, draws a selection in the Lineage space, rolls the settings down on
   their Column lineage section, and puts them back as they were when it
   ends. The pure part runs from tourSteps to tourPlace, which
   web/tests/tour.js slices. */

/* The steps, from what the page knows when the tour starts: `model` from
   /api/tour, `manifest` whether one was read, `jobs` how many job sources
   there are, `reports` the labels of
   the reports with something to show, `cll` the column lineage tool on
   screen, '' for none, and `snowflake` whether its features are on. A step
   about a model is left out without one; a step about a feature that is off
   says how to turn it on. Text between backticks is set as code, and a key
   between braces as a key: ⌘` holds a backtick of its own. */
function tourSteps(c) {
  const m = c.model;
  const key = (combo) => '{' + keyLabel(combo, c.mac) + '}';
  const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
  const steps = [];
  const leftOut = 'so the editor, the lineage, the Catalog and the Jobs tab are left out.';
  // Without a model the welcome rings the ? button, where the tour is taken
  // again: a list nobody has opened is no place to send anyone by name.
  const again = `then take the tour again from the shortcut list, behind this button or ${key('?')}: Give me a tour `
    + `heads it. ${key('Escape')} ends it.`;
  steps.push({ key: 'welcome', target: m ? '' : '#keys-btn', title: 'A tour of dbt-edith',
    text: m
      ? (m.package ? 'This project has no model of its own, so it opens' : 'It opens')
        + ` \`${m.name}\`, a model of ${m.package ? `the package \`${m.package}\`` : 'this project'} with `
        + `${plural(m.parents, 'parent', 'parents')} and ${plural(m.children, 'child', 'children')}, and points at `
        + `what each part of the page does with it. It runs nothing and changes no setting, and ${key('Escape')} ends `
        + 'it at any step.'
      : c.manifest
        ? `This manifest has no model to show, ${leftOut} Once the project has one, run \`dbt parse\` in the `
          + `terminal, ${again}`
        : `There is no \`manifest.json\` to read yet, ${leftOut} Run \`dbt parse\` in the terminal, which writes `
          + `one, ${again}` });
  // Right after the welcome: every step after it is only as true as this file.
  const read = 'Everything here is read from `manifest.json`, which only dbt writes: the lineage, the Catalog, every '
    + 'selection, what each job runs.';
  const after = '; the page reads the new manifest on its own. The arrows at its end read the file again at once.';
  const parse = 'Hovering or clicking it opens its card, which says which files and where the branch sits and, '
    + 'once a file has moved, holds a button that runs `dbt parse` in the terminal' + after;
  // With no manifest the card lists no files and no branch drift to speak of.
  const parseNone = 'Hovering or clicking it opens its card, with a button that runs `dbt parse` in the terminal' + after;
  steps.push({ key: 'manifest', target: '#manifest-pill', title: 'manifest.json, and how fresh it is',
    text: c.manifest
      ? `${read} So the page is as true as the last \`dbt parse\`. This says how old the manifest is, and its mark `
        + 'whether a file dbt reads changed since: a green check, none has; an amber triangle, your own saved edits; a red '
        + `cross, a pull, a checkout or a merge. ${parse}`
      : `${read} There is none yet, so this says no manifest. ${parseNone}` });
  if (m) {
    steps.push({ key: 'editor', target: '#editor-pane', title: `${m.name}, in the editor`,
      text: 'Every `ref()`, `source()` and macro call is a link to the file behind it, and hovering one says what it is. '
        + 'Each part of the breadcrumb above opens a menu of what sits beside it.' });
    steps.push({ key: 'config', target: ['#crumbs .cfg', '.crumbmenu.config'], title: 'Where dbt_project.yml configures it',
      text: `The violet \`dbt_project.yml\` button at the end of the breadcrumb shows the lines of \`dbt_project.yml\` that reach \`${m.name}\`, `
        + 'as the file writes them; a key a deeper folder replaces is struck. Picking a line opens `dbt_project.yml` there. '
        + 'A `config()` in the model, or in its properties YAML, still wins over them.' });
    steps.push({ key: 'lineage', target: '#dock-lineage', title: 'Lineage',
      text: `\`${m.name}\` and its neighbours, as many levels up and down as the numbers either side of its name say, read from \`manifest.json\`: `
        + 'nothing here runs dbt. Click a box to read its file, double-click to centre the lineage on it, and a `+N` '
        + 'badge pulls in one more level. Opening a model\'s file moves the lineage onto it. '
        + `${key('Mod+F')} over the canvas finds a box by its name and brings it to the middle.` });
    steps.push({ key: 'select', target: '#selpanel-head', title: 'Lineage, as a selection',
      text: 'Any set of nodes, written the way dbt reads a selection: names, `tag:`, `path:`, `+` and `@`, or a named '
        + `selector from \`selectors.yml\`. This one, \`+${m.name}+\`, is everything it is built from and everything `
        + 'built from it. It opens over the whole window, from the Lineage tab in the top bar or the lineage\'s bar, '
        + 'and an empty box starts as the model in front with a level either side. '
        + 'A click on a box opens its card beside the canvas, a double-click opens its file. dbt ls types the same '
        + 'selection into the terminal, for you to check against dbt itself.' });
    steps.push({ key: 'share', target: ['#export-btn', '#select-copy'], title: 'Export, or copy as an image',
      text: 'Whatever the canvas shows, this selection included. Export opens a menu that says what you get: Copy as '
        + 'image puts the picture on the clipboard as a PNG, for a ticket or a chat; Save as image saves the same '
        + 'picture as a .png file; Save as HTML page saves one file that opens offline, zooms without blurring and '
        + 'prints on one page. Copy names, in the bar of the selection, copies the names instead, one per line.' });
    steps.push({ key: 'catalog', target: '#dock-catalog', title: 'Catalog',
      text: `What the manifest says of \`${m.name}\`: its materialization, description, tags and tests, where it lands `
        + 'in each environment, the steps of your jobs that run it once the Jobs tab has a source, and its columns '
        + 'under Columns. Its upstream and downstream counts move the lineage, as a box does.' });
  }
  // In the settings, behind the sliders, where every setting is (0100); the
  // Columns tab's menu picks the same.
  const columns = c.cll
    ? `On screen: ${c.cll}. A click on a column in Catalog > Columns follows it from model to model, and this `
      + 'section of the settings, behind the sliders in the top bar, picks where the edges come from, as the menu in '
      + 'that tab does.'
    : 'None yet: this section of the settings, behind the sliders in the top bar, picks where a column\'s lineage comes '
      + 'from. Collin reads the compiled SQL, and picking it runs it, or offers the command that installs it'
      + (c.snowflake ? '; Snowflake fetches a column\'s lineage when you click it.' : '.')
      + ' Then a click on a column in Catalog > Columns follows it from model to model.'
      + (c.snowflake ? '' : ' Snowflake joins the list once its features are on, in the Snowflake section.');
  steps.push({ key: 'columns', target: '#settings-view [data-live=columns]', title: 'Column lineage', text: columns });
  if (m) {
    steps.push({ key: 'jobs', target: '#dock-jobs', title: 'Jobs',
      text: c.jobs
        ? `Which of your orchestrator's jobs run \`${m.name}\`: an Airflow DAG and its task, or a dbt Cloud job and `
          + 'its step, with its schedule and its dbt command, resolved here as a selection is. Sources…, '
          + 'at the right of the dock\'s tab row, says where the jobs are read from.'
        : 'Which of your orchestrator\'s jobs run a model, read from their YAML, often in another repository: '
          + 'Airflow DAGs or dbt Cloud jobs. None is read yet: Add a source names the folder they are in, and '
          + 'nothing outside the project is read before.' });
  }
  const reportsKey = key('Mod+Alt+R');
  steps.push({ key: 'reports', target: '#space-reports', title: 'Reports',
    text: c.reports.length
      ? `Reports on the whole project: ${c.reports.join(', ')}. A chip on the button says what is new in them `
        + `since you last looked, and ${reportsKey} opens them from anywhere.`
      : 'Reports on the whole project, dimmed until one has something to show: the last dbt run, from '
        + '`run_results.json`, the config paths of dbt_project.yml that apply to nothing, collin\'s findings, '
        + 'the job coverage once the Jobs tab has a source, and a macro of the project no node reaches that nothing '
        + 'explains. Meanwhile '
        + `it opens on the coverage, where a source is added, and ${reportsKey} opens it from anywhere.` });
  steps.push({ key: 'terminal', target: '#dock [data-dock=terminal]', title: 'Terminal',
    text: 'A shell in the project folder, where dbt runs: this page never runs it. A button that offers a dbt '
      + 'command, such as dbt ls above the lineage, types it there and leaves Enter to you. '
      + `${key('Mod+`')} brings it forward from anywhere.` });
  steps.push({ key: 'search', target: '#palette-btn', title: 'Search',
    text: `Every model, source, macro and file of the project by its name, from ${key('Mod+K')} anywhere. The Search tab `
      + 'in the sidebar looks inside the files instead.' });
  steps.push({ key: 'end', target: '#keys-btn', title: 'Every shortcut, and this tour',
    text: `${key('?')} or ${key('F1')} lists every shortcut, and Give me a tour at the top of that list starts this `
      + 'again. That is the tour.' });
  return steps;
}

/* The ring around a target: its box grown by `pad`, kept inside the view so
   a pane against the window's edge still shows all four sides. A target of
   several elements is rung as one box around them all. */
function tourRing(at, view, pad = 4) {
  const left = Math.max(2, at.left - pad), top = Math.max(2, at.top - pad);
  const right = Math.min(view.width - 2, at.right + pad), bottom = Math.min(view.height - 2, at.bottom + pad);
  return { left, top, width: Math.max(0, right - left), height: Math.max(0, bottom - top) };
}

/* Where the card goes beside a ring: below it, centred on it, when it fits,
   then above, and otherwise inside its lower edge, for a target as tall as
   the window. Never off screen. */
function tourPlace(ring, box, view, gap = 12) {
  const left = Math.max(8, Math.min(ring.left + ring.width / 2 - box.width / 2, view.width - box.width - 8));
  const bottom = ring.top + ring.height;
  if (bottom + gap + box.height <= view.height - 8) return { left, top: bottom + gap };
  if (ring.top - gap - box.height >= 8) return { left, top: ring.top - gap - box.height };
  return { left, top: Math.max(8, Math.min(bottom - box.height - gap, view.height - box.height - 8)) };
}

/* Starts the tour, unless one is on screen. The overlay goes up at once, so
   nothing can be done under it while the model is picked, and what the tour
   will move is noted in the same moment, to be put back when it ends. */
async function startTour() {
  if (S.tour) return;
  closeShortcuts();
  closePalette();
  const panel = S.panel;
  const panelSaved = panel ? PANELS[panel].save() : null;
  const panelReturn = S.panelReturn;
  closePanel();
  closePopup();
  closeHoverCard();
  for (const offer of $$('.tour-offer')) offer.remove();
  const t = { at: -1, ask: 0, chain: Promise.resolve() };
  S.tour = t;
  t.saved = {
    active: S.active, preview: S.preview, order: S.order.slice(), dock: S.dock, mode: S.graphMode,
    focus: S.focus, colFocus: S.colFocus, jobsFor: S.jobsFor, unsynced: S.unsynced,
    select: $('#select-input').value, history: S.selectHistory.slice(), catTab: S.catTab,
    up: $('#up').value, down: $('#down').value,
    node: S.node, catalog: [...$('#catalog').childNodes], back: document.activeElement,
    panel, panelSaved, panelReturn, settingsSection: S.settingsSection,
  };
  buildTour(t);
  // The index too, so the Reports step says what the button shows even when
  // the page asked for it a moment ago and has not heard back.
  const [{ model, sources: jobs }] = await Promise.all([
    api.get('/api/tour').then((r) => ({ model: r.model || null, sources: r.sources || 0 }), () => ({ model: null, sources: 0 })),
    loadReportsIndex(),
  ]);
  if (S.tour !== t || t.ending) return;
  const pick = lineagePickLabel(S.meta, S.cllTool, sidecarOn(), S.sidecar, S.collin);
  t.model = model;
  t.steps = tourSteps({
    model, mac: IS_MAC, jobs,
    manifest: !!(S.meta && S.meta.manifest_mtime),
    reports: reportsNow().sections.filter(lights).map((sec) => sec.label),
    // A tool picked is not yet edges on screen: collin running or failed has none.
    cll: (S.meta && S.meta.cll_file) || sidecarOn() ? pick.name : '',
    snowflake: !!(S.features && S.features.snowflake),
  });
  tourGo(0);
}

/* The overlay: a ring that dims the rest of the page through its shadow, and
   a card, which says the model is being picked until the first step is
   ready. The page under it takes no click and no key while it is up. */
function buildTour(t) {
  const root = jel('div', 'centre');
  root.id = 'tour';
  root.setAttribute('role', 'dialog');
  root.setAttribute('aria-modal', 'true');
  root.setAttribute('aria-labelledby', 'tour-title');
  const ring = jel('div', 'tour-ring hidden');
  const card = jel('div', 'tour-card');
  card.tabIndex = -1;
  const head = jel('div', 'tour-head');
  const close = jel('button', 'icon', '×');
  close.type = 'button';
  close.title = `End the tour (${keyLabel('Escape', IS_MAC)})`;
  close.addEventListener('click', endTour);
  head.append(jel('span', 'tour-count'), jel('div', 'grow'), close);
  const title = jel('h2', '', 'A tour of dbt-edith');
  title.id = 'tour-title';
  const back = jel('button', 'btn sm tour-back', 'Back');
  back.type = 'button';
  back.disabled = true;
  back.addEventListener('click', () => tourStep(-1));
  const next = jel('button', 'btn sm primary tour-next', 'Next');
  next.type = 'button';
  next.disabled = true;
  next.addEventListener('click', () => tourStep(1));
  const actions = jel('div', 'tour-actions');
  const keys = jel('span', 'tour-keys', '← →');
  keys.title = 'The arrow keys walk the tour too';
  actions.append(keys, jel('div', 'grow'), back, next);
  card.append(head, title, jel('p', 'tour-text', 'Picking a model of this project…'), actions);
  root.append(ring, card);
  document.body.append(root);
  for (const id of ['#topbar', '#body', '#statusbar']) $(id).inert = true;
  t.root = root;
  card.focus();
  window.addEventListener('keydown', tourKey, true);
  window.addEventListener('resize', paintTour);
}

/* The keys the app answers from anywhere, which wait for the tour to end,
   with what the browser would do with them meanwhile: Cmd+S would offer to
   save the page, and F1 open the browser's help. */
function tourHeld() {
  return new Set(shortcutSheet().filter((g) => g.title === 'Anywhere' || g.title === 'Find')
    .flatMap((g) => g.keys.flatMap(([combos]) => combos)).filter((k) => /Mod|Alt|(^|\+)F\d|^\?$/.test(k)));
}

/* The arrows and Enter walk the tour, Escape ends it, and every other key
   waits for it to end. Enter on a button is the button's own, and Tab moves
   between the card's buttons, the rest of the page being inert. */
function tourKey(e) {
  if (!S.tour) return;
  if (S.tour.ending) {
    // The page is being put back: nothing reaches it, and nothing walks on.
    if (e.key !== 'Tab') e.preventDefault();
    e.stopPropagation();
    return;
  }
  const onButton = e.target && e.target.tagName === 'BUTTON';
  if (e.key === 'Escape') endTour();
  else if (e.key === 'ArrowRight' || (e.key === 'Enter' && !onButton)) tourStep(1);
  else if (e.key === 'ArrowLeft') tourStep(-1);
  else {
    if (tourHeld().has(keyCombo(e, IS_MAC))) e.preventDefault();
    e.stopPropagation();
    return;
  }
  e.preventDefault();
  e.stopPropagation();
}

function tourStep(by) {
  const t = S.tour;
  if (!t || !t.steps || t.ending) return;
  const to = t.at + by;
  if (to >= t.steps.length) return endTour();
  if (to >= 0) tourGo(to);
}

/* Sets the page up for a step, then draws the ring and the card over it.
   One step sets the page up at a time, and one passed meanwhile, by a key
   held down or an end, stops at its next look: finishing over the next step,
   or after the end, it would leave its canvas or its menu behind. */
async function tourGo(i) {
  const t = S.tour;
  if (!t || !t.steps || t.ending) return;
  t.at = i;
  const ask = ++t.ask;
  const step = t.steps[i];
  const live = () => S.tour === t && t.ask === ask;
  t.chain = t.chain.then(async () => {
    if (!live()) return;
    closeCrumbMenu();
    try { await tourEnter(step.key, t, live); }
    catch (e) { toast('tour: ' + e.message, 'err'); }
  });
  await t.chain;
  // The dock fits its canvas 30 ms after it is shown, and a target can still
  // be moving, or not drawn yet: the ring waits for it to stand still.
  const wait = (ms) => new Promise((done) => setTimeout(done, ms));
  await wait(60);
  for (let n = 0, was = null; step.target && n < 12 && live(); n++) {
    const r = tourTarget(step.target);
    const now = r ? [r.left, r.top, r.right, r.bottom].join() : null;
    if (now !== null && now === was) break;
    was = now;
    await wait(50);
  }
  if (!live()) return;
  paintTour();
  t.root.querySelector('.tour-next').focus();
}

/* What each step needs on screen. Each sets up all of it, whichever step it
   is reached from, so Back works as Next does, and stops as soon as `live`
   says the tour has moved on. */
async function tourEnter(key, t, live) {
  const m = t.model;
  // The model's file in front, and with `canvas`, its lineage on the canvas:
  // a step that draws a selection there has no use for it first.
  const onModel = async ({ canvas = true } = {}) => {
    if (!m) return;
    if (S.active !== m.file) {
      // A tab already open is brought forward as it is, a preview left one.
      if (S.open.has(m.file)) activate(m.file, false);
      else await openFile(m.file, { preview: true, focusLineage: false });
    }
    if (canvas && live() && (S.graphMode !== 'model' || S.focus !== m.id)) await focusNode(m.id);
  };
  // The settings are down for their own step only.
  if (key !== 'columns' && panelOpen('settings')) closePanel();
  const selection = async () => {
    showDock('lineage');
    if (S.graphMode === 'select' && $('#select-input').value === `+${m.name}+`) return;
    $('#select-input').value = `+${m.name}+`;
    await runSelection();
  };
  switch (key) {
    case 'editor':
      await onModel();
      break;
    case 'lineage':
      await onModel();
      if (live()) showDock('lineage');
      break;
    case 'select':
    case 'share':
      await onModel({ canvas: false });
      if (live()) await selection();
      break;
    case 'catalog':
      await onModel();
      if (!live()) break;
      // A test shows Preview whatever the tab, and leaves the one picked for
      // the next model.
      if (S.catTab !== 'preview' && S.node.kind !== 'test') showCatalogTab(S.node, 'preview');
      showDock('catalog');
      break;
    case 'columns':
      // Over the model the steps around it show, which Back comes back to.
      await onModel();
      if (live()) openSettings('columns');
      break;
    case 'jobs':
      await onModel();
      // The jobs as last read, which /api/tour has just read if nothing had:
      // the tour never asks to look at the job files again (0063, 0075).
      if (live()) await showDock('jobs', { look: false });
      break;
    case 'config': {
      await onModel();
      const button = live() && $('#crumbs .cfg');
      if (!button) break;
      // Opened, so the step shows the keys themselves, but not to be used
      // from the tour: a key picked would open dbt_project.yml under it.
      await openCrumbMenu(button, { kind: 'config', file: S.active });
      if (!live()) closeCrumbMenu();
      else if (crumbMenu) crumbMenu.el.inert = true;
      break;
    }
  }
}

/* The box around a step's target, one selector or several: every element
   found and drawn, as one box. Null when none is on screen. */
function tourTarget(target) {
  const boxes = [].concat(target).map((sel) => document.querySelector(sel)).filter(Boolean)
    .map((el) => el.getBoundingClientRect()).filter((r) => r.width > 0 && r.height > 0);
  if (!boxes.length) return null;
  return {
    left: Math.min(...boxes.map((r) => r.left)), top: Math.min(...boxes.map((r) => r.top)),
    right: Math.max(...boxes.map((r) => r.right)), bottom: Math.max(...boxes.map((r) => r.bottom)),
  };
}

function paintTour() {
  const t = S.tour;
  if (!t || t.at < 0 || t.ending) return;
  const step = t.steps[t.at];
  const root = t.root;
  root.querySelector('.tour-count').textContent = `${t.at + 1} of ${t.steps.length}`;
  root.querySelector('#tour-title').textContent = step.title;
  const text = root.querySelector('.tour-text');
  text.textContent = '';
  for (const [, plain, code, key] of step.text.matchAll(/([^`{]+)|`([^`]*)`|\{([^}]*)\}/g)) {
    if (plain) text.append(plain);
    else text.append(Object.assign(document.createElement(code !== undefined ? 'code' : 'kbd'), { textContent: code !== undefined ? code : key }));
  }
  root.querySelector('.tour-back').disabled = t.at === 0;
  root.querySelector('.tour-next').disabled = false;
  root.querySelector('.tour-next').textContent = t.at === t.steps.length - 1 ? 'Done' : 'Next';
  const at = step.target ? tourTarget(step.target) : null;
  const view = { width: window.innerWidth, height: window.innerHeight };
  const shown = !!at;
  root.classList.toggle('centre', !shown);
  const ring = root.querySelector('.tour-ring');
  const card = root.querySelector('.tour-card');
  ring.classList.toggle('hidden', !shown);
  if (!shown) {
    card.style.left = card.style.top = '';
    return;
  }
  const r = tourRing(at, view);
  Object.assign(ring.style, { left: r.left + 'px', top: r.top + 'px', width: r.width + 'px', height: r.height + 'px' });
  const box = card.getBoundingClientRect();
  const place = tourPlace(r, { width: box.width, height: box.height }, view);
  card.style.left = place.left + 'px';
  card.style.top = place.top + 'px';
}

/* Puts back what the tour moved, once every step still setting the page up
   has stopped. A page with no tab open keeps the model, in the editor, the
   lineage and the Catalog, as a place to start from. Any other gets back its
   tabs in their order, a preview the tour's took the place of included, the
   tab in front, the canvas, the node the dock's tabs speak of, the Catalog,
   and the panel that was down, if one was. */
async function endTour() {
  const t = S.tour;
  if (!t || t.ending) return;
  // The overlay stays, inert under it, until the page is back: a click while
  // it is put back would be undone by it, and a tour started meanwhile would
  // note a page half restored. Every step still setting the page up stops at
  // its next look.
  t.ending = true;
  t.ask++;
  if (t.root) {
    t.root.classList.add('centre');
    t.root.querySelector('.tour-ring').classList.add('hidden');
    const card = t.root.querySelector('.tour-card');
    card.style.left = card.style.top = '';
    t.root.querySelector('.tour-text').textContent = 'Putting the page back…';
    for (const b of t.root.querySelectorAll('button')) b.disabled = true;
  }
  await t.chain;
  closeCrumbMenu();
  // Down for the Column lineage step: what was down before the tour comes
  // back last, and the settings button opens on the section it last showed.
  if (panelOpen('settings')) closePanel();
  const s = t.saved;
  S.settingsSection = s.settingsSection;
  const m = t.model;
  if (s.active) {
    if (m && !s.order.includes(m.file) && S.open.has(m.file) && !S.open.get(m.file).dirty) dropTab(m.file);
    if (s.preview && !S.open.has(s.preview)) await openFile(s.preview, { preview: true, focusLineage: false });
    S.order = s.order.filter((p) => S.open.has(p)).concat(S.order.filter((p) => !s.order.includes(p)));
    if (S.open.has(s.active)) activate(s.active, false);
    else settleTabs();
    $('#select-input').value = s.select;
    // A tour that moved to a model of its own drew it at the default depth.
    const depth = $('#up').value !== s.up || $('#down').value !== s.down;
    $('#up').value = s.up;
    $('#down').value = s.down;
    // A selection is never the mode noted: the tour rolls its panel up
    // first, and puts the panel back last.
    if (s.mode === 'column' && s.colFocus) await focusColumn(s.colFocus.id, s.colFocus.column);
    else if (s.focus) {
      if (S.focus !== s.focus || S.graphMode !== 'model' || depth) await focusNode(s.focus, { keepDepth: true });
    } else blankLineage();
    // Whatever the canvas shows, Jobs, Compiled and Run speak of these.
    Object.assign(S, { focus: s.focus, colFocus: s.colFocus, jobsFor: s.jobsFor, unsynced: s.unsynced });
    if ((S.node && S.node.id) !== (s.node && s.node.id)) {
      S.node = s.node;
      $('#catalog').replaceChildren(...s.catalog);
    }
  } else if (m && S.graphMode !== 'model') {
    // An end on a selection leaves the model's lineage, as the editor does.
    await focusNode(m.id);
  }
  $('#select-input').value = s.select;
  S.selectHistory = s.history;
  S.selectHistAt = -1;
  if (S.catTab !== s.catTab && S.node) showCatalogTab(S.node, s.catTab);
  else S.catTab = s.catTab;
  showDock(s.dock, { look: false });
  S.tour = null;
  window.removeEventListener('keydown', tourKey, true);
  window.removeEventListener('resize', paintTour);
  if (t.root) t.root.remove();
  for (const id of ['#topbar', '#body', '#statusbar']) $(id).inert = false;
  if (s.panel) {
    await PANELS[s.panel].reopen(s.panelSaved);
    // Where Escape in the panel sends the focus back, as before the tour.
    S.panelReturn = s.panelReturn;
  } else if (s.back && s.back.focus && document.body.contains(s.back)) s.back.focus();
  // A manifest that landed during the tour was not asked about (0078).
  if (S.tourOfferHeld && !S.tour) offerTour();
}

/* Once on a machine, the first page to ask with a model to show offers the
   tour beside the ? button, which is where it stays (0074). Nothing opens: it
   waits for an answer, and the server has already noted that it was made.
   Without a model the server notes nothing and the offer is held, to be asked
   for again when a manifest lands (0078). Never while a tour is on screen:
   the server notes the offer as it answers, and a card nobody can see would
   spend it, so the tour's end asks instead. */
async function offerTour() {
  if (S.tour) {
    S.tourOfferHeld = true;
    return;
  }
  const was = S.tourOfferHeld;
  S.tourOfferHeld = false;
  const at = S.meta && S.meta.manifest_mtime;
  let r;
  try { r = await api.send('/api/tour/offer', 'POST', {}); } catch {
    // Not asked, so still to ask at the next manifest.
    S.tourOfferHeld = was;
    return;
  }
  if (r && r.held) {
    S.tourOfferHeld = true;
    // A manifest that landed while the server answered was not asked about.
    if (S.meta && S.meta.manifest_mtime !== at) offerTour();
    return;
  }
  if (!r || !r.offer || S.tour) return;
  const box = jel('div', 'tour-offer');
  box.setAttribute('role', 'dialog');
  box.setAttribute('aria-label', 'A tour of dbt-edith');
  const go = jel('button', 'btn sm primary', 'Give me a tour');
  go.type = 'button';
  const later = jel('button', 'btn sm', 'Not now');
  later.type = 'button';
  // Under the ? button, its arrow on the button's middle, until it goes:
  // answered, or taken away by a tour started from the shortcut list.
  const place = () => {
    if (!box.isConnected) return window.removeEventListener('resize', place);
    const at = $('#keys-btn').getBoundingClientRect();
    const width = box.offsetWidth;
    const left = Math.max(8, Math.min(at.left + at.width / 2 - width + 24, window.innerWidth - width - 8));
    box.style.left = left + 'px';
    box.style.top = (at.bottom + 10) + 'px';
    box.style.setProperty('--arrow-x', (at.left + at.width / 2 - left) + 'px');
  };
  const close = () => {
    box.remove();
    window.removeEventListener('resize', place);
  };
  go.addEventListener('click', () => { close(); startTour(); });
  later.addEventListener('click', close);
  box.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    e.stopPropagation();
    close();
  });
  const actions = jel('div', 'tour-actions');
  actions.append(jel('div', 'grow'), later, go);
  box.append(
    jel('b', '', 'New to dbt-edith?'),
    jel('p', '', 'A tour of what it does, on this project. It runs nothing and changes no setting.'),
    actions,
    jel('p', 'tour-later', `Not now leaves it in the shortcut list, under ${keyLabel('?', IS_MAC)}.`),
  );
  document.body.append(box);
  place();
  window.addEventListener('resize', place);
}

// ------------------------------------------------------------------ keys --
/* A keydown, named the way the shortcut list names it: Mod+Alt+S, Shift+Enter,
   ?. Mod is Cmd or Ctrl, as it always was here. Shift is named for a letter or
   a named key only: for a symbol it is already in the character, which is how
   `?` stays `?` on a layout that types it with Shift and on one that does not.

   On a Mac, Option makes a letter into another character, Option+W into ∑, so
   there the physical key is read instead. Not when Option alone typed a
   letter, though: that is someone writing Â on a French keyboard, and closing
   their tab would be the wrong answer to it. */
function keyCombo(e, mac) {
  let key = e.key || '';
  const letter = /^Key([A-Z])$/.exec(e.code || '');
  if (mac && e.altKey && letter && (e.metaKey || e.ctrlKey || !/^\p{L}$/u.test(key))) key = letter[1];
  if (/^[a-z]$/.test(key)) key = key.toUpperCase();
  if (key === ' ') key = 'Space';
  const mods = [];
  if (e.metaKey || e.ctrlKey) mods.push('Mod');
  if (e.altKey) mods.push('Alt');
  if (e.shiftKey && (/^[A-Z]$/.test(key) || key.length > 1)) mods.push('Shift');
  return mods.concat(key).join('+');
}

/* How a key reads on this machine: ⌥⌘S on a Mac, in Apple's order, and
   Ctrl+Alt+S elsewhere. */
function keyLabel(combo, mac) {
  const parts = combo.split('+');
  const key = parts.pop();
  const k = {
    ArrowUp: '↑', ArrowDown: '↓', ArrowLeft: '←', ArrowRight: '→', Escape: 'Esc', Enter: mac ? '↩' : 'Enter',
    Backspace: mac ? '⌫' : 'Backspace', Delete: mac ? '⌦' : 'Delete',
  }[key] || key;
  if (!mac) return parts.map((m) => (m === 'Mod' ? 'Ctrl' : m)).concat(k).join('+');
  const glyphs = [['Ctrl', '⌃'], ['Alt', '⌥'], ['Shift', '⇧'], ['Mod', '⌘']];
  const mods = glyphs.filter(([m]) => parts.includes(m)).map(([, g]) => g).join('');
  // A mouse action is a word, which reads apart from the glyphs: ⌥ click.
  return mods + (mods && /^[a-z]/.test(k) ? ' ' : '') + k;
}

/* Every shortcut there is, for the list ? opens: each row is the keys, any of
   which does it, and what it does. The keys wireKeys answers to are checked
   against this by web/tests/keys.js, so none is bound without appearing here;
   the rest are answered by CodeMirror or by one box, and are listed by hand.
   `os` is KEYS_OS: the terminal's line keys differ on each (0073). */
function shortcutSheet(os) {
  return [
    { title: 'Anywhere', keys: [
      [['Mod+K'], 'Search models, sources, macros and every file'],
      [['Mod+S'], 'Save the file'],
      [['Mod+Alt+S'], 'Save every modified file'],
      [['Mod+Alt+X', 'Alt+W'], 'Close the tab'],
      [['Mod+Alt+Shift+X'], 'Close every tab'],
      [['Mod+Alt+P'], 'Back to the link you followed'],
      [['Mod+Alt+N'], 'Forward again'],
      [['Mod+`'], 'Show the terminal'],
      [['Mod+Alt+R'], 'Open or close the reports'],
      [['?', 'F1'], 'This list: ? outside a text box, F1 from anywhere'],
    ] },
    { title: 'Lineage, Reports and settings', keys: [
      [['Escape'], 'Back to Code, from inside: a card, menu or find bar open in them closes first'],
      [['Mod+Alt+X', 'Alt+W'], 'Close them too, rather than the tab under them'],
    ] },
    { title: 'Find', keys: [
      [['Mod+F'], 'In a file, or in Compiled or Run: find in that text'],
      [['Mod+F'], 'In the Catalog: filter the columns by name'],
      [['Mod+F'], 'On the lineage: find a node by its name, and centre the view on it'],
      [['Enter', 'Shift+Enter'], 'Next and previous match, from the find box'],
      [['Mod+G', 'Mod+Shift+G'], 'Next and previous match, from the text or the canvas too'],
      [['F3', 'Shift+F3'], 'The same, as in VS Code'],
      [['Escape'], 'Close the find bar, or empty the column filter'],
    ] },
    { title: 'Editor', keys: [
      [['Mod+Z', 'Mod+Shift+Z'], 'Undo and redo'],
      [['Mod+['], 'Indent less'],
      [['Mod+]'], 'Indent more'],
      [['Mod+D'], 'Delete the line, where VS Code would select the next match'],
      [['Alt+click'], 'Put the cursor on a link without following it'],
    ] },
    { title: 'Tabs', keys: [
      [['Middle-click'], 'Close a tab'],
      [['Double-click'], 'Keep a preview tab, the one in italics'],
    ] },
    { title: 'Search box, branches and menus', keys: [
      [['ArrowUp', 'ArrowDown'], 'Move'],
      [['Enter'], 'Open or pick'],
      [['Escape'], 'Close'],
    ] },
    { title: 'Selection box, in the Lineage space', keys: [
      [['Enter'], 'Draw it now'],
      [['ArrowUp', 'ArrowDown'], 'Earlier expressions'],
    ] },
    { title: 'Git', keys: [
      [['Mod+Enter'], 'Commit, from the message box'],
    ] },
    { title: 'Terminal', keys: [
      [['Mod+C'], 'Copy the selection; Ctrl+C with nothing selected interrupts'],
      [['Mod+V'], 'Paste'],
      ...termLineRows(os),
    ] },
    { title: 'Catalog', keys: [
      [['Enter', 'Space'], 'On a +N chip: every test on that column'],
    ] },
  ];
}

/* The terminal's line keys, as termLineKey answers them, for the shortcut
   list: on a Mac in any shell, on Windows in Git Bash, and none elsewhere,
   where the shell reads xterm.js's own. */
function termLineRows(os) {
  if (os === 'mac') return [
    [['Alt+ArrowLeft', 'Alt+ArrowRight'], 'A word back and forward'],
    [['Mod+ArrowLeft', 'Mod+ArrowRight'], 'Start and end of the command'],
    [['Mod+Backspace'], 'Delete the command back to its start, all of it in zsh'],
    [['Alt+Backspace', 'Alt+Delete'], 'Delete the word before and after'],
  ];
  if (os === 'windows') return [
    [['Mod+ArrowLeft', 'Mod+ArrowRight'], 'A word back and forward, in Git Bash'],
    [['Home', 'End'], 'Start and end of the command, in Git Bash'],
    [['Mod+Backspace', 'Mod+Delete'], 'Delete the word before and after, in Git Bash'],
  ];
  return [];
}

/* What the list shows for what is typed in its find box. A row stays when its
   text, one of its keys, or its group's title holds the query, whatever the
   case; a group's title keeps all of its rows. A key is found by its label as
   this machine draws it (`label`) and by its modifiers spelled out, as they are
   said aloud: Cmd, Command and Option on a Mac, where the glyphs cannot be
   typed, and Ctrl and Alt elsewhere, plus the key's own name (Enter, and Return
   beside it on a Mac; ArrowUp, Backspace, Escape). Those are matched from the
   start of a word, never inside one: "man" must not keep every Cmd row through
   Command. keyCombo's own `Mod` and `+` are not searched, since they are in
   nearly every row and hit none in particular. Only the first hit in a row's
   text is marked, split into the parts before, at and after it: a key or a
   title hit marks nothing. A blank query keeps everything. */
function filterShortcuts(sheet, query, label, mac) {
  const q = query.trim().toLowerCase();
  // A French Mac's keys print alt, not the glyph (0037).
  const said = mac
    ? { Mod: 'cmd command', Alt: 'option alt', Shift: 'shift', Ctrl: 'control' }
    : { Mod: 'ctrl', Alt: 'alt', Shift: 'shift', Ctrl: 'ctrl' };
  const starts = (words) => words.split(' ').some((w) => w.startsWith(q));
  const out = [];
  for (const group of sheet) {
    const titleHit = !!q && group.title.toLowerCase().includes(q);
    const rows = [];
    for (const [combos, what] of group.keys) {
      const keys = combos.map((c) => label(c));
      const at = q ? what.toLowerCase().indexOf(q) : -1;
      const keyHit = !!q && combos.some((c, i) => {
        const parts = c.split('+');
        const name = parts.pop().toLowerCase();
        return keys[i].toLowerCase().includes(q) || starts(name + (mac && name === 'enter' ? ' return' : ''))
          || parts.some((m) => starts(said[m] || ''));
      });
      if (q && at < 0 && !keyHit && !titleHit) continue;
      rows.push(at < 0 ? { keys, a: what, m: '', b: '' }
        : { keys, a: what.slice(0, at), m: what.slice(at, at + q.length), b: what.slice(at + q.length) });
    }
    if (rows.length) out.push({ title: group.title, rows });
  }
  return out;
}

/* Whether a key pressed here is text: a box, the editor, the terminal. `?` is
   a shortcut only outside all three. */
function isTyping(el) {
  if (!el || !el.tagName) return false;
  if (el.isContentEditable || el.tagName === 'TEXTAREA' || el.tagName === 'SELECT') return true;
  return el.tagName === 'INPUT' && !/^(checkbox|radio|button|submit|range)$/.test(el.type);
}

/* The shortcut list: ? outside a text box, F1 anywhere, or the button in the
   top bar. Cmd+H was the first idea and cannot work: on a Mac, the system
   hides the browser before any page sees the key (0030). */
function toggleShortcuts() {
  const built = $('#shortcuts');
  if (built && !built.classList.contains('hidden')) return closeShortcuts();
  const box = built || buildShortcuts();
  S.keysReturn = document.activeElement;
  // It opens on every shortcut, whatever was searched for last time.
  const find = box.querySelector('.keys-find input');
  find.value = '';
  // Shown before it is drawn: a hidden box has no scroll to put back to the top.
  box.classList.remove('hidden');
  paintShortcuts(box);
  find.focus();
}

/* Focus goes back to where the keys were typed, the editor usually. */
function closeShortcuts() {
  const box = $('#shortcuts');
  if (!box || box.classList.contains('hidden')) return;
  box.classList.add('hidden');
  const back = S.keysReturn;
  S.keysReturn = null;
  if (back && back.focus && document.body.contains(back)) back.focus();
}

function buildShortcuts() {
  const box = document.createElement('div');
  box.id = 'shortcuts';
  box.className = 'hidden';
  const panel = document.createElement('div');
  panel.className = 'keys-box' + (IS_MAC ? '' : ' pc');
  panel.tabIndex = -1;
  panel.setAttribute('role', 'dialog');
  panel.setAttribute('aria-label', 'Keyboard shortcuts');
  const head = document.createElement('div');
  head.className = 'keys-head';
  // Typing redraws the groups only: the head and the foot stay as they are, so
  // the caret does not leave the box.
  const find = document.createElement('label');
  find.className = 'keys-find';
  const input = document.createElement('input');
  input.type = 'text';
  input.placeholder = 'Find a shortcut, a key or a word';
  input.spellcheck = false;
  input.setAttribute('aria-label', 'Find a shortcut');
  input.addEventListener('input', () => paintShortcuts(box));
  find.append(strokeIcon('0 0 16 16', 'keys-ico', ['M7 2.25a4.75 4.75 0 1 0 0 9.5 4.75 4.75 0 0 0 0-9.5z', 'M10.5 10.5l3.5 3.5']), input);
  const close = document.createElement('button');
  close.type = 'button';
  close.className = 'keys-x';
  close.title = `Close (${keyLabel('Escape', IS_MAC)})`;
  close.setAttribute('aria-label', 'Close');
  close.append(strokeIcon('0 0 16 16', 'keys-ico', ['M4 4l8 8M12 4l-8 8']));
  close.addEventListener('click', closeShortcuts);
  // The tour lives here, where someone looking for what the page can do looks (0074).
  const tour = document.createElement('button');
  tour.type = 'button';
  tour.className = 'btn primary';
  tour.textContent = 'Give me a tour';
  tour.title = 'What each part of the page is for, on a model of this project. It runs nothing.';
  tour.addEventListener('click', startTour);
  head.append(Object.assign(document.createElement('h2'), { textContent: 'Keyboard shortcuts' }), find,
    Object.assign(document.createElement('div'), { className: 'grow' }), tour, close);
  // The grid scrolls and its columns sit inside it: columns on the scrolling box
  // itself would open more columns to the right, not scroll down, once the
  // window is shorter than the list.
  const grid = document.createElement('div');
  grid.className = 'keys-grid';
  grid.append(Object.assign(document.createElement('div'), { className: 'keys-cols' }));
  // The question the list raises first: why not the key every other app uses.
  const note = document.createElement('p');
  note.className = 'keys-note';
  note.textContent = IS_MAC
    ? '⌘W and ⌘H belong to the browser and to macOS, never to a page: one closes the browser tab, '
      + 'the other hides the window. Hence ⌥W to close a tab here, which a French keyboard cannot '
      + 'type at all: there the same command answers to ⌥⌘X, closing every tab to ⌥⇧⌘X, and back '
      + 'and forward ask for ⌘ for the same reason (0037). ? or F1 opens this list.'
    : 'Ctrl+W belongs to the browser, never to a page: it closes the browser tab. Hence Alt+W to close a tab here.';
  const foot = document.createElement('div');
  foot.className = 'keys-foot';
  const kbd = (text) => Object.assign(document.createElement('kbd'), { textContent: text });
  const pressed = document.createElement('span');
  pressed.append(kbd('?'), ' outside a text box, ', kbd('F1'), ' from anywhere but the terminal, ', kbd(keyLabel('Escape', IS_MAC)), ' to close');
  // The list is drawn in this machine's keys, and the foot says how the other's
  // read: the terminal's line keys are the exception, its own on each (0073).
  foot.append(
    Object.assign(document.createElement('span'), { textContent: IS_MAC
      ? 'Keys as on a Mac. On Windows and Linux, ⌘ is Ctrl and ⌥ is Alt, the terminal\'s line keys apart.'
      : 'Keys as on Windows and Linux. On a Mac, Ctrl is ⌘ and Alt is ⌥, the terminal\'s line keys apart.' }),
    Object.assign(document.createElement('div'), { className: 'grow' }),
    pressed);
  grid.append(note);
  panel.append(head, grid, foot);
  box.append(panel);
  box.addEventListener('mousedown', (e) => { if (e.target === box) closeShortcuts(); });
  // Only the list closes: the search box or a dialog under it stays open.
  panel.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    e.preventDefault();
    e.stopPropagation();
    closeShortcuts();
  });
  document.body.append(box);
  return box;
}

/* The groups the find box leaves, drawn again in the columns; the note stays
   under them, read after the groups and scrolled with them. */
function paintShortcuts(box) {
  const query = box.querySelector('.keys-find input').value;
  const cols = box.querySelector('.keys-cols');
  // Each query starts at the top of its hits, not where the last list was scrolled to.
  box.querySelector('.keys-grid').scrollTop = 0;
  const groups = filterShortcuts(shortcutSheet(KEYS_OS), query, (c) => keyLabel(c, IS_MAC), IS_MAC);
  const nodes = [];
  for (const group of groups) {
    const sec = document.createElement('section');
    sec.append(h3(group.title));
    for (const row of group.rows) {
      const line = document.createElement('div');
      line.className = 'keys-row';
      const keys = document.createElement('span');
      keys.className = 'keys-k';
      for (const k of row.keys) keys.append(Object.assign(document.createElement('kbd'), { textContent: k }));
      const what = document.createElement('span');
      what.className = 'keys-what';
      what.append(row.a);
      if (row.m) what.append(Object.assign(document.createElement('mark'), { textContent: row.m }), row.b);
      line.append(keys, what);
      sec.append(line);
    }
    nodes.push(sec);
  }
  if (!groups.length) {
    nodes.push(Object.assign(document.createElement('p'), { className: 'keys-none', textContent: `No shortcut says \u201c${query.trim()}\u201d.` }));
  }
  cols.replaceChildren(...nodes);
}

/* What a close key closes: the panel when one is down, since the tab under
   it cannot be seen, and the tab otherwise. */
function closeFront() {
  if (S.panel) closePanel({ restore: true });
  else if (S.active) closeFile(S.active);
}

function wireKeys() {
  /* Whether a menu was open as the key came in, read before any menu sees it.
     One the pointer opened closes on any key and lets it go on, Escape too
     (0086): that Escape was the menu's, and must not also roll up the panel
     under it once the menu is gone. */
  let menuAtKey = false;
  window.addEventListener('keydown', () => { menuAtKey = anyMenuOpen(); }, true);
  window.addEventListener('keydown', (e) => {
    switch (keyCombo(e, IS_MAC)) {
      case 'Mod+Alt+S': e.preventDefault(); saveAll(); return;
      case 'Mod+S': e.preventDefault(); save(); return;
      /* X for the cross on the tab, and in the same place on every layout.
         Alt+W stays bound for the keyboards it reaches, but a French Mac is
         not one: there the key marked W is `KeyZ`, and the key at `KeyW` is
         marked Z and writes a letter under Option, which keyCombo leaves alone
         on purpose (0030, 0037). Alt+Shift+W is not kept beside it: it sat one
         modifier from Shift+Cmd+W, which closes the browser window. */
      case 'Mod+Alt+X': e.preventDefault(); closeFront(); return;
      case 'Mod+Alt+Shift+X': e.preventDefault(); closeAll(); return;
      case 'Alt+W': e.preventDefault(); closeFront(); return;
      /* P for previous and N for next, and Cmd is not decoration: Option alone
         with a letter is left as typed, since on some layouts it writes one
         (keyCombo). Option+B and Option+N were tried and wrote into the file on
         a keyboard where both produce a letter. Cmd is what makes keyCombo read
         the physical key, as it already does for Mod+Alt+S. Not Alt+Left and
         Alt+Right either, which CodeMirror binds in both its keymaps, nor
         Mod+Alt+Left and Mod+Alt+Right, which Chrome takes for its tabs. */
      case 'Mod+Alt+P': e.preventDefault(); jumpBack(); return;
      case 'Mod+Alt+N': e.preventDefault(); jumpForward(); return;
      case 'Mod+K': e.preventDefault(); openPalette(); return;
      case 'Mod+`': e.preventDefault(); closePanel(); showDock('terminal'); return;
      /* R for reports, in the same place on every layout, with Cmd so that
         keyCombo reads the key and not what Option typed (0037). */
      case 'Mod+Alt+R': e.preventDefault(); goSpace(panelOpen('reports') ? 'code' : 'reports'); return;
      // An editor with the focus has answered this already, and said so.
      case 'Mod+F':
        if (!e.defaultPrevented && findInPane(paneOf(e.target) || S.lastPane)) e.preventDefault();
        return;
      // From the lineage canvas, which holds no focus of its own: an editor
      // and both find bars have answered these already.
      case 'Mod+G': case 'F3':
        if (!e.defaultPrevented && stepGraphFind(paneOf(e.target) || S.lastPane, 1)) e.preventDefault();
        return;
      case 'Mod+Shift+G': case 'Shift+F3':
        if (!e.defaultPrevented && stepGraphFind(paneOf(e.target) || S.lastPane, -1)) e.preventDefault();
        return;
      // Not from the terminal, where F1 belongs to whatever runs in it.
      case 'F1':
        if (e.target.closest && e.target.closest('#term')) return;
        e.preventDefault();
        toggleShortcuts();
        return;
      case '?':
        if (isTyping(e.target)) return;
        e.preventDefault();
        toggleShortcuts();
        return;
    }
    if (e.key === 'Escape' && !$('#palette').classList.contains('hidden')) closePalette();
    else if (e.key === 'Escape' && escapesGraphFind(e)) {
      e.preventDefault();
      closeGraphFind();
    } else if (e.key === 'Escape' && S.panel && !e.defaultPrevented && !menuAtKey
      && (!e.target || e.target === document.body)) {
      // A panel takes Escape on its own element. Once the focus has fallen
      // back to the page, a filter emptied by Escape blurring itself, say,
      // the key reaches only here, and the panel is still what is in front.
      e.preventDefault();
      escapePanel();
    }
  });
  // What Cmd+F searches when nothing has the focus: the pane last used, never a
  // dialog or the top bar.
  const lastPane = (e) => {
    const pane = paneOf(e.target);
    if (pane && pane !== 'other') S.lastPane = pane;
  };
  document.addEventListener('pointerdown', lastPane, true);
  document.addEventListener('focusin', lastPane);
  $('#keys-btn').addEventListener('click', toggleShortcuts);
  $('#palette-input').addEventListener('input', (e) => runPalette(e.target.value));
  $('#palette-input').addEventListener('keydown', (e) => {
    if (e.key === 'ArrowDown') { e.preventDefault(); movePalette(1); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); movePalette(-1); }
    else if (e.key === 'Enter') { e.preventDefault(); enterPalette(); }
  });
  $('#palette').addEventListener('click', (e) => { if (e.target.id === 'palette') closePalette(); });
  $('#palette-btn').addEventListener('click', openPalette);
  $('#model-filter').addEventListener('input', () => {
    clearTimeout(modelTimer);
    modelTimer = setTimeout(refreshModels, 120);
  });
  $('#branch-btn').addEventListener('click', openBranches);
  $('#status-branch').addEventListener('click', openBranches);
  $('#git-fetch').addEventListener('click', async () => {
    const r = await gitPost('fetch');
    if (r && !r.ok) showGitFailure('Fetch failed', r); else toast('fetched', 'ok');
  });
  $('#git-pull').addEventListener('click', doPull);
  $('#git-push').addEventListener('click', doPush);
  $('#commit-btn').addEventListener('click', doCommit);
  $('#commit-kbd').textContent = keyLabel('Mod+Enter', IS_MAC);
  $('#commit-msg').addEventListener('keydown', (e) => {
    if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') { e.preventDefault(); doCommit(); }
  });
  $('#branch-filter').addEventListener('input', (e) => paintBranches(e.target.value));
  $('#branch-filter').addEventListener('keydown', (e) => {
    if (e.key === 'ArrowDown') { e.preventDefault(); moveBranch(1); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); moveBranch(-1); }
    else if (e.key === 'Enter') {
      e.preventDefault();
      const b = (branchHits.visible || [])[branchIndex];
      if (b) chooseBranch(b);
    } else if (e.key === 'Escape') $('#branches').classList.add('hidden');
  });
  $('#branches').addEventListener('click', (e) => { if (e.target.id === 'branches') e.currentTarget.classList.add('hidden'); });
  $('#save-all-btn').addEventListener('click', (e) => { e.stopPropagation(); saveAll(); });
  $('#close-all-btn').addEventListener('click', (e) => { e.stopPropagation(); closeAll(); });
  $('#collapse-btn').addEventListener('click', collapseTree);
  for (const sel of ['#tabbar', '#oe-list']) {
    $(sel).addEventListener('contextmenu', (e) => {
      const el = e.target.closest('[data-key]');
      if (!el) return;
      e.preventDefault();
      openTabMenu(el, el.dataset.key);
    });
  }
  $('#reveal-btn').addEventListener('click', revealActive);
  $('#oe-toggle').addEventListener('click', (e) => {
    const open = $('#open-editors').classList.toggle('collapsed') === false;
    e.currentTarget.setAttribute('aria-expanded', String(open));
  });
  // Its arrows turn until the server has read the file, and a second click
  // meanwhile reads it no sooner.
  $('#reload-btn').addEventListener('click', async (e) => {
    const btn = e.currentTarget;
    if (btn.getAttribute('aria-busy') === 'true') return;
    btn.setAttribute('aria-busy', 'true');
    try {
      const meta = await api.send('/api/reload', 'POST', {});
      applyMeta(meta);
      toast(`manifest reloaded in ${meta.load_ms} ms`, 'ok');
      if (!await followActive()) rerender();
      refreshFreshness();
    } catch (e) { toast('reload failed: ' + e.message, 'err'); }
    finally { btn.removeAttribute('aria-busy'); }
  });
  // The badge opens the pill's card, whose button is the one that types
  // dbt parse in the user's terminal: dbt still runs there, under their
  // environment, never from the server (0002, 0157).
  $('#fresh-badge').addEventListener('click', (e) => openFreshCard(e.currentTarget));
  openOnHover($('#fresh-badge'), (hover) => openFreshCard($('#fresh-badge'), hover));
  $$('#spaces .sp').forEach((b) => b.addEventListener('click', () => goSpace(b.dataset.space)));
  $('#selpanel-card-close').title = `Close the card (${keyLabel('Escape', IS_MAC)})`;
  $('#selpanel-card-close').addEventListener('click', () => closeSelCard());
  // On each panel rather than the document: a dialog over it answers its own
  // Escape there, and must not take the panel with it.
  for (const p of Object.values(PANELS)) {
    $(p.el).addEventListener('keydown', (e) => {
      if (e.key !== 'Escape' || e.defaultPrevented) return;
      // The canvas's find bar closes first, from wherever its Escape comes:
      // the window's handler takes it (0081).
      if (escapesGraphFind(e)) return;
      e.preventDefault();
      e.stopPropagation();
      escapePanel();
    });
  }
}

// ------------------------------------------------------------------ boot --
function applyMeta(meta) {
  // Every caller of this has just learned the graph changed, which is exactly
  // when a cached /api/node payload stops being true. Here rather than at each
  // call site: forgetting one is how a stale count survives a column fetch.
  dropNodeCache();
  // What a step selects follows the manifest alone: a switch of column lineage,
  // a feature or a collin poll brings the same one again.
  const moved = !S.meta || S.meta.manifest_mtime !== meta.manifest_mtime;
  S.meta = meta;
  if (moved && S.rows.size) refreshFileMarks();
  // A sandbox may have appeared or gone, and the pill names the manifest's choice by it.
  if (S.envs) paintEnvSelect();
  // Another cache may hold indirect edges where this one had none.
  paintIndirectToggle();
  $('#project').textContent = meta.project || '(no manifest)';
  $('#project').title = meta.project || '';
  $('#tree-title').textContent = meta.project || 'Project';
  $('#status-counts').textContent = statusCounts(meta.counts);
  const when = meta.manifest_mtime ? new Date(meta.manifest_mtime * 1000).toLocaleString() : 'missing';
  $('#status-manifest').textContent = `dbt ${meta.dbt_version || '?'} · manifest ${when}`;
  // A reload can change the count of edges the menu's button names.
  paintSourceButton();
  // And which nodes each job's selection reaches.
  if (S.dock === 'jobs') loadJobs();
  if (moved) forgetCatalogJobs();
  // A macro a card asked about may be gone, or its callers changed: the
  // Macros section is listed again for what the new manifest leaves (0105).
  if (moved) S.macroFocus = '';
  // And the coverage the reports would show, which the index stamps with it.
  loadReportsIndex();
  // A first manifest may have a model to show the tour on (0078).
  if (moved && S.tourOfferHeld) offerTour();
}

/* A whole /api/meta answer: the graph's facts, then where its column lineage
   comes from, which the settings' rail names in place of a count. */
function applyInfo(info) {
  applyMeta(info.meta);
  applyLineage(info);
}

/* One click on a box opens its file as the preview, the way one click in the
   tree does: walking the graph leaves no tab behind, and the canvas stays where
   it is. Two clicks pin it and centre the lineage on it (onOpen). The move is
   recorded, so Back returns to a pinned tab it left, but it pins nothing: a
   preview it leaves is replaced, as the next click in the tree would. */
function previewBox(n) {
  // A generic test lands on its line, in the file already shown too (0041).
  if (n.kind === 'test' && n.test_name) return openTest(n, { focus: false });
  if (!n.file || n.file === S.active) return;
  pushJump({ pin: false });
  openFile(n.file, { focusLineage: false, preview: true });
  revealInTree(n.file);
}

/* Two clicks on a box, a model's or one of its columns': the first already
   opened the file as the preview and recorded where it came from, so this one
   pins it in place. */
function pinBoxFile(n) {
  if (!n.file) return;
  if (S.active !== n.file) pushJump();
  openFile(n.file, { focusLineage: false });
  revealInTree(n.file);
}

/* What the status bar offers for an /api/update answer (0068): nothing until
   a later release is known, then a pill naming it, and a menu with its notes
   and, for a binary built from a clone on this machine, the command that
   brings the clone up to the release and rebuilds it, or why there is none. `os` is the server's, which
   decides what a refusal points to. Pure, for web/tests/update.js. */
function updateOffer(u, os) {
  if (!u || !u.newer) return null;
  const hows = u.hows || [];
  const restart = `stop dbt-edith where you started it and start it again: until then, ${u.current} serves this page.`;
  const head = `dbt-edith ${u.latest} · this is ${u.current}`;
  // Installed in this one's place (0095): what is left is the restart, and
  // the command again would only stop on the renamed .exe. Which version
  // went in is not known, and a release out since may not be it, so none is
  // named: a restart onto one still behind is offered the update again.
  if (u.replaced) {
    return {
      label: 'restart to update',
      title: `A new dbt-edith is installed in this one's place, and this is still ${u.current}: restart it to run it`,
      head: `dbt-edith ${u.current} · a new one is installed`,
      notes: u.notes || '',
      command: '',
      installed: true,
      step: `A new dbt-edith is installed in this one's place. To run it, ${restart}`,
      options: [],
      lines: [],
    };
  }
  // One option per command the server offered, the recommended first (0123).
  // With a choice each button says what it does; alone it is the update.
  const options = hows.map((how) => {
    const download = how.kind === 'download';
    return {
      kind: how.kind,
      command: how.command,
      button: hows.length < 2 ? `Update to ${u.latest}`
        : download ? 'Download the release\'s .exe' : `Update to ${u.latest} with cargo`,
      step: `It types the update into the terminal below. Press Enter there to run it`
        + `${download ? ',' : ', a minute or two,'} then ${restart}`,
      lines: [download
        ? 'It downloads the .exe CI built for this release, of this build\'s architecture, checks its SHA-256 '
          + 'against the one published beside it, and replaces the running .exe with it.'
        : how.kind === 'build'
          ? `It brings ${how.source} up to v${u.latest}, the release's tag and no further, and builds it again with cargo build --release, compiling it on this machine.`
          : `It brings ${how.source} up to v${u.latest}, the release's tag and no further, and installs it again with cargo install, compiling it on this machine.`],
    };
  });
  const lines = options.flatMap((o) => o.lines);
  // Said once, whichever command is pressed.
  const stepping = hows.find((how) => how.renames);
  if (stepping) {
    const fails = hows.some((how) => how.kind === 'download') && hows.length > 1 ? 'swap or the build'
      : hows[0].kind === 'download' ? 'swap' : 'build';
    lines.push(`Windows will not replace a running .exe but lets it be renamed: ${stepping.exe} steps aside as `
      + `${stepping.exe}.old first, goes on serving this page, and comes back if the ${fails} fails.`);
  }
  // With a choice, one step says how either goes.
  if (options.length > 1) {
    options[0].step = 'Either types the update into the terminal below. Press Enter there to run it: the download '
      + `takes seconds, cargo a minute or two. Then ${restart}`;
  }
  if (!options.length) {
    // On Windows the way out of a refusal is the file a release carries.
    const by = os === 'windows'
      ? 'download the release\'s .exe by hand, as docs/windows.md says under Download it.'
      : `bring the clone up to the release (fetch the tags, then git merge --ff-only v${u.latest}) and install it again, as the README says.`;
    if (u.why === 'locked') {
      lines.push('This dbt-edith runs from a build in its clone\'s target folder, which an update would replace '
        + `and a build cannot while it runs: stop it, then bring the clone up to the release (git merge --ff-only v${u.latest}) and build it again.`);
    } else if (u.why === 'shell') {
      lines.push(`The update is typed for sh, bash, zsh and PowerShell, and this terminal runs another shell: ${by}`);
    } else if (u.why === 'release') {
      lines.push(`The release this dbt-edith was told of is not a version number, so no clone is brought up to it: ${by}`);
    } else if (u.why === 'path') {
      lines.push(`A path in the update holds a character a shell would read inside quotes, so none is typed: ${by}`);
    } else if (os === 'windows') {
      lines.push(`There is no command to offer for this dbt-edith: ${by}`);
    } else {
      lines.push('This dbt-edith is neither in cargo\'s bin nor in the target/release of a clone on this machine, '
        + `so there is no command to offer: bring the clone up to the release (fetch the tags, then git merge --ff-only v${u.latest}) and rebuild it where it was built, as the README says.`);
    }
  }
  const first = options[0] || null;
  return {
    label: `${u.latest} available`,
    title: `dbt-edith ${u.latest} is out, and this is ${u.current}`,
    head,
    notes: u.notes || '',
    // The recommended command stands for the offer, as the only one did.
    command: first ? first.command : '',
    button: first ? first.button : undefined,
    step: first ? first.step : '',
    options,
    lines,
  };
}

/* When a look was made or is due, as the menu says it: today, yesterday or
   tomorrow and the time, or the date and the time. `t` and `now` in seconds
   since the epoch, read in the machine's own time zone, so a look the server
   times in Paris reads in local time. Pure, for web/tests/update.js. */
function whenLooked(t, now) {
  const at = new Date(t * 1000);
  const two = (n) => String(n).padStart(2, '0');
  const time = `${two(at.getHours())}:${two(at.getMinutes())}`;
  const midnight = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
  // Rounded, since a day the clocks change on lasts 23 or 25 hours.
  const days = Math.round((midnight(new Date(now * 1000)) - midnight(at)) / 86400000);
  if (days === 0) return `today at ${time}`;
  if (days === 1) return `yesterday at ${time}`;
  if (days === -1) return `tomorrow at ${time}`;
  const month = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][at.getMonth()];
  return `${at.getDate()} ${month} at ${time}`;
}

/* What the menu says of the looks for a newer dbt-edith (0068, 0079): one on
   its way, when the answer came and what it was, what git said when a later
   one got none, and when the next is due, which the server works out from the
   Paris clock. Pure, for web/tests/update.js. */
function updateLook(u, now) {
  if (!u) return '';
  if (u.off) return 'Started with --no-update-check, so no release is looked for.';
  if (u.checking) return 'Looking for a newer release on GitHub…';
  const said = [];
  if (u.failed) said.push(`The look ${whenLooked(u.failed, now)} got no answer from GitHub: ${u.error || 'git said nothing'}.`);
  if (u.checked) {
    const when = whenLooked(u.checked, now);
    if (u.newer) said.push(`GitHub listed ${u.latest} ${when}.`);
    else if (u.latest === u.current) said.push(`${u.current} is the newest release, as GitHub listed it ${when}.`);
    // A build from a branch, or a release not yet tagged when GitHub answered.
    else said.push(`This build is ahead of ${u.latest}, the newest release GitHub listed ${when}.`);
  } else if (!u.failed) {
    said.push('Not looked for yet.');
  }
  if (u.next > now) said.push(`The next look is ${whenLooked(u.next, now)}.`);
  else if (u.next) said.push('The next look is due now.');
  return said.join(' ');
}

/* The releases since the running one, as the menu lists them (0079): a head
   counting them all, one row per release with its pull request's title, and
   a last row for the older ones the server left out. Null without the list,
   when the menu links the newest release's notes alone. Pure, for
   web/tests/update.js. */
function releaseRows(u) {
  if (!u || !u.newer || !(u.releases || []).length) return null;
  const all = u.releases.length + (u.older || 0);
  return {
    head: `${all} release${all === 1 ? '' : 's'} since yours`,
    rows: u.releases.map((r) => ({ version: r.version, title: r.title, href: r.notes, tip: `dbt-edith ${r.version}: ${r.title}` })),
    older: u.older && u.older_notes
      ? { label: `and ${u.older} older`, href: u.older_notes, tip: 'Every release, on GitHub' } : null,
  };
}

/* The cards of the update flow (0111), as data so the harness reads them
   without a DOM. 'typed' is the one after the button types the command, which
   goes by itself. 'installed' is the answer to a transition: the one to
   `replaced`, from an answer that was not (null for the first answer, which
   the pill already covers), and sticky since nothing else says to restart.
   Null when there is nothing to show. */
function updateNotice(kind, prev, next) {
  if (kind === 'typed') {
    // `prev` is the kind of command that was typed.
    return {
      title: 'Press Enter in the terminal to run the update',
      body: `${prev === 'download' ? 'It takes a few seconds.' : 'It takes a minute or two.'} `
        + 'When it ends, stop dbt-edith where you started it and start it again.',
      sticky: false, ms: 15000,
    };
  }
  // The menu's own test of installed, so a card shows exactly when the pill
  // and the menu start to say it: `replaced` alone is true for a binary that
  // is already the newest.
  if (!prev || !prev.current) return null;
  const was = updateOffer(prev), is = updateOffer(next);
  if ((was && was.installed) || !(is && is.installed)) return null;
  return {
    title: 'dbt-edith is installed',
    body: 'Stop dbt-edith in the terminal where you started it (Ctrl+C), then start it again to run the new version.',
    sticky: true,
  };
}

/* Edith's menu, from the name at the top left and from the status bar's pill
   alike: which build serves the page, a newer release and how to install it
   once one is known (0068), the restart left once it is installed (0095), and
   the looks for one, with a button that makes one at once (0079). The name
   opens it under the pointer too (0086). */
function openUpdateMenu(anchor, hover = false) {
  if (closePopup(anchor)) return;
  const menu = document.createElement('div');
  menu.className = 'envmenu updmenu';
  menu.setAttribute('role', 'menu');
  S.updateMenu = menu;
  paintUpdateMenu(menu);
  openPopup(anchor, menu, null, hover);
  freshenUpdate();
}

/* The manifest pill's card, from its badge: what the pill counts, laid out,
   and the button that parses. It opens under the pointer after a rest, a click
   holds it (0086, 0157). Placed against the whole pill, so its right edge meets
   the pill's rather than the badge's. */
function openFreshCard(anchor, hover = false) {
  if (closePopup(anchor)) return;
  if (!S.fresh) return;
  const card = document.createElement('div');
  card.className = 'mcard';
  card.setAttribute('role', 'dialog');
  card.setAttribute('aria-label', 'The manifest');
  card.dataset.align = 'right';
  // A fresh manifest's card has no button to take the focus a click gives it.
  card.tabIndex = -1;
  card.dataset.tone = freshnessBadge(S.fresh).tone;
  S.freshCard = card;
  fillFreshCard(card, S.fresh);
  markFreshCard(card, S.fresh);
  openPopup(anchor, card, () => { S.freshCard = null; anchor.setAttribute('aria-expanded', 'false'); }, hover);
  anchor.setAttribute('aria-expanded', 'true');
  placePopup($('#manifest-pill'), card);
}

/* An update installed by hand since the last answer says so on opening the
   menu or the settings' Updates section, the answer drawn only if it changed
   anything. Not more than twice a minute, since the pointer opens the menu
   too (0086), nor while a look is on its way, whose answer is the newer one. */
function freshenUpdate() {
  const u = S.update;
  if (u && !u.off && !u.checking && !S.lookPosted && Date.now() - S.updateAt > 30 * 1000) refreshUpdate();
}

/* Drawn again in place when an answer comes in while the menu is open. */
function paintUpdateMenu(menu) {
  const el = (tag, className, textContent = '') => Object.assign(document.createElement(tag), { className, textContent });
  const u = S.update || { current: S.version };
  const o = updateOffer(u, S.os);
  const from = 'Edith\'s menu';
  // Drawn anew under the focus, at a click and every two seconds of a look:
  // it goes back to the same row, found by its link since an answer can add
  // rows above it, or to the button, without scrolling the menu to it.
  const rows = () => [...menu.querySelectorAll('[role=menuitem]')];
  const had = menu.contains(document.activeElement) ? document.activeElement : null;
  const same = (r) => (had.getAttribute('href') ? r.getAttribute('href') === had.getAttribute('href') : r.className === had.className);
  menu.replaceChildren(el('div', 'menuhead', o ? o.head : `dbt-edith ${S.version || '?'}`));
  if (S.build) menu.append(el('div', 'menunote', S.build));
  const unsafe = pathWarning(S.pathReadsCwd, S.pathEntry);
  if (unsafe.length) {
    menu.append(document.createElement('hr'));
    unsafe.forEach((parts, i) => {
      const note = el('div', i ? 'menunote' : 'menunote pathwarn');
      for (const part of parts) note.append(part.code === undefined ? part : el('code', '', part.code));
      menu.append(note);
    });
  }
  if (o) {
    menu.append(document.createElement('hr'));
    // What to do comes first, drawn as a button or said as done, with how it
    // goes right under it: a row like the others read as a heading.
    if (o.installed) {
      menu.append(el('div', 'updready', 'Installed: restart dbt-edith to run it'));
    } else {
      // One button per command, the recommended first and drawn as the
      // primary; one step under them says how it goes (0123).
      o.options.forEach((option, i) => {
        const run = el('button', i ? 'updrun alt' : 'updrun', option.button);
        run.type = 'button';
        run.setAttribute('role', 'menuitem');
        run.title = option.command;
        run.addEventListener('click', () => {
          closePopup();
          sendToTerminal(option.command, false, () => notice(updateNotice('typed', option.kind)), from);
          watchInstall();
        });
        menu.append(run);
      });
    }
    if (o.step) menu.append(el('div', 'menunote updstep', o.step));
    const link = (href, className, title) => {
      const a = el('a', className);
      a.setAttribute('role', 'menuitem');
      a.href = href;
      a.target = '_blank';
      a.rel = 'noopener noreferrer';
      if (title) a.title = title;
      // After the click, so the link is still in the page when the browser follows it.
      a.addEventListener('click', () => setTimeout(closePopup));
      return a;
    };
    const listed = releaseRows(u);
    if (listed) {
      menu.append(el('div', 'menuhead', listed.head));
      for (const r of listed.rows) {
        const a = link(r.href, 'menulink relrow', r.tip);
        a.append(el('span', 'ver', r.version), el('span', 'lbl', r.title));
        menu.append(a);
      }
      if (listed.older) {
        const a = link(listed.older.href, 'menulink relrow', listed.older.tip);
        a.append(el('span', 'ver', ''), el('span', 'lbl', listed.older.label), el('span', 'sub', 'GitHub'));
        menu.append(a);
      }
      // The list ends here, and what follows says how the update goes.
      if (o.lines.length) menu.append(document.createElement('hr'));
    } else if (o.notes) {
      const a = link(o.notes, 'menulink');
      a.append(el('span', 'lbl', 'What changed'), el('span', 'sub', 'GitHub'));
      menu.append(a);
    }
    for (const line of o.lines) menu.append(el('div', 'menunote', line));
  }
  menu.append(document.createElement('hr'));
  // What the looks found, beside the button that makes one now.
  const foot = el('div', 'updfoot');
  foot.append(el('div', 'menunote', updateLook(u, Math.floor(Date.now() / 1000))));
  if (!u.off) {
    const look = el('button', 'btn updcheck', u.checking ? 'Looking…' : 'Check for updates');
    look.type = 'button';
    look.setAttribute('role', 'menuitem');
    // Not `disabled`, which takes no focus: the focus goes back to it once
    // the menu is drawn anew.
    if (u.checking) look.setAttribute('aria-disabled', 'true');
    look.addEventListener('click', () => { if (!u.checking) checkForUpdate(); });
    foot.append(look);
  }
  menu.append(foot);
  const back = had && (rows().find(same) || menu.querySelector('.updcheck') || rows().pop());
  if (back) back.focus({ preventScroll: true });
}

/* The menu's button. The server answers once GitHub has, so the menu says it
   is looking until then, and is drawn again with the answer. */
async function checkForUpdate() {
  // The answer before this look, not the copy marked as checking: with none
  // yet, an install the page finds already done is not a transition.
  const before = S.update;
  S.update = Object.assign({}, S.update, { checking: true });
  S.lookPosted = true;
  const asked = ++S.updateAsks;
  paintUpdate();
  try {
    const got = await api.send('/api/update/check', 'POST', {});
    const n = updateNotice('installed', before, got);
    if (n) notice(n);
    S.update = got;
    S.updateShown = asked;
    S.updateAt = Date.now();
  } catch (e) {
    S.update = Object.assign({}, S.update, { checking: false });
    toast('looking for a newer dbt-edith: ' + e.message, 'err');
  } finally {
    S.lookPosted = false;
  }
  paintUpdate();
  // Another look was on its way, whose answer this one waits for.
  if (S.update.checking) refreshUpdate();
}

/* The pill in the status bar, the name at the top left, and the menu if it
   is open, from the last /api/update answer. */
function paintUpdate() {
  const o = updateOffer(S.update);
  const pill = $('#status-update');
  pill.classList.toggle('hidden', !o);
  if (o) {
    pill.textContent = o.label;
    pill.title = o.title;
  }
  // No tooltip on the name: the menu it opens under the pointer says all of
  // it, and a tooltip would land on the menu's first lines. A screen reader
  // still hears what the mark shows.
  const brand = $('#brand');
  // The glyph widens the name by a few pixels, and the fold observer skips the
  // brand's own attribute changes, so the bar is folded again here when it flips.
  const was = brand.classList.contains('newer');
  brand.classList.toggle('newer', !!o);
  if (was !== !!o) foldTopbar();
  brand.setAttribute('aria-description', o ? o.title : `dbt-edith ${S.version || '?'}`);
  if (S.updateMenu && S.updateMenu.isConnected) {
    paintUpdateMenu(S.updateMenu);
    if (popup && popup.el === S.updateMenu) placePopup(popup.anchor, S.updateMenu);
  }
  repaintSettings();
}

/* Asked at boot, then every few seconds while a look is on its way, then
   every ten minutes: the server looks on the hour through the Paris night, and
   the page shows the answer soon after. */
async function refreshUpdate() {
  clearTimeout(S.updatePoll);
  const asked = ++S.updateAsks;
  let got;
  try { got = await api.get('/api/update'); } catch {
    // A request lost to sleep or the network: asked again in a minute.
    S.updatePoll = setTimeout(refreshUpdate, 60 * 1000);
    return;
  }
  // Only an answer asked after the one shown is newer. A Check for updates
  // on its way, or answered since this was asked, knows more: taken, this
  // would put its button back while the look runs, or an older answer back
  // for ten minutes.
  if (!S.lookPosted && asked > S.updateShown) {
    const changed = JSON.stringify(got) !== JSON.stringify(S.update);
    const n = updateNotice('installed', S.update, got);
    if (n) notice(n);
    S.update = got;
    S.updateShown = asked;
    S.updateAt = Date.now();
    if (changed) paintUpdate();
  }
  // Switched off, there will be nothing to hear.
  if (S.update.off) return;
  // Waiting on the update only while there is one to wait on.
  if (!S.update.newer || !(S.update.hows || []).length || S.update.replaced) S.installSince = 0;
  const installing = S.installSince && Date.now() - S.installSince < 30 * 60 * 1000;
  S.updatePoll = setTimeout(refreshUpdate, S.update.checking ? 2000 : installing ? 5000 : 600 * 1000);
}

/* Once the update is typed, asked every few seconds for half an hour, so the
   menu and the pill say to restart soon after cargo puts the new binary in
   place (0095). */
function watchInstall() {
  S.installSince = Date.now();
  clearTimeout(S.updatePoll);
  S.updatePoll = setTimeout(refreshUpdate, 5000);
}

/* Where the GitHub menu's two rows go. An issue starts with the version, the
   build and the system, which a report needs and its writer seldom has to
   hand, and which they can still edit before sending. A star cannot be given
   from a link, so that row opens the repository, at its Star button. Pure, for
   web/tests/github.js.
   The build goes in only in the shape a build of this repository gives it.
   build.rs describes only from a release's tag, at the top of a repository,
   but a build from before it did would name another repository's tag or the
   user's own, and an issue is public. Anything else keeps only its date. */
function githubLinks(repo, version, build, os) {
  const system = { macos: 'macOS', windows: 'Windows', linux: 'Linux' }[os] || os || 'an unknown system';
  const stamp = /^((v\d+\.\d+\.\d+(-\d+-g[0-9a-f]+)?|[0-9a-f]{7,40})(-dirty)?, )?built \d{4}-\d{2}-\d{2}$/.test(build || '')
    ? build : ((build || '').match(/built \d{4}-\d{2}-\d{2}$/) || [''])[0];
  const body = `<!-- What happened, or what would you like? -->\n\n\n\n`
    + `dbt-edith ${version || '?'}${stamp ? ` (${stamp})` : ''} on ${system}`;
  return { issue: `${repo}/issues/new?body=${encodeURIComponent(body)}`, star: repo };
}

/* The GitHub mark in the top bar: anyone using the tool can say what went
   wrong or what is missing, or star it, without looking for the repository. */
function openGithubMenu(anchor) {
  if (closePopup(anchor)) return;
  const el = (tag, className, textContent = '') => Object.assign(document.createElement(tag), { className, textContent });
  const links = githubLinks(S.repo, S.version, S.build, S.os);
  const menu = el('div', 'envmenu ghmenu');
  menu.setAttribute('role', 'menu');
  menu.append(el('div', 'menuhead', 'dbt-edith on GitHub'));
  const row = (href, glyph, label, title) => {
    const a = el('a', 'menulink');
    a.setAttribute('role', 'menuitem');
    a.href = href;
    a.target = '_blank';
    a.rel = 'noopener noreferrer';
    a.title = title;
    const icon = el('span', 'ghglyph');
    icon.innerHTML = glyph;
    a.append(icon, el('span', 'lbl', label));
    // After the click, so the link is still in the page when the browser follows it.
    a.addEventListener('click', () => setTimeout(closePopup));
    menu.append(a);
  };
  const svg = (inner) => `<svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" `
    + `stroke-width="1.4" stroke-linejoin="round" aria-hidden="true">${inner}</svg>`;
  row(links.issue, svg('<circle cx="8" cy="8" r="6.25"/><circle cx="8" cy="8" r="1.3" fill="currentColor" stroke="none"/>'),
    'Raise an issue or a request', 'A new issue on GitHub, your version already in it');
  row(links.star, svg('<path d="M8 1.95L9.62 6.33L14.28 6.51L10.62 9.4L11.88 13.89L8 11.3L4.12 13.89L5.38 9.4L1.72 6.51L6.38 6.33Z"/>'),
    'Give dbt-edith a star', 'The repository on GitHub, whose Star button is at the top right');
  menu.append(el('div', 'menunote', 'Both open GitHub in a new tab; an issue or a star needs a GitHub account.'));
  anchor.setAttribute('aria-expanded', 'true');
  openPopup(anchor, menu, () => anchor.setAttribute('aria-expanded', 'false'));
}

async function boot() {
  initEditor();
  Lineage.init($('#graph'), {
    onSelect: (n) => {
      const { node: nodeId, column } = splitColId(n.id);
      highlightColumn(column, nodeId);
      if (column) S.catTab = 'columns';
      // In the selection's panel the Catalog is the answer, in the card a
      // click opens beside the canvas: a file opened would roll the panel up
      // (0092, 0101).
      if (panelOpen('select')) openSelCard(n.id);
      catalogFor(nodeId).catch(() => {});
      if (panelOpen('select')) return;
      // A column's box opens its model's file too: following a column from
      // model to model is reading each one in turn.
      previewBox(n);
    },
    // A pan or a zoom while a card waits: it opens where the canvas is left.
    onMove: () => { selCardStill = false; },
    onHover: (n, g, said) => {
      const { node: nodeId, column } = splitColId(n.id);
      // The group, as it always was, unless it holds the selected box's web, which would move the card: then
      // the rect. Chosen when the card is placed, which waits a moment, so a click in between is covered.
      const at = { getBoundingClientRect: () => (g.querySelector('.hw-web') ? g.querySelector('rect.box') || g : g).getBoundingClientRect() };
      // In column mode the box already says everything, but for the value a
      // generated column is set to (0096), the expression behind a column
      // (0138) and what keeps its rows (0097), which have no room on it.
      if (column) {
        const rows = (said && said.rows) || '';
        if (Array.isArray(n.generated) || n.expression || (n.partial && n.partial.length) || rows) hoverEnter('col:' + n.id, () => at.getBoundingClientRect(), (el) => fillColumnCard(el, n, rows));
        return;
      }
      hoverEnter('node:' + nodeId, () => at.getBoundingClientRect(), (el) => fillNodeCard(el, nodeId, n));
    },
    onHoverOut: hoverLeave,
    onHoverClose: closeHoverCard,
    // A fold chip redrew the canvas in place: only the line under it changes.
    onRefold: (d, drawn) => { $('#lineage-status').textContent = canvasStatus(d, drawn); },
    onFound: paintGraphFind,
    onOpen: (n) => {
      const { node: nodeId, column } = splitColId(n.id);
      if (column) {
        pinBoxFile(n);
        if (sidecarOn()) {
          return api.get('/api/node?id=' + encodeURIComponent(nodeId))
            .then((detail) => openColumn(detail, column))
            .catch((e) => toast('column lineage: ' + e.message, 'err'));
        }
        return focusColumn(nodeId, column);
      }
      focusNode(nodeId, { keepDepth: true });
      if (n.kind === 'test' && n.test_name) return openTest(n, { pin: true });
      pinBoxFile(n);
    },
    onExpand: (dir, n) => {
      if (S.graphMode === 'select') return expandSelection(dir, n);
      const input = dir === 'up' ? $('#up') : $('#down');
      input.value = Math.min(20, +input.value + 1);
      rerender();
    },
    // Where the folder names can sit, and the middle a found box is brought
    // to: below the bars floating over the top of the canvas, the selector's
    // warnings in that mode (the selector itself is the space's bar) and
    // find's while it is open. Not below the note alone,
    // which the names have always run under.
    headTop: () => {
      const top = $('#lineage-top');
      const bars = [$('#select-bar'), S.graphFind && S.graphFind.bar]
        .filter((b) => b && !b.classList.contains('hidden'));
      return bars.length ? top.offsetTop + Math.max(...bars.map((b) => b.offsetTop + b.offsetHeight)) : 0;
    },
  });
  wireTabs(); wireKeys(); wireSplitters(); relinkTools();
  // The markup says ⌘K, which on the Windows machine this is built for is Ctrl+K.
  const palKey = keyLabel('Mod+K', IS_MAC);
  $$('.k-palette').forEach((k) => { k.textContent = palKey; });
  $('#palette-btn').title = `Search models, macros and files (${palKey})`;
  $('#grep-input').addEventListener('input', runGrep);
  $('#grep-input').addEventListener('keydown', (e) => {
    if (e.key !== 'ArrowDown') return;
    e.preventDefault();
    const first = $('#grep-results .gfile');
    if (first) focusGrepRow(first);
  });
  $('#grep-clear').addEventListener('click', () => {
    $('#grep-input').value = '';
    runGrep();
    $('#grep-input').focus();
  });
  $('#grep-fold').addEventListener('click', foldAllGrep);
  $('#grep-results').addEventListener('keydown', grepKey);
  renderTabs();
  paintMode();
  $('#editor-host').style.display = 'none';

  paintTestsToggle(false);
  $('#settings-btn').addEventListener('click', () => goSpace('settings'));
  wireLook();
  loadLook();
  const info = await api.get('/api/meta');
  applyInfo(info);
  $('#status-shell').textContent = info.shell;
  S.shellName = info.shell_name || '';
  paintTermTools();
  S.pathReadsCwd = (info.path_reads_cwd || {}).why || '';
  S.pathEntry = (info.path_reads_cwd || {}).entry || '';
  // Which build drew this page. A release binary embeds web/ (0005), so this is
  // what tells a stale binary from a frontend change that really did nothing.
  const build = $('#status-build');
  S.version = info.version || '';
  S.build = info.build || '';
  S.repo = info.repo || '';
  S.os = info.os || '';
  build.textContent = 'v' + (info.version || '?');
  build.title = `dbt-edith ${info.version || '?'}\n${info.build || 'no build stamp'}`;
  $('#status-update').addEventListener('click', () => openSettings('updates'));
  $('#brand').addEventListener('click', (e) => openUpdateMenu(e.currentTarget));
  openOnHover($('#brand'), (hover) => openUpdateMenu($('#brand'), hover));
  $('#github-btn').addEventListener('click', (e) => openGithubMenu(e.currentTarget));
  paintUpdate();
  refreshUpdate();
  S.venv = info.venv || {};
  paintVenv();
  $('#status-venv').addEventListener('click', () => openSettings('project'));
  document.title = `${info.meta.project || 'dbt-edith'} · dbt-edith`;
  $('#status-env').addEventListener('click', (e) => openEnvMenu(e.currentTarget));
  loadEnvs();
  await loadDir($('#tree'), '', 0);
  refreshGit();
  refreshFreshness();
  // Each round costs the server a git status and a walk of the model folders,
  // for a page nobody sees while its tab is hidden. It waits there instead, and
  // catches up the moment the tab is shown again.
  const poll = () => {
    paintNight();
    if (document.hidden) return;
    refreshGit(); refreshFreshness(); refreshOpenFiles();
    // The Jobs tab's header says how long ago the files were compared: the words move, nothing is drawn again.
    const age = S.dock === 'jobs' && $('#jobs-head .jobs-age');
    if (age) age.textContent = jobsAgeText();
  };
  setInterval(poll, 5000);
  document.addEventListener('visibilitychange', poll);
  window.addEventListener('resize', () => Lineage.fit());
  offerTour();
}

/* What bash said at its prompt (0069), said again at every prompt. A folder no
   venv read is may be one made since startup, so the server reads the project
   again, once per folder; nothing is sent to it. */
function heardVenv(data) {
  if (data === S.termVenv) return;
  S.termVenv = data;
  paintVenv();
  if (!data || venvMatch(S.venv || {}, data) || S.venvAsked === data) return;
  S.venvAsked = data;
  api.get('/api/venv').then((v) => { S.venv = v; paintVenv(); }).catch(() => {});
}

/* The pill opens the project's settings, where each venv a click can offer
   has the button that types its activate line (0072, 0100). */
function paintVenv() {
  const { text, title, state, offer } = venvStatus(S.venv || {}, S.termVenv);
  const el = $('#status-venv');
  el.textContent = text;
  el.title = title + '\n' + (offer.length
    ? 'click to activate it in the terminal, from the project\'s settings'
    : 'click for the project\'s settings');
  el.dataset.state = state;
  paintTermTools();
  repaintSettings();
}

/* One spelling per folder, to tell whether the venv the terminal names is one
   the server read. On Windows, Git Bash says /c/Users/... where Windows says
   C:\Users\... or C:/Users/..., and case does not count; elsewhere a path is
   compared as it is. */
function venvKey(path, win) {
  if (!win) return String(path).replace(/\/+$/, '');
  let p = String(path).replace(/\\/g, '/').replace(/^\/\/\?\//, '').replace(/\/+$/, '');
  const drive = /^\/(?:cygdrive\/)?([a-zA-Z])(?=\/|$)/.exec(p);
  if (drive) p = drive[1] + ':' + p.slice(drive[0].length);
  return p.toLowerCase();
}

/* The venv the server read that the terminal names, if any: by its folder, or
   by the folder its activate script sets, which is how bash spells it when the
   project root is reached through a mapped drive, a subst or a symlink. The
   server's own paths say whether it runs on Windows. */
function venvMatch(v, reported) {
  const known = [v, ...(v.found || [])].filter((e) => e.path);
  const key = venvKey(reported, venvWin(v));
  return known.find((e) => venvKeys(v, e).includes(key)) || null;
}

/* Whether the server runs on Windows, from its own paths. */
function venvWin(v) {
  return [v, ...(v.found || [])].some((e) => e.path && /^(?:[a-zA-Z]:[\\/]|\\\\)/.test(e.path));
}

/* The spellings `e`, one of the venvs `v` lists, is known by: its folder, and
   the folder its activate script sets. */
function venvKeys(v, e) {
  const win = venvWin(v);
  return [e.path, e.activates].filter(Boolean).map((p) => venvKey(p, win));
}

/* What the status bar says about Python. Until the terminal's shell has said
   anything, that is the venv dbt-edith was started in, else the best one found
   in the project. bash says at each prompt (0069): `reported` is then its
   VIRTUAL_ENV, '' for none, and undefined while nothing has been heard. A venv
   the server did not read, outside the project or tracked by git, is only
   named: its path never goes to the server. `state` colours it: 'on' for an
   active venv, 'off' for one found but not active, 'none' for no venv.
   `offer` is what a click offers to type, and `line` the one it types at
   once, '' when it lists them instead. `name` and `py` are the venv's
   folder name and Python version where known, for the terminal's own chip. The
   tooltip's lines come apart too, for the settings' Python row: `path`, the
   versions read (`python`, `dbt`), the sentence that says the state (`say`) and
   the lines left (`notes`). */
function venvStatus(v, reported) {
  const found = v.found || [];
  const py = (e) => (e.python ? ' · py ' + e.python : '');
  const also = (shown) => {
    const names = found.filter((e) => !shown || e.path !== shown.path).map((e) => e.name);
    return names.length ? 'also found: ' + names.join(', ') : '';
  };
  const lines = (...parts) => [...parts, committedNote(v)].filter(Boolean).join('\n');
  // The tooltip is the path, the dbt versions, the state's sentence, then the notes.
  const whole = (e, path, say, shown) => ({
    path, python: (e && e.python) || '', dbt: (e && e.dbt) || '', say, notes: lines(also(shown)),
    title: lines(path, e && e.dbt && ('dbt: ' + e.dbt), say, also(shown)),
  });
  if (reported) {
    const e = venvMatch(v, reported);
    if (!e) {
      const name = reported.replace(/[\\/]+$/, '').split(/[\\/]/).pop();
      return Object.assign(whole(null, reported, 'activated in the terminal; not a venv dbt-edith read, so its versions are not shown', null),
        { text: 'venv ' + name, name, py: '', state: 'on', offer: [], line: '' });
    }
    return Object.assign(whole(e, e.path, 'activated in the terminal', e),
      { text: 'venv ' + e.name + py(e), name: e.name, py: e.python || '', state: 'on', offer: [], line: '' });
  }
  if (!v.name) {
    const say = reported === ''
      ? 'none activated in the terminal, and none found in the project'
      : 'no VIRTUAL_ENV when dbt-edith started, and none found in the project';
    return Object.assign(whole(null, '', say, null), { text: 'no venv', name: '', py: '', state: 'none', offer: [], line: '', notes: lines(), title: lines(say) });
  }
  const active = reported === undefined && v.source === 'activated';
  const offer = active ? [] : venvOffer(v);
  const say = active ? 'activated when dbt-edith started'
    : reported === '' ? 'not activated in the terminal; source its activate script there'
      : 'found in the project, not activated when dbt-edith started; source its activate script in the terminal';
  return Object.assign(whole(v, v.path, say, v), {
    text: (active ? 'venv ' : 'venv (inactive) ') + v.name + py(v),
    name: v.name, py: v.python || '',
    state: active ? 'on' : 'off',
    // Typed at once only when it is the venv the bar names; any other is picked.
    offer, line: offer.length === 1 && offer[0] === v ? v.activation : '',
  });
}

/* The terminal's own chip says it shorter than the status bar's pill, in
   the words the prompt uses: (name) py 3.11.9, (name) inactive, no venv. */
function termVenvText({ state, name, py }) {
  if (state === 'none') return 'no venv';
  if (state === 'off') return `(${name}) inactive`;
  return py ? `(${name}) py ${py}` : `(${name})`;
}

/* What a click on an inactive venv offers to type: the venv the bar names
   first, then the others found, each with the line the server made for the
   terminal's shell (0072). One with no script for that shell has no line and
   is left out, and a venv git tracks is never found (0053). The venv
   dbt-edith was started in can also be among those found, under the
   project's spelling of its folder, and is offered once. */
function venvOffer(v) {
  const named = venvKeys(v, v);
  const others = (v.found || []).filter((e) => !venvKeys(v, e).some((k) => named.includes(k)));
  return [v, ...others].filter((e) => e.path && e.activation);
}

/* A venv git tracks came with the repository, so whoever wrote the repository
   wrote its python too: the server never runs it, and this says why it is not
   the one shown (0053). When git could not say whether they are committed
   (`unsure`, the pause note), they were set aside for want of an answer, and
   the note says that, with git's reason, instead of claiming they are. */
function committedNote(v) {
  const names = v.committed || [];
  if (!names.length) return '';
  if (v.unsure) return `never run by dbt-edith, as git cannot say here whether they are committed: ${names.join(', ')}\n${v.unsure}`;
  return `committed to the repository, so never run by dbt-edith: ${names.join(', ')}`;
}

// Without the key the bar at the top already says why, once.
boot().catch((e) => { if (!S.keyless) toast('startup failed: ' + e.message, 'err'); });
})();
